CREATE OR REPLACE FUNCTION pgreact.advance_deadline_clock(sampled_time timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    previous_frontier timestamptz;
    next_frontier timestamptz;
    max_keys integer;
    deadline_rule record;
    candidate record;
    rule_keys bigint;
    total_keys bigint := 0;
    changed_rules integer := 0;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M12_CLOCK_UNAUTHORIZED: only pgreact_admin may advance database time';
    END IF;
    IF sampled_time IS NULL OR NOT isfinite(sampled_time) THEN
        RAISE EXCEPTION 'M12_CLOCK_SAMPLE: sampled database time must be finite and non-null';
    END IF;
    IF pg_catalog.pg_is_in_recovery() THEN
        RAISE EXCEPTION 'M12_CLOCK_STANDBY: database time cannot advance on a physical standby';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pgreact_internal.deadline_rules deadline
        JOIN pgreact_internal.rule_versions version USING (rule_version_id)
        WHERE version.state = 'ACTIVE'
          AND NOT EXISTS (
              SELECT 1 FROM pgreact_internal.rule_barriers barrier
              WHERE barrier.rule_version_id = deadline.rule_version_id
                AND barrier.reason = 'REFRESHING'
          )
    ) THEN
        RAISE EXCEPTION 'M12_CLOCK_BARRIER: begin_deadline_refresh must commit before clock advancement';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    SELECT frontier INTO STRICT previous_frontier
    FROM pgreact_internal.clock_frontier
    FOR UPDATE;
    next_frontier := greatest(previous_frontier, sampled_time);
    SELECT max_deadlines_per_pass INTO STRICT max_keys
    FROM pgreact_internal.operational_settings;

    UPDATE pgreact_internal.clock_frontier
    SET frontier = next_frontier,
        last_sampled_time = sampled_time,
        last_advanced_at = clock_timestamp();

    FOR deadline_rule IN
        SELECT deadline.rule_version_id,
               deadline.deadline_column,
               version.match_relid,
               version.key_column
        FROM pgreact_internal.deadline_rules deadline
        JOIN pgreact_internal.rule_versions version USING (rule_version_id)
        WHERE version.state = 'ACTIVE'
        ORDER BY deadline.rule_version_id
    LOOP
        EXECUTE format(
            'SELECT count(*) FROM %s WHERE %I > $1 AND %I <= $2',
            deadline_rule.match_relid::regclass,
            deadline_rule.deadline_column,
            deadline_rule.deadline_column
        ) INTO rule_keys USING previous_frontier, next_frontier;
        total_keys := total_keys + rule_keys;
        IF total_keys > max_keys THEN
            RAISE EXCEPTION 'M12_DEADLINE_LIMIT: clock pass would advance % keys; limit is %',
                total_keys, max_keys;
        END IF;
    END LOOP;

    IF pg_catalog.current_setting('pgreact.test_fail_clock_phase', true) = 'frontier' THEN
        RAISE EXCEPTION 'injected M12 clock failure after frontier update';
    END IF;

    FOR deadline_rule IN
        SELECT deadline.rule_version_id,
               deadline.deadline_column,
               version.match_relid,
               version.key_column
        FROM pgreact_internal.deadline_rules deadline
        JOIN pgreact_internal.rule_versions version USING (rule_version_id)
        WHERE version.state = 'ACTIVE'
        ORDER BY deadline.rule_version_id
    LOOP
        rule_keys := 0;
        FOR candidate IN EXECUTE format(
            'SELECT %I::bigint AS semantic_key FROM %s '
            'WHERE %I > $1 AND %I <= $2 ORDER BY %I, %I',
            deadline_rule.key_column,
            deadline_rule.match_relid::regclass,
            deadline_rule.deadline_column,
            deadline_rule.deadline_column,
            deadline_rule.deadline_column,
            deadline_rule.key_column
        ) USING previous_frontier, next_frontier
        LOOP
            PERFORM pgreact_internal.reconcile_deadline_key(
                deadline_rule.rule_version_id, candidate.semantic_key);
            rule_keys := rule_keys + 1;
        END LOOP;
        IF rule_keys > 0 THEN
            changed_rules := changed_rules + 1;
        END IF;
    END LOOP;

    IF pg_catalog.current_setting('pgreact.test_fail_clock_phase', true) = 'lifecycle' THEN
        RAISE EXCEPTION 'injected M12 clock failure after lifecycle update';
    END IF;

    INSERT INTO pgreact_internal.clock_history (
        sampled_time, previous_frontier, frontier,
        affected_rules, affected_keys
    ) VALUES (
        sampled_time, previous_frontier, next_frontier,
        changed_rules, total_keys
    );
    RETURN jsonb_build_object(
        'sampled_time', sampled_time,
        'previous_frontier', previous_frontier,
        'frontier', next_frontier,
        'affected_rules', changed_rules,
        'affected_keys', total_keys);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.author_decision_program(program_name text, candidate_relation regclass, subject_key_column name, candidate_key_column name, priority_column name, result_columns name[], valid_from timestamp with time zone DEFAULT clock_timestamp(), valid_to timestamp with time zone DEFAULT NULL::timestamp with time zone, max_candidates integer DEFAULT 1000)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE diagnostic record;
    target_program_id uuid;
    version_id uuid := gen_random_uuid();
    next_version integer;
    current_frontier timestamptz;
    result_types jsonb;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_internal.validate_decision_program(
        program_name, candidate_relation, subject_key_column, candidate_key_column,
        priority_column, result_columns, max_candidates)
    WHERE severity = 'ERROR' LIMIT 1;
    IF FOUND THEN RAISE EXCEPTION 'M26_VALIDATION:%: %', diagnostic.code, diagnostic.message; END IF;
    IF valid_from IS NULL OR NOT isfinite(valid_from)
       OR (valid_to IS NOT NULL AND (NOT isfinite(valid_to) OR valid_to <= valid_from)) THEN
        RAISE EXCEPTION 'M26_INTERVAL: decision version interval is empty, inverted, or non-finite';
    END IF;
    SELECT p.program_id INTO target_program_id FROM pgreact_internal.decision_programs p
    WHERE p.program_name = author_decision_program.program_name AND p.state <> 'REMOVED'
    FOR UPDATE;
    IF target_program_id IS NULL THEN
        target_program_id := gen_random_uuid();
        INSERT INTO pgreact_internal.decision_programs(program_id, program_name, owner_oid)
        VALUES (target_program_id, program_name, session_user::regrole::oid);
    ELSIF NOT pg_has_role(session_user,
                          (SELECT owner_oid FROM pgreact_internal.decision_programs p WHERE p.program_id = target_program_id),
                          'USAGE') AND NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M26_CANDIDATE_OWNER: only the decision program owner or operator may replace a program';
    END IF;
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.decision_program_versions v
        WHERE v.program_id = target_program_id AND v.state = 'DEPLOYED'
          AND v.valid_from < COALESCE(author_decision_program.valid_to, 'infinity'::timestamptz)
          AND COALESCE(v.valid_to, 'infinity'::timestamptz) > author_decision_program.valid_from) THEN
        RAISE EXCEPTION 'M26_INTERVAL_OVERLAP: decision version overlaps an existing authoritative interval';
    END IF;
    SELECT COALESCE(max(version_no), 0) + 1 INTO next_version
    FROM pgreact_internal.decision_program_versions v WHERE v.program_id = target_program_id;
    SELECT details -> 'result_types' INTO result_types
    FROM pgreact_internal.validate_decision_program(
        program_name, candidate_relation, subject_key_column, candidate_key_column,
        priority_column, result_columns, max_candidates)
    WHERE code = 'OK' LIMIT 1;
    INSERT INTO pgreact_internal.decision_program_versions(
        version_id, program_id, version_no, candidate_relation_oid, candidate_relation_name,
        subject_key_column, candidate_key_column, priority_column, result_columns, result_types,
        source_signature, source_definition_digest, max_candidates, valid_from, valid_to, deployed_by)
    VALUES (version_id, target_program_id, next_version,
            candidate_relation, candidate_relation::text, subject_key_column, candidate_key_column,
            priority_column, result_columns, COALESCE(result_types, '[]'::jsonb),
            pgreact_internal.source_row_signature(candidate_relation),
            pgreact_internal.decision_source_digest(candidate_relation), max_candidates,
            valid_from, valid_to, session_user::regrole::oid);
    SELECT frontier INTO current_frontier FROM pgreact_internal.clock_frontier;
    IF current_frontier >= valid_from
       AND (valid_to IS NULL OR current_frontier < valid_to) THEN
        PERFORM pgreact_internal.refresh_decision_program(target_program_id, current_frontier);
    END IF;
    RETURN version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.author_immediate_rule(rule_name text, condition regclass, semantic_key name)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE target_version uuid;
    diagnostic record;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_immediate_rule(condition, semantic_key) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M19_IMMEDIATE_INVALID: % for %: %', diagnostic.code,
            diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    target_version := pgreact_api.author_rule(
        rule_name => rule_name, condition => condition,
        semantic_key => semantic_key, kind => 'CONSTRAINT');
    PERFORM pgreact_internal.enable_immediate_rule(target_version);
    RETURN target_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.author_rule(definition jsonb, mappings jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE digest text;
BEGIN
  SELECT min(plan_digest) INTO digest FROM pgreact.preview_pack(definition, mappings);
  IF digest IS NULL THEN RAISE EXCEPTION 'M11_PACK_EMPTY: preview produced no deployable plan'; END IF;
  RETURN pgreact.deploy_pack(definition, digest, mappings);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.author_temporal_rule(rule_name text, condition regclass, semantic_key name, primitive text, duration interval DEFAULT NULL::interval, deadline_column name DEFAULT NULL::name, cooldown interval DEFAULT NULL::interval, recovery_condition regclass DEFAULT NULL::regclass, recovery_key_column name DEFAULT NULL::name, on_activate regprocedure DEFAULT NULL::regprocedure, salience integer DEFAULT 0, agenda_group text DEFAULT 'default'::text, max_attempts integer DEFAULT 1, initial_backoff_seconds integer DEFAULT 1, backoff_multiplier numeric DEFAULT 2, max_backoff_seconds integer DEFAULT 60)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE diagnostic record; version_id uuid; version_row pgreact_internal.rule_versions%ROWTYPE;
    duration_us bigint; cooldown_us bigint;
BEGIN
    SELECT result.* INTO diagnostic
    FROM pgreact_internal.validate_temporal_rule(
        condition, semantic_key, primitive, duration, deadline_column,
        cooldown, recovery_condition, recovery_key_column) result
    WHERE result.severity = 'ERROR' ORDER BY result.code LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react temporal validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    IF primitive = 'DURATION' THEN duration_us := pgreact_internal.temporal_duration_us(duration); END IF;
    IF primitive = 'COOLDOWN' THEN cooldown_us := pgreact_internal.temporal_duration_us(cooldown); END IF;
    version_id := pgreact.create_rule(
        name => rule_name, definition => condition,
        key_columns => ARRAY[semantic_key]::name[], kind => 'CONSTRAINT',
        on_activate => NULL::regprocedure, on_deactivate => NULL::regprocedure,
        on_change => NULL::regprocedure, bootstrap_policy => 'SEED_CURRENT',
        change_columns => NULL::name[], salience => salience,
        agenda_group => agenda_group, conflict_key_columns => NULL::name[],
        max_attempts => max_attempts, initial_backoff_seconds => initial_backoff_seconds,
        backoff_multiplier => backoff_multiplier, max_backoff_seconds => max_backoff_seconds);
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions
    WHERE rule_version_id = version_id;
    IF on_activate IS NOT NULL THEN
        PERFORM pgreact_internal.add_typed_binding(
            version_id, 'ACTIVATE', on_activate, max_attempts,
            initial_backoff_seconds, backoff_multiplier, max_backoff_seconds);
    END IF;
    INSERT INTO pgreact_internal.temporal_rules (
        rule_version_id, primitive, duration_us, deadline_column, cooldown_us,
        recovery_condition_oid, recovery_condition_name, recovery_key_column)
    VALUES (
        version_id, primitive, duration_us, deadline_column, cooldown_us,
        recovery_condition, recovery_condition::text, recovery_key_column);
    EXECUTE format('DROP TRIGGER IF EXISTS pgreact_finalize ON %s', version_row.match_relid::regclass);
    DELETE FROM pgreact_internal.agenda WHERE rule_version_id = version_id;
    DELETE FROM pgreact_internal.lifecycle_events WHERE rule_version_id = version_id;
    DELETE FROM pgreact_internal.activation_state WHERE rule_version_id = version_id;
    EXECUTE format(
        'CREATE CONSTRAINT TRIGGER pgreact_temporal_finalize '
        'AFTER INSERT OR UPDATE OR DELETE ON %s DEFERRABLE INITIALLY DEFERRED '
        'FOR EACH ROW EXECUTE FUNCTION pgreact_internal.finalize_temporal_match_delta(%L)',
        version_row.match_relid::regclass, version_id::text);
    PERFORM pgreact_internal.reconcile_temporal_rule(version_id);
    RETURN version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.capture_evidence_snapshot(target pgreact_api.target, subject jsonb, root jsonb, capture_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE subject_key bigint;
    result_key bigint;
    root_identity text;
    computed_identity text;
    existing pgreact_internal.evidence_snapshots%ROWTYPE;
    tombstone record;
    declaration_row pgreact_internal.api_declarations%ROWTYPE;
    answer jsonb;
    policy jsonb;
    policy_findings jsonb;
    declaration_digest text;
    policy_digest text;
    captured_at timestamptz := clock_timestamp();
    deletion_eligible_at timestamptz;
    payload_bytes bigint;
    source_reads bigint;
BEGIN
    IF target IS NULL OR (target).kind IS DISTINCT FROM 'decision_program'
       OR (target).name IS NULL OR (target).version IS NULL
       OR (target).version !~ '^[1-9][0-9]*$'
       OR jsonb_typeof(root) IS DISTINCT FROM 'object'
       OR root ->> 'root_kind' IS DISTINCT FROM 'decision_result'
       OR root ->> 'result_key' !~ '^-?[0-9]+$'
       OR (SELECT count(*) FROM jsonb_object_keys(root)) <> 2 THEN
        RETURN pgreact_internal.m42_result('capture', 'unsupported', NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_ROOT_INVALID', 'ERROR', 'root',
                'capture accepts one decision_result root and a numeric version',
                'Pass target kind decision_program, its version, and {root_kind, result_key}.')));
    END IF;
    IF capture_key IS NULL OR capture_key !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$' THEN
        RETURN pgreact_internal.m42_result('capture', 'unsupported', NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_CAPTURE_KEY_INVALID', 'ERROR', 'capture_key',
                'capture_key must be 1 to 128 safe characters',
                'Use letters, digits, dot, underscore, colon, or hyphen.')));
    END IF;
    subject_key := pgreact_internal.m40_subject_key(subject);
    IF subject_key IS NULL THEN
        RETURN pgreact_internal.m42_result('capture', 'unsupported', NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_ROOT_INVALID', 'ERROR', 'subject',
                'subject must contain one bigint business key',
                'Pass a JSON number or {"key": number}.')));
    END IF;
    result_key := (root ->> 'result_key')::bigint;
    root_identity := format('decision_result:%s@%s:subject=%s:candidate=%s',
        (target).name, (target).version, subject_key, result_key);
    computed_identity := pgreact_internal.m42_identity(
        (target).kind, (target).name, (target).version, root_identity, capture_key);

    SELECT * INTO existing
    FROM pgreact_internal.evidence_snapshots
    WHERE evidence_snapshots.snapshot_identity = computed_identity
    FOR UPDATE;
    IF FOUND THEN
        IF NOT pg_has_role(session_user, existing.owner_oid, 'USAGE')
           AND NOT pgreact_internal.is_operator_admin() THEN
            RETURN pgreact_internal.m42_result('capture', 'unavailable', NULL, NULL, '{}',
                jsonb_build_array(pgreact_internal.m42_finding(
                    'M42_TARGET_UNAUTHORIZED', 'WARNING', NULL,
                    'the retained evidence is not available to this caller',
                    'Use the declaration owner or configured operator role.')));
        END IF;
        RETURN pgreact_internal.m42_result(
            'capture', CASE WHEN existing.deletion_eligible_at <= clock_timestamp()
                            THEN 'deletion_eligible' ELSE 'available' END,
            existing.snapshot_identity, existing.m41_answer,
            pgreact_internal.m42_snapshot_metadata(existing),
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_CAPTURE_DUPLICATE', 'INFO', 'capture_key',
                'the capture identity already exists; the retained answer was returned',
                'Reuse the same identity to retry safely.')));
    END IF;
    IF EXISTS (SELECT 1 FROM pgreact_internal.retention_tombstones
               WHERE family = 'evidence_snapshots'
                 AND historical_identity = computed_identity) THEN
        RETURN pgreact_internal.m42_result('capture', 'deleted', NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_SNAPSHOT_DELETED', 'INFO', NULL,
                'this capture identity was deleted and cannot be recreated',
                'Use a new capture_key for a new historical record.')));
    END IF;

    SELECT * INTO declaration_row
    FROM pgreact_internal.api_declarations
    WHERE kind = 'decision_program' AND object_name = (target).name AND state = 'DEPLOYED';
    IF NOT FOUND THEN
        RETURN pgreact_internal.m42_result('capture', 'unavailable', NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_TARGET_NOT_FOUND', 'WARNING', 'target',
                'no deployed canonical decision program has this name',
                'Deploy a decision_program declaration before capturing evidence.')));
    END IF;
    IF NOT pg_has_role(session_user, declaration_row.owner_oid, 'USAGE')
       AND NOT pgreact_internal.is_operator_admin() THEN
        RETURN pgreact_internal.m42_result('capture', 'unavailable', NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_TARGET_UNAUTHORIZED', 'WARNING', NULL,
                'the decision program is not available to this caller',
                'Use the declaration owner or configured operator role.')));
    END IF;
    policy := declaration_row.normalized -> 'spec' -> 'evidence_snapshot';
    IF policy IS NULL THEN
        RETURN pgreact_internal.m42_result('capture', 'unavailable', NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_POLICY_MISSING', 'WARNING', 'spec.evidence_snapshot',
                'evidence snapshots are disabled because the declaration did not opt in',
                'Deploy the decision program with a finite evidence_snapshot retention_seconds policy.')));
    END IF;
    policy_findings := pgreact_internal.m42_policy_findings(policy, (target).name);
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(policy_findings) f WHERE f ->> 'severity' = 'ERROR') THEN
        RETURN pgreact_internal.m42_result('capture', 'unsupported', NULL, NULL, '{}', policy_findings);
    END IF;
    IF COALESCE((policy ->> 'enabled')::boolean, true) = false THEN
        RETURN pgreact_internal.m42_result('capture', 'unavailable', NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_POLICY_DISABLED', 'WARNING', 'spec.evidence_snapshot.enabled',
                'evidence snapshots are disabled by this declaration',
                'Set enabled to true or omit it.')));
    END IF;

    answer := pgreact_internal.m41_explain(
        (target).name, subject, jsonb_build_object('causal_path', root));
    IF answer ->> 'state' <> 'complete' THEN
        RETURN pgreact_internal.m42_result('capture',
            CASE WHEN answer ->> 'state' = 'partial' THEN 'partial' ELSE 'unavailable' END,
            NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_ROOT_INCOMPLETE', 'WARNING', 'root',
                'only a complete current M41 causal path can be retained',
                'Resolve the M41 finding and retry while the evidence is current.',
                jsonb_build_object('m41_state', answer ->> 'state'))));
    END IF;
    IF answer -> 'target' ->> 'version' IS DISTINCT FROM (target).version
       OR answer -> 'root' ->> 'identity' IS DISTINCT FROM root_identity THEN
        RETURN pgreact_internal.m42_result('capture', 'unavailable', NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_VERSION_STALE', 'WARNING', 'target.version',
                'the requested M41 path does not match the requested public version',
                'Retry with the version and root identity returned by M41.')));
    END IF;
    declaration_digest := encode(declaration_row.declaration_digest, 'hex');
    policy_digest := encode(sha256(convert_to(policy::text, 'UTF8')), 'hex');
    captured_at := clock_timestamp();
    deletion_eligible_at := captured_at +
        interval '1 second' * (policy ->> 'retention_seconds')::bigint;
    payload_bytes := pg_column_size(answer);
    source_reads := COALESCE((answer -> 'cost' ->> 'boundary_checks')::bigint, 0);
    INSERT INTO pgreact_internal.evidence_snapshots(
        snapshot_identity, target_kind, target_name, target_version, root_identity,
        capture_key, subject, owner_oid, declaration_digest, policy_digest, m41_answer,
        sampled_time, captured_at, deletion_eligible_at, payload_bytes,
        source_evidence_read, storage_writes)
    VALUES (computed_identity, (target).kind, (target).name, (target).version, root_identity,
            capture_key, subject, declaration_row.owner_oid, declaration_digest, policy_digest,
            answer, (answer ->> 'sampled_time')::timestamptz, captured_at,
            deletion_eligible_at, payload_bytes, source_reads, 1)
    ON CONFLICT (snapshot_identity) DO NOTHING;
    SELECT * INTO existing
    FROM pgreact_internal.evidence_snapshots
    WHERE evidence_snapshots.snapshot_identity = computed_identity;
    IF existing.snapshot_identity IS DISTINCT FROM computed_identity THEN
        RETURN pgreact_internal.m42_result('capture', 'unavailable', NULL, NULL, '{}',
            jsonb_build_array(pgreact_internal.m42_finding(
                'M42_STORAGE_FAILURE', 'ERROR', NULL,
                'the retained evidence could not be read after capture',
                'Retry the capture after resolving storage pressure.')));
    END IF;
    INSERT INTO pgreact_internal.evidence_snapshot_audits(
        snapshot_identity, operation, outcome, actor_oid, owner_oid, details)
    VALUES (computed_identity, 'capture', 'captured', session_user::regrole::oid,
            existing.owner_oid, jsonb_build_object('payload_bytes', payload_bytes))
    ON CONFLICT (snapshot_identity, operation) DO NOTHING;
    RETURN pgreact_internal.m42_result('capture', 'available', computed_identity,
        existing.m41_answer, pgreact_internal.m42_snapshot_metadata(existing), '[]');
EXCEPTION WHEN OTHERS THEN
    RETURN pgreact_internal.m42_result('capture', 'unavailable', NULL, NULL, '{}',
        jsonb_build_array(pgreact_internal.m42_finding(
            'M42_STORAGE_FAILURE', 'ERROR', NULL,
            'the evidence snapshot was not retained',
            'Retry after resolving the reported PostgreSQL storage error.',
            jsonb_build_object('sqlstate', SQLSTATE))));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.configure_roles(author_role regrole, operator_role regrole, worker_role regrole, reader_role regrole, advanced_reader_role regrole)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    caller_oid oid := (SELECT oid FROM pg_roles WHERE rolname = session_user);
    extension_owner oid;
    old_roles oid[];
BEGIN
    SELECT extowner INTO STRICT extension_owner FROM pg_extension WHERE extname = 'pg_react';
    IF caller_oid <> extension_owner
       AND NOT COALESCE((SELECT rolsuper FROM pg_roles WHERE oid = caller_oid), false)
       AND NOT (to_regrole('pgreact_admin') IS NOT NULL
                AND pg_has_role(session_user, 'pgreact_admin', 'member')) THEN
        RAISE EXCEPTION 'M13_ROLE_ADMIN: only the extension owner or pgreact_admin may configure roles';
    END IF;
    IF cardinality(ARRAY[author_role::oid, operator_role::oid, worker_role::oid, reader_role::oid])
       <> (SELECT count(DISTINCT role_oid) FROM unnest(ARRAY[
           author_role::oid, operator_role::oid, worker_role::oid, reader_role::oid]) role_oid) THEN
        RAISE EXCEPTION 'M13_ROLE_DISTINCT: author, operator, worker, and reader roles must be distinct';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('pgreact:configure_roles', 5788046901200000));
    SELECT COALESCE(array_agg(role_oid ORDER BY role_kind), ARRAY[]::oid[])
    INTO old_roles FROM pgreact_internal.application_roles;
    DELETE FROM pgreact_internal.application_roles;
    PERFORM pgreact_api.configure_roles_m53(
        author_role, operator_role, worker_role, reader_role, advanced_reader_role);
    PERFORM pgreact_internal.m54_sync_grants(old_roles);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.decision_preview(target_program_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE program_row record;
    version_row record;
    subject_row record;
    candidate_row record;
    subjects jsonb := '[]'::jsonb;
    candidates jsonb;
    candidate_result jsonb;
    top_priority bigint;
    top_count bigint;
    candidate_count bigint;
    preview_state text;
BEGIN
    SELECT * INTO program_row FROM pgreact_internal.decision_programs
    WHERE program_name = target_program_name AND state <> 'REMOVED';
    IF NOT FOUND THEN RETURN jsonb_build_object('contract_version', 14, 'available', false,
                                                'program', target_program_name); END IF;
    SELECT * INTO version_row FROM pgreact_internal.decision_program_versions
    WHERE program_id = program_row.program_id AND state = 'DEPLOYED'
    ORDER BY valid_from DESC, version_no DESC LIMIT 1;
    IF NOT FOUND THEN RETURN jsonb_build_object('contract_version', 14, 'available', false,
                                                'program', target_program_name); END IF;
    PERFORM pgreact_internal.load_decision_candidates(version_row.version_id);
    FOR subject_row IN SELECT DISTINCT subject_key FROM pg_temp.m26_decision_candidates ORDER BY subject_key LOOP
        candidates := '[]'::jsonb;
        FOR candidate_row IN SELECT candidate_key, priority, row_data
            FROM pg_temp.m26_decision_candidates WHERE subject_key = subject_row.subject_key
            ORDER BY priority, candidate_key LIMIT 25 LOOP
            candidate_result := pgreact_internal.decision_result(candidate_row.row_data, version_row.result_columns);
            candidates := candidates || jsonb_build_array(jsonb_build_object(
                'candidate', candidate_row.candidate_key, 'priority', candidate_row.priority,
                'result', candidate_result));
        END LOOP;
        SELECT min(priority), count(*) FILTER (WHERE priority = (SELECT min(c.priority)
               FROM pg_temp.m26_decision_candidates c WHERE c.subject_key = subject_row.subject_key))
        INTO top_priority, top_count FROM pg_temp.m26_decision_candidates c
        WHERE c.subject_key = subject_row.subject_key;
        SELECT count(*) INTO candidate_count FROM pg_temp.m26_decision_candidates c
        WHERE c.subject_key = subject_row.subject_key;
        preview_state := CASE WHEN top_count > 1 THEN 'AMBIGUOUS' ELSE 'WINNER' END;
        subjects := subjects || jsonb_build_array(jsonb_build_object(
            'subject', subject_row.subject_key, 'state', preview_state,
            'top_priority', top_priority, 'candidates', candidates,
            'truncated', candidate_count > 25));
    END LOOP;
    RETURN jsonb_build_object('contract_version', 14, 'available', true,
        'program', target_program_name, 'version_id', version_row.version_id,
        'side_effect_free', true, 'subjects', subjects,
        'competitor_limit', 25);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.declare_derived_relation(relation_name text, row_type regtype, semantic_keys name[], relation_version integer DEFAULT 1)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    identity_parts text[] := parse_ident(relation_name, true);
    public_schema name;
    public_relation name;
    type_relation oid;
    type_owner oid;
    attribute record;
    key_column name;
    key_types regtype[] := ARRAY[]::regtype[];
    key_collations regcollation[] := ARRAY[]::regcollation[];
    attribute_definitions text[] := ARRAY[]::text[];
    public_columns text[] := ARRAY[]::text[];
    internal_suffix text := md5(relation_name || ':' || relation_version::text);
    internal_type_name name;
    internal_relation_name name;
    internal_type regtype;
    created_version uuid;
BEGIN
    IF cardinality(identity_parts) <> 2 THEN
        RAISE EXCEPTION 'M15_RELATION_NAME: derived relation names must be schema-qualified';
    END IF;
    public_schema := identity_parts[1];
    public_relation := identity_parts[2];
    IF NOT has_schema_privilege(session_user, public_schema, 'CREATE') THEN
        RAISE EXCEPTION 'M15_RELATION_SCHEMA: % cannot create in schema %', session_user, public_schema;
    END IF;
    SELECT type.typrelid, type.typowner INTO STRICT type_relation, type_owner
    FROM pg_type type WHERE type.oid = row_type;
    IF type_relation = 0 OR type_owner <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RAISE EXCEPTION 'M15_RELATION_TYPE: the author must own composite row type %', row_type;
    END IF;
    IF cardinality(semantic_keys) NOT BETWEEN 1 AND 4
       OR array_position(semantic_keys, NULL) IS NOT NULL
       OR (SELECT count(DISTINCT key) FROM unnest(semantic_keys) key)
          <> cardinality(semantic_keys) THEN
        RAISE EXCEPTION 'M15_KEY_ARITY: semantic keys require one to four distinct named attributes';
    END IF;
    FOR attribute IN
        SELECT value.attname, value.atttypid, value.atttypmod, value.attcollation,
               attribute_collation.collname, attribute_collation.collisdeterministic
        FROM pg_attribute value
        LEFT JOIN pg_collation attribute_collation
          ON attribute_collation.oid = value.attcollation
        WHERE value.attrelid = type_relation AND value.attnum > 0 AND NOT value.attisdropped
        ORDER BY value.attnum
    LOOP
        attribute_definitions := attribute_definitions || format(
            '%I %s%s', attribute.attname,
            format_type(attribute.atttypid, attribute.atttypmod),
            CASE WHEN attribute.attcollation = 0 THEN ''
                 ELSE format(' COLLATE %I', attribute.collname) END);
        public_columns := public_columns || format('%I', attribute.attname);
    END LOOP;
    FOREACH key_column IN ARRAY semantic_keys LOOP
        SELECT value.atttypid::regtype, value.attcollation::regcollation,
               key_collation.collname, key_collation.collisdeterministic,
               current_database_row.datcollate
        INTO STRICT attribute
        FROM pg_attribute value
        LEFT JOIN pg_collation key_collation ON key_collation.oid = value.attcollation
        CROSS JOIN pg_database current_database_row
        WHERE value.attrelid = type_relation AND value.attname = key_column
          AND value.attnum > 0 AND NOT value.attisdropped
          AND current_database_row.datname = current_database();
        IF attribute.atttypid NOT IN ('bigint'::regtype, 'uuid'::regtype, 'text'::regtype) THEN
            RAISE EXCEPTION 'M15_KEY_TYPE: %.% has unsupported type %',
                row_type, key_column, attribute.atttypid;
        END IF;
        IF attribute.atttypid = 'text'::regtype
           AND (NOT attribute.collisdeterministic
                OR (attribute.collname <> 'C'
                    AND NOT (attribute.collname = 'default'
                             AND attribute.datcollate IN ('C', 'C.UTF-8', 'C.utf8')))) THEN
            RAISE EXCEPTION 'M15_KEY_COLLATION: %.% requires deterministic C collation',
                row_type, key_column;
        END IF;
        key_types := key_types || attribute.atttypid;
        key_collations := key_collations || attribute.attcollation;
    END LOOP;
    internal_type_name := ('m15_type_' || internal_suffix)::name;
    internal_relation_name := ('m15_relation_' || internal_suffix)::name;
    EXECUTE format(
        'CREATE TYPE pgreact_runtime.%I AS (%s, __pgreact_canonical bytea, '
        '__pgreact_key bigint, __pgreact_public_key jsonb)',
        internal_type_name, array_to_string(attribute_definitions, ', '));
    EXECUTE format('ALTER TYPE pgreact_runtime.%I OWNER TO %I',
                   internal_type_name, session_user);
    EXECUTE format('GRANT USAGE ON SCHEMA pgreact_runtime TO %I', session_user);
    internal_type := format('pgreact_runtime.%I', internal_type_name)::regtype;
    EXECUTE format('GRANT CREATE ON SCHEMA pgreact_runtime TO %I', session_user);
    created_version := pgreact.create_derived_relation(
        format('pgreact_runtime.%I', internal_relation_name), internal_type,
        ARRAY['__pgreact_key'::name], relation_version);
    EXECUTE format('REVOKE CREATE ON SCHEMA pgreact_runtime FROM %I', session_user);
    EXECUTE format(
        'CREATE VIEW %I.%I AS SELECT %s FROM pgreact_runtime.%I',
        public_schema, public_relation, array_to_string(public_columns, ', '),
        internal_relation_name);
    EXECUTE format('GRANT SELECT ON %I.%I TO %I WITH GRANT OPTION',
                   public_schema, public_relation, session_user);
    INSERT INTO pgreact_internal.keyed_derived_relations VALUES (
        created_version, format('%I.%I', public_schema, public_relation),
        format('pgreact_runtime.%I', internal_relation_name), row_type, internal_type,
        semantic_keys, key_types, key_collations);
    RETURN created_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.deploy_decision_program(program_name text, version_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE target_program uuid;
    owner_oid oid;
BEGIN
    SELECT p.program_id, p.owner_oid INTO target_program, owner_oid
    FROM pgreact_internal.decision_programs p
    JOIN pgreact_internal.decision_program_versions v USING (program_id)
    WHERE p.program_name = deploy_decision_program.program_name
      AND v.version_id = deploy_decision_program.version_id AND p.state <> 'REMOVED';
    IF NOT FOUND THEN RAISE EXCEPTION 'M26_VERSION: decision program version was not found'; END IF;
    IF NOT pg_has_role(session_user, owner_oid, 'USAGE')
       AND NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M26_CANDIDATE_OWNER: only the decision program owner or operator may deploy a version';
    END IF;
    PERFORM pgreact_internal.assert_decision_admission(version_id);
    UPDATE pgreact_internal.decision_program_versions SET state = 'DEPLOYED'
    WHERE decision_program_versions.version_id = deploy_decision_program.version_id;
    RETURN deploy_decision_program.version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.deploy_immediate_program(definition jsonb, expected_plan_digest text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE diagnostic record;
    target_program uuid;
    member record;
    program_name text := definition ->> 'name';
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_immediate_program(definition) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M19_PROGRAM_INVALID: % for %: %', diagnostic.code,
            diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(program_name, 5788046901200003));
    target_program := pgreact_api.deploy_program(definition, expected_plan_digest);
    UPDATE pgreact_internal.derivation_program_versions
    SET maintenance_mode = 'IMMEDIATE'
    WHERE program_version_id = target_program;
    -- Convert the whole closure before re-enabling its triggers; otherwise a
    -- downstream full refresh can observe an upstream mode transition.
    PERFORM set_config('session_replication_role', 'replica', true);
    FOR member IN
        SELECT version.rule_version_id, version.match_name
        FROM pgreact_internal.derivation_program_rules program_rule
        JOIN pgreact_internal.rule_versions version
          ON version.rule_version_id = program_rule.rule_version_id
        WHERE program_rule.program_version_id = target_program
        ORDER BY program_rule.rule_order DESC
    LOOP
        IF NOT EXISTS (
            SELECT 1
            FROM pgreact_internal.derivation_program_inputs input
            WHERE input.program_version_id = target_program
              AND input.rule_version_id = member.rule_version_id
        ) THEN
            PERFORM pgreact_internal.enable_immediate_rule(member.rule_version_id);
        ELSE
            -- ponytail: pg_trickle 0.81 cannot nest IMMEDIATE stream refreshes;
            -- roots stay native, downstream members use ordered closure refresh.
            PERFORM pgreact_internal.mark_immediate_rule(member.rule_version_id);
        END IF;
    END LOOP;
    PERFORM set_config('session_replication_role', 'origin', true);
    INSERT INTO pgreact_internal.immediate_audits(object_identity, operation, details)
    VALUES (program_name, 'ENABLE_PROGRAM',
            jsonb_build_object('program_version_id', target_program,
                               'closure', 'finite acyclic positive',
                               'lock', 'program advisory xact lock'));
    RETURN target_program;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.deploy_m28(declaration pgreact_api.declaration, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE validation jsonb;
    normalized jsonb;
    findings jsonb;
    current_row pgreact_internal.api_declarations%ROWTYPE;
    delegated_id uuid;
    owner_id oid;
    current_found boolean;
    expected_digest text;
    allow_create boolean := true;
    condition_oid regclass;
    candidate_oid regclass;
    result_columns name[];
BEGIN
    IF preconditions IS NULL OR jsonb_typeof(preconditions) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M28_PRECONDITIONS: preconditions must be a JSON object';
    END IF;
    SELECT value, value -> 'normalized', value -> 'findings'
      INTO validation, normalized, findings
    FROM (SELECT pgreact_internal.m28_validate(declaration) AS value) checked;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(findings) finding WHERE finding ->> 'severity' = 'ERROR') THEN
        RAISE EXCEPTION 'M28_VALIDATION: %', findings;
    END IF;
    IF jsonb_typeof(preconditions -> 'allow_create') IS NOT NULL
       AND jsonb_typeof(preconditions -> 'allow_create') IS DISTINCT FROM 'boolean' THEN
        RAISE EXCEPTION 'M28_PRECONDITION_FIELD: allow_create must be boolean';
    END IF;
    allow_create := COALESCE((preconditions ->> 'allow_create')::boolean, true);
    expected_digest := preconditions ->> 'preview_digest';
    IF expected_digest IS NOT NULL
       AND expected_digest <> pgreact_internal.m28_digest(normalized) THEN
        RAISE EXCEPTION 'M28_PREVIEW_STALE'
            USING HINT = 'Preview the declaration again after changing its fields or source relations.';
    END IF;
    SELECT * INTO current_row
    FROM pgreact_internal.api_declarations
    WHERE kind = (declaration).kind AND object_name = (declaration).name
    FOR UPDATE;
    current_found := FOUND;
    SELECT oid INTO owner_id FROM pg_roles WHERE rolname = session_user;
    IF current_found AND current_row.owner_oid <> owner_id
       AND NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M28_OWNER: only the declaration owner or operator may deploy this target';
    END IF;
    IF current_found AND current_row.state = 'DEPLOYED' AND allow_create THEN
        RAISE EXCEPTION 'M28_EXISTS: target already exists'
            USING HINT = 'Pass allow_create=false and the current preview digest for an intentional replacement.';
    END IF;
    IF current_found AND current_row.state = 'DEPLOYED' AND NOT allow_create
       AND preconditions ->> 'expected_current_digest' IS DISTINCT FROM encode(current_row.declaration_digest, 'hex') THEN
        RAISE EXCEPTION 'M28_REPLACE_STALE'
            USING HINT = 'Preview the current target and use its exact digest as expected_current_digest.';
    END IF;

    IF (declaration).kind = 'rule' AND COALESCE((declaration).spec ->> 'delegate', 'true') = 'true' THEN
        condition_oid := to_regclass((declaration).spec ->> 'condition');
        SELECT pgreact_api.author_rule(
            (declaration).name, condition_oid, ((declaration).spec ->> 'semantic_key')::name,
            COALESCE((declaration).spec ->> 'kind', 'CONSTRAINT'),
            (declaration).spec ->> 'on_activate', (declaration).spec ->> 'on_deactivate',
            (declaration).spec ->> 'on_change', COALESCE((declaration).spec ->> 'bootstrap_policy', 'SEED_CURRENT'),
            NULL::name[], COALESCE(((declaration).spec ->> 'salience')::integer, 0),
            COALESCE((declaration).spec ->> 'agenda_group', 'default'), NULL::name[],
            COALESCE(((declaration).spec ->> 'max_attempts')::integer, 1),
            COALESCE(((declaration).spec ->> 'initial_backoff_seconds')::integer, 1),
            COALESCE(((declaration).spec ->> 'backoff_multiplier')::numeric, 2),
            COALESCE(((declaration).spec ->> 'max_backoff_seconds')::integer, 60))
        INTO delegated_id;
    ELSIF (declaration).kind = 'decision_program'
          AND COALESCE((declaration).spec ->> 'delegate', 'true') = 'true' THEN
        candidate_oid := to_regclass((declaration).spec ->> 'candidate_relation');
        SELECT ARRAY(SELECT jsonb_array_elements_text((declaration).spec -> 'results'))::name[] INTO result_columns;
        SELECT pgreact_api.author_decision_program(
            (declaration).name, candidate_oid, ((declaration).spec ->> 'subject_key')::name,
            ((declaration).spec ->> 'candidate_key')::name, ((declaration).spec ->> 'priority')::name,
            result_columns, COALESCE(((declaration).spec ->> 'valid_from')::timestamptz, clock_timestamp()),
            NULLIF((declaration).spec ->> 'valid_to', '')::timestamptz,
            COALESCE(((declaration).spec ->> 'max_candidates')::integer, 1000))
        INTO delegated_id;
    END IF;

    IF current_found AND current_row.state = 'REMOVED' THEN
        UPDATE pgreact_internal.api_declarations
        SET api_version = (declaration).api_version, spec = (declaration).spec,
            normalized = normalized, declaration_digest = sha256(convert_to(normalized::text, 'UTF8')),
            delegated_id = COALESCE(delegated_id, current_row.delegated_id), owner_oid = owner_id,
            state = 'DEPLOYED', deployed_at = clock_timestamp(), removed_at = NULL
        WHERE declaration_id = current_row.declaration_id;
    ELSE
        INSERT INTO pgreact_internal.api_declarations(
            api_version, kind, object_name, spec, normalized, declaration_digest,
            delegated_id, owner_oid, state, deployed_at)
        VALUES ((declaration).api_version, (declaration).kind, (declaration).name,
                (declaration).spec, normalized, sha256(convert_to(normalized::text, 'UTF8')),
                delegated_id, owner_id, 'DEPLOYED', clock_timestamp());
    END IF;
    RETURN pgreact_internal.m28_envelope(
        'deploy', normalized, 'deployed',
        jsonb_build_object('read_only', false, 'delegated_id', delegated_id,
                           'delegates_to', (declaration).kind), findings);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.deploy_m29(declaration pgreact_api.declaration, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE checked jsonb;
    normalized jsonb;
    findings jsonb;
    snapshot jsonb;
    preview_digest text;
    existing pgreact_internal.policy_set_versions%ROWTYPE;
    set_row pgreact_internal.policy_sets%ROWTYPE;
    owner_id oid := (SELECT oid FROM pg_roles WHERE rolname = session_user);
    set_version text;
    allow_create boolean := true;
    member jsonb;
    ordinal integer := 0;
    source jsonb;
    set_valid_from timestamptz;
    set_valid_to timestamptz;
    set_id uuid;
BEGIN
    IF (declaration).kind <> 'policy_set' THEN
        RETURN pgreact_api.deploy_m28(declaration, preconditions);
    END IF;
    IF preconditions IS NULL OR jsonb_typeof(preconditions) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M29_PRECONDITIONS: preconditions must be a JSON object';
    END IF;
    checked := pgreact_internal.m29_validate(declaration);
    normalized := checked -> 'normalized';
    findings := checked -> 'findings';
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(findings) item WHERE item ->> 'severity' = 'ERROR') THEN
        RAISE EXCEPTION 'M29_VALIDATION: %', findings;
    END IF;
    snapshot := pgreact_internal.m29_snapshot(normalized);
    preview_digest := pgreact_internal.m29_digest(normalized, snapshot);
    IF preconditions ->> 'preview_digest' IS NOT NULL
       AND preconditions ->> 'preview_digest' <> preview_digest THEN
        RAISE EXCEPTION 'M29_PREVIEW_STALE'
            USING HINT = 'Preview the policy set again after applicability or member changes.';
    END IF;
    allow_create := COALESCE((preconditions ->> 'allow_create')::boolean, true);
    set_version := normalized -> 'spec' ->> 'version';
    set_valid_from := (normalized -> 'spec' ->> 'valid_from')::timestamptz;
    set_valid_to := NULLIF(normalized -> 'spec' ->> 'valid_to', '')::timestamptz;
    PERFORM pg_advisory_xact_lock(hashtextextended((declaration).name, 5788046901200004));
    SELECT * INTO set_row FROM pgreact_internal.policy_sets
    WHERE set_name = (declaration).name FOR UPDATE;
    IF FOUND THEN
        IF NOT pg_has_role(session_user, set_row.owner_oid, 'USAGE')
           AND NOT pgreact_internal.is_operator_admin() THEN
            RAISE EXCEPTION 'M29_OWNER: only the policy-set owner or operator may deploy this target';
        END IF;
        set_id := set_row.policy_set_id;
    ELSE
        INSERT INTO pgreact_internal.policy_sets(set_name, owner_oid)
        VALUES ((declaration).name, owner_id) RETURNING policy_set_id INTO set_id;
    END IF;
    SELECT * INTO existing FROM pgreact_internal.policy_set_versions
    WHERE policy_set_id = set_id AND version = set_version FOR UPDATE;
    IF FOUND THEN
        IF existing.declaration_digest IS DISTINCT FROM sha256(convert_to(normalized::text, 'UTF8')) THEN
            RAISE EXCEPTION 'M29_VERSION_IMMUTABLE: policy-set version % already has a different declaration', set_version;
        END IF;
        IF existing.state = 'DEPLOYED' AND allow_create THEN
            RAISE EXCEPTION 'M29_EXISTS: policy-set version % is already deployed', set_version
                USING HINT = 'Use a new immutable version for a changed policy set.';
        END IF;
        IF existing.state = 'DEPLOYED' AND NOT allow_create
           AND preconditions ->> 'expected_current_digest' IS DISTINCT FROM encode(existing.declaration_digest, 'hex') THEN
            RAISE EXCEPTION 'M29_REPLACE_STALE';
        END IF;
        UPDATE pgreact_internal.policy_set_versions
        SET state = 'DEPLOYED', removed_at = NULL, deployed_at = clock_timestamp(),
            complete_frontier = (snapshot ->> 'complete_frontier')::timestamptz,
            applicability_fingerprint = snapshot ->> 'applicability_fingerprint',
            eligible_subjects = snapshot -> 'eligible_subjects',
            eligible_subject_count = (snapshot ->> 'eligible_subject_count')::bigint
        WHERE policy_set_version_id = existing.policy_set_version_id;
    ELSE
        IF EXISTS (
            SELECT 1 FROM pgreact_internal.policy_set_versions other
            WHERE other.policy_set_id = set_id AND other.state = 'DEPLOYED'
              AND tstzrange(other.valid_from, COALESCE(other.valid_to, 'infinity'::timestamptz), '[)')
                  && tstzrange(set_valid_from, COALESCE(set_valid_to, 'infinity'::timestamptz), '[)')) THEN
            RAISE EXCEPTION 'M29_EFFECTIVE_OVERLAP: policy-set effective intervals overlap';
        END IF;
        source := checked -> 'source';
        INSERT INTO pgreact_internal.policy_set_versions(
            policy_set_id, version, normalized, declaration_digest, applicability_kind,
            applicability_source, applicability_source_oid, applicability_condition_version_id,
            subject_key, subject_type, valid_from, valid_to, complete_frontier,
            applicability_fingerprint, eligible_subjects, eligible_subject_count, state, deployed_at)
        VALUES (set_id, set_version, normalized, sha256(convert_to(normalized::text, 'UTF8')),
            source ->> 'source_kind', source ->> 'source_name', (source ->> 'relation')::oid,
            (source ->> 'condition_version_id')::uuid, (source ->> 'subject_key')::name,
            (source ->> 'subject_type')::regtype, set_valid_from, set_valid_to,
            (snapshot ->> 'complete_frontier')::timestamptz,
            snapshot ->> 'applicability_fingerprint', snapshot -> 'eligible_subjects',
            (snapshot ->> 'eligible_subject_count')::bigint, 'DEPLOYED', clock_timestamp())
        RETURNING policy_set_version_id INTO existing.policy_set_version_id;
        INSERT INTO pgreact_internal.policy_set_members(
            policy_set_version_id, ordinal, member_kind, member_name, member_version, member_target)
        SELECT existing.policy_set_version_id, row_number() OVER (), value ->> 'kind',
               value ->> 'name', value ->> 'version', value
        FROM jsonb_array_elements(normalized -> 'spec' -> 'members') value;
    END IF;
    INSERT INTO pgreact_internal.policy_set_history(policy_set_version_id, event_kind, frontier, details)
    VALUES (existing.policy_set_version_id, 'DEPLOYED', (snapshot ->> 'complete_frontier')::timestamptz,
        jsonb_build_object('preview_digest', preview_digest, 'eligible_subject_count', snapshot -> 'eligible_subject_count'));
    RETURN pgreact_internal.m29_envelope('deploy', normalized, 'deployed',
        jsonb_build_object('read_only', false, 'policy_set_version_id', existing.policy_set_version_id,
            'preview_digest', preview_digest, 'version', set_version,
            'complete_frontier', snapshot ->> 'complete_frontier',
            'eligible_subject_count', snapshot -> 'eligible_subject_count'), findings,
        jsonb_build_object('normalized_declaration', normalized, 'snapshot', snapshot));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.deploy_m30(declaration pgreact_api.declaration, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE checked jsonb;
    normalized jsonb;
    findings jsonb;
    snapshot jsonb;
    source jsonb;
    digest text;
    set_row pgreact_internal.policy_sets%ROWTYPE;
    existing pgreact_internal.policy_set_versions%ROWTYPE;
    set_id uuid;
    version_id uuid;
    owner_id oid := (SELECT oid FROM pg_roles WHERE rolname = session_user);
    set_version text;
    set_valid_from timestamptz;
    set_valid_to timestamptz;
    member jsonb;
    ordinal integer := 0;
BEGIN
    IF (declaration).kind <> 'policy_set' THEN
        RETURN pgreact_api.deploy_m29(declaration, preconditions);
    END IF;
    IF preconditions IS NULL OR jsonb_typeof(preconditions) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M30_PRECONDITIONS: preconditions must be a JSON object';
    END IF;
    checked := pgreact_internal.m30_validate(declaration);
    normalized := checked -> 'normalized';
    findings := checked -> 'findings';
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(findings) item
               WHERE item ->> 'severity' = 'ERROR') THEN
        RAISE EXCEPTION 'M30_VALIDATION: %', findings;
    END IF;
    snapshot := pgreact_internal.m30_snapshot(normalized);
    source := checked -> 'source';
    digest := pgreact_internal.m30_digest(normalized, snapshot);
    IF preconditions ->> 'preview_digest' IS NOT NULL
       AND preconditions ->> 'preview_digest' <> digest THEN
        RAISE EXCEPTION 'M30_PREVIEW_STALE'
            USING HINT = 'Preview the policy set again after source or member changes.';
    END IF;
    set_version := normalized -> 'spec' ->> 'version';
    set_valid_from := (normalized -> 'spec' ->> 'valid_from')::timestamptz;
    set_valid_to := NULLIF(normalized -> 'spec' ->> 'valid_to', '')::timestamptz;
    PERFORM pg_advisory_xact_lock(hashtextextended((declaration).name, 5788046901200004));
    SELECT * INTO set_row FROM pgreact_internal.policy_sets
    WHERE set_name = (declaration).name FOR UPDATE;
    IF FOUND THEN
        IF NOT pg_has_role(session_user, set_row.owner_oid, 'USAGE')
           AND NOT pgreact_internal.is_operator_admin() THEN
            RAISE EXCEPTION 'M30_OWNER: only the policy-set owner or operator may deploy this target';
        END IF;
        set_id := set_row.policy_set_id;
    ELSE
        INSERT INTO pgreact_internal.policy_sets(set_name, owner_oid)
        VALUES ((declaration).name, owner_id) RETURNING policy_set_id INTO set_id;
    END IF;
    SELECT * INTO existing FROM pgreact_internal.policy_set_versions
    WHERE policy_set_id = set_id AND version = set_version FOR UPDATE;
    IF FOUND THEN
        IF existing.declaration_digest IS DISTINCT FROM sha256(convert_to(normalized::text, 'UTF8')) THEN
            RAISE EXCEPTION 'M30_VERSION_IMMUTABLE: policy-set version % already has a different declaration',
                set_version;
        END IF;
        IF existing.state = 'DEPLOYED'
           AND COALESCE((preconditions ->> 'allow_create')::boolean, true) THEN
            RAISE EXCEPTION 'M30_EXISTS: policy-set version % is already deployed', set_version;
        END IF;
        version_id := existing.policy_set_version_id;
        UPDATE pgreact_internal.policy_set_versions
        SET state = 'DEPLOYED', removed_at = NULL, deployed_at = clock_timestamp(),
            subject_key = (source -> 'subject_keys' ->> 0)::name,
            subject_keys = ARRAY(SELECT jsonb_array_elements_text(source -> 'subject_keys'))::name[],
            subject_type = (source -> 'subject_types' ->> 0)::regtype,
            key_codec_version = 2, migration_state = 'READY',
            valid_from = set_valid_from, valid_to = set_valid_to,
            complete_frontier = (snapshot ->> 'complete_frontier')::timestamptz,
            applicability_fingerprint = snapshot ->> 'applicability_fingerprint',
            eligible_subjects = snapshot -> 'eligible_subjects',
            eligible_subject_count = (snapshot ->> 'eligible_subject_count')::bigint
        WHERE policy_set_version_id = version_id;
        DELETE FROM pgreact_internal.policy_set_members
        WHERE policy_set_version_id = version_id;
    ELSE
        IF EXISTS (
            SELECT 1 FROM pgreact_internal.policy_set_versions other
            WHERE other.policy_set_id = set_id AND other.state = 'DEPLOYED'
              AND tstzrange(other.valid_from, COALESCE(other.valid_to, 'infinity'::timestamptz), '[)')
                  && tstzrange(set_valid_from, COALESCE(set_valid_to, 'infinity'::timestamptz), '[)')) THEN
            RAISE EXCEPTION 'M30_EFFECTIVE_OVERLAP: policy-set effective intervals overlap';
        END IF;
        INSERT INTO pgreact_internal.policy_set_versions(
            policy_set_id, version, normalized, declaration_digest, applicability_kind,
            applicability_source, applicability_source_oid, applicability_condition_version_id,
            subject_key, subject_keys, subject_type, key_codec_version,
            valid_from, valid_to, complete_frontier, applicability_fingerprint,
            eligible_subjects, eligible_subject_count, migration_state, state, deployed_at)
        VALUES (
            set_id, set_version, normalized, sha256(convert_to(normalized::text, 'UTF8')),
            source ->> 'source_kind', source ->> 'source_name',
            (source ->> 'relation_oid')::oid, (source ->> 'condition_version_id')::uuid,
            (source -> 'subject_keys' ->> 0)::name,
            ARRAY(SELECT jsonb_array_elements_text(source -> 'subject_keys'))::name[],
            (source -> 'subject_types' ->> 0)::regtype, 2,
            set_valid_from, set_valid_to,
            (snapshot ->> 'complete_frontier')::timestamptz,
            snapshot ->> 'applicability_fingerprint',
            snapshot -> 'eligible_subjects',
            (snapshot ->> 'eligible_subject_count')::bigint,
            'READY', 'DEPLOYED', clock_timestamp())
        RETURNING policy_set_version_id INTO version_id;
    END IF;
    FOR member IN SELECT value FROM jsonb_array_elements(normalized -> 'spec' -> 'members') value LOOP
        ordinal := ordinal + 1;
        INSERT INTO pgreact_internal.policy_set_members(
            policy_set_version_id, ordinal, member_kind, member_name, member_version,
            member_target, match_keys, subject_keys, scope_mode, disposition)
        VALUES (
            version_id, ordinal, member ->> 'kind', member ->> 'name', member ->> 'version',
            member,
            ARRAY(SELECT jsonb_array_elements_text(member -> 'match_keys'))::name[],
            ARRAY(SELECT jsonb_array_elements_text(member -> 'subject_keys'))::name[],
            member ->> 'scope_mode', member ->> 'disposition');
    END LOOP;
    DELETE FROM pgreact_internal.policy_set_eligibility
    WHERE policy_set_version_id = version_id;
    INSERT INTO pgreact_internal.policy_set_eligibility(
        policy_set_version_id, subject_identity, subject_values, key_types,
        key_codec_version, complete_frontier, source_fingerprint)
    SELECT version_id, decode(row_data ->> 'subject_identity', 'hex'),
           row_data -> 'subject_values',
           ARRAY(SELECT jsonb_array_elements_text(row_data -> 'key_types'))::text[],
           2, (snapshot ->> 'complete_frontier')::timestamptz,
           snapshot ->> 'applicability_fingerprint'
    FROM jsonb_array_elements(snapshot -> 'eligibility_rows') row_data;
    INSERT INTO pgreact_internal.policy_set_history(
        policy_set_version_id, event_kind, frontier, details)
    VALUES (version_id, 'DEPLOYED',
        (snapshot ->> 'complete_frontier')::timestamptz,
        jsonb_build_object('preview_digest', digest,
            'eligible_subject_count', snapshot -> 'eligible_subject_count',
            'key_codec_version', 2));
    INSERT INTO pgreact_internal.declaration_migrations(
        declaration_id, kind, object_name, object_version, state, reason, remediation)
    VALUES (
        (SELECT declaration_id FROM pgreact_internal.api_declarations
         WHERE kind = 'policy_set' AND object_name = (declaration).name),
        'policy_set', (declaration).name, set_version, 'READY',
        'M30 canonical applicability foundation is deployed',
        'Use status, explain, and the relational inspection views.')
    ON CONFLICT (kind, object_name, object_version) DO UPDATE SET
        state = EXCLUDED.state, reason = EXCLUDED.reason,
        remediation = EXCLUDED.remediation, observed_at = clock_timestamp();
    RETURN pgreact_internal.m30_envelope('deploy', normalized, 'deployed',
        jsonb_build_object(
            'read_only', false,
            'policy_set_version_id', version_id,
            'version', set_version,
            'subject_keys', snapshot -> 'subject_keys',
            'eligible_subject_count', snapshot -> 'eligible_subject_count',
            'migration_state', 'READY',
            'runtime_state', 'FOUNDATION_ONLY'),
        findings,
        jsonb_build_object(
            'raw_truth', jsonb_build_object('eligible_subject_count',
                snapshot -> 'eligible_subject_count'),
            'effective_truth', jsonb_build_object('scope_supports', 0),
            'subject_identity', jsonb_build_object(
                'keys', snapshot -> 'subject_keys', 'codec_version', 2),
            'runtime_barriers', '[]'::jsonb,
            'work_recheck', jsonb_build_object('state', 'M31_REQUIRED')));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.deploy_program(definition jsonb, expected_plan_digest text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    diagnostic record;
    actual_digest text;
    rewritten jsonb := definition;
    first_rule jsonb := definition #> '{rules,0}';
    window_item jsonb := definition #> '{rules,0,aggregate_input,window}';
    target_spec pgreact_internal.keyed_derived_relations%ROWTYPE;
    old_program pgreact_internal.window_programs%ROWTYPE;
    has_old boolean := false;
    deployed uuid;
    helper_suffix text := md5((definition ->> 'name') || '@' || (definition ->> 'version'));
    helper_input text := format('pgreact_runtime.m17_input_%s', helper_suffix);
    helper_keys text := format('pgreact_runtime.m17_keys_%s', helper_suffix);
    helper_input_store text := format('pgreact_runtime.m17_input_store_%s', helper_suffix);
    helper_keys_store text := format('pgreact_runtime.m17_keys_store_%s', helper_suffix);
    group_columns name[];
    group_list text;
    join_list text;
    window_column name;
    item record;
    rule_version_id uuid;
    function_name text;
    input_name text := first_rule #>> '{aggregate_input,relation}';
    condition_name text := first_rule ->> 'definition';
    input_oid oid;
    condition_oid oid;
    duration_value bigint;
    lateness_value bigint;
BEGIN
    IF NOT pgreact_internal.is_window_program(definition) THEN
        RETURN pgreact_internal.deploy_program_m16(definition, expected_plan_digest);
    END IF;
    SELECT * INTO diagnostic FROM pgreact_api.validate_program(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M17_PROGRAM_INVALID: % for %', diagnostic.code, diagnostic.object_identity
            USING HINT = diagnostic.hint;
    END IF;
    actual_digest := pgreact_internal.window_plan_digest(definition);
    IF expected_plan_digest IS NOT NULL AND expected_plan_digest <> actual_digest THEN
        RAISE EXCEPTION 'M17_PROGRAM_PREVIEW_STALE'
            USING ERRCODE = '55000',
                  HINT = 'Preview the program again after DDL or deployment changes.';
    END IF;
    SELECT spec.* INTO STRICT target_spec
    FROM pgreact_internal.keyed_derived_relations spec
    WHERE spec.public_name = first_rule ->> 'target';
    group_columns := target_spec.key_columns[1:cardinality(target_spec.key_columns)-1];
    window_column := target_spec.key_columns[cardinality(target_spec.key_columns)];
    SELECT string_agg(format('%I', value), ', ' ORDER BY ordinal),
           string_agg(format('%I', value), ', ' ORDER BY ordinal)
    INTO group_list, join_list
    FROM unnest(group_columns) WITH ORDINALITY column_name(value, ordinal);
    input_oid := to_regclass(input_name);
    condition_oid := to_regclass(condition_name);
    duration_value := pgreact_internal.fixed_interval_us(window_item ->> 'duration', false);
    lateness_value := pgreact_internal.fixed_interval_us(
        window_item ->> 'allowed_lateness', true);
    SELECT prior.* INTO old_program
    FROM pgreact_internal.window_programs prior
    WHERE prior.program_name = definition ->> 'name' AND prior.active
    FOR UPDATE;
    has_old := FOUND;

    EXECUTE format('DROP VIEW IF EXISTS %s CASCADE', helper_input);
    EXECUTE format('DROP VIEW IF EXISTS %s CASCADE', helper_keys);
    EXECUTE format('DROP TABLE IF EXISTS %s CASCADE', helper_input_store);
    EXECUTE format('DROP TABLE IF EXISTS %s CASCADE', helper_keys_store);
    EXECUTE format(
        'CREATE TABLE %s AS SELECT source.*, 0::bigint AS %I FROM %s source WITH NO DATA',
        helper_input_store, window_column, input_oid::regclass);
    EXECUTE format(
        'CREATE TABLE %s AS SELECT %s, %I FROM %s WITH NO DATA',
        helper_keys_store, group_list, window_column, helper_input_store);
    EXECUTE format('CREATE VIEW %s AS SELECT * FROM %s', helper_input, helper_input_store);
    EXECUTE format('CREATE VIEW %s AS SELECT * FROM %s', helper_keys, helper_keys_store);
    EXECUTE format('ALTER TABLE %s OWNER TO %I', helper_input_store, session_user);
    EXECUTE format('ALTER TABLE %s OWNER TO %I', helper_keys_store, session_user);
    EXECUTE format('ALTER VIEW %s OWNER TO %I', helper_input, session_user);
    EXECUTE format('ALTER VIEW %s OWNER TO %I', helper_keys, session_user);
    EXECUTE format('ALTER TABLE %s ADD PRIMARY KEY (%s, %I)',
                   helper_keys_store, group_list, window_column);
    IF has_old THEN
        EXECUTE format('INSERT INTO %s SELECT * FROM %s',
                       helper_keys_store, old_program.helper_keys_name);
        EXECUTE format(
            'INSERT INTO %s SELECT source.*, pgreact_internal.window_ordinal(source.%I, $1) '
            'FROM %s source JOIN %s condition USING (%s)',
            helper_input_store, (window_item ->> 'event_time')::name,
            input_oid::regclass, condition_oid::regclass, join_list)
        USING duration_value;
    END IF;

    FOR item IN SELECT value, ordinal FROM jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY rules(value, ordinal)
    LOOP
        rewritten := jsonb_set(rewritten,
            ARRAY['rules',(item.ordinal - 1)::text,'definition'], to_jsonb(helper_keys));
        rewritten := jsonb_set(rewritten,
            ARRAY['rules',(item.ordinal - 1)::text,'aggregate_input'],
            ((item.value -> 'aggregate_input') - 'window') || jsonb_build_object('relation', helper_input));
    END LOOP;
    deployed := pgreact_internal.deploy_program_m16(rewritten, NULL);
    IF has_old THEN
        UPDATE pgreact_internal.window_programs SET active = false
        WHERE program_version_id = old_program.program_version_id;
    END IF;
    INSERT INTO pgreact_internal.window_programs (
        program_version_id, program_name, program_version, owner_oid, public_definition,
        input_relation_name, condition_relation_name,
        input_definition_digest, input_row_signature,
        condition_definition_digest, condition_row_signature,
        event_time_column, duration_us, allowed_lateness_us, group_columns, window_column,
        helper_input_name, helper_keys_name, helper_input_store_name, helper_keys_store_name,
        max_facts,
        lower_frontier, observed_frontier, requested_watermark, complete_watermark,
        history_floor, last_source_fingerprint, last_observed_fingerprint)
    VALUES (
        deployed, definition ->> 'name', (definition ->> 'version')::integer,
        (SELECT oid FROM pg_roles WHERE rolname = session_user), definition,
        input_name, condition_name,
        pgreact_internal.source_closure_digest(input_oid),
        pgreact_internal.source_row_signature(input_oid),
        pgreact_internal.source_closure_digest(condition_oid),
        pgreact_internal.source_row_signature(condition_oid),
        (window_item ->> 'event_time')::name, duration_value, lateness_value,
        group_columns, window_column, helper_input, helper_keys,
        helper_input_store, helper_keys_store,
        (definition ->> 'max_facts')::bigint,
        CASE WHEN has_old THEN old_program.lower_frontier ELSE 0 END,
        CASE WHEN has_old THEN old_program.observed_frontier ELSE 0 END,
        CASE WHEN has_old THEN old_program.requested_watermark ELSE '-infinity' END,
        CASE WHEN has_old THEN old_program.complete_watermark ELSE '-infinity' END,
        CASE WHEN has_old THEN old_program.history_floor ELSE '-infinity' END,
        CASE WHEN has_old THEN old_program.last_source_fingerprint ELSE sha256(''::bytea) END,
        CASE WHEN has_old THEN old_program.last_observed_fingerprint ELSE sha256(''::bytea) END);

    FOR item IN SELECT value, ordinal FROM jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY rules(value, ordinal)
    LOOP
        SELECT version.rule_version_id INTO STRICT rule_version_id
        FROM pgreact_internal.rules rule
        JOIN pgreact_internal.rule_versions version USING (rule_id)
        WHERE rule.rule_name = item.value ->> 'name' AND version.state = 'ACTIVE';
        function_name := COALESCE(item.value #>> '{aggregate_input,function}', 'COUNT_STAR');
        INSERT INTO pgreact_internal.window_rules (
            program_version_id, rule_version_id, rule_name, rule_version,
            target_relation, aggregate_function, value_expression, comparison, typed_threshold)
        VALUES (
            deployed, rule_version_id, item.value ->> 'name',
            (item.value ->> 'version')::integer, item.value ->> 'target', function_name,
            (item.value #>> '{aggregate_input,expression}')::name,
            item.value #>> '{aggregate_input,comparison}',
            item.value #>> '{aggregate_input,threshold}');
    END LOOP;
    IF has_old THEN
        INSERT INTO pgreact_internal.window_source_rows
        SELECT deployed, row_data, public_window_key, event_time, window_ordinal, occurrences
        FROM pgreact_internal.window_source_rows
        WHERE program_version_id = old_program.program_version_id;
        INSERT INTO pgreact_internal.window_identities
        SELECT deployed, public_window_key, canonical_window_key, window_ordinal,
               window_start, window_end, lateness_boundary, final
        FROM pgreact_internal.window_identities
        WHERE program_version_id = old_program.program_version_id;
        PERFORM pgreact_internal.seed_window_corrections(deployed);
    END IF;
    INSERT INTO pgreact_internal.window_audits(program_version_id, operation, details)
    VALUES (deployed, 'DEPLOY', jsonb_build_object(
        'program', definition ->> 'name', 'version', (definition ->> 'version')::integer,
        'replacement', has_old));
    RETURN deployed;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.deploy_shared_condition(definition jsonb, expected_plan_digest text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    preview jsonb;
    normalized jsonb;
    condition_row pgreact_internal.shared_conditions%ROWTYPE;
    prior pgreact_internal.shared_condition_versions%ROWTYPE;
    source_oid oid;
    row_type_oid oid;
    relation_version uuid;
    program_version uuid;
    condition_version uuid := gen_random_uuid();
    target_version integer;
    actual_plan_digest text;
    program_definition jsonb;
    program_preview jsonb;
    program_name text;
    mode text;
    keys name[];
    key_types regtype[];
    key_collations regcollation[];
    source_definition text;
    source_signature bytea;
    source_digest bytea;
    condition_owner oid := (SELECT oid FROM pg_roles WHERE rolname = session_user);
    incompatible boolean := false;
    consumer_count bigint;
    has_prior boolean := false;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(
        COALESCE(definition ->> 'name', 'condition'), 5788046901200004));
    preview := pgreact_api.preview_shared_condition(definition);
    normalized := preview -> 'condition';
    target_version := (normalized ->> 'version')::integer;
    actual_plan_digest := preview ->> 'plan_digest';
    IF expected_plan_digest IS NOT NULL AND expected_plan_digest <> actual_plan_digest THEN
        RAISE EXCEPTION 'M20_CONDITION_PREVIEW_STALE'
            USING HINT = 'Preview the shared condition again after source or deployment changes.';
    END IF;
    SELECT * INTO condition_row
    FROM pgreact_internal.shared_conditions
    WHERE condition_name = normalized ->> 'name'
    FOR UPDATE;
    IF FOUND AND condition_row.owner_oid <> condition_owner THEN
        RAISE EXCEPTION 'M20_CONDITION_OWNER: % is not owned by %',
            normalized ->> 'name', session_user;
    END IF;
    IF NOT FOUND THEN
        INSERT INTO pgreact_internal.shared_conditions(condition_id, condition_name, owner_oid)
        VALUES (condition_version, normalized ->> 'name', condition_owner)
        RETURNING * INTO condition_row;
        relation_version := pgreact_api.declare_derived_relation(
            normalized ->> 'name', (normalized ->> 'row_type')::regtype,
            pgreact_internal.condition_keys(normalized), 1);
        EXECUTE format('ALTER VIEW %s OWNER TO %I',
                       normalized ->> 'name', session_user);
    ELSE
        has_prior := true;
        SELECT * INTO STRICT prior
        FROM pgreact_internal.shared_condition_versions
        WHERE condition_id = condition_row.condition_id AND state = 'ACTIVE'
        FOR UPDATE;
        PERFORM pgreact_internal.refresh_shared_condition_consumers(prior.condition_version_id);
        SELECT count(*) INTO consumer_count
        FROM pgreact_internal.shared_condition_consumers
        WHERE condition_version_id = prior.condition_version_id;
        source_oid := to_regclass(normalized ->> 'source');
        row_type_oid := (normalized ->> 'row_type')::regtype;
        keys := pgreact_internal.condition_keys(normalized);
        SELECT array_agg(attribute.atttypid::regtype ORDER BY key.ordinality),
               array_agg(attribute.attcollation::regcollation ORDER BY key.ordinality)
        INTO key_types, key_collations
        FROM unnest(keys) WITH ORDINALITY key(key_name, ordinality)
        JOIN pg_attribute attribute
          ON attribute.attrelid = (SELECT typrelid FROM pg_type WHERE oid = row_type_oid)
         AND attribute.attname = key.key_name
         AND attribute.attnum > 0 AND NOT attribute.attisdropped;
        incompatible := prior.row_type_oid <> row_type_oid
            OR prior.key_columns <> keys
            OR prior.key_types <> key_types
            OR prior.key_collations <> key_collations
            OR prior.maintenance_mode <> upper(COALESCE(normalized ->> 'maintenance_mode', 'SCHEDULED'))
            OR prior.source_row_signature <> pgreact_internal.source_row_signature(source_oid);
        IF incompatible AND consumer_count > 0 THEN
            RAISE EXCEPTION 'M20_INCOMPATIBLE_REPLACEMENT: % has live consumers',
                normalized ->> 'name'
                USING HINT = 'Deploy a compatible schema or remove/replace every consumer atomically.';
        END IF;
        relation_version := prior.relation_version_id;
    END IF;
    source_oid := to_regclass(normalized ->> 'source');
    row_type_oid := (normalized ->> 'row_type')::regtype;
    keys := pgreact_internal.condition_keys(normalized);
    SELECT array_agg(attribute.atttypid::regtype ORDER BY key.ordinality),
           array_agg(attribute.attcollation::regcollation ORDER BY key.ordinality)
    INTO key_types, key_collations
    FROM unnest(keys) WITH ORDINALITY key(key_name, ordinality)
    JOIN pg_attribute attribute
      ON attribute.attrelid = (SELECT typrelid FROM pg_type WHERE oid = row_type_oid)
     AND attribute.attname = key.key_name
     AND attribute.attnum > 0 AND NOT attribute.attisdropped;
    source_definition := COALESCE(pg_get_viewdef(source_oid, true), source_oid::regclass::text);
    source_signature := pgreact_internal.source_row_signature(source_oid);
    source_digest := pgreact_internal.source_closure_digest(source_oid);
    mode := upper(COALESCE(normalized ->> 'maintenance_mode', 'SCHEDULED'));
    program_definition := pgreact_internal.condition_program(normalized, target_version);
    program_name := program_definition ->> 'name';
    IF mode = 'IMMEDIATE' THEN
        program_preview := pgreact_api.preview_immediate_program(program_definition);
        program_version := pgreact_api.deploy_immediate_program(
            program_definition, program_preview ->> 'plan_digest');
    ELSE
        program_preview := pgreact_api.preview_program(program_definition);
        program_version := pgreact_api.deploy_program(
            program_definition, program_preview ->> 'plan_digest');
    END IF;
    IF has_prior THEN
        UPDATE pgreact_internal.shared_condition_versions
        SET state = 'REMOVED'
        WHERE condition_version_id = prior.condition_version_id;
    END IF;
    INSERT INTO pgreact_internal.shared_condition_versions(
        condition_version_id, condition_id, version, owner_oid,
        source_view_oid, source_view_name, source_definition,
        source_definition_digest, source_row_signature, row_type_oid,
        row_type_name, key_columns, key_types, key_collations,
        relation_version_id, program_version_id, maintenance_mode, state)
    SELECT condition_version, condition_row.condition_id, target_version, condition_owner,
           source_oid, source_oid::regclass::text, source_definition,
           source_digest, source_signature,
           row_type_oid, normalized ->> 'row_type',
           keys, key_types, key_collations, relation_version, program_version,
           mode, 'ACTIVE';
    PERFORM pgreact_internal.refresh_shared_condition_consumers(condition_version);
    RETURN condition_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.doctor_m29(target pgreact_api.target, options jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
    row_data pgreact_internal.policy_set_versions%ROWTYPE;
    current_fingerprint text;
    diagnostics jsonb := '[]'::jsonb;
BEGIN
    IF (target).kind <> 'policy_set' THEN RETURN pgreact_api.doctor_m28(target, options); END IF;
    result := pgreact_internal.m29_status(target);
    SELECT version.* INTO row_data
    FROM pgreact_internal.policy_set_versions version
    JOIN pgreact_internal.policy_sets set USING (policy_set_id)
    WHERE set.set_name = (target).name
      AND (($1).version IS NULL OR version.version = ($1).version)
      AND version.state = 'DEPLOYED'
    ORDER BY version.valid_from DESC LIMIT 1;
    IF NOT FOUND THEN
        diagnostics := jsonb_build_array(pgreact_internal.m29_finding(
            'M29_TARGET_NOT_FOUND', 'ERROR', (target).name, 'target',
            'no deployed policy-set version is available', 'Deploy a valid policy-set version.'));
    ELSE
        current_fingerprint := pgreact_internal.m29_relation_fingerprint(
            row_data.applicability_source_oid, row_data.subject_key, row_data.complete_frontier);
        IF current_fingerprint IS DISTINCT FROM row_data.applicability_fingerprint THEN
            diagnostics := jsonb_build_array(pgreact_internal.m29_finding(
                'M29_SOURCE_DRIFT', 'ERROR', (target).name, 'applicability',
                'the applicability source changed after deployment',
                'Run the policy-set again or deploy a new immutable version.',
                jsonb_build_object('deployed', row_data.applicability_fingerprint,
                                   'current', current_fingerprint)));
        ELSE
            diagnostics := jsonb_build_array(jsonb_build_object(
                'code', 'M29_POLICY_SET_READY', 'severity', 'INFO', 'blocker', false,
                'object_identity', (target).name,
                'message', 'policy-set applicability is current and fail-closed',
                'hint', 'Use status or explain to inspect eligible subjects.'));
        END IF;
    END IF;
    RETURN result || jsonb_build_object('operation', 'doctor', 'diagnostics', diagnostics);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.explain_provenance(target_relation uuid, target_key bigint, max_supports integer DEFAULT 100, continuation_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE relation_row pgreact_internal.derived_relation_versions%ROWTYPE;
    fact_value jsonb; support_total bigint; remaining_count bigint; returned_count integer;
    support_rows jsonb; proof jsonb; token jsonb; after_support uuid;
    support_digest bytea; continuation text; result jsonb;
    program_id uuid; inherited_proof jsonb;
BEGIN
    relation_row := pgreact_internal.assert_provenance_reader(target_relation);
    IF max_supports NOT BETWEEN 1 AND 1000 THEN
        RAISE EXCEPTION 'M22_PROVENANCE_LIMIT: max_supports must be between 1 and 1000';
    END IF;
    SELECT fact INTO fact_value
      FROM pgreact_internal.derived_facts
     WHERE relation_version_id = target_relation AND semantic_key = target_key;
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'contract_version', 10, 'status', 'UNAVAILABLE',
            'relation', relation_row.public_view_name || '@' || relation_row.version,
            'semantic_key', target_key,
            'diagnostic', jsonb_build_object(
                'code', 'M22_PROVENANCE_UNAVAILABLE',
                'message', 'the requested derived fact has no retained current proof',
                'remediation', 'reconcile the relation or restore retained history'));
    END IF;

    SELECT count(*), sha256(convert_to(COALESCE(string_agg(
        support_id::text, ',' ORDER BY support_id), ''), 'UTF8'))
      INTO support_total, support_digest
      FROM pgreact_internal.derived_supports
     WHERE relation_version_id = target_relation
       AND semantic_key = target_key AND active;
    IF continuation_token IS NOT NULL THEN
        BEGIN
            token := convert_from(decode(continuation_token, 'base64'), 'UTF8')::jsonb;
            IF token ->> 'relation' <> target_relation::text
               OR (token ->> 'semantic_key')::bigint <> target_key
               OR token ->> 'digest' <> encode(support_digest, 'hex') THEN
                RAISE EXCEPTION 'M22_PROVENANCE_SNAPSHOT_CHANGED';
            END IF;
            after_support := (token ->> 'after_support_id')::uuid;
        EXCEPTION WHEN SQLSTATE 'P0001' THEN RAISE;
                WHEN OTHERS THEN
            RAISE EXCEPTION 'M22_PROVENANCE_CONTINUATION_INVALID: token is expired or malformed';
        END;
    END IF;

    SELECT COALESCE(jsonb_agg(row_json ORDER BY support_id), '[]'::jsonb)
      INTO support_rows
      FROM (
          SELECT support.support_id,
                 pgreact_internal.provenance_support_json(support.support_id) AS row_json
            FROM pgreact_internal.derived_supports support
           WHERE support.relation_version_id = target_relation
             AND support.semantic_key = target_key AND support.active
             AND (after_support IS NULL OR support.support_id > after_support)
           ORDER BY support.support_id
           LIMIT max_supports
      ) page;
    returned_count := jsonb_array_length(support_rows);
    IF after_support IS NULL THEN
        remaining_count := support_total;
    ELSE
        SELECT count(*) INTO remaining_count
          FROM pgreact_internal.derived_supports support
         WHERE support.relation_version_id = target_relation
           AND support.semantic_key = target_key AND support.active
           AND support.support_id > after_support;
    END IF;
    IF returned_count > 0 AND returned_count < remaining_count THEN
        continuation := encode(convert_to(jsonb_build_object(
            'relation', target_relation, 'semantic_key', target_key,
            'digest', encode(support_digest, 'hex'),
            'after_support_id', (support_rows -> (returned_count - 1)) ->> 'support_id'
        )::text, 'UTF8'), 'base64');
    END IF;
    proof := pgreact_internal.provenance_proof(target_relation, target_key, 32, 1000);
    SELECT support.program_version_id INTO program_id
      FROM pgreact_internal.derived_supports support
     WHERE support.relation_version_id = target_relation
       AND support.semantic_key = target_key AND support.active
       AND support.program_version_id IS NOT NULL
     ORDER BY support.program_version_id LIMIT 1;
    inherited_proof := CASE WHEN program_id IS NULL THEN
        jsonb_build_object('relation_version_id', target_relation, 'semantic_key', target_key,
                           'supports', '[]'::jsonb)
      ELSE pgreact_internal.recursive_fact_proof(
          program_id, target_relation, target_key, '{}'::uuid[]) END;
    result := jsonb_build_object(
        'contract_version', 10, 'status', 'GROUNDED',
        'relation', relation_row.public_view_name || '@' || relation_row.version,
        'relation_version_id', target_relation, 'semantic_key', target_key,
        'fact', fact_value,
        'supports', support_rows,
        'total_supports', support_total,
        'returned_supports', returned_count,
        'omitted_supports', remaining_count - returned_count,
        'continuation', continuation,
        'proof', proof,
        'inherited_proof', inherited_proof,
        'bounds', jsonb_build_object(
            'max_supports', max_supports, 'max_depth', 32,
            'max_nodes', 1000, 'max_payload_bytes', 1048576));
    RETURN result || jsonb_build_object('payload_bytes', pg_column_size(result));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.explain_rule(name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_id uuid; result jsonb;
BEGIN
    SELECT version.rule_version_id INTO version_id
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    WHERE rule.rule_name = explain_rule.name
    ORDER BY version.created_at DESC LIMIT 1;
    IF version_id IS NULL THEN RAISE EXCEPTION 'M11_RULE_NOT_FOUND: %', name; END IF;
    result := pgreact.explain_rule(version_id);
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.deadline_rules
        WHERE rule_version_id = version_id
    ) THEN
        result := result || jsonb_build_object(
            'deadline', (pgreact_internal.deadline_status(name) -> 0),
            'deadline_history', pgreact_internal.deadline_history(name));
    END IF;
    RETURN result;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.grant_shared_condition_reader(condition_name text, reader_role regrole)
 RETURNS void
 LANGUAGE plpgsql
