CREATE OR REPLACE FUNCTION pgreact_api.preview_program(definition jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE diagnostic record;
BEGIN
    IF NOT pgreact_internal.is_window_program(definition) THEN
        RETURN pgreact_internal.preview_program_m16(definition);
    END IF;
    SELECT * INTO diagnostic FROM pgreact_api.validate_program(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M17_PROGRAM_INVALID: % for %', diagnostic.code, diagnostic.object_identity
            USING HINT = diagnostic.hint;
    END IF;
    RETURN jsonb_build_object(
        'contract_version', 6,
        'program', pgreact_internal.normalized_window_program(definition),
        'plan_digest', pgreact_internal.window_plan_digest(definition));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.preview_shared_condition(definition jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    diagnostic record;
    normalized jsonb := definition;
    source_oid oid;
    source_digest text;
    next_version integer;
    expected_version integer;
    plan_digest text;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_shared_condition(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M20_CONDITION_INVALID: % for %: %', diagnostic.code,
            diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    SELECT COALESCE(max(version), 0) + 1 INTO next_version
    FROM pgreact_internal.shared_condition_versions version
    JOIN pgreact_internal.shared_conditions condition USING (condition_id)
    WHERE condition.condition_name = definition ->> 'name';
    expected_version := COALESCE((definition ->> 'version')::integer, next_version);
    IF expected_version <> next_version THEN
        RAISE EXCEPTION 'M20_VERSION_ORDER: expected version %, received %',
            next_version, expected_version;
    END IF;
    normalized := jsonb_set(definition, '{version}', to_jsonb(next_version), true);
    source_oid := to_regclass(normalized ->> 'source');
    source_digest := encode(pgreact_internal.source_closure_digest(source_oid), 'hex');
    plan_digest := encode(sha256(convert_to(
        normalized::text || ':' || session_user || ':' || source_digest, 'UTF8')), 'hex');
    RETURN jsonb_build_object(
        'contract_version', 8,
        'condition', normalized,
        'relation', normalized ->> 'name',
        'version', next_version,
        'maintenance_mode', upper(COALESCE(normalized ->> 'maintenance_mode', 'SCHEDULED')),
        'source_digest', source_digest,
        'consumers', '[]'::jsonb,
        'program', pgreact_internal.condition_program(normalized, next_version),
        'plan_digest', plan_digest);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.prune_window_history(program_name text, cutoff timestamp with time zone)
 RETURNS TABLE(windows bigint, corrections bigint, blocked bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    deleted_count bigint := 0;
    window_count bigint := 0;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M17_PRUNE_UNAUTHORIZED: % is not the configured operator', session_user
            USING ERRCODE = '42501';
    END IF;
    IF cutoff IS NULL OR NOT isfinite(cutoff) THEN
        RAISE EXCEPTION 'M17_HISTORY_CUTOFF_INVALID: cutoff must be finite'
            USING ERRCODE = '22008';
    END IF;
    SELECT * INTO STRICT program FROM pgreact_internal.window_programs
    WHERE window_programs.program_name = prune_window_history.program_name AND active FOR UPDATE;
    IF cutoff < program.history_floor OR cutoff > program.complete_watermark THEN
        RAISE EXCEPTION 'M17_HISTORY_CUTOFF_INVALID: cutoff is outside the committed recovery horizon'
            USING ERRCODE = '22023';
    END IF;
    IF cutoff = program.history_floor THEN
        RETURN QUERY SELECT 0::bigint,0::bigint,0::bigint;
        RETURN;
    END IF;
    WITH ranked AS (
        SELECT correction.correction_order,correction.public_window_key,
               row_number() OVER (
                   PARTITION BY correction.rule_version_id,correction.public_window_key
                   ORDER BY correction.lower_frontier DESC,correction.correction_order DESC) AS position
        FROM pgreact_internal.window_corrections correction
        JOIN pgreact_internal.window_identities identity
          USING (program_version_id,public_window_key)
        WHERE correction.program_version_id = program.program_version_id
          AND identity.final AND identity.lateness_boundary < cutoff
    ), candidates AS (
        SELECT * FROM ranked WHERE position > 1
    ), deleted AS (
        DELETE FROM pgreact_internal.window_corrections correction
        USING candidates
        WHERE correction.correction_order = candidates.correction_order
        RETURNING candidates.public_window_key)
    SELECT count(*),count(DISTINCT public_window_key) INTO deleted_count,window_count FROM deleted;
    UPDATE pgreact_internal.window_programs SET history_floor = cutoff
    WHERE program_version_id = program.program_version_id;
    INSERT INTO pgreact_internal.window_audits(program_version_id,operation,details)
    VALUES (program.program_version_id,'PRUNE_WINDOW_HISTORY',jsonb_build_object(
        'cutoff',cutoff,'windows',window_count,'corrections',deleted_count,'blocked',0));
    RETURN QUERY SELECT window_count,deleted_count,0::bigint;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.reconcile_decision_program(program_name text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE target_program uuid;
    current_frontier timestamptz;
BEGIN
    SELECT program_id INTO target_program FROM pgreact_internal.decision_programs
    WHERE decision_programs.program_name = reconcile_decision_program.program_name
      AND state <> 'REMOVED';
    IF NOT FOUND THEN RAISE EXCEPTION 'M26_PROGRAM: decision program was not found'; END IF;
    SELECT frontier INTO current_frontier FROM pgreact_internal.clock_frontier;
    RETURN pgreact_internal.refresh_decision_program(target_program, current_frontier);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.reconcile_program(program_name text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    fingerprint bytea;
    repaired bigint;
BEGIN
    SELECT * INTO program FROM pgreact_internal.window_programs
    WHERE window_programs.program_name = reconcile_program.program_name AND active FOR UPDATE;
    IF NOT FOUND THEN RETURN pgreact_internal.reconcile_program_m16(program_name); END IF;
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M17_RECONCILE_UNAUTHORIZED: % is not the configured operator', session_user
            USING ERRCODE = '42501';
    END IF;
    PERFORM pg_advisory_xact_lock(5788046901200000);
    PERFORM pgreact_internal.assert_window_history(program.program_version_id);
    IF program.barrier IS NULL THEN
        RETURN pgreact_internal.reconcile_program_m16(program_name);
    END IF;
    PERFORM pgreact_internal.begin_window_stage();
    PERFORM pgreact_internal.load_window_rows(program.program_version_id);
    IF pgreact_internal.stage_differs(program.program_version_id) THEN
        RAISE EXCEPTION 'M17_LATE_INPUT_UNRESOLVED: authoritative input still differs from finalized state'
            USING ERRCODE = '55000',
                  HINT = 'Restore the authoritative input, then reconcile again.';
    END IF;
    fingerprint := pgreact_internal.staged_window_fingerprint(program.program_version_id);
    repaired := pgreact_internal.reconcile_program_m16(program_name);
    UPDATE pgreact_internal.window_programs
    SET observed_frontier = observed_frontier +
            CASE WHEN fingerprint IS DISTINCT FROM last_observed_fingerprint THEN 1 ELSE 0 END,
        lower_frontier = observed_frontier +
            CASE WHEN fingerprint IS DISTINCT FROM last_observed_fingerprint THEN 1 ELSE 0 END,
        last_source_fingerprint = fingerprint,
        last_observed_fingerprint = fingerprint,
        barrier = NULL
    WHERE program_version_id = program.program_version_id;
    INSERT INTO pgreact_internal.window_audits(program_version_id,operation,details)
    VALUES (program.program_version_id,'LATE_INPUT_REPAIRED',
            jsonb_build_object('program',program.program_name));
    RETURN repaired;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.reconcile_temporal_rule(target_name text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_id uuid; repaired bigint;
BEGIN
    SELECT version.rule_version_id INTO STRICT version_id
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    JOIN pgreact_internal.temporal_rules spec USING (rule_version_id)
    WHERE rule.rule_name = target_name AND version.state = 'ACTIVE';
    PERFORM pgreact.refresh_rule(version_id);
    SET CONSTRAINTS ALL IMMEDIATE;
    repaired := pgreact_internal.reconcile_temporal_rule(version_id);
    RETURN repaired;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.remove_m28(target pgreact_api.target, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE row pgreact_internal.api_declarations%ROWTYPE;
    normalized jsonb;
    owner_id oid;
BEGIN
    SELECT * INTO row FROM pgreact_internal.api_declarations
    WHERE kind = (target).kind AND object_name = (target).name FOR UPDATE;
    IF NOT FOUND THEN
        RETURN pgreact_internal.m28_status(target);
    END IF;
    SELECT oid INTO owner_id FROM pg_roles WHERE rolname = session_user;
    IF row.owner_oid <> owner_id AND NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M28_OWNER: only the declaration owner or operator may remove this target';
    END IF;
    normalized := row.normalized;
    UPDATE pgreact_internal.api_declarations
    SET state = 'REMOVED', removed_at = clock_timestamp()
    WHERE declaration_id = row.declaration_id;
    RETURN pgreact_internal.m28_envelope(
        'remove', normalized, 'removed',
        jsonb_build_object('read_only', false, 'declaration_id', row.declaration_id));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.remove_m29(target pgreact_api.target, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE row_data pgreact_internal.policy_set_versions%ROWTYPE;
    set_owner_oid oid;
BEGIN
    IF (target).kind <> 'policy_set' THEN RETURN pgreact_api.remove_m28(target, preconditions); END IF;
    SELECT version.* INTO row_data
    FROM pgreact_internal.policy_set_versions version
    JOIN pgreact_internal.policy_sets set USING (policy_set_id)
    WHERE set.set_name = (target).name
      AND (($1).version IS NULL OR version.version = ($1).version)
    ORDER BY version.valid_from DESC LIMIT 1 FOR UPDATE;
    IF NOT FOUND THEN RETURN pgreact_internal.m29_status(target); END IF;
    SELECT set.owner_oid INTO set_owner_oid FROM pgreact_internal.policy_sets set
    WHERE set.policy_set_id = row_data.policy_set_id;
    IF NOT pg_has_role(session_user, set_owner_oid, 'USAGE') AND NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M29_OWNER: only the policy-set owner or operator may remove this target';
    END IF;
    UPDATE pgreact_internal.policy_set_versions SET state = 'REMOVED', removed_at = clock_timestamp()
    WHERE policy_set_version_id = row_data.policy_set_version_id;
    INSERT INTO pgreact_internal.policy_set_history(policy_set_version_id, event_kind, frontier, details)
    VALUES (row_data.policy_set_version_id,
        'REMOVED', (SELECT frontier FROM pgreact_internal.clock_frontier WHERE singleton), '{}');
    RETURN pgreact_internal.m29_envelope('remove', row_data.normalized, 'removed',
        jsonb_build_object('read_only', false, 'policy_set_version_id', row_data.policy_set_version_id));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.remove_m30(target pgreact_api.target, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.policy_set_versions%ROWTYPE;
    owner_id oid;
BEGIN
    IF (target).kind <> 'policy_set' THEN
        RETURN pgreact_api.remove_m29(target, preconditions);
    END IF;
    SELECT version.* INTO version_row
    FROM pgreact_internal.policy_set_versions version
    JOIN pgreact_internal.policy_sets set USING (policy_set_id)
    WHERE set.set_name = (target).name
      AND ((target).version IS NULL OR version.version = (target).version)
    ORDER BY version.valid_from DESC LIMIT 1 FOR UPDATE;
    IF NOT FOUND THEN
        RETURN pgreact_internal.m30_status(target);
    END IF;
    SELECT set.owner_oid INTO owner_id FROM pgreact_internal.policy_sets set
    WHERE set.policy_set_id = version_row.policy_set_id;
    IF NOT pg_has_role(session_user, owner_id, 'USAGE')
       AND NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M30_OWNER: only the policy-set owner or operator may remove this target';
    END IF;
    UPDATE pgreact_internal.policy_set_versions
    SET state = 'REMOVED', removed_at = clock_timestamp()
    WHERE policy_set_version_id = version_row.policy_set_version_id;
    INSERT INTO pgreact_internal.policy_set_history(
        policy_set_version_id, event_kind, frontier, details)
    VALUES (version_row.policy_set_version_id, 'REMOVED',
        (SELECT frontier FROM pgreact_internal.clock_frontier WHERE singleton),
        jsonb_build_object('foundation_only', true));
    RETURN pgreact_internal.m30_envelope('remove', version_row.normalized, 'removed',
        jsonb_build_object('read_only', false,
            'policy_set_version_id', version_row.policy_set_version_id,
            'migration_state', version_row.migration_state,
            'runtime_state', 'FOUNDATION_ONLY'));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.remove_m31(target pgreact_api.target, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.policy_set_versions%ROWTYPE;
    owner_id oid;
    rule_version_id uuid;
    rule_row pgreact_internal.rule_versions%ROWTYPE;
    decision_program_id uuid;
    member_row record;
    result jsonb;
BEGIN
    PERFORM pg_advisory_xact_lock(5788046901200000);
    PERFORM pg_advisory_xact_lock(5788046901200004);
    IF (target).kind <> 'policy_set' THEN
        IF (target).kind = 'rule' THEN
            SELECT delegated_id INTO rule_version_id FROM pgreact_internal.api_declarations
            WHERE kind = 'rule' AND object_name = (target).name AND state = 'DEPLOYED';
            IF (target).version IS NOT NULL
               AND (target).version NOT IN ('1', rule_version_id::text) THEN
                RETURN pgreact_api.remove_m30(target, preconditions);
            END IF;
            IF rule_version_id IS NULL THEN RETURN pgreact_api.remove_m30(target, preconditions); END IF;
            FOR member_row IN
                SELECT support.scope_support_id
                FROM pgreact_internal.policy_set_scope_supports support
                WHERE support.member_kind = 'rule'
                  AND support.member_name = (target).name
                  AND EXISTS (
                      SELECT 1
                      FROM pgreact_internal.policy_set_members member
                      WHERE member.policy_set_version_id = support.policy_set_version_id
                        AND member.member_kind = 'rule'
                        AND member.member_name = support.member_name
                        AND member.member_version IN ('1', rule_version_id::text)
                        AND member.scope_mode = 'POLICY_SET_REQUIRED')
            LOOP
                PERFORM pgreact_internal.m31_remove_support(
                    member_row.scope_support_id, 'rule_removed');
            END LOOP;
            PERFORM pgreact.pause_rule(rule_version_id);
            PERFORM pgreact.remove_rule(rule_version_id);
        ELSIF (target).kind = 'decision_program' THEN
            SELECT program_id, owner_oid INTO decision_program_id, owner_id
            FROM pgreact_internal.decision_programs
            WHERE program_name = (target).name AND state <> 'REMOVED'
            FOR UPDATE;
            IF decision_program_id IS NULL THEN
                RETURN pgreact_api.remove_m30(target, preconditions);
            END IF;
            IF NOT pg_has_role(session_user, owner_id, 'USAGE')
               AND NOT pgreact_internal.is_operator_admin() THEN
                RAISE EXCEPTION 'M31_OWNER: only the decision-program owner or operator may remove this target';
            END IF;
            PERFORM pgreact_api.pause_decision_program((target).name);
            PERFORM pgreact_api.remove_decision_program((target).name);
            FOR member_row IN
                SELECT support.scope_support_id
                FROM pgreact_internal.policy_set_scope_supports support
                WHERE support.member_kind = 'decision_program'
                  AND support.member_name = (target).name
                  AND EXISTS (
                      SELECT 1
                      FROM pgreact_internal.policy_set_members member
                      JOIN pgreact_internal.decision_program_versions version
                        ON version.program_id = decision_program_id
                       AND version.state = 'DEPLOYED'
                      WHERE member.policy_set_version_id = support.policy_set_version_id
                        AND member.member_kind = 'decision_program'
                        AND member.member_name = support.member_name
                        AND member.member_version IN (version.version_id::text,
                                                       version.version_no::text)
                        AND member.scope_mode = 'POLICY_SET_REQUIRED')
            LOOP
                PERFORM pgreact_internal.m31_remove_support(
                    member_row.scope_support_id, 'decision_program_removed');
            END LOOP;
            IF decision_program_id IS NOT NULL THEN
                DELETE FROM pgreact_internal.decision_work
                WHERE program_id = decision_program_id;
            END IF;
        ELSE
            RAISE EXCEPTION 'M31_UNSUPPORTED_KIND: generic removal has no authoritative adapter for %',
                (target).kind;
        END IF;
        RETURN pgreact_api.remove_m30(target, preconditions);
    END IF;
    SELECT version.* INTO version_row
    FROM pgreact_internal.policy_set_versions version
    JOIN pgreact_internal.policy_sets set USING (policy_set_id)
    WHERE set.set_name = (target).name
      AND (($1).version IS NULL OR version.version = ($1).version)
    ORDER BY version.valid_from DESC LIMIT 1 FOR UPDATE;
    IF NOT FOUND THEN RETURN pgreact_internal.m31_policy_status(target); END IF;
    SELECT set.owner_oid INTO owner_id FROM pgreact_internal.policy_sets set
    WHERE set.policy_set_id = version_row.policy_set_id;
    IF NOT pg_has_role(session_user, owner_id, 'USAGE')
       AND NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M31_OWNER: only the policy-set owner or operator may remove this target';
    END IF;
    UPDATE pgreact_internal.policy_set_versions
    SET state = 'REMOVED', removed_at = clock_timestamp()
    WHERE policy_set_version_id = version_row.policy_set_version_id;
    FOR member_row IN DELETE FROM pgreact_internal.policy_set_scope_supports
        WHERE policy_set_version_id = version_row.policy_set_version_id RETURNING * LOOP
        INSERT INTO pgreact_internal.policy_set_scope_support_history(
            scope_support_id, policy_set_version_id, member_kind, member_name,
            member_version, match_identity, subject_identity, event_kind,
            complete_frontier, details)
        VALUES (member_row.scope_support_id, member_row.policy_set_version_id,
                member_row.member_kind, member_row.member_name, member_row.member_version,
                member_row.match_identity, member_row.subject_identity, 'REMOVED',
                member_row.complete_frontier, jsonb_build_object('reason', 'set_removed'));
    END LOOP;
    UPDATE pgreact_internal.decision_work work
    SET claimable = state.state = 'WINNER' AND EXISTS (
            SELECT 1
            FROM pgreact_internal.policy_set_scope_supports support
            JOIN pgreact_internal.decision_programs program
              ON program.program_name = support.member_name
             AND support.member_kind = 'decision_program'
            WHERE program.program_id = state.program_id
              AND support.activation_id = state.activation_id
              AND NOT EXISTS (
                  SELECT 1 FROM pgreact_internal.policy_set_runtime_barriers barrier
                  WHERE barrier.policy_set_version_id = support.policy_set_version_id
                    AND barrier.cleared_at IS NULL)),
        updated_at = clock_timestamp()
    FROM pgreact_internal.decision_subject_state state
    WHERE work.program_id = state.program_id AND work.subject_key = state.subject_key;
    INSERT INTO pgreact_internal.policy_set_history(
        policy_set_version_id, event_kind, frontier, details)
    VALUES (version_row.policy_set_version_id, 'REMOVED',
            (SELECT frontier FROM pgreact_internal.clock_frontier WHERE singleton),
            jsonb_build_object('runtime_state', 'AUTHORITATIVE'));
    result := pgreact_internal.m30_envelope('remove', version_row.normalized, 'removed',
        jsonb_build_object('read_only', false,
                           'policy_set_version_id', version_row.policy_set_version_id,
                           'runtime_state', 'AUTHORITATIVE'));
    RETURN result;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.remove_shared_condition(condition_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    condition_row pgreact_internal.shared_conditions%ROWTYPE;
    version_row pgreact_internal.shared_condition_versions%ROWTYPE;
    consumers bigint;
BEGIN
    SELECT condition.* INTO STRICT condition_row
    FROM pgreact_internal.shared_conditions condition
    WHERE condition.condition_name = remove_shared_condition.condition_name FOR UPDATE;
    IF condition_row.owner_oid <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RAISE EXCEPTION 'M20_CONDITION_OWNER: % is not owned by %', condition_name, session_user;
    END IF;
    SELECT * INTO STRICT version_row FROM pgreact_internal.shared_condition_versions
    WHERE condition_id = condition_row.condition_id AND state = 'ACTIVE' FOR UPDATE;
    PERFORM pgreact_internal.refresh_shared_condition_consumers(version_row.condition_version_id);
    SELECT count(*) INTO consumers FROM pgreact_internal.shared_condition_consumers
    WHERE condition_version_id = version_row.condition_version_id;
    IF consumers > 0 THEN
        RAISE EXCEPTION 'M20_CONDITION_IN_USE: % has % active consumers', condition_name, consumers
            USING HINT = 'Remove or replace consumers before removing the shared condition.';
    END IF;
    PERFORM pgreact_api.remove_program(
        '__pgreact.condition.' || condition_name, version_row.version);
    EXECUTE format('DROP VIEW %s', condition_name::regclass);
    DELETE FROM pgreact_internal.keyed_derived_relations
    WHERE relation_version_id = version_row.relation_version_id;
    UPDATE pgreact_internal.derived_relation_versions
    SET state = 'REMOVED'
    WHERE relation_version_id = version_row.relation_version_id;
    UPDATE pgreact_internal.shared_condition_versions
    SET state = 'REMOVED'
    WHERE condition_version_id = version_row.condition_version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.remove_temporal_rule(target_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_id uuid;
BEGIN
    SELECT version.rule_version_id INTO STRICT version_id
    FROM pgreact_internal.rules rule JOIN pgreact_internal.rule_versions version USING (rule_id)
    JOIN pgreact_internal.temporal_rules spec USING (rule_version_id)
    WHERE rule.rule_name = target_name AND version.state <> 'REMOVED'
    ORDER BY version.created_at DESC LIMIT 1;
    PERFORM pgreact.pause_rule(version_id);
    DELETE FROM pgreact_internal.temporal_history WHERE rule_version_id = version_id;
    DELETE FROM pgreact_internal.temporal_state WHERE rule_version_id = version_id;
    DELETE FROM pgreact_internal.temporal_rules WHERE rule_version_id = version_id;
    PERFORM pgreact.remove_rule(version_id);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.replace_immediate_rule(rule_name text, condition regclass, semantic_key name)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE target_version uuid;
    prior_version uuid;
    diagnostic record;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_immediate_rule(condition, semantic_key) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M19_IMMEDIATE_INVALID: % for %: %', diagnostic.code,
            diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    SELECT version.rule_version_id INTO prior_version
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    WHERE rule.rule_name = replace_immediate_rule.rule_name
      AND version.state IN ('ACTIVE', 'PAUSED')
    ORDER BY version.created_at DESC
    LIMIT 1;
    IF prior_version IS NULL THEN
        RAISE EXCEPTION 'M19_IMMEDIATE_NOT_FOUND: %', rule_name;
    END IF;
    target_version := pgreact.replace_rule(
        prior_version, condition, ARRAY[semantic_key]::name[], NULL,
        'SEED_CURRENT', NULL, NULL, 'DRAIN_OLD');
    PERFORM pgreact_internal.enable_immediate_rule(target_version);
    RETURN target_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.request_watermark(program_name text, input_relation text, event_time_column name, target timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE program pgreact_internal.window_programs%ROWTYPE;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M17_WATERMARK_UNAUTHORIZED: % is not the configured operator', session_user
            USING ERRCODE = '42501';
    END IF;
    IF pg_is_in_recovery() THEN
        RAISE EXCEPTION 'M17_WATERMARK_STANDBY: watermark requests require a writable primary'
            USING ERRCODE = '25006';
    END IF;
    IF target IS NULL OR NOT isfinite(target) THEN
        RAISE EXCEPTION 'M17_WATERMARK_TARGET_INVALID: target must be finite and non-null'
            USING ERRCODE = '22008';
    END IF;
    IF cardinality(parse_ident(input_relation, true)) <> 2 THEN
        RAISE EXCEPTION 'M17_WATERMARK_INPUT_UNQUALIFIED: %', input_relation
            USING ERRCODE = '22023';
    END IF;
    SELECT * INTO program FROM pgreact_internal.window_programs
    WHERE window_programs.program_name = request_watermark.program_name
      AND active FOR UPDATE;
    IF NOT FOUND OR to_regclass(program.input_relation_name) IS DISTINCT FROM to_regclass(input_relation)
       OR program.event_time_column IS DISTINCT FROM request_watermark.event_time_column THEN
        RAISE EXCEPTION 'M17_WATERMARK_INPUT_UNKNOWN: %.%', input_relation, event_time_column
            USING ERRCODE = '22023';
    END IF;
    IF target < program.requested_watermark THEN
        RAISE EXCEPTION 'M17_WATERMARK_BACKWARD: target % precedes requested watermark %',
            target, program.requested_watermark USING ERRCODE = '22023';
    END IF;
    IF target = program.requested_watermark THEN RETURN; END IF;
    UPDATE pgreact_internal.window_programs SET requested_watermark = target
    WHERE program_version_id = program.program_version_id;
    INSERT INTO pgreact_internal.window_audits(program_version_id,operation,details)
    VALUES (program.program_version_id,'REQUEST_WATERMARK',
            jsonb_build_object('previous',program.requested_watermark,'target',target));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.restore_window_state(recovery_state jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    item jsonb;
    rule_id uuid;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M17_RECOVERY_UNAUTHORIZED: % is not the configured operator',session_user
            USING ERRCODE='42501';
    END IF;
    IF recovery_state ->> 'contract_version' <> '6'
       OR jsonb_typeof(recovery_state -> 'program') IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M17_RECOVERY_STATE_INVALID: expected contract version 6'
            USING ERRCODE='22023';
    END IF;
    SELECT * INTO STRICT program FROM pgreact_internal.window_programs
    WHERE window_programs.program_name=recovery_state #>> '{program,name}' AND active FOR UPDATE;
    IF program.program_version <> (recovery_state #>> '{program,version}')::integer THEN
        RAISE EXCEPTION 'M17_RECOVERY_STATE_INVALID: active program version differs'
            USING ERRCODE='22023';
    END IF;
    PERFORM pg_advisory_xact_lock(5788046901200000);
    DELETE FROM pgreact_internal.window_corrections WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_finalizations WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_lifecycle WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_diagnostics WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_audits WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_source_rows WHERE program_version_id=program.program_version_id;
    DELETE FROM pgreact_internal.window_identities WHERE program_version_id=program.program_version_id;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'source_rows') value LOOP
        INSERT INTO pgreact_internal.window_source_rows VALUES (
            program.program_version_id,item -> 'row_data',item -> 'public_window_key',
            (item ->> 'event_time')::timestamptz,(item ->> 'window_ordinal')::bigint,
            (item ->> 'occurrences')::bigint);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'identities') value LOOP
        INSERT INTO pgreact_internal.window_identities VALUES (
            program.program_version_id,item -> 'public_window_key',
            decode(item ->> 'canonical_window_key','hex'),(item ->> 'window_ordinal')::bigint,
            (item ->> 'window_start')::timestamptz,(item ->> 'window_end')::timestamptz,
            (item ->> 'lateness_boundary')::timestamptz,(item ->> 'final')::boolean);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'corrections') value LOOP
        SELECT rules.rule_version_id INTO STRICT rule_id FROM pgreact_internal.window_rules rules
        WHERE rules.program_version_id=program.program_version_id
          AND rules.rule_name=item ->> 'rule_name';
        INSERT INTO pgreact_internal.window_corrections (
            correction_order,correction_identity,program_version_id,program_name,program_version,
            rule_version_id,rule_name,rule_version,target_relation,public_window_key,
            public_group_key,window_ordinal,canonical_window_key,lower_frontier,
            before_value,after_value,before_truth,after_truth,support_generation,created_at)
        OVERRIDING SYSTEM VALUE VALUES (
            (item ->> 'correction_order')::bigint,item ->> 'correction_identity',
            program.program_version_id,program.program_name,program.program_version,rule_id,
            item ->> 'rule_name',(item ->> 'rule_version')::integer,item ->> 'target_relation',
            item -> 'public_window_key',item -> 'public_group_key',
            (item ->> 'window_ordinal')::bigint,decode(item ->> 'canonical_window_key','hex'),
            (item ->> 'lower_frontier')::bigint,item ->> 'before_value',item ->> 'after_value',
            (item ->> 'before_truth')::boolean,(item ->> 'after_truth')::boolean,
            (item ->> 'support_generation')::integer,(item ->> 'created_at')::timestamptz);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'finalizations') value LOOP
        INSERT INTO pgreact_internal.window_finalizations VALUES (
            item ->> 'finalization_identity',program.program_version_id,
            item -> 'public_window_key',decode(item ->> 'canonical_window_key','hex'),
            (item ->> 'lateness_boundary')::timestamptz,(item ->> 'finalized_at')::timestamptz);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'lifecycle') value LOOP
        INSERT INTO pgreact_internal.window_lifecycle (
            lifecycle_order,program_version_id,lower_frontier,public_window_key,
            canonical_window_key,rule_name,event_kind,support_generation)
        OVERRIDING SYSTEM VALUE VALUES (
            (item ->> 'lifecycle_order')::bigint,program.program_version_id,
            (item ->> 'lower_frontier')::bigint,item -> 'public_window_key',
            decode(item ->> 'canonical_window_key','hex'),item ->> 'rule_name',
            item ->> 'event_kind',(item ->> 'support_generation')::integer);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'diagnostics') value LOOP
        INSERT INTO pgreact_internal.window_diagnostics (
            diagnostic_order,contract_version,code,severity,object_identity,sqlstate,
            message,hint,details,program_version_id,created_at)
        OVERRIDING SYSTEM VALUE VALUES (
            (item ->> 'diagnostic_order')::bigint,(item ->> 'contract_version')::integer,
            item ->> 'code',item ->> 'severity',item ->> 'object_identity',item ->> 'sqlstate',
            item ->> 'message',item ->> 'hint',item -> 'details',program.program_version_id,
            (item ->> 'created_at')::timestamptz);
    END LOOP;
    FOR item IN SELECT value FROM jsonb_array_elements(recovery_state -> 'audits') value LOOP
        INSERT INTO pgreact_internal.window_audits (
            audit_order,program_version_id,operation,actor,details,created_at)
        OVERRIDING SYSTEM VALUE VALUES (
            (item ->> 'audit_order')::bigint,program.program_version_id,item ->> 'operation',
            (item ->> 'actor')::name,item -> 'details',(item ->> 'created_at')::timestamptz);
    END LOOP;
    UPDATE pgreact_internal.window_programs SET
        lower_frontier=(recovery_state #>> '{program,lower_frontier}')::bigint,
        observed_frontier=(recovery_state #>> '{program,observed_frontier}')::bigint,
        requested_watermark=(recovery_state #>> '{program,requested_watermark}')::timestamptz,
        complete_watermark=(recovery_state #>> '{program,complete_watermark}')::timestamptz,
        history_floor=(recovery_state #>> '{program,history_floor}')::timestamptz,
        barrier=(recovery_state #>> '{program,barrier}')::text,
        last_source_fingerprint=decode(recovery_state #>> '{program,source_fingerprint}','hex'),
        last_observed_fingerprint=decode(recovery_state #>> '{program,observed_fingerprint}','hex')
    WHERE program_version_id=program.program_version_id;
    UPDATE pgreact_internal.derivation_program_versions
    SET frontier=(recovery_state #>> '{program,engine_frontier}')::bigint
    WHERE program_version_id=program.program_version_id;
    PERFORM setval(pg_get_serial_sequence('pgreact_internal.window_corrections','correction_order'),
        COALESCE((SELECT max(correction_order) FROM pgreact_internal.window_corrections),1),true);
    PERFORM setval(pg_get_serial_sequence('pgreact_internal.window_lifecycle','lifecycle_order'),
        COALESCE((SELECT max(lifecycle_order) FROM pgreact_internal.window_lifecycle),1),true);
    PERFORM setval(pg_get_serial_sequence('pgreact_internal.window_diagnostics','diagnostic_order'),
        COALESCE((SELECT max(diagnostic_order) FROM pgreact_internal.window_diagnostics),1),true);
    PERFORM setval(pg_get_serial_sequence('pgreact_internal.window_audits','audit_order'),
        COALESCE((SELECT max(audit_order) FROM pgreact_internal.window_audits),1),true);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.resume_rule(name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_id uuid;
BEGIN
    SELECT version.rule_version_id INTO version_id
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    WHERE rule.rule_name = resume_rule.name AND version.state = 'PAUSED'
    ORDER BY version.created_at DESC LIMIT 1;
    IF version_id IS NULL THEN RAISE EXCEPTION 'M12_RULE_NOT_PAUSED: %', name; END IF;
    PERFORM pgreact.resume_rule(version_id);
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.deadline_rules
        WHERE rule_version_id = version_id
    ) THEN
        PERFORM pgreact_internal.reconcile_deadline_rule(version_id);
    END IF;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.retention_apply_m21(requested_cutoff timestamp with time zone, batch_size integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE policy_row record; effective_cutoff timestamptz; new_batch_id uuid; family_name text;
    removed bigint; total_removed bigint := 0; counts jsonb := '{}'::jsonb; preview jsonb;
    remaining bigint; batch_state text;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN RAISE EXCEPTION 'M21_RETENTION_FORBIDDEN: operator role required'; END IF;
    IF requested_cutoff >= clock_timestamp() THEN RAISE EXCEPTION 'M21_RETENTION_CUTOFF: cutoff must be in the past'; END IF;
    IF batch_size NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'M21_RETENTION_BATCH_SIZE: must be between 1 and 10000'; END IF;
    PERFORM pg_advisory_xact_lock(5788046901200021);
    SELECT * INTO STRICT policy_row FROM pgreact_internal.retention_policies WHERE singleton;
    IF NOT policy_row.enabled THEN RAISE EXCEPTION 'M21_RETENTION_DISABLED: enable a policy before apply'; END IF;
    effective_cutoff := greatest(requested_cutoff, clock_timestamp() - GREATEST(
        policy_row.full_detail_horizon, policy_row.minimum_audit_horizon,
        policy_row.replay_horizon, policy_row.rollback_horizon,
        policy_row.deduplication_horizon, policy_row.explanation_horizon,
        policy_row.reconciliation_horizon, policy_row.recovery_horizon));
    preview := pgreact_api.retention_preview(requested_cutoff, batch_size);
    IF (preview #>> '{totals,eligible_rows}')::bigint = 0 THEN
        RETURN preview || jsonb_build_object('outcome','NOOP','batch_id',NULL);
    END IF;
    new_batch_id := gen_random_uuid();
    INSERT INTO pgreact_internal.retention_batches(
        batch_id,policy_version,requested_cutoff,effective_cutoff,state,protected_reasons)
    VALUES(new_batch_id,policy_row.policy_version,requested_cutoff,effective_cutoff,'RUNNING',
        COALESCE((SELECT jsonb_object_agg(item.value ->> 'family', item.value -> 'blocking_reasons')
                  FROM jsonb_array_elements(preview -> 'families') item), '{}'::jsonb));
    -- ponytail: one database-wide retention lock; use per-family locks if maintenance throughput matters.
    BEGIN
        FOREACH family_name IN ARRAY ARRAY[
            'runtime_events','executions','derived_support_inputs','negative_dependency_evidence',
            'aggregate_dependency_evidence','derived_supports','derived_repair_diagnostics',
            'derived_reconciliations','derivation_program_repair_diagnostics','derivation_program_iterations',
            'derivation_program_runs','window_corrections','window_diagnostics','window_audits',
            'clock_history','reconciliation_audit','metadata_rebuild_audits','agenda','lifecycle_events'] LOOP
            removed := pgreact_internal.retention_apply_family(family_name,effective_cutoff,batch_size,
                policy_row.policy_version,new_batch_id);
            IF removed > 0 THEN total_removed := total_removed + removed; END IF;
            counts := counts || jsonb_build_object(family_name, removed);
        END LOOP;
        SELECT COALESCE(sum(eligible_rows),0) INTO remaining
        FROM pgreact_internal.retention_preview_data(effective_cutoff,batch_size);
        batch_state := CASE WHEN remaining = 0 THEN 'COMPLETED' ELSE 'PARTIAL' END;
        UPDATE pgreact_internal.retention_batches SET state=batch_state, family_counts=counts,
            finished_at=clock_timestamp() WHERE retention_batches.batch_id=new_batch_id;
        RETURN preview || jsonb_build_object('outcome',lower(batch_state),'batch_id',new_batch_id,
            'removed_rows',total_removed,'family_counts',counts,'remaining_eligible_rows',remaining);
    EXCEPTION WHEN OTHERS THEN
        UPDATE pgreact_internal.retention_batches SET state='FAILED', family_counts=counts,
            finished_at=clock_timestamp(), error=jsonb_build_object('sqlstate',SQLSTATE,'message',SQLERRM)
        WHERE retention_batches.batch_id=new_batch_id;
        RETURN jsonb_build_object('contract_version',9,'outcome','failed','batch_id',new_batch_id,
            'family_counts',counts,'error',jsonb_build_object('sqlstate',SQLSTATE,'message',SQLERRM));
    END;
END
$function$

