            'removed_rows', total_removed, 'family_counts', counts,
            'remaining_eligible_rows', remaining);
    EXCEPTION WHEN OTHERS THEN
        UPDATE pgreact_internal.retention_batches SET state = 'FAILED', family_counts = counts,
            finished_at = clock_timestamp(), error = jsonb_build_object('sqlstate', SQLSTATE, 'message', SQLERRM)
        WHERE retention_batches.batch_id = new_batch_id;
        RETURN jsonb_build_object('contract_version', 9, 'outcome', 'failed',
            'batch_id', new_batch_id, 'family_counts', counts,
            'error', jsonb_build_object('sqlstate', SQLSTATE, 'message', SQLERRM));
    END;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.run_m28(target pgreact_api.target, sampled_time timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
BEGIN
    IF (target).kind = 'rule' THEN
        IF EXISTS (
            SELECT 1 FROM pgreact_internal.api_declarations
            WHERE kind = (target).kind AND object_name = (target).name
              AND delegated_id IS NOT NULL AND state = 'DEPLOYED') THEN
            PERFORM pgreact_api.run_rule((target).name);
        END IF;
        result := pgreact_internal.m28_status(target);
    ELSE
        result := pgreact_api.run(sampled_time);
    END IF;
    RETURN result || jsonb_build_object('operation', 'run', 'sampled_time', sampled_time);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.run_m30_global(sampled_time timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
    program_row record;
BEGIN
    result := pgreact_internal.run_m25(sampled_time);
    FOR program_row IN SELECT program_id FROM pgreact_internal.decision_programs WHERE state = 'ACTIVE' LOOP
        PERFORM pgreact_internal.refresh_decision_program(program_row.program_id, sampled_time);
    END LOOP;
    RETURN jsonb_set(result || jsonb_build_object(
        'decision_programs', pgreact_api.decision_status(),
        'decision_analyses', pgreact_api.decision_analysis_status()),
        '{contract_version}', '15'::jsonb, true);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.semantic_diff_m43(proposed pgreact_api.declaration, deployed pgreact_api.target, options jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE target_kind text := (deployed).kind;
    target_name text := (deployed).name;
    target_version text := (deployed).version;
    target_identity jsonb;
    current_normalized jsonb;
    proposed_normalized jsonb;
    current_digest text;
    proposed_digest text;
    current_owner oid;
    current_delegate uuid;
    current_source_oid oid;
    current_source_digest text;
    current_subject_keys name[];
    current_rule record;
    validation jsonb;
    prepared pgreact_api.declaration;
    paths text[];
    field_path text;
    field_name text;
    field_kind text;
    current_spec jsonb;
    proposed_spec jsonb;
    current_value jsonb;
    proposed_value jsonb;
    current_present boolean;
    proposed_present boolean;
    differences jsonb := '[]'::jsonb;
    opaque jsonb := '[]'::jsonb;
    findings jsonb := '[]'::jsonb;
    reached_limits jsonb := '[]'::jsonb;
    current_typed jsonb;
    proposed_typed jsonb;
    opaque_record jsonb;
    live_digest text;
    action_row record;
    source_oid oid;
    object_oid oid;
    before_checksum text;
    after_checksum text;
    started_at timestamptz := clock_timestamp();
    field_count integer;
    fields_compared integer := 0;
    collection_members bigint := 0;
    difference_count integer := 0;
    opaque_count integer := 0;
    max_declaration_bytes integer := 65536;
    max_fields integer := 128;
    max_collection_members integer := 256;
    max_differences integer := 128;
    max_opaque_records integer := 64;
    max_nesting_depth integer := 8;
    max_payload_bytes integer := 1048576;
    complete boolean := true;
    unsupported boolean := false;
    option_name text;
    option_value integer;
    cost jsonb;
BEGIN
    IF options IS NULL OR jsonb_typeof(options) IS DISTINCT FROM 'object' THEN
        RETURN pgreact_internal.m43_result(
            'invalid', NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), '{}'::jsonb,
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_OPTIONS_INVALID', 'ERROR', 'options must be a JSON object',
                'Pass bounded JSON options or omit the argument.')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    FOREACH option_name IN ARRAY ARRAY[
        'max_declaration_bytes', 'max_fields', 'max_collection_members',
        'max_differences', 'max_opaque_records', 'max_nesting_depth',
        'max_payload_bytes'] LOOP
        IF options ? option_name THEN
            IF jsonb_typeof(options -> option_name) IS DISTINCT FROM 'number' THEN
                findings := findings || jsonb_build_array(pgreact_internal.m43_finding(
                    'M43_OPTIONS_INVALID', 'ERROR', option_name || ' must be an integer',
                    'Use a positive integer within the published bound.'));
            ELSE
                BEGIN
                    option_value := (options ->> option_name)::integer;
                    IF option_value < 1
                       OR (option_name = 'max_declaration_bytes' AND option_value > 1048576)
                       OR (option_name = 'max_fields' AND option_value > 1024)
                       OR (option_name = 'max_collection_members' AND option_value > 10000)
                       OR (option_name = 'max_differences' AND option_value > 1024)
                       OR (option_name = 'max_opaque_records' AND option_value > 256)
                       OR (option_name = 'max_nesting_depth' AND option_value > 32)
                       OR (option_name = 'max_payload_bytes' AND option_value > 16777216) THEN
                        RAISE EXCEPTION 'outside published bound';
                    END IF;
                    CASE option_name
                        WHEN 'max_declaration_bytes' THEN max_declaration_bytes := option_value;
                        WHEN 'max_fields' THEN max_fields := option_value;
                        WHEN 'max_collection_members' THEN max_collection_members := option_value;
                        WHEN 'max_differences' THEN max_differences := option_value;
                        WHEN 'max_opaque_records' THEN max_opaque_records := option_value;
                        WHEN 'max_nesting_depth' THEN max_nesting_depth := option_value;
                        WHEN 'max_payload_bytes' THEN max_payload_bytes := option_value;
                    END CASE;
                EXCEPTION WHEN OTHERS THEN
                    findings := findings || jsonb_build_array(pgreact_internal.m43_finding(
                        'M43_OPTIONS_INVALID', 'ERROR', option_name || ' is outside the supported integer range',
                        'Use a positive integer within the published bound.'));
                END;
            END IF;
        END IF;
    END LOOP;
    IF jsonb_array_length(findings) > 0 THEN
        RETURN pgreact_internal.m43_result(
            'invalid', NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), jsonb_build_object(
                'max_declaration_bytes', max_declaration_bytes, 'max_fields', max_fields,
                'max_collection_members', max_collection_members, 'max_differences', max_differences,
                'max_opaque_records', max_opaque_records, 'max_nesting_depth', max_nesting_depth,
                'max_payload_bytes', max_payload_bytes, 'reached', reached_limits), findings,
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    IF target_kind IS NULL OR target_name IS NULL OR deployed IS NULL THEN
        RETURN pgreact_internal.m43_result(
            'unavailable', NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), '{}'::jsonb,
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_TARGET_UNAVAILABLE', 'WARNING', 'the deployed target is unavailable',
                'Check the public target name, kind, version, and your granted access.')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;

    IF target_kind = 'policy_set' THEN
        SELECT version.normalized, encode(version.declaration_digest, 'hex'), set.owner_oid,
               version.policy_set_version_id, version.applicability_source_oid,
               version.applicability_source_definition_digest, version.subject_keys,
               version.version
        INTO current_normalized, current_digest, current_owner, current_delegate,
             current_source_oid, current_source_digest, current_subject_keys, target_version
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE set.set_name = target_name
          AND version.state = 'DEPLOYED'
          AND (target_version IS NULL OR version.version = target_version)
        ORDER BY version.valid_from DESC, version.created_at DESC
        LIMIT 1;
    ELSE
        SELECT row_data.normalized, encode(row_data.declaration_digest, 'hex'),
               row_data.owner_oid, row_data.delegated_id
        INTO current_normalized, current_digest, current_owner, current_delegate
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
        IF current_normalized IS NOT NULL THEN target_version := COALESCE(target_version, '1'); END IF;
    END IF;
    IF current_normalized IS NOT NULL AND target_kind = 'rule' THEN
        SELECT encode(version.source_definition_digest, 'hex'), version.rule_version_id
        INTO current_source_digest, current_delegate
        FROM pgreact_internal.rule_versions version
        JOIN pgreact_internal.rules rule USING (rule_id)
        WHERE version.rule_version_id = current_delegate
           OR (current_delegate IS NULL AND rule.rule_name = target_name)
        ORDER BY version.created_at DESC
        LIMIT 1;
    ELSIF current_normalized IS NOT NULL AND target_kind = 'decision_program' THEN
        SELECT encode(version.source_definition_digest, 'hex'), version.version_id
        INTO current_source_digest, current_delegate
        FROM pgreact_internal.decision_program_versions version
        JOIN pgreact_internal.decision_programs program USING (program_id)
        WHERE version.version_id = current_delegate
           OR (current_delegate IS NULL AND program.program_name = target_name)
        ORDER BY version.valid_from DESC, version.version_no DESC
        LIMIT 1;
    END IF;
    IF current_normalized IS NULL
       OR (target_kind <> 'policy_set' AND (deployed).version IS NOT NULL AND (deployed).version <> '1') THEN
        RETURN pgreact_internal.m43_result(
            'unavailable', NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), '{}'::jsonb,
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_TARGET_UNAVAILABLE', 'WARNING', 'the deployed target is unavailable',
                'Check the public target name, kind, version, and your granted access.')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    IF NOT pg_has_role(session_user, current_owner, 'USAGE')
       AND NOT pgreact_internal.is_operator_admin()
       AND NOT EXISTS (
           SELECT 1 FROM pgreact_internal.application_roles role_row
           WHERE role_row.role_kind = 'reader'
             AND pg_has_role(session_user, role_row.role_oid, 'member')) THEN
        RETURN pgreact_internal.m43_result(
            'unavailable', NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), '{}'::jsonb,
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_TARGET_UNAVAILABLE', 'WARNING', 'the deployed target is unavailable',
                'Check the public target name, kind, version, and your granted access.')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    target_identity := jsonb_build_object('kind', target_kind, 'name', target_name, 'version', target_version);
    IF target_kind NOT IN ('rule', 'decision_program', 'policy_set') THEN
        RETURN pgreact_internal.m43_result(
            'unsupported', target_identity, NULL, current_digest, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), '{}'::jsonb,
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_UNSUPPORTED_KIND', 'ERROR', 'this declaration kind has no M43 field inventory',
                'Use rule, decision_program, or policy_set.')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    IF proposed IS NULL THEN
        RETURN pgreact_internal.m43_result(
            'invalid', target_identity, NULL, current_digest, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), '{}'::jsonb,
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_INVALID_DECLARATION', 'ERROR', 'the proposed declaration is required',
                'Build it with pgreact_api.declaration().')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    IF (proposed).kind IS DISTINCT FROM target_kind THEN
        RETURN pgreact_internal.m43_result(
            'invalid', target_identity, NULL, current_digest, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), '{}'::jsonb,
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_KIND_MISMATCH', 'ERROR', 'proposed and deployed kinds must match',
                'Use the deployed target kind in the proposed declaration.')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    IF (proposed).name IS DISTINCT FROM target_name THEN
        RETURN pgreact_internal.m43_result(
            'invalid', target_identity, NULL, current_digest, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), '{}'::jsonb,
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_NAME_MISMATCH', 'ERROR', 'proposed and deployed names must match',
                'Use the deployed target name in the proposed declaration.')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    prepared := pgreact_internal.m43_prepare_declaration(proposed);
    validation := pgreact_api.validate(prepared);
    proposed_normalized := validation -> 'evidence' -> 'normalized_declaration';
    IF proposed_normalized IS NULL THEN proposed_normalized := validation -> 'normalized'; END IF;
    IF validation ->> 'state' = 'attention'
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(validation -> 'findings', '[]'::jsonb)) f
                  WHERE f ->> 'severity' = 'ERROR')
       OR proposed_normalized IS NULL THEN
        findings := jsonb_build_array(pgreact_internal.m43_finding(
            'M43_INVALID_DECLARATION', 'ERROR', 'the proposed declaration is not valid',
            'Correct the declaration using the existing validation findings.'))
            || COALESCE(validation -> 'findings', '[]'::jsonb);
        RETURN pgreact_internal.m43_result(
            'invalid', target_identity, NULL, current_digest, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), '{}'::jsonb, findings,
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    proposed_digest := pgreact_internal.m43_declaration_digest(proposed_normalized);
    IF pgreact_internal.m43_json_depth(current_normalized) > max_nesting_depth
       OR pgreact_internal.m43_json_depth(proposed_normalized) > max_nesting_depth THEN
        RETURN pgreact_internal.m43_result(
            'partial', target_identity, proposed_digest, current_digest, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), jsonb_build_object(
                'max_nesting_depth', max_nesting_depth,
                'reached', jsonb_build_array('max_nesting_depth')),
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_LIMIT', 'WARNING', 'a declaration exceeded the nesting-depth limit',
                'Flatten the declaration or raise max_nesting_depth within the published ceiling.')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    IF length(convert_to(proposed_normalized::text, 'UTF8')) > max_declaration_bytes
       OR length(convert_to(current_normalized::text, 'UTF8')) > max_declaration_bytes THEN
        RETURN pgreact_internal.m43_result(
            'partial', target_identity, proposed_digest, current_digest, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), jsonb_build_object(
                'max_declaration_bytes', max_declaration_bytes,
                'reached', jsonb_build_array('max_declaration_bytes')),
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_LIMIT', 'WARNING', 'a declaration exceeded the byte limit',
                'Reduce the declaration size or raise max_declaration_bytes within the published ceiling.')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    paths := pgreact_internal.m43_field_paths(target_kind, current_normalized, proposed_normalized);
    field_count := cardinality(paths);
    FOREACH field_path IN ARRAY paths LOOP
        field_kind := pgreact_internal.m43_field_kind(target_kind, field_path);
        IF field_kind IS NULL THEN
            unsupported := true;
            findings := findings || jsonb_build_array(pgreact_internal.m43_finding(
                'M43_UNSUPPORTED_FIELD', 'ERROR', 'the declaration contains an unsupported modeled field',
                'Use only fields in pgreact_internal.m43_field_inventory().',
                jsonb_build_object('field_path', field_path)));
        END IF;
    END LOOP;
    IF unsupported THEN
        RETURN pgreact_internal.m43_result(
            'unsupported', target_identity, proposed_digest, current_digest, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false, 'fields_considered', field_count),
            jsonb_build_object('max_fields', max_fields, 'reached', reached_limits), findings,
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    FOREACH field_path IN ARRAY paths LOOP
        field_kind := pgreact_internal.m43_field_kind(target_kind, field_path);
        IF field_path LIKE 'spec.applicability.%' THEN
            field_name := substring(field_path FROM length('spec.applicability.') + 1);
            current_spec := COALESCE(current_normalized -> 'spec' -> 'applicability', '{}'::jsonb);
            proposed_spec := COALESCE(proposed_normalized -> 'spec' -> 'applicability', '{}'::jsonb);
        ELSE
            field_name := substring(field_path FROM length('spec.') + 1);
            current_spec := COALESCE(current_normalized -> 'spec', '{}'::jsonb);
            proposed_spec := COALESCE(proposed_normalized -> 'spec', '{}'::jsonb);
        END IF;
        IF field_kind IN ('relation_identity', 'function_identity') THEN
            IF current_spec ? field_name
               AND NOT pgreact_internal.m43_object_access(field_kind, current_spec ->> field_name) THEN
                RETURN pgreact_internal.m43_result(
                    'unavailable', NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb,
                    jsonb_build_object('complete', false), '{}'::jsonb,
                    jsonb_build_array(pgreact_internal.m43_finding(
                        'M43_TARGET_UNAVAILABLE', 'WARNING', 'the deployed target is unavailable',
                        'Check the public target name, kind, version, and your granted access.')),
                    jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                                       extract(epoch FROM clock_timestamp() - started_at) * 1000));
            END IF;
            IF proposed_spec ? field_name
               AND NOT pgreact_internal.m43_object_access(field_kind, proposed_spec ->> field_name) THEN
                RETURN pgreact_internal.m43_result(
                    'unavailable', NULL, NULL, NULL, '[]'::jsonb, '[]'::jsonb,
                    jsonb_build_object('complete', false), '{}'::jsonb,
                    jsonb_build_array(pgreact_internal.m43_finding(
                        'M43_TARGET_UNAVAILABLE', 'WARNING', 'the deployed target is unavailable',
                        'Check the public target name, kind, version, and your granted access.')),
                    jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                                       extract(epoch FROM clock_timestamp() - started_at) * 1000));
            END IF;
        END IF;
    END LOOP;
    IF field_count > max_fields THEN
        complete := false;
        reached_limits := reached_limits || jsonb_build_array('max_fields');
        findings := findings || jsonb_build_array(pgreact_internal.m43_finding(
            'M43_LIMIT', 'WARNING', 'the field limit was reached',
            'Raise max_fields within the published ceiling or split the review.'));
    END IF;
    before_checksum := pgreact_internal.m34_authoritative_checksum();
    FOREACH field_path IN ARRAY paths LOOP
        EXIT WHEN fields_compared >= max_fields;
        field_kind := pgreact_internal.m43_field_kind(target_kind, field_path);
        IF field_path LIKE 'spec.applicability.%' THEN
            field_name := substring(field_path FROM length('spec.applicability.') + 1);
            current_spec := COALESCE(current_normalized -> 'spec' -> 'applicability', '{}'::jsonb);
            proposed_spec := COALESCE(proposed_normalized -> 'spec' -> 'applicability', '{}'::jsonb);
        ELSE
            field_name := substring(field_path FROM length('spec.') + 1);
            current_spec := COALESCE(current_normalized -> 'spec', '{}'::jsonb);
            proposed_spec := COALESCE(proposed_normalized -> 'spec', '{}'::jsonb);
        END IF;
        current_present := current_spec ? field_name;
        proposed_present := proposed_spec ? field_name;
        current_value := current_spec -> field_name;
        proposed_value := proposed_spec -> field_name;
        fields_compared := fields_compared + 1;
        IF jsonb_typeof(current_value) = 'array' THEN
            collection_members := collection_members + jsonb_array_length(current_value);
            IF jsonb_array_length(current_value) > max_collection_members THEN
                complete := false;
                reached_limits := reached_limits || jsonb_build_array('max_collection_members');
            END IF;
        END IF;
        IF jsonb_typeof(proposed_value) = 'array' THEN
            collection_members := collection_members + jsonb_array_length(proposed_value);
            IF jsonb_array_length(proposed_value) > max_collection_members THEN
                complete := false;
                reached_limits := reached_limits || jsonb_build_array('max_collection_members');
            END IF;
        END IF;
        IF current_present AND proposed_present
           AND current_value IS NOT DISTINCT FROM proposed_value THEN
            IF field_kind IN ('relation_identity', 'function_identity') THEN
                opaque_record := pgreact_internal.m43_opaque_record(
                    target_kind, field_path, current_value #>> '{}',
                    current_source_digest, current_delegate, current_subject_keys);
                IF opaque_record IS NOT NULL AND opaque_count < max_opaque_records THEN
                    opaque := opaque || jsonb_build_array(opaque_record);
                    opaque_count := opaque_count + 1;
                    findings := findings || jsonb_build_array(pgreact_internal.m43_finding(
                        'M43_OPAQUE_CHANGE', 'WARNING', 'a stored public object definition changed',
                        'Review the public object outside pg-react; no business meaning is assigned.',
                        jsonb_build_object('field_path', field_path,
                                           'identity', current_value #>> '{}')));
                END IF;
            END IF;
            CONTINUE;
        END IF;
        IF difference_count >= max_differences THEN
            complete := false;
            reached_limits := reached_limits || jsonb_build_array('max_differences');
            CONTINUE;
        END IF;
        current_typed := pgreact_internal.m43_typed_value(
            field_kind, current_present,
            pgreact_internal.m43_limit_value(current_value, max_collection_members));
        proposed_typed := pgreact_internal.m43_typed_value(
            field_kind, proposed_present,
            pgreact_internal.m43_limit_value(proposed_value, max_collection_members));
        differences := differences || jsonb_build_array(jsonb_build_object(
            'field_path', field_path,
            'field_kind', field_kind,
            'change_kind', CASE WHEN NOT current_present THEN 'added'
                                WHEN NOT proposed_present THEN 'removed'
                                ELSE 'changed' END,
            'before', current_typed,
            'after', proposed_typed,
            'complete', NOT ((jsonb_typeof(current_value) = 'array'
                             AND jsonb_array_length(current_value) > max_collection_members)
                            OR (jsonb_typeof(proposed_value) = 'array'
                                AND jsonb_array_length(proposed_value) > max_collection_members))));
        difference_count := difference_count + 1;
        IF difference_count >= max_differences THEN complete := false; END IF;

    END LOOP;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(reached_limits) item
               WHERE item.value #>> '{}' = 'max_collection_members') THEN
        findings := findings || jsonb_build_array(pgreact_internal.m43_finding(
            'M43_LIMIT', 'WARNING', 'a collection limit was reached',
            'Raise max_collection_members within the published ceiling or split the review.'));
    END IF;
    IF opaque_count >= max_opaque_records THEN
        complete := false;
        reached_limits := reached_limits || jsonb_build_array('max_opaque_records');
    END IF;
    after_checksum := pgreact_internal.m34_authoritative_checksum();
    IF before_checksum IS DISTINCT FROM after_checksum THEN
        RETURN pgreact_internal.m43_result(
            'changed', target_identity, proposed_digest, current_digest, '[]'::jsonb, '[]'::jsonb,
            jsonb_build_object('complete', false), jsonb_build_object('reached', '[]'::jsonb),
            jsonb_build_array(pgreact_internal.m43_finding(
                'M43_CHANGED_STATE', 'WARNING', 'authoritative state changed during the review',
                'Run the same read-only review again.')),
            jsonb_build_object('fields_compared', 0, 'elapsed_ms',
                               extract(epoch FROM clock_timestamp() - started_at) * 1000));
    END IF;
    IF length(convert_to((differences || opaque)::text, 'UTF8')) > max_payload_bytes THEN
        complete := false;
        reached_limits := reached_limits || jsonb_build_array('max_payload_bytes');
        differences := '[]'::jsonb;
        opaque := '[]'::jsonb;
        findings := findings || jsonb_build_array(pgreact_internal.m43_finding(
            'M43_LIMIT', 'WARNING', 'the returned payload limit was reached',
            'Raise max_payload_bytes within the published ceiling or split the review.'));
    END IF;
    IF complete AND jsonb_array_length(differences) = 0 AND jsonb_array_length(opaque) = 0 THEN
        findings := findings || jsonb_build_array(pgreact_internal.m43_finding(
            'M43_NO_DIFFERENCE', 'INFO', 'the modeled declarations are semantically equal',
            'No deployment is required for this result.'));
    END IF;
    cost := jsonb_build_object(
        'fields_compared', fields_compared,
        'collection_members', collection_members,
        'differences_returned', jsonb_array_length(differences),
        'opaque_records', jsonb_array_length(opaque),
        'object_lookups', 0,
        'serialization_bytes', length(convert_to((current_normalized || proposed_normalized)::text, 'UTF8')),
        'hashing_bytes', length(convert_to((current_normalized || proposed_normalized || differences || opaque)::text, 'UTF8')),
        'elapsed_ms', extract(epoch FROM clock_timestamp() - started_at) * 1000,
        'memory_bytes', NULL,
        'temporary_storage_bytes', 0);
    RETURN pgreact_internal.m43_result(
        CASE WHEN complete THEN 'complete' ELSE 'partial' END,
        target_identity, proposed_digest, current_digest, differences, opaque,
        jsonb_build_object('complete', complete, 'fields_considered', field_count,
                           'fields_compared', fields_compared,
                           'differences_complete', complete OR difference_count < max_differences,
                           'opaque_complete', opaque_count < max_opaque_records),
        jsonb_build_object(
            'max_declaration_bytes', max_declaration_bytes,
            'max_fields', max_fields,
            'max_collection_members', max_collection_members,
            'max_differences', max_differences,
            'max_opaque_records', max_opaque_records,
            'max_nesting_depth', max_nesting_depth,
            'max_payload_bytes', max_payload_bytes,
            'reached', reached_limits),
        findings, cost);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.validate_immediate_program(definition jsonb)
 RETURNS TABLE(contract_version integer, code text, severity text, object_identity text, message text, hint text, details jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE diagnostic record;
    item jsonb;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact_api.validate_program(definition) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RETURN QUERY SELECT 7, diagnostic.code, diagnostic.severity,
            diagnostic.object_identity, diagnostic.message, diagnostic.hint,
            diagnostic.details;
        RETURN;
    END IF;
    IF jsonb_typeof(definition -> 'rules') IS DISTINCT FROM 'array'
       OR jsonb_array_length(definition -> 'rules') = 0 THEN
        RETURN QUERY SELECT 7, 'M19_PROGRAM_EMPTY', 'ERROR',
            COALESCE(definition ->> 'name', 'program'),
            'an immediate derivation program must contain at least one rule',
            'Provide one or more positive finite derivation rules.', '{}'::jsonb;
        RETURN;
    END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(definition -> 'rules') LOOP
        IF jsonb_array_length(COALESCE(item -> 'negative_inputs', '[]'::jsonb)) > 0 THEN
            RETURN QUERY SELECT 7, 'M19_NEGATION_UNSUPPORTED', 'ERROR', item ->> 'name',
                'immediate derivations are positive only',
                'Remove negative inputs or deploy the program in scheduled mode.', '{}'::jsonb;
            RETURN;
        END IF;
        IF item ? 'aggregate_input' THEN
            RETURN QUERY SELECT 7, 'M19_AGGREGATE_UNSUPPORTED', 'ERROR', item ->> 'name',
                'aggregates are outside the immediate derivation closure',
                'Keep aggregate rules scheduled.', '{}'::jsonb;
            RETURN;
        END IF;
        IF item ? 'window' OR item ? 'deadline' THEN
            RETURN QUERY SELECT 7, 'M19_TEMPORAL_UNSUPPORTED', 'ERROR', item ->> 'name',
                'temporal rules are outside the immediate derivation closure',
                'Keep window and deadline rules scheduled.', '{}'::jsonb;
            RETURN;
        END IF;
    END LOOP;
    IF (SELECT extversion FROM pg_extension WHERE extname = 'pg_trickle') IS DISTINCT FROM '0.81.0'
       OR current_setting('transaction_isolation') <> 'read committed'
       OR COALESCE(current_setting('pg_trickle.user_triggers', true), '') <> 'auto'
    THEN
        RETURN QUERY SELECT 7, 'M19_TRICKLE_CAPABILITY', 'ERROR', 'pg_trickle',
            'the pinned immediate-maintenance capability is unavailable',
            'Use PostgreSQL 18.3, pg_trickle 0.81.0, READ COMMITTED, and pg_trickle.user_triggers=auto.', '{}'::jsonb;
        RETURN;
    END IF;
    RETURN QUERY SELECT 7, 'OK', 'INFO', definition ->> 'name',
        'program is eligible for a finite positive immediate closure',
        'Call pgreact_api.deploy_immediate_program with the preview digest.',
        jsonb_build_object('maintenance_mode', 'IMMEDIATE', 'closure', 'finite acyclic positive',
                           'downstream_boundary', 'scheduled consumers remain asynchronous');
EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT 7, 'M19_PROGRAM_VALIDATION', 'ERROR',
        COALESCE(definition ->> 'name', 'program'), SQLERRM,
        'Correct the program or deploy it in scheduled mode.', '{}'::jsonb;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.validate_immediate_rule(condition regclass, semantic_key name)
 RETURNS TABLE(contract_version integer, code text, severity text, object_identity text, message text, hint text, details jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    diagnostic record;
    query_tree text;
    key_attno smallint;
    source_oid oid;
    source_count integer;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact.validate_rule(condition, ARRAY[semantic_key]::name[], NULL::regprocedure) diagnostics
    WHERE diagnostics.severity = 'ERROR'
    ORDER BY diagnostics.code, diagnostics.object_identity
    LIMIT 1;
    IF FOUND THEN
        RETURN QUERY SELECT 7, diagnostic.code, diagnostic.severity,
            diagnostic.object_identity, diagnostic.message, diagnostic.hint,
            diagnostic.details;
        RETURN;
    END IF;

    SELECT attnum INTO key_attno
    FROM pg_attribute
    WHERE attrelid = condition AND attname = semantic_key
      AND attnum > 0 AND NOT attisdropped;
    IF key_attno IS NULL OR NOT pgreact_internal.view_key_is_direct(condition, key_attno) THEN
        RETURN QUERY SELECT 7, 'M19_KEY_NOT_DIRECT', 'ERROR', condition::text,
            'immediate rules require one direct semantic key projected from the source table',
            'Project one stored bigint key unchanged from the source table.',
            jsonb_build_object('semantic_key', semantic_key);
        RETURN;
    END IF;

    query_tree := pgreact_internal.relation_query_tree(condition);
    IF query_tree ~ E':has(Aggs|WindowFuncs|Recursive|SubLinks)[[:space:]]+true'
       OR query_tree ~ E':jointype[[:space:]]+[0-9]'
    THEN
        RETURN QUERY SELECT 7, 'M19_QUERY_UNSUPPORTED', 'ERROR', condition::text,
            'immediate rules require a finite single-table positive query',
            'Use a direct SELECT from one base table; joins, aggregates, windows, recursion, and subqueries remain scheduled.',
            '{}'::jsonb;
        RETURN;
    END IF;

    WITH RECURSIVE dependencies(relid) AS (
        SELECT condition::oid
        UNION
        SELECT dependency.refobjid
        FROM dependencies parent
        JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relid
        JOIN pg_depend dependency
          ON dependency.classid = 'pg_rewrite'::regclass
         AND dependency.objid = rewrite.oid
         AND dependency.refclassid = 'pg_class'::regclass
         AND dependency.deptype = 'n'
    )
    SELECT count(DISTINCT relation.oid) FILTER (WHERE relation.relkind IN ('r', 'p')),
           min(relation.oid) FILTER (WHERE relation.relkind IN ('r', 'p'))
    INTO source_count, source_oid
    FROM dependencies
    JOIN pg_class relation ON relation.oid = dependencies.relid
    WHERE relation.oid <> condition;
    IF source_count <> 1 THEN
        RETURN QUERY SELECT 7, 'M19_SOURCE_SHAPE', 'ERROR', condition::text,
            'immediate rules require exactly one ordinary base-table source',
            'Keep this version scheduled or replace it with a single-table positive condition.',
            jsonb_build_object('base_table_count', source_count);
        RETURN;
    END IF;

    IF EXISTS (SELECT 1 FROM pg_class WHERE oid = source_oid
               AND (relrowsecurity OR relforcerowsecurity)) THEN
        RETURN QUERY SELECT 7, 'M19_RLS_UNSUPPORTED', 'ERROR', source_oid::regclass::text,
            'RLS-protected sources are outside the immediate capability matrix',
            'Use a non-RLS source or keep this version scheduled.', '{}'::jsonb;
        RETURN;
    END IF;
    IF NOT has_table_privilege(session_user, source_oid, 'TRIGGER') THEN
        RETURN QUERY SELECT 7, 'M19_SOURCE_TRIGGER_PRIVILEGE', 'ERROR', source_oid::regclass::text,
            'the immediate author must be able to maintain the source table with PostgreSQL triggers',
            'Grant TRIGGER on the source table or keep this version scheduled.', '{}'::jsonb;
        RETURN;
    END IF;
    IF (SELECT extversion FROM pg_extension WHERE extname = 'pg_trickle') IS DISTINCT FROM '0.81.0' THEN
        RETURN QUERY SELECT 7, 'M19_TRICKLE_CAPABILITY', 'ERROR', 'pg_trickle',
            'the pinned pg_trickle immediate-maintenance capability is unavailable',
            'Install pg_trickle 0.81.0 on the supported PostgreSQL 18.3 tuple.', '{}'::jsonb;
        RETURN;
    END IF;
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RETURN QUERY SELECT 7, 'M19_ISOLATION_UNSUPPORTED', 'ERROR', current_setting('transaction_isolation'),
            'immediate maintenance requires READ COMMITTED',
            'Run the source transaction at READ COMMITTED.', '{}'::jsonb;
        RETURN;
    END IF;
    IF COALESCE(current_setting('pg_trickle.user_triggers', true), '') <> 'auto' THEN
        RETURN QUERY SELECT 7, 'M19_TRIGGER_CAPABILITY', 'ERROR', 'pg_trickle.user_triggers',
            'the pinned immediate-maintenance trigger capability is not enabled',
            'Set pg_trickle.user_triggers=auto and restart PostgreSQL.', '{}'::jsonb;
        RETURN;
    END IF;

    RETURN QUERY SELECT 7, 'OK', 'INFO', condition::text,
        'constraint rule is eligible for PostgreSQL-native immediate maintenance',
        'Call pgreact_api.author_immediate_rule to opt this version in.',
        jsonb_build_object('maintenance_mode', 'IMMEDIATE', 'source_table', source_oid::regclass::text,
                           'visibility', 'same transaction after each supported source statement',
                           'consequence_boundary', 'committed asynchronous agenda');
EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT 7, 'M19_IMMEDIATE_VALIDATION', 'ERROR', condition::text,
        SQLERRM, 'Correct the named object or keep this version scheduled.', '{}'::jsonb;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.validate_program(definition jsonb)
 RETURNS TABLE(contract_version integer, code text, severity text, object_identity text, message text, hint text, details jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    item record;
    aggregate_item jsonb;
    window_item jsonb;
    first_relation text;
    first_condition text;
    first_event name;
    duration_value bigint;
    lateness_value bigint;
    first_duration bigint;
    first_lateness bigint;
    input_oid oid;
    condition_oid oid;
    target_spec pgreact_internal.keyed_derived_relations%ROWTYPE;
    event_attribute record;
    value_attribute record;
    function_name text;
    result_type oid;
    group_column name;
    rule_count integer;
BEGIN
    IF NOT pgreact_internal.is_window_program(definition) THEN
        RETURN QUERY SELECT * FROM pgreact_internal.validate_program_m16(definition);
        RETURN;
    END IF;
    IF jsonb_typeof(definition) IS DISTINCT FROM 'object'
       OR jsonb_typeof(definition -> 'rules') IS DISTINCT FROM 'array'
       OR jsonb_array_length(definition -> 'rules') = 0 THEN
        RETURN QUERY SELECT 6, 'M17_PROGRAM_INVALID', 'ERROR', 'program',
            'windowed program must be an object with at least one rule',
            'Declare one or more rules sharing one timed aggregate input.', '{}'::jsonb;
        RETURN;
    END IF;
    rule_count := jsonb_array_length(definition -> 'rules');
    IF COALESCE((definition ->> 'max_facts')::bigint, 0) < rule_count THEN
        RETURN QUERY SELECT 6, 'M17_RESOURCE_LIMIT', 'ERROR', definition ->> 'name',
            'max_facts cannot hold one state for every window rule',
            'Raise max_facts to at least the number of rules.',
            jsonb_build_object('required', rule_count);
        RETURN;
    END IF;
    FOR item IN SELECT value, ordinal FROM jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY rules(value, ordinal)
    LOOP
        aggregate_item := item.value -> 'aggregate_input';
        window_item := aggregate_item -> 'window';
        IF jsonb_typeof(aggregate_item) IS DISTINCT FROM 'object'
           OR jsonb_typeof(window_item) IS DISTINCT FROM 'object'
           OR NOT aggregate_item ?& ARRAY['relation','key','comparison','threshold','window']
           OR (aggregate_item ? 'function') <> (aggregate_item ? 'expression')
           OR (SELECT count(*) FROM jsonb_object_keys(aggregate_item)) <>
              (CASE WHEN aggregate_item ? 'function' THEN 7 ELSE 5 END)
           OR NOT window_item ?& ARRAY['event_time','duration','allowed_lateness']
           OR (SELECT count(*) FROM jsonb_object_keys(window_item)) <> 3 THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_DECLARATION_INVALID', 'ERROR',
                COALESCE(item.value ->> 'name', item.ordinal::text),
                'windowed aggregate_input has unsupported or missing members',
                'Use relation, key, comparison, threshold, optional function/expression, and one event_time/duration/allowed_lateness window.',
                '{}'::jsonb;
            RETURN;
        END IF;
        BEGIN
            duration_value := pgreact_internal.fixed_interval_us(window_item ->> 'duration', false);
            lateness_value := pgreact_internal.fixed_interval_us(
                window_item ->> 'allowed_lateness', true);
        EXCEPTION WHEN SQLSTATE '22023' THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_INTERVAL_INVALID', 'ERROR',
                item.value ->> 'name', 'window duration or allowed lateness is invalid',
                'Use fixed integral microsecond intervals; duration must be positive and lateness nonnegative.',
                jsonb_build_object('duration', window_item -> 'duration',
                                   'allowed_lateness', window_item -> 'allowed_lateness');
            RETURN;
        END;
        IF item.ordinal = 1 THEN
            first_relation := aggregate_item ->> 'relation';
            first_condition := item.value ->> 'definition';
            first_event := (window_item ->> 'event_time')::name;
            first_duration := duration_value;
            first_lateness := lateness_value;
        ELSIF first_relation IS DISTINCT FROM aggregate_item ->> 'relation'
              OR first_condition IS DISTINCT FROM item.value ->> 'definition'
              OR first_event IS DISTINCT FROM (window_item ->> 'event_time')::name
              OR first_duration IS DISTINCT FROM duration_value
              OR first_lateness IS DISTINCT FROM lateness_value THEN
            RETURN QUERY SELECT 6, 'M17_MULTIPLE_WINDOWS', 'ERROR', definition ->> 'name',
                'all windowed rules in one program must share one logical timed input',
                'Use one relation, event-time column, duration, lateness, and group source.', '{}'::jsonb;
            RETURN;
        END IF;
        input_oid := to_regclass(aggregate_item ->> 'relation');
        condition_oid := to_regclass(item.value ->> 'definition');
        IF input_oid IS NULL OR condition_oid IS NULL THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_RELATION_UNRESOLVED', 'ERROR', item.value ->> 'name',
                'window input or group source does not resolve',
                'Use schema-qualified existing relations.',
                jsonb_build_object('input', aggregate_item -> 'relation',
                                   'condition', item.value -> 'definition');
            RETURN;
        END IF;
        IF cardinality(parse_ident(aggregate_item ->> 'relation', true)) <> 2
           OR cardinality(parse_ident(item.value ->> 'definition', true)) <> 2 THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_RELATION_UNQUALIFIED', 'ERROR', item.value ->> 'name',
                'window input and group source must be schema-qualified',
                'Qualify both relations with their schema.', '{}'::jsonb;
            RETURN;
        END IF;
        IF NOT has_table_privilege(session_user, input_oid, 'SELECT')
           OR NOT has_table_privilege(session_user, condition_oid, 'SELECT') THEN
            RETURN QUERY SELECT 6, 'PROGRAM_AGGREGATE_UNAUTHORIZED', 'ERROR', item.value ->> 'name',
                'program author cannot read the timed input or group source',
                'Grant SELECT on both relations to the author.', '{}'::jsonb;
            RETURN;
        END IF;
        IF EXISTS (SELECT 1 FROM pg_class WHERE oid IN (input_oid, condition_oid) AND relrowsecurity) THEN
            RETURN QUERY SELECT 6, 'PROGRAM_AGGREGATE_RLS_UNSUPPORTED', 'ERROR', item.value ->> 'name',
                'row-level-security sources are outside the supported window boundary',
                'Use an authorized non-RLS projection.', '{}'::jsonb;
            RETURN;
        END IF;
        SELECT attnum, atttypid INTO event_attribute
        FROM pg_attribute
        WHERE attrelid = input_oid AND attname = (window_item ->> 'event_time')::name
          AND attnum > 0 AND NOT attisdropped;
        IF NOT FOUND OR event_attribute.atttypid IS DISTINCT FROM 'timestamptz'::regtype::oid THEN
            RETURN QUERY SELECT 6, 'M17_EVENT_TIME_TYPE', 'ERROR', item.value ->> 'name',
                'event_time must name one direct timestamptz column',
                'Project a finite non-null timestamptz column and name it directly.',
                jsonb_build_object('event_time', window_item -> 'event_time');
            RETURN;
        END IF;
        SELECT spec.* INTO target_spec FROM pgreact_internal.keyed_derived_relations spec
        WHERE spec.public_name = item.value ->> 'target';
        IF NOT FOUND OR cardinality(target_spec.key_columns) NOT BETWEEN 2 AND 4
           OR target_spec.key_types[cardinality(target_spec.key_types)] <> 'bigint'::regtype THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_KEY_INVALID', 'ERROR', item.value ->> 'name',
                'window target key must append one bigint ordinal to one to three group components',
                'Declare the target with group keys followed by a bigint window ordinal.', '{}'::jsonb;
            RETURN;
        END IF;
        IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = input_oid
                   AND attname = target_spec.key_columns[cardinality(target_spec.key_columns)]
                   AND attnum > 0 AND NOT attisdropped) THEN
            RETURN QUERY SELECT 6, 'M17_WINDOW_KEY_AMBIGUOUS', 'ERROR', item.value ->> 'name',
                'timed input already exposes the reserved target window-ordinal column',
                'Rename that source column or the target ordinal column.', '{}'::jsonb;
            RETURN;
        END IF;
        FOREACH group_column IN ARRAY target_spec.key_columns[1:cardinality(target_spec.key_columns)-1]
        LOOP
            IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = input_oid
                           AND attname = group_column AND attnum > 0 AND NOT attisdropped)
               OR NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = condition_oid
                              AND attname = group_column AND attnum > 0 AND NOT attisdropped) THEN
                RETURN QUERY SELECT 6, 'M17_WINDOW_KEY_UNBOUND', 'ERROR', item.value ->> 'name',
                    'group key is not directly present in both source relations',
                    'Expose every target group-key column from the timed input and group source.',
                    jsonb_build_object('column', group_column);
                RETURN;
            END IF;
        END LOOP;
        function_name := COALESCE(aggregate_item ->> 'function', 'COUNT_STAR');
        IF function_name NOT IN ('COUNT','SUM','MIN','MAX','COUNT_STAR')
           OR (function_name = 'COUNT' AND aggregate_item ->> 'expression' = '*') THEN
            RETURN QUERY SELECT 6, 'PROGRAM_AGGREGATE_FUNCTION_UNSUPPORTED', 'ERROR', item.value ->> 'name',
                'aggregate function is outside the M16 allow-list',
                'Use inherited COUNT(*) or COUNT, SUM, MIN, or MAX over one named column.',
                jsonb_build_object('function', function_name);
            RETURN;
        END IF;
        IF function_name <> 'COUNT_STAR' THEN
            SELECT attnum, atttypid, attcollation INTO value_attribute
            FROM pg_attribute WHERE attrelid = input_oid
              AND attname = (aggregate_item ->> 'expression')::name
              AND attnum > 0 AND NOT attisdropped;
            result_type := pgreact_internal.aggregate_result_type(function_name, value_attribute.atttypid);
            IF NOT FOUND OR result_type IS NULL THEN
                RETURN QUERY SELECT 6, 'PROGRAM_AGGREGATE_TYPE_UNSUPPORTED', 'ERROR', item.value ->> 'name',
                    'aggregate expression type is unsupported',
                    'Use one M16-supported direct column and aggregate function.',
                    jsonb_build_object('expression', aggregate_item -> 'expression');
                RETURN;
            END IF;
        ELSIF (aggregate_item ->> 'threshold')::bigint < 0 THEN
            RETURN QUERY SELECT 6, 'PROGRAM_AGGREGATE_THRESHOLD_INVALID', 'ERROR', item.value ->> 'name',
                'COUNT(*) threshold must be nonnegative', 'Use a nonnegative bigint threshold.', '{}'::jsonb;
            RETURN;
        END IF;
    END LOOP;
    RETURN QUERY SELECT 6, 'PROGRAM_VALID', 'INFO', definition ->> 'name',
        'windowed program is valid', 'Preview and deploy this exact definition.',
        jsonb_build_object('normalized_definition',
                           pgreact_internal.normalized_window_program(definition));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.validate_rule(condition regclass, semantic_keys name[], action_schema name, on_activate name, on_deactivate name DEFAULT NULL::name, on_change name DEFAULT NULL::name)
 RETURNS TABLE(contract_version integer, code text, severity text, object_identity text, message text, hint text, details jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
    PERFORM pgreact_internal.assert_key_columns(condition, semantic_keys);
    PERFORM pgreact_internal.resolve_action(action_schema, on_activate, condition, 'ACTIVATE');
    IF on_deactivate IS NOT NULL THEN
        PERFORM pgreact_internal.resolve_action(action_schema, on_deactivate, condition, 'DEACTIVATE');
    END IF;
    IF on_change IS NOT NULL THEN
        PERFORM pgreact_internal.resolve_action(action_schema, on_change, condition, 'CHANGE');
    END IF;
    RETURN QUERY SELECT 5, 'OK', 'INFO', condition::text,
        'typed semantic key and actions are valid',
        'Call author_rule with the same ordered key columns.',
        jsonb_build_object('key_columns', semantic_keys);
EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT 5, split_part(SQLERRM, ':', 1), 'ERROR', condition::text,
        SQLERRM, 'Correct the named key or action and validate again.', '{}'::jsonb;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_api.validate_shared_condition(definition jsonb)
 RETURNS TABLE(contract_version integer, code text, severity text, object_identity text, message text, hint text, details jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    source_oid oid;
    target_oid oid;
    row_type_oid oid;
    row_relid oid;
    row_owner oid;
    source_owner oid;
    keys name[];
    key_types regtype[];
    key_collations regcollation[];
    source_signature bytea;
    mode text := upper(COALESCE(definition ->> 'maintenance_mode', 'SCHEDULED'));
    condition_name text := definition ->> 'name';
BEGIN
    IF jsonb_typeof(definition) IS DISTINCT FROM 'object'
       OR condition_name IS NULL
       OR definition ->> 'source' IS NULL
       OR definition ->> 'row_type' IS NULL
       OR pgreact_internal.condition_keys(definition) IS NULL THEN
        RETURN QUERY SELECT 8, 'M20_DEFINITION_SHAPE', 'ERROR',
            COALESCE(condition_name, 'condition'),
            'shared condition definitions require name, source, row_type, and key',
            'Use a schema-qualified relation, an owned composite row type, and one to four named key columns.',
            '{}'::jsonb;
        RETURN;
    END IF;
    keys := pgreact_internal.condition_keys(definition);
    IF cardinality(keys) NOT BETWEEN 1 AND 4
       OR array_position(keys, NULL) IS NOT NULL
       OR (SELECT count(DISTINCT key) FROM unnest(keys) key) <> cardinality(keys) THEN
        RETURN QUERY SELECT 8, 'M20_KEY_ARITY', 'ERROR', condition_name,
            'shared condition keys require one to four distinct columns',
            'Use one to four non-null, distinct key names.', '{}'::jsonb;
        RETURN;
    END IF;
    IF mode NOT IN ('SCHEDULED', 'IMMEDIATE') THEN
        RETURN QUERY SELECT 8, 'M20_MAINTENANCE_MODE', 'ERROR', condition_name,
            'shared condition maintenance_mode is unsupported',
            'Choose SCHEDULED or IMMEDIATE.', jsonb_build_object('maintenance_mode', mode);
        RETURN;
    END IF;
    source_oid := to_regclass(definition ->> 'source');
    IF source_oid IS NULL THEN
        RETURN QUERY SELECT 8, 'M20_SOURCE_NOT_FOUND', 'ERROR', definition ->> 'source',
            'the shared condition source relation does not exist',
            'Create the schema-qualified source view before previewing the condition.', '{}'::jsonb;
        RETURN;
    END IF;
    IF (SELECT relkind FROM pg_class WHERE oid = source_oid) NOT IN ('v', 'm') THEN
        RETURN QUERY SELECT 8, 'M20_SOURCE_KIND', 'ERROR', source_oid::regclass::text,
            'shared condition sources must be views or materialized views',
            'Expose the SQL condition through a view.', '{}'::jsonb;
        RETURN;
    END IF;
    SELECT relowner INTO source_owner FROM pg_class WHERE oid = source_oid;
    IF source_owner <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RETURN QUERY SELECT 8, 'M20_SOURCE_OWNER', 'ERROR', source_oid::regclass::text,
            'the condition author must own the source view',
            'Use the source view owner to declare the shared condition.', '{}'::jsonb;
        RETURN;
    END IF;
    row_type_oid := to_regtype(definition ->> 'row_type');
    SELECT typrelid, typowner INTO row_relid, row_owner
    FROM pg_type WHERE oid = row_type_oid;
    IF row_type_oid IS NULL OR row_relid = 0 OR row_owner <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RETURN QUERY SELECT 8, 'M20_ROW_TYPE', 'ERROR', COALESCE(definition ->> 'row_type', 'row_type'),
            'the condition row_type must be an owned composite type',
            'Create and own a composite type matching the source view columns.', '{}'::jsonb;
        RETURN;
    END IF;
    IF pgreact_internal.source_row_signature(source_oid)
       IS DISTINCT FROM pgreact_internal.source_row_signature(row_relid) THEN
        RETURN QUERY SELECT 8, 'M20_SCHEMA_MISMATCH', 'ERROR', condition_name,
            'the source view columns do not match row_type',
            'Keep column names, order, types, and collations identical.',
            jsonb_build_object('source', source_oid::regclass::text,
                               'row_type', row_type_oid::regtype::text);
        RETURN;
    END IF;
    SELECT array_agg(attribute.atttypid::regtype ORDER BY key.ordinality),
           array_agg(attribute.attcollation::regcollation ORDER BY key.ordinality)
    INTO key_types, key_collations
    FROM unnest(keys) WITH ORDINALITY key(key_name, ordinality)
    LEFT JOIN pg_attribute attribute
      ON attribute.attrelid = row_relid AND attribute.attname = key.key_name
     AND attribute.attnum > 0 AND NOT attribute.attisdropped;
    IF COALESCE(cardinality(key_types), 0) <> cardinality(keys)
       OR EXISTS (SELECT 1 FROM unnest(COALESCE(key_types, ARRAY[]::regtype[])) key_type
                 WHERE key_type IS NULL) THEN
        RETURN QUERY SELECT 8, 'M20_KEY_NOT_FOUND', 'ERROR', condition_name,
            'every shared condition key must be a row_type attribute',
            'Use key columns present in the source view and row_type.',
            jsonb_build_object('key', keys);
        RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(key_types) key_type
               WHERE key_type NOT IN ('bigint'::regtype, 'uuid'::regtype, 'text'::regtype)) THEN
        RETURN QUERY SELECT 8, 'M20_KEY_TYPE', 'ERROR', condition_name,
            'shared condition keys use unsupported types',
            'Use bigint, uuid, or deterministic-C-collated text keys.',
            jsonb_build_object('key_types', key_types);
        RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_attribute attribute
               JOIN pg_collation key_collation ON key_collation.oid = attribute.attcollation
               WHERE attribute.attrelid = row_relid
                 AND attribute.attname = ANY(keys)
                 AND attribute.atttypid = 'text'::regtype
                 AND (NOT key_collation.collisdeterministic OR key_collation.collname NOT IN ('C', 'default'))) THEN
        RETURN QUERY SELECT 8, 'M20_KEY_COLLATION', 'ERROR', condition_name,
            'text keys require a deterministic C collation',
            'Use COLLATE "C" for text semantic keys.', '{}'::jsonb;
        RETURN;
    END IF;
    IF EXISTS (
        WITH RECURSIVE dependencies(relid) AS (
            SELECT source_oid
            UNION
            SELECT dependency.refobjid
            FROM dependencies parent
            JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relid
            JOIN pg_depend dependency
              ON dependency.classid = 'pg_rewrite'::regclass
             AND dependency.objid = rewrite.oid
             AND dependency.refclassid = 'pg_class'::regclass
             AND dependency.deptype = 'n')
        SELECT 1 FROM dependencies
        JOIN pg_class relation ON relation.oid = dependencies.relid
        WHERE relation.relrowsecurity) THEN
        RETURN QUERY SELECT 8, 'M20_RLS_UNSUPPORTED', 'ERROR', condition_name,
            'shared condition sources may not depend on row-level-security relations',
            'Expose an authorized, non-RLS source view for this condition.', '{}'::jsonb;
        RETURN;
    END IF;
    target_oid := to_regclass(condition_name);
    IF target_oid IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pgreact_internal.shared_conditions
        WHERE shared_conditions.condition_name = condition_name) THEN
        RETURN QUERY SELECT 8, 'M20_RELATION_EXISTS', 'ERROR', condition_name,
            'the shared condition public relation already exists',
            'Choose a new condition name or remove the unrelated relation first.', '{}'::jsonb;
        RETURN;
    END IF;
    IF target_oid IS NOT NULL AND EXISTS (
        WITH RECURSIVE dependencies(relid) AS (
            SELECT source_oid
            UNION
            SELECT dependency.refobjid
            FROM dependencies parent
            JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relid
            JOIN pg_depend dependency
              ON dependency.classid = 'pg_rewrite'::regclass
             AND dependency.objid = rewrite.oid
             AND dependency.refclassid = 'pg_class'::regclass
             AND dependency.deptype = 'n')
        SELECT 1 FROM dependencies WHERE relid = target_oid) THEN
        RETURN QUERY SELECT 8, 'M20_CONDITION_CYCLE', 'ERROR', condition_name,
            'a shared condition cannot depend on its own public relation',
            'Remove the self-reference from the source view.', '{}'::jsonb;
        RETURN;
    END IF;
    source_signature := pgreact_internal.source_row_signature(source_oid);
    RETURN QUERY SELECT 8, 'OK', 'INFO', condition_name,
        'shared condition definition is valid',
        'Preview the condition before deployment.',
        jsonb_build_object('source', source_oid::regclass::text,
                           'row_type', row_type_oid::regtype::text,
                           'key_columns', keys,
                           'key_types', key_types,
                           'maintenance_mode', mode,
                           'source_row_signature', encode(source_signature, 'hex'));
EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT 8, 'M20_VALIDATION', 'ERROR',
        COALESCE(condition_name, 'condition'), SQLERRM,
        'Correct the shared condition definition and validate again.', '{}'::jsonb;
END
$function$

CREATE OR REPLACE FUNCTION pgreact.begin_deadline_refresh(refresh_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE locked boolean := false;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M12_CLOCK_UNAUTHORIZED: only pgreact_admin may advance database time';
    END IF;
    IF pg_catalog.pg_is_in_recovery() THEN
        RAISE EXCEPTION 'M12_CLOCK_STANDBY: database time cannot advance on a physical standby';
    END IF;
    PERFORM pg_catalog.pg_advisory_lock(5788046901200000);
    locked := true;
    IF EXISTS (
        SELECT 1
        FROM pgreact_internal.rule_barriers barrier
        JOIN pgreact_internal.deadline_rules deadline USING (rule_version_id)
        JOIN pgreact_internal.rule_versions version USING (rule_version_id)
        WHERE version.state = 'ACTIVE'
    ) THEN
        RAISE EXCEPTION 'M12_CLOCK_BARRIER: an active deadline rule already has a claim barrier';
    END IF;
    INSERT INTO pgreact_internal.rule_barriers (
        rule_version_id, reason, refresh_id
    )
    SELECT deadline.rule_version_id, 'REFRESHING', begin_deadline_refresh.refresh_id
    FROM pgreact_internal.deadline_rules deadline
    JOIN pgreact_internal.rule_versions version USING (rule_version_id)
    WHERE version.state = 'ACTIVE';
EXCEPTION WHEN OTHERS THEN
    IF locked THEN
        PERFORM pg_catalog.pg_advisory_unlock(5788046901200000);
    END IF;
    RAISE;
END
$function$

CREATE OR REPLACE FUNCTION pgreact.claim_episode(target_version_id uuid, worker_id text, lease_seconds integer DEFAULT 60)
 RETURNS TABLE(episode_id bigint, lease_token uuid, activation_id uuid, bindings jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE claimed record;
    episode pgreact_internal.agenda%ROWTYPE;
    rule_name text;
    scoped boolean;
    execution_time timestamptz;
BEGIN
    PERFORM pg_advisory_xact_lock_shared(5788046901200000);
    PERFORM pg_advisory_xact_lock(hashtextextended(
        'm31:rule:' || target_version_id::text, 5788046901200005));
    LOOP
        SELECT * INTO claimed
        FROM pgreact.claim_episode_m31_base(target_version_id, worker_id, lease_seconds);
        IF NOT FOUND THEN RETURN; END IF;
    SELECT agenda.* INTO STRICT episode
    FROM pgreact_internal.agenda agenda
    WHERE agenda.episode_id = claimed.episode_id
    FOR UPDATE;
    execution_time := clock_timestamp();
    SELECT rule.rule_name INTO rule_name
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    WHERE version.rule_version_id = episode.rule_version_id;
    SELECT EXISTS (
        SELECT 1
        FROM pgreact_internal.policy_set_members member
        JOIN pgreact_internal.policy_set_versions version
          USING (policy_set_version_id)
        WHERE member.member_kind = 'rule' AND member.member_name = rule_name
          AND member.scope_mode = 'POLICY_SET_REQUIRED'
          AND member.member_version IN ('1', target_version_id::text)
          AND version.state = 'DEPLOYED'
    ) INTO scoped;
    IF scoped AND NOT pgreact_internal.m31_has_effective_rule_support(
        episode.activation_id, rule_name, target_version_id, execution_time) THEN
        UPDATE pgreact_internal.agenda
        SET state = 'WITHDRAWN', completed_at = clock_timestamp(),
            lease_token = NULL, worker_id = NULL, lease_expires_at = NULL
        WHERE agenda.episode_id = claimed.episode_id
          AND agenda.state = 'LEASED'
          AND agenda.worker_id = worker_id
          AND agenda.lease_token = claimed.lease_token;
        IF FOUND THEN CONTINUE; END IF;
    END IF;
    RETURN QUERY SELECT claimed.episode_id, claimed.lease_token,
                        claimed.activation_id, claimed.bindings;
    RETURN;
    END LOOP;
END
$function$

CREATE OR REPLACE FUNCTION pgreact.claim(worker_id text, max_items integer DEFAULT 1, lease_for interval DEFAULT '00:01:00'::interval, agenda_groups text[] DEFAULT NULL::text[])
 RETURNS TABLE(episode_id bigint, lease_token uuid, activation_id uuid, bindings jsonb, event_kind text, rule_version_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    candidate record;
    claimed record;
    version_id uuid;
    count_claimed integer := 0;
    seconds integer := extract(epoch FROM lease_for)::integer;
    fairness interval;
    claim_limit integer;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200000);
    SELECT fairness_window, max_claims INTO fairness, claim_limit
    FROM pgreact_internal.operational_settings;
    IF max_items NOT BETWEEN 1 AND claim_limit THEN
        RAISE EXCEPTION 'max_items must be between 1 and %', claim_limit;
    END IF;
    IF seconds < 1 THEN
        RAISE EXCEPTION 'lease_for must be at least one second';
    END IF;
    FOR version_id IN
        SELECT rule_version_id
        FROM pgreact_internal.rule_versions
        WHERE state IN ('ACTIVE', 'DRAINING')
        ORDER BY rule_version_id
    LOOP
        PERFORM pgreact.sweep_expired_leases(version_id);
    END LOOP;
    FOR candidate IN
        SELECT agenda.rule_version_id
        FROM pgreact_internal.agenda agenda
        JOIN pgreact_internal.rule_versions version USING (rule_version_id)
        WHERE agenda.state IN ('PENDING', 'RETRY_WAIT')
          AND agenda.available_at <= clock_timestamp()
          AND version.state IN ('ACTIVE', 'DRAINING')
          AND NOT EXISTS (
              SELECT 1 FROM pgreact_internal.rule_barriers barrier
              WHERE barrier.rule_version_id = agenda.rule_version_id)
          AND (agenda_groups IS NULL OR agenda.agenda_group = ANY(agenda_groups))
        ORDER BY CASE WHEN agenda.available_at <= clock_timestamp() - fairness
                      THEN 0 ELSE 1 END,
                 agenda.available_at, agenda.salience DESC, agenda.episode_id
    LOOP
        SELECT * INTO claimed
        FROM pgreact.claim_episode(candidate.rule_version_id, worker_id, seconds);
        IF FOUND THEN
            SELECT agenda.event_kind INTO event_kind
            FROM pgreact_internal.agenda agenda
            WHERE agenda.episode_id = claimed.episode_id;
            episode_id := claimed.episode_id;
            lease_token := claimed.lease_token;
            activation_id := claimed.activation_id;
            bindings := claimed.bindings;
            rule_version_id := candidate.rule_version_id;
            RETURN NEXT;
            count_claimed := count_claimed + 1;
            EXIT WHEN count_claimed >= max_items;
        END IF;
    END LOOP;
END
$function$

CREATE OR REPLACE FUNCTION pgreact.compare(proposed pgreact_api.declaration, deployed pgreact_api.target, options jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE previous_context text := current_setting('pgreact.compare_target', true);
    result jsonb;
BEGIN
    PERFORM set_config('pgreact.compare_target', jsonb_build_object(
        'kind', (deployed).kind, 'name', (deployed).name, 'version', (deployed).version,
        'proposed', pgreact_internal.m28_normalize(proposed))::text, true);
    BEGIN
        result := CASE WHEN pgreact_internal.m38_requested(options)
            THEN pgreact_internal.m38_annotate_compare(
                pgreact_internal.m34_compare(
                    proposed, deployed, pgreact_internal.m38_strip_options(options)),
                'compare')
            ELSE pgreact_internal.m34_compare(
                proposed, deployed, pgreact_internal.m38_strip_options(options))
        END;
        result := pgreact_internal.m55_mark_compare_result(result);
    EXCEPTION WHEN OTHERS THEN
        PERFORM set_config('pgreact.compare_target', COALESCE(previous_context, ''), true);
        RAISE;
    END;
    PERFORM set_config('pgreact.compare_target', COALESCE(previous_context, ''), true);
    RETURN result;
END
$function$

CREATE OR REPLACE FUNCTION pgreact.compare(proposed pgreact_api.declaration, deployed pgreact_api.target, change_set jsonb, options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE previous_context text := current_setting('pgreact.compare_target', true);
    result jsonb;
BEGIN
    PERFORM set_config('pgreact.compare_target', jsonb_build_object(
        'kind', (deployed).kind, 'name', (deployed).name, 'version', (deployed).version,
        'proposed', pgreact_internal.m28_normalize(proposed))::text, true);
    BEGIN
        result := CASE WHEN pgreact_internal.m38_requested(options)
            THEN pgreact_internal.m38_annotate_compare(
                pgreact_internal.m35_compare(
                    proposed, deployed, change_set,
                    pgreact_internal.m38_strip_options(options)),
                'compare')
            ELSE pgreact_internal.m35_compare(
                proposed, deployed, change_set,
                pgreact_internal.m38_strip_options(options))
        END;
        result := pgreact_internal.m55_mark_compare_result(result);
    EXCEPTION WHEN OTHERS THEN
        PERFORM set_config('pgreact.compare_target', COALESCE(previous_context, ''), true);
        RAISE;
    END;
    PERFORM set_config('pgreact.compare_target', COALESCE(previous_context, ''), true);
    RETURN result;
END
$function$

CREATE OR REPLACE FUNCTION pgreact.create_derived_relation(name text, row_type regtype, key_columns name[], relation_version integer DEFAULT 1)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    diagnostic record;
    parts text[] := pg_catalog.parse_ident(name, true);
    relation_id uuid := gen_random_uuid();
    version_id uuid := gen_random_uuid();
    caller_oid oid := (SELECT oid FROM pg_catalog.pg_roles WHERE rolname = session_user);
    type_name text;
    qualified_name text;
    view_oid oid;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact.validate_derived_relation(name, row_type, key_columns, relation_version)
    WHERE severity = 'ERROR' ORDER BY code LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react derived relation validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    qualified_name := format('%I.%I', parts[1], parts[2]);
    SELECT format('%I.%I', n.nspname, t.typname) INTO STRICT type_name
    FROM pg_catalog.pg_type t
    JOIN pg_catalog.pg_namespace n ON n.oid = t.typnamespace
    WHERE t.oid = row_type;
    INSERT INTO pgreact_internal.derived_relations
        (relation_id, relation_name, owner_oid)
    VALUES (relation_id, qualified_name, caller_oid);
    INSERT INTO pgreact_internal.derived_relation_versions (
        relation_version_id, relation_id, version, owner_oid, row_type_oid,
        row_type_name, row_signature, key_column, public_view_name, state
    ) VALUES (
        version_id, relation_id, relation_version, caller_oid, row_type,
        type_name, pgreact_internal.composite_type_signature(row_type),
        key_columns[1], qualified_name, 'ACTIVE'
    );
    EXECUTE format(
        'CREATE VIEW %s WITH (security_barrier=true) AS '
        'SELECT (pg_catalog.jsonb_populate_record(NULL::%s, f.fact)).* '
        'FROM pgreact_internal.derived_facts f WHERE f.relation_version_id = %L::uuid',
        qualified_name, type_name, version_id
    );
    view_oid := pg_catalog.to_regclass(qualified_name);
    UPDATE pgreact_internal.derived_relation_versions
    SET public_view_oid = view_oid WHERE relation_version_id = version_id;
    EXECUTE format('REVOKE ALL ON %s FROM PUBLIC', qualified_name);
    EXECUTE format('GRANT SELECT ON %s TO %I', qualified_name, session_user);
    RETURN version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact.create_rule(name text, definition regclass, key_columns name[], kind text DEFAULT NULL::text, on_activate regprocedure DEFAULT NULL::regprocedure, on_deactivate regprocedure DEFAULT NULL::regprocedure, on_change regprocedure DEFAULT NULL::regprocedure, bootstrap_policy text DEFAULT 'SEED_CURRENT'::text, change_columns name[] DEFAULT NULL::name[], salience integer DEFAULT 0, agenda_group text DEFAULT 'default'::text, conflict_key_columns name[] DEFAULT NULL::name[], max_attempts integer DEFAULT 1, initial_backoff_seconds integer DEFAULT 1, backoff_multiplier numeric DEFAULT 2, max_backoff_seconds integer DEFAULT 60)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE diagnostic record; version_id uuid; watched name[]; source_type oid;
BEGIN
    IF kind IS NOT NULL AND kind NOT IN ('COMMAND', 'CONSTRAINT') THEN RAISE EXCEPTION 'kind must be COMMAND or CONSTRAINT'; END IF;
    IF kind = 'CONSTRAINT' AND (on_activate IS NOT NULL OR on_deactivate IS NOT NULL OR on_change IS NOT NULL) THEN
        RAISE EXCEPTION 'constraint rules cannot have consequences';
    END IF;
    IF agenda_group = '' THEN RAISE EXCEPTION 'agenda_group must not be empty'; END IF;
    IF max_attempts NOT BETWEEN 1 AND 100 OR initial_backoff_seconds NOT BETWEEN 1 AND 3600
       OR max_backoff_seconds NOT BETWEEN 1 AND 86400 OR backoff_multiplier < 1 THEN
        RAISE EXCEPTION 'invalid retry policy';
    END IF;
    IF EXISTS (SELECT 1 FROM pgreact_internal.rules r JOIN pgreact_internal.rule_versions v USING (rule_id)
               WHERE r.rule_name = name AND v.state <> 'REMOVED') THEN
        RAISE EXCEPTION 'a non-removed rule named % already exists', name;
    END IF;
    SELECT * INTO diagnostic FROM pgreact.validate_rule(definition, key_columns, on_activate)
    WHERE severity = 'ERROR' LIMIT 1;
    IF FOUND THEN RAISE EXCEPTION 'pg-react validation % for %: %', diagnostic.code, diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint; END IF;
    version_id := pgreact_internal.register_reference_rule(name, definition, key_columns[1], on_activate, bootstrap_policy);
    IF change_columns IS NULL THEN
        SELECT array_agg(a.attname ORDER BY a.attnum) INTO watched
        FROM pg_catalog.pg_attribute a WHERE a.attrelid = definition AND a.attnum > 0 AND NOT a.attisdropped
          AND a.attname <> key_columns[1];
    ELSE
        watched := change_columns;
    END IF;
    IF on_change IS NOT NULL AND (cardinality(watched) IS NULL OR cardinality(watched) = 0) THEN
        RAISE EXCEPTION 'on_change requires at least one watched change column';
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(watched) c WHERE NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_operator o
          ON o.oprname = '=' AND o.oprleft = a.atttypid AND o.oprright = a.atttypid
        WHERE a.attrelid = definition AND a.attname = c AND a.attnum > 0 AND NOT a.attisdropped
    )) THEN RAISE EXCEPTION 'watched columns must have PostgreSQL equality semantics'; END IF;
    IF EXISTS (SELECT 1 FROM unnest(COALESCE(conflict_key_columns, ARRAY[]::name[])) c WHERE NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid = definition AND a.attname = c AND a.attnum > 0 AND NOT a.attisdropped
    )) THEN RAISE EXCEPTION 'conflict key columns must be projected by the source view'; END IF;
    UPDATE pgreact_internal.rule_versions SET change_columns = watched, salience = create_rule.salience,
        agenda_group = create_rule.agenda_group, conflict_key_columns = create_rule.conflict_key_columns
    WHERE rule_version_id = version_id;
    IF on_activate IS NOT NULL THEN
        PERFORM pgreact_internal.add_typed_binding(version_id, 'ACTIVATE', on_activate, max_attempts,
            initial_backoff_seconds, backoff_multiplier, max_backoff_seconds);
    END IF;
    IF on_deactivate IS NOT NULL THEN
        PERFORM pgreact_internal.add_typed_binding(version_id, 'DEACTIVATE', on_deactivate, max_attempts,
            initial_backoff_seconds, backoff_multiplier, max_backoff_seconds);
    END IF;
    IF on_change IS NOT NULL THEN
        PERFORM pgreact_internal.add_typed_binding(version_id, 'CHANGE', on_change, max_attempts,
            initial_backoff_seconds, backoff_multiplier, max_backoff_seconds);
    END IF;
    RETURN version_id;
END $function$

CREATE OR REPLACE FUNCTION pgreact.deploy_pack(definition jsonb, expected_plan_digest text, mappings jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    diagnostic record;
    actual_digest text;
    base_definition jsonb;
    base_digest text;
    pack_version uuid;
    program_item record;
    program_version uuid;
    mapped_program jsonb;
BEGIN
    IF NOT (definition ? 'programs' OR definition ? 'remove_programs') THEN
        SELECT * INTO diagnostic FROM pgreact.validate_pack(definition, mappings) d
        WHERE d.severity = 'ERROR' ORDER BY d.code, d.object_identity LIMIT 1;
        IF FOUND THEN
            RAISE EXCEPTION 'pg-react pack validation % for %: %',
                diagnostic.code, diagnostic.object_identity, diagnostic.message
                USING HINT = diagnostic.hint;
        END IF;
        RETURN pgreact_internal.deploy_pack(
            definition, expected_plan_digest, mappings);
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200001);
    SELECT * INTO diagnostic FROM pgreact.validate_pack(definition, mappings) d
    WHERE d.severity = 'ERROR' ORDER BY d.code, d.object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react pack validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    actual_digest := pgreact_internal.m8_pack_plan_digest(definition, mappings);
    IF expected_plan_digest IS DISTINCT FROM actual_digest THEN
        RAISE EXCEPTION 'rule-pack preview is stale'
            USING HINT = 'Run pgreact.preview_pack again after concurrent DDL, support, or deployment changes.',
                  DETAIL = format('expected %s, current %s',
                                  expected_plan_digest, actual_digest);
    END IF;
    base_definition := pgreact_internal.m8_pack_definition(definition);
    SELECT plan_digest INTO base_digest
    FROM pgreact_internal.preview_pack(base_definition, mappings)
    ORDER BY action_order LIMIT 1;
    pack_version := pgreact_internal.deploy_pack(
        base_definition, base_digest, mappings);
    FOR program_item IN
        SELECT value FROM jsonb_array_elements(COALESCE(definition -> 'programs', '[]'::jsonb)) value
    LOOP
        mapped_program := pgreact_internal.m8_program_definition(
            program_item.value, mappings);
        program_version := pgreact_internal.deploy_derivation_program(
            mapped_program, pack_version);
        INSERT INTO pgreact_internal.rule_pack_programs (
            pack_version_id, program_name, program_version_id
        ) VALUES (
            pack_version, program_item.value ->> 'name', program_version
        );
    END LOOP;
    FOR program_item IN
        SELECT value FROM jsonb_array_elements(COALESCE(definition -> 'remove_programs', '[]'::jsonb)) value
    LOOP
        SELECT v.program_version_id INTO STRICT program_version
        FROM pgreact_internal.derivation_programs p
        JOIN pgreact_internal.derivation_program_versions v USING (program_id)
        WHERE p.program_name = program_item.value ->> 'name'
          AND v.state = 'ACTIVE';
        PERFORM pgreact_internal.remove_derivation_program(program_version);
    END LOOP;
    PERFORM pgreact_internal.maybe_fail_pack('programs');
    UPDATE pgreact_internal.rule_pack_versions SET
        definition = deploy_pack.definition,
        definition_digest = sha256(convert_to(deploy_pack.definition::text, 'UTF8')),
        plan_digest = actual_digest
    WHERE pack_version_id = pack_version;
    RETURN pack_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact.deploy(declaration pgreact_api.declaration, review_token text, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE payload jsonb;
BEGIN
    IF review_token IS NULL OR octet_length(review_token) > 4096 THEN
        RAISE EXCEPTION 'M54_REVIEW_TOKEN_LIMIT: review token must be at most 4096 bytes';
    END IF;
    payload := pgreact_internal.m54_decode_review_token(review_token);
    IF payload IS NULL THEN
        RAISE EXCEPTION 'M54_REVIEW_TOKEN_INVALID: review token is malformed or unsupported';
    END IF;
    RETURN pgreact_internal.m54_deploy($1, $3, payload);
END
$function$

CREATE OR REPLACE FUNCTION pgreact.execute_claimed_batch(target_batch_id uuid, expected_worker_id text)
 RETURNS TABLE(episode_id bigint, status text, error_code text, error_message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    batch_row pgreact_internal.execution_batches%ROWTYPE;
    item_row record;
    item_status text;
    item_error_code text;
    item_error_message text;
    total_items integer;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200000);
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200001);
    SELECT * INTO STRICT batch_row
    FROM pgreact_internal.execution_batches
    WHERE batch_id = target_batch_id
    FOR UPDATE;
    IF batch_row.worker_id <> expected_worker_id THEN
        RAISE EXCEPTION 'batch % is owned by worker %, not %',
            target_batch_id, batch_row.worker_id, expected_worker_id;
    END IF;
    IF batch_row.state <> 'CLAIMED' THEN
        RAISE EXCEPTION 'batch % is not claimable in state %',
            target_batch_id, batch_row.state;
    END IF;
    SELECT count(*) INTO total_items
    FROM pgreact_internal.execution_batch_items
    WHERE batch_id = target_batch_id;
    IF total_items NOT BETWEEN 2 AND 32 OR total_items > batch_row.max_items THEN
        UPDATE pgreact_internal.execution_batches
        SET state = 'REJECTED', diagnostic_code = 'OVERSIZED_OR_EMPTY',
            diagnostic = jsonb_build_object('items', total_items,
                                             'max_items', batch_row.max_items),
            finished_at = clock_timestamp()
        WHERE batch_id = target_batch_id;
        UPDATE pgreact_internal.execution_batch_items
        SET outcome = 'REJECTED', error_code = 'OVERSIZED_OR_EMPTY',
            error_message = 'batch rejected before consequence invocation'
        WHERE batch_id = target_batch_id;
        RETURN QUERY
        SELECT item.episode_id, item.outcome, item.error_code, item.error_message
        FROM pgreact_internal.execution_batch_items item
        WHERE item.batch_id = target_batch_id
        ORDER BY item.item_order;
        RETURN;
    END IF;
    UPDATE pgreact_internal.execution_batches
    SET state = 'RUNNING', started_at = clock_timestamp()
    WHERE batch_id = target_batch_id;
    FOR item_row IN
        SELECT item_order, episode_id, lease_token
        FROM pgreact_internal.execution_batch_items
        WHERE batch_id = target_batch_id
        ORDER BY item_order
    LOOP
        item_status := NULL;
        item_error_code := NULL;
        item_error_message := NULL;
        BEGIN
            SELECT pgreact.execute_claimed_episode(
                item_row.episode_id, expected_worker_id, item_row.lease_token)
            INTO STRICT item_status;
        EXCEPTION WHEN OTHERS THEN
            item_status := 'FAILED';
            item_error_code := SQLSTATE;
            item_error_message := SQLERRM;
            UPDATE pgreact_internal.agenda
            SET state = 'FAILED', completed_at = clock_timestamp(),
                lease_token = NULL, worker_id = NULL, lease_expires_at = NULL,
                last_error = jsonb_build_object('code', item_error_code,
                                                 'message', item_error_message)
            WHERE episode_id = item_row.episode_id
              AND state = 'LEASED'
              AND worker_id = expected_worker_id
              AND lease_token = item_row.lease_token;
        END;
        SELECT agenda.last_error ->> 'code', agenda.last_error ->> 'message'
        INTO item_error_code, item_error_message
        FROM pgreact_internal.agenda agenda
        WHERE agenda.episode_id = item_row.episode_id;
        UPDATE pgreact_internal.execution_batch_items
        SET outcome = item_status,
            error_code = CASE WHEN item_status IN ('FAILED', 'RETRY_WAIT')
                              THEN item_error_code END,
            error_message = CASE WHEN item_status IN ('FAILED', 'RETRY_WAIT')
                                 THEN item_error_message END
        WHERE batch_id = target_batch_id
          AND episode_id = item_row.episode_id;
    END LOOP;
    UPDATE pgreact_internal.execution_batches
    SET state = CASE WHEN EXISTS (
            SELECT 1 FROM pgreact_internal.execution_batch_items item
            WHERE item.batch_id = target_batch_id
              AND item.outcome IN ('FAILED', 'RETRY_WAIT'))
        THEN 'PARTIAL' ELSE 'COMPLETED' END,
        diagnostic_code = CASE WHEN EXISTS (
            SELECT 1 FROM pgreact_internal.execution_batch_items item
            WHERE item.batch_id = target_batch_id
              AND item.outcome IN ('FAILED', 'RETRY_WAIT'))
            THEN 'ITEM_FAILURE' END,
        finished_at = clock_timestamp()
    WHERE batch_id = target_batch_id;
    RETURN QUERY
    SELECT item.episode_id, item.outcome, item.error_code, item.error_message
    FROM pgreact_internal.execution_batch_items item
    WHERE item.batch_id = target_batch_id
    ORDER BY item.item_order;
END
$function$

CREATE OR REPLACE FUNCTION pgreact.execute_claimed_episode(target_episode_id bigint, expected_worker_id text, expected_lease_token uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE episode pgreact_internal.agenda%ROWTYPE;
    rule_name text;
    scoped boolean;
    target_rule_version uuid;
    execution_time timestamptz;
BEGIN
    PERFORM pg_advisory_xact_lock_shared(5788046901200000);
    SELECT agenda.rule_version_id INTO target_rule_version
    FROM pgreact_internal.agenda agenda
    WHERE agenda.episode_id = target_episode_id;
    IF target_rule_version IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended(
            'm31:rule:' || target_rule_version::text, 5788046901200005));
    END IF;
    SELECT agenda.* INTO STRICT episode
    FROM pgreact_internal.agenda agenda
    WHERE agenda.episode_id = target_episode_id
    FOR UPDATE;
    SELECT rule.rule_name INTO rule_name
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    WHERE version.rule_version_id = episode.rule_version_id;
    PERFORM pgreact_internal.assert_not_active_program_member(
        episode.rule_version_id, 'agenda-executed',
        'Program derivations do not use the agenda; use pgreact.refresh_derivation_program.');
    SELECT EXISTS (
        SELECT 1
        FROM pgreact_internal.policy_set_members member
        JOIN pgreact_internal.policy_set_versions version
          USING (policy_set_version_id)
        WHERE member.member_kind = 'rule' AND member.member_name = rule_name
          AND member.scope_mode = 'POLICY_SET_REQUIRED'
          AND member.member_version IN ('1', episode.rule_version_id::text)
          AND version.state = 'DEPLOYED'
    ) INTO scoped;
    execution_time := clock_timestamp();
    IF scoped AND NOT pgreact_internal.m31_has_effective_rule_support(
        episode.activation_id, rule_name, episode.rule_version_id, execution_time) THEN
        IF episode.state = 'WITHDRAWN' THEN RETURN 'SKIPPED'; END IF;
        UPDATE pgreact_internal.agenda
        SET state = 'WITHDRAWN', completed_at = clock_timestamp(),
            lease_token = NULL, worker_id = NULL, lease_expires_at = NULL
        WHERE agenda.episode_id = target_episode_id
          AND agenda.state = 'LEASED'
          AND agenda.worker_id = expected_worker_id
          AND agenda.lease_token = expected_lease_token;
        IF FOUND THEN RETURN 'SKIPPED'; END IF;
    END IF;
    RETURN pgreact.execute_claimed_episode_m31_base(
        target_episode_id, expected_worker_id, expected_lease_token);
END
$function$

CREATE OR REPLACE FUNCTION pgreact.explain_recursive_fact(target_program uuid, target_relation uuid, target_key bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    program_row record;
    relation_identity text;
    proof jsonb;
BEGIN
    PERFORM pgreact_internal.assert_program_owner(target_program);
    SELECT p.program_name, v.version, v.frontier
    INTO STRICT program_row
    FROM pgreact_internal.derivation_programs p
    JOIN pgreact_internal.derivation_program_versions v USING (program_id)
    WHERE v.program_version_id = target_program AND v.state = 'ACTIVE';
    IF NOT EXISTS (
        SELECT 1 FROM pgreact_internal.derivation_program_components
        WHERE program_version_id = target_program
          AND target_relation = ANY (target_relations)
    ) THEN
        RAISE EXCEPTION 'relation % is not a member of program %',
            target_relation, target_program;
    END IF;
    SELECT r.relation_name || '@' || v.version INTO STRICT relation_identity
    FROM pgreact_internal.derived_relations r
    JOIN pgreact_internal.derived_relation_versions v USING (relation_id)
    WHERE v.relation_version_id = target_relation;
    proof := pgreact_internal.recursive_fact_proof(
        target_program, target_relation, target_key, ARRAY[]::uuid[]);
    IF proof IS NULL THEN RETURN NULL; END IF;
    RETURN jsonb_build_object(
        'program', program_row.program_name || '@' || program_row.version,
        'frontier', program_row.frontier,
        'relation', relation_identity,
        'fact', proof -> 'fact',
        'proof', proof
    );
END
$function$

CREATE OR REPLACE FUNCTION pgreact.explanation_capabilities(name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    target_count integer;
    target_kind text;
    target_version text;
    target_owner oid;
    target jsonb := '{}'::jsonb;
    questions jsonb;
    item jsonb;
    findings jsonb := '[]'::jsonb;
BEGIN
    IF name IS NULL THEN
        RETURN jsonb_build_object(
            'contract_version', 53, 'operation', 'explanation_capabilities',
            'target', '{}',
            'questions', pgreact_internal.m53_capability_questions(NULL),
            'read_only', true, 'findings', '[]'::jsonb);
    END IF;
    SELECT count(*) INTO target_count
    FROM (
        SELECT kind, object_name, owner_oid
        FROM pgreact_internal.api_declarations WHERE state = 'DEPLOYED'
        UNION
        SELECT 'policy_set', set.set_name, set.owner_oid
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE version.state = 'DEPLOYED'
    ) targets WHERE object_name = name;
    IF target_count = 1 THEN
        SELECT kind, owner_oid INTO target_kind, target_owner
        FROM (
            SELECT kind, object_name, owner_oid
            FROM pgreact_internal.api_declarations WHERE state = 'DEPLOYED'
            UNION
            SELECT 'policy_set', set.set_name, set.owner_oid
            FROM pgreact_internal.policy_set_versions version
            JOIN pgreact_internal.policy_sets set USING (policy_set_id)
            WHERE version.state = 'DEPLOYED'
        ) targets WHERE object_name = name;
        IF target_kind = 'policy_set' THEN
            SELECT version.version INTO target_version
            FROM pgreact_internal.policy_set_versions version
            JOIN pgreact_internal.policy_sets set USING (policy_set_id)
            WHERE set.set_name = name AND version.state = 'DEPLOYED'
            ORDER BY version.valid_from DESC, version.created_at DESC LIMIT 1;
        ELSE
            target_version := '1';
        END IF;
    END IF;
    IF target_count <> 1
       OR (NOT pg_has_role(session_user, target_owner, 'USAGE')
           AND NOT pgreact_internal.is_operator_admin()
           AND NOT EXISTS (
               SELECT 1 FROM pgreact_internal.application_roles role_row
               WHERE role_row.role_kind = 'reader'
                 AND pg_has_role(session_user, role_row.role_oid, 'member'))) THEN
        findings := jsonb_build_array(pgreact_internal.m53_finding(
            'M53_TARGET_UNAVAILABLE', 'WARNING', NULL,
            'the requested target is unavailable',
            'Check the public target name and your granted access.'));
        questions := pgreact_internal.m53_capability_questions(NULL);
        SELECT COALESCE(jsonb_agg(
            item.value || jsonb_build_object(
                'supported', false, 'finding', findings -> 0)
            ORDER BY item.ordinality), '[]'::jsonb)
        INTO questions
        FROM jsonb_array_elements(questions) WITH ORDINALITY item(value, ordinality);
        RETURN jsonb_build_object(
            'contract_version', 53, 'operation', 'explanation_capabilities',
            'target', '{}', 'questions', questions,
            'read_only', true, 'findings', findings);
    END IF;
    target := jsonb_build_object('kind', target_kind, 'name', name, 'version', target_version);
    questions := pgreact_internal.m53_capability_questions(target_kind);
    RETURN jsonb_build_object(
        'contract_version', 53, 'operation', 'explanation_capabilities',
        'target', target, 'questions', questions, 'read_only', true, 'findings', findings);
END
$function$

CREATE OR REPLACE FUNCTION pgreact.explanation_summary(answer jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    contract text := answer ->> 'contract_version';
    origin text;
    question_kind text;
    state text;
    explanation_state text;
    availability_state text := 'current';
    target jsonb := COALESCE(answer -> 'target', '{}'::jsonb);
    subject jsonb := answer -> 'subject';
    reference jsonb;
    evidence_point jsonb := '{}';
    semantic_digest text;
    limits jsonb := COALESCE(answer -> 'limits', '{}'::jsonb);
    findings jsonb := COALESCE(answer -> 'findings', '[]'::jsonb);
    next_actions jsonb;
    children jsonb := '[]'::jsonb;
    item jsonb;
    why jsonb;
    nested jsonb;
    complete boolean := false;
    seen integer := 0;
BEGIN
    IF answer IS NULL OR jsonb_typeof(answer) IS DISTINCT FROM 'object'
       OR contract !~ '^[0-9]+$' THEN
        RETURN jsonb_build_object(
            'contract_version', 53, 'origin', 'unsupported',
            'question_kind', 'unsupported', 'target', '{}'::jsonb,
            'subject', NULL, 'explanation_ref', NULL,
            'availability_state', 'unsupported', 'origin_state', 'unsupported',
            'explanation_state', 'unsupported', 'complete', false,
            'evidence_point', '{}', 'semantic_digest', NULL, 'limits', '{}',
            'findings', jsonb_build_array(pgreact_internal.m53_finding(
                'M53_EXPLANATION_SUMMARY_UNSUPPORTED', 'ERROR', NULL,
                'the supplied result contract is unsupported',
                'Pass an installed Area 2 explanation result.')),
            'next_actions', jsonb_build_array(jsonb_build_object(
                'action', 'stop', 'reason_code', 'M53_EXPLANATION_SUMMARY_UNSUPPORTED',
                'safe_to_retry', false, 'parameters', '{}'::jsonb)));
    END IF;
    IF contract = '14' THEN
        origin := 'current'; question_kind := 'current';
        state := COALESCE(answer ->> 'state', answer ->> 'status', 'complete');
        evidence_point := COALESCE(answer -> 'evidence', '{}');
    ELSIF contract = '26' THEN
        origin := 'why_not'; question_kind := 'why_not';
        state := COALESCE(answer ->> 'state', 'unsupported');
        evidence_point := COALESCE(answer -> 'evidence', '{}');
        limits := COALESCE(answer -> 'limits', '{}');
    ELSIF contract = '27' AND answer ->> 'operation' = 'explain'
          AND answer -> 'request' ->> 'causal_path' = 'true' THEN
        origin := 'causal_path'; question_kind := 'causal_path';
        state := COALESCE(answer ->> 'state', 'unsupported');
        evidence_point := jsonb_build_object(
            'sampled_time', answer -> 'sampled_time',
            'authoritative_frontier', answer -> 'authoritative_frontier',
            'digests', COALESCE(answer -> 'digests', '{}'::jsonb));
        reference := pgreact_internal.m53_explanation_ref(answer);
        semantic_digest := answer -> 'digests' ->> 'semantic';
    ELSIF contract = '25' AND answer ->> 'operation' = 'compare' THEN
        origin := 'why_changed'; question_kind := 'why_changed';
        state := COALESCE(answer ->> 'state', 'unsupported');
        evidence_point := COALESCE(answer -> 'evidence', '{}');
        semantic_digest := answer -> 'evidence' -> 'why_changed' ->> 'explanation_digest';
        limits := jsonb_build_object(
            'evidence_limit', answer -> 'evidence' -> 'why_changed' -> 'evidence_limit');
        FOR item IN
            SELECT value FROM jsonb_array_elements(
                COALESCE(answer -> 'delta', '[]'::jsonb)
                || COALESCE(answer -> 'lifecycle', '[]'::jsonb))
        LOOP
            why := item -> 'why_changed';
            IF jsonb_typeof(why) = 'object' THEN
                seen := seen + 1;
                IF seen <= 256 THEN
                    children := children || jsonb_build_array(jsonb_build_object(
                        'origin', 'why_changed', 'question_kind', 'why_changed',
                        'target', target,
                        'subject', to_jsonb(COALESCE(item ->> 'subject_key', item ->> 'result_key')),
                        'explanation_ref', NULL,
                        'availability_state', CASE WHEN why ->> 'state' = 'complete'
                                                   THEN 'current' ELSE 'unavailable' END,
                        'origin_state', why ->> 'state',
                        'explanation_state', pgreact_internal.m53_state(why ->> 'state'),
                        'complete', why ->> 'state' = 'complete',
                        'evidence_point', COALESCE(why -> 'evidence', '{}'),
                        'semantic_digest', why ->> 'explanation_digest',
                        'limits', '{}', 'findings', '[]'::jsonb,
                        'next_actions', pgreact_internal.m53_next_actions(
                            '[]'::jsonb, why ->> 'state', 'why_changed')));
                END IF;
            END IF;
        END LOOP;
        IF seen > 256 THEN state := 'partial'; END IF;
    ELSIF contract = '28' THEN
        origin := 'retained_causal_path'; question_kind := 'causal_path';
        state := COALESCE(answer ->> 'state', 'unsupported');
        IF state IN ('available', 'deletion_eligible')
           AND jsonb_typeof(answer -> 'snapshot') = 'object' THEN
            nested := answer -> 'snapshot';
            explanation_state := pgreact_internal.m53_state(nested ->> 'state');
            complete := explanation_state = 'complete';
            target := COALESCE(answer -> 'metadata' -> 'target', '{}');
            subject := nested -> 'subject';
            evidence_point := COALESCE(answer -> 'metadata', '{}');
            limits := COALESCE(nested -> 'limits', '{}');
            semantic_digest := nested -> 'digests' ->> 'semantic';
            reference := pgreact_internal.m53_explanation_ref(nested);
            availability_state := 'historical';
        ELSIF state = 'deleted' THEN
            availability_state := 'deleted';
        ELSIF state = 'missing' THEN
            availability_state := 'missing';
        ELSE
            availability_state := 'unavailable';
        END IF;
    ELSIF contract = '43' AND answer ->> 'operation' = 'semantic_diff' THEN
        origin := 'semantic_difference'; question_kind := 'semantic_difference';
        state := COALESCE(answer ->> 'state', 'unsupported');
        evidence_point := jsonb_build_object(
            'proposed_declaration_digest', answer -> 'proposed_declaration_digest',
            'deployed_declaration_digest', answer -> 'deployed_declaration_digest',
            'completeness', COALESCE(answer -> 'completeness', '{}'));
        semantic_digest := answer ->> 'semantic_digest';
        complete := COALESCE((answer -> 'completeness' ->> 'complete')::boolean,
                             state = 'ready');
    ELSE
        RETURN pgreact.explanation_summary(NULL);
    END IF;
    IF explanation_state IS NULL THEN
        explanation_state := pgreact_internal.m53_state(state);
    END IF;
    IF NOT complete THEN complete := explanation_state = 'complete'; END IF;
    next_actions := pgreact_internal.m53_next_actions(findings, state, origin);
    RETURN jsonb_build_object(
        'contract_version', 53, 'origin', origin,
        'question_kind', question_kind, 'target', target, 'subject', subject,
        'explanation_ref', reference, 'availability_state', availability_state,
        'origin_state', state, 'explanation_state', explanation_state,
        'complete', complete, 'evidence_point', evidence_point,
        'semantic_digest', semantic_digest, 'limits', limits,
        'findings', findings, 'next_actions', next_actions)
        || CASE WHEN jsonb_array_length(children) > 0 OR origin = 'why_changed'
                THEN jsonb_build_object('children', children) ELSE '{}'::jsonb END;
END
$function$

CREATE OR REPLACE FUNCTION pgreact.export_m32(name text, kind text DEFAULT NULL::text, version text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE declaration pgreact_internal.api_declarations%ROWTYPE;
    policy_normalized jsonb;
    policy_spec jsonb;
    policy_members jsonb;
    policy_name text;
    digest text;
    target_count integer;
BEGIN
    SELECT count(*) INTO target_count
    FROM pgreact_internal.api_declarations row_data
    WHERE row_data.object_name = $1
      AND row_data.state = 'DEPLOYED'
      AND ($2 IS NULL OR row_data.kind = $2);
    IF target_count = 0 AND ($2 IS NULL OR $2 = 'policy_set') THEN
        SELECT version.normalized, set.set_name
        INTO policy_normalized, policy_name
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE set.set_name = $1
          AND version.state = 'DEPLOYED'
          AND ($3 IS NULL OR version.version = $3)
        ORDER BY version.valid_from DESC, version.created_at DESC
        LIMIT 1;
        IF FOUND THEN
            SELECT jsonb_agg(item.member - 'disposition' ORDER BY item.ordinality)
            INTO policy_members
            FROM jsonb_array_elements(policy_normalized -> 'spec' -> 'members')
                 WITH ORDINALITY AS item(member, ordinality);
            policy_spec := jsonb_set(
                policy_normalized -> 'spec', '{members}', COALESCE(policy_members, '[]'::jsonb));
            digest := encode(sha256(convert_to(jsonb_build_object(
                'api_version', '1',
                'kind', 'policy_set',
                'name', policy_name,
                'spec', policy_spec)::text, 'UTF8')), 'hex');
            RETURN jsonb_build_object(
                'api_version', '1',
                'kind', 'policy_set',
                'name', policy_name,
                'spec', policy_spec,
                'declaration_digest', digest,
                'digest', digest);
        END IF;
    END IF;
    IF target_count = 0 THEN
        RAISE EXCEPTION 'M32_EXPORT_NOT_FOUND: no deployed ordinary object named %', $1;
    END IF;
    IF target_count > 1 THEN
        RAISE EXCEPTION 'M32_EXPORT_AMBIGUOUS: more than one deployed ordinary object is named %',
            name;
    END IF;
    SELECT * INTO declaration
    FROM pgreact_internal.api_declarations row_data
    WHERE row_data.object_name = $1
      AND row_data.state = 'DEPLOYED'
      AND ($2 IS NULL OR row_data.kind = $2);
    IF declaration.kind NOT IN ('rule', 'decision_program', 'policy_set') THEN
        RAISE EXCEPTION 'M32_EXPORT_KIND: only ordinary objects can be exported';
    END IF;
    digest := encode(sha256(convert_to(jsonb_build_object(
        'api_version', declaration.api_version,
        'kind', declaration.kind,
        'name', declaration.object_name,
        'spec', declaration.normalized -> 'spec')::text, 'UTF8')), 'hex');
    RETURN jsonb_build_object(
        'api_version', declaration.api_version,
        'kind', declaration.kind,
        'name', declaration.object_name,
        'spec', declaration.normalized -> 'spec',
        'declaration_digest', digest,
        'digest', digest);
END
$function$

CREATE OR REPLACE FUNCTION pgreact.import(document jsonb, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE declaration pgreact_api.declaration;
    expected_digest text;
    actual_digest text;
BEGIN
    IF jsonb_typeof(document) IS DISTINCT FROM 'object'
       OR document ->> 'kind' IS NULL OR document ->> 'name' IS NULL
       OR jsonb_typeof(document -> 'spec') IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M53_IMPORT_DOCUMENT: export must contain kind, name, and object spec';
    END IF;
    expected_digest := COALESCE(document ->> 'definition_digest', document ->> 'digest');
    IF document ->> 'kind' = 'policy_set'
       AND (document -> 'spec' ? 'support' OR document -> 'spec' ? 'dependencies' OR EXISTS (
           SELECT 1 FROM jsonb_array_elements(CASE
               WHEN jsonb_typeof(document -> 'spec' -> 'members') = 'array'
               THEN document -> 'spec' -> 'members' ELSE '[]'::jsonb END) value
           WHERE jsonb_typeof(value -> 'declaration') = 'object')) THEN
        actual_digest := pgreact_internal.m53_package_digest(
            pgreact_internal.m53_package_normalize(
                pgreact_api.declaration(document ->> 'kind', document ->> 'name', document -> 'spec')));
    ELSE
        actual_digest := encode(sha256(convert_to(jsonb_build_object(
            'api_version', COALESCE(document ->> 'api_version', '1'),
            'kind', document ->> 'kind', 'name', document ->> 'name',
            'spec', document -> 'spec')::text, 'UTF8')), 'hex');
    END IF;
    IF expected_digest IS NOT NULL AND expected_digest <> actual_digest THEN
        RAISE EXCEPTION 'M53_IMPORT_DIGEST: canonical package digest does not match document';
    END IF;
    declaration := pgreact_api.declaration(document ->> 'kind', document ->> 'name', document -> 'spec');
    IF document ->> 'kind' = 'policy_set'
       AND NOT (document -> 'spec' ? 'support' OR document -> 'spec' ? 'dependencies' OR EXISTS (
           SELECT 1 FROM jsonb_array_elements(CASE
               WHEN jsonb_typeof(document -> 'spec' -> 'members') = 'array'
               THEN document -> 'spec' -> 'members' ELSE '[]'::jsonb END) value
           WHERE jsonb_typeof(value -> 'declaration') = 'object')) THEN
        RETURN pgreact.import_m32(document, preconditions);
    END IF;
    RETURN pgreact.deploy(declaration, preconditions);
END
$function$

CREATE OR REPLACE FUNCTION pgreact.import_m32(document jsonb, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE declaration pgreact_api.declaration;
    expected_digest text;
    actual_digest text;
BEGIN
    IF jsonb_typeof(document) IS DISTINCT FROM 'object'
       OR document ->> 'kind' IS NULL
       OR document ->> 'name' IS NULL
       OR jsonb_typeof(document -> 'spec') IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M32_IMPORT_DOCUMENT: export must contain kind, name, and object spec';
    END IF;
    expected_digest := COALESCE(document ->> 'declaration_digest', document ->> 'digest');
    actual_digest := encode(sha256(convert_to(jsonb_build_object(
        'api_version', COALESCE(document ->> 'api_version', '1'),
        'kind', document ->> 'kind',
        'name', document ->> 'name',
        'spec', document -> 'spec')::text, 'UTF8')), 'hex');
    IF expected_digest IS NOT NULL AND expected_digest <> actual_digest THEN
        RAISE EXCEPTION 'M32_IMPORT_DIGEST: canonical export digest does not match document';
    END IF;
    declaration := pgreact_api.declaration(
        COALESCE(document ->> 'kind', 'unknown'),
        document ->> 'name',
        document -> 'spec');
    RETURN pgreact.deploy(declaration, preconditions);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.activation_uuid(digest bytea)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
AS $function$
DECLARE
    value bytea := substring(digest FROM 1 FOR 16);
    hex text;
BEGIN
    IF length(digest) <> 32 THEN
        RAISE EXCEPTION 'pg-react identity digest must contain 32 bytes';
    END IF;
    value := set_byte(value, 6, (get_byte(value, 6) & 15) | 128);
    value := set_byte(value, 8, (get_byte(value, 8) & 63) | 128);
    hex := encode(value, 'hex');
    RETURN (substring(hex, 1, 8) || '-' || substring(hex, 9, 4) || '-' ||
            substring(hex, 13, 4) || '-' || substring(hex, 17, 4) || '-' ||
            substring(hex, 21, 12))::uuid;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.add_typed_binding(version_id uuid, kind text, consequence regprocedure, max_attempts integer DEFAULT 1, initial_backoff_seconds integer DEFAULT 1, backoff_multiplier numeric DEFAULT 2, max_backoff_seconds integer DEFAULT 60)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE; dispatcher_name text; dispatcher_qualified text;
    consequence_qualified text; dispatcher_oid oid;
BEGIN
    IF kind NOT IN ('ACTIVATE', 'CHANGE', 'DEACTIVATE') THEN RAISE EXCEPTION 'unsupported lifecycle event %', kind; END IF;
    PERFORM pgreact_internal.assert_typed_consequence(version_id, kind, consequence);
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions WHERE rule_version_id = version_id;
    SELECT format('%I.%I', n.nspname, p.proname) INTO STRICT consequence_qualified
      FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE p.oid = consequence;
    dispatcher_name := format('dispatch_m2_%s_%s', replace(version_id::text, '-', ''), lower(kind));
    dispatcher_qualified := format('%I.%I', 'pgreact_runtime', dispatcher_name);
    IF kind = 'CHANGE' THEN
        EXECUTE format(
            'CREATE FUNCTION %s(context pgreact.activation_context, old_bindings jsonb, new_bindings jsonb) '
            'RETURNS void LANGUAGE SQL SECURITY DEFINER SET search_path = pg_catalog, pg_temp '
            'AS $f$ SELECT %s($1, jsonb_populate_record(NULL::%s, $2), jsonb_populate_record(NULL::%s, $3)) $f$',
            dispatcher_qualified, consequence_qualified, version_row.source_view_name, version_row.source_view_name);
    ELSE
        EXECUTE format(
            'CREATE FUNCTION %s(context pgreact.activation_context, old_bindings jsonb, new_bindings jsonb) '
            'RETURNS void LANGUAGE SQL SECURITY DEFINER SET search_path = pg_catalog, pg_temp '
            'AS $f$ SELECT %s($1, jsonb_populate_record(NULL::%s, $%s)) $f$',
            dispatcher_qualified, consequence_qualified, version_row.source_view_name,
            CASE WHEN kind = 'ACTIVATE' THEN '3' ELSE '2' END);
    END IF;
    EXECUTE format('ALTER FUNCTION %s(pgreact.activation_context,jsonb,jsonb) OWNER TO %I', dispatcher_qualified, session_user);
    EXECUTE format('REVOKE ALL ON FUNCTION %s(pgreact.activation_context,jsonb,jsonb) FROM PUBLIC', dispatcher_qualified);
    dispatcher_oid := to_regprocedure(dispatcher_qualified || '(pgreact.activation_context,jsonb,jsonb)');
    INSERT INTO pgreact_internal.consequence_bindings (
        rule_version_id, event_kind, consequence_kind, function_oid, function_digest,
        dispatcher_oid, dispatcher_digest, max_attempts, initial_backoff_seconds,
        backoff_multiplier, max_backoff_seconds
    ) VALUES (
        version_id, kind, 'DATABASE_TYPED', consequence,
        sha256(convert_to(pg_get_functiondef(consequence), 'UTF8')), dispatcher_oid,
        sha256(convert_to(pg_get_functiondef(dispatcher_oid), 'UTF8')), max_attempts,
        initial_backoff_seconds, backoff_multiplier, max_backoff_seconds
    );
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.advance_window_watermark(target_program uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    program pgreact_internal.window_programs%ROWTYPE;
    boundary timestamptz;
    identity_count bigint;
    batch_limit integer := current_setting('pg_react.batch_size')::integer;
    finalized jsonb;
BEGIN
    SELECT * INTO STRICT program FROM pgreact_internal.window_programs
    WHERE program_version_id = target_program FOR UPDATE;
    IF program.barrier IS NOT NULL OR program.complete_watermark >= program.requested_watermark THEN
        RETURN jsonb_build_object('status', CASE WHEN program.barrier IS NULL THEN 'complete' ELSE 'blocked' END,
                                  'finalized', '[]'::jsonb);
    END IF;
    SELECT min(lateness_boundary) INTO boundary
    FROM pgreact_internal.window_identities
    WHERE program_version_id = target_program AND NOT final
      AND lateness_boundary > program.complete_watermark
      AND lateness_boundary <= program.requested_watermark;
    IF boundary IS NULL THEN
        UPDATE pgreact_internal.window_programs
        SET complete_watermark = requested_watermark
        WHERE program_version_id = target_program;
        RETURN jsonb_build_object('status','complete','finalized','[]'::jsonb);
    END IF;
    SELECT count(*) INTO identity_count FROM pgreact_internal.window_identities
    WHERE program_version_id = target_program AND NOT final AND lateness_boundary = boundary;
    IF identity_count > batch_limit THEN
        INSERT INTO pgreact_internal.window_diagnostics (
            code,severity,object_identity,sqlstate,message,hint,details,program_version_id)
        VALUES ('M17_WATERMARK_BATCH_LIMIT','ERROR',program.program_name,'54000',
            'earliest lateness boundary exceeds pg_react.batch_size',
            'Raise pg_react.batch_size to at least the required minimum and retry.',
            jsonb_build_object('required_minimum',identity_count,'batch_size',batch_limit,
                               'lateness_boundary',boundary),target_program);
        RETURN jsonb_build_object('status','failed','code','M17_WATERMARK_BATCH_LIMIT',
                                  'finalized','[]'::jsonb);
    END IF;
    IF current_setting('pg_react.m17_fail_watermark', true) = 'on' THEN
        INSERT INTO pgreact_internal.window_diagnostics (
            code,severity,object_identity,sqlstate,message,hint,details,program_version_id)
        VALUES ('M17_WATERMARK_BATCH_FAILED','ERROR',program.program_name,'XX000',
            'injected watermark advancement failure',
            'Clear pg_react.m17_fail_watermark and repeat the requested target.',
            jsonb_build_object('complete_watermark',program.complete_watermark,
                               'requested_watermark',program.requested_watermark),target_program);
        RETURN jsonb_build_object('status','failed','code','M17_WATERMARK_BATCH_FAILED',
                                  'finalized','[]'::jsonb);
    END IF;
    WITH finalized_rows AS (
        UPDATE pgreact_internal.window_identities
        SET final = true
        WHERE program_version_id = target_program AND NOT final AND lateness_boundary = boundary
        RETURNING public_window_key,canonical_window_key,lateness_boundary
    ), recorded AS (
        INSERT INTO pgreact_internal.window_finalizations (
            finalization_identity,program_version_id,public_window_key,
            canonical_window_key,lateness_boundary)
        SELECT replace(public_window_key::text, ' ', '') || '@' ||
               to_char(lateness_boundary AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
               target_program,public_window_key,canonical_window_key,lateness_boundary
        FROM finalized_rows ON CONFLICT DO NOTHING
        RETURNING public_window_key,canonical_window_key
    )
    SELECT COALESCE(jsonb_agg(public_window_key ORDER BY canonical_window_key),'[]'::jsonb)
    INTO finalized FROM recorded;
    UPDATE pgreact_internal.window_programs SET complete_watermark = boundary
    WHERE program_version_id = target_program;
    RETURN jsonb_build_object(
        'status',CASE WHEN boundary = program.requested_watermark THEN 'complete' ELSE 'pending' END,
        'finalized',finalized);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.assert_decision_admission(target_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE analysis_row record;
BEGIN
    SELECT * INTO analysis_row FROM pgreact_internal.decision_analyses
    WHERE decision_analyses.proposed_version_id = target_version_id
      AND decision_analyses.state <> 'REMOVED'
    ORDER BY analyzed_at DESC NULLS LAST, created_at DESC LIMIT 1;
    IF FOUND THEN
        IF NOT pgreact_internal.decision_analysis_is_fresh(analysis_row.analysis_id) THEN
            RAISE EXCEPTION 'M27_ANALYSIS_STALE: decision analysis fingerprints or complete frontier changed';
        END IF;
        IF analysis_row.last_report ->> 'state' <> 'PASS' THEN
            RAISE EXCEPTION 'M27_ANALYSIS_BLOCKED: proposed decision version has blocking analysis findings';
        END IF;
    END IF;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.assert_key_columns(condition regclass, key_columns name[])
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    source_owner oid;
    column_row record;
    found_columns integer := 0;
BEGIN
    IF cardinality(key_columns) NOT BETWEEN 1 AND 4
       OR array_position(key_columns, NULL) IS NOT NULL THEN
        RAISE EXCEPTION 'M15_KEY_ARITY: semantic keys require one to four named columns';
    END IF;
    IF (SELECT count(DISTINCT key_column) FROM unnest(key_columns) key_column)
       <> cardinality(key_columns) THEN
        RAISE EXCEPTION 'M15_KEY_DUPLICATE_COLUMN: semantic key columns must be distinct';
    END IF;
    SELECT relowner INTO STRICT source_owner FROM pg_class WHERE oid = condition;
    IF source_owner <> (SELECT oid FROM pg_roles WHERE rolname = session_user) THEN
        RAISE EXCEPTION 'M15_KEY_OWNER: the author must own condition %', condition;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_attribute
               WHERE attrelid = condition AND left(attname, 10) = '__pgreact_'
                 AND attnum > 0 AND NOT attisdropped) THEN
        RAISE EXCEPTION 'M15_KEY_RESERVED: condition % uses a reserved __pgreact_ column', condition;
    END IF;
    FOR column_row IN
        SELECT key.ordinality, key.key_column, attribute.atttypid,
               attribute.attcollation, key_collation.collname,
               key_collation.collisdeterministic, current_database_row.datcollate
        FROM unnest(key_columns) WITH ORDINALITY key(key_column, ordinality)
        LEFT JOIN pg_attribute attribute
          ON attribute.attrelid = condition AND attribute.attname = key.key_column
         AND attribute.attnum > 0 AND NOT attribute.attisdropped
        LEFT JOIN pg_collation key_collation ON key_collation.oid = attribute.attcollation
        CROSS JOIN pg_database current_database_row
        WHERE current_database_row.datname = current_database()
        ORDER BY key.ordinality
    LOOP
        IF column_row.atttypid IS NULL THEN
            RAISE EXCEPTION 'M15_KEY_COLUMN: column % does not exist in %',
                column_row.key_column, condition;
        END IF;
        found_columns := found_columns + 1;
        IF column_row.atttypid NOT IN ('bigint'::regtype, 'uuid'::regtype, 'text'::regtype) THEN
            RAISE EXCEPTION 'M15_KEY_TYPE: %.% has unsupported type %',
                condition, column_row.key_column, column_row.atttypid::regtype
                USING HINT = 'Use bigint, uuid, or text directly; domains and implicit casts are not key codecs.';
        END IF;
        IF column_row.atttypid = 'text'::regtype
           AND NOT column_row.collisdeterministic THEN
            RAISE EXCEPTION 'M15_KEY_COLLATION: %.% uses nondeterministic collation %',
                condition, column_row.key_column, column_row.collname;
        END IF;
        IF column_row.atttypid = 'text'::regtype
           AND column_row.collname <> 'C'
           AND NOT (column_row.collname = 'default'
                    AND column_row.datcollate IN ('C', 'C.UTF-8', 'C.utf8')) THEN
            RAISE EXCEPTION 'M15_KEY_COLLATION: %.% requires C collation for portable identity',
                condition, column_row.key_column
                USING HINT = 'Declare the text key column with COLLATE "C".';
        END IF;
    END LOOP;
    IF found_columns <> cardinality(key_columns) THEN
        RAISE EXCEPTION 'M15_KEY_COLUMN: semantic key columns could not be resolved';
    END IF;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.assert_typed_consequence(version_id uuid, kind text, consequence regprocedure)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE; source_type oid; proc record; expected_args integer;
BEGIN
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions WHERE rule_version_id = version_id;
    SELECT reltype INTO STRICT source_type FROM pg_catalog.pg_class WHERE oid = version_row.source_view_oid;
    SELECT proowner, prorettype, pronargs, proargtypes INTO STRICT proc FROM pg_catalog.pg_proc WHERE oid = consequence;
    expected_args := CASE WHEN kind = 'CHANGE' THEN 3 ELSE 2 END;
    IF proc.proowner <> version_row.owner_oid OR proc.prorettype <> 'void'::regtype OR proc.pronargs <> expected_args
       OR proc.proargtypes[0] <> 'pgreact.activation_context'::regtype
       OR proc.proargtypes[1] <> source_type
       OR (kind = 'CHANGE' AND proc.proargtypes[2] <> source_type) THEN
        RAISE EXCEPTION '% consequence % must be owned by the rule owner and have the exact typed % signature',
            kind, consequence, version_row.source_view_name;
    END IF;
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.author_keyed_rule(rule_name text, condition regclass, key_columns name[], action_schema name, on_activate name, on_deactivate name DEFAULT NULL::name, on_change name DEFAULT NULL::name, deadline_column name DEFAULT NULL::name)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    wrapper regclass;
    version_id uuid;
    action_event text;
    selected_action name;
    action regprocedure;
    proxy regprocedure;
    key_types regtype[];
    key_collations regcollation[];
BEGIN
    PERFORM pgreact_internal.assert_key_columns(condition, key_columns);
    IF on_activate IS NULL THEN
        RAISE EXCEPTION 'M15_ACTION_REQUIRED: on_activate must name an action';
    END IF;
    SELECT array_agg(attribute.atttypid::regtype ORDER BY key.ordinality),
           array_agg(attribute.attcollation::regcollation ORDER BY key.ordinality)
    INTO key_types, key_collations
    FROM unnest(key_columns) WITH ORDINALITY key(key_column, ordinality)
    JOIN pg_attribute attribute
      ON attribute.attrelid = condition AND attribute.attname = key.key_column
     AND attribute.attnum > 0 AND NOT attribute.attisdropped;
    wrapper := pgreact_internal.create_key_wrapper(condition, key_columns);
    IF deadline_column IS NULL THEN
        version_id := pgreact.create_rule(
            rule_name, wrapper, ARRAY['__pgreact_key'::name], 'COMMAND',
            NULL, NULL, NULL, 'SEED_CURRENT', NULL, 0, 'default', NULL,
            3, 1, 2, 60);
    ELSE
        version_id := pgreact.create_deadline_rule(
            rule_name, wrapper, ARRAY['__pgreact_key'::name], deadline_column,
            'COMMAND', NULL, NULL, NULL, 'SEED_CURRENT', NULL, 0, 'default', NULL,
            3, 1, 2, 60);
    END IF;
    INSERT INTO pgreact_internal.keyed_rule_versions VALUES (
        version_id, condition, wrapper, key_columns, key_types, key_collations);
    FOR action_event, selected_action IN
        SELECT * FROM (VALUES
            ('ACTIVATE'::text, on_activate),
            ('DEACTIVATE'::text, on_deactivate),
            ('CHANGE'::text, on_change)) actions(selected_event, selected_name)
        WHERE selected_name IS NOT NULL
    LOOP
        action := pgreact_internal.resolve_action(
            action_schema, selected_action, condition, action_event);
        proxy := pgreact_internal.create_action_proxy(
            version_id, action_event, action, condition, wrapper);
        PERFORM pgreact_internal.add_resolved_binding(version_id, action_event, proxy);
        UPDATE pgreact_internal.consequence_bindings
        SET max_attempts = 3
        WHERE rule_version_id = version_id
          AND consequence_bindings.event_kind = action_event;
    END LOOP;
    RETURN version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.author_resolved_rule(rule_name text, condition regclass, semantic_key name, action_schema name, on_activate name, on_deactivate name, on_change name, deadline_column name DEFAULT NULL::name)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    diagnostic record;
    version_id uuid;
    activate_action regprocedure;
    deactivate_action regprocedure;
    change_action regprocedure;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200001);
    SELECT * INTO diagnostic
      FROM pgreact_internal.validate_resolved_rule(
            condition, semantic_key, action_schema,
            on_activate, on_deactivate, on_change, deadline_column)
     WHERE severity = 'ERROR'
     ORDER BY code LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    IF on_activate IS NOT NULL THEN
        activate_action := pgreact_internal.resolve_action(
            action_schema, on_activate, condition, 'ACTIVATE');
    END IF;
    IF on_deactivate IS NOT NULL THEN
        deactivate_action := pgreact_internal.resolve_action(
            action_schema, on_deactivate, condition, 'DEACTIVATE');
    END IF;
    IF on_change IS NOT NULL THEN
        change_action := pgreact_internal.resolve_action(
            action_schema, on_change, condition, 'CHANGE');
    END IF;
    IF deadline_column IS NULL THEN
        version_id := pgreact.create_rule(
            rule_name, condition, ARRAY[semantic_key], 'COMMAND',
            NULL, NULL, NULL, 'SEED_CURRENT');
    ELSE
        version_id := pgreact.create_deadline_rule(
            rule_name, condition, ARRAY[semantic_key], deadline_column,
            'COMMAND', NULL, NULL, NULL, 'SEED_CURRENT');
    END IF;
    IF activate_action IS NOT NULL THEN
        PERFORM pgreact_internal.add_resolved_binding(
            version_id, 'ACTIVATE', activate_action);
    END IF;
    IF deactivate_action IS NOT NULL THEN
        PERFORM pgreact_internal.add_resolved_binding(
            version_id, 'DEACTIVATE', deactivate_action);
    END IF;
    IF change_action IS NOT NULL THEN
        PERFORM pgreact_internal.add_resolved_binding(
            version_id, 'CHANGE', change_action);
    END IF;
    RETURN version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.bind_outbox_consequence_m7(target_version_id uuid, kind text, sink regprocedure, max_attempts integer DEFAULT 3, initial_backoff_seconds integer DEFAULT 1, backoff_multiplier numeric DEFAULT 2, max_backoff_seconds integer DEFAULT 60)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
    PERFORM pgreact_internal.assert_rule_owner(target_version_id);
    IF kind NOT IN ('ACTIVATE', 'CHANGE', 'DEACTIVATE') THEN RAISE EXCEPTION 'unsupported lifecycle event %', kind; END IF;
    IF EXISTS (SELECT 1 FROM pgreact_internal.consequence_bindings WHERE rule_version_id = target_version_id AND event_kind = kind) THEN
        RAISE EXCEPTION 'rule version % already has a % consequence', target_version_id, kind;
    END IF;
    PERFORM pgreact.register_outbox_sink(sink);
    INSERT INTO pgreact_internal.consequence_bindings (
        rule_version_id, event_kind, consequence_kind, function_oid, function_digest,
        max_attempts, initial_backoff_seconds, backoff_multiplier, max_backoff_seconds
    ) VALUES (target_version_id, kind, 'OUTBOX', sink, sha256(convert_to(pg_get_functiondef(sink), 'UTF8')),
        max_attempts, initial_backoff_seconds, backoff_multiplier, max_backoff_seconds);
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.cancel_episode_m7(target_episode_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE episode pgreact_internal.agenda%ROWTYPE;
BEGIN
    SELECT * INTO STRICT episode FROM pgreact_internal.agenda WHERE episode_id = target_episode_id FOR UPDATE;
    PERFORM pgreact_internal.assert_rule_owner(episode.rule_version_id);
    IF episode.state NOT IN ('PENDING', 'RETRY_WAIT') THEN RAISE EXCEPTION 'only unleased episodes can be cancelled'; END IF;
    UPDATE pgreact_internal.agenda SET state = 'CANCELLED', completed_at = clock_timestamp() WHERE episode_id = target_episode_id;
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.canonical_key(components bytea[])
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    component bytea;
    result bytea;
BEGIN
    IF cardinality(components) NOT BETWEEN 1 AND 4
       OR array_position(components, NULL) IS NOT NULL THEN
        RAISE EXCEPTION 'M15_KEY_ARITY: semantic keys require one to four non-null components';
    END IF;
    result := decode('02' || lpad(to_hex(cardinality(components)), 2, '0'), 'hex');
    FOREACH component IN ARRAY components LOOP
        result := result || component;
    END LOOP;
    RETURN result;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.capture_match_delta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    version_id uuid := TG_ARGV[0]::uuid;
    key_name name;
    old_bindings jsonb;
    new_bindings jsonb;
    old_key bigint;
    new_key bigint;
    current_xid xid8 := pg_catalog.pg_current_xact_id();
BEGIN
    SELECT key_column INTO STRICT key_name
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = version_id;

    IF TG_OP <> 'INSERT' THEN
        old_bindings := to_jsonb(OLD);
        IF NOT old_bindings ? key_name::text OR old_bindings ->> key_name::text IS NULL THEN
            RAISE EXCEPTION 'pg-react key %.% must be non-null', TG_TABLE_NAME, key_name;
        END IF;
        old_key := (old_bindings ->> key_name::text)::bigint;
        INSERT INTO pgreact_internal.activation_delta_buffer (
            rule_version_id, semantic_key, xid, saw_update, saw_delete, before_bindings
        ) VALUES (
            version_id, old_key, current_xid,
            TG_OP = 'UPDATE' AND (to_jsonb(NEW) ->> key_name::text)::bigint = old_key,
            TG_OP = 'DELETE' OR (to_jsonb(NEW) ->> key_name::text)::bigint IS DISTINCT FROM old_key,
            old_bindings
        )
        ON CONFLICT (rule_version_id, semantic_key, xid) DO UPDATE SET
            saw_update = pgreact_internal.activation_delta_buffer.saw_update OR EXCLUDED.saw_update,
            saw_delete = pgreact_internal.activation_delta_buffer.saw_delete OR EXCLUDED.saw_delete,
            before_bindings = COALESCE(pgreact_internal.activation_delta_buffer.before_bindings,
                                       EXCLUDED.before_bindings);
    END IF;

    IF TG_OP <> 'DELETE' THEN
        new_bindings := to_jsonb(NEW);
        IF NOT new_bindings ? key_name::text OR new_bindings ->> key_name::text IS NULL THEN
            RAISE EXCEPTION 'pg-react key %.% must be non-null', TG_TABLE_NAME, key_name;
        END IF;
        new_key := (new_bindings ->> key_name::text)::bigint;
        INSERT INTO pgreact_internal.activation_delta_buffer (
            rule_version_id, semantic_key, xid, saw_insert, saw_update, after_bindings
        ) VALUES (
            version_id, new_key, current_xid,
            TG_OP = 'INSERT' OR old_key IS DISTINCT FROM new_key,
            TG_OP = 'UPDATE' AND old_key = new_key,
            new_bindings
        )
        ON CONFLICT (rule_version_id, semantic_key, xid) DO UPDATE SET
            saw_insert = pgreact_internal.activation_delta_buffer.saw_insert OR EXCLUDED.saw_insert,
            saw_update = pgreact_internal.activation_delta_buffer.saw_update OR EXCLUDED.saw_update,
            after_bindings = EXCLUDED.after_bindings;
    END IF;
    RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.claim_batch(target_version_id uuid, event_kind text, worker_id text, max_items integer DEFAULT 32, lease_for interval DEFAULT '00:01:00'::interval)
 RETURNS TABLE(batch_id uuid, item_order integer, episode_id bigint, lease_token uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    version_row pgreact_internal.rule_versions%ROWTYPE;
    binding pgreact_internal.consequence_bindings%ROWTYPE;
    candidate pgreact_internal.agenda%ROWTYPE;
    next_token uuid;
    next_batch uuid := gen_random_uuid();
    claimed integer := 0;
    seconds integer := extract(epoch FROM lease_for)::integer;
    expires_at timestamptz;
    fairness interval;
    lease_limit integer;
    group_limit integer;
    available_slots integer;
BEGIN
    IF worker_id IS NULL OR btrim(worker_id) = '' THEN
        RAISE EXCEPTION 'worker_id must not be empty';
    END IF;
    IF max_items NOT BETWEEN 2 AND 32 THEN
        RAISE EXCEPTION 'max_items must be between 2 and 32';
    END IF;
    SELECT fairness_window, max_lease_seconds INTO fairness, lease_limit
    FROM pgreact_internal.operational_settings;
    IF seconds NOT BETWEEN 1 AND lease_limit OR lease_for <> make_interval(secs => seconds) THEN
        RAISE EXCEPTION 'lease_for must be a whole number of seconds between 1 and %', lease_limit;
    END IF;
    expires_at := clock_timestamp() + lease_for;
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200000);
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200001);
    PERFORM pgreact.sweep_expired_leases(target_version_id);
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions v
    WHERE v.rule_version_id = target_version_id;
    SELECT * INTO binding FROM pgreact_internal.consequence_bindings b
    WHERE b.rule_version_id = target_version_id AND b.event_kind = claim_batch.event_kind;
    IF NOT FOUND OR binding.consequence_kind <> 'DATABASE_TYPED' OR binding.dispatcher_oid IS NULL THEN
        RAISE EXCEPTION 'batch claim requires one exact DATABASE_TYPED % binding', event_kind;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pgreact_internal.batch_declarations d
        WHERE d.rule_version_id = target_version_id AND d.event_kind = claim_batch.event_kind
    ) THEN
        RAISE EXCEPTION 'batch execution is not declared for rule version % event %',
            target_version_id, event_kind;
    END IF;
    IF version_row.state <> 'ACTIVE' THEN
        RAISE EXCEPTION 'rule version % is not executable in state %', target_version_id, version_row.state;
    END IF;
    IF EXISTS (SELECT 1 FROM pgreact_internal.rule_barriers b WHERE b.rule_version_id = target_version_id) THEN
        RAISE EXCEPTION 'pg-react claims are blocked for rule version %', target_version_id;
    END IF;
    IF pgreact_internal.source_row_signature(version_row.source_view_oid)
       IS DISTINCT FROM version_row.source_row_signature
       OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_proc WHERE oid = binding.function_oid)
       OR sha256(convert_to(pg_get_functiondef(binding.function_oid), 'UTF8')) <> binding.function_digest
       OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_proc WHERE oid = binding.dispatcher_oid)
       OR sha256(convert_to(pg_get_functiondef(binding.dispatcher_oid), 'UTF8')) <> binding.dispatcher_digest THEN
        RAISE EXCEPTION 'pg-react source, consequence, or dispatcher drift for rule version %', target_version_id;
    END IF;
    SELECT max_leases INTO group_limit FROM pgreact_internal.agenda_group_limits
    WHERE agenda_group = version_row.agenda_group;
    IF group_limit IS NOT NULL THEN
        available_slots := group_limit - (SELECT count(*) FROM pgreact_internal.agenda a
            WHERE a.agenda_group = version_row.agenda_group AND a.state = 'LEASED'
              AND a.lease_expires_at > clock_timestamp());
        IF available_slots < 2 THEN RETURN; END IF;
        max_items := LEAST(max_items, available_slots);
    END IF;
    INSERT INTO pgreact_internal.execution_batches (
        batch_id, rule_version_id, event_kind, worker_id, max_items,
        function_oid, function_identity, function_digest,
        dispatcher_oid, dispatcher_identity, dispatcher_digest,
        execution_role_oid, execution_role, recheck_policy, conflict_key_columns, state
    ) VALUES (
        next_batch, target_version_id, event_kind, worker_id, max_items,
        binding.function_oid, binding.function_identity, binding.function_digest,
        binding.dispatcher_oid, binding.dispatcher_identity, binding.dispatcher_digest,
        version_row.owner_oid, pg_get_userbyid(version_row.owner_oid), 'FRESH',
        version_row.conflict_key_columns, 'CLAIMED'
    );
    FOR candidate IN
        SELECT a.* FROM pgreact_internal.agenda a
        WHERE a.rule_version_id = target_version_id
          AND a.event_kind = claim_batch.event_kind
          AND a.consequence_kind = 'DATABASE_TYPED'
          AND a.state IN ('PENDING', 'RETRY_WAIT')
          AND a.available_at <= clock_timestamp()
          AND (a.conflict_key IS NULL OR NOT EXISTS (
              SELECT 1 FROM pgreact_internal.conflict_leases l
              WHERE l.rule_version_id = a.rule_version_id
                AND l.conflict_key = a.conflict_key
                AND l.lease_expires_at > clock_timestamp()
          ))
        ORDER BY CASE WHEN a.available_at <= clock_timestamp() - fairness THEN 0 ELSE 1 END,
                 a.available_at, a.salience DESC, a.episode_id
        LIMIT max_items
        FOR UPDATE SKIP LOCKED
    LOOP
        next_token := gen_random_uuid();
        IF candidate.conflict_key IS NOT NULL THEN
            BEGIN
                INSERT INTO pgreact_internal.conflict_leases (
                    rule_version_id, conflict_key, episode_id, lease_token, lease_expires_at
                ) VALUES (
                    candidate.rule_version_id, candidate.conflict_key,
                    candidate.episode_id, next_token, expires_at
                );
            EXCEPTION WHEN unique_violation THEN
                CONTINUE;
            END;
        END IF;
        claimed := claimed + 1;
        UPDATE pgreact_internal.agenda a
        SET state = 'LEASED', lease_token = next_token, worker_id = claim_batch.worker_id,
            claimed_at = clock_timestamp(), lease_expires_at = expires_at,
            attempt_count = attempt_count + 1
        WHERE a.episode_id = candidate.episode_id;
        INSERT INTO pgreact_internal.execution_batch_items (
            batch_id, item_order, episode_id, lease_token, attempt_no
        ) VALUES (next_batch, claimed, candidate.episode_id, next_token, candidate.attempt_count + 1);
    END LOOP;
    IF claimed < 2 THEN
        DELETE FROM pgreact_internal.conflict_leases l
        USING pgreact_internal.execution_batch_items i
        WHERE i.batch_id = next_batch AND l.episode_id = i.episode_id
          AND l.lease_token = i.lease_token;
        UPDATE pgreact_internal.agenda a
        SET state = 'PENDING', lease_token = NULL, worker_id = NULL,
            claimed_at = NULL, lease_expires_at = NULL,
            attempt_count = attempt_count - 1
        FROM pgreact_internal.execution_batch_items i
        WHERE i.batch_id = next_batch AND a.episode_id = i.episode_id
          AND a.lease_token = i.lease_token;
        DELETE FROM pgreact_internal.execution_batches b WHERE b.batch_id = next_batch;
        RETURN;
    END IF;
    RETURN QUERY
    SELECT i.batch_id, i.item_order, i.episode_id, i.lease_token
    FROM pgreact_internal.execution_batch_items i
    WHERE i.batch_id = next_batch ORDER BY i.item_order;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.claim_episode(target_version_id uuid, worker_id text, lease_seconds integer DEFAULT 60)
 RETURNS TABLE(episode_id bigint, lease_token uuid, activation_id uuid, bindings jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE episode pgreact_internal.agenda%ROWTYPE; token uuid := gen_random_uuid(); expires_at timestamptz;
    fairness interval; lease_limit integer; group_limit integer;
BEGIN
    SELECT fairness_window, max_lease_seconds INTO fairness, lease_limit FROM pgreact_internal.operational_settings;
    IF lease_seconds NOT BETWEEN 1 AND lease_limit THEN
        RAISE EXCEPTION 'lease_seconds must be between 1 and %', lease_limit;
    END IF;
    expires_at := clock_timestamp() + make_interval(secs => lease_seconds);
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200000);
    PERFORM pgreact.sweep_expired_leases(target_version_id);
    IF EXISTS (SELECT 1 FROM pgreact_internal.rule_barriers WHERE rule_version_id = target_version_id) THEN
        RAISE EXCEPTION 'pg-react claims are blocked for rule version %', target_version_id;
    END IF;
    SELECT a.* INTO episode FROM pgreact_internal.agenda a JOIN pgreact_internal.rule_versions v USING (rule_version_id)
    WHERE a.rule_version_id = target_version_id AND a.state IN ('PENDING', 'RETRY_WAIT') AND a.available_at <= clock_timestamp()
      AND v.state IN ('ACTIVE', 'DRAINING')
      AND (a.conflict_key IS NULL OR NOT EXISTS (SELECT 1 FROM pgreact_internal.conflict_leases l
          WHERE l.rule_version_id = a.rule_version_id AND l.conflict_key = a.conflict_key AND l.lease_expires_at > clock_timestamp()))
    ORDER BY CASE WHEN a.available_at <= clock_timestamp() - fairness THEN 0 ELSE 1 END,
             a.available_at, a.salience DESC, a.episode_id
    LIMIT 1 FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN RETURN; END IF;
    SELECT max_leases INTO group_limit FROM pgreact_internal.agenda_group_limits WHERE agenda_group = episode.agenda_group;
    IF group_limit IS NOT NULL AND (SELECT count(*) FROM pgreact_internal.agenda
        WHERE agenda_group = episode.agenda_group AND state = 'LEASED' AND lease_expires_at > clock_timestamp()) >= group_limit THEN
        RETURN;
    END IF;
    IF episode.conflict_key IS NOT NULL THEN
        BEGIN
            INSERT INTO pgreact_internal.conflict_leases VALUES (episode.rule_version_id, episode.conflict_key, episode.episode_id, token, expires_at);
        EXCEPTION WHEN unique_violation THEN RETURN;
        END;
    END IF;
    UPDATE pgreact_internal.agenda SET state = 'LEASED', lease_token = token, worker_id = claim_episode.worker_id,
        claimed_at = clock_timestamp(), lease_expires_at = expires_at, attempt_count = attempt_count + 1
    WHERE agenda.episode_id = episode.episode_id;
    RETURN QUERY SELECT episode.episode_id, token, episode.activation_id, COALESCE(episode.new_bindings, episode.old_bindings);
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.configure_roles_m14(author_role regrole, operator_role regrole, worker_role regrole, reader_role regrole, advanced_reader_role regrole)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE previous name;
BEGIN
    PERFORM pgreact_api.configure_roles(author_role, operator_role, worker_role, reader_role);
    SELECT role_oid::regrole::text INTO previous FROM pgreact_internal.advanced_readers;
    IF previous IS NOT NULL THEN
        EXECUTE format('REVOKE ALL ON FUNCTION pgreact_api.explain_advanced(uuid) FROM %I', previous);
        EXECUTE format('REVOKE USAGE ON SCHEMA pgreact_api FROM %I', previous);
    END IF;
    DELETE FROM pgreact_internal.advanced_readers;
    INSERT INTO pgreact_internal.advanced_readers VALUES (advanced_reader_role);
    EXECUTE format('GRANT USAGE ON SCHEMA pgreact_api TO %I', advanced_reader_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.explain_advanced(uuid) TO %I', advanced_reader_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.validate_program(jsonb), '
        'pgreact_api.preview_program(jsonb), pgreact_api.declare_derived_relation(text,regtype,name,integer), '
        'pgreact_api.deploy_program(jsonb,text), pgreact_api.remove_program(text,integer) TO %I', author_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.doctor(), '
        'pgreact_api.explain(text,bigint), pgreact_api.explain(text,uuid), '
        'pgreact_api.explain(text,bigint,boolean), pgreact_api.explain(text,boolean) TO %I', operator_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.doctor(), '
        'pgreact_api.explain(text,bigint), pgreact_api.explain(text,uuid), '
        'pgreact_api.explain(text,bigint,boolean), pgreact_api.explain(text,boolean) TO %I', reader_role::text);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.configure_roles_m22(author_role regrole, operator_role regrole, worker_role regrole, reader_role regrole, advanced_reader_role regrole)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE previous name;
BEGIN
    PERFORM pgreact_api.configure_roles(author_role, operator_role, worker_role, reader_role);
    SELECT role_oid::regrole::text INTO previous FROM pgreact_internal.advanced_readers;
    IF previous IS NOT NULL THEN
        EXECUTE format('REVOKE ALL ON FUNCTION pgreact_api.explain_provenance_advanced(uuid,bigint,integer,text) FROM %I', previous);
    END IF;
    DELETE FROM pgreact_internal.advanced_readers;
    INSERT INTO pgreact_internal.advanced_readers VALUES (advanced_reader_role);
    EXECUTE format('GRANT USAGE ON SCHEMA pgreact_api TO %I', advanced_reader_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.explain_provenance_advanced(uuid,bigint,integer,text) TO %I', advanced_reader_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.provenance_validate(uuid), pgreact_api.provenance_preview(uuid,bigint,integer) TO %I', author_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.provenance_status(uuid), pgreact_api.provenance_preview(uuid,bigint,integer), pgreact_api.explain_provenance(uuid,bigint,integer,text), pgreact_api.provenance_doctor() TO %I', reader_role::text);
    EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_api.provenance_status(uuid), pgreact_api.provenance_preview(uuid,bigint,integer), pgreact_api.explain_provenance(uuid,bigint,integer,text), pgreact_api.provenance_doctor() TO %I', operator_role::text);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.create_action_proxy(target_version_id uuid, event_kind text, action regprocedure, public_condition regclass, wrapper_condition regclass)
 RETURNS regprocedure
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    proxy_name name := ('m15_action_' || replace(gen_random_uuid()::text, '-', ''))::name;
    proxy_qualified text := format('%I.%I', 'pgreact_runtime', proxy_name);
    action_qualified text;
    has_context boolean;
    argument_declarations text;
    argument_types text;
    invocation text;
    proxy regprocedure;
BEGIN
    SELECT format('%I.%I', namespace.nspname, procedure.proname),
           procedure.proargtypes[0] = 'pgreact.activation_context'::regtype
    INTO STRICT action_qualified, has_context
    FROM pg_proc procedure
    JOIN pg_namespace namespace ON namespace.oid = procedure.pronamespace
    WHERE procedure.oid = action;
    IF event_kind = 'CHANGE' AND has_context THEN
        argument_declarations := format(
            'context pgreact.activation_context, old_row %s, new_row %s',
            wrapper_condition, wrapper_condition);
        argument_types := format('pgreact.activation_context,%s,%s', wrapper_condition, wrapper_condition);
        invocation := format(
            '%s($1, jsonb_populate_record(NULL::%s, to_jsonb($2)), jsonb_populate_record(NULL::%s, to_jsonb($3)))',
            action_qualified, public_condition, public_condition);
    ELSIF event_kind = 'CHANGE' THEN
        argument_declarations := format('old_row %s, new_row %s', wrapper_condition, wrapper_condition);
        argument_types := format('%s,%s', wrapper_condition, wrapper_condition);
        invocation := format(
            '%s(jsonb_populate_record(NULL::%s, to_jsonb($1)), jsonb_populate_record(NULL::%s, to_jsonb($2)))',
            action_qualified, public_condition, public_condition);
    ELSIF has_context THEN
        argument_declarations := format('context pgreact.activation_context, row_value %s', wrapper_condition);
        argument_types := format('pgreact.activation_context,%s', wrapper_condition);
        invocation := format(
            '%s($1, jsonb_populate_record(NULL::%s, to_jsonb($2)))',
            action_qualified, public_condition);
    ELSE
        argument_declarations := format('row_value %s', wrapper_condition);
        argument_types := wrapper_condition::text;
        invocation := format(
            '%s(jsonb_populate_record(NULL::%s, to_jsonb($1)))',
            action_qualified, public_condition);
    END IF;
    EXECUTE format(
        'CREATE FUNCTION %s(%s) RETURNS void LANGUAGE SQL SECURITY DEFINER '
        'SET search_path = pg_catalog, pg_temp AS $proxy$ SELECT %s $proxy$',
        proxy_qualified, argument_declarations, invocation);
    EXECUTE format('ALTER FUNCTION %s(%s) OWNER TO %I',
                   proxy_qualified, argument_types, session_user);
    proxy := to_regprocedure(format('%s(%s)', proxy_qualified, argument_types));
    INSERT INTO pgreact_internal.action_proxies VALUES (proxy, action);
    RETURN proxy;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.create_derivation_rule_m7(name text, definition regclass, key_columns name[], target_relation uuid, rule_version integer DEFAULT 1, bootstrap_policy text DEFAULT 'SEED_CURRENT'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    diagnostic record;
    version_id uuid;
    watched name[];
    active_activation record;
BEGIN
    SELECT * INTO diagnostic
    FROM pgreact.validate_derivation_rule(
        definition, target_relation, key_columns, rule_version)
    WHERE severity = 'ERROR' ORDER BY code LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react derivation validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.rules r
        JOIN pgreact_internal.rule_versions v USING (rule_id)
        WHERE r.rule_name = name AND v.state <> 'REMOVED'
    ) THEN
        RAISE EXCEPTION 'a non-removed rule named % already exists', name;
    END IF;
    version_id := pgreact_internal.register_reference_rule(
        name, definition, key_columns[1], NULL, bootstrap_policy);
    SELECT array_agg(a.attname ORDER BY a.attnum) INTO watched
    FROM pg_catalog.pg_attribute a
    WHERE a.attrelid = definition AND a.attnum > 0 AND NOT a.attisdropped
      AND a.attname <> key_columns[1];
    UPDATE pgreact_internal.rule_versions
    SET rule_kind = 'DERIVATION', change_columns = watched
    WHERE rule_version_id = version_id;
    INSERT INTO pgreact_internal.derivation_rule_versions (
        rule_version_id, rule_id, relation_version_id, version
    ) SELECT version_id, rule_id, target_relation, rule_version
    FROM pgreact_internal.rule_versions WHERE rule_version_id = version_id;
    FOR active_activation IN
        SELECT activation_id FROM pgreact_internal.activation_state
        WHERE rule_version_id = version_id AND active
    LOOP
        PERFORM pgreact_internal.maintain_derived_support(
            version_id, active_activation.activation_id);
    END LOOP;
    RETURN version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.create_key_wrapper(condition regclass, key_columns name[])
 RETURNS regclass
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    key_column name;
    key_type oid;
    computed_name name := ('m15_key_base_' || md5(condition::text || ':' || key_columns::text))::name;
    wrapper_name name := ('m15_key_' || md5(condition::text || ':' || key_columns::text))::name;
    wrapper regclass;
    components text[] := ARRAY[]::text[];
    public_values text[] := ARRAY[]::text[];
    canonical_expression text;
BEGIN
    PERFORM pgreact_internal.assert_key_columns(condition, key_columns);
    FOREACH key_column IN ARRAY key_columns LOOP
        SELECT atttypid INTO STRICT key_type
        FROM pg_attribute
        WHERE attrelid = condition AND attname = key_column
          AND attnum > 0 AND NOT attisdropped;
        components := components || CASE key_type
            WHEN 'bigint'::regtype THEN format(
                '(decode(''01'' || lpad(to_hex(octet_length(int8send(m.%1$I))), 8, ''0''), ''hex'') || int8send(m.%1$I))',
                key_column)
            WHEN 'uuid'::regtype THEN format(
                '(decode(''02'' || lpad(to_hex(octet_length(uuid_send(m.%1$I))), 8, ''0''), ''hex'') || uuid_send(m.%1$I))',
                key_column)
            WHEN 'text'::regtype THEN format(
                '(decode(''03'' || lpad(to_hex(octet_length(convert_to(m.%1$I, ''UTF8''))), 8, ''0''), ''hex'') || convert_to(m.%1$I, ''UTF8''))',
                key_column)
        END;
        public_values := public_values || format('to_jsonb(m.%I)', key_column);
    END LOOP;
    canonical_expression := format(
        '(decode(''02'' || lpad(to_hex(%s), 2, ''0''), ''hex'') || %s)',
        cardinality(key_columns), array_to_string(components, ' || '));
    EXECUTE format(
        'CREATE OR REPLACE VIEW pgreact_runtime.%I WITH (security_barrier=true) AS '
        'SELECT m.*, %s AS __pgreact_canonical, '
        '(''x'' || encode(substring(sha256(%s) FROM 1 FOR 8), ''hex''))::bit(64)::bigint '
        'AS __pgreact_key, %s AS __pgreact_public_key '
        'FROM %s m',
        computed_name, canonical_expression, canonical_expression,
        CASE WHEN cardinality(public_values) = 1 THEN public_values[1]
             ELSE format('jsonb_build_array(%s)', array_to_string(public_values, ', ')) END,
        condition);
    EXECUTE format(
        'CREATE OR REPLACE VIEW pgreact_runtime.%I WITH (security_barrier=true) AS '
        'SELECT * FROM pgreact_runtime.%I', wrapper_name, computed_name);
    EXECUTE format('ALTER VIEW pgreact_runtime.%I OWNER TO %I', computed_name, session_user);
    EXECUTE format('ALTER VIEW pgreact_runtime.%I OWNER TO %I', wrapper_name, session_user);
    EXECUTE format('GRANT USAGE ON SCHEMA pgreact_runtime TO %I', session_user);
    wrapper := format('pgreact_runtime.%I', wrapper_name)::regclass;
    INSERT INTO pgreact_internal.key_wrappers VALUES (wrapper, condition)
    ON CONFLICT (wrapper_condition) DO UPDATE
    SET public_condition = EXCLUDED.public_condition;
    RETURN wrapper;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.decision_result(row_data jsonb, columns name[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE column_name name;
    result jsonb := '{}'::jsonb;
BEGIN
    FOREACH column_name IN ARRAY columns LOOP
        result := result || jsonb_build_object(column_name::text, row_data -> (column_name::text));
    END LOOP;
    RETURN result;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.declare_batch_safe(target_version_id uuid, event_kind text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    version_row pgreact_internal.rule_versions%ROWTYPE;
    binding pgreact_internal.consequence_bindings%ROWTYPE;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200001);
    version_row := pgreact_internal.assert_rule_owner(target_version_id);
    IF event_kind NOT IN ('ACTIVATE', 'CHANGE', 'DEACTIVATE') THEN
        RAISE EXCEPTION 'unsupported lifecycle event %', event_kind;
    END IF;
    SELECT * INTO binding FROM pgreact_internal.consequence_bindings b
    WHERE b.rule_version_id = target_version_id AND b.event_kind = declare_batch_safe.event_kind
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'rule version % has no % consequence binding', target_version_id, event_kind;
    END IF;
    IF binding.consequence_kind <> 'DATABASE_TYPED' OR binding.dispatcher_oid IS NULL THEN
        RAISE EXCEPTION 'only DATABASE_TYPED consequences can be declared batch-safe';
    END IF;
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.lifecycle_events e
        WHERE e.rule_version_id = target_version_id AND e.event_kind = declare_batch_safe.event_kind
    ) THEN
        RAISE EXCEPTION 'batch safety must be declared before the first % lifecycle event', event_kind;
    END IF;
    IF pgreact_internal.source_row_signature(version_row.source_view_oid)
       IS DISTINCT FROM version_row.source_row_signature
       OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_proc WHERE oid = binding.function_oid)
       OR sha256(convert_to(pg_get_functiondef(binding.function_oid), 'UTF8')) <> binding.function_digest
       OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_proc WHERE oid = binding.dispatcher_oid)
       OR sha256(convert_to(pg_get_functiondef(binding.dispatcher_oid), 'UTF8')) <> binding.dispatcher_digest THEN
        RAISE EXCEPTION 'cannot declare a drifted source or consequence batch-safe';
    END IF;
    INSERT INTO pgreact_internal.batch_declarations (rule_version_id, event_kind)
    VALUES (target_version_id, event_kind);
EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'batch safety is already declared for rule version % event %',
        target_version_id, event_kind;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.deploy_derivation_program(definition jsonb, target_pack_version uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    logical_program uuid;
    next_program uuid := gen_random_uuid();
    prior_program uuid;
    component_row record;
    rule_item record;
    input_item record;
    current_rule record;
    target_relation uuid;
    source_oid oid;
    source_digest bytea;
    component_id uuid;
    next_rule uuid;
    orphan_rule uuid;
    watched name[];
    active_activation record;
    removed_rule record;
    diagnostic record;
    caller_oid oid := (
        SELECT oid FROM pg_catalog.pg_roles WHERE rolname = session_user
    );
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200001);
    SELECT * INTO diagnostic
    FROM pgreact.validate_derivation_program(definition) d
    WHERE d.severity = 'ERROR'
    ORDER BY d.code, d.object_identity
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react derivation-program validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    SELECT p.program_id, v.program_version_id
    INTO logical_program, prior_program
    FROM pgreact_internal.derivation_programs p
    LEFT JOIN pgreact_internal.derivation_program_versions v
      ON v.program_id = p.program_id AND v.state = 'ACTIVE'
    WHERE p.program_name = definition ->> 'name';
    IF logical_program IS NULL THEN
        logical_program := gen_random_uuid();
        INSERT INTO pgreact_internal.derivation_programs (
            program_id, program_name, owner_oid
        ) VALUES (logical_program, definition ->> 'name', caller_oid);
    ELSIF NOT EXISTS (
        SELECT 1 FROM pgreact_internal.derivation_programs
        WHERE program_id = logical_program
          AND (owner_oid = caller_oid OR pgreact_internal.is_operator_admin())
    ) THEN
        RAISE EXCEPTION 'only the derivation-program owner or pgreact_admin may replace %',
            definition ->> 'name';
    END IF;
    IF prior_program IS NOT NULL AND EXISTS (
        SELECT 1 FROM pgreact_internal.derivation_program_versions
        WHERE program_version_id = prior_program
          AND version = (definition ->> 'version')::integer
          AND definition = deploy_derivation_program.definition
    ) THEN
        RETURN prior_program;
    END IF;
    UPDATE pgreact_internal.derivation_program_versions
    SET state = 'REMOVED'
    WHERE program_version_id = prior_program;
    FOR removed_rule IN
        SELECT r.rule_version_id
        FROM pgreact_internal.derivation_program_rules r
        WHERE r.program_version_id = prior_program
          AND NOT EXISTS (
              SELECT 1 FROM jsonb_array_elements(definition -> 'rules') incoming
              WHERE incoming ->> 'name' = r.rule_name
          )
        ORDER BY r.rule_order DESC, r.rule_name DESC
    LOOP
        PERFORM pgreact_internal.retire_derivation_rule(
            removed_rule.rule_version_id);
    END LOOP;
    INSERT INTO pgreact_internal.derivation_program_versions (
        program_version_id, program_id, pack_version_id, version,
        owner_oid, definition, definition_digest, max_iterations,
        max_facts, state
    ) VALUES (
        next_program, logical_program, target_pack_version,
        (definition ->> 'version')::integer, caller_oid, definition,
        sha256(convert_to(definition::text, 'UTF8')),
        (definition ->> 'max_iterations')::integer,
        (definition ->> 'max_facts')::bigint, 'ACTIVE'
    );
    FOR component_row IN
        SELECT * FROM pgreact_internal.derivation_program_components(definition)
    LOOP
        INSERT INTO pgreact_internal.derivation_program_components (
            program_version_id, component_id, component_order, cyclic,
            rule_names, target_relations
        ) SELECT
            next_program, component_row.component_id,
            component_row.component_order, component_row.cyclic,
            component_row.rule_names,
            ARRAY(
                SELECT v.relation_version_id
                FROM unnest(component_row.target_names) WITH ORDINALITY names(name, ordinal)
                JOIN pgreact_internal.derived_relations r ON r.relation_name = names.name
                JOIN pgreact_internal.derived_relation_versions v USING (relation_id)
                WHERE v.state = 'ACTIVE' ORDER BY names.ordinal
            );
    END LOOP;

    FOR rule_item IN
        SELECT value, ordinal
        FROM jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY r(value, ordinal)
        ORDER BY ordinal
    LOOP
        source_oid := pg_catalog.to_regclass(rule_item.value ->> 'definition');
        source_digest := pgreact_internal.source_closure_digest(source_oid);
        SELECT v.relation_version_id INTO STRICT target_relation
        FROM pgreact_internal.derived_relations r
        JOIN pgreact_internal.derived_relation_versions v USING (relation_id)
        WHERE r.relation_name = rule_item.value ->> 'target'
          AND v.state = 'ACTIVE';
        SELECT c.component_id INTO STRICT component_id
        FROM pgreact_internal.derivation_program_components c
        WHERE c.program_version_id = next_program
          AND rule_item.value ->> 'name' = ANY (c.rule_names);
        SELECT v.rule_version_id, v.rule_id, v.rule_kind,
               v.source_view_name, v.source_definition,
               d.version, d.relation_version_id,
               prior_member.source_definition_digest
        INTO current_rule
        FROM pgreact_internal.rules r
        JOIN pgreact_internal.rule_versions v USING (rule_id)
        LEFT JOIN pgreact_internal.derivation_rule_versions d USING (rule_version_id)
        LEFT JOIN pgreact_internal.derivation_program_rules prior_member
          ON prior_member.program_version_id = prior_program
         AND prior_member.rule_version_id = v.rule_version_id
        WHERE r.rule_name = rule_item.value ->> 'name'
          AND v.state <> 'REMOVED'
        ORDER BY v.created_at DESC LIMIT 1;
        IF FOUND AND current_rule.rule_kind = 'DERIVATION'
           AND current_rule.version = (rule_item.value ->> 'version')::integer
           AND current_rule.source_view_name = rule_item.value ->> 'definition'
           AND current_rule.source_definition = pg_catalog.pg_get_viewdef(source_oid, true)
           AND current_rule.source_definition_digest = source_digest
           AND current_rule.relation_version_id = target_relation THEN
            next_rule := current_rule.rule_version_id;
        ELSE
            IF FOUND AND (current_rule.rule_kind <> 'DERIVATION'
               OR current_rule.version >= (rule_item.value ->> 'version')::integer) THEN
                RAISE EXCEPTION 'immutable rule version conflict for program rule %',
                    rule_item.value ->> 'name';
            END IF;
            IF FOUND THEN
                UPDATE pgreact_internal.rule_versions SET state = 'REMOVED'
                WHERE rule_version_id = current_rule.rule_version_id;
            END IF;
            next_rule := pgreact_internal.register_reference_rule(
                rule_item.value ->> 'name', source_oid::regclass,
                (rule_item.value ->> 'key')::name, NULL, 'SEED_CURRENT');
            SELECT array_agg(a.attname ORDER BY a.attnum) INTO watched
            FROM pg_catalog.pg_attribute a
            WHERE a.attrelid = source_oid AND a.attnum > 0 AND NOT a.attisdropped
              AND a.attname <> (rule_item.value ->> 'key')::name;
            UPDATE pgreact_internal.rule_versions
            SET rule_kind = 'DERIVATION', change_columns = watched
            WHERE rule_version_id = next_rule;
            INSERT INTO pgreact_internal.derivation_rule_versions (
                rule_version_id, rule_id, relation_version_id, version
            ) SELECT next_rule, rule_id, target_relation,
                     (rule_item.value ->> 'version')::integer
              FROM pgreact_internal.rule_versions
              WHERE rule_version_id = next_rule;
            IF current_rule.rule_version_id IS NOT NULL THEN
                SELECT rule_id INTO STRICT orphan_rule
                FROM pgreact_internal.rule_versions
                WHERE rule_version_id = next_rule;
                UPDATE pgreact_internal.rule_versions SET rule_id = current_rule.rule_id
                WHERE rule_version_id = next_rule;
                UPDATE pgreact_internal.derivation_rule_versions SET rule_id = current_rule.rule_id
                WHERE rule_version_id = next_rule;
                DELETE FROM pgreact_internal.rules WHERE rule_id = orphan_rule;
                PERFORM pgreact_internal.retire_derivation_rule(
                    current_rule.rule_version_id);
            END IF;
        END IF;
        INSERT INTO pgreact_internal.derivation_program_rules (
            program_version_id, rule_version_id, rule_name, rule_order,
            component_id, source_view_oid, source_view_name,
            source_definition, source_definition_digest,
            target_relation_version_id
        ) VALUES (
            next_program, next_rule, rule_item.value ->> 'name',
            rule_item.ordinal, component_id, source_oid,
            rule_item.value ->> 'definition',
            pg_catalog.pg_get_viewdef(source_oid, true),
            source_digest,
            target_relation
        );
        FOR input_item IN
            SELECT value, ordinal
            FROM jsonb_array_elements(rule_item.value -> 'inputs')
            WITH ORDINALITY i(value, ordinal)
        LOOP
            INSERT INTO pgreact_internal.derivation_program_inputs (
                program_version_id, rule_version_id, input_order,
                relation_version_id, key_column
            ) SELECT
                next_program, next_rule, input_item.ordinal,
                v.relation_version_id, (input_item.value ->> 'key')::name
            FROM pgreact_internal.derived_relations r
            JOIN pgreact_internal.derived_relation_versions v USING (relation_id)
            WHERE r.relation_name = input_item.value ->> 'relation'
              AND v.state = 'ACTIVE';
        END LOOP;
        FOR active_activation IN
            SELECT activation_id
            FROM pgreact_internal.activation_state
            WHERE rule_version_id = next_rule AND active
            ORDER BY activation_id
        LOOP
            PERFORM pgreact_internal.maintain_derived_support(
                next_rule, active_activation.activation_id);
        END LOOP;
    END LOOP;
    PERFORM pgreact_internal.rebuild_derivation_program(next_program, true);
    RETURN next_program;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.deploy_pack(definition jsonb, expected_plan_digest text, mappings jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    diagnostic record;
    actual_digest text;
    v1_definition jsonb;
    v1_digest text;
    pack_version uuid;
    prior_pack_version uuid;
    item record;
    relation_item record;
    current_relation record;
    target_relation uuid;
    current_rule record;
    next_version uuid;
    prior_version uuid;
    mapped_name text;
    mapped_type text;
    mapped_source text;
    dependency_names text[];
    action_name text;
    action_number integer := 0;
BEGIN
    IF NOT (definition ? 'derived_relations' OR definition ? 'derivations'
            OR definition ? 'remove_derivations' OR definition ? 'remove_derived_relations') THEN
        RETURN pgreact_internal.deploy_pack_v1(definition, expected_plan_digest, mappings);
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200001);
    SELECT * INTO diagnostic FROM pgreact.validate_pack(definition, mappings) d
    WHERE d.severity = 'ERROR' ORDER BY d.code, d.object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react pack validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    actual_digest := pgreact_internal.m7_pack_plan_digest(definition, mappings);
    IF expected_plan_digest IS DISTINCT FROM actual_digest THEN
        RAISE EXCEPTION 'rule-pack preview is stale'
            USING HINT = 'Run pgreact.preview_pack again after concurrent DDL, support, or deployment changes.',
                  DETAIL = format('expected %s, current %s', expected_plan_digest, actual_digest);
    END IF;
    SELECT v.pack_version_id INTO prior_pack_version
    FROM pgreact_internal.rule_packs p
    JOIN pgreact_internal.rule_pack_versions v USING (pack_id)
    WHERE p.pack_name = definition ->> 'pack' AND v.state = 'ACTIVE';

    FOR item IN
        SELECT value FROM jsonb_array_elements(definition -> 'derived_relations') value
    LOOP
        mapped_name := pgreact_internal.pack_mapping(
            mappings, 'objects', item.value ->> 'name');
        mapped_type := pgreact_internal.pack_mapping(
            mappings, 'objects', item.value ->> 'row_type');
        SELECT v.relation_version_id, v.version INTO current_relation
        FROM pgreact_internal.derived_relations r
        JOIN pgreact_internal.derived_relation_versions v USING (relation_id)
        WHERE r.relation_name = mapped_name AND v.state = 'ACTIVE';
        IF current_relation.relation_version_id IS NULL THEN
            PERFORM pgreact.create_derived_relation(
                mapped_name, to_regtype(mapped_type),
                ARRAY[(item.value ->> 'key')::name],
                (item.value ->> 'version')::integer);
        ELSIF current_relation.version < (item.value ->> 'version')::integer THEN
            PERFORM pgreact_internal.replace_derived_relation(
                current_relation.relation_version_id, to_regtype(mapped_type),
                ARRAY[(item.value ->> 'key')::name],
                (item.value ->> 'version')::integer);
        END IF;
    END LOOP;

    FOR item IN
        SELECT value FROM jsonb_array_elements(definition -> 'derivations') value
    LOOP
        mapped_source := pgreact_internal.pack_mapping(
            mappings, 'objects', item.value ->> 'definition');
        mapped_name := pgreact_internal.pack_mapping(
            mappings, 'objects', item.value ->> 'target');
        SELECT v.relation_version_id INTO STRICT target_relation
        FROM pgreact_internal.derived_relations r
        JOIN pgreact_internal.derived_relation_versions v USING (relation_id)
        WHERE r.relation_name = mapped_name AND v.state = 'ACTIVE';
        SELECT v.rule_version_id, v.rule_kind, v.source_view_name,
               v.source_definition, d.version, d.relation_version_id
        INTO current_rule
        FROM pgreact_internal.rules r
        JOIN pgreact_internal.rule_versions v USING (rule_id)
        LEFT JOIN pgreact_internal.derivation_rule_versions d USING (rule_version_id)
        WHERE r.rule_name = item.value ->> 'name' AND v.state <> 'REMOVED'
        ORDER BY v.created_at DESC LIMIT 1;
        IF current_rule.rule_version_id IS NULL THEN
            PERFORM pgreact.create_derivation_rule(
                item.value ->> 'name', to_regclass(mapped_source),
                ARRAY[(item.value ->> 'key')::name], target_relation,
                (item.value ->> 'version')::integer,
                COALESCE(item.value ->> 'bootstrap_policy', 'SEED_CURRENT'));
        ELSIF current_rule.rule_kind <> 'DERIVATION' THEN
            RAISE EXCEPTION 'cannot replace non-derivation rule % with a derivation',
                item.value ->> 'name';
        ELSIF current_rule.version = (item.value ->> 'version')::integer
              AND current_rule.source_view_name = mapped_source
              AND current_rule.source_definition = pg_get_viewdef(to_regclass(mapped_source), true)
              AND current_rule.relation_version_id = target_relation THEN
            NULL;
        ELSIF current_rule.version >= (item.value ->> 'version')::integer THEN
            RAISE EXCEPTION 'immutable derivation version % already exists for %',
                current_rule.version, item.value ->> 'name';
        ELSE
            PERFORM pgreact.replace_derivation_rule(
                current_rule.rule_version_id, to_regclass(mapped_source),
                ARRAY[(item.value ->> 'key')::name],
                (item.value ->> 'version')::integer,
                COALESCE(item.value ->> 'bootstrap_policy', 'SEED_CURRENT'));
        END IF;
    END LOOP;

    v1_definition := pgreact_internal.m7_pack_definition(definition);
    v1_digest := pgreact_internal.pack_plan_digest(v1_definition, mappings);
    PERFORM pgreact_internal.maybe_fail_pack('derived');
    pack_version := pgreact_internal.deploy_pack_v1(v1_definition, v1_digest, mappings);
    UPDATE pgreact_internal.rule_pack_versions SET
        definition = deploy_pack.definition,
        definition_digest = sha256(convert_to(deploy_pack.definition::text, 'UTF8')),
        plan_digest = actual_digest
    WHERE pack_version_id = pack_version;

    FOR item IN
        SELECT value FROM jsonb_array_elements(definition -> 'derived_relations') value
    LOOP
        action_number := action_number + 1;
        mapped_name := pgreact_internal.pack_mapping(
            mappings, 'objects', item.value ->> 'name');
        SELECT v.relation_version_id INTO STRICT next_version
        FROM pgreact_internal.derived_relations r
        JOIN pgreact_internal.derived_relation_versions v USING (relation_id)
        WHERE r.relation_name = mapped_name AND v.state = 'ACTIVE';
        SELECT relation_version_id INTO prior_version
        FROM pgreact_internal.rule_pack_derived_relations
        WHERE pack_version_id = prior_pack_version
          AND relation_name = item.value ->> 'name';
        action_name := CASE WHEN prior_version IS NULL THEN 'ADD'
                            WHEN prior_version = next_version THEN 'KEEP'
                            ELSE 'REPLACE' END;
        INSERT INTO pgreact_internal.rule_pack_derived_relations VALUES (
            pack_version, item.value ->> 'name', next_version);
        INSERT INTO pgreact_internal.rule_pack_derived_actions VALUES (
            pack_version, action_number, 'DERIVED_RELATION', action_name,
            item.value ->> 'name', prior_version, next_version,
            jsonb_build_object('mapped_name', mapped_name,
                               'version', (item.value ->> 'version')::integer));
    END LOOP;
    FOR item IN
        SELECT value FROM jsonb_array_elements(definition -> 'derivations') value
    LOOP
        action_number := action_number + 1;
        SELECT v.rule_version_id INTO STRICT next_version
        FROM pgreact_internal.rules r
        JOIN pgreact_internal.rule_versions v USING (rule_id)
        WHERE r.rule_name = item.value ->> 'name' AND v.state <> 'REMOVED'
        ORDER BY v.created_at DESC LIMIT 1;
        SELECT rule_version_id INTO prior_version
        FROM pgreact_internal.rule_pack_derivations
        WHERE pack_version_id = prior_pack_version
          AND rule_name = item.value ->> 'name';
        SELECT array_agg(value #>> '{}' ORDER BY ordinal)::text[] INTO dependency_names
        FROM jsonb_array_elements(COALESCE(item.value -> 'depends_on', '[]'::jsonb))
        WITH ORDINALITY d(value, ordinal);
        action_name := CASE WHEN prior_version IS NULL THEN 'ADD'
                            WHEN prior_version = next_version THEN 'KEEP'
                            ELSE 'REPLACE' END;
        INSERT INTO pgreact_internal.rule_pack_derivations VALUES (
            pack_version, item.value ->> 'name', next_version,
            item.value ->> 'target', COALESCE(dependency_names, ARRAY[]::text[]));
        INSERT INTO pgreact_internal.rule_pack_derived_actions VALUES (
            pack_version, action_number, 'DERIVATION', action_name,
            item.value ->> 'name', prior_version, next_version,
            jsonb_build_object('target', item.value ->> 'target',
                               'dependencies', COALESCE(to_jsonb(dependency_names), '[]'::jsonb)));
    END LOOP;

    FOR item IN
        SELECT value FROM jsonb_array_elements(definition -> 'remove_derivations') value
    LOOP
        action_number := action_number + 1;
        SELECT rule_version_id INTO STRICT prior_version
        FROM pgreact_internal.rule_pack_derivations
        WHERE pack_version_id = prior_pack_version
          AND rule_name = item.value ->> 'name';
        PERFORM pgreact_internal.retire_derivation_rule(prior_version);
        INSERT INTO pgreact_internal.rule_pack_derived_actions VALUES (
            pack_version, action_number, 'DERIVATION', 'REMOVE',
            item.value ->> 'name', prior_version, NULL, '{}'::jsonb);
    END LOOP;
    FOR item IN
        SELECT value FROM jsonb_array_elements(definition -> 'remove_derived_relations') value
    LOOP
        action_number := action_number + 1;
        SELECT relation_version_id INTO STRICT prior_version
        FROM pgreact_internal.rule_pack_derived_relations
        WHERE pack_version_id = prior_pack_version
          AND relation_name = item.value ->> 'name';
        PERFORM pgreact_internal.remove_derived_relation(prior_version);
        INSERT INTO pgreact_internal.rule_pack_derived_actions VALUES (
            pack_version, action_number, 'DERIVED_RELATION', 'REMOVE',
            item.value ->> 'name', prior_version, NULL, '{}'::jsonb);
    END LOOP;
    RETURN pack_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.deploy_pack_v1(definition jsonb, expected_plan_digest text, mappings jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    diagnostic record;
    actual_plan_digest text;
    caller_oid oid := (SELECT oid FROM pg_catalog.pg_roles WHERE rolname = session_user);
    pack_id uuid;
    prior_pack_version uuid;
    next_pack_version uuid := gen_random_uuid();
    rule_item record;
    current_version uuid;
    next_rule_version uuid;
    source_oid oid;
    on_activate_oid oid;
    on_deactivate_oid oid;
    on_change_oid oid;
    change_columns name[];
    conflict_columns name[];
    dependencies text[];
    policy text;
    action_name text;
    action_number integer := 0;
    outbox_item record;
BEGIN
    -- ponytail: global deployment/DDL locks are the smallest correct boundary;
    -- shard by pack only if measured deployment concurrency requires it.
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200001);
    SELECT * INTO diagnostic FROM pgreact.validate_pack(definition, mappings)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react pack validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    actual_plan_digest := pgreact_internal.pack_plan_digest(definition, mappings);
    IF expected_plan_digest IS DISTINCT FROM actual_plan_digest THEN
        RAISE EXCEPTION 'rule-pack preview is stale'
            USING HINT = 'Run pgreact.preview_pack again after concurrent DDL, work, or deployment changes.',
                  DETAIL = format('expected %s, current %s', expected_plan_digest, actual_plan_digest);
    END IF;
    SELECT p.pack_id INTO pack_id FROM pgreact_internal.rule_packs p
    WHERE p.owner_oid = caller_oid AND p.pack_name = definition ->> 'pack';
    IF pack_id IS NULL THEN
        pack_id := gen_random_uuid();
        INSERT INTO pgreact_internal.rule_packs(pack_id, pack_name, owner_oid)
        VALUES (pack_id, definition ->> 'pack', caller_oid);
    ELSE
        SELECT v.pack_version_id INTO prior_pack_version
        FROM pgreact_internal.rule_pack_versions v
        WHERE v.pack_id = pack_id AND v.state = 'ACTIVE';
    END IF;
    INSERT INTO pgreact_internal.rule_pack_versions(
        pack_version_id, pack_id, version, definition, mappings, definition_digest,
        plan_digest, state, deployed_by
    ) VALUES (
        next_pack_version, pack_id, definition ->> 'version', definition, mappings,
        sha256(convert_to(definition::text, 'UTF8')), actual_plan_digest, 'STAGED', session_user
    );
    PERFORM pgreact_internal.maybe_fail_pack('catalog');

    FOR rule_item IN
        SELECT value, ordinal FROM pg_catalog.jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY AS r(value, ordinal) ORDER BY ordinal
    LOOP
        action_number := action_number + 1;
        SELECT v.rule_version_id INTO current_version
        FROM pgreact_internal.rules r JOIN pgreact_internal.rule_versions v USING (rule_id)
        WHERE r.rule_name = rule_item.value ->> 'name' AND v.state <> 'REMOVED'
        ORDER BY v.created_at DESC LIMIT 1;
        source_oid := pg_catalog.to_regclass(pgreact_internal.pack_mapping(
            mappings, 'objects', rule_item.value ->> 'definition'));
        on_activate_oid := pg_catalog.to_regprocedure(pgreact_internal.pack_mapping(
            mappings, 'objects', rule_item.value ->> 'on_activate'));
        on_deactivate_oid := pg_catalog.to_regprocedure(pgreact_internal.pack_mapping(
            mappings, 'objects', rule_item.value ->> 'on_deactivate'));
        on_change_oid := pg_catalog.to_regprocedure(pgreact_internal.pack_mapping(
            mappings, 'objects', rule_item.value ->> 'on_change'));
        SELECT array_agg(value #>> '{}' ORDER BY ordinal)::name[] INTO change_columns
        FROM pg_catalog.jsonb_array_elements(rule_item.value -> 'change_columns')
        WITH ORDINALITY AS c(value, ordinal);
        SELECT array_agg(value #>> '{}' ORDER BY ordinal)::name[] INTO conflict_columns
        FROM pg_catalog.jsonb_array_elements(rule_item.value -> 'conflict_key_columns')
        WITH ORDINALITY AS c(value, ordinal);
        SELECT array_agg(value #>> '{}' ORDER BY ordinal)::text[] INTO dependencies
        FROM pg_catalog.jsonb_array_elements(COALESCE(rule_item.value -> 'depends_on', '[]'::jsonb))
        WITH ORDINALITY AS d(value, ordinal);
        policy := COALESCE(rule_item.value ->> 'old_work_policy', 'DRAIN_OLD');
        action_name := CASE WHEN current_version IS NULL THEN 'ADD' ELSE 'REPLACE' END;
        IF current_version IS NULL THEN
            next_rule_version := pgreact.create_rule(
                rule_item.value ->> 'name', source_oid::regclass,
                ARRAY[(rule_item.value ->> 'key')::name], rule_item.value ->> 'kind',
                on_activate_oid::regprocedure, on_deactivate_oid::regprocedure, on_change_oid::regprocedure,
                COALESCE(rule_item.value ->> 'bootstrap_policy', 'SEED_CURRENT'), change_columns,
                COALESCE((rule_item.value ->> 'salience')::integer, 0),
                COALESCE(rule_item.value ->> 'agenda_group', 'default'), conflict_columns,
                COALESCE((rule_item.value ->> 'max_attempts')::integer, 1),
                COALESCE((rule_item.value ->> 'initial_backoff_seconds')::integer, 1),
                COALESCE((rule_item.value ->> 'backoff_multiplier')::numeric, 2),
                COALESCE((rule_item.value ->> 'max_backoff_seconds')::integer, 60));
        ELSE
            next_rule_version := pgreact_internal.replace_pack_rule(
                current_version, rule_item.value ->> 'name', source_oid::regclass,
                ARRAY[(rule_item.value ->> 'key')::name], rule_item.value ->> 'kind',
                on_activate_oid::regprocedure, on_deactivate_oid::regprocedure, on_change_oid::regprocedure,
                COALESCE(rule_item.value ->> 'bootstrap_policy', 'SEED_CURRENT'), change_columns,
                COALESCE((rule_item.value ->> 'salience')::integer, 0),
                COALESCE(rule_item.value ->> 'agenda_group', 'default'), conflict_columns,
                COALESCE((rule_item.value ->> 'max_attempts')::integer, 1),
                COALESCE((rule_item.value ->> 'initial_backoff_seconds')::integer, 1),
                COALESCE((rule_item.value ->> 'backoff_multiplier')::numeric, 2),
                COALESCE((rule_item.value ->> 'max_backoff_seconds')::integer, 60), policy);
        END IF;
        FOR outbox_item IN
            SELECT key AS event_kind, value #>> '{}' AS identity
            FROM pg_catalog.jsonb_each(COALESCE(rule_item.value -> 'outbox', '{}'::jsonb))
        LOOP
            PERFORM pgreact.bind_outbox_consequence(next_rule_version, outbox_item.event_kind,
                pg_catalog.to_regprocedure(pgreact_internal.pack_mapping(mappings, 'objects', outbox_item.identity)),
                COALESCE((rule_item.value ->> 'max_attempts')::integer, 1),
                COALESCE((rule_item.value ->> 'initial_backoff_seconds')::integer, 1),
                COALESCE((rule_item.value ->> 'backoff_multiplier')::numeric, 2),
                COALESCE((rule_item.value ->> 'max_backoff_seconds')::integer, 60));
        END LOOP;
        INSERT INTO pgreact_internal.rule_pack_members
            (pack_version_id, rule_name, rule_version_id, dependencies)
        VALUES (next_pack_version, rule_item.value ->> 'name', next_rule_version,
                COALESCE(dependencies, ARRAY[]::text[]));
        INSERT INTO pgreact_internal.rule_pack_actions(
            pack_version_id, action_order, action, rule_name, old_rule_version_id,
            new_rule_version_id, old_work_policy, details
        ) VALUES (
            next_pack_version, action_number, action_name, rule_item.value ->> 'name',
            current_version, next_rule_version, policy,
            jsonb_build_object('dependencies', COALESCE(to_jsonb(dependencies), '[]'::jsonb),
                               'source', rule_item.value ->> 'definition')
        );
        current_version := NULL;
    END LOOP;
    PERFORM pgreact_internal.maybe_fail_pack('rules');

    FOR rule_item IN
        SELECT value FROM pg_catalog.jsonb_array_elements(definition -> 'remove') AS r(value)
    LOOP
        action_number := action_number + 1;
        SELECT m.rule_version_id INTO current_version
        FROM pgreact_internal.rule_pack_members m
        WHERE m.pack_version_id = prior_pack_version AND m.rule_name = rule_item.value ->> 'name';
        policy := COALESCE(rule_item.value ->> 'old_work_policy', 'DRAIN_OLD');
        PERFORM pgreact_internal.retire_pack_rule(current_version, policy);
        INSERT INTO pgreact_internal.rule_pack_actions(
            pack_version_id, action_order, action, rule_name, old_rule_version_id,
            old_work_policy, details
        ) VALUES (next_pack_version, action_number, 'REMOVE', rule_item.value ->> 'name',
                  current_version, policy, '{}'::jsonb);
        current_version := NULL;
    END LOOP;
    PERFORM pgreact_internal.maybe_fail_pack('removals');

    UPDATE pgreact_internal.rule_pack_versions SET state = 'SUPERSEDED'
    WHERE pack_version_id = prior_pack_version;
    UPDATE pgreact_internal.rule_pack_versions SET state = 'ACTIVE'
    WHERE pack_version_id = next_pack_version;
    PERFORM pgreact_internal.maybe_fail_pack('activation');
    RETURN next_pack_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.deploy_program_m14(definition jsonb, expected_plan_digest text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    inferred jsonb := pgreact_api.infer_program(definition);
    actual_plan_digest text;
BEGIN
    actual_plan_digest := encode(sha256(convert_to(inferred::text || ':' || session_user, 'UTF8')), 'hex');
    IF expected_plan_digest IS NOT NULL AND expected_plan_digest <> actual_plan_digest THEN
        RAISE EXCEPTION 'M14_PROGRAM_PREVIEW_STALE'
            USING HINT = 'Preview the program again after DDL or deployment changes.';
    END IF;
    RETURN pgreact_internal.deploy_derivation_program(inferred, NULL);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.deploy_program_m16(definition jsonb, expected_plan_digest text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    normalized jsonb;
    actual_plan_digest text;
    deployed uuid;
    rule_item record;
    derived pgreact_internal.keyed_derived_relations%ROWTYPE;
    version_id uuid;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(definition -> 'rules') rule
        JOIN pgreact_internal.keyed_derived_relations relation_spec
          ON relation_spec.public_name = rule ->> 'target') THEN
        RETURN pgreact_internal.deploy_program_m14(definition, expected_plan_digest);
    END IF;
    SELECT * INTO rule_item FROM pgreact_api.validate_program(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M16_PROGRAM_INVALID: % for %', rule_item.code, rule_item.object_identity
            USING HINT = rule_item.hint;
    END IF;
    normalized := pgreact_internal.normalize_program(definition);
    actual_plan_digest := pgreact_internal.program_plan_digest(normalized);
    IF expected_plan_digest IS NOT NULL AND expected_plan_digest <> actual_plan_digest THEN
        RAISE EXCEPTION 'M16_PROGRAM_PREVIEW_STALE'
            USING HINT = 'Preview the program again after DDL or deployment changes.';
    END IF;
    deployed := pgreact_internal.deploy_derivation_program(normalized, NULL);
    FOR rule_item IN
        SELECT original.value, normalized_rule.value AS normalized_value
        FROM jsonb_array_elements(definition -> 'rules') WITH ORDINALITY original(value, ordinal)
        JOIN jsonb_array_elements(normalized -> 'rules') WITH ORDINALITY normalized_rule(value, ordinal)
          USING (ordinal)
    LOOP
        SELECT * INTO derived
        FROM pgreact_internal.keyed_derived_relations
        WHERE public_name = rule_item.value ->> 'target';
        IF NOT FOUND THEN CONTINUE; END IF;
        SELECT version.rule_version_id INTO STRICT version_id
        FROM pgreact_internal.rules rule
        JOIN pgreact_internal.rule_versions version USING (rule_id)
        WHERE rule.rule_name = rule_item.value ->> 'name' AND version.state = 'ACTIVE';
        INSERT INTO pgreact_internal.keyed_rule_versions VALUES (
            version_id, to_regclass(rule_item.value ->> 'definition'),
            to_regclass(rule_item.normalized_value ->> 'definition'),
            derived.key_columns, derived.key_types, derived.key_collations)
        ON CONFLICT (rule_version_id) DO UPDATE
        SET public_condition = EXCLUDED.public_condition,
            wrapper_condition = EXCLUDED.wrapper_condition,
            key_columns = EXCLUDED.key_columns,
            key_types = EXCLUDED.key_types,
            key_collations = EXCLUDED.key_collations;
    END LOOP;
    RETURN deployed;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.emit_event(version_row pgreact_internal.rule_versions, activation uuid, generation bigint, revision bigint, kind text, old_value jsonb, new_value jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE event_id bigint; event_key text; binding pgreact_internal.consequence_bindings%ROWTYPE;
    max_pending integer;
BEGIN
    event_key := encode(sha256(convert_to(
        version_row.rule_version_id::text || ':' || activation::text || ':' || generation || ':' || kind || ':' || revision,
        'UTF8')), 'hex');
    INSERT INTO pgreact_internal.lifecycle_events (
        rule_id, rule_version_id, activation_id, generation, revision, event_kind,
        old_bindings, new_bindings, idempotency_key
    ) VALUES (
        version_row.rule_id, version_row.rule_version_id, activation, $3, $4, $5,
        old_value, new_value, event_key
    ) ON CONFLICT ON CONSTRAINT lifecycle_events_identity_key DO NOTHING
    RETURNING lifecycle_events.event_id INTO event_id;
    IF event_id IS NULL THEN
        SELECT e.event_id INTO event_id FROM pgreact_internal.lifecycle_events e
        WHERE e.rule_version_id = version_row.rule_version_id AND e.activation_id = activation
          AND e.generation = $3 AND e.event_kind = $5 AND e.revision = $4;
        RETURN event_id;
    END IF;
    SELECT * INTO binding FROM pgreact_internal.consequence_bindings
    WHERE rule_version_id = version_row.rule_version_id AND event_kind = kind;
    IF FOUND OR (kind = 'ACTIVATE' AND version_row.consequence_oid IS NOT NULL) THEN
        SELECT max_pending_per_rule INTO max_pending FROM pgreact_internal.operational_settings;
        IF (SELECT count(*) FROM pgreact_internal.agenda
            WHERE rule_version_id = version_row.rule_version_id
              AND state IN ('PENDING', 'RETRY_WAIT', 'LEASED')) >= max_pending THEN
            PERFORM pgreact_internal.record_runtime_event('ERROR', 'BACKPRESSURE', version_row.rule_version_id,
                NULL, NULL, jsonb_build_object('max_pending_per_rule', max_pending));
            RAISE EXCEPTION 'pg-react backpressure for rule version %: pending-work limit % reached',
                version_row.rule_version_id, max_pending
                USING HINT = 'Drain, cancel, or raise the approved per-rule limit before refreshing again.';
        END IF;
        INSERT INTO pgreact_internal.agenda (
            event_id, rule_id, rule_version_id, activation_id, activation_generation,
            activation_revision, event_kind, state, old_bindings, new_bindings,
            consequence_kind, agenda_group, salience, conflict_key, max_attempts,
            retry_initial_seconds, retry_multiplier, retry_max_seconds, idempotency_key
        ) VALUES (
            event_id, version_row.rule_id, version_row.rule_version_id, activation, generation,
            revision, kind, 'PENDING', old_value, new_value,
            COALESCE(binding.consequence_kind, 'DATABASE_TYPED'), version_row.agenda_group, version_row.salience,
            pgreact_internal.conflict_key(version_row.conflict_key_columns, COALESCE(new_value, old_value)),
            COALESCE(binding.max_attempts, 3), COALESCE(binding.initial_backoff_seconds, 1),
            COALESCE(binding.backoff_multiplier, 2), COALESCE(binding.max_backoff_seconds, 60), event_key
        );
    END IF;
    RETURN event_id;
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.enable_immediate_rule(target_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE;
    source_oid oid;
BEGIN
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_version_id;
    PERFORM pg_advisory_xact_lock(hashtextextended(version_row.rule_version_id::text, 5788046901200002));
    IF version_row.state <> 'ACTIVE' THEN
        RAISE EXCEPTION 'M19_IMMEDIATE_STATE: rule version % is not active', target_version_id;
    END IF;
    UPDATE pgreact_internal.rule_versions
    SET maintenance_mode = 'IMMEDIATE'
    WHERE rule_version_id = target_version_id;
    PERFORM pgtrickle.set_stream_table_refresh_policy(version_row.match_name, 'IMMEDIATE');
    EXECUTE format('DROP TRIGGER IF EXISTS pgreact_immediate_finalize ON %s', version_row.match_name);
    EXECUTE format(
        'CREATE TRIGGER pgreact_immediate_finalize AFTER INSERT OR UPDATE OR DELETE ON %s '
        'FOR EACH STATEMENT EXECUTE FUNCTION pgreact_internal.finalize_immediate_match_delta(%L)',
        version_row.match_name, version_row.rule_version_id::text);
    IF NOT EXISTS (
        SELECT 1 FROM pgtrickle.pgt_stream_tables stream
        WHERE stream.pgt_relid = version_row.match_relid
          AND stream.refresh_mode = 'IMMEDIATE'
    ) THEN
        RAISE EXCEPTION 'M19_IMMEDIATE_CAPABILITY: pg_trickle did not enable IMMEDIATE for %', version_row.match_name;
    END IF;
    WITH RECURSIVE dependencies(relid) AS (
        SELECT version_row.source_view_oid
        UNION
        SELECT dependency.refobjid
        FROM dependencies parent
        JOIN pg_rewrite rewrite ON rewrite.ev_class = parent.relid
        JOIN pg_depend dependency
          ON dependency.classid = 'pg_rewrite'::regclass
         AND dependency.objid = rewrite.oid
         AND dependency.refclassid = 'pg_class'::regclass
         AND dependency.deptype = 'n'
    )
    SELECT min(relation.oid) FILTER (WHERE relation.relkind IN ('r', 'p'))
    INTO source_oid
    FROM dependencies
    JOIN pg_class relation ON relation.oid = dependencies.relid;
    IF source_oid IS NOT NULL THEN
        EXECUTE format('DROP TRIGGER IF EXISTS zz_pgreact_immediate_propagate ON %s', source_oid::regclass);
        EXECUTE format(
            'CREATE TRIGGER zz_pgreact_immediate_propagate AFTER INSERT OR UPDATE OR DELETE ON %s '
            'FOR EACH STATEMENT EXECUTE FUNCTION pgreact_internal.propagate_immediate_facts()',
            source_oid::regclass);
    END IF;
    INSERT INTO pgreact_internal.immediate_audits(object_identity, operation, details)
    VALUES (version_row.rule_version_id::text, 'ENABLE_RULE',
            jsonb_build_object('rule', version_row.source_view_name,
                               'match', version_row.match_name,
                               'lock', 'rule-version advisory xact lock',
                               'visibility', 'READ COMMITTED same transaction'));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.execute_claimed_batch_m7(target_batch_id uuid, expected_worker_id text)
 RETURNS TABLE(episode_id bigint, status text, error_code text, error_message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    batch_row pgreact_internal.execution_batches%ROWTYPE;
    item_row record;
    episode pgreact_internal.agenda%ROWTYPE;
    version_row pgreact_internal.rule_versions%ROWTYPE;
    binding pgreact_internal.consequence_bindings%ROWTYPE;
    item_status text;
    rejection_code text;
    rejection_detail jsonb := '{}'::jsonb;
    duplicate_conflict text;
    total_items integer;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200000);
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200001);
    SELECT * INTO STRICT batch_row FROM pgreact_internal.execution_batches b
    WHERE b.batch_id = target_batch_id FOR UPDATE;
    IF batch_row.worker_id <> expected_worker_id THEN
        RAISE EXCEPTION 'batch % is owned by worker %, not %',
            target_batch_id, batch_row.worker_id, expected_worker_id;
    END IF;
    IF batch_row.state <> 'CLAIMED' THEN
        RAISE EXCEPTION 'batch % is not claimable in state %', target_batch_id, batch_row.state;
    END IF;
    SELECT count(*) INTO total_items FROM pgreact_internal.execution_batch_items i
    WHERE i.batch_id = target_batch_id;
    IF total_items NOT BETWEEN 2 AND 32 OR total_items > batch_row.max_items THEN
        rejection_code := 'OVERSIZED_OR_EMPTY';
        rejection_detail := jsonb_build_object('items', total_items, 'max_items', batch_row.max_items);
    END IF;
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions v
    WHERE v.rule_version_id = batch_row.rule_version_id FOR SHARE;
    SELECT * INTO binding FROM pgreact_internal.consequence_bindings b
    WHERE b.rule_version_id = batch_row.rule_version_id AND b.event_kind = batch_row.event_kind
    FOR SHARE;
    IF rejection_code IS NULL AND (
        NOT FOUND OR binding.consequence_kind <> 'DATABASE_TYPED' OR binding.dispatcher_oid IS NULL
        OR binding.function_oid <> batch_row.function_oid
        OR binding.function_digest <> batch_row.function_digest
        OR binding.dispatcher_oid <> batch_row.dispatcher_oid
        OR binding.dispatcher_digest <> batch_row.dispatcher_digest
    ) THEN
        rejection_code := 'MIXED_BINDING';
    END IF;
    IF rejection_code IS NULL AND version_row.owner_oid <> batch_row.execution_role_oid THEN
        rejection_code := 'MIXED_ROLE';
    END IF;
    IF rejection_code IS NULL
       AND version_row.conflict_key_columns IS DISTINCT FROM batch_row.conflict_key_columns THEN
        rejection_code := 'MIXED_CONFLICT_SCOPE';
    END IF;
    IF rejection_code IS NULL AND batch_row.recheck_policy <> 'FRESH' THEN
        rejection_code := 'MIXED_POLICY';
    END IF;
    IF rejection_code IS NULL AND NOT EXISTS (
        SELECT 1 FROM pgreact_internal.batch_declarations d
        WHERE d.rule_version_id = batch_row.rule_version_id AND d.event_kind = batch_row.event_kind
    ) THEN
        rejection_code := 'UNDECLARED';
    END IF;
    IF rejection_code IS NULL AND version_row.state = 'DRAINING' THEN
        rejection_code := 'REPLACED';
    ELSIF rejection_code IS NULL AND version_row.state <> 'ACTIVE' THEN
        rejection_code := 'INELIGIBLE_RULE_STATE';
        rejection_detail := jsonb_build_object('state', version_row.state);
    END IF;
    IF rejection_code IS NULL AND EXISTS (
        SELECT 1 FROM pgreact_internal.rule_barriers b
        WHERE b.rule_version_id = batch_row.rule_version_id
    ) THEN
        rejection_code := 'BARRIER';
    END IF;
    IF rejection_code IS NULL THEN
        EXECUTE format('LOCK TABLE %s IN ACCESS SHARE MODE', version_row.source_view_oid::regclass);
    END IF;
    IF rejection_code IS NULL AND (
        pgreact_internal.source_row_signature(version_row.source_view_oid)
            IS DISTINCT FROM version_row.source_row_signature
        OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_proc WHERE oid = binding.function_oid)
        OR sha256(convert_to(pg_get_functiondef(binding.function_oid), 'UTF8')) <> binding.function_digest
        OR NOT EXISTS (SELECT 1 FROM pg_catalog.pg_proc WHERE oid = binding.dispatcher_oid)
        OR sha256(convert_to(pg_get_functiondef(binding.dispatcher_oid), 'UTF8')) <> binding.dispatcher_digest
    ) THEN
        rejection_code := 'DRIFT';
    END IF;
    IF rejection_code IS NULL THEN
        SELECT a.conflict_key INTO duplicate_conflict
        FROM pgreact_internal.execution_batch_items i
        JOIN pgreact_internal.agenda a USING (episode_id)
        WHERE i.batch_id = target_batch_id AND a.conflict_key IS NOT NULL
        GROUP BY a.conflict_key HAVING count(*) > 1
        ORDER BY a.conflict_key LIMIT 1;
        IF FOUND THEN
            rejection_code := 'INCOMPATIBLE_CONFLICT';
            rejection_detail := jsonb_build_object('conflict_key', duplicate_conflict);
        END IF;
    END IF;
    FOR item_row IN
        SELECT i.item_order, i.episode_id, i.lease_token
        FROM pgreact_internal.execution_batch_items i
        WHERE i.batch_id = target_batch_id ORDER BY i.item_order
    LOOP
        EXIT WHEN rejection_code IS NOT NULL;
        SELECT * INTO STRICT episode FROM pgreact_internal.agenda a
        WHERE a.episode_id = item_row.episode_id FOR UPDATE;
        IF episode.rule_version_id <> batch_row.rule_version_id THEN
            rejection_code := 'MIXED_VERSION';
        ELSIF episode.event_kind <> batch_row.event_kind THEN
            rejection_code := 'MIXED_EVENT';
        ELSIF episode.consequence_kind <> 'DATABASE_TYPED' THEN
            rejection_code := 'MIXED_BINDING';
        ELSIF episode.state <> 'LEASED'
           OR episode.worker_id <> expected_worker_id
           OR episode.lease_token <> item_row.lease_token
           OR episode.lease_expires_at <= clock_timestamp() THEN
            rejection_code := 'STALE_LEASE';
        ELSIF NOT (CASE episode.event_kind
            WHEN 'ACTIVATE' THEN EXISTS (
                SELECT 1 FROM pgreact_internal.activation_state s
                WHERE s.rule_version_id = episode.rule_version_id
                  AND s.activation_id = episode.activation_id AND s.active
                  AND s.generation = episode.activation_generation
            )
            WHEN 'CHANGE' THEN EXISTS (
                SELECT 1 FROM pgreact_internal.activation_state s
                WHERE s.rule_version_id = episode.rule_version_id
                  AND s.activation_id = episode.activation_id AND s.active
                  AND s.generation = episode.activation_generation
                  AND s.revision = episode.activation_revision
            )
            ELSE NOT EXISTS (
                SELECT 1 FROM pgreact_internal.activation_state s
                WHERE s.rule_version_id = episode.rule_version_id
                  AND s.activation_id = episode.activation_id AND s.active
                  AND s.generation > episode.activation_generation
            )
        END) THEN
            rejection_code := 'INELIGIBLE_EPISODE';
        END IF;
        IF rejection_code IS NOT NULL THEN
            rejection_detail := jsonb_build_object(
                'item_order', item_row.item_order, 'episode_id', item_row.episode_id
            );
        END IF;
    END LOOP;
    IF rejection_code IS NOT NULL THEN
        UPDATE pgreact_internal.execution_batches b
        SET state = 'REJECTED', diagnostic_code = rejection_code,
            diagnostic = rejection_detail || jsonb_build_object(
                'code', rejection_code, 'message', 'batch rejected before consequence invocation'
            ), finished_at = clock_timestamp()
        WHERE b.batch_id = target_batch_id;
        UPDATE pgreact_internal.execution_batch_items i
        SET outcome = 'REJECTED', error_code = rejection_code,
            error_message = 'batch rejected before consequence invocation'
        WHERE i.batch_id = target_batch_id;
        RETURN QUERY
        SELECT i.episode_id, i.outcome, i.error_code, i.error_message
        FROM pgreact_internal.execution_batch_items i
        WHERE i.batch_id = target_batch_id ORDER BY i.item_order;
        RETURN;
    END IF;
    UPDATE pgreact_internal.execution_batches b
    SET state = 'RUNNING', started_at = clock_timestamp()
    WHERE b.batch_id = target_batch_id;
    FOR item_row IN
        SELECT i.item_order, i.episode_id, i.lease_token
        FROM pgreact_internal.execution_batch_items i
        WHERE i.batch_id = target_batch_id ORDER BY i.item_order
    LOOP
        SELECT pgreact.execute_claimed_episode(
            item_row.episode_id, expected_worker_id, item_row.lease_token
        ) INTO STRICT item_status;
        UPDATE pgreact_internal.execution_batch_items i
        SET outcome = item_status,
            error_code = CASE WHEN item_status IN ('FAILED', 'RETRY_WAIT')
                THEN a.last_error ->> 'code' END,
            error_message = CASE WHEN item_status IN ('FAILED', 'RETRY_WAIT')
                THEN a.last_error ->> 'message' END
        FROM pgreact_internal.agenda a
        WHERE i.batch_id = target_batch_id AND i.episode_id = item_row.episode_id
          AND a.episode_id = i.episode_id;
    END LOOP;
    UPDATE pgreact_internal.execution_batches b
    SET state = CASE WHEN EXISTS (
            SELECT 1 FROM pgreact_internal.execution_batch_items i
            WHERE i.batch_id = target_batch_id AND i.outcome IN ('FAILED', 'RETRY_WAIT')
        ) THEN 'PARTIAL' ELSE 'COMPLETED' END,
        diagnostic_code = CASE WHEN EXISTS (
            SELECT 1 FROM pgreact_internal.execution_batch_items i
            WHERE i.batch_id = target_batch_id AND i.outcome IN ('FAILED', 'RETRY_WAIT')
        ) THEN 'ITEM_FAILURE' END,
        diagnostic = jsonb_build_object('items', (
            SELECT jsonb_agg(jsonb_build_object(
                'item_order', i.item_order, 'episode_id', i.episode_id,
                'outcome', i.outcome, 'error_code', i.error_code
            ) ORDER BY i.item_order)
            FROM pgreact_internal.execution_batch_items i WHERE i.batch_id = target_batch_id
        )),
        finished_at = clock_timestamp()
    WHERE b.batch_id = target_batch_id;
    RETURN QUERY
    SELECT i.episode_id, i.outcome, i.error_code, i.error_message
    FROM pgreact_internal.execution_batch_items i
    WHERE i.batch_id = target_batch_id ORDER BY i.item_order;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.execute_claimed_episode_m7(target_episode_id bigint, expected_worker_id text, expected_lease_token uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    episode pgreact_internal.agenda%ROWTYPE;
    event_row pgreact_internal.lifecycle_events%ROWTYPE;
    version_row pgreact_internal.rule_versions%ROWTYPE;
    binding pgreact_internal.consequence_bindings%ROWTYPE;
    context pgreact.activation_context;
    attempt integer;
    started timestamptz := clock_timestamp();
    dispatcher_call text;
    sink_call text;
    failure text;
    failure_code text;
    retry_seconds integer;
    retry_value numeric;
    step integer;
    eligible boolean;
    binding_found boolean;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200000);
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200001);
    SELECT * INTO STRICT episode
    FROM pgreact_internal.agenda
    WHERE episode_id = target_episode_id
    FOR UPDATE;
    IF episode.state <> 'LEASED'
       OR episode.worker_id <> expected_worker_id
       OR episode.lease_token <> expected_lease_token THEN
        RAISE EXCEPTION 'lease is no longer valid for episode %', target_episode_id;
    END IF;
    attempt := episode.attempt_count;

    BEGIN
        IF episode.lease_expires_at <= clock_timestamp() THEN
            RAISE EXCEPTION 'lease is no longer valid for episode %', target_episode_id;
        END IF;
        SELECT * INTO STRICT version_row
        FROM pgreact_internal.rule_versions
        WHERE rule_version_id = episode.rule_version_id;
        SELECT * INTO STRICT event_row
        FROM pgreact_internal.lifecycle_events
        WHERE event_id = episode.event_id;
        SELECT * INTO binding
        FROM pgreact_internal.consequence_bindings
        WHERE rule_version_id = episode.rule_version_id
          AND event_kind = episode.event_kind;
        binding_found := FOUND;
        eligible := NOT EXISTS (
                SELECT 1 FROM pgreact_internal.rule_barriers
                WHERE rule_version_id = episode.rule_version_id)
            AND version_row.state IN ('ACTIVE', 'DRAINING')
            AND CASE episode.event_kind
                WHEN 'ACTIVATE' THEN EXISTS (
                    SELECT 1 FROM pgreact_internal.activation_state state
                    WHERE state.rule_version_id = episode.rule_version_id
                      AND state.activation_id = episode.activation_id
                      AND state.active
                      AND state.generation = episode.activation_generation)
                WHEN 'CHANGE' THEN EXISTS (
                    SELECT 1 FROM pgreact_internal.activation_state state
                    WHERE state.rule_version_id = episode.rule_version_id
                      AND state.activation_id = episode.activation_id
                      AND state.active
                      AND state.generation = episode.activation_generation
                      AND state.revision = episode.activation_revision)
                ELSE NOT EXISTS (
                    SELECT 1 FROM pgreact_internal.activation_state state
                    WHERE state.rule_version_id = episode.rule_version_id
                      AND state.activation_id = episode.activation_id
                      AND state.active
                      AND state.generation > episode.activation_generation)
            END;
        IF NOT eligible THEN
            INSERT INTO pgreact_internal.executions (
                episode_id, attempt_no, worker_id, lease_token, started_at,
                finished_at, status, event_kind, transaction_id)
            VALUES (
                target_episode_id, attempt, expected_worker_id,
                expected_lease_token, started, clock_timestamp(), 'SKIPPED',
                episode.event_kind, pg_current_xact_id());
            UPDATE pgreact_internal.agenda
            SET state = 'SKIPPED', completed_at = clock_timestamp(),
                lease_token = NULL, worker_id = NULL, lease_expires_at = NULL
            WHERE episode_id = target_episode_id
              AND state = 'LEASED'
              AND worker_id = expected_worker_id
              AND lease_token = expected_lease_token;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'lease lost for episode %', target_episode_id;
            END IF;
            DELETE FROM pgreact_internal.conflict_leases
            WHERE episode_id = target_episode_id
              AND lease_token = expected_lease_token;
            RETURN 'SKIPPED';
        END IF;
        IF pgreact_internal.source_row_signature(version_row.source_view_oid)
           IS DISTINCT FROM version_row.source_row_signature THEN
            RAISE EXCEPTION
                'pg-react source row signature drift for rule version %; pause, drain, and replace it',
                episode.rule_version_id;
        END IF;
        IF NOT binding_found THEN
            binding.consequence_kind := 'DATABASE_TYPED';
            binding.function_oid := version_row.consequence_oid;
            binding.function_digest := version_row.consequence_digest;
            binding.dispatcher_oid := version_row.dispatcher_oid;
            binding.dispatcher_digest := version_row.dispatcher_digest;
        END IF;
        IF binding.function_oid IS NULL
           OR NOT EXISTS (
               SELECT 1 FROM pg_catalog.pg_proc
               WHERE oid = binding.function_oid)
           OR sha256(convert_to(pg_get_functiondef(binding.function_oid), 'UTF8'))
              <> binding.function_digest
           OR (binding.dispatcher_oid IS NOT NULL AND (
               NOT EXISTS (
                   SELECT 1 FROM pg_catalog.pg_proc
                   WHERE oid = binding.dispatcher_oid)
               OR sha256(convert_to(pg_get_functiondef(binding.dispatcher_oid), 'UTF8'))
                  <> binding.dispatcher_digest)) THEN
            RAISE EXCEPTION 'pg-react consequence or dispatcher drift for rule version %',
                episode.rule_version_id;
        END IF;
        context := ROW(
            episode.activation_id, episode.episode_id, episode.rule_id,
            episode.rule_version_id, episode.activation_generation,
            episode.activation_revision, episode.event_kind, attempt,
            event_row.transitioned_at, expected_worker_id,
            episode.idempotency_key)::pgreact.activation_context;
        IF binding.consequence_kind = 'OUTBOX' THEN
            SELECT format('%I.%I', namespace.nspname, proc_row.proname)
            INTO STRICT sink_call
            FROM pg_catalog.pg_proc proc_row
            JOIN pg_catalog.pg_namespace namespace
              ON namespace.oid = proc_row.pronamespace
            WHERE proc_row.oid = binding.function_oid;
            EXECUTE format('SELECT %s($1, $2)', sink_call)
            USING context, jsonb_build_object(
                'version', 1, 'rule_id', episode.rule_id,
                'rule_version_id', episode.rule_version_id,
                'event_kind', episode.event_kind,
                'activation_id', episode.activation_id,
                'generation', episode.activation_generation,
                'revision', episode.activation_revision,
                'episode_id', episode.episode_id,
                'idempotency_key', episode.idempotency_key,
                'old', episode.old_bindings, 'new', episode.new_bindings);
        ELSIF binding.dispatcher_oid = version_row.dispatcher_oid THEN
            SELECT format('%I.%I', namespace.nspname, proc_row.proname)
            INTO STRICT dispatcher_call
            FROM pg_catalog.pg_proc proc_row
            JOIN pg_catalog.pg_namespace namespace
              ON namespace.oid = proc_row.pronamespace
            WHERE proc_row.oid = binding.dispatcher_oid;
            EXECUTE format('SELECT %s($1, $2)', dispatcher_call)
            USING context, episode.new_bindings;
        ELSE
            SELECT format('%I.%I', namespace.nspname, proc_row.proname)
            INTO STRICT dispatcher_call
            FROM pg_catalog.pg_proc proc_row
            JOIN pg_catalog.pg_namespace namespace
              ON namespace.oid = proc_row.pronamespace
            WHERE proc_row.oid = binding.dispatcher_oid;
            EXECUTE format('SELECT %s($1, $2, $3)', dispatcher_call)
            USING context, episode.old_bindings, episode.new_bindings;
        END IF;
        INSERT INTO pgreact_internal.executions (
            episode_id, attempt_no, worker_id, lease_token, started_at,
            finished_at, status, event_kind, transaction_id)
        VALUES (
            target_episode_id, attempt, expected_worker_id,
            expected_lease_token, started, clock_timestamp(), 'COMPLETED',
            episode.event_kind, pg_current_xact_id());
        UPDATE pgreact_internal.agenda
        SET state = 'COMPLETED', completed_at = clock_timestamp(),
            lease_token = NULL, worker_id = NULL, lease_expires_at = NULL
        WHERE episode_id = target_episode_id
          AND lease_token = expected_lease_token
          AND worker_id = expected_worker_id
          AND state = 'LEASED';
        IF NOT FOUND THEN
            RAISE EXCEPTION 'lease lost for episode %', target_episode_id;
        END IF;
        DELETE FROM pgreact_internal.conflict_leases
        WHERE episode_id = target_episode_id
          AND lease_token = expected_lease_token;
        RETURN 'COMPLETED';
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            failure = MESSAGE_TEXT,
            failure_code = RETURNED_SQLSTATE;
        IF failure_code !~ '^(28|42)'
           AND attempt < episode.max_attempts
           AND episode.retry_multiplier IS NOT NULL
           AND episode.retry_multiplier::text <> 'NaN'
           AND episode.retry_multiplier >= 1 THEN
            retry_value := episode.retry_initial_seconds::numeric;
            IF retry_value < episode.retry_max_seconds THEN
                IF episode.retry_multiplier >
                   episode.retry_max_seconds::numeric / retry_value THEN
                    retry_value := episode.retry_max_seconds;
                ELSE
                    FOR step IN 2..LEAST(attempt, 100) LOOP
                        EXIT WHEN retry_value >= episode.retry_max_seconds;
                        IF retry_value > episode.retry_max_seconds::numeric /
                           episode.retry_multiplier THEN
                            retry_value := episode.retry_max_seconds;
                            EXIT;
                        END IF;
                        retry_value := retry_value * episode.retry_multiplier;
                    END LOOP;
                END IF;
            END IF;
            retry_seconds := LEAST(
                episode.retry_max_seconds,
                GREATEST(1, floor(retry_value))::integer);
            INSERT INTO pgreact_internal.executions (
                episode_id, attempt_no, worker_id, lease_token, started_at,
                finished_at, status, error_message, error_code, event_kind,
                transaction_id)
            VALUES (
                target_episode_id, attempt, expected_worker_id,
                expected_lease_token, started, clock_timestamp(),
                'RETRY_WAIT', failure, failure_code, episode.event_kind,
                pg_current_xact_id());
            UPDATE pgreact_internal.agenda
            SET state = 'RETRY_WAIT',
                available_at = clock_timestamp() + make_interval(secs => retry_seconds),
                lease_token = NULL, worker_id = NULL, lease_expires_at = NULL,
                last_error = jsonb_build_object('code', failure_code, 'message', failure)
            WHERE episode_id = target_episode_id
              AND state = 'LEASED'
              AND worker_id = expected_worker_id
              AND lease_token = expected_lease_token;
            IF FOUND THEN
                DELETE FROM pgreact_internal.conflict_leases
                WHERE episode_id = target_episode_id
                  AND lease_token = expected_lease_token;
            END IF;
            RETURN 'RETRY_WAIT';
        END IF;
        INSERT INTO pgreact_internal.executions (
            episode_id, attempt_no, worker_id, lease_token, started_at,
            finished_at, status, error_message, error_code, event_kind,
            transaction_id)
        VALUES (
            target_episode_id, attempt, expected_worker_id,
            expected_lease_token, started, clock_timestamp(), 'FAILED',
            failure, failure_code, episode.event_kind, pg_current_xact_id());
        UPDATE pgreact_internal.agenda
        SET state = 'FAILED', completed_at = clock_timestamp(),
            lease_token = NULL, worker_id = NULL, lease_expires_at = NULL,
            last_error = jsonb_build_object('code', failure_code, 'message', failure)
        WHERE episode_id = target_episode_id
          AND state = 'LEASED'
          AND worker_id = expected_worker_id
          AND lease_token = expected_lease_token;
        IF FOUND THEN
            DELETE FROM pgreact_internal.conflict_leases
            WHERE episode_id = target_episode_id
              AND lease_token = expected_lease_token;
        END IF;
        RETURN 'FAILED';
    END;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.execute_one(rule_version_id uuid, worker_id text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    episode pgreact_internal.agenda%ROWTYPE;
    event_row pgreact_internal.lifecycle_events%ROWTYPE;
    version_row pgreact_internal.rule_versions%ROWTYPE;
    token uuid := gen_random_uuid();
    started timestamptz := clock_timestamp();
    context pgreact.activation_context;
    dispatcher_call text;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200000);
    IF EXISTS (SELECT 1 FROM pgreact_internal.rule_barriers b
               WHERE b.rule_version_id = execute_one.rule_version_id) THEN
        RAISE EXCEPTION 'pg-react claims are blocked for rule version %', rule_version_id;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(5788046901200001);

    SELECT * INTO episode
    FROM pgreact_internal.agenda a
    WHERE a.rule_version_id = execute_one.rule_version_id AND a.state = 'PENDING'
      AND a.available_at <= clock_timestamp()
    ORDER BY a.episode_id
    LIMIT 1 FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN RETURN NULL; END IF;

    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions v
    WHERE v.rule_version_id = execute_one.rule_version_id;
    SELECT * INTO STRICT event_row FROM pgreact_internal.lifecycle_events e
    WHERE e.event_id = episode.event_id;

    IF sha256(convert_to(pg_catalog.pg_get_functiondef(version_row.consequence_oid), 'UTF8'))
           <> version_row.consequence_digest
       OR sha256(convert_to(pg_catalog.pg_get_functiondef(version_row.dispatcher_oid), 'UTF8'))
           <> version_row.dispatcher_digest THEN
        RAISE EXCEPTION 'pg-react consequence or dispatcher drift for rule version %', rule_version_id;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pgreact_internal.activation_state s
        WHERE s.rule_version_id = execute_one.rule_version_id
          AND s.activation_id = episode.activation_id
          AND s.active AND s.generation = episode.activation_generation
    ) THEN
        RAISE EXCEPTION 'pg-react episode % is no longer eligible', episode.episode_id;
    END IF;

    UPDATE pgreact_internal.agenda SET
        state = 'LEASED', lease_token = token, worker_id = execute_one.worker_id,
        claimed_at = started
    WHERE episode_id = episode.episode_id;

    context := ROW(
        episode.activation_id, episode.episode_id, episode.rule_id,
        episode.rule_version_id, episode.activation_generation, 0,
        'ACTIVATE', 1, event_row.transitioned_at, worker_id,
        episode.idempotency_key
    )::pgreact.activation_context;
    SELECT format('%I.%I', n.nspname, p.proname) INTO STRICT dispatcher_call
    FROM pg_catalog.pg_proc p
    JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
    WHERE p.oid = version_row.dispatcher_oid;
    EXECUTE format('SELECT %s($1, $2)', dispatcher_call)
        USING context, episode.new_bindings;

    INSERT INTO pgreact_internal.executions (
        episode_id, attempt_no, worker_id, lease_token, started_at,
        finished_at, status, transaction_id
    ) VALUES (
        episode.episode_id, 1, worker_id, token, started, clock_timestamp(),
        'COMPLETED', pg_catalog.pg_current_xact_id()
    );
    UPDATE pgreact_internal.agenda SET state = 'COMPLETED', completed_at = clock_timestamp()
    WHERE episode_id = episode.episode_id AND lease_token = token AND state = 'LEASED';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'pg-react lease lost for episode %', episode.episode_id;
    END IF;
    RETURN episode.episode_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.finalize_match_delta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    version_id uuid := TG_ARGV[0]::uuid;
    version_row pgreact_internal.rule_versions%ROWTYPE; buffered record; current_count bigint;
    final_bindings jsonb; canonical bytea; digest bytea; activation uuid;
    prior pgreact_internal.activation_state%ROWTYPE; next_generation bigint; next_revision bigint;
BEGIN
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions WHERE rule_version_id = version_id;
    FOR buffered IN DELETE FROM pgreact_internal.activation_delta_buffer
        WHERE rule_version_id = version_id AND xid = pg_catalog.pg_current_xact_id() RETURNING *
    LOOP
        EXECUTE format('SELECT count(*), min(to_jsonb(m)::text)::jsonb FROM %s m WHERE (to_jsonb(m) ->> %L)::bigint = $1',
            version_row.match_relid::regclass, version_row.key_column::text)
            INTO current_count, final_bindings USING buffered.semantic_key;
        IF current_count > 1 THEN RAISE EXCEPTION 'pg-react duplicate semantic key % in %', buffered.semantic_key, version_row.match_name; END IF;
        canonical := pgreact_internal.canonical_bigint_v1(buffered.semantic_key);
        digest := pgreact_internal.activation_digest(version_id, canonical);
        activation := pgreact_internal.activation_uuid(digest);
        SELECT * INTO prior FROM pgreact_internal.activation_state
        WHERE rule_version_id = version_id AND activation_id = activation FOR UPDATE;
        IF FOUND AND (prior.canonical_key <> canonical OR prior.canonical_key_digest <> digest) THEN
            RAISE EXCEPTION 'pg-react activation UUID collision for semantic key %', buffered.semantic_key;
        END IF;
        IF current_count = 1 AND (prior.activation_id IS NULL OR NOT prior.active) THEN
            next_generation := COALESCE(prior.generation, 0) + 1;
            INSERT INTO pgreact_internal.activation_state (
                rule_version_id, activation_id, semantic_key, canonical_key, canonical_key_digest,
                key_codec_version, active, generation, revision, current_bindings, last_active_bindings,
                first_seen_at, last_seen_at
            ) VALUES (version_id, activation, buffered.semantic_key, canonical, digest, 1, true,
                next_generation, 0, final_bindings, final_bindings, clock_timestamp(), clock_timestamp())
            ON CONFLICT (rule_version_id, activation_id) DO UPDATE SET active = true,
                generation = EXCLUDED.generation, revision = 0, current_bindings = EXCLUDED.current_bindings,
                last_active_bindings = EXCLUDED.last_active_bindings, last_seen_at = EXCLUDED.last_seen_at,
                deactivated_at = NULL;
            PERFORM pgreact_internal.emit_event(version_row, activation, next_generation, 0, 'ACTIVATE', NULL, final_bindings);
        ELSIF current_count = 1 AND prior.active THEN
            IF pgreact_internal.watched_changed(version_row, prior.current_bindings, final_bindings) THEN
                next_revision := prior.revision + 1;
                PERFORM pgreact_internal.emit_event(version_row, activation, prior.generation, next_revision,
                    'CHANGE', prior.current_bindings, final_bindings);
                UPDATE pgreact_internal.activation_state SET revision = next_revision, current_bindings = final_bindings,
                    last_active_bindings = final_bindings, last_seen_at = clock_timestamp()
                WHERE rule_version_id = version_id AND activation_id = activation;
            ELSE
                UPDATE pgreact_internal.activation_state SET current_bindings = final_bindings,
                    last_active_bindings = final_bindings, last_seen_at = clock_timestamp()
                WHERE rule_version_id = version_id AND activation_id = activation;
            END IF;
        ELSIF current_count = 0 AND prior.active THEN
            UPDATE pgreact_internal.activation_state SET active = false, current_bindings = NULL,
                deactivated_at = clock_timestamp(), last_seen_at = clock_timestamp()
            WHERE rule_version_id = version_id AND activation_id = activation;
            UPDATE pgreact_internal.agenda SET state = 'WITHDRAWN', completed_at = clock_timestamp(),
                lease_token = NULL, worker_id = NULL, lease_expires_at = NULL
            WHERE rule_version_id = version_id AND activation_id = activation
              AND activation_generation = prior.generation AND event_kind = 'ACTIVATE'
              AND state IN ('PENDING', 'RETRY_WAIT');
            PERFORM pgreact_internal.emit_event(version_row, activation, prior.generation, 0,
                'DEACTIVATE', prior.last_active_bindings, NULL);
        END IF;
    END LOOP;
    RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.finalize_match_delta_now(target_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    version_id uuid := target_version_id;
    version_row pgreact_internal.rule_versions%ROWTYPE;
    buffered record;
    current_count bigint;
    final_bindings jsonb;
    canonical bytea;
    digest bytea;
    activation uuid;
    prior pgreact_internal.activation_state%ROWTYPE;
    next_generation bigint;
    new_event_id bigint;
    event_key text;
BEGIN
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = version_id;
    PERFORM pg_advisory_xact_lock(hashtextextended(version_id::text, 5788046901200002));

    FOR buffered IN
        DELETE FROM pgreact_internal.activation_delta_buffer
        WHERE rule_version_id = version_id
          AND xid = pg_catalog.pg_current_xact_id()
        RETURNING *
    LOOP
        EXECUTE format(
            'SELECT count(*), min(to_jsonb(m)::text)::jsonb FROM %s AS m '
            'WHERE (to_jsonb(m) ->> %L)::bigint = $1',
            version_row.match_relid::regclass, version_row.key_column::text
        ) INTO current_count, final_bindings USING buffered.semantic_key;

        IF current_count > 1 THEN
            RAISE EXCEPTION 'pg-react duplicate semantic key % in %',
                buffered.semantic_key, version_row.match_name;
        END IF;

        canonical := pgreact_internal.canonical_bigint_v1(buffered.semantic_key);
        digest := pgreact_internal.activation_digest(version_id, canonical);
        activation := pgreact_internal.activation_uuid(digest);
        SELECT * INTO prior
        FROM pgreact_internal.activation_state
        WHERE rule_version_id = version_id AND activation_id = activation
        FOR UPDATE;
        IF FOUND AND (prior.canonical_key <> canonical OR prior.canonical_key_digest <> digest) THEN
            RAISE EXCEPTION 'pg-react activation UUID collision for semantic key %',
                buffered.semantic_key;
        END IF;

        IF current_count = 1 AND (prior.activation_id IS NULL OR NOT prior.active) THEN
            next_generation := COALESCE(prior.generation, 0) + 1;
            INSERT INTO pgreact_internal.activation_state (
                rule_version_id, activation_id, semantic_key, canonical_key,
                canonical_key_digest, key_codec_version, active, generation,
                current_bindings, last_active_bindings, first_seen_at, last_seen_at
            ) VALUES (
                version_id, activation, buffered.semantic_key, canonical, digest, 1,
                true, next_generation, final_bindings, final_bindings,
                clock_timestamp(), clock_timestamp()
            )
            ON CONFLICT (rule_version_id, activation_id) DO UPDATE SET
                active = true, generation = EXCLUDED.generation,
                current_bindings = EXCLUDED.current_bindings,
                last_active_bindings = EXCLUDED.last_active_bindings,
                last_seen_at = EXCLUDED.last_seen_at, deactivated_at = NULL;
            event_key := encode(sha256(convert_to(
                version_id::text || ':' || activation::text || ':' || next_generation || ':ACTIVATE',
                'UTF8')), 'hex');
            INSERT INTO pgreact_internal.lifecycle_events (
                rule_id, rule_version_id, activation_id, generation, event_kind,
                new_bindings, idempotency_key
            ) VALUES (
                version_row.rule_id, version_id, activation, next_generation,
                'ACTIVATE', final_bindings, event_key
            ) RETURNING event_id INTO new_event_id;
            INSERT INTO pgreact_internal.agenda (
                event_id, rule_id, rule_version_id, activation_id,
                activation_generation, state, new_bindings, idempotency_key
            ) SELECT
                new_event_id, version_row.rule_id, version_id, activation,
                next_generation, 'PENDING', final_bindings, event_key
            WHERE version_row.consequence_oid IS NOT NULL;
        ELSIF current_count = 1 AND prior.active THEN
            UPDATE pgreact_internal.activation_state SET
                current_bindings = final_bindings,
                last_active_bindings = final_bindings,
                last_seen_at = clock_timestamp()
            WHERE rule_version_id = version_id AND activation_id = activation;
        ELSIF current_count = 0 AND prior.active THEN
            UPDATE pgreact_internal.activation_state SET
                active = false, current_bindings = NULL,
                deactivated_at = clock_timestamp(), last_seen_at = clock_timestamp()
            WHERE rule_version_id = version_id AND activation_id = activation;
            event_key := encode(sha256(convert_to(
                version_id::text || ':' || activation::text || ':' || prior.generation || ':DEACTIVATE',
                'UTF8')), 'hex');
            INSERT INTO pgreact_internal.lifecycle_events (
                rule_id, rule_version_id, activation_id, generation, event_kind,
                old_bindings, idempotency_key
            ) VALUES (
                version_row.rule_id, version_id, activation, prior.generation,
                'DEACTIVATE', prior.last_active_bindings, event_key);
        END IF;
    END LOOP;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.finalize_temporal_match_delta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_id uuid := TG_ARGV[0]::uuid; key_column name; old_key bigint; new_key bigint;
BEGIN
    SELECT rule_versions.key_column INTO STRICT key_column
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = version_id;
    IF TG_OP <> 'INSERT' THEN
        old_key := (to_jsonb(OLD) ->> key_column)::bigint;
        IF old_key IS NOT NULL THEN PERFORM pgreact_internal.reconcile_temporal_key(version_id, old_key); END IF;
    END IF;
    IF TG_OP <> 'DELETE' THEN
        new_key := (to_jsonb(NEW) ->> key_column)::bigint;
        IF new_key IS NOT NULL AND new_key IS DISTINCT FROM old_key THEN
            PERFORM pgreact_internal.reconcile_temporal_key(version_id, new_key);
        END IF;
    END IF;
    RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.finish_window_program(target_program uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE fingerprint bytea; correction_count bigint;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_temp.m17_affected_windows
                   WHERE program_version_id = target_program) THEN
        RETURN 0;
    END IF;
    correction_count := pgreact_internal.append_window_corrections(target_program, false);
    fingerprint := pgreact_internal.staged_window_fingerprint(target_program);
    DELETE FROM pgreact_internal.window_source_rows WHERE program_version_id = target_program;
    INSERT INTO pgreact_internal.window_source_rows
    SELECT program_version_id,row_data,public_window_key,event_time,window_ordinal,occurrences
    FROM pg_temp.m17_current_rows WHERE program_version_id = target_program;
    UPDATE pgreact_internal.window_programs
    SET lower_frontier = observed_frontier,
        last_source_fingerprint = fingerprint,
        last_observed_fingerprint = fingerprint
    WHERE program_version_id = target_program;
    RETURN correction_count;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.fixed_interval_us(value text, allow_zero boolean)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE parsed interval; micros numeric;
BEGIN
    BEGIN
        parsed := value::interval;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'M17_WINDOW_INTERVAL_INVALID: %', value USING ERRCODE = '22023';
    END;
    IF extract(year FROM parsed) <> 0 OR extract(month FROM parsed) <> 0 THEN
        RAISE EXCEPTION 'M17_WINDOW_INTERVAL_INVALID: % is not fixed-duration', value
            USING ERRCODE = '22023';
    END IF;
    micros := extract(epoch FROM parsed)::numeric * 1000000;
    IF micros <> trunc(micros) OR micros > 9223372036854775807
       OR micros < (CASE WHEN allow_zero THEN 0 ELSE 1 END) THEN
        RAISE EXCEPTION 'M17_WINDOW_INTERVAL_INVALID: % is outside the supported range', value
            USING ERRCODE = '22023';
    END IF;
    RETURN micros::bigint;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.heartbeat_episode_m7(target_episode_id bigint, expected_worker_id text, expected_lease_token uuid, extend_for interval DEFAULT '00:01:00'::interval)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE expires_at timestamptz := clock_timestamp() + extend_for;
BEGIN
    IF extract(epoch FROM extend_for) NOT BETWEEN 1 AND 3600 THEN RAISE EXCEPTION 'extend_for must be between 1 second and 1 hour'; END IF;
    UPDATE pgreact_internal.agenda SET lease_expires_at = expires_at
    WHERE episode_id = target_episode_id AND state = 'LEASED' AND worker_id = expected_worker_id
      AND lease_token = expected_lease_token AND lease_expires_at > clock_timestamp();
    IF NOT FOUND THEN RAISE EXCEPTION 'lease is no longer valid for episode %', target_episode_id; END IF;
    UPDATE pgreact_internal.conflict_leases SET lease_expires_at = expires_at
    WHERE episode_id = target_episode_id AND lease_token = expected_lease_token;
    RETURN expires_at;
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.insert_parameter_rows(target_family_id uuid, rows jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE family_row pgreact_internal.parameter_families%ROWTYPE;
    item jsonb;
    inserted bigint := 0;
BEGIN
    IF rows IS NULL THEN RETURN 0; END IF;
    IF jsonb_typeof(rows) <> 'array' THEN
        RAISE EXCEPTION 'M25_PARAMETER_DATA: initial parameter data must be a JSON array'
            USING HINT = 'Pass one object per parameter row, or pass an empty array.';
    END IF;
    SELECT * INTO STRICT family_row FROM pgreact_internal.parameter_families
    WHERE family_id = target_family_id AND state = 'ACTIVE';
    IF NOT pgreact_internal.parameter_family_editor_allowed(target_family_id) THEN
        RAISE EXCEPTION 'M25_PARAMETER_EDITOR_FORBIDDEN: % cannot seed parameter family %',
            session_user, target_family_id USING ERRCODE = '42501';
    END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(rows) LOOP
        IF jsonb_typeof(item) <> 'object' THEN
            RAISE EXCEPTION 'M25_PARAMETER_DATA: every initial parameter row must be a JSON object';
        END IF;
        EXECUTE format(
            'INSERT INTO %s SELECT * FROM jsonb_populate_record(NULL::%s, $1)',
            family_row.parameter_relation_oid::regclass,
            family_row.parameter_relation_oid::regclass)
        USING item;
        inserted := inserted + 1;
    END LOOP;
    RETURN inserted;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.load_decision_candidates(target_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.decision_program_versions%ROWTYPE;
    null_rows bigint;
BEGIN
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.decision_program_versions
    WHERE version_id = target_version_id;
    IF version_row.source_signature IS DISTINCT FROM
       pgreact_internal.source_row_signature(version_row.candidate_relation_oid)
       OR version_row.source_definition_digest IS DISTINCT FROM
          pgreact_internal.decision_source_digest(version_row.candidate_relation_oid) THEN
        RAISE EXCEPTION 'M26_DECISION_DRIFT: candidate relation % changed after declaration',
            version_row.candidate_relation_name;
    END IF;
    DROP TABLE IF EXISTS pg_temp.m26_decision_candidates;
    CREATE TEMP TABLE pg_temp.m26_decision_candidates (
        subject_key bigint NOT NULL,
        candidate_key bigint NOT NULL,
        priority bigint NOT NULL,
        row_data jsonb NOT NULL
    ) ON COMMIT DROP;
    EXECUTE format(
        'INSERT INTO pg_temp.m26_decision_candidates(subject_key, candidate_key, priority, row_data) '
        'SELECT r.%1$I, r.%2$I, r.%3$I, to_jsonb(r) FROM %4$s r',
        version_row.subject_key_column, version_row.candidate_key_column,
        version_row.priority_column, version_row.candidate_relation_oid::regclass);
    EXECUTE 'SELECT count(*) FROM pg_temp.m26_decision_candidates '
        'WHERE subject_key IS NULL OR candidate_key IS NULL OR priority IS NULL'
        INTO null_rows;
    IF null_rows > 0 THEN
        RAISE EXCEPTION 'M26_CANDIDATE_NULL: candidate identity and priority columns must be non-null';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_temp.m26_decision_candidates
               GROUP BY subject_key, candidate_key HAVING count(*) > 1) THEN
        RAISE EXCEPTION 'M26_CANDIDATE_UNIQUE: candidate source contains duplicate subject and candidate identities';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_temp.m26_decision_candidates
               GROUP BY subject_key HAVING count(*) > version_row.max_candidates) THEN
        RAISE EXCEPTION 'M26_CANDIDATE_LIMIT: candidate source exceeds the declared per-subject limit';
    END IF;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m24_sync_rule(target_version_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE;
    state_row pgreact_internal.activation_state%ROWTYPE;
    candidate record;
    candidate_count bigint;
    prior pgreact_internal.activation_state%ROWTYPE;
    canonical bytea;
    digest bytea;
    activation uuid;
    generation bigint;
    next_revision bigint;
    changed bigint := 0;
BEGIN
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_version_id AND state = 'ACTIVE';

    EXECUTE format(
        'SELECT count(*) FROM %s source WHERE (%I) IS NULL',
        version_row.source_view_oid::regclass, version_row.key_column
    ) INTO candidate_count;
    IF candidate_count > 0 THEN
        RAISE EXCEPTION 'M24_NULL_KEY: policy source % contains % null semantic keys',
            version_row.source_view_name, candidate_count;
    END IF;
    EXECUTE format(
        'SELECT count(*) FROM (SELECT %1$I FROM %2$s GROUP BY %1$I HAVING count(*) > 1) duplicates',
        version_row.key_column, version_row.source_view_oid::regclass
    ) INTO candidate_count;
    IF candidate_count > 0 THEN
        RAISE EXCEPTION 'M24_DUPLICATE_KEY: policy source % contains duplicate semantic keys',
            version_row.source_view_name;
    END IF;

    FOR state_row IN
        SELECT * FROM pgreact_internal.activation_state
        WHERE rule_version_id = target_version_id AND active
        ORDER BY semantic_key
        FOR UPDATE
    LOOP
        EXECUTE format(
            'SELECT count(*) FROM %s source WHERE (%I)::bigint = $1',
            version_row.source_view_oid::regclass, version_row.key_column
        ) INTO candidate_count USING state_row.semantic_key;
        IF candidate_count = 0 THEN
            UPDATE pgreact_internal.activation_state
            SET active = false, current_bindings = NULL,
                deactivated_at = clock_timestamp(), last_seen_at = clock_timestamp()
            WHERE rule_version_id = target_version_id
              AND activation_id = state_row.activation_id;
            UPDATE pgreact_internal.agenda
            SET state = 'SUPERSEDED', completed_at = clock_timestamp()
            WHERE rule_version_id = target_version_id
              AND activation_id = state_row.activation_id
              AND state IN ('PENDING', 'RETRY_WAIT');
            PERFORM pgreact_internal.emit_event(
                version_row, state_row.activation_id, state_row.generation, 0,
                'DEACTIVATE', state_row.last_active_bindings, NULL);
            changed := changed + 1;
        ELSIF candidate_count > 1 THEN
            RAISE EXCEPTION 'M24_DUPLICATE_KEY: policy source % contains multiple rows for semantic key %',
                version_row.source_view_name, state_row.semantic_key;
        END IF;
    END LOOP;

    FOR candidate IN EXECUTE format(
        'SELECT (%1$I)::bigint AS semantic_key, to_jsonb(source) AS bindings '
        'FROM %2$s source ORDER BY %1$I',
        version_row.key_column, version_row.source_view_oid::regclass)
    LOOP
        SELECT count(*) INTO candidate_count
        FROM pgreact_internal.activation_state
        WHERE rule_version_id = target_version_id
          AND semantic_key = candidate.semantic_key;
        IF candidate_count > 1 THEN
            RAISE EXCEPTION 'M24_DUPLICATE_STATE: policy source % contains duplicate state for semantic key %',
                version_row.source_view_name, candidate.semantic_key;
        END IF;
        canonical := pgreact_internal.canonical_bigint_v1(candidate.semantic_key);
        digest := pgreact_internal.activation_digest(target_version_id, canonical);
        activation := pgreact_internal.activation_uuid(digest);
        SELECT * INTO prior
        FROM pgreact_internal.activation_state
        WHERE rule_version_id = target_version_id
          AND activation_id = activation
        FOR UPDATE;
        IF prior.activation_id IS NULL OR NOT prior.active THEN
            generation := COALESCE(prior.generation, 0) + 1;
            INSERT INTO pgreact_internal.activation_state (
                rule_version_id, activation_id, semantic_key, canonical_key,
                canonical_key_digest, key_codec_version, active, generation,
                revision, current_bindings, last_active_bindings,
                first_seen_at, last_seen_at
            ) VALUES (
                target_version_id, activation, candidate.semantic_key, canonical,
                digest, 1, true, generation, 0, candidate.bindings,
                candidate.bindings, clock_timestamp(), clock_timestamp()
            )
            ON CONFLICT (rule_version_id, activation_id) DO UPDATE
            SET active = true, generation = EXCLUDED.generation, revision = 0,
                current_bindings = EXCLUDED.current_bindings,
                last_active_bindings = EXCLUDED.last_active_bindings,
                last_seen_at = EXCLUDED.last_seen_at, deactivated_at = NULL;
            PERFORM pgreact_internal.emit_event(
                version_row, activation, generation, 0, 'ACTIVATE', NULL, candidate.bindings);
            changed := changed + 1;
        ELSIF pgreact_internal.watched_changed(
            version_row, prior.current_bindings, candidate.bindings
        ) THEN
            next_revision := prior.revision + 1;
            PERFORM pgreact_internal.emit_event(
                version_row, activation, prior.generation, next_revision, 'CHANGE',
                prior.current_bindings, candidate.bindings);
            UPDATE pgreact_internal.activation_state
            SET revision = next_revision, current_bindings = candidate.bindings,
                last_active_bindings = candidate.bindings, last_seen_at = clock_timestamp()
            WHERE rule_version_id = target_version_id AND activation_id = activation;
            changed := changed + 1;
        ELSE
            UPDATE pgreact_internal.activation_state
            SET current_bindings = candidate.bindings,
                last_active_bindings = candidate.bindings, last_seen_at = clock_timestamp()
            WHERE rule_version_id = target_version_id AND activation_id = activation;
        END IF;
    END LOOP;
    RETURN changed;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m28_digest(normalized jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    relation_name text;
    relation_oid oid;
    relation_kind "char";
    source text;
    sources text := '';
BEGIN
    FOR relation_name IN
        SELECT value
        FROM jsonb_each_text(COALESCE(normalized -> 'spec', '{}'::jsonb))
        WHERE key IN ('condition', 'candidate_relation', 'population_relation',
                      'candidate_catalog', 'parameter_relation')
        ORDER BY key
    LOOP
        relation_oid := to_regclass(relation_name);
        IF relation_oid IS NULL THEN
            CONTINUE;
        END IF;
        SELECT c.relkind INTO relation_kind FROM pg_class c WHERE c.oid = relation_oid;
        source := CASE WHEN relation_kind IN ('v', 'm')
                       THEN pg_get_viewdef(relation_oid, true)
                       ELSE encode(pgreact_internal.source_row_signature(relation_oid), 'hex') END;
        sources := sources || '|' || relation_name || '=' || COALESCE(source, '');
    END LOOP;
    RETURN encode(sha256(convert_to(normalized::text || sources, 'UTF8')), 'hex');
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m28_validate_m41(declaration pgreact_api.declaration)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    findings jsonb := '[]'::jsonb;
    unknown_field text;
    relation_name text;
    required_field text;
    allowed_fields text[] := ARRAY[
        'condition', 'semantic_key', 'kind', 'on_activate', 'on_deactivate', 'on_change',
        'bootstrap_policy', 'candidate_relation', 'subject_key', 'candidate_key', 'priority',
        'results', 'valid_from', 'valid_to', 'max_candidates', 'primitive', 'duration',
        'deadline_column', 'family_name', 'parameter_relation', 'parameter_key',
        'parameter_value_columns', 'parameter_values', 'definition', 'program_name',
        'current_version', 'proposed_version', 'population_relation', 'population_key',
        'candidate_catalog', 'catalog_candidate_key', 'catalog_default_column',
        'require_default', 'exclusive', 'max_absolute_distribution_delta',
        'max_relative_distribution_delta', 'evidence_limit', 'population_limit', 'options',
        'delegate', 'salience', 'agenda_group', 'max_attempts', 'initial_backoff_seconds',
        'backoff_multiplier', 'max_backoff_seconds', 'change_columns', 'conflict_key_columns'
    ];
    target pgreact_api.declaration := declaration;
BEGIN
    IF target IS NULL THEN
        findings := findings || pgreact_internal.m28_finding(
            'M28_DECLARATION_NULL', 'ERROR', '<unnamed>', '<declaration>',
            'declaration is required', 'Build a versioned declaration with pgreact_api.declaration()');
        RETURN jsonb_build_object('normalized', NULL, 'findings', findings);
    END IF;
    IF (target).api_version IS DISTINCT FROM '1' THEN
        findings := findings || pgreact_internal.m28_finding(
            'M28_API_VERSION', 'ERROR', COALESCE((target).name, '<unnamed>'), 'api_version',
            'only declaration API version 1 is supported', 'Set api_version to 1');
    END IF;
    IF (target).kind IS NULL OR (target).kind NOT IN (
        'rule', 'derived_program', 'temporal_policy', 'shared_condition',
        'effective_policy', 'parameter_family', 'decision_program', 'decision_analysis') THEN
        findings := findings || pgreact_internal.m28_finding(
            'M28_KIND', 'ERROR', COALESCE((target).name, '<unnamed>'), 'kind',
            'declaration kind is unsupported',
            'Use rule, derived_program, temporal_policy, shared_condition, effective_policy, parameter_family, decision_program, or decision_analysis');
    END IF;
    IF (target).name IS NULL OR (target).name !~ '^[A-Za-z_][A-Za-z0-9_.-]*$' THEN
        findings := findings || pgreact_internal.m28_finding(
            'M28_NAME', 'ERROR', COALESCE((target).name, '<unnamed>'), 'name',
            'name must be a stable non-empty public name',
            'Use letters, digits, underscore, dot, or hyphen and start with a letter or underscore');
    END IF;
    IF (target).spec IS NULL OR jsonb_typeof((target).spec) IS DISTINCT FROM 'object' THEN
        findings := findings || pgreact_internal.m28_finding(
            'M28_SPEC', 'ERROR', COALESCE((target).name, '<unnamed>'), 'spec',
            'spec must be a JSON object', 'Provide named declaration fields in spec');
        RETURN jsonb_build_object('normalized', pgreact_internal.m28_normalize(target), 'findings', findings);
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_object_keys((target).spec) AS key
    WHERE key <> ALL (allowed_fields)
    ORDER BY key LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        findings := findings || pgreact_internal.m28_finding(
            'M28_FIELD_UNKNOWN', 'ERROR', (target).name, 'spec.' || unknown_field,
            'declaration contains an unknown field',
            'Remove the field or use a newer supported API version', jsonb_build_object('field', unknown_field));
    END IF;
    IF (target).kind IN ('rule', 'temporal_policy', 'shared_condition', 'effective_policy') THEN
        FOREACH required_field IN ARRAY ARRAY['condition', 'semantic_key'] LOOP
            IF NOT ((target).spec ? required_field)
               OR NULLIF(btrim((target).spec ->> required_field), '') IS NULL THEN
                findings := findings || pgreact_internal.m28_finding(
                    'M28_FIELD_REQUIRED', 'ERROR', (target).name, 'spec.' || required_field,
                    'required declaration field is missing', 'Provide a stable named value');
            END IF;
        END LOOP;
        relation_name := (target).spec ->> 'condition';
        IF relation_name IS NOT NULL AND relation_name !~ '^[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*$' THEN
            findings := findings || pgreact_internal.m28_finding(
                'M28_RELATION_NAME', 'ERROR', (target).name, 'spec.condition',
                'relation references must be schema-qualified', 'Use schema_name.object_name');
        ELSIF relation_name IS NOT NULL AND to_regclass(relation_name) IS NULL THEN
            findings := findings || pgreact_internal.m28_finding(
                'M28_RELATION_NOT_FOUND', 'ERROR', (target).name, 'spec.condition',
                'declared PostgreSQL relation was not found', 'Create the relation or correct its qualified name');
        END IF;
    ELSIF (target).kind = 'derived_program' THEN
        IF jsonb_typeof((target).spec -> 'definition') IS DISTINCT FROM 'object' THEN
            findings := findings || pgreact_internal.m28_finding(
                'M28_FIELD_REQUIRED', 'ERROR', (target).name, 'spec.definition',
                'derived programs require a named definition object', 'Provide the existing derived-program definition');
        END IF;
    ELSIF (target).kind = 'parameter_family' THEN
        FOREACH required_field IN ARRAY ARRAY['parameter_relation', 'parameter_key', 'parameter_value_columns'] LOOP
            IF NOT ((target).spec ? required_field)
               OR NULLIF(btrim((target).spec ->> required_field), '') IS NULL THEN
                findings := findings || pgreact_internal.m28_finding(
                    'M28_FIELD_REQUIRED', 'ERROR', (target).name, 'spec.' || required_field,
                    'required parameter-family field is missing', 'Provide the existing named family fields');
            END IF;
        END LOOP;
    ELSIF (target).kind = 'decision_program' THEN
        FOREACH required_field IN ARRAY ARRAY['candidate_relation', 'subject_key', 'candidate_key', 'priority', 'results'] LOOP
            IF NOT ((target).spec ? required_field)
               OR NULLIF(btrim((target).spec ->> required_field), '') IS NULL THEN
                findings := findings || pgreact_internal.m28_finding(
                    'M28_FIELD_REQUIRED', 'ERROR', (target).name, 'spec.' || required_field,
                    'required decision-program field is missing', 'Provide the existing named decision fields');
            END IF;
        END LOOP;
        relation_name := (target).spec ->> 'candidate_relation';
        IF relation_name IS NOT NULL AND relation_name !~ '^[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*$' THEN
            findings := findings || pgreact_internal.m28_finding(
                'M28_RELATION_NAME', 'ERROR', (target).name, 'spec.candidate_relation',
                'relation references must be schema-qualified', 'Use schema_name.object_name');
        ELSIF relation_name IS NOT NULL AND to_regclass(relation_name) IS NULL THEN
            findings := findings || pgreact_internal.m28_finding(
                'M28_RELATION_NOT_FOUND', 'ERROR', (target).name, 'spec.candidate_relation',
                'declared PostgreSQL relation was not found', 'Create the relation or correct its qualified name');
        END IF;
        IF (jsonb_typeof((target).spec -> 'results') IS DISTINCT FROM 'array'
            OR CASE WHEN jsonb_typeof((target).spec -> 'results') = 'array'
                    THEN jsonb_array_length((target).spec -> 'results') = 0 ELSE false END) THEN
            findings := findings || pgreact_internal.m28_finding(
                'M28_RESULTS', 'ERROR', (target).name, 'spec.results',
                'results must be a non-empty array of column names', 'Name at least one result column');
        END IF;
    ELSIF (target).kind = 'decision_analysis' THEN
        FOREACH required_field IN ARRAY ARRAY['program_name', 'current_version', 'proposed_version', 'population_relation', 'population_key', 'candidate_catalog'] LOOP
            IF NOT ((target).spec ? required_field)
               OR NULLIF(btrim((target).spec ->> required_field), '') IS NULL THEN
                findings := findings || pgreact_internal.m28_finding(
                    'M28_FIELD_REQUIRED', 'ERROR', (target).name, 'spec.' || required_field,
                    'required decision-analysis field is missing', 'Provide the existing M27 analysis identity');
            END IF;
        END LOOP;
    END IF;
    RETURN jsonb_build_object('normalized', pgreact_internal.m28_normalize(target), 'findings', findings);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m28_validate(declaration pgreact_api.declaration)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE sanitized pgreact_api.declaration;
    result jsonb;
    policy jsonb;
    policy_findings jsonb := '[]'::jsonb;
BEGIN
    IF declaration IS NOT NULL AND (declaration).kind = 'decision_program' THEN
        policy := (declaration).spec -> 'evidence_snapshot';
        IF (declaration).spec ? 'evidence_snapshot' THEN
            policy_findings := pgreact_internal.m42_policy_findings(policy, (declaration).name);
        END IF;
        sanitized := ROW(
            (declaration).api_version, (declaration).kind, (declaration).name,
            CASE WHEN (declaration).spec IS NULL THEN NULL
                 ELSE (declaration).spec - 'evidence_snapshot' END
        )::pgreact_api.declaration;
    ELSE
        sanitized := declaration;
    END IF;
    result := pgreact_internal.m28_validate_m41(sanitized);
    IF jsonb_array_length(policy_findings) > 0 THEN
        result := jsonb_set(result, '{findings}',
            COALESCE(result -> 'findings', '[]'::jsonb) || policy_findings, true);
    END IF;
    IF declaration IS NOT NULL AND (declaration).kind = 'decision_program'
       AND (declaration).spec ? 'evidence_snapshot'
       AND result -> 'normalized' IS NOT NULL THEN
        result := jsonb_set(result, '{normalized,spec,evidence_snapshot}', policy, true);
    END IF;
    RETURN result;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m29_member_exists(member_kind text, member_name text, member_version text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE found_member boolean := false;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM pgreact_internal.api_declarations
        WHERE kind = member_kind AND object_name = member_name AND state = 'DEPLOYED')
    INTO found_member;
    IF found_member THEN RETURN true; END IF;
    IF member_kind = 'rule' THEN
        SELECT EXISTS (SELECT 1 FROM pgreact.rules WHERE rule_name = member_name
                       AND (member_version IS NULL OR rule_version_id::text = member_version))
        INTO found_member;
    ELSIF member_kind = 'derived_program' THEN
        SELECT EXISTS (SELECT 1 FROM pgreact.derivation_programs WHERE program_name = member_name)
        INTO found_member;
    ELSIF member_kind = 'shared_condition' THEN
        SELECT EXISTS (SELECT 1 FROM pgreact_internal.shared_conditions WHERE condition_name = member_name)
        INTO found_member;
    ELSIF member_kind = 'effective_policy' THEN
        SELECT EXISTS (SELECT 1 FROM pgreact_internal.effective_policies WHERE policy_name = member_name)
        INTO found_member;
    ELSIF member_kind = 'parameter_family' THEN
        SELECT EXISTS (SELECT 1 FROM pgreact_internal.parameter_families WHERE family_name = member_name)
        INTO found_member;
    ELSIF member_kind = 'decision_program' THEN
        SELECT EXISTS (SELECT 1 FROM pgreact_internal.decision_programs WHERE program_name = member_name)
        INTO found_member;
    END IF;
    RETURN found_member;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m29_preview(declaration pgreact_api.declaration, operation text DEFAULT 'preview'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE checked jsonb;
    normalized jsonb;
    findings jsonb;
    snapshot jsonb;
    digest text;
    evidence_limit integer;
BEGIN
    checked := pgreact_internal.m29_validate(declaration);
    normalized := checked -> 'normalized';
    findings := checked -> 'findings';
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(findings) item WHERE item ->> 'severity' = 'ERROR') THEN
        RETURN pgreact_internal.m29_envelope(operation, normalized, 'attention',
            jsonb_build_object('read_only', true), findings);
    END IF;
    snapshot := pgreact_internal.m29_snapshot(normalized);
    digest := pgreact_internal.m29_digest(normalized, snapshot);
    evidence_limit := COALESCE((normalized -> 'spec' ->> 'evidence_limit')::integer, 100);
    RETURN pgreact_internal.m29_envelope(operation, normalized, 'ready',
        jsonb_build_object('read_only', true, 'preview_digest', digest,
            'version', normalized -> 'spec' ->> 'version',
            'member_count', jsonb_array_length(normalized -> 'spec' -> 'members'),
            'source_kind', snapshot ->> 'source_kind', 'source_name', snapshot ->> 'source_name',
            'subject_key', snapshot ->> 'subject_key',
            'complete_frontier', snapshot ->> 'complete_frontier',
            'applicability_fingerprint', snapshot ->> 'applicability_fingerprint',
            'eligible_subject_count', snapshot -> 'eligible_subject_count'),
        findings,
        jsonb_build_object('normalized_declaration', normalized, 'snapshot',
            jsonb_set(snapshot, '{eligible_subjects}',
                COALESCE((SELECT jsonb_agg(value ORDER BY value)
                          FROM jsonb_array_elements(snapshot -> 'eligible_subjects') value
                          LIMIT evidence_limit), '[]'::jsonb), true)),
        '[]'::jsonb);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m29_relation_fingerprint(source_oid oid, key_column name, complete_frontier timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE details jsonb;
    signature bytea;
BEGIN
    IF source_oid IS NULL THEN
        RETURN NULL;
    END IF;
    details := pgreact_internal.m29_relation_details(source_oid, key_column);
    signature := pgreact_internal.source_row_signature(source_oid);
    RETURN encode(sha256(convert_to(
        COALESCE(details::text, '') || ':' || encode(signature, 'hex') || ':' ||
        COALESCE(complete_frontier::text, ''), 'UTF8')), 'hex');
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m29_snapshot(normalized jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE app jsonb := normalized -> 'spec' -> 'applicability';
    source_oid oid;
    details jsonb;
    frontier timestamptz := (SELECT frontier FROM pgreact_internal.clock_frontier WHERE singleton);
    source_name text := COALESCE(app ->> 'relation', app ->> 'condition');
    source_version_id uuid;
    source_kind text := app ->> 'source_kind';
    key name := (app ->> 'subject_key')::name;
    fingerprint text;
BEGIN
    IF source_kind = 'shared_condition' THEN
        SELECT version.condition_version_id INTO source_version_id
        FROM pgreact_internal.shared_condition_versions version
        JOIN pgreact_internal.shared_conditions condition USING (condition_id)
        WHERE condition.condition_name = source_name AND version.state = 'ACTIVE'
          AND (app ->> 'version' IS NULL OR version.version::text = app ->> 'version');
    END IF;
    source_oid := to_regclass(source_name);
    details := pgreact_internal.m29_relation_details(source_oid, key);
    fingerprint := pgreact_internal.m29_relation_fingerprint(source_oid, key, frontier);
    RETURN jsonb_build_object('source_kind', source_kind, 'source_name', source_name,
        'source_oid', source_oid, 'source_version_id', source_version_id,
        'subject_key', key, 'subject_type',
        (SELECT a.atttypid::regtype::text FROM pg_attribute a
         WHERE a.attrelid = source_oid AND a.attname = key AND a.attnum > 0 AND NOT a.attisdropped),
        'complete_frontier', frontier, 'applicability_fingerprint', fingerprint,
        'eligible_subjects', details -> 'eligible_subjects',
        'eligible_subject_count', details -> 'row_count');
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m29_validate(declaration pgreact_api.declaration)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE findings jsonb := '[]'::jsonb;
    normalized jsonb;
    spec jsonb;
    applicability jsonb;
    member jsonb;
    member_kind text;
    member_name text;
    member_version text;
    source_kind text;
    source_name text;
    relation_oid oid;
    condition_version_id uuid;
    subject_key name;
    subject_type regtype;
    field text;
    duplicate text;
    details jsonb;
    valid_from timestamptz;
    valid_to timestamptz;
    evidence_limit integer;
    source_owner oid;
    source_kind_catalog "char";
    source_rls boolean;
    condition_key name;
BEGIN
    IF declaration IS NULL THEN
        RETURN jsonb_build_object('normalized', NULL, 'findings', jsonb_build_array(
            pgreact_internal.m29_finding('M29_DECLARATION_NULL', 'ERROR', '<unnamed>', '<declaration>',
                'policy-set declaration is required', 'Build it with pgreact_api.declaration().')));
    END IF;
    normalized := pgreact_internal.m29_normalize(declaration);
    spec := COALESCE((declaration).spec, '{}'::jsonb);
    IF (declaration).api_version IS DISTINCT FROM '1' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
            'M29_API_VERSION', 'ERROR', (declaration).name, 'api_version',
            'only declaration API version 1 is supported', 'Set api_version to 1.'));
    END IF;
    IF (declaration).kind IS DISTINCT FROM 'policy_set' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
            'M29_KIND', 'ERROR', COALESCE((declaration).name, '<unnamed>'), 'kind',
            'this validator accepts policy_set declarations', 'Use kind policy_set.'));
    END IF;
    IF (declaration).name IS NULL OR (declaration).name !~ '^[A-Za-z_][A-Za-z0-9_.-]*$' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
            'M29_NAME', 'ERROR', COALESCE((declaration).name, '<unnamed>'), 'name',
            'name must be a stable non-empty public name', 'Use letters, digits, underscore, dot, or hyphen.'));
    END IF;
    IF jsonb_typeof(spec) IS DISTINCT FROM 'object' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
            'M29_SPEC', 'ERROR', COALESCE((declaration).name, '<unnamed>'), 'spec',
            'spec must be a JSON object', 'Provide version, members, applicability, and effective bounds.'));
        RETURN jsonb_build_object('normalized', normalized, 'findings', findings);
    END IF;
    FOR field IN SELECT key FROM jsonb_object_keys(spec) key LOOP
        IF field NOT IN ('version', 'members', 'applicability', 'valid_from', 'valid_to', 'evidence_limit') THEN
            findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                'M29_FIELD_UNKNOWN', 'ERROR', (declaration).name, 'spec.' || field,
                'policy-set declaration contains an unknown field',
                'Remove it or use a field in the M29 policy-set contract.', jsonb_build_object('field', field)));
            EXIT;
        END IF;
    END LOOP;
    IF NULLIF(btrim(spec ->> 'version'), '') IS NULL
       OR length(spec ->> 'version') > 64 OR spec ->> 'version' !~ '^[A-Za-z0-9][A-Za-z0-9._-]*$' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
            'M29_VERSION', 'ERROR', (declaration).name, 'spec.version',
            'version must be a stable non-empty immutable identifier', 'Use a short value such as 1 or 2026-08.'));
    END IF;
    IF jsonb_typeof(spec -> 'members') IS DISTINCT FROM 'array'
       OR jsonb_array_length(COALESCE(spec -> 'members', '[]'::jsonb)) = 0 THEN
        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
            'M29_MEMBERS', 'ERROR', (declaration).name, 'spec.members',
            'members must be a non-empty array', 'List already-deployed policy targets.'));
    ELSIF jsonb_array_length(spec -> 'members') > 64 THEN
        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
            'M29_LIMIT', 'ERROR', (declaration).name, 'spec.members',
            'a policy set may contain at most 64 members', 'Split the population into smaller policy sets.'));
    ELSE
        FOR member IN SELECT value FROM jsonb_array_elements(spec -> 'members') value LOOP
            IF jsonb_typeof(member) IS DISTINCT FROM 'object' THEN
                findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                    'M29_MEMBER_SHAPE', 'ERROR', (declaration).name, 'spec.members',
                    'each member must be an object', 'Use kind, name, and version for every member.'));
                CONTINUE;
            END IF;
            member_kind := member ->> 'kind';
            member_name := member ->> 'name';
            member_version := member ->> 'version';
            SELECT key INTO field
            FROM jsonb_object_keys(member) key
            WHERE key NOT IN ('kind', 'name', 'version')
            ORDER BY key LIMIT 1;
            IF field IS NOT NULL THEN
                findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                    'M29_MEMBER_FIELD_UNKNOWN', 'ERROR', COALESCE(member_name, (declaration).name),
                    'spec.members', 'member contains an unknown field',
                    'Keep members to kind, name, and version.', jsonb_build_object('field', field)));
                field := NULL;
            END IF;
            IF member_kind NOT IN ('rule', 'derived_program', 'temporal_policy', 'effective_policy',
                                   'parameter_family', 'decision_program', 'shared_condition') THEN
                findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                    'M29_MEMBER_KIND', 'ERROR', COALESCE(member_name, (declaration).name), 'spec.members',
                    'member kind is unsupported', 'Use one of the released policy-bearing kinds.'));
            ELSIF NULLIF(btrim(member_name), '') IS NULL OR NULLIF(btrim(member_version), '') IS NULL THEN
                findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                    'M29_MEMBER_IDENTITY', 'ERROR', (declaration).name, 'spec.members',
                    'every member needs kind, name, and immutable version', 'Copy the exact deployed target identity.'));
            ELSIF NOT pgreact_internal.m29_member_exists(member_kind, member_name, member_version) THEN
                findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                    'M29_MEMBER_NOT_FOUND', 'ERROR', member_name, 'spec.members',
                    'the member target is not deployed', 'Deploy the member first and use its exact version.'));
            END IF;
            SELECT key INTO duplicate
            FROM jsonb_array_elements(spec -> 'members') value,
                 LATERAL (SELECT (value ->> 'kind') || ':' || (value ->> 'name') || ':' ||
                                  (value ->> 'version') AS key) item
            WHERE item.key = member_kind || ':' || member_name || ':' || member_version
            GROUP BY key HAVING count(*) > 1 LIMIT 1;
            IF duplicate IS NOT NULL THEN
                findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                    'M29_MEMBER_DUPLICATE', 'ERROR', (declaration).name, 'spec.members',
                    'a member target appears more than once', 'Keep each immutable member target once.',
                    jsonb_build_object('member', duplicate)));
                duplicate := NULL;
            END IF;
        END LOOP;
    END IF;
    applicability := spec -> 'applicability';
    IF jsonb_typeof(applicability) IS DISTINCT FROM 'object' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
            'M29_APPLICABILITY', 'ERROR', (declaration).name, 'spec.applicability',
            'applicability must name one relation or shared condition',
            'Use source_kind relation or shared_condition and one subject_key.'));
    ELSE
        source_kind := applicability ->> 'source_kind';
        source_name := COALESCE(applicability ->> 'relation', applicability ->> 'condition');
        subject_key := NULLIF(applicability ->> 'subject_key', '')::name;
        SELECT key INTO field
        FROM jsonb_object_keys(applicability) key
        WHERE key NOT IN ('source_kind', 'relation', 'condition', 'version', 'subject_key')
        ORDER BY key LIMIT 1;
        IF field IS NOT NULL THEN
            findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                'M29_FIELD_UNKNOWN', 'ERROR', (declaration).name, 'spec.applicability.' || field,
                'applicability contains an unknown field',
                'Remove the field or use the M29 applicability contract.', jsonb_build_object('field', field)));
            field := NULL;
        END IF;
        IF source_kind NOT IN ('relation', 'shared_condition') THEN
            findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                'M29_SOURCE_KIND', 'ERROR', (declaration).name, 'spec.applicability.source_kind',
                'applicability source kind is unsupported', 'Choose relation or shared_condition.'));
        ELSIF subject_key IS NULL THEN
            findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                'M29_SUBJECT_KEY', 'ERROR', (declaration).name, 'spec.applicability.subject_key',
                'a typed subject key is required', 'Name the one bigint, uuid, or text key column.'));
        ELSIF source_kind = 'relation' THEN
            IF source_name IS NULL OR source_name !~ '^[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*$' THEN
                findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                    'M29_SOURCE_NAME', 'ERROR', (declaration).name, 'spec.applicability.relation',
                    'relation sources must be schema-qualified', 'Use schema_name.object_name.'));
            ELSE
                relation_oid := to_regclass(source_name);
                IF relation_oid IS NULL THEN
                    findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                        'M29_SOURCE_NOT_FOUND', 'ERROR', source_name, 'spec.applicability.relation',
                        'the applicability relation does not exist', 'Create it before previewing the policy set.'));
                ELSE
                    SELECT relkind, relrowsecurity, relowner INTO source_kind_catalog, source_rls, source_owner
                    FROM pg_class WHERE oid = relation_oid;
                    IF source_kind_catalog NOT IN ('r', 'p', 'v', 'm', 'f') THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                            'M29_SOURCE_KIND', 'ERROR', source_name, 'spec.applicability.relation',
                            'the applicability source is not a finite PostgreSQL relation',
                            'Use a table, partitioned table, view, materialized view, or foreign table.'));
                    END IF;
                    IF source_rls THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                            'M29_RLS_UNSUPPORTED', 'ERROR', source_name, 'spec.applicability.relation',
                            'row-level-security sources are not supported',
                            'Expose an authorized non-RLS relation or view.'));
                    END IF;
                    IF NOT has_table_privilege(session_user, relation_oid, 'SELECT') THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                            'M29_SOURCE_UNAUTHORIZED', 'ERROR', source_name, 'spec.applicability.relation',
                            'the caller does not have SELECT on the applicability source',
                            'Grant SELECT on the source to the policy-set author.'));
                    END IF;
                    SELECT a.atttypid::regtype INTO subject_type
                    FROM pg_attribute a
                    WHERE a.attrelid = relation_oid AND a.attname = subject_key
                      AND a.attnum > 0 AND NOT a.attisdropped;
                    IF subject_type IS NULL THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                            'M29_SUBJECT_KEY_NOT_FOUND', 'ERROR', source_name, 'spec.applicability.subject_key',
                            'the subject key column does not exist', 'Use a column present in the source relation.'));
                    ELSIF subject_type NOT IN ('bigint'::regtype, 'uuid'::regtype, 'text'::regtype) THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                            'M29_SUBJECT_KEY_TYPE', 'ERROR', source_name, 'spec.applicability.subject_key',
                            'subject keys must be bigint, uuid, or text', 'Use one of the supported stable key types.'));
                    ELSE
                        IF subject_type = 'text'::regtype AND EXISTS (
                            SELECT 1 FROM pg_attribute a
                            JOIN pg_collation c ON c.oid = a.attcollation
                            WHERE a.attrelid = relation_oid AND a.attname = subject_key
                              AND (NOT c.collisdeterministic OR c.collname NOT IN ('C', 'default'))) THEN
                            findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                                'M29_SUBJECT_KEY_COLLATION', 'ERROR', source_name,
                                'spec.applicability.subject_key',
                                'text subject keys require a deterministic C collation',
                                'Use COLLATE "C" for the applicability key.'));
                        END IF;
                        details := pgreact_internal.m29_relation_details(relation_oid, subject_key);
                        IF (details ->> 'null_count')::bigint > 0 THEN
                            findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                                'M29_SUBJECT_NULL', 'ERROR', source_name, 'spec.applicability.subject_key',
                                'applicability rows must have non-null subject keys',
                                'Remove null gate rows before deployment.', details));
                        END IF;
                        IF (details ->> 'distinct_count')::bigint <> (details ->> 'row_count')::bigint THEN
                            findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                                'M29_SUBJECT_DUPLICATE', 'ERROR', source_name, 'spec.applicability.subject_key',
                                'applicability subject keys must be unique',
                                'Keep one gate row per eligible subject.', details));
                        END IF;
                        IF (details ->> 'row_count')::bigint > 100000 THEN
                            findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                                'M29_LIMIT', 'ERROR', source_name, 'spec.applicability.relation',
                                'applicability source exceeds the 100000-row limit',
                                'Partition or narrow the source before deployment.', details));
                        END IF;
                    END IF;
                END IF;
            END IF;
        ELSE
            SELECT version.condition_version_id, condition.key_columns[1]
            INTO condition_version_id, condition_key
            FROM pgreact_internal.shared_condition_versions version
            JOIN pgreact_internal.shared_conditions condition USING (condition_id)
            WHERE condition.condition_name = source_name
              AND version.state = 'ACTIVE'
              AND (applicability ->> 'version' IS NULL
                   OR version.version::text = applicability ->> 'version');
            IF condition_version_id IS NULL THEN
                findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                    'M29_SHARED_CONDITION_NOT_FOUND', 'ERROR', source_name, 'spec.applicability.condition',
                    'the named shared condition version is not active',
                    'Deploy the shared condition and use its active version.'));
            ELSIF condition_key IS DISTINCT FROM subject_key THEN
                findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                    'M29_SUBJECT_KEY_MISMATCH', 'ERROR', source_name, 'spec.applicability.subject_key',
                    'the set subject key must match the shared condition key',
                    'Use the shared condition’s declared key column.'));
            ELSE
                relation_oid := to_regclass(source_name);
                IF relation_oid IS NULL THEN
                    findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                        'M29_SOURCE_NOT_FOUND', 'ERROR', source_name, 'spec.applicability.condition',
                        'the shared condition relation is unavailable', 'Restore the shared condition before deployment.'));
                ELSE
                    subject_type := (SELECT a.atttypid::regtype FROM pg_attribute a
                                     WHERE a.attrelid = relation_oid AND a.attname = subject_key
                                       AND a.attnum > 0 AND NOT a.attisdropped);
                    details := pgreact_internal.m29_relation_details(relation_oid, subject_key);
                    IF subject_type NOT IN ('bigint'::regtype, 'uuid'::regtype, 'text'::regtype) THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                            'M29_SUBJECT_KEY_TYPE', 'ERROR', source_name, 'spec.applicability.subject_key',
                            'shared-condition subject keys must be bigint, uuid, or text',
                            'Change the shared condition key to a supported type.'));
                    ELSIF (details ->> 'null_count')::bigint > 0
                       OR (details ->> 'distinct_count')::bigint <> (details ->> 'row_count')::bigint THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                            'M29_SOURCE_NOT_CANONICAL', 'ERROR', source_name, 'spec.applicability.condition',
                            'the shared condition must expose one non-null unique subject row per subject',
                            'Repair the condition source and refresh its version.', details));
                    END IF;
                END IF;
            END IF;
        END IF;
    END IF;
    BEGIN
        valid_from := (spec ->> 'valid_from')::timestamptz;
    EXCEPTION WHEN OTHERS THEN
        valid_from := NULL;
    END;
    IF valid_from IS NULL THEN
        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
            'M29_VALID_FROM', 'ERROR', (declaration).name, 'spec.valid_from',
            'valid_from must be a timestamp', 'Use an ISO-8601 PostgreSQL timestamptz.'));
    END IF;
    IF NULLIF(spec ->> 'valid_to', '') IS NOT NULL THEN
        BEGIN
            valid_to := (spec ->> 'valid_to')::timestamptz;
        EXCEPTION WHEN OTHERS THEN
            valid_to := NULL;
        END;
        IF valid_to IS NULL OR valid_from IS NULL OR valid_to <= valid_from THEN
            findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
                'M29_VALID_BOUNDS', 'ERROR', (declaration).name, 'spec.valid_to',
                'valid_to must be later than valid_from', 'Use a half-open [valid_from, valid_to) interval.'));
        END IF;
    END IF;
    BEGIN
        evidence_limit := COALESCE((spec ->> 'evidence_limit')::integer, 100);
    EXCEPTION WHEN OTHERS THEN
        evidence_limit := 0;
    END;
    IF evidence_limit < 1 OR evidence_limit > 1000 THEN
        findings := findings || jsonb_build_array(pgreact_internal.m29_finding(
            'M29_EVIDENCE_LIMIT', 'ERROR', (declaration).name, 'spec.evidence_limit',
            'evidence_limit must be between 1 and 1000', 'Choose a bounded evidence page size.'));
    END IF;
    RETURN jsonb_build_object('normalized', normalized, 'findings', findings,
        'source', jsonb_build_object('relation', relation_oid, 'condition_version_id', condition_version_id,
                                     'subject_key', subject_key, 'subject_type', subject_type,
                                     'source_kind', source_kind, 'source_name', source_name),
        'valid_from', valid_from, 'valid_to', valid_to, 'evidence_limit', evidence_limit);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('normalized', normalized, 'findings', findings || jsonb_build_array(
        pgreact_internal.m29_finding('M29_VALIDATION', 'ERROR', COALESCE((declaration).name, '<unnamed>'),
            '<declaration>', SQLERRM, 'Correct the policy-set declaration and validate again.')));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m30_key_array(source jsonb, canonical text, plural_alias text, scalar_alias text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE value jsonb;
BEGIN
    value := source -> canonical;
    IF jsonb_typeof(value) = 'array' THEN
        RETURN value;
    END IF;
    IF plural_alias IS NOT NULL THEN
        value := source -> plural_alias;
        IF jsonb_typeof(value) = 'array' THEN
            RETURN value;
        END IF;
    END IF;
    IF scalar_alias IS NOT NULL THEN
        value := source -> scalar_alias;
        IF jsonb_typeof(value) = 'string' THEN
            RETURN jsonb_build_array(value);
        END IF;
    END IF;
    RETURN '[]'::jsonb;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m30_key_identity(key_types text[], key_values jsonb)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result bytea := decode('0202', 'hex') || int4send(cardinality(key_types));
    value jsonb;
    raw bytea;
    type_name text;
    type_tag text;
    position integer;
BEGIN
    IF cardinality(key_types) < 1 OR cardinality(key_types) > 4
       OR jsonb_typeof(key_values) IS DISTINCT FROM 'array'
       OR jsonb_array_length(key_values) <> cardinality(key_types) THEN
        RAISE EXCEPTION 'M30_KEY_ARITY: key identity needs one to four typed values';
    END IF;
    FOR position IN 1..cardinality(key_types) LOOP
        type_name := lower(key_types[position]);
        value := key_values -> (position - 1);
        IF jsonb_typeof(value) IS NULL OR jsonb_typeof(value) = 'null' THEN
            RAISE EXCEPTION 'M30_KEY_NULL: key identity components cannot be null';
        END IF;
        IF type_name = 'bigint' AND jsonb_typeof(value) = 'number' THEN
            raw := int8send((value #>> '{}')::bigint);
            type_tag := '01';
        ELSIF type_name = 'uuid' AND jsonb_typeof(value) = 'string' THEN
            raw := uuid_send((value #>> '{}')::uuid);
            type_tag := '02';
        ELSIF type_name = 'text' AND jsonb_typeof(value) = 'string' THEN
            raw := convert_to(value #>> '{}', 'UTF8');
            type_tag := '03';
        ELSE
            RAISE EXCEPTION 'M30_KEY_TYPE: value does not match supported key type %', type_name;
        END IF;
        result := result || decode(type_tag, 'hex') || int4send(length(raw)) || raw;
    END LOOP;
    RETURN result;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m30_relation_fingerprint(source_oid oid, key_names name[], complete_frontier timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE details jsonb;
    signature bytea;
BEGIN
    IF source_oid IS NULL THEN
        RETURN NULL;
    END IF;
    details := pgreact_internal.m30_relation_details(source_oid, key_names);
    signature := pgreact_internal.source_row_signature(source_oid);
    RETURN encode(sha256(convert_to(
        COALESCE(details -> 'eligibility_rows', '[]'::jsonb)::text
        || ':' || encode(signature, 'hex') || ':'
        || COALESCE(complete_frontier::text, ''), 'UTF8')), 'hex');
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m30_snapshot(normalized jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE app jsonb := normalized -> 'spec' -> 'applicability';
    source_oid oid := (app ->> 'relation_oid')::oid;
    key_names name[] := ARRAY(
        SELECT jsonb_array_elements_text(app -> 'subject_keys'))::name[];
    frontier timestamptz := (
        SELECT frontier FROM pgreact_internal.clock_frontier WHERE singleton);
    details jsonb;
    fingerprint text;
BEGIN
    IF source_oid IS NULL THEN
        source_oid := to_regclass(COALESCE(app ->> 'relation', app ->> 'condition'));
    END IF;
    details := pgreact_internal.m30_relation_details(source_oid, key_names);
    fingerprint := pgreact_internal.m30_relation_fingerprint(source_oid, key_names, frontier);
    RETURN jsonb_build_object(
        'source_kind', app ->> 'source_kind',
        'source_name', COALESCE(app ->> 'relation', app ->> 'condition'),
        'source_oid', source_oid,
        'subject_keys', to_jsonb(key_names),
        'complete_frontier', frontier,
        'applicability_fingerprint', fingerprint,
        'eligible_subject_count', details -> 'row_count',
        'eligible_subjects', details -> 'eligible_subjects',
        'eligibility_rows', details -> 'eligibility_rows');
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m30_subject_eligible(target pgreact_api.target, subject jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.policy_set_versions%ROWTYPE;
    requested_key_values jsonb := '[]'::jsonb;
    requested_key_types text[];
    key_name name;
    position integer := 0;
BEGIN
    SELECT version.* INTO version_row
    FROM pgreact_internal.policy_set_versions version
    JOIN pgreact_internal.policy_sets set USING (policy_set_id)
    WHERE set.set_name = (target).name
      AND ((target).version IS NULL OR version.version = (target).version)
      AND version.state = 'DEPLOYED'
    ORDER BY version.valid_from DESC LIMIT 1;
    IF NOT FOUND OR subject IS NULL THEN
        RETURN false;
    END IF;
    FOREACH key_name IN ARRAY version_row.subject_keys LOOP
        position := position + 1;
        requested_key_values := requested_key_values || jsonb_build_array(
            CASE WHEN jsonb_typeof(subject) = 'object'
                 THEN subject -> key_name::text
                 ELSE subject -> (position - 1) END);
    END LOOP;
    SELECT eligibility.key_types INTO requested_key_types
    FROM pgreact_internal.policy_set_eligibility eligibility
    WHERE eligibility.policy_set_version_id = version_row.policy_set_version_id
    LIMIT 1;
    IF requested_key_types IS NULL THEN
        SELECT array_agg(a.atttypid::regtype::text ORDER BY requested.ordinal)
        INTO requested_key_types
        FROM unnest(version_row.subject_keys) WITH ORDINALITY requested(key_name, ordinal)
        JOIN pg_attribute a ON a.attrelid = version_row.applicability_source_oid
                           AND a.attname = requested.key_name
                           AND a.attnum > 0 AND NOT a.attisdropped;
    END IF;
    RETURN EXISTS (
        SELECT 1 FROM pgreact_internal.policy_set_eligibility eligibility
        WHERE eligibility.policy_set_version_id = version_row.policy_set_version_id
          AND eligibility.subject_identity =
              pgreact_internal.m30_key_identity(requested_key_types, requested_key_values));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m30_validate(declaration pgreact_api.declaration)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE findings jsonb := '[]'::jsonb;
    normalized jsonb;
    spec jsonb;
    member jsonb;
    app jsonb;
    field text;
    member_kind text;
    member_name text;
    member_version text;
    source_kind text;
    source_name text;
    source_oid oid;
    source_owner oid;
    source_rls boolean;
    relation_kind "char";
    key_names name[];
    key_name name;
    key_types text[];
    details jsonb;
    source jsonb := '{}'::jsonb;
    valid_from timestamptz;
    valid_to timestamptz;
    evidence_limit integer;
    condition_version_id uuid;
BEGIN
    IF declaration IS NULL THEN
        RETURN jsonb_build_object('normalized', NULL, 'findings', jsonb_build_array(
            pgreact_internal.m30_finding('M30_DECLARATION_NULL', 'ERROR', '<unnamed>',
                '<declaration>', 'policy-set declaration is required',
                'Build it with pgreact_api.declaration().')));
    END IF;
    normalized := pgreact_internal.m30_normalize(declaration);
    spec := COALESCE((declaration).spec, '{}'::jsonb);
    IF (declaration).api_version IS DISTINCT FROM '1' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_API_VERSION', 'ERROR', (declaration).name, 'api_version',
            'only declaration API version 1 is supported', 'Set api_version to 1.'));
    END IF;
    IF (declaration).kind IS DISTINCT FROM 'policy_set' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_KIND', 'ERROR', COALESCE((declaration).name, '<unnamed>'), 'kind',
            'this validator accepts policy_set declarations', 'Use kind policy_set.'));
    END IF;
    IF (declaration).name IS NULL OR (declaration).name !~ '^[A-Za-z_][A-Za-z0-9_.-]*$' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_NAME', 'ERROR', COALESCE((declaration).name, '<unnamed>'), 'name',
            'name must be a stable non-empty public name',
            'Use letters, digits, underscore, dot, or hyphen.'));
    END IF;
    IF jsonb_typeof(spec) IS DISTINCT FROM 'object' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_SPEC', 'ERROR', COALESCE((declaration).name, '<unnamed>'), 'spec',
            'spec must be a JSON object',
            'Provide version, members, applicability, and effective bounds.'));
        RETURN jsonb_build_object('normalized', normalized, 'findings', findings);
    END IF;
    FOR field IN SELECT key FROM jsonb_object_keys(spec) key LOOP
        IF field NOT IN ('version', 'members', 'applicability', 'valid_from',
                         'valid_to', 'evidence_limit') THEN
            findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                'M30_FIELD_UNKNOWN', 'ERROR', (declaration).name, 'spec.' || field,
                'policy-set declaration contains an unknown field',
                'Remove it or use a field in the M30 policy-set contract.',
                jsonb_build_object('field', field)));
            EXIT;
        END IF;
    END LOOP;
    IF NULLIF(btrim(spec ->> 'version'), '') IS NULL
       OR length(spec ->> 'version') > 64
       OR spec ->> 'version' !~ '^[A-Za-z0-9][A-Za-z0-9._-]*$' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_VERSION', 'ERROR', (declaration).name, 'spec.version',
            'version must be a stable non-empty immutable identifier',
            'Use a short value such as 2 or 2026-08.'));
    END IF;
    IF jsonb_typeof(spec -> 'members') IS DISTINCT FROM 'array'
       OR jsonb_array_length(COALESCE(spec -> 'members', '[]'::jsonb)) = 0 THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_MEMBERS', 'ERROR', (declaration).name, 'spec.members',
            'members must be a non-empty array',
            'List already-deployed policy targets.'));
    ELSIF jsonb_array_length(spec -> 'members') > 64 THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_LIMIT', 'ERROR', (declaration).name, 'spec.members',
            'a policy set may contain at most 64 members',
            'Split the population into smaller policy sets.'));
    ELSE
        FOR member IN SELECT value FROM jsonb_array_elements(spec -> 'members') value LOOP
            member_kind := member ->> 'kind';
            member_name := member ->> 'name';
            member_version := member ->> 'version';
            IF jsonb_typeof(member) IS DISTINCT FROM 'object' THEN
                findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                    'M30_MEMBER_SHAPE', 'ERROR', (declaration).name, 'spec.members',
                    'each member must be an object',
                    'Use kind, name, version, keys, and scope_mode.'));
                CONTINUE;
            END IF;
            SELECT key INTO field FROM jsonb_object_keys(member) key
            WHERE key NOT IN ('kind', 'name', 'version', 'match_keys',
                              'semantic_key', 'semantic_keys', 'subject_keys',
                              'subject_key', 'scope_mode')
            ORDER BY key LIMIT 1;
            IF field IS NOT NULL THEN
                findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                    'M30_MEMBER_FIELD_UNKNOWN', 'ERROR', COALESCE(member_name, (declaration).name),
                    'spec.members.' || field, 'member contains an unknown field',
                    'Use the frozen M30 member identity fields.',
                    jsonb_build_object('field', field)));
            END IF;
            IF pgreact_internal.m30_member_disposition(member_kind) = 'UNSUPPORTED' THEN
                findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                    'M30_MEMBER_KIND', 'ERROR', COALESCE(member_name, (declaration).name),
                    'spec.members', 'member kind is unsupported by the frozen M30 matrix',
                    'Use rule, decision_program, or a documented specialized member kind.'));
            END IF;
            IF NULLIF(btrim(member_name), '') IS NULL
               OR NULLIF(btrim(member_version), '') IS NULL THEN
                findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                    'M30_MEMBER_IDENTITY', 'ERROR', (declaration).name, 'spec.members',
                    'every member needs kind, name, and immutable version',
                    'Copy the exact deployed target identity.'));
            ELSIF NOT pgreact_internal.m29_member_exists(member_kind, member_name, member_version) THEN
                findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                    'M30_MEMBER_NOT_FOUND', 'ERROR', member_name, 'spec.members',
                    'the member target is not deployed',
                    'Deploy the member first and use its exact version.'));
            END IF;
            IF member ->> 'scope_mode' IS DISTINCT FROM 'POLICY_SET_REQUIRED' THEN
                findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                    'M30_SCOPE_MODE', 'ERROR', COALESCE(member_name, (declaration).name),
                    'spec.members.scope_mode',
                    'policy-set members must explicitly require policy-set scope',
                    'Set scope_mode to POLICY_SET_REQUIRED.'));
            END IF;
            key_names := ARRAY(SELECT jsonb_array_elements_text(
                pgreact_internal.m30_key_array(member, 'match_keys', 'semantic_keys', 'semantic_key'))
                )::name[];
            IF cardinality(key_names) NOT BETWEEN 1 AND 4
               OR cardinality(key_names) <> (
                   SELECT count(DISTINCT value) FROM unnest(key_names) value) THEN
                findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                    'M30_MATCH_KEYS', 'ERROR', COALESCE(member_name, (declaration).name),
                    'spec.members.match_keys',
                    'match_keys must contain one to four distinct columns',
                    'Use the canonical match identity or a compatibility alias.'));
            END IF;
            FOREACH key_name IN ARRAY COALESCE(key_names, ARRAY[]::name[]) LOOP
                IF key_name !~ '^[A-Za-z_][A-Za-z0-9_]*$' THEN
                    findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                        'M30_MATCH_KEY_NAME', 'ERROR', COALESCE(member_name, (declaration).name),
                        'spec.members.match_keys',
                        'identity column names must be simple PostgreSQL names',
                        'Use an unquoted column name.'));
                END IF;
            END LOOP;
        END LOOP;
    END IF;
    app := spec -> 'applicability';
    source_kind := app ->> 'source_kind';
    source_name := COALESCE(app ->> 'relation', app ->> 'condition');
    key_names := ARRAY(SELECT jsonb_array_elements_text(
        normalized -> 'spec' -> 'applicability' -> 'subject_keys'))::name[];
    IF jsonb_typeof(app) IS DISTINCT FROM 'object'
       OR source_kind NOT IN ('relation', 'shared_condition')
       OR NULLIF(source_name, '') IS NULL THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_APPLICABILITY', 'ERROR', (declaration).name, 'spec.applicability',
            'applicability must name one relation or shared condition',
            'Use source_kind, source identity, and subject_keys.'));
    ELSIF cardinality(key_names) NOT BETWEEN 1 AND 4
          OR cardinality(key_names) <> (
              SELECT count(DISTINCT value) FROM unnest(key_names) value) THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_SUBJECT_KEYS', 'ERROR', (declaration).name,
            'spec.applicability.subject_keys',
            'subject_keys must contain one to four distinct columns',
            'Use bigint, uuid, or text COLLATE "C" columns.'));
    ELSE
        IF source_name !~ '^[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*$' THEN
            findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                'M30_SOURCE_NAME', 'ERROR', (declaration).name,
                'spec.applicability', 'applicability sources must be schema-qualified',
                'Use schema_name.object_name.'));
        ELSE
            source_oid := to_regclass(source_name);
            IF source_kind = 'shared_condition' THEN
                SELECT version.condition_version_id INTO condition_version_id
                FROM pgreact_internal.shared_condition_versions version
                JOIN pgreact_internal.shared_conditions condition USING (condition_id)
                WHERE condition.condition_name = source_name
                  AND version.state = 'ACTIVE'
                  AND (app ->> 'version' IS NULL
                       OR version.version::text = app ->> 'version');
                IF condition_version_id IS NULL THEN
                    findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                        'M30_SHARED_CONDITION_NOT_FOUND', 'ERROR', source_name,
                        'spec.applicability.condition',
                        'the named shared condition version is not active',
                        'Deploy the shared condition and use its active version.'));
                END IF;
            END IF;
            IF source_oid IS NULL THEN
                findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                    'M30_SOURCE_NOT_FOUND', 'ERROR', source_name,
                    'spec.applicability', 'the applicability source does not exist',
                    'Create or restore it before previewing the policy set.'));
            ELSE
                SELECT c.relkind, c.relrowsecurity, c.relowner
                INTO relation_kind, source_rls, source_owner
                FROM pg_class c WHERE c.oid = source_oid;
                IF relation_kind NOT IN ('r', 'p', 'v', 'm', 'f') THEN
                    findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                        'M30_SOURCE_KIND', 'ERROR', source_name, 'spec.applicability',
                        'the applicability source is not a finite PostgreSQL relation',
                        'Use a table, partitioned table, view, materialized view, or foreign table.'));
                END IF;
                IF source_rls THEN
                    findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                        'M30_RLS_UNSUPPORTED', 'ERROR', source_name, 'spec.applicability',
                        'row-level-security sources are not supported',
                        'Expose an authorized non-RLS relation or view.'));
                END IF;
                IF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
                    findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                        'M30_SOURCE_UNAUTHORIZED', 'ERROR', source_name, 'spec.applicability',
                        'the caller does not have SELECT on the applicability source',
                        'Grant SELECT on the source to the policy-set author.'));
                END IF;
                SELECT array_agg(a.atttypid::regtype::text ORDER BY requested.ordinal)
                INTO key_types
                FROM unnest(key_names) WITH ORDINALITY requested(key_name, ordinal)
                JOIN pg_attribute a ON a.attrelid = source_oid
                                   AND a.attname = requested.key_name
                                   AND a.attnum > 0 AND NOT a.attisdropped;
                IF cardinality(COALESCE(key_types, ARRAY[]::text[]))
                   <> cardinality(key_names) THEN
                    findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                        'M30_SUBJECT_KEY_NOT_FOUND', 'ERROR', source_name,
                        'spec.applicability.subject_keys',
                        'one or more subject key columns do not exist',
                        'Use columns present in the source relation.'));
                ELSIF EXISTS (
                    SELECT 1 FROM unnest(key_types) type_name
                    WHERE type_name NOT IN ('bigint', 'uuid', 'text')
                ) THEN
                    findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                        'M30_SUBJECT_KEY_TYPE', 'ERROR', source_name,
                        'spec.applicability.subject_keys',
                        'subject keys must be bigint, uuid, or text',
                        'Use the supported typed-key codec v2.'));
                ELSE
                    IF EXISTS (
                        SELECT 1
                        FROM unnest(key_names) WITH ORDINALITY requested(key_name, ordinal)
                        JOIN pg_attribute a ON a.attrelid = source_oid
                                             AND a.attname = requested.key_name
                        JOIN pg_collation c ON c.oid = a.attcollation
                        WHERE a.atttypid = 'text'::regtype
                          AND (NOT c.collisdeterministic OR c.collname NOT IN ('C', 'default'))
                    ) THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                            'M30_SUBJECT_KEY_COLLATION', 'ERROR', source_name,
                            'spec.applicability.subject_keys',
                            'text subject keys require deterministic C collation',
                            'Use text COLLATE "C" for the applicability key.'));
                    END IF;
                    details := pgreact_internal.m30_relation_details(source_oid, key_names);
                    IF (details ->> 'null_count')::bigint > 0 THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                            'M30_SUBJECT_NULL', 'ERROR', source_name,
                            'spec.applicability.subject_keys',
                            'applicability rows must have non-null subject keys',
                            'Remove null gate rows before deployment.', details));
                    END IF;
                    IF (details ->> 'distinct_count')::bigint
                       <> (details ->> 'row_count')::bigint THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                            'M30_SUBJECT_DUPLICATE', 'ERROR', source_name,
                            'spec.applicability.subject_keys',
                            'subject identities must be unique',
                            'Keep one row per eligible subject identity.', details));
                    END IF;
                    IF (details ->> 'row_count')::bigint > 100000 THEN
                        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                            'M30_LIMIT', 'ERROR', source_name, 'spec.applicability',
                            'applicability source exceeds the 100000-row limit',
                            'Partition or narrow the source before deployment.', details));
                    END IF;
                    source := jsonb_build_object(
                        'source_kind', source_kind,
                        'source_name', source_name,
                        'relation_oid', source_oid::text,
                        'condition_version_id', condition_version_id,
                        'subject_keys', to_jsonb(key_names),
                        'subject_types', to_jsonb(key_types));
                END IF;
            END IF;
        END IF;
    END IF;
    BEGIN
        valid_from := (spec ->> 'valid_from')::timestamptz;
    EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
        valid_from := NULL;
    END;
    IF valid_from IS NULL THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_VALID_FROM', 'ERROR', (declaration).name, 'spec.valid_from',
            'valid_from must be a timestamp',
            'Use an ISO-8601 PostgreSQL timestamptz.'));
    END IF;
    IF NULLIF(spec ->> 'valid_to', '') IS NOT NULL THEN
        BEGIN
            valid_to := (spec ->> 'valid_to')::timestamptz;
        EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
            valid_to := NULL;
        END;
        IF valid_to IS NULL OR valid_from IS NULL OR valid_to <= valid_from THEN
            findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
                'M30_VALID_BOUNDS', 'ERROR', (declaration).name, 'spec.valid_to',
                'valid_to must be later than valid_from',
                'Use a half-open [valid_from, valid_to) interval.'));
        END IF;
    END IF;
    BEGIN
        evidence_limit := COALESCE((spec ->> 'evidence_limit')::integer, 100);
    EXCEPTION WHEN invalid_text_representation THEN
        evidence_limit := 0;
    END;
    IF evidence_limit < 1 OR evidence_limit > 1000 THEN
        findings := findings || jsonb_build_array(pgreact_internal.m30_finding(
            'M30_EVIDENCE_LIMIT', 'ERROR', (declaration).name, 'spec.evidence_limit',
            'evidence_limit must be between 1 and 1000',
            'Choose a bounded evidence limit.'));
    END IF;
    RETURN jsonb_build_object(
        'normalized', normalized,
        'findings', findings,
        'source', source,
        'valid_from', valid_from,
        'valid_to', valid_to);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m31_binding_values(bindings jsonb, key_names name[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE key_name name;
    values jsonb := '[]'::jsonb;
BEGIN
    FOREACH key_name IN ARRAY key_names LOOP
        IF NOT (bindings ? key_name::text)
           OR bindings -> key_name::text IS NULL
           OR jsonb_typeof(bindings -> key_name::text) = 'null' THEN
            RAISE EXCEPTION 'M31_BINDING_KEY: binding does not contain non-null key %', key_name;
        END IF;
        values := values || jsonb_build_array(bindings -> key_name::text);
    END LOOP;
    RETURN values;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m31_decision_explain(target pgreact_api.target, subject jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
    subject_key bigint;
    runtime_status jsonb;
BEGIN
    runtime_status := pgreact_internal.m31_decision_status(target);
    IF subject IS NULL THEN
        RETURN runtime_status || jsonb_build_object('operation', 'explain');
    END IF;
    IF jsonb_typeof(subject) = 'object' THEN
        subject_key := (subject ->> 'subject')::bigint;
    ELSE
        subject_key := (subject #>> '{}')::bigint;
    END IF;
    result := pgreact_api.decision_explain((target).name, subject_key);
    RETURN result || jsonb_build_object(
        'operation', 'explain',
        'target', jsonb_build_object('kind', (target).kind, 'name', (target).name,
                                     'version', (target).version),
        'runtime', runtime_status -> 'summary');
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m31_doctor(target pgreact_api.target)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb := pgreact_internal.m31_policy_status(target);
    base_result jsonb := pgreact_internal.m30_doctor(target);
    version_id uuid;
    diagnostics jsonb;
    barrier_count bigint;
BEGIN
    version_id := NULLIF(result -> 'summary' ->> 'policy_set_version_id', '')::uuid;
    diagnostics := COALESCE(base_result -> 'diagnostics', '[]'::jsonb);
    SELECT count(*) INTO barrier_count FROM pgreact_internal.policy_set_runtime_barriers
    WHERE policy_set_version_id = version_id AND cleared_at IS NULL;
    IF barrier_count > 0 THEN
        diagnostics := diagnostics || jsonb_build_array(jsonb_build_object(
                'code', 'M31_RUNTIME_BLOCKED', 'severity', 'ERROR', 'blocker', true,
                'object_identity', (target).name,
                'message', 'runtime authority is blocked by an applicability barrier',
                'hint', 'Repair the source and run the policy set again.',
                'details', (SELECT jsonb_agg(to_jsonb(barrier))
                            FROM pgreact_internal.policy_set_runtime_barriers barrier
                            WHERE barrier.policy_set_version_id = version_id
                              AND barrier.cleared_at IS NULL)));
    END IF;
    IF barrier_count = 0 AND NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(diagnostics) diagnostic
        WHERE diagnostic ->> 'severity' = 'ERROR') THEN
        diagnostics := jsonb_build_array(jsonb_build_object(
            'code', 'M31_RUNTIME_READY', 'severity', 'INFO', 'blocker', false,
            'object_identity', (target).name,
            'message', 'eligibility and effective runtime state agree',
            'hint', 'Use run after an applicability change.'));
    END IF;
    RETURN result || jsonb_build_object(
        'operation', 'doctor', 'diagnostics', diagnostics);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m31_refresh_policy_set(target_set_version uuid, sampled_time timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.policy_set_versions%ROWTYPE;
    snapshot jsonb;
    source_schema text;
    source_kind "char";
    source_rls boolean;
    source_details jsonb;
    source_definition_digest text;
    key_names name[];
BEGIN
    PERFORM pg_advisory_xact_lock(5788046901200000);
    PERFORM pg_advisory_xact_lock(5788046901200004);
    SELECT version.* INTO version_row
    FROM pgreact_internal.policy_set_versions version
    WHERE version.policy_set_version_id = target_set_version
      AND version.state = 'DEPLOYED'
      AND version.valid_from <= sampled_time
      AND (version.valid_to IS NULL OR sampled_time < version.valid_to)
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO pgreact_internal.policy_set_runtime_barriers(
            policy_set_version_id, code, details, cleared_at)
        VALUES (target_set_version, 'M31_SET_NOT_EFFECTIVE',
                jsonb_build_object('sampled_time', sampled_time), NULL)
        ON CONFLICT (policy_set_version_id) DO UPDATE SET
            code = EXCLUDED.code, details = EXCLUDED.details,
            created_at = clock_timestamp(), cleared_at = NULL;
        RETURN false;
    END IF;
    BEGIN
        IF version_row.applicability_source_oid IS NULL THEN
            RAISE EXCEPTION 'M31_SOURCE_UNAVAILABLE: applicability source is not relational';
        END IF;
        SELECT namespace.nspname, relation.relkind, relation.relrowsecurity
        INTO source_schema, source_kind, source_rls
        FROM pg_namespace namespace
        JOIN pg_class relation ON relation.relnamespace = namespace.oid
        WHERE relation.oid = version_row.applicability_source_oid;
        IF source_schema IS NULL THEN
            RAISE EXCEPTION 'M31_SOURCE_UNAVAILABLE: applicability relation no longer exists';
        END IF;
        IF source_kind NOT IN ('r', 'p', 'v', 'm', 'f') THEN
            RAISE EXCEPTION 'M31_SOURCE_INVALID: applicability relation kind is unsupported';
        END IF;
        IF source_rls THEN
            RAISE EXCEPTION 'M31_SOURCE_RLS_PROTECTED: applicability relation uses row-level security';
        END IF;
        IF NOT has_table_privilege(session_user,
                                   version_row.applicability_source_oid, 'SELECT') THEN
            RAISE EXCEPTION 'M31_SOURCE_UNAUTHORIZED: applicability source is not readable';
        END IF;
        PERFORM set_config(
            'search_path', format('pg_catalog,pg_temp,%I', source_schema), true);
        key_names := ARRAY(SELECT jsonb_array_elements_text(
            version_row.normalized -> 'spec' -> 'applicability' -> 'subject_keys'))::name[];
        source_details := pgreact_internal.m30_relation_details(
            version_row.applicability_source_oid, key_names);
        IF (source_details ->> 'null_count')::bigint > 0 THEN
            RAISE EXCEPTION 'M31_SOURCE_INCOMPLETE: applicability subjects contain null keys';
        END IF;
        IF (source_details ->> 'distinct_count')::bigint
           <> (source_details ->> 'row_count')::bigint THEN
            RAISE EXCEPTION 'M31_SOURCE_DUPLICATE: applicability subjects are duplicated';
        END IF;
        IF (source_details ->> 'row_count')::bigint > 100000 THEN
            RAISE EXCEPTION 'M31_SOURCE_OVER_LIMIT: applicability source exceeds the row limit';
        END IF;
        source_definition_digest := pgreact_internal.m31_source_definition_digest(
            version_row.applicability_source_oid, key_names);
        IF version_row.applicability_source_definition_digest IS NOT NULL
           AND version_row.applicability_source_definition_digest
               IS DISTINCT FROM source_definition_digest THEN
            RAISE EXCEPTION 'M31_SOURCE_DRIFT: applicability relation definition changed';
        END IF;
        snapshot := pgreact_internal.m30_snapshot(jsonb_set(
            version_row.normalized, '{spec,applicability,relation_oid}',
            to_jsonb(version_row.applicability_source_oid::text), true));
    EXCEPTION WHEN OTHERS THEN
        INSERT INTO pgreact_internal.policy_set_runtime_barriers(
            policy_set_version_id, code, details, cleared_at)
        VALUES (target_set_version,
                CASE
                    WHEN SQLERRM LIKE 'M31_SOURCE_UNAUTHORIZED:%'
                        THEN 'M31_SOURCE_UNAUTHORIZED'
                    WHEN SQLERRM LIKE 'M31_SOURCE_RLS_PROTECTED:%'
                        THEN 'M31_SOURCE_RLS_PROTECTED'
                    WHEN SQLERRM LIKE 'M31_SOURCE_INCOMPLETE:%'
                        THEN 'M31_SOURCE_INCOMPLETE'
                    WHEN SQLERRM LIKE 'M31_SOURCE_DUPLICATE:%'
                        THEN 'M31_SOURCE_DUPLICATE'
                    WHEN SQLERRM LIKE 'M31_SOURCE_OVER_LIMIT:%'
                        THEN 'M31_SOURCE_OVER_LIMIT'
                    WHEN SQLERRM LIKE 'M31_SOURCE_DRIFT:%'
                        THEN 'M31_SOURCE_DRIFT'
                    WHEN SQLERRM LIKE 'M31_SOURCE_INVALID:%'
                        THEN 'M31_SOURCE_INVALID'
                    WHEN SQLERRM LIKE 'M30_SOURCE_KEY:%'
                        OR SQLERRM LIKE 'M31_MEMBER_KEY:%'
                        THEN 'M31_SOURCE_INCOMPLETE'
                    WHEN SQLERRM LIKE 'M30_KEY_%'
                        THEN 'M31_SOURCE_MALFORMED'
                    WHEN SQLSTATE IN ('22P02', '22023')
                        THEN 'M31_SOURCE_MALFORMED'
                    ELSE 'M31_SOURCE_UNAVAILABLE'
                END,
                jsonb_build_object('message', SQLERRM), NULL)
        ON CONFLICT (policy_set_version_id) DO UPDATE SET
            code = EXCLUDED.code, details = EXCLUDED.details,
            created_at = clock_timestamp(), cleared_at = NULL;
        RETURN false;
    END;
    UPDATE pgreact_internal.policy_set_versions
    SET complete_frontier = (snapshot ->> 'complete_frontier')::timestamptz,
        applicability_fingerprint = snapshot ->> 'applicability_fingerprint',
        applicability_source_definition_digest = source_definition_digest,
        eligible_subjects = snapshot -> 'eligible_subjects',
        eligible_subject_count = (snapshot ->> 'eligible_subject_count')::bigint
    WHERE policy_set_version_id = target_set_version;
    DELETE FROM pgreact_internal.policy_set_eligibility
    WHERE policy_set_version_id = target_set_version;
    INSERT INTO pgreact_internal.policy_set_eligibility(
        policy_set_version_id, subject_identity, subject_values, key_types,
        key_codec_version, complete_frontier, source_fingerprint)
    SELECT target_set_version, decode(row_data ->> 'subject_identity', 'hex'),
           row_data -> 'subject_values',
           ARRAY(SELECT jsonb_array_elements_text(row_data -> 'key_types'))::text[],
           2, (snapshot ->> 'complete_frontier')::timestamptz,
           snapshot ->> 'applicability_fingerprint'
    FROM jsonb_array_elements(snapshot -> 'eligibility_rows') row_data;
    DELETE FROM pgreact_internal.policy_set_runtime_barriers
    WHERE policy_set_version_id = target_set_version;
    INSERT INTO pgreact_internal.policy_set_history(
        policy_set_version_id, event_kind, frontier, details)
    VALUES (target_set_version, 'REFRESHED',
        (snapshot ->> 'complete_frontier')::timestamptz,
        jsonb_build_object('runtime_state', 'AUTHORITATIVE',
                           'eligible_subject_count', snapshot -> 'eligible_subject_count'));
    RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m33_check_finding(finding jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    normalized jsonb;
    finding_code text;
    errors text[] := ARRAY[]::text[];
BEGIN
    IF finding IS NULL OR jsonb_typeof(finding) <> 'object' THEN
        RETURN jsonb_build_object(
            'valid', false,
            'code', NULL,
            'errors', jsonb_build_array('finding must be a JSON object')
        );
    END IF;

    normalized := pgreact_internal.m32_finding_shape(finding);
    finding_code := finding ->> 'code';
    IF NOT EXISTS (
        SELECT 1 FROM pgreact_internal.m33_finding_registry AS r
        WHERE r.code = finding_code
    ) THEN
        errors := array_append(errors, 'code is not in the stable v1 registry');
    END IF;
    IF NOT (finding ?& ARRAY[
        'code', 'severity', 'blocking', 'target',
        'field', 'message', 'hint', 'details'
    ]) THEN
        errors := array_append(errors, 'finding shape is incomplete');
    END IF;
    IF finding ->> 'severity' NOT IN ('ERROR', 'WARNING', 'INFO') THEN
        errors := array_append(errors, 'severity is not one of ERROR, WARNING, INFO');
    END IF;
    IF jsonb_typeof(finding -> 'blocking') <> 'boolean' THEN
        errors := array_append(errors, 'blocking must be boolean');
    END IF;
    IF jsonb_typeof(finding -> 'details') <> 'object' THEN
        errors := array_append(errors, 'details must be an object');
    END IF;

    RETURN jsonb_build_object(
        'valid', cardinality(errors) = 0,
        'code', finding_code,
        'normalized', normalized,
        'errors', to_jsonb(errors)
    );
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m34_compare(proposed pgreact_api.declaration, deployed pgreact_api.target, options jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE validation jsonb;
    proposed_normalized jsonb;
    current_normalized jsonb;
    current_owner oid;
    current_checksum text;
    after_checksum text;
    current_model jsonb;
    proposed_model jsonb;
    delta_model jsonb;
    current_rows jsonb;
    proposed_rows jsonb;
    delta_rows jsonb;
    lifecycle_rows jsonb;
    work_rows jsonb;
    current_count bigint;
    proposed_count bigint;
    missing_count bigint := 0;
    evidence_limit integer := 100;
    sampled_time timestamptz;
    source_frontier timestamptz;
    started_at timestamptz := clock_timestamp();
    comparison_complete boolean;
    target_kind text := (deployed).kind;
    target_name text := (deployed).name;
    target_version text := (deployed).version;
    source_oid oid;
    key_column name;
    subject_column name;
    candidate_column name;
    priority_column name;
    result_columns name[];
    max_candidates integer;
    relation_name text;
BEGIN
    IF options IS NULL OR jsonb_typeof(options) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M34_OPTIONS: options must be a JSON object';
    END IF;
    IF options ? 'evidence_limit' THEN
        IF jsonb_typeof(options -> 'evidence_limit') IS DISTINCT FROM 'number'
           OR (options ->> 'evidence_limit')::integer < 1
           OR (options ->> 'evidence_limit')::integer > 1000 THEN
            RAISE EXCEPTION 'M34_RESOURCE_LIMIT: evidence_limit must be between 1 and 1000';
        END IF;
        evidence_limit := (options ->> 'evidence_limit')::integer;
    END IF;
    IF options ? 'sampled_time'
       AND jsonb_typeof(options -> 'sampled_time') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'M34_OPTIONS: sampled_time must be an RFC3339 timestamp string';
    END IF;
    SELECT frontier INTO source_frontier
    FROM pgreact_internal.clock_frontier
    WHERE singleton;
    sampled_time := COALESCE(
        NULLIF(options ->> 'sampled_time', '')::timestamptz,
        source_frontier);
    IF sampled_time IS DISTINCT FROM source_frontier THEN
        RAISE EXCEPTION 'M34_SAMPLED_TIME: comparison must use the current authoritative frontier %',
            source_frontier;
    END IF;
    IF proposed IS NULL THEN
        RAISE EXCEPTION 'M34_INVALID_DECLARATION: proposed declaration is required';
    END IF;
    IF target_kind IS NULL OR target_name IS NULL THEN
        RAISE EXCEPTION 'M34_TARGET_NOT_FOUND: deployed target kind and name are required';
    END IF;
    IF (proposed).kind IS DISTINCT FROM target_kind THEN
        RAISE EXCEPTION 'M34_TARGET_KIND: proposed and deployed kinds must match';
    END IF;
    IF (proposed).name IS DISTINCT FROM target_name THEN
        RAISE EXCEPTION 'M34_TARGET_NAME: proposed declaration name must match deployed target name';
    END IF;
    validation := pgreact.validate(proposed);
    IF validation ->> 'state' = 'attention' THEN
        RETURN jsonb_build_object(
            'contract_version', 21,
            'operation', 'compare',
            'target', jsonb_build_object(
                'kind', target_kind, 'name', target_name, 'version', target_version),
            'state', 'attention',
            'summary', jsonb_build_object('read_only', true),
            'findings', validation -> 'findings',
            'current', '[]'::jsonb,
            'proposed', '[]'::jsonb,
            'delta', '[]'::jsonb,
            'lifecycle', '[]'::jsonb,
            'work', '[]'::jsonb,
            'truncated', false);
    END IF;
    proposed_normalized := COALESCE(
        validation -> 'evidence' -> 'normalized_declaration',
        pgreact_internal.m28_normalize(proposed));

    IF target_kind = 'policy_set' THEN
        SELECT version.normalized, set.owner_oid
        INTO current_normalized, current_owner
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE set.set_name = target_name
          AND version.state = 'DEPLOYED'
          AND version.valid_from <= source_frontier
          AND (version.valid_to IS NULL OR source_frontier < version.valid_to)
          AND (target_version IS NULL OR version.version = target_version)
        ORDER BY version.valid_from DESC, version.created_at DESC
        LIMIT 1;
    ELSE
        SELECT row_data.normalized, row_data.owner_oid
        INTO current_normalized, current_owner
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
        IF current_normalized IS NULL THEN
            RAISE EXCEPTION 'M34_TARGET_NOT_FOUND: deployed % % was not found',
                target_kind, target_name;
        END IF;
        IF target_version IS NOT NULL AND target_version <> '1' THEN
            RAISE EXCEPTION 'M34_TARGET_VERSION: only the deployed declaration version 1 is supported';
        END IF;
    END IF;
    IF current_normalized IS NULL THEN
        RAISE EXCEPTION 'M34_TARGET_NOT_FOUND: deployed % % was not found',
            target_kind, target_name;
    END IF;
    IF NOT pg_has_role(session_user, current_owner, 'USAGE')
       AND NOT pgreact_internal.is_operator_admin()
       AND NOT EXISTS (
           SELECT 1
           FROM pgreact_internal.application_roles role_row
           WHERE role_row.role_kind = 'reader'
             AND pg_has_role(session_user, role_row.role_oid, 'member')) THEN
        RAISE EXCEPTION 'M34_UNAUTHORIZED_TARGET: caller is not allowed to inspect %', target_name;
    END IF;
    current_checksum := pgreact_internal.m34_authoritative_checksum();

    IF target_kind = 'rule' THEN
        relation_name := proposed_normalized -> 'spec' ->> 'condition';
        source_oid := to_regclass(relation_name);
        PERFORM pgreact_internal.m34_require_source(source_oid, relation_name);
        key_column := (proposed_normalized -> 'spec' ->> 'semantic_key')::name;
        proposed_model := pgreact_internal.m34_rule_rows(
            source_oid, key_column, relation_name, evidence_limit);
        SELECT row_data.source_view_oid, row_data.key_column
        INTO source_oid, key_column
        FROM pgreact_internal.rule_versions row_data
        JOIN pgreact_internal.rules rule USING (rule_id)
        WHERE rule.rule_name = target_name
          AND row_data.state <> 'REMOVED'
        ORDER BY row_data.created_at DESC
        LIMIT 1;
        PERFORM pgreact_internal.m34_require_source(source_oid, source_oid::regclass::text);
        current_model := pgreact_internal.m34_current_rule_rows(target_name, evidence_limit);
    ELSIF target_kind = 'decision_program' THEN
        relation_name := proposed_normalized -> 'spec' ->> 'candidate_relation';
        source_oid := to_regclass(relation_name);
        PERFORM pgreact_internal.m34_require_source(source_oid, relation_name);
        subject_column := (proposed_normalized -> 'spec' ->> 'subject_key')::name;
        candidate_column := (proposed_normalized -> 'spec' ->> 'candidate_key')::name;
        priority_column := (proposed_normalized -> 'spec' ->> 'priority')::name;
        SELECT array_agg(value::name ORDER BY ordinal)
        INTO result_columns
        FROM jsonb_array_elements_text(proposed_normalized -> 'spec' -> 'results')
             WITH ORDINALITY item(value, ordinal);
        max_candidates := COALESCE(
            (proposed_normalized -> 'spec' ->> 'max_candidates')::integer, 1000);
        proposed_model := pgreact_internal.m34_decision_rows(
            source_oid, subject_column, candidate_column, priority_column,
            result_columns, max_candidates, relation_name, evidence_limit);
        SELECT version.candidate_relation_oid
        INTO source_oid
        FROM pgreact_internal.decision_program_versions version
        JOIN pgreact_internal.decision_programs program USING (program_id)
        WHERE program.program_name = target_name
          AND version.state = 'DEPLOYED'
        ORDER BY version.valid_from DESC, version.version_no DESC
        LIMIT 1;
        PERFORM pgreact_internal.m34_require_source(source_oid, source_oid::regclass::text);
        current_model := pgreact_internal.m34_current_decision_rows(target_name, evidence_limit);
        SELECT count(*) INTO missing_count
        FROM jsonb_array_elements(current_model -> 'rows') current_row
        WHERE NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
            WHERE proposed_row.value ->> 'subject_key' =
                  current_row.value ->> 'subject_key');
        IF missing_count > 0 THEN
            SELECT COALESCE(jsonb_agg(row_data ORDER BY row_data ->> 'subject_key'), '[]'::jsonb)
            INTO proposed_rows
            FROM (
                SELECT proposed_row.value AS row_data
                FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
                UNION ALL
                SELECT jsonb_build_object(
                           'subject_key', current_row.value ->> 'subject_key',
                           'result_key', NULL,
                           'state', 'NO_CANDIDATE',
                           'value', jsonb_build_object(
                               'candidate', NULL,
                               'priority', NULL,
                               'result', NULL,
                               'claimable', false),
                           'work', jsonb_build_object('would_be_work', false),
                           'evidence', jsonb_build_object(
                               'source', 'pgreact.decision_winners',
                               'complete', true))
                FROM jsonb_array_elements(current_model -> 'rows') current_row
                WHERE NOT EXISTS (
                    SELECT 1
                    FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
                    WHERE proposed_row.value ->> 'subject_key' =
                          current_row.value ->> 'subject_key')
            ) rows;
            proposed_model := jsonb_build_object(
                'rows', proposed_rows,
                'rows_considered',
                    (proposed_model ->> 'rows_considered')::bigint + missing_count,
                'truncated',
                    COALESCE((proposed_model ->> 'truncated')::boolean, false)
                    OR ((
                        proposed_model ->> 'rows_considered')::bigint + missing_count
                        > evidence_limit));
        END IF;
    ELSIF target_kind = 'policy_set' THEN
        proposed_model := pgreact_internal.m34_policy_rows(
            current_normalized, proposed_normalized, target_name, evidence_limit) -> 'proposed';
        current_model := pgreact_internal.m34_policy_rows(
            current_normalized, proposed_normalized, target_name, evidence_limit) -> 'current';
    ELSE
        RAISE EXCEPTION 'M34_UNSUPPORTED_KIND: comparison does not approximate %', target_kind;
    END IF;

    current_rows := current_model -> 'rows';
    proposed_rows := proposed_model -> 'rows';
    delta_model := pgreact_internal.m34_delta(current_rows, proposed_rows);
    delta_rows := delta_model -> 'rows';
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
    INTO lifecycle_rows
    FROM jsonb_array_elements(delta_rows) item(value)
    WHERE item.value ->> 'change' <> 'UNCHANGED';
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
    INTO work_rows
    FROM jsonb_array_elements(proposed_rows) item(value)
    WHERE (item.value -> 'work' ->> 'would_be_work')::boolean;
    comparison_complete := NOT COALESCE((current_model ->> 'truncated')::boolean, false)
        AND NOT COALESCE((proposed_model ->> 'truncated')::boolean, false)
        AND jsonb_array_length(delta_rows) <= evidence_limit;
    after_checksum := pgreact_internal.m34_authoritative_checksum();
    IF current_checksum IS DISTINCT FROM after_checksum THEN
        RAISE EXCEPTION 'M34_AUTHORITATIVE_CHANGED: authoritative state changed during comparison';
    END IF;
    current_count := (current_model ->> 'rows_considered')::bigint;
    proposed_count := (proposed_model ->> 'rows_considered')::bigint;
    RETURN jsonb_build_object(
        'contract_version', 21,
        'operation', 'compare',
        'target', jsonb_build_object(
            'kind', target_kind, 'name', target_name, 'version', target_version),
        'state', CASE WHEN comparison_complete THEN 'ready' ELSE 'partial' END,
        'summary', jsonb_build_object(
            'read_only', true,
            'current_count', current_count,
            'proposed_count', proposed_count,
            'delta_counts', CASE WHEN comparison_complete
                THEN delta_model -> 'counts' ELSE NULL END,
            'counts_exact', comparison_complete,
            'affected_subject_count', CASE WHEN comparison_complete THEN
                COALESCE((delta_model -> 'counts' ->> 'added')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'removed')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'changed')::bigint, 0)
                ELSE NULL END,
            'would_be_work', COALESCE((
                SELECT count(*)
                FROM jsonb_array_elements(proposed_rows) item
                WHERE (item.value -> 'work' ->> 'would_be_work')::boolean), 0)),
        'evidence', jsonb_build_object(
            'sampled_time', sampled_time,
            'source_frontier', source_frontier,
            'applicability_snapshot', CASE WHEN target_kind = 'policy_set'
                THEN proposed_normalized -> 'spec' -> 'applicability' ELSE NULL END,
            'declaration_digest', encode(
                sha256(convert_to(proposed_normalized::text, 'UTF8')), 'hex'),
            'authoritative_checksum_before', current_checksum,
            'authoritative_checksum_after', after_checksum,
            'complete', comparison_complete,
            'evidence_limit', evidence_limit),
        'cost', jsonb_build_object(
            'rows_considered', current_count + proposed_count,
            'affected_subjects', CASE WHEN comparison_complete THEN
                COALESCE((delta_model -> 'counts' ->> 'added')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'removed')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'changed')::bigint, 0)
                ELSE NULL END,
            'dependency_fan_out', 0,
            'reevaluation', 0,
            'cascade_depth', 0,
            'would_be_work', COALESCE((
                SELECT count(*)
                FROM jsonb_array_elements(proposed_rows) item
                WHERE (item.value -> 'work' ->> 'would_be_work')::boolean), 0),
            'elapsed_ms', extract(epoch FROM clock_timestamp() - started_at) * 1000,
            'memory_bytes', NULL,
            'temporary_storage_bytes', 0),
        'findings', CASE WHEN comparison_complete THEN
            jsonb_build_array(pgreact_internal.m34_finding(
                'M34_NO_EFFECT', 'INFO', target_name, '<comparison>',
                'comparison completed without changing authoritative state',
                'No deployment or run is required to inspect this result.'))
            ELSE jsonb_build_array(pgreact_internal.m34_finding(
                'M34_COMPARISON_INCOMPLETE', 'WARNING', target_name, '<comparison>',
                'evidence was truncated at the requested limit',
                'Increase evidence_limit or inspect the relational result stream.'))
            END,
        'current', pgreact_internal.m34_raw_rows(
            current_rows, current_count, evidence_limit) -> 'rows',
        'proposed', pgreact_internal.m34_raw_rows(
            proposed_rows, proposed_count, evidence_limit) -> 'rows',
        'delta', pgreact_internal.m34_raw_rows(
            delta_rows,
            jsonb_array_length(delta_rows),
            evidence_limit) -> 'rows',
        'lifecycle', pgreact_internal.m34_raw_rows(
            lifecycle_rows,
            jsonb_array_length(lifecycle_rows),
            evidence_limit) -> 'rows',
        'work', pgreact_internal.m34_raw_rows(
            work_rows,
            jsonb_array_length(work_rows),
            evidence_limit) -> 'rows',
        'truncated', NOT comparison_complete);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m34_require_source(source_oid oid, source_name text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE rls_enabled boolean;
BEGIN
    IF source_oid IS NULL THEN
        RAISE EXCEPTION 'M34_SOURCE_DRIFT: source relation % no longer exists', source_name;
    END IF;
    SELECT relrowsecurity INTO rls_enabled
    FROM pg_class
    WHERE oid = source_oid;
    IF rls_enabled THEN
        RAISE EXCEPTION 'M34_RLS_UNSUPPORTED: source relation % uses row-level security', source_name;
    END IF;
    IF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
        RAISE EXCEPTION 'M34_UNAUTHORIZED_SOURCE: caller lacks SELECT on source relation %', source_name;
    END IF;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m35_apply_changes(source_oid oid, key_column name, change_set jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE rows jsonb;
    item jsonb;
    operation text;
    key_text text;
    existing jsonb;
    row_count bigint;
    duplicate_count bigint;
    null_count bigint;
    unknown_field text;
    key_type regtype;
BEGIN
    PERFORM pgreact_internal.m35_require_source(source_oid, source_oid::regclass::text);
    IF jsonb_typeof(change_set) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: change_set must be a JSON array';
    END IF;
    SELECT a.atttypid::regtype INTO key_type
    FROM pg_attribute a
    WHERE a.attrelid = source_oid AND a.attname = key_column
      AND a.attnum > 0 AND NOT a.attisdropped;
    IF key_type IS DISTINCT FROM 'bigint'::regtype THEN
        RAISE EXCEPTION 'M35_CHANGE_KEY: identity column % must be bigint', key_column;
    END IF;
    EXECUTE format('SELECT count(*) FROM %s WHERE %I IS NULL', source_oid::regclass, key_column)
    INTO null_count;
    IF null_count > 0 THEN
        RAISE EXCEPTION 'M35_CHANGE_KEY: source relation contains null identities';
    END IF;
    EXECUTE format(
        'SELECT count(*) FROM (SELECT %1$I FROM %2$s GROUP BY %1$I HAVING count(*) > 1) d',
        key_column, source_oid::regclass)
    INTO duplicate_count;
    IF duplicate_count > 0 THEN
        RAISE EXCEPTION 'M35_CHANGE_DUPLICATE: source relation contains duplicate identities';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'object'
           OR NOT (item.value ?& ARRAY['relation', 'operation', 'ordinal', 'key', 'before', 'after'])
           OR (SELECT count(*) FROM jsonb_object_keys(item.value)) <> 6
    ) THEN
        RAISE EXCEPTION 'M35_CHANGE_REQUIRED_FIELD: every change must contain relation, operation, ordinal, key, before, and after';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_array_elements(change_set) item(value),
         jsonb_object_keys(item.value) AS key
    WHERE key NOT IN ('relation', 'operation', 'ordinal', 'key', 'before', 'after')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M35_CHANGE_UNKNOWN_FIELD: change field % is not supported', unknown_field;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        WHERE jsonb_typeof(item.value -> 'ordinal') IS DISTINCT FROM 'number'
           OR item.value ->> 'ordinal' !~ '^[1-9][0-9]*$'
    ) THEN
        RAISE EXCEPTION 'M35_CHANGE_ORDINAL: ordinals must be positive integers';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        GROUP BY (item.value ->> 'ordinal')::bigint
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'M35_CHANGE_DUPLICATE: ordinals must be unique';
    END IF;
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.%1$I), ''[]''::jsonb)
         FROM %2$s s', key_column, source_oid::regclass)
    INTO rows;
    FOR item IN
        SELECT value
        FROM jsonb_array_elements(change_set) AS change(value)
        ORDER BY (value ->> 'ordinal')::bigint
    LOOP
        IF to_regclass(item ->> 'relation') IS DISTINCT FROM source_oid THEN
            RAISE EXCEPTION 'M35_CHANGE_RELATION: change relation % does not match %',
                item ->> 'relation', source_oid::regclass;
        END IF;
        operation := item ->> 'operation';
        IF operation IS NULL OR operation NOT IN ('INSERT', 'UPDATE', 'DELETE') THEN
            RAISE EXCEPTION 'M35_CHANGE_OPERATION: operation % is not supported', operation;
        END IF;
        IF jsonb_typeof(item -> 'key') IS DISTINCT FROM 'object'
           OR (SELECT count(*) FROM jsonb_object_keys(item -> 'key')) <> 1
           OR NOT (item -> 'key' ? key_column::text)
           OR jsonb_typeof(item -> 'key' -> key_column::text) IS DISTINCT FROM 'number'
           OR item -> 'key' ->> key_column::text !~ '^-?[0-9]+$' THEN
            RAISE EXCEPTION 'M35_CHANGE_KEY: key must contain one integer % value', key_column;
        END IF;
        key_text := item -> 'key' ->> key_column::text;
        IF operation = 'INSERT' THEN
            IF jsonb_typeof(item -> 'before') IS DISTINCT FROM 'null'
               OR jsonb_typeof(item -> 'after') IS DISTINCT FROM 'object' THEN
                RAISE EXCEPTION 'M35_CHANGE_ROW: INSERT requires a null before image and an after image';
            END IF;
            PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'after', 'after');
            IF item -> 'after' ->> key_column::text IS DISTINCT FROM key_text THEN
                RAISE EXCEPTION 'M35_CHANGE_KEY: INSERT key does not match its after image';
            END IF;
            SELECT count(*) INTO row_count
            FROM jsonb_array_elements(rows) current_row(value)
            WHERE current_row.value ->> key_column::text = key_text;
            IF row_count > 0 THEN
                RAISE EXCEPTION 'M35_CHANGE_CONFLICT: INSERT identity % already exists', key_text;
            END IF;
            rows := rows || jsonb_build_array(item -> 'after');
        ELSE
            IF jsonb_typeof(item -> 'before') IS DISTINCT FROM 'object'
               OR jsonb_typeof(item -> 'after') IS DISTINCT FROM
                  (CASE WHEN operation = 'UPDATE' THEN 'object' ELSE 'null' END) THEN
                RAISE EXCEPTION 'M35_CHANGE_ROW: % requires the correct before and after images', operation;
            END IF;
            PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'before', 'before');
            IF operation = 'UPDATE' THEN
                PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'after', 'after');
                IF item -> 'after' ->> key_column::text IS DISTINCT FROM key_text THEN
                    RAISE EXCEPTION 'M35_CHANGE_KEY: UPDATE cannot change its identity';
                END IF;
            END IF;
            SELECT count(*), (array_agg(current_row.value))[1]
            INTO row_count, existing
            FROM jsonb_array_elements(rows) current_row(value)
            WHERE current_row.value ->> key_column::text = key_text;
            IF row_count = 0 THEN
                RAISE EXCEPTION 'M35_CHANGE_STALE: identity % is not present', key_text;
            ELSIF row_count > 1 THEN
                RAISE EXCEPTION 'M35_CHANGE_DUPLICATE: identity % is ambiguous', key_text;
            ELSIF existing IS DISTINCT FROM item -> 'before' THEN
                RAISE EXCEPTION 'M35_CHANGE_STALE: before image for identity % is stale', key_text;
            END IF;
            SELECT COALESCE(jsonb_agg(
                       CASE WHEN current_row.value ->> key_column::text = key_text
                            THEN CASE WHEN operation = 'UPDATE'
                                      THEN item -> 'after' ELSE NULL END
                            ELSE current_row.value END
                       ORDER BY current_row.ordinality), '[]'::jsonb)
            INTO rows
            FROM jsonb_array_elements(rows) WITH ORDINALITY current_row(value, ordinality)
            WHERE NOT (operation = 'DELETE'
                       AND current_row.value ->> key_column::text = key_text);
        END IF;
    END LOOP;
    RETURN rows;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m35_check_image(source_oid oid, image jsonb, image_name text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE expected_count bigint;
    actual_count bigint;
    unknown_field text;
    missing_field text;
    converted jsonb;
BEGIN
    IF jsonb_typeof(image) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M35_CHANGE_ROW: % must be a complete JSON object', image_name;
    END IF;
    SELECT count(*) INTO expected_count
    FROM pg_attribute
    WHERE attrelid = source_oid AND attnum > 0 AND NOT attisdropped;
    SELECT count(*) INTO actual_count FROM jsonb_object_keys(image);
    SELECT key INTO unknown_field
    FROM jsonb_object_keys(image) AS key
    WHERE NOT EXISTS (
        SELECT 1 FROM pg_attribute
        WHERE attrelid = source_oid AND attnum > 0 AND NOT attisdropped
          AND attname = key)
    ORDER BY key
    LIMIT 1;
    SELECT a.attname INTO missing_field
    FROM pg_attribute a
    WHERE a.attrelid = source_oid AND a.attnum > 0 AND NOT a.attisdropped
      AND NOT (image ? a.attname)
    ORDER BY a.attnum
    LIMIT 1;
    IF actual_count IS DISTINCT FROM expected_count OR unknown_field IS NOT NULL
       OR missing_field IS NOT NULL THEN
        RAISE EXCEPTION 'M35_CHANGE_ROW: % must contain exactly the source columns', image_name;
    END IF;
    BEGIN
        EXECUTE format(
            'SELECT to_jsonb(jsonb_populate_record(NULL::%s, $1))',
            source_oid::regclass)
        INTO converted
        USING image;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'M35_CHANGE_ROW: % does not match the source column types', image_name;
    END;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m35_compare(proposed pgreact_api.declaration, deployed pgreact_api.target, change_set jsonb, options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE effective_proposed pgreact_api.declaration;
    proposed_normalized jsonb;
    base jsonb;
    base_options jsonb;
    source_oid oid;
    source_label text;
    key_column name;
    target_kind text := (deployed).kind;
    target_name text := (deployed).name;
    target_version text := (deployed).version;
    evidence_limit integer := 100;
    max_changes integer := 1000;
    source_frontier timestamptz;
    sampled_time timestamptz;
    started_at timestamptz := clock_timestamp();
    source_checksum_before text;
    source_checksum_after text;
    authoritative_checksum_before text;
    authoritative_checksum_after text;
    source_rows jsonb;
    current_rows jsonb;
    proposed_rows jsonb;
    delta_rows jsonb;
    lifecycle_rows jsonb;
    work_rows jsonb;
    proposed_model jsonb;
    delta_model jsonb;
    current_count bigint;
    proposed_count bigint;
    missing_count bigint := 0;
    comparison_complete boolean;
    change_set_digest text;
    member_rows jsonb;
    subject_model jsonb;
    member_count bigint := 0;
    subject_count bigint := 0;
    key_names name[];
    result_columns name[];
    max_candidates integer;
BEGIN
    target_kind := (deployed).kind;
    target_name := (deployed).name;
    target_version := (deployed).version;
    effective_proposed := proposed;
    IF options IS NULL OR jsonb_typeof(options) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: options must be a JSON object';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_object_keys(options) AS key
        WHERE key NOT IN ('evidence_limit', 'sampled_time', 'max_changes')
    ) THEN
        RAISE EXCEPTION 'M35_CHANGE_UNKNOWN_FIELD: unsupported comparison option';
    END IF;
    IF options ? 'evidence_limit' THEN
        IF jsonb_typeof(options -> 'evidence_limit') IS DISTINCT FROM 'number'
           OR options ->> 'evidence_limit' !~ '^[1-9][0-9]*$'
           OR (options ->> 'evidence_limit')::integer > 1000 THEN
            RAISE EXCEPTION 'M35_RESOURCE_LIMIT: evidence_limit must be between 1 and 1000';
        END IF;
        evidence_limit := (options ->> 'evidence_limit')::integer;
    END IF;
    IF options ? 'max_changes' THEN
        IF jsonb_typeof(options -> 'max_changes') IS DISTINCT FROM 'number'
           OR options ->> 'max_changes' !~ '^[1-9][0-9]*$'
           OR (options ->> 'max_changes')::integer > 1000 THEN
            RAISE EXCEPTION 'M35_RESOURCE_LIMIT: max_changes must be between 1 and 1000';
        END IF;
        max_changes := (options ->> 'max_changes')::integer;
    END IF;
    IF jsonb_typeof(change_set) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: change_set must be a JSON array';
    END IF;
    IF jsonb_array_length(change_set) > max_changes THEN
        RAISE EXCEPTION 'M35_RESOURCE_LIMIT: change_set exceeds max_changes';
    END IF;
    IF options ? 'sampled_time'
       AND jsonb_typeof(options -> 'sampled_time') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: sampled_time must be an RFC3339 timestamp string';
    END IF;
    IF effective_proposed IS NULL THEN
        SELECT ROW(row_data.api_version, row_data.kind, row_data.object_name,
                   row_data.spec)::pgreact_api.declaration
        INTO effective_proposed
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
        SELECT row_data.normalized INTO proposed_normalized
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
        IF effective_proposed IS NULL THEN
            RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: deployed declaration is required';
        END IF;
    ELSE
        proposed_normalized := pgreact_internal.m28_normalize(effective_proposed);
    END IF;
    IF target_kind NOT IN ('rule', 'decision_program', 'policy_set') THEN
        RAISE EXCEPTION 'M35_UNSUPPORTED_SOURCE: target kind % is not supported', target_kind;
    END IF;
    IF (effective_proposed).kind IS DISTINCT FROM target_kind
       OR (effective_proposed).name IS DISTINCT FROM target_name THEN
        RAISE EXCEPTION 'M35_CHANGE_SET_INVALID: proposed and deployed targets must match';
    END IF;
    IF target_kind = 'rule' THEN
        source_label := proposed_normalized -> 'spec' ->> 'condition';
        key_column := (proposed_normalized -> 'spec' ->> 'semantic_key')::name;
    ELSIF target_kind = 'decision_program' THEN
        source_label := proposed_normalized -> 'spec' ->> 'candidate_relation';
        key_column := (proposed_normalized -> 'spec' ->> 'candidate_key')::name;
    ELSE
        source_label := proposed_normalized -> 'spec' -> 'applicability' ->> 'relation';
        SELECT array_agg(value::name ORDER BY ordinal)
        INTO key_names
        FROM jsonb_array_elements_text(
                 proposed_normalized -> 'spec' -> 'applicability' -> 'subject_keys')
             WITH ORDINALITY requested(value, ordinal);
        IF cardinality(key_names) IS DISTINCT FROM 1 THEN
            RAISE EXCEPTION 'M35_UNSUPPORTED_SOURCE: M35 requires one bigint policy subject key';
        END IF;
        key_column := key_names[1];
    END IF;
    source_oid := to_regclass(source_label);
    PERFORM pgreact_internal.m35_require_source(source_oid, source_label);
    source_checksum_before := pgreact_internal.m35_source_checksum(source_oid, key_column);
    base_options := options - 'max_changes';
    base := pgreact.compare(effective_proposed, deployed, base_options);
    IF base ->> 'state' = 'attention' THEN
        RETURN base || jsonb_build_object(
            'contract_version', 22,
            'simulation', 'hypothetical_fact_changes',
            'change_set_digest', encode(
                sha256(convert_to(change_set::text, 'UTF8')), 'hex'));
    END IF;
    source_rows := pgreact_internal.m35_apply_changes(source_oid, key_column, change_set);
    current_rows := base -> 'current';
    current_count := (base -> 'summary' ->> 'current_count')::bigint;
    IF target_kind = 'rule' THEN
        proposed_model := pgreact_internal.m35_rule_rows(
            source_rows, key_column, source_label, evidence_limit);
    ELSIF target_kind = 'decision_program' THEN
        SELECT array_agg(value::name ORDER BY ordinal)
        INTO result_columns
        FROM jsonb_array_elements_text(proposed_normalized -> 'spec' -> 'results')
             WITH ORDINALITY item(value, ordinal);
        max_candidates := COALESCE(
            (proposed_normalized -> 'spec' ->> 'max_candidates')::integer, 1000);
        proposed_model := pgreact_internal.m35_decision_rows(
            source_rows,
            (proposed_normalized -> 'spec' ->> 'subject_key')::name,
            (proposed_normalized -> 'spec' ->> 'candidate_key')::name,
            (proposed_normalized -> 'spec' ->> 'priority')::name,
            result_columns, max_candidates, source_label, evidence_limit);
        SELECT count(*) INTO missing_count
        FROM jsonb_array_elements(current_rows) current_row
        WHERE NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
            WHERE proposed_row.value ->> 'subject_key' = current_row.value ->> 'subject_key');
        IF missing_count > 0 THEN
            SELECT COALESCE(jsonb_agg(row_data ORDER BY row_data ->> 'subject_key'), '[]'::jsonb)
            INTO proposed_rows
            FROM (
                SELECT proposed_row.value AS row_data
                FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
                UNION ALL
                SELECT jsonb_build_object(
                           'subject_key', current_row.value ->> 'subject_key',
                           'result_key', NULL,
                           'state', 'NO_CANDIDATE',
                           'value', jsonb_build_object(
                               'candidate', NULL, 'priority', NULL, 'result', NULL),
                           'work', jsonb_build_object('would_be_work', false),
                           'evidence', jsonb_build_object(
                               'source', 'pgreact.decision_winners',
                               'hypothetical', true, 'complete', true))
                FROM jsonb_array_elements(current_rows) current_row
                WHERE NOT EXISTS (
                    SELECT 1 FROM jsonb_array_elements(proposed_model -> 'rows') proposed_row
                    WHERE proposed_row.value ->> 'subject_key' = current_row.value ->> 'subject_key')
            ) rows;
            proposed_model := jsonb_build_object(
                'rows', proposed_rows,
                'rows_considered', (proposed_model ->> 'rows_considered')::bigint + missing_count,
                'truncated', COALESCE((proposed_model ->> 'truncated')::boolean, false)
                    OR (proposed_model ->> 'rows_considered')::bigint + missing_count
                       > evidence_limit);
        END IF;
    ELSE
        subject_model := pgreact_internal.m35_policy_subject_rows(
            source_rows, key_column, source_label, evidence_limit);
        SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
        INTO member_rows
        FROM jsonb_array_elements(base -> 'proposed') item(value)
        WHERE item.value ->> 'subject_key' NOT LIKE 'subject:%';
        member_count := jsonb_array_length(
            COALESCE(proposed_normalized -> 'spec' -> 'members', '[]'::jsonb));
        subject_count := (subject_model ->> 'rows_considered')::bigint;
        proposed_model := jsonb_build_object(
            'rows', COALESCE(member_rows, '[]'::jsonb) || (subject_model -> 'rows'),
            'rows_considered', member_count + subject_count,
            'truncated', COALESCE((base ->> 'truncated')::boolean, false)
                OR COALESCE((subject_model ->> 'truncated')::boolean, false)
                OR member_count > evidence_limit);
    END IF;
    proposed_rows := proposed_model -> 'rows';
    proposed_count := (proposed_model ->> 'rows_considered')::bigint;
    delta_model := pgreact_internal.m34_delta(current_rows, proposed_rows);
    delta_rows := delta_model -> 'rows';
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
    INTO lifecycle_rows
    FROM jsonb_array_elements(delta_rows) item(value)
    WHERE item.value ->> 'change' <> 'UNCHANGED';
    SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
    INTO work_rows
    FROM jsonb_array_elements(proposed_rows) item(value)
    WHERE (item.value -> 'work' ->> 'would_be_work')::boolean;
    source_checksum_after := pgreact_internal.m35_source_checksum(source_oid, key_column);
    authoritative_checksum_before := base -> 'evidence' ->> 'authoritative_checksum_before';
    authoritative_checksum_after := pgreact_internal.m34_authoritative_checksum();
    IF source_checksum_before IS DISTINCT FROM source_checksum_after
       OR authoritative_checksum_before IS DISTINCT FROM authoritative_checksum_after THEN
        RAISE EXCEPTION 'M35_AUTHORITATIVE_CHANGED: authoritative source or pg-react state changed during comparison';
    END IF;
    source_frontier := (base -> 'evidence' ->> 'source_frontier')::timestamptz;
    sampled_time := (base -> 'evidence' ->> 'sampled_time')::timestamptz;
    comparison_complete := NOT COALESCE((base ->> 'truncated')::boolean, false)
        AND NOT COALESCE((proposed_model ->> 'truncated')::boolean, false)
        AND jsonb_array_length(delta_rows) <= evidence_limit;
    change_set_digest := encode(sha256(convert_to(change_set::text, 'UTF8')), 'hex');
    RETURN jsonb_build_object(
        'contract_version', 22,
        'operation', 'compare',
        'simulation', 'hypothetical_fact_changes',
        'target', jsonb_build_object(
            'kind', target_kind, 'name', target_name, 'version', target_version),
        'state', CASE WHEN comparison_complete THEN 'ready' ELSE 'partial' END,
        'summary', jsonb_build_object(
            'read_only', true,
            'current_count', current_count,
            'proposed_count', proposed_count,
            'delta_counts', CASE WHEN comparison_complete THEN delta_model -> 'counts' END,
            'counts_exact', comparison_complete,
            'affected_subject_count', CASE WHEN comparison_complete THEN
                COALESCE((delta_model -> 'counts' ->> 'added')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'removed')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'changed')::bigint, 0) END,
            'hypothetical_change_count', jsonb_array_length(change_set),
            'would_be_work', COALESCE((
                SELECT count(*) FROM jsonb_array_elements(proposed_rows) item
                WHERE (item.value -> 'work' ->> 'would_be_work')::boolean), 0)),
        'snapshot', jsonb_build_object(
            'source_relation', source_label,
            'source_frontier', source_frontier,
            'sampled_time', sampled_time,
            'applicability_snapshot', base -> 'evidence' -> 'applicability_snapshot',
            'authoritative_checksum_before', authoritative_checksum_before,
            'authoritative_checksum_after', authoritative_checksum_after,
            'source_checksum_before', source_checksum_before,
            'source_checksum_after', source_checksum_after),
        'evidence', jsonb_build_object(
            'declaration_digest', base -> 'evidence' ->> 'declaration_digest',
            'change_set_digest', change_set_digest,
            'changed_facts', change_set,
            'causal', jsonb_build_object(
                'changed_facts', jsonb_array_length(change_set),
                'support', 'production evaluator evidence',
                'complete', comparison_complete),
            'complete', comparison_complete,
            'evidence_limit', evidence_limit),
        'cost', jsonb_build_object(
            'rows_considered', current_count + proposed_count,
            'hypothetical_rows', jsonb_array_length(change_set),
            'affected_subjects', CASE WHEN comparison_complete THEN
                COALESCE((delta_model -> 'counts' ->> 'added')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'removed')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'changed')::bigint, 0) END,
            'dependency_fan_out', 0,
            'reevaluation', proposed_count,
            'cascade_depth', 0,
            'temporary_storage_bytes', 0,
            'memory_bytes', NULL,
            'elapsed_ms', extract(epoch FROM clock_timestamp() - started_at) * 1000),
        'findings', CASE WHEN comparison_complete THEN
            jsonb_build_array(pgreact_internal.m35_finding(
                'M35_NO_EFFECT', 'INFO', target_name, '<comparison>',
                'hypothetical comparison completed without changing source or pg-react state',
                'Apply the reviewed change separately if you want to change production.'))
            ELSE jsonb_build_array(pgreact_internal.m35_finding(
                'M35_COMPARISON_INCOMPLETE', 'WARNING', target_name, '<comparison>',
                'hypothetical evidence was truncated at the requested limit',
                'Increase evidence_limit or reduce the input and inspect the bounded result.')) END,
        'current', pgreact_internal.m34_raw_rows(current_rows, current_count, evidence_limit) -> 'rows',
        'proposed', pgreact_internal.m34_raw_rows(proposed_rows, proposed_count, evidence_limit) -> 'rows',
        'delta', pgreact_internal.m34_raw_rows(
            delta_rows, jsonb_array_length(delta_rows), evidence_limit) -> 'rows',
        'lifecycle', pgreact_internal.m34_raw_rows(
            lifecycle_rows, jsonb_array_length(lifecycle_rows), evidence_limit) -> 'rows',
        'work', pgreact_internal.m34_raw_rows(
            work_rows, jsonb_array_length(work_rows), evidence_limit) -> 'rows',
        'truncated', NOT comparison_complete)
;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m35_require_source(source_oid oid, source_name text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
-- ponytail: direct tables and one bigint key keep simulation bounded; add
-- typed composite-key and view adapters only with a new evidence-backed contract.
DECLARE relation_kind "char";
    rls_enabled boolean;
BEGIN
    IF source_oid IS NULL THEN
        RAISE EXCEPTION 'M35_CHANGE_RELATION: source relation % no longer exists', source_name;
    END IF;
    SELECT relkind, relrowsecurity
    INTO relation_kind, rls_enabled
    FROM pg_class
    WHERE oid = source_oid;
    IF relation_kind NOT IN ('r', 'p') THEN
        RAISE EXCEPTION 'M35_UNSUPPORTED_SOURCE: source relation % must be a table', source_name;
    END IF;
    IF rls_enabled THEN
        RAISE EXCEPTION 'M35_RLS_UNSUPPORTED: source relation % uses row-level security', source_name;
    END IF;
    IF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
        RAISE EXCEPTION 'M35_UNAUTHORIZED_SOURCE: caller lacks SELECT on source relation %', source_name;
    END IF;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m36_apply_changes(source_oid oid, key_column name, source_label text, rows jsonb, change_set jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    item jsonb;
    operation text;
    key_text text;
    existing jsonb;
    row_count bigint;
    unknown_field text;
BEGIN
    IF jsonb_typeof(change_set) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M36_REPLAY_INVALID: change_set must be a JSON array';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'object'
           OR NOT (item.value ?& ARRAY['relation', 'operation', 'ordinal', 'key', 'before', 'after'])
           OR (SELECT count(*) FROM jsonb_object_keys(item.value)) <> 6
    ) THEN
        RAISE EXCEPTION 'M36_REPLAY_REQUIRED_FIELD: every change must contain relation, operation, ordinal, key, before, and after';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_array_elements(change_set) item(value),
         jsonb_object_keys(item.value) AS key
    WHERE key NOT IN ('relation', 'operation', 'ordinal', 'key', 'before', 'after')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M36_REPLAY_UNKNOWN_FIELD: change field % is not supported', unknown_field;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        WHERE jsonb_typeof(item.value -> 'ordinal') IS DISTINCT FROM 'number'
           OR item.value ->> 'ordinal' !~ '^[1-9][0-9]*$'
    ) THEN
        RAISE EXCEPTION 'M36_REPLAY_ORDINAL: change ordinals must be positive integers';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(change_set) item(value)
        GROUP BY (item.value ->> 'ordinal')::bigint
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'M36_REPLAY_DUPLICATE: change ordinals must be unique';
    END IF;
    FOR item IN
        SELECT value
        FROM jsonb_array_elements(change_set) change(value)
        ORDER BY (value ->> 'ordinal')::bigint
    LOOP
        IF to_regclass(item ->> 'relation') IS DISTINCT FROM source_oid THEN
            RAISE EXCEPTION 'M36_SNAPSHOT_RELATION: change relation % does not match %',
                item ->> 'relation', source_label;
        END IF;
        operation := item ->> 'operation';
        IF operation IS NULL OR operation NOT IN ('INSERT', 'UPDATE', 'DELETE') THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: operation % is not supported', operation;
        END IF;
        IF jsonb_typeof(item -> 'key') IS DISTINCT FROM 'object'
           OR (SELECT count(*) FROM jsonb_object_keys(item -> 'key')) <> 1
           OR NOT (item -> 'key' ? key_column::text)
           OR jsonb_typeof(item -> 'key' -> key_column::text) IS DISTINCT FROM 'number'
           OR item -> 'key' ->> key_column::text !~ '^-?[0-9]+$' THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: key must contain one integer % value', key_column;
        END IF;
        key_text := item -> 'key' ->> key_column::text;
        IF operation = 'INSERT' THEN
            IF jsonb_typeof(item -> 'before') IS DISTINCT FROM 'null'
               OR jsonb_typeof(item -> 'after') IS DISTINCT FROM 'object' THEN
                RAISE EXCEPTION 'M36_REPLAY_INVALID: INSERT requires a null before image and an after image';
            END IF;
            BEGIN
                PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'after', 'after');
            EXCEPTION WHEN OTHERS THEN
                RAISE EXCEPTION 'M36_REPLAY_INVALID: after image does not match the source schema';
            END;
            IF item -> 'after' ->> key_column::text IS DISTINCT FROM key_text THEN
                RAISE EXCEPTION 'M36_REPLAY_INVALID: INSERT key does not match its after image';
            END IF;
            SELECT count(*) INTO row_count
            FROM jsonb_array_elements(rows) current_row(value)
            WHERE current_row.value ->> key_column::text = key_text;
            IF row_count > 0 THEN
                RAISE EXCEPTION 'M36_REPLAY_CONFLICT: INSERT identity % already exists', key_text;
            END IF;
            rows := rows || jsonb_build_array(item -> 'after');
        ELSE
            IF jsonb_typeof(item -> 'before') IS DISTINCT FROM 'object'
               OR jsonb_typeof(item -> 'after') IS DISTINCT FROM
                  (CASE WHEN operation = 'UPDATE' THEN 'object' ELSE 'null' END) THEN
                RAISE EXCEPTION 'M36_REPLAY_INVALID: % requires the correct before and after images', operation;
            END IF;
            BEGIN
                PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'before', 'before');
            EXCEPTION WHEN OTHERS THEN
                RAISE EXCEPTION 'M36_REPLAY_INVALID: before image does not match the source schema';
            END;
            IF operation = 'UPDATE' THEN
                BEGIN
                    PERFORM pgreact_internal.m35_check_image(source_oid, item -> 'after', 'after');
                EXCEPTION WHEN OTHERS THEN
                    RAISE EXCEPTION 'M36_REPLAY_INVALID: after image does not match the source schema';
                END;
                IF item -> 'after' ->> key_column::text IS DISTINCT FROM key_text THEN
                    RAISE EXCEPTION 'M36_REPLAY_INVALID: UPDATE cannot change its identity';
                END IF;
            END IF;
            SELECT count(*), (array_agg(current_row.value))[1]
            INTO row_count, existing
            FROM jsonb_array_elements(rows) current_row(value)
            WHERE current_row.value ->> key_column::text = key_text;
            IF row_count = 0 THEN
                RAISE EXCEPTION 'M36_REPLAY_STALE: identity % is not present', key_text;
            ELSIF row_count > 1 THEN
                RAISE EXCEPTION 'M36_REPLAY_DUPLICATE: identity % is ambiguous', key_text;
            ELSIF existing IS DISTINCT FROM item -> 'before' THEN
                RAISE EXCEPTION 'M36_REPLAY_STALE: before image for identity % is stale', key_text;
            END IF;
            SELECT COALESCE(jsonb_agg(
                       CASE WHEN current_row.value ->> key_column::text = key_text
                            THEN CASE WHEN operation = 'UPDATE'
                                      THEN item -> 'after' ELSE NULL END
                            ELSE current_row.value END
                       ORDER BY current_row.ordinality), '[]'::jsonb)
            INTO rows
            FROM jsonb_array_elements(rows) WITH ORDINALITY current_row(value, ordinality)
            WHERE NOT (operation = 'DELETE'
                       AND current_row.value ->> key_column::text = key_text);
        END IF;
    END LOOP;
    RETURN rows;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m36_model(normalized jsonb, target_kind text, rows jsonb, source_label text, evidence_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    key_column name;
    subject_column name;
    candidate_column name;
    priority_column name;
    result_columns name[];
    max_candidates integer;
    member_rows jsonb;
    subject_model jsonb;
    member_count bigint;
BEGIN
    IF target_kind = 'rule' THEN
        key_column := (normalized -> 'spec' ->> 'semantic_key')::name;
        RETURN pgreact_internal.m35_rule_rows(rows, key_column, source_label, evidence_limit);
    ELSIF target_kind = 'decision_program' THEN
        subject_column := (normalized -> 'spec' ->> 'subject_key')::name;
        candidate_column := (normalized -> 'spec' ->> 'candidate_key')::name;
        priority_column := (normalized -> 'spec' ->> 'priority')::name;
        SELECT array_agg(value::name ORDER BY ordinal)
        INTO result_columns
        FROM jsonb_array_elements_text(normalized -> 'spec' -> 'results')
             WITH ORDINALITY item(value, ordinal);
        max_candidates := COALESCE(
            (normalized -> 'spec' ->> 'max_candidates')::integer, 1000);
        RETURN pgreact_internal.m35_decision_rows(
            rows, subject_column, candidate_column, priority_column,
            result_columns, max_candidates, source_label, evidence_limit);
    ELSIF target_kind = 'policy_set' THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
                   'subject_key', 'member:' || (item.value ->> 'kind') || ':' ||
                                  (item.value ->> 'name') || ':' || (item.value ->> 'version'),
                   'result_key', 'member:' || (item.value ->> 'kind') || ':' ||
                                 (item.value ->> 'name') || ':' || (item.value ->> 'version'),
                   'state', 'MEMBER',
                   'value', item.value,
                   'work', jsonb_build_object('would_be_work', false),
                   'evidence', jsonb_build_object(
                       'source', 'pgreact.policy_set_members', 'complete', true))
                   ORDER BY item.value ->> 'kind', item.value ->> 'name', item.value ->> 'version'),
               '[]'::jsonb)
        INTO member_rows
        FROM jsonb_array_elements(COALESCE(normalized -> 'spec' -> 'members', '[]'::jsonb)) item(value);
        member_count := jsonb_array_length(COALESCE(normalized -> 'spec' -> 'members', '[]'::jsonb));
        subject_model := pgreact_internal.m35_policy_subject_rows(
            rows,
            ((normalized -> 'spec' -> 'applicability' -> 'subject_keys' ->> 0)::name),
            source_label,
            evidence_limit);
        RETURN jsonb_build_object(
            'rows', member_rows || (subject_model -> 'rows'),
            'rows_considered', member_count + (subject_model ->> 'rows_considered')::bigint,
            'truncated', member_count > evidence_limit
                OR COALESCE((subject_model ->> 'truncated')::boolean, false));
    END IF;
    RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: target kind % is not supported', target_kind;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m36_replay(proposed pgreact_api.declaration, deployed pgreact_api.target, initial_snapshot jsonb, replay_steps jsonb, options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    target_kind text := (deployed).kind;
    target_name text := (deployed).name;
    target_version text := (deployed).version;
    target_owner oid;
    frozen_normalized jsonb;
    normalized jsonb;
    validation jsonb;
    source_label text;
    source_oid oid;
    key_column name;
    source_schema_before text;
    source_schema_after text;
    target_digest_before text;
    target_digest_after text;
    source_rows jsonb;
    initial_snapshot_digest text;
    current_rows jsonb;
    previous_model_rows jsonb;
    initial_model jsonb;
    model jsonb;
    delta_model jsonb;
    delta_rows jsonb;
    lifecycle_rows jsonb;
    work_rows jsonb;
    initial_result jsonb;
    step_result jsonb;
    step_results jsonb := '[]'::jsonb;
    snapshot_relations jsonb;
    snapshot_relation jsonb;
    step jsonb;
    snapshot_digest text;
    replay_digest text;
    declaration_digest text;
    authoritative_checksum_before text;
    authoritative_checksum_after text;
    evidence_limit integer := 100;
    max_steps integer := 100;
    max_changes integer := 1000;
    max_snapshot_rows integer := 10000;
    max_total_changes integer := 10000;
    snapshot_row_count bigint;
    total_changes bigint := 0;
    step_count integer := 0;
    previous_ordinal bigint := 0;
    ordinal bigint;
    previous_frontier timestamptz;
    previous_sampled_time timestamptz;
    previous_watermark timestamptz;
    current_frontier timestamptz;
    current_sampled_time timestamptz;
    current_watermark timestamptz;
    starting_frontier timestamptz;
    starting_sampled_time timestamptz;
    starting_watermark timestamptz;
    finalized boolean := false;
    final_step boolean;
    key_not_null boolean;
    replay_complete boolean := true;
    step_complete boolean;
    rows_considered bigint := 0;
    affected_subjects bigint := 0;
    started_at timestamptz := clock_timestamp();
    unknown_field text;
    expected_source text;
BEGIN
    IF deployed IS NULL OR target_kind IS NULL OR target_name IS NULL THEN
        RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: deployed target kind and name are required';
    END IF;
    IF options IS NULL OR jsonb_typeof(options) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M36_REPLAY_INVALID: options must be a JSON object';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_object_keys(options) AS key
    WHERE key NOT IN ('evidence_limit', 'max_steps', 'max_changes',
                      'max_snapshot_rows', 'max_total_changes')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M36_REPLAY_UNKNOWN_FIELD: option % is not supported', unknown_field;
    END IF;
    IF options ? 'evidence_limit' THEN
        IF jsonb_typeof(options -> 'evidence_limit') IS DISTINCT FROM 'number'
           OR options ->> 'evidence_limit' !~ '^[1-9][0-9]*$'
           OR (options ->> 'evidence_limit')::integer > 1000 THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: evidence_limit must be between 1 and 1000';
        END IF;
        evidence_limit := (options ->> 'evidence_limit')::integer;
    END IF;
    IF options ? 'max_steps' THEN
        IF jsonb_typeof(options -> 'max_steps') IS DISTINCT FROM 'number'
           OR options ->> 'max_steps' !~ '^[1-9][0-9]*$'
           OR (options ->> 'max_steps')::integer > 1000 THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: max_steps must be between 1 and 1000';
        END IF;
        max_steps := (options ->> 'max_steps')::integer;
    END IF;
    IF options ? 'max_changes' THEN
        IF jsonb_typeof(options -> 'max_changes') IS DISTINCT FROM 'number'
           OR options ->> 'max_changes' !~ '^[1-9][0-9]*$'
           OR (options ->> 'max_changes')::integer > 1000 THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: max_changes must be between 1 and 1000';
        END IF;
        max_changes := (options ->> 'max_changes')::integer;
    END IF;
    IF options ? 'max_snapshot_rows' THEN
        IF jsonb_typeof(options -> 'max_snapshot_rows') IS DISTINCT FROM 'number'
           OR options ->> 'max_snapshot_rows' !~ '^[1-9][0-9]*$'
           OR (options ->> 'max_snapshot_rows')::integer > 100000 THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: max_snapshot_rows must be between 1 and 100000';
        END IF;
        max_snapshot_rows := (options ->> 'max_snapshot_rows')::integer;
    END IF;
    IF options ? 'max_total_changes' THEN
        IF jsonb_typeof(options -> 'max_total_changes') IS DISTINCT FROM 'number'
           OR options ->> 'max_total_changes' !~ '^[1-9][0-9]*$'
           OR (options ->> 'max_total_changes')::integer > 100000 THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: max_total_changes must be between 1 and 100000';
        END IF;
        max_total_changes := (options ->> 'max_total_changes')::integer;
    END IF;
    IF jsonb_typeof(replay_steps) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M36_REPLAY_INVALID: replay_steps must be a JSON array';
    END IF;
    IF jsonb_array_length(replay_steps) > max_steps THEN
        RAISE EXCEPTION 'M36_RESOURCE_LIMIT: replay_steps exceeds max_steps';
    END IF;

    IF target_kind = 'policy_set' THEN
        SELECT version.normalized, set.owner_oid
        INTO frozen_normalized, target_owner
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE set.set_name = target_name
          AND version.state = 'DEPLOYED'
          AND (target_version IS NULL OR version.version = target_version)
        ORDER BY version.valid_from DESC, version.created_at DESC
        LIMIT 1;
    ELSE
        SELECT row_data.normalized, row_data.owner_oid
        INTO frozen_normalized, target_owner
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
        IF target_version IS NOT NULL AND target_version <> '1' THEN
            RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: only deployed declaration version 1 is supported';
        END IF;
    END IF;
    IF frozen_normalized IS NULL THEN
        RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: deployed % % was not found', target_kind, target_name;
    END IF;
    target_digest_before := encode(sha256(convert_to(frozen_normalized::text, 'UTF8')), 'hex');
    IF NOT pg_has_role(session_user, target_owner, 'USAGE')
       AND NOT pgreact_internal.is_operator_admin()
       AND NOT EXISTS (
           SELECT 1 FROM pgreact_internal.application_roles role_row
           WHERE role_row.role_kind = 'reader'
             AND pg_has_role(session_user, role_row.role_oid, 'member')) THEN
        RAISE EXCEPTION 'M36_UNAUTHORIZED_TARGET: caller is not allowed to inspect %', target_name;
    END IF;
    IF proposed IS NULL THEN
        normalized := frozen_normalized;
    ELSE
        IF (proposed).kind IS DISTINCT FROM target_kind
           OR (proposed).name IS DISTINCT FROM target_name THEN
            RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: proposed and deployed targets must match';
        END IF;
        validation := pgreact_internal.m28_validate(proposed);
        IF EXISTS (
            SELECT 1 FROM jsonb_array_elements(validation -> 'findings') finding(value)
            WHERE value ->> 'severity' = 'ERROR'
        ) THEN
            RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: proposed declaration is invalid: %',
                validation -> 'findings';
        END IF;
        normalized := pgreact_internal.m28_normalize(proposed);
    END IF;

    IF target_kind = 'rule' THEN
        source_label := normalized -> 'spec' ->> 'condition';
        key_column := (normalized -> 'spec' ->> 'semantic_key')::name;
    ELSIF target_kind = 'decision_program' THEN
        source_label := normalized -> 'spec' ->> 'candidate_relation';
        key_column := (normalized -> 'spec' ->> 'candidate_key')::name;
    ELSIF target_kind = 'policy_set' THEN
        source_label := normalized -> 'spec' -> 'applicability' ->> 'relation';
        IF jsonb_array_length(COALESCE(
               normalized -> 'spec' -> 'applicability' -> 'subject_keys', '[]'::jsonb)) <> 1 THEN
            RAISE EXCEPTION 'M36_UNSUPPORTED_SOURCE: M36 requires one bigint policy subject key';
        END IF;
        key_column := (normalized -> 'spec' -> 'applicability' -> 'subject_keys' ->> 0)::name;
    ELSE
        RAISE EXCEPTION 'M36_UNSUPPORTED_TARGET: target kind % is not supported', target_kind;
    END IF;
    source_oid := to_regclass(source_label);
    PERFORM pgreact_internal.m36_require_source(source_oid, source_label);
    SELECT a.atttypid::regtype, a.attnotnull
    INTO expected_source, key_not_null
    FROM pg_attribute a
    WHERE a.attrelid = source_oid AND a.attname = key_column
      AND a.attnum > 0 AND NOT a.attisdropped;
    IF expected_source IS DISTINCT FROM 'bigint' OR NOT key_not_null THEN
        RAISE EXCEPTION 'M36_UNSUPPORTED_SOURCE: identity column % must be non-null bigint', key_column;
    END IF;
    source_schema_before := pgreact_internal.m36_schema_fingerprint(source_oid);

    IF initial_snapshot IS NULL OR jsonb_typeof(initial_snapshot) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_INVALID: initial_snapshot must be a JSON object';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_object_keys(initial_snapshot) AS key
    WHERE key NOT IN ('relations', 'source_frontier', 'sampled_time', 'event_time_watermark')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_UNKNOWN_FIELD: snapshot field % is not supported', unknown_field;
    END IF;
    IF NOT (initial_snapshot ?& ARRAY['relations', 'source_frontier', 'sampled_time', 'event_time_watermark'])
       OR jsonb_typeof(initial_snapshot -> 'relations') IS DISTINCT FROM 'array'
       OR jsonb_array_length(initial_snapshot -> 'relations') <> 1 THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_REQUIRED_FIELD: snapshot needs one relation and its three starting times';
    END IF;
    snapshot_relations := initial_snapshot -> 'relations';
    snapshot_relation := snapshot_relations -> 0;
    IF jsonb_typeof(snapshot_relation) IS DISTINCT FROM 'object'
       OR NOT (snapshot_relation ?& ARRAY['relation', 'rows', 'schema_fingerprint']) THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_REQUIRED_FIELD: relation needs relation, rows, and schema_fingerprint fields';
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_object_keys(snapshot_relation) AS key
    WHERE key NOT IN ('relation', 'rows', 'schema_fingerprint')
    ORDER BY key
    LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_UNKNOWN_FIELD: relation field % is not supported', unknown_field;
    END IF;
    IF to_regclass(snapshot_relation ->> 'relation') IS DISTINCT FROM source_oid THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_RELATION: snapshot relation % does not match %',
            snapshot_relation ->> 'relation', source_label;
    END IF;
    IF snapshot_relation ->> 'relation' IS DISTINCT FROM source_oid::regclass::text THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_RELATION: snapshot relation must use canonical name %',
            source_oid::regclass;
    END IF;
    PERFORM pgreact_internal.m36_validate_rows(
        source_oid, key_column, snapshot_relation -> 'rows', source_label);
    SELECT COALESCE(jsonb_array_length(snapshot_relation -> 'rows'), 0)
    INTO snapshot_row_count;
    IF snapshot_row_count > max_snapshot_rows THEN
        RAISE EXCEPTION 'M36_RESOURCE_LIMIT: initial snapshot exceeds max_snapshot_rows';
    END IF;
    IF snapshot_relation ? 'schema_fingerprint'
       AND snapshot_relation ->> 'schema_fingerprint' IS DISTINCT FROM source_schema_before THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_SCHEMA: supplied schema_fingerprint does not match %', source_label;
    END IF;
    BEGIN
        starting_frontier := (initial_snapshot ->> 'source_frontier')::timestamptz;
        starting_sampled_time := (initial_snapshot ->> 'sampled_time')::timestamptz;
        starting_watermark := (initial_snapshot ->> 'event_time_watermark')::timestamptz;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_INVALID: snapshot times must be valid timestamps';
    END;
    IF starting_frontier IS NULL OR starting_sampled_time IS NULL OR starting_watermark IS NULL THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_REQUIRED_FIELD: snapshot times cannot be null';
    END IF;
    IF starting_sampled_time > starting_frontier THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_INVALID: sampled_time cannot be after source_frontier';
    END IF;

    authoritative_checksum_before := pgreact_internal.m34_authoritative_checksum();
    source_rows := snapshot_relation -> 'rows';
    snapshot_digest := pgreact_internal.m36_snapshot_digest(snapshot_relations);
    initial_snapshot_digest := snapshot_digest;
    declaration_digest := encode(sha256(convert_to(normalized::text, 'UTF8')), 'hex');
    initial_model := pgreact_internal.m36_model(
        normalized, target_kind, source_rows, source_label, evidence_limit);
    previous_model_rows := initial_model -> 'rows';
    previous_frontier := starting_frontier;
    previous_sampled_time := starting_sampled_time;
    previous_watermark := starting_watermark;
    replay_complete := NOT COALESCE((initial_model ->> 'truncated')::boolean, false);
    rows_considered := rows_considered + (initial_model ->> 'rows_considered')::bigint;
    initial_result := jsonb_build_object(
        'result_set', 'initial',
        'ordinal', 0,
        'source_frontier', starting_frontier,
        'sampled_time', starting_sampled_time,
        'event_time_watermark', starting_watermark,
        'change_set', '[]'::jsonb,
        'rows', initial_model -> 'rows',
        'rows_considered', initial_model -> 'rows_considered',
        'delta', '[]'::jsonb,
        'lifecycle', '[]'::jsonb,
        'work', '[]'::jsonb,
        'snapshot_checksum_before', initial_snapshot_digest,
        'snapshot_checksum_after', initial_snapshot_digest,
        'complete', replay_complete);

    FOR step IN SELECT value FROM jsonb_array_elements(replay_steps) item(value)
    LOOP
        step_count := step_count + 1;
        IF jsonb_typeof(step) IS DISTINCT FROM 'object'
           OR NOT (step ?& ARRAY['ordinal', 'source_frontier', 'sampled_time',
                                 'event_time_watermark', 'change_set']) THEN
            RAISE EXCEPTION 'M36_REPLAY_REQUIRED_FIELD: every step needs ordinal, source_frontier, sampled_time, event_time_watermark, and change_set';
        END IF;
        SELECT key INTO unknown_field
        FROM jsonb_object_keys(step) AS key
        WHERE key NOT IN ('ordinal', 'source_frontier', 'sampled_time',
                          'event_time_watermark', 'change_set', 'final')
        ORDER BY key
        LIMIT 1;
        IF unknown_field IS NOT NULL THEN
            RAISE EXCEPTION 'M36_REPLAY_UNKNOWN_FIELD: step field % is not supported', unknown_field;
        END IF;
        IF step ->> 'ordinal' !~ '^[1-9][0-9]*$' THEN
            RAISE EXCEPTION 'M36_REPLAY_ORDINAL: step ordinals must be positive integers';
        END IF;
        ordinal := (step ->> 'ordinal')::bigint;
        IF ordinal <= previous_ordinal THEN
            IF ordinal = previous_ordinal THEN
                RAISE EXCEPTION 'M36_REPLAY_DUPLICATE: step ordinals must be unique';
            END IF;
            RAISE EXCEPTION 'M36_REPLAY_NONMONOTONE: step ordinals must increase';
        END IF;
        BEGIN
            current_frontier := (step ->> 'source_frontier')::timestamptz;
            current_sampled_time := (step ->> 'sampled_time')::timestamptz;
            current_watermark := (step ->> 'event_time_watermark')::timestamptz;
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: step times must be valid timestamps';
        END;
        IF current_frontier IS NULL OR current_sampled_time IS NULL OR current_watermark IS NULL THEN
            RAISE EXCEPTION 'M36_REPLAY_REQUIRED_FIELD: step times cannot be null';
        END IF;
        IF current_frontier < previous_frontier OR current_sampled_time < previous_sampled_time THEN
            RAISE EXCEPTION 'M36_REPLAY_NONMONOTONE: source_frontier and sampled_time cannot move backward';
        END IF;
        IF current_watermark < previous_watermark THEN
            RAISE EXCEPTION 'M36_REPLAY_LATE_INPUT: event_time_watermark cannot move backward';
        END IF;
        IF current_sampled_time > current_frontier THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: sampled_time cannot be after source_frontier';
        END IF;
        IF finalized THEN
            RAISE EXCEPTION 'M36_REPLAY_FINALIZED: replay cannot continue after a final step';
        END IF;
        IF jsonb_typeof(step -> 'change_set') IS DISTINCT FROM 'array' THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: change_set must be a JSON array';
        END IF;
        IF jsonb_array_length(step -> 'change_set') > max_changes THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: step change_set exceeds max_changes';
        END IF;
        total_changes := total_changes + jsonb_array_length(step -> 'change_set');
        IF total_changes > max_total_changes THEN
            RAISE EXCEPTION 'M36_RESOURCE_LIMIT: replay changes exceed max_total_changes';
        END IF;
        IF step ? 'final' AND jsonb_typeof(step -> 'final') IS DISTINCT FROM 'boolean' THEN
            RAISE EXCEPTION 'M36_REPLAY_INVALID: final must be boolean';
        END IF;
        final_step := COALESCE((step ->> 'final')::boolean, false);
        snapshot_digest := pgreact_internal.m36_snapshot_digest(
            jsonb_build_array(jsonb_build_object('relation', source_label, 'rows', source_rows)));
        current_rows := pgreact_internal.m36_apply_changes(
            source_oid, key_column, source_label, source_rows, step -> 'change_set');
        snapshot_digest := pgreact_internal.m36_snapshot_digest(
            jsonb_build_array(jsonb_build_object('relation', source_label, 'rows', current_rows)));
        model := pgreact_internal.m36_model(
            normalized, target_kind, current_rows, source_label, evidence_limit);
        delta_model := pgreact_internal.m34_delta(previous_model_rows, model -> 'rows');
        delta_rows := delta_model -> 'rows';
        SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
        INTO lifecycle_rows
        FROM jsonb_array_elements(delta_rows) item(value)
        WHERE item.value ->> 'change' <> 'UNCHANGED';
        SELECT COALESCE(jsonb_agg(item.value ORDER BY item.value ->> 'subject_key'), '[]'::jsonb)
        INTO work_rows
        FROM jsonb_array_elements(model -> 'rows') item(value)
        WHERE (item.value -> 'work' ->> 'would_be_work')::boolean;
        step_complete := replay_complete
            AND NOT COALESCE((model ->> 'truncated')::boolean, false)
            AND jsonb_array_length(delta_rows) <= evidence_limit;
        step_result := jsonb_build_object(
            'result_set', 'step',
            'ordinal', ordinal,
            'source_frontier', current_frontier,
            'sampled_time', current_sampled_time,
            'event_time_watermark', current_watermark,
            'change_set', step -> 'change_set',
            'rows', model -> 'rows',
            'rows_considered', model -> 'rows_considered',
            'delta', delta_rows,
            'lifecycle', lifecycle_rows,
            'work', work_rows,
            'snapshot_checksum_before', pgreact_internal.m36_snapshot_digest(
                jsonb_build_array(jsonb_build_object('relation', source_label, 'rows', source_rows))),
            'snapshot_checksum_after', snapshot_digest,
            'complete', step_complete);
        step_results := step_results || jsonb_build_array(step_result);
        previous_model_rows := model -> 'rows';
        source_rows := current_rows;
        previous_ordinal := ordinal;
        previous_frontier := current_frontier;
        previous_sampled_time := current_sampled_time;
        previous_watermark := current_watermark;
        replay_complete := step_complete;
        IF final_step THEN
            finalized := true;
        END IF;
        rows_considered := rows_considered + (model ->> 'rows_considered')::bigint;
        IF step_complete THEN
            affected_subjects := affected_subjects
                + COALESCE((delta_model -> 'counts' ->> 'added')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'removed')::bigint, 0)
                + COALESCE((delta_model -> 'counts' ->> 'changed')::bigint, 0);
        END IF;
    END LOOP;
    authoritative_checksum_after := pgreact_internal.m34_authoritative_checksum();
    source_schema_after := pgreact_internal.m36_schema_fingerprint(source_oid);
    IF authoritative_checksum_before IS DISTINCT FROM authoritative_checksum_after
       OR source_schema_before IS DISTINCT FROM source_schema_after THEN
        RAISE EXCEPTION 'M36_AUTHORITATIVE_CHANGED: authoritative source or pg-react state changed during replay';
    END IF;
    IF target_kind = 'policy_set' THEN
        SELECT version.normalized INTO frozen_normalized
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE set.set_name = target_name
          AND version.state = 'DEPLOYED'
          AND (target_version IS NULL OR version.version = target_version)
        ORDER BY version.valid_from DESC, version.created_at DESC
        LIMIT 1;
    ELSE
        SELECT row_data.normalized INTO frozen_normalized
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = target_kind
          AND row_data.object_name = target_name
          AND row_data.state = 'DEPLOYED';
    END IF;
    target_digest_after := encode(sha256(convert_to(frozen_normalized::text, 'UTF8')), 'hex');
    IF target_digest_before IS DISTINCT FROM target_digest_after THEN
        RAISE EXCEPTION 'M36_AUTHORITATIVE_CHANGED: deployed declaration changed during replay';
    END IF;
    replay_digest := encode(sha256(convert_to(
        initial_snapshot_digest || E'\n' || replay_steps::text, 'UTF8')), 'hex');
    initial_result := initial_result
        || jsonb_build_object(
            'declaration_digest', declaration_digest,
            'snapshot_digest', initial_snapshot_digest,
            'replay_digest', replay_digest);
    RETURN jsonb_build_object(
        'contract_version', 23,
        'operation', 'replay',
        'simulation', 'historical_replay',
        'target', jsonb_build_object(
            'kind', target_kind, 'name', target_name, 'version', target_version),
        'state', CASE WHEN replay_complete THEN 'ready' ELSE 'partial' END,
        'summary', jsonb_build_object(
            'read_only', true,
            'initial_row_count', snapshot_row_count,
            'replay_step_count', step_count,
            'replay_change_count', total_changes,
            'final_row_count', jsonb_array_length(previous_model_rows),
            'counts_exact', replay_complete,
            'affected_subject_count', CASE WHEN replay_complete THEN affected_subjects END),
        'snapshot', jsonb_build_object(
            'relations', jsonb_build_array(jsonb_build_object(
                'relation', source_label,
                'schema_fingerprint', source_schema_before,
                'snapshot_checksum', initial_snapshot_digest)),
            'starting_source_frontier', starting_frontier,
            'starting_sampled_time', starting_sampled_time,
            'starting_event_time_watermark', starting_watermark,
            'ending_source_frontier', previous_frontier,
            'ending_sampled_time', previous_sampled_time,
            'ending_event_time_watermark', previous_watermark,
            'authoritative_checksum_before', authoritative_checksum_before,
            'authoritative_checksum_after', authoritative_checksum_after,
            'source_schema_fingerprint_before', source_schema_before,
            'source_schema_fingerprint_after', source_schema_after),
        'evidence', jsonb_build_object(
            'declaration_digest', declaration_digest,
            'snapshot_digest', initial_snapshot_digest,
            'replay_digest', replay_digest,
            'source_frontier', jsonb_build_object(
                'start', starting_frontier, 'end', previous_frontier),
            'sampled_time', jsonb_build_object(
                'start', starting_sampled_time, 'end', previous_sampled_time),
            'event_time_watermark', jsonb_build_object(
                'start', starting_watermark, 'end', previous_watermark),
            'causal', jsonb_build_object(
                'changed_facts', total_changes,
                'steps', step_count,
                'complete', replay_complete),
            'complete', replay_complete,
            'evidence_limit', evidence_limit),
        'cost', jsonb_build_object(
            'snapshot_rows', snapshot_row_count,
            'replay_steps', step_count,
            'change_rows', total_changes,
            'rows_considered', rows_considered,
            'affected_subjects', CASE WHEN replay_complete THEN affected_subjects END,
            'dependency_fan_out', 0,
            'reevaluation', rows_considered,
            'cascade_depth', 0,
            'temporary_storage_bytes', 0,
            'memory_bytes', NULL,
            'elapsed_ms', extract(epoch FROM clock_timestamp() - started_at) * 1000),
        'findings', CASE WHEN replay_complete THEN
            jsonb_build_array(pgreact_internal.m36_finding(
                'M36_NO_EFFECT', 'INFO', target_name, '<replay>',
                'historical replay completed without changing source or pg-react state',
                'Apply reviewed production changes separately if you want to change data.'))
            ELSE jsonb_build_array(pgreact_internal.m36_finding(
                'M36_REPLAY_INCOMPLETE', 'WARNING', target_name, '<replay>',
                'historical replay evidence was truncated at the requested limit',
                'Increase evidence_limit or reduce the supplied snapshot.')) END,
        'initial', initial_result,
        'steps', step_results,
        'final', jsonb_build_object(
            'result_set', 'final',
            'ordinal', previous_ordinal,
            'source_frontier', previous_frontier,
            'sampled_time', previous_sampled_time,
            'event_time_watermark', previous_watermark,
            'rows', previous_model_rows,
            'complete', replay_complete,
            'snapshot_checksum', pgreact_internal.m36_snapshot_digest(
                jsonb_build_array(jsonb_build_object('relation', source_label, 'rows', source_rows)))));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m36_require_source(source_oid oid, source_name text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    relation_kind "char";
    rls_enabled boolean;
BEGIN
    IF source_oid IS NULL THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_RELATION: source relation % no longer exists', source_name;
    END IF;
    SELECT relkind, relrowsecurity
    INTO relation_kind, rls_enabled
    FROM pg_class
    WHERE oid = source_oid;
    IF relation_kind NOT IN ('r', 'p') THEN
        RAISE EXCEPTION 'M36_UNSUPPORTED_SOURCE: source relation % must be a table', source_name;
    END IF;
    IF rls_enabled THEN
        RAISE EXCEPTION 'M36_RLS_UNSUPPORTED: source relation % uses row-level security', source_name;
    END IF;
    IF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
        RAISE EXCEPTION 'M36_UNAUTHORIZED_SOURCE: caller lacks SELECT on source relation %', source_name;
    END IF;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m36_snapshot_digest(relations jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    relation_item jsonb;
    row_material text;
    material text := '';
BEGIN
    FOR relation_item IN
        SELECT value
        FROM jsonb_array_elements($1) item(value)
        ORDER BY value ->> 'relation'
    LOOP
        SELECT COALESCE(string_agg(value::text, ',' ORDER BY value::text), '')
        INTO row_material
        FROM jsonb_array_elements(relation_item -> 'rows') row(value);
        material := material || (relation_item ->> 'relation') || '=' || row_material || E'\n';
    END LOOP;
    RETURN encode(sha256(convert_to(material, 'UTF8')), 'hex');
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m36_validate_rows(source_oid oid, key_column name, rows jsonb, source_label text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    duplicate_count bigint;
    row_item jsonb;
BEGIN
    IF jsonb_typeof(rows) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_ROW: rows for % must be a JSON array', source_label;
    END IF;
    FOR row_item IN SELECT value FROM jsonb_array_elements(rows) item(value)
    LOOP
        BEGIN
            PERFORM pgreact_internal.m35_check_image(source_oid, row_item, 'snapshot row');
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'M36_SNAPSHOT_ROW: row in % does not match the source schema', source_label;
        END;
        IF row_item ->> key_column::text IS NULL
           OR row_item ->> key_column::text !~ '^-?[0-9]+$' THEN
            RAISE EXCEPTION 'M36_SNAPSHOT_ROW: % identity must be a bigint value', source_label;
        END IF;
    END LOOP;
    SELECT count(*) INTO duplicate_count
    FROM (
        SELECT value ->> key_column::text
        FROM jsonb_array_elements(rows) item(value)
        GROUP BY value ->> key_column::text
        HAVING count(*) > 1
    ) duplicates;
    IF duplicate_count > 0 THEN
        RAISE EXCEPTION 'M36_SNAPSHOT_DUPLICATE: % contains duplicate identities', source_label;
    END IF;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m38_annotate_backtest(result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    rows jsonb;
    differences jsonb;
    evidence_limit integer := COALESCE((result -> 'evidence' ->> 'evidence_limit')::integer, 100);
BEGIN
    rows := pgreact_internal.m38_annotate_rows(
        result -> 'differences' -> 'rows', 'backtest',
        'baseline', 'candidate', 'difference', result, 'backtest');
    differences := COALESCE(result -> 'differences', '{}'::jsonb)
        || jsonb_build_object('rows', rows);
    result := result || jsonb_build_object('differences', differences);
    RETURN pgreact_internal.m38_finish(result, rows, 'backtest', evidence_limit);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m38_annotate_compare(result jsonb, operation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    delta jsonb;
    lifecycle jsonb;
    explained jsonb;
    evidence_limit integer := COALESCE((result -> 'evidence' ->> 'evidence_limit')::integer, 100);
BEGIN
    delta := pgreact_internal.m38_annotate_rows(
        result -> 'delta', operation, 'current', 'proposed', 'delta', result, 'comparison');
    lifecycle := pgreact_internal.m38_annotate_rows(
        result -> 'lifecycle', operation, 'current', 'proposed', 'lifecycle', result, 'comparison');
    explained := COALESCE(delta, '[]'::jsonb) || COALESCE(lifecycle, '[]'::jsonb);
    result := result || jsonb_build_object('delta', delta, 'lifecycle', lifecycle);
    RETURN pgreact_internal.m38_finish(result, explained, operation, evidence_limit);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m38_annotate_replay(result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    step_item jsonb;
    step_output jsonb;
    delta jsonb;
    lifecycle jsonb;
    steps jsonb := '[]'::jsonb;
    explained jsonb := '[]'::jsonb;
    evidence_limit integer := COALESCE((result -> 'evidence' ->> 'evidence_limit')::integer, 100);
BEGIN
    FOR step_item IN SELECT value FROM jsonb_array_elements(COALESCE(result -> 'steps', '[]'::jsonb)) item(value)
    LOOP
        step_output := result || jsonb_build_object('step', step_item);
        delta := pgreact_internal.m38_annotate_rows(
            step_item -> 'delta', 'replay', 'previous', 'current',
            'delta', step_output, 'comparison');
        lifecycle := pgreact_internal.m38_annotate_rows(
            step_item -> 'lifecycle', 'replay', 'previous', 'current',
            'lifecycle', step_output, 'comparison');
        step_item := step_item || jsonb_build_object('delta', delta, 'lifecycle', lifecycle);
        steps := steps || jsonb_build_array(step_item);
        explained := explained || COALESCE(delta, '[]'::jsonb) || COALESCE(lifecycle, '[]'::jsonb);
    END LOOP;
    result := result || jsonb_build_object('steps', steps);
    RETURN pgreact_internal.m38_finish(result, explained, 'replay', evidence_limit);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m38_annotate_rows(rows jsonb, operation text, baseline_side text, candidate_side text, result_set_name text, context jsonb, row_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    row_item jsonb;
    annotated jsonb;
    why jsonb;
    output_rows jsonb := '[]'::jsonb;
    change_kind text;
    baseline_value jsonb;
    candidate_value jsonb;
    baseline_work jsonb;
    candidate_work jsonb;
    baseline_evidence jsonb;
    candidate_evidence jsonb;
    ordinal text;
    point jsonb;
    digest text;
BEGIN
    digest := encode(sha256(convert_to(context::text, 'UTF8')), 'hex');
    FOR row_item IN SELECT value FROM jsonb_array_elements(COALESCE(rows, '[]'::jsonb)) item(value)
    LOOP
        change_kind := row_item ->> 'change';
        IF change_kind IS NULL OR change_kind = 'UNCHANGED' THEN
            output_rows := output_rows || jsonb_build_array(row_item);
            CONTINUE;
        END IF;
        IF row_mode = 'backtest' THEN
            baseline_value := row_item -> 'baseline' -> 'value';
            candidate_value := row_item -> 'candidate' -> 'value';
            baseline_work := row_item -> 'baseline' -> 'work';
            candidate_work := row_item -> 'candidate' -> 'work';
            baseline_evidence := row_item -> 'baseline' -> 'evidence';
            candidate_evidence := row_item -> 'candidate' -> 'evidence';
        ELSE
            baseline_value := row_item -> 'current_value';
            candidate_value := row_item -> 'proposed_value';
            baseline_work := row_item -> 'current_work';
            candidate_work := row_item -> 'proposed_work';
            baseline_evidence := row_item -> 'evidence' -> 'current';
            candidate_evidence := row_item -> 'evidence' -> 'proposed';
        END IF;
        ordinal := COALESCE(
            row_item ->> 'ordinal',
            context ->> 'ordinal',
            context -> 'step' ->> 'ordinal');
        point := jsonb_build_object(
            'result_set', result_set_name,
            'ordinal', ordinal,
            'sampled_time', COALESCE(
                context ->> 'sampled_time',
                context -> 'evidence' ->> 'sampled_time',
                context -> 'snapshot' ->> 'sampled_time',
                context -> 'step' ->> 'sampled_time'),
            'source_frontier', COALESCE(
                context ->> 'source_frontier',
                context -> 'evidence' ->> 'source_frontier',
                context -> 'snapshot' ->> 'source_frontier',
                context -> 'step' ->> 'source_frontier'),
            'event_time_watermark', COALESCE(
                context ->> 'event_time_watermark',
                context -> 'step' ->> 'event_time_watermark'));
        why := pgreact_internal.m38_explain_row(
            operation, result_set_name, ordinal,
            row_item ->> 'subject_key',
            COALESCE(row_item ->> 'result_key', row_item ->> 'subject_key'),
            change_kind, baseline_side, candidate_side,
            baseline_value, candidate_value,
            baseline_work, candidate_work,
            baseline_evidence, candidate_evidence,
            point, context ->> 'state', digest);
        annotated := row_item || jsonb_build_object(
            'why_changed', why,
            'evidence', COALESCE(row_item -> 'evidence', '{}'::jsonb)
                || jsonb_build_object('why_changed', why));
        IF row_mode = 'backtest' THEN
            annotated := annotated || jsonb_build_object(
                'baseline', COALESCE(row_item -> 'baseline', '{}'::jsonb)
                    || jsonb_build_object('evidence',
                        COALESCE(row_item -> 'baseline' -> 'evidence', '{}'::jsonb)
                            || jsonb_build_object('why_changed', why)),
                'candidate', COALESCE(row_item -> 'candidate', '{}'::jsonb)
                    || jsonb_build_object('evidence',
                        COALESCE(row_item -> 'candidate' -> 'evidence', '{}'::jsonb)
                            || jsonb_build_object('why_changed', why)));
        END IF;
        output_rows := output_rows || jsonb_build_array(annotated);
    END LOOP;
    RETURN output_rows;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m38_requested(options jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
    IF options IS NULL OR jsonb_typeof(options) IS DISTINCT FROM 'object'
       OR NOT options ? 'why_changed' THEN
        RETURN false;
    END IF;
    IF jsonb_typeof(options -> 'why_changed') IS DISTINCT FROM 'boolean' THEN
        RAISE EXCEPTION 'M38_OPTIONS_INVALID: why_changed must be a boolean';
    END IF;
    RETURN (options ->> 'why_changed')::boolean;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m40_explain(target_name text, subject jsonb, options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    started_at timestamptz := clock_timestamp();
    sampled_time timestamptz := statement_timestamp();
    authoritative_frontier timestamptz;
    target_count bigint;
    target_kind text;
    target_version text;
    expected_input jsonb;
    expected_payload jsonb;
    expected jsonb;
    expected_kind text;
    expected_key text;
    expected_key_numeric bigint;
    expected_value jsonb;
    cause_limit integer := 32;
    limit_text text;
    subject_key bigint;
    subject_identity text;
    source_oid oid;
    relation_kind "char";
    rls_enabled boolean;
    source_name text;
    source_row jsonb;
    source_count bigint := 0;
    match_row jsonb;
    decision_row record;
    derived_row record;
    derived_fact jsonb;
    derived_support_count bigint := 0;
    candidate_row jsonb;
    candidate_count bigint := 0;
    candidate_priority bigint;
    winner_row jsonb;
    winner_state text;
    winner_candidate bigint;
    winner_priority bigint;
    policy_row pgreact_internal.policy_set_versions%ROWTYPE;
    scope_row record;
    source_complete boolean := true;
    causes jsonb := '[]'::jsonb;
    findings jsonb := '[]'::jsonb;
    observed jsonb := '{}'::jsonb;
    limits jsonb;
    state text;
BEGIN
    SELECT frontier INTO authoritative_frontier
    FROM pgreact_internal.clock_frontier
    WHERE singleton;

    IF jsonb_typeof(options) IS DISTINCT FROM 'object'
       OR jsonb_typeof(options -> 'why_not') IS DISTINCT FROM 'object' THEN
        RETURN pgreact_internal.m40_result(
            NULL, target_name, NULL, 'unsupported', subject, '{}', sampled_time,
            authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_OPTIONS_INVALID', 'ERROR', COALESCE(target_name, '<unknown>'),
                    'options.why_not',
                    'why_not must be an object containing one expected result',
                    'Pass why_not => {result_kind, result_key}.' )),
            jsonb_build_object('cause_limit', cause_limit),
            pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;

    expected_input := options -> 'why_not';
    expected_payload := COALESCE(expected_input -> 'expected_result',
                                 expected_input -> 'expected', expected_input);
    expected_kind := COALESCE(expected_payload ->> 'result_kind',
                              expected_payload ->> 'kind');
    expected_key := COALESCE(expected_payload ->> 'result_key',
                              expected_payload ->> 'key', expected_payload ->> 'identity');
    expected_value := expected_payload -> 'value';
    limit_text := expected_input ->> 'cause_limit';
    IF limit_text IS NOT NULL THEN
        IF limit_text !~ '^[1-9][0-9]*$' THEN
            RETURN pgreact_internal.m40_result(
                NULL, target_name, NULL, 'unsupported', subject, '{}', sampled_time,
                authoritative_frontier, '{}', '[]', jsonb_build_array(
                    pgreact_internal.m40_finding(
                        'M40_OPTIONS_INVALID', 'ERROR', COALESCE(target_name, '<unknown>'),
                        'options.why_not.cause_limit',
                        'cause_limit must be a positive integer',
                        'Use a value between 1 and 1000.' )),
                jsonb_build_object('cause_limit', cause_limit),
                pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
        END IF;
        IF length(limit_text) > 4 THEN
            RETURN pgreact_internal.m40_result(
                NULL, target_name, NULL, 'unsupported', subject, '{}', sampled_time,
                authoritative_frontier, '{}', '[]', jsonb_build_array(
                    pgreact_internal.m40_finding(
                        'M40_OPTIONS_INVALID', 'ERROR', COALESCE(target_name, '<unknown>'),
                        'options.why_not.cause_limit',
                        'cause_limit exceeds the supported bound',
                        'Use a value between 1 and 1000.' )),
                jsonb_build_object('cause_limit', cause_limit),
                pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
        END IF;
        cause_limit := limit_text::integer;
        IF cause_limit > 1000 THEN
            RETURN pgreact_internal.m40_result(
                NULL, target_name, NULL, 'unsupported', subject, '{}', sampled_time,
                authoritative_frontier, '{}', '[]', jsonb_build_array(
                    pgreact_internal.m40_finding(
                        'M40_OPTIONS_INVALID', 'ERROR', COALESCE(target_name, '<unknown>'),
                        'options.why_not.cause_limit',
                        'cause_limit exceeds the supported bound',
                        'Use a value between 1 and 1000.' )),
                jsonb_build_object('cause_limit', cause_limit),
                pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
        END IF;
    END IF;
    limits := jsonb_build_object(
        'candidate_limit', 1000,
        'cause_limit', cause_limit,
        'path_depth_limit', 1,
        'evidence_limit', cause_limit);

    IF jsonb_typeof(expected_payload) IS DISTINCT FROM 'object'
       OR expected_kind IS NULL OR expected_key IS NULL OR expected_key = '' THEN
        RETURN pgreact_internal.m40_result(
            NULL, target_name, NULL, 'unsupported', subject, '{}', sampled_time,
            authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_EXPECTED_RESULT_INVALID', 'ERROR', COALESCE(target_name, '<unknown>'),
                    'options.why_not.expected_result',
                    'one public result kind and result key are required',
                    'Use result_kind and result_key in the why_not object.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;
    expected := jsonb_build_object('kind', expected_kind, 'key', expected_key)
        || CASE WHEN expected_value IS NULL THEN '{}'::jsonb
                ELSE jsonb_build_object('value', expected_value) END;

    SELECT count(*) INTO target_count
    FROM (
        SELECT declaration.kind, declaration.object_name
        FROM pgreact_internal.api_declarations declaration
        WHERE declaration.state = 'DEPLOYED'
        UNION
        SELECT 'policy_set', set.set_name
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE version.state = 'DEPLOYED'
        UNION
        SELECT 'derived_relation', relation.relation_name
        FROM pgreact_internal.derived_relations relation
        JOIN pgreact_internal.derived_relation_versions version USING (relation_id)
        WHERE version.state = 'ACTIVE'
    ) targets
    WHERE object_name = target_name;
    IF target_count = 0 THEN
        RETURN pgreact_internal.m40_result(
            NULL, target_name, NULL, 'unsupported', subject, expected, sampled_time,
            authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_TARGET_NOT_FOUND', 'ERROR', COALESCE(target_name, '<unknown>'),
                    'target', 'no deployed target with this public name exists',
                    'Use the stable name of one deployed rule, decision program, or policy set.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    ELSIF target_count > 1 THEN
        RETURN pgreact_internal.m40_result(
            NULL, target_name, NULL, 'unsupported', subject, expected, sampled_time,
            authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_TARGET_AMBIGUOUS', 'ERROR', target_name, 'target',
                    'more than one deployed target has this public name',
                    'Pass a unique public target name.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;
    SELECT kind, object_name INTO target_kind, target_name
    FROM (
        SELECT declaration.kind, declaration.object_name
        FROM pgreact_internal.api_declarations declaration
        WHERE declaration.state = 'DEPLOYED'
        UNION
        SELECT 'policy_set', set.set_name
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE version.state = 'DEPLOYED'
        UNION
        SELECT 'derived_relation', relation.relation_name
        FROM pgreact_internal.derived_relations relation
        JOIN pgreact_internal.derived_relation_versions version USING (relation_id)
        WHERE version.state = 'ACTIVE'
    ) targets
    WHERE object_name = target_name
    LIMIT 1;

    IF target_kind NOT IN ('rule', 'decision_program', 'policy_set', 'derived_relation') THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, NULL, 'unsupported', subject, expected, sampled_time,
            authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_UNSUPPORTED_TARGET', 'WARNING', target_name, 'target.kind',
                    'this target kind has no bounded M40 adapter',
                    'Use a deployed rule, decision program, policy set, or derived relation.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;

    subject_key := pgreact_internal.m40_subject_key(subject);
    subject_identity := CASE WHEN jsonb_typeof(subject) = 'object'
                             THEN subject::text ELSE subject #>> '{}' END;
    IF target_kind IN ('rule', 'decision_program', 'derived_relation') AND subject_key IS NULL THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, NULL, 'unsupported', subject, expected, sampled_time,
            authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_SUBJECT_INVALID', 'ERROR', target_name, 'subject',
                    'this adapter requires one bigint business key',
                    'Pass a JSON number or {"key": number}.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;

    IF target_kind = 'rule' AND expected_kind <> 'rule_match' THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, '1', 'unsupported', subject, expected, sampled_time,
            authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_UNSUPPORTED_RESULT', 'WARNING', target_name, 'expected_result.kind',
                    'rules accept the public rule_match result kind',
                    'Use result_kind => rule_match and the semantic key as result_key.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;
    IF target_kind = 'decision_program' AND expected_kind <> 'decision_result' THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, NULL, 'unsupported', subject, expected, sampled_time,
            authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_UNSUPPORTED_RESULT', 'WARNING', target_name, 'expected_result.kind',
                    'decision programs accept the public decision_result result kind',
                    'Use result_kind => decision_result and the candidate key as result_key.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;
    IF target_kind = 'policy_set' AND expected_kind <> 'policy_eligibility' THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, NULL, 'unsupported', subject, expected, sampled_time,
            authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_UNSUPPORTED_RESULT', 'WARNING', target_name, 'expected_result.kind',
                    'policy sets accept the public policy_eligibility result kind',
                    'Use result_kind => policy_eligibility and the subject as result_key.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;
    IF target_kind = 'derived_relation' AND expected_kind <> 'derived_fact' THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, NULL, 'unsupported', subject, expected, sampled_time,
            authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_UNSUPPORTED_RESULT', 'WARNING', target_name, 'expected_result.kind',
                    'derived relations accept the public derived_fact result kind',
                    'Use result_kind => derived_fact and the semantic key as result_key.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;

    expected_key_numeric := pgreact_internal.m40_subject_key(to_jsonb(expected_key));
    IF target_kind IN ('rule', 'derived_relation')
       AND (expected_key_numeric IS NULL OR expected_key_numeric <> subject_key) THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, NULL, 'unsupported', subject, expected,
            sampled_time, authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_EXPECTED_RESULT_INVALID', 'ERROR', target_name,
                    'expected_result.key',
                    'the expected result key must equal the bigint subject key',
                    'Use the subject key as result_key.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;
    IF target_kind = 'decision_program' AND expected_key_numeric IS NULL THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, NULL, 'unsupported', subject, expected,
            sampled_time, authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_EXPECTED_RESULT_INVALID', 'ERROR', target_name,
                    'expected_result.key',
                    'decision result keys must be bigint candidate keys',
                    'Use the candidate key as result_key.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;

    IF target_kind = 'derived_relation' THEN

        SELECT version.relation_version_id, version.version,
               version.public_view_oid, version.public_view_name
        INTO derived_row
        FROM pgreact_internal.derived_relations relation
        JOIN pgreact_internal.derived_relation_versions version USING (relation_id)
        WHERE relation.relation_name = target_name AND version.state = 'ACTIVE'
        ORDER BY version.version DESC
        LIMIT 1;
        IF derived_row.relation_version_id IS NULL THEN
            RETURN pgreact_internal.m40_result(
                target_kind, target_name, NULL, 'unavailable', subject, expected,
                sampled_time, authoritative_frontier, '{}', '[]', jsonb_build_array(
                    pgreact_internal.m40_finding(
                        'M40_EVIDENCE_UNAVAILABLE', 'WARNING', target_name, 'version',
                        'the active derived relation version is unavailable',
                        'Refresh or restore the derived relation before asking why-not.' )),
                limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
        END IF;
        target_version := derived_row.version::text;
        source_oid := derived_row.public_view_oid;
        source_name := derived_row.public_view_name;
        IF source_oid IS NULL OR NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
            RETURN pgreact_internal.m40_result(
                target_kind, target_name, target_version, 'unavailable', subject, expected,
                sampled_time, authoritative_frontier, '{}', '[]', jsonb_build_array(
                    pgreact_internal.m40_finding(
                        'M40_UNAUTHORIZED', 'WARNING', target_name, 'source',
                        'the caller cannot read the public derived-fact view',
                        'Grant the caller SELECT on the public derived-fact view.' )),
                limits, pgreact_internal.m40_cost(started_at, 1, 0, 0, 0, 0));
        END IF;
        SELECT jsonb_build_object(
                   'fact', fact.fact,
                   'support_count', fact.support_count,
                   'first_frontier', fact.first_frontier,
                   'last_frontier', fact.last_frontier)
        INTO derived_fact
        FROM pgreact.derived_facts fact
        WHERE fact.relation_name = target_name
          AND fact.relation_version = derived_row.version
          AND fact.semantic_key = subject_key
        LIMIT 1;
        SELECT count(*) INTO derived_support_count
        FROM pgreact_internal.derived_supports support
        WHERE support.relation_version_id = derived_row.relation_version_id
          AND support.semantic_key = subject_key AND support.active;
        IF derived_fact IS NOT NULL THEN
            state := 'already_present';
            observed := jsonb_build_object('state', 'DERIVED_FACT', 'fact', derived_fact);
        ELSIF derived_support_count = 0 THEN
            state := 'complete';
            causes := jsonb_build_array(jsonb_build_object(
                'kind', 'derived_fact', 'direction', 'absent',
                'path', 'derived.' || target_name || '.fact',
                'public_evidence', jsonb_build_object(
                    'relation', target_name, 'subject_key', subject_key,
                    'support_count', 0)));
            observed := jsonb_build_object(
                'state', 'ABSENT', 'support_count', derived_support_count);
            findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                'M40_DERIVED_FACT_MISSING', 'WARNING', target_name, 'derived_fact',
                'the modeled derived fact has no active support',
                'Inspect the maintained source rule and its public support evidence.'));
        ELSE
            state := 'unavailable';
            causes := jsonb_build_array(jsonb_build_object(
                'kind', 'positive_support', 'direction', 'present_without_fact',
                'path', 'derived.' || target_name || '.support',
                'public_evidence', jsonb_build_object(
                    'relation', target_name, 'subject_key', subject_key,
                    'support_count', derived_support_count)));
            findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                'M40_EVIDENCE_UNAVAILABLE', 'WARNING', target_name, 'derived_fact',
                'active support exists but the derived fact is not available',
                'Reconcile the derived relation before treating the absence as complete.'));
            observed := jsonb_build_object(
                'state', 'ABSENT', 'support_count', derived_support_count);
        END IF;
        SELECT COALESCE(jsonb_agg(value ORDER BY value ->> 'path'), '[]'::jsonb)
        INTO causes FROM jsonb_array_elements(causes) item(value);
        IF state = 'complete' OR state = 'already_present' THEN
            findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                'M40_NO_EFFECT', 'INFO', target_name, 'why_not',
                'why-not evaluation was read-only',
                'The request changed no source or pg-react state.'));
        END IF;
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, target_version, state, subject, expected,
            sampled_time, authoritative_frontier, observed, causes, findings, limits,
            pgreact_internal.m40_cost(started_at, 1, derived_support_count,
                                      jsonb_array_length(causes),
                                      CASE WHEN jsonb_array_length(causes) > 0 THEN 1 ELSE 0 END,
                                      jsonb_array_length(causes)));
    END IF;

    IF target_kind = 'rule' THEN
        SELECT version.rule_version_id, version.source_view_oid, version.source_view_name,
               version.key_column, version.state
        INTO STRICT decision_row
        FROM pgreact_internal.api_declarations declaration
        JOIN pgreact_internal.rule_versions version
          ON version.rule_version_id = declaration.delegated_id
        WHERE declaration.kind = 'rule'
          AND declaration.object_name = target_name
          AND declaration.state = 'DEPLOYED'
        ORDER BY version.created_at DESC
        LIMIT 1;
        target_version := '1';
        source_oid := decision_row.source_view_oid;
        source_name := decision_row.source_view_name;
        SELECT relkind, relrowsecurity INTO relation_kind, rls_enabled
        FROM pg_class WHERE oid = source_oid;
        IF relation_kind IS NULL THEN
            source_complete := false;
            findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                'M40_SCHEMA_DRIFT', 'WARNING', target_name, 'source',
                'the deployed rule source no longer exists',
                'Restore the source relation or deploy a replacement rule.'));
        ELSIF rls_enabled THEN
            source_complete := false;
            findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                'M40_RLS_REJECTED', 'WARNING', target_name, 'source',
                'row-level security prevents a safe complete answer',
                'Use a source with the inherited fail-closed RLS contract.'));
        ELSIF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
            source_complete := false;
            findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                'M40_UNAUTHORIZED', 'WARNING', target_name, 'source',
                'the caller lacks SELECT on a source needed for this answer',
                'Grant the caller read access to the source relation.'));
        ELSE
            IF NOT EXISTS (
                SELECT 1 FROM pg_attribute
                WHERE attrelid = source_oid AND attname = decision_row.key_column
                  AND attnum > 0 AND NOT attisdropped) THEN
                source_complete := false;
                findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                    'M40_SCHEMA_DRIFT', 'WARNING', target_name, 'source.key_column',
                    'the deployed rule key column no longer exists',
                    'Restore the declared key column or deploy a replacement rule.'));
            ELSE
                EXECUTE format('SELECT count(*) FROM %s s WHERE s.%I = $1',
                               source_oid::regclass, decision_row.key_column)
                INTO source_count USING subject_key;
                EXECUTE format('SELECT to_jsonb(s) FROM %s s WHERE s.%I = $1 LIMIT 1',
                               source_oid::regclass, decision_row.key_column)
                INTO source_row USING subject_key;
                SELECT jsonb_build_object(
                           'semantic_key', current_match.semantic_key,
                           'active', current_match.active,
                           'generation', current_match.generation,
                           'revision', current_match.revision,
                           'bindings', current_match.bindings)
                INTO match_row
                FROM pgreact.matches current_match
                WHERE current_match.name = target_name
                  AND current_match.semantic_key = subject_key
                  AND current_match.active
                ORDER BY current_match.revision DESC
                LIMIT 1;
                IF match_row IS NOT NULL THEN
                    state := 'already_present';
                    observed := jsonb_build_object('state', 'MATCH', 'match', match_row);
                ELSE
                    IF source_count = 0 THEN
                        causes := causes || jsonb_build_array(jsonb_build_object(
                            'kind', 'missing_input', 'direction', 'absent',
                            'path', 'source.' || decision_row.key_column::text,
                            'public_evidence', jsonb_build_object(
                                'source', source_name, 'key', subject_key, 'row', NULL)));
                    ELSE
                        causes := causes || jsonb_build_array(jsonb_build_object(
                            'kind', 'positive_support', 'direction', 'present_but_not_active',
                            'path', 'source.' || decision_row.key_column::text,
                            'public_evidence', jsonb_build_object(
                                'source', source_name, 'key', subject_key, 'row', source_row)));
                        source_complete := false;
                        findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                            'M40_EVIDENCE_UNAVAILABLE', 'WARNING', target_name, 'activation',
                            'the source row is present but no active match is available',
                            'Refresh the deployed rule before treating the absence as complete.'));
                    END IF;
                    IF decision_row.state <> 'ACTIVE' THEN
                        causes := causes || jsonb_build_array(jsonb_build_object(
                            'kind', 'lifecycle_revision', 'direction', 'disqualifying',
                            'path', 'runtime.state',
                            'public_evidence', jsonb_build_object(
                                'state', decision_row.state)));
                    END IF;
                    FOR scope_row IN
                        SELECT set.set_name, version.version,
                               EXISTS (SELECT 1
                                       FROM pgreact_internal.policy_set_runtime_barriers barrier
                                       WHERE barrier.policy_set_version_id = version.policy_set_version_id
                                         AND barrier.cleared_at IS NULL) AS blocked
                        FROM pgreact_internal.policy_set_members member
                        JOIN pgreact_internal.policy_set_versions version
                          USING (policy_set_version_id)
                        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
                        WHERE member.member_kind = 'rule'
                          AND member.member_name = target_name
                          AND member.member_version IN ('1', decision_row.rule_version_id::text)
                          AND member.scope_mode = 'POLICY_SET_REQUIRED'
                          AND version.state = 'DEPLOYED'
                          AND version.valid_from <= sampled_time
                          AND (version.valid_to IS NULL OR sampled_time < version.valid_to)
                    LOOP
                        IF scope_row.blocked THEN
                            source_complete := false;
                            findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                                'M40_EVIDENCE_UNAVAILABLE', 'WARNING', target_name,
                                'applicability', 'a required policy-set runtime barrier is active',
                                'Repair the policy-set source before using the answer.'));
                        ELSIF NOT pgreact_internal.m30_subject_eligible(
                                  pgreact_api.target('policy_set', scope_row.set_name, scope_row.version),
                                  subject) THEN
                            causes := causes || jsonb_build_array(jsonb_build_object(
                                'kind', 'applicability', 'direction', 'disqualifying',
                                'path', 'policy_set.' || scope_row.set_name || '.eligibility',
                                'public_evidence', jsonb_build_object(
                                    'policy_set', scope_row.set_name,
                                    'version', scope_row.version,
                                    'subject', subject)));
                        END IF;
                    END LOOP;
                END IF;
            END IF;
        END IF;
        IF state IS NULL THEN
            state := CASE WHEN source_complete THEN 'complete' ELSE 'unavailable' END;
        END IF;
        SELECT COALESCE(jsonb_agg(value ORDER BY value ->> 'path'), '[]'::jsonb)
        INTO causes FROM jsonb_array_elements(causes) item(value);
        IF state = 'complete' OR state = 'already_present' THEN
            findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                'M40_NO_EFFECT', 'INFO', target_name, 'why_not',
                'why-not evaluation was read-only',
                'The request changed no source or pg-react state.'));
        END IF;
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, target_version, state, subject, expected,
            sampled_time, authoritative_frontier,
            COALESCE(observed, jsonb_build_object('state', 'ABSENT', 'source', source_name)),
            causes, findings, limits,
            pgreact_internal.m40_cost(started_at, 1, jsonb_array_length(causes),
                                      jsonb_array_length(causes),
                                      CASE WHEN jsonb_array_length(causes) > 0 THEN 1 ELSE 0 END,
                                      jsonb_array_length(causes)));
    END IF;

    IF target_kind = 'decision_program' THEN
        IF expected_key !~ '^-?[0-9]+$' THEN
            RETURN pgreact_internal.m40_result(
                target_kind, target_name, NULL, 'unsupported', subject, expected,
                sampled_time, authoritative_frontier, '{}', '[]', jsonb_build_array(
                    pgreact_internal.m40_finding(
                        'M40_EXPECTED_RESULT_INVALID', 'ERROR', target_name,
                        'expected_result.key', 'decision result keys must be bigint candidate keys',
                        'Use the candidate key as result_key.' )),
                limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
        END IF;
        SELECT version.*
        INTO decision_row
        FROM pgreact_internal.decision_programs program
        JOIN pgreact_internal.decision_program_versions version USING (program_id)
        WHERE program.program_name = target_name
          AND program.state <> 'REMOVED'
          AND version.state = 'DEPLOYED'
        ORDER BY version.valid_from DESC, version.version_no DESC
        LIMIT 1;
        IF decision_row.version_id IS NULL THEN
            RETURN pgreact_internal.m40_result(
                target_kind, target_name, NULL, 'unavailable', subject, expected,
                sampled_time, authoritative_frontier, '{}', '[]', jsonb_build_array(
                    pgreact_internal.m40_finding(
                        'M40_EVIDENCE_UNAVAILABLE', 'WARNING', target_name, 'version',
                        'the deployed decision version is unavailable',
                        'Deploy a current decision version before asking why-not.' )),
                limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
        END IF;
        target_version := decision_row.version_no::text;
        source_oid := decision_row.candidate_relation_oid;
        source_name := decision_row.candidate_relation_name;
        IF sampled_time < decision_row.valid_from
           OR (decision_row.valid_to IS NOT NULL AND sampled_time >= decision_row.valid_to) THEN
            causes := jsonb_build_array(jsonb_build_object(
                'kind', 'inactive_policy_time', 'direction', 'disqualifying',
                'path', 'decision.validity',
                'public_evidence', jsonb_build_object(
                    'valid_from', decision_row.valid_from,
                    'valid_to', decision_row.valid_to,
                    'sampled_time', sampled_time)));
            RETURN pgreact_internal.m40_result(
                target_kind, target_name, target_version, 'complete', subject, expected,
                sampled_time, authoritative_frontier,
                jsonb_build_object('state', 'INACTIVE_TIME'), causes,
                jsonb_build_array(pgreact_internal.m40_finding(
                    'M40_NO_EFFECT', 'INFO', target_name, 'why_not',
                    'why-not evaluation was read-only',
                    'The request changed no source or pg-react state.')),
                limits, pgreact_internal.m40_cost(started_at, 1, 0, 1, 1, 1));
        END IF;
        SELECT relkind, relrowsecurity INTO relation_kind, rls_enabled
        FROM pg_class WHERE oid = source_oid;
        IF relation_kind IS NULL THEN
            findings := jsonb_build_array(pgreact_internal.m40_finding(
                'M40_SCHEMA_DRIFT', 'WARNING', target_name, 'source',
                'the decision candidate source no longer exists',
                'Restore the source relation or deploy a replacement decision.'));
            source_complete := false;
        ELSIF rls_enabled THEN
            findings := jsonb_build_array(pgreact_internal.m40_finding(
                'M40_RLS_REJECTED', 'WARNING', target_name, 'source',
                'row-level security prevents a safe complete answer',
                'Use a source with the inherited fail-closed RLS contract.'));
            source_complete := false;
        ELSIF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
            findings := jsonb_build_array(pgreact_internal.m40_finding(
                'M40_UNAUTHORIZED', 'WARNING', target_name, 'source',
                'the caller lacks SELECT on the candidate source',
                'Grant the caller read access to the source relation.'));
            source_complete := false;
        ELSE
            EXECUTE format('SELECT count(*) FROM %s s WHERE s.%I = $1',
                           source_oid::regclass, decision_row.subject_key_column)
            INTO candidate_count USING subject_key;
            EXECUTE format(
                'SELECT to_jsonb(s), s.%1$I::bigint, s.%2$I::bigint
                 FROM %3$s s WHERE s.%4$I = $1 AND s.%1$I = $2 LIMIT 1',
                decision_row.candidate_key_column, decision_row.priority_column,
                source_oid::regclass, decision_row.subject_key_column)
            INTO candidate_row, winner_candidate, candidate_priority
            USING subject_key, expected_key_numeric;
            SELECT jsonb_build_object(
                       'state', winner.state,
                       'winner_candidate', winner.winner_candidate,
                       'winner_priority', winner.winner_priority,
                       'winner_result', winner.winner_result,
                       'competitors', winner.competitors,
                       'competitors_truncated', winner.competitors_truncated),
                   winner.state, winner.winner_candidate, winner.winner_priority
            INTO winner_row, winner_state, winner_candidate, winner_priority
            FROM pgreact.decision_winners winner
            WHERE winner.program_name = target_name
              AND winner.subject_key = pgreact_internal.m40_subject_key(subject)
            LIMIT 1;
            observed := jsonb_build_object(
                'state', COALESCE(winner_state, 'NO_CANDIDATE'),
                'candidate_count', candidate_count,
                'expected_candidate', candidate_row,
                'winner', COALESCE(winner_row, '{}'::jsonb));
            IF winner_state = 'WINNER' AND winner_candidate = expected_key_numeric THEN
                state := 'already_present';
            ELSE
                IF candidate_row IS NULL THEN
                    causes := causes || jsonb_build_array(jsonb_build_object(
                        'kind', 'decision_candidate', 'direction', 'absent',
                        'path', 'candidate.' || expected_key,
                        'public_evidence', jsonb_build_object(
                            'source', source_name, 'subject', subject_key,
                            'candidate_key', expected_key, 'row', NULL)));
                END IF;
                IF winner_state = 'NO_CANDIDATE' OR winner_state = 'AMBIGUOUS'
                   OR winner_state IS NULL THEN
                    causes := causes || jsonb_build_array(jsonb_build_object(
                        'kind', 'decision_eligibility', 'direction', 'disqualifying',
                        'path', 'decision.state',
                        'public_evidence', jsonb_build_object(
                            'state', COALESCE(winner_state, 'NO_CANDIDATE'),
                            'candidate_count', candidate_count)));
                ELSIF candidate_row IS NOT NULL THEN
                    causes := causes || jsonb_build_array(jsonb_build_object(
                        'kind', 'decision_selection', 'direction', 'not_selected',
                        'path', 'decision.winner',
                        'public_evidence', jsonb_build_object(
                            'expected_candidate', expected_key,
                            'expected_priority', candidate_priority,
                            'winner_candidate', winner_candidate,
                            'winner_priority', winner_priority)));
                END IF;
                IF candidate_count > decision_row.max_candidates THEN
                    source_complete := false;
                    findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                        'M40_RESOURCE_LIMIT', 'WARNING', target_name, 'candidate_count',
                        'the candidate source exceeds its declared bound',
                        'Reduce candidates or deploy a decision with a larger bound.'));
                END IF;
            END IF;
        END IF;
        IF state IS NULL THEN
            state := CASE WHEN source_complete THEN 'complete' ELSE 'unavailable' END;
        END IF;
        SELECT COALESCE(jsonb_agg(value ORDER BY value ->> 'path'), '[]'::jsonb)
        INTO causes FROM jsonb_array_elements(causes) item(value);
        IF state = 'complete' OR state = 'already_present' THEN
            findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
                'M40_NO_EFFECT', 'INFO', target_name, 'why_not',
                'why-not evaluation was read-only',
                'The request changed no source or pg-react state.'));
        END IF;
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, target_version, state, subject, expected,
            sampled_time, authoritative_frontier, observed, causes, findings, limits,
            pgreact_internal.m40_cost(started_at, candidate_count, 1,
                                      jsonb_array_length(causes),
                                      CASE WHEN jsonb_array_length(causes) > 0 THEN 1 ELSE 0 END,
                                      jsonb_array_length(causes)));
    END IF;

    subject_identity := CASE WHEN jsonb_typeof(subject) = 'object'
                             THEN subject::text ELSE subject #>> '{}' END;
    IF expected_key <> subject_identity THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, NULL, 'unsupported', subject, expected,
            sampled_time, authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_EXPECTED_RESULT_INVALID', 'ERROR', target_name,
                    'expected_result.key',
                    'the policy eligibility key must equal the supplied subject',
                    'Use the subject JSON value as result_key.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;
    SELECT version.* INTO policy_row
    FROM pgreact_internal.policy_set_versions version
    JOIN pgreact_internal.policy_sets set USING (policy_set_id)
    WHERE set.set_name = target_name AND version.state = 'DEPLOYED'
    ORDER BY version.valid_from DESC
    LIMIT 1;
    IF policy_row.policy_set_version_id IS NULL THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, NULL, 'unavailable', subject, expected,
            sampled_time, authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_EVIDENCE_UNAVAILABLE', 'WARNING', target_name, 'version',
                    'the deployed policy-set version is unavailable',
                    'Deploy a current policy-set version before asking why-not.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;
    target_version := policy_row.version;
    IF policy_row.applicability_kind <> 'relation' THEN
        RETURN pgreact_internal.m40_result(
            target_kind, target_name, target_version, 'unsupported', subject, expected,
            sampled_time, authoritative_frontier, '{}', '[]', jsonb_build_array(
                pgreact_internal.m40_finding(
                    'M40_UNSUPPORTED_TARGET', 'WARNING', target_name, 'applicability',
                    'only relational policy-set applicability is modeled in M40',
                    'Use a relation-backed policy-set or wait for a later adapter.' )),
            limits, pgreact_internal.m40_cost(started_at, 0, 0, 0, 0, 0));
    END IF;
    source_oid := policy_row.applicability_source_oid;
    source_name := policy_row.applicability_source;
    SELECT relkind, relrowsecurity INTO relation_kind, rls_enabled
    FROM pg_class WHERE oid = source_oid;
    IF relation_kind IS NULL THEN
        source_complete := false;
        findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
            'M40_SCHEMA_DRIFT', 'WARNING', target_name, 'applicability',
            'the policy-set applicability source no longer exists',
            'Restore the source relation or deploy a replacement policy set.'));
    ELSIF rls_enabled THEN
        source_complete := false;
        findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
            'M40_RLS_REJECTED', 'WARNING', target_name, 'applicability',
            'row-level security prevents a safe complete answer',
            'Use a source with the inherited fail-closed RLS contract.'));
    ELSIF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
        source_complete := false;
        findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
            'M40_UNAUTHORIZED', 'WARNING', target_name, 'applicability',
            'the caller lacks SELECT on the applicability source',
            'Grant the caller read access to the source relation.'));
    END IF;
    IF sampled_time < policy_row.valid_from
       OR (policy_row.valid_to IS NOT NULL AND sampled_time >= policy_row.valid_to) THEN
        causes := jsonb_build_array(jsonb_build_object(
            'kind', 'inactive_policy_time', 'direction', 'disqualifying',
            'path', 'policy_set.validity',
            'public_evidence', jsonb_build_object(
                'valid_from', policy_row.valid_from,
                'valid_to', policy_row.valid_to,
                'sampled_time', sampled_time)));
        state := 'complete';
    ELSIF source_complete THEN
        IF pgreact_internal.m30_subject_eligible(
               pgreact_api.target('policy_set', target_name, target_version), subject) THEN
            state := 'already_present';
            observed := jsonb_build_object('state', 'ELIGIBLE', 'subject', subject);
        ELSE
            causes := jsonb_build_array(jsonb_build_object(
                'kind', 'applicability', 'direction', 'disqualifying',
                'path', 'policy_set.eligibility',
                'public_evidence', jsonb_build_object(
                    'policy_set', target_name, 'version', target_version,
                    'subject', subject, 'eligible', false)));
            state := 'complete';
            observed := jsonb_build_object('state', 'INELIGIBLE', 'subject', subject);
        END IF;
    ELSE
        state := 'unavailable';
    END IF;
    IF policy_row.complete_frontier < sampled_time AND state <> 'already_present' THEN
        state := 'partial';
        findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
            'M40_STALE_FRONTIER', 'WARNING', target_name, 'authoritative_frontier',
            'the installed eligibility evidence is older than the sampled time',
            'Refresh the policy set and retry the request.'));
    END IF;
    SELECT COALESCE(jsonb_agg(value ORDER BY value ->> 'path'), '[]'::jsonb)
    INTO causes FROM jsonb_array_elements(causes) item(value);
    IF state = 'complete' OR state = 'already_present' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m40_finding(
            'M40_NO_EFFECT', 'INFO', target_name, 'why_not',
            'why-not evaluation was read-only',
            'The request changed no source or pg-react state.'));
    END IF;
    RETURN pgreact_internal.m40_result(
        target_kind, target_name, target_version, state, subject, expected,
        sampled_time, authoritative_frontier, observed, causes, findings, limits,
        pgreact_internal.m40_cost(started_at, 1, 1, jsonb_array_length(causes),
                                  CASE WHEN jsonb_array_length(causes) > 0 THEN 1 ELSE 0 END,
                                  jsonb_array_length(causes)));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m40_subject_key(subject jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE value_text text;
BEGIN
    IF subject IS NULL THEN
        RETURN NULL;
    ELSIF jsonb_typeof(subject) = 'object' THEN
        value_text := COALESCE(subject ->> 'key', subject ->> 'subject');
    ELSIF jsonb_typeof(subject) IN ('number', 'string') THEN
        value_text := subject #>> '{}';
    ELSE
        RETURN NULL;
    END IF;
    IF value_text IS NULL OR value_text !~ '^-?[0-9]+$' THEN
        RETURN NULL;
    END IF;
    BEGIN
        RETURN value_text::bigint;
    EXCEPTION WHEN numeric_value_out_of_range THEN
        RETURN NULL;
    END;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m41_decision_fragment(target_name text, subject_key bigint, result_key bigint DEFAULT NULL::bigint, parent_id text DEFAULT NULL::text, sampled_time timestamp with time zone DEFAULT statement_timestamp(), depth_limit integer DEFAULT 16, fanout_limit integer DEFAULT 64, path_limit integer DEFAULT 64)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
<<m41_decision_block>>
DECLARE
    version_row record;
    winner_row record;
    candidate_row jsonb;
    policy_row record;
    child jsonb;
    source_id text;
    result_id text;
    selection_id text;
    candidate_id text;
    boundary_id text;
    edge jsonb;
    nodes jsonb := '[]'::jsonb;
    edges jsonb := '[]'::jsonb;
    paths jsonb := '[]'::jsonb;
    boundaries jsonb := '[]'::jsonb;
    findings jsonb := '[]'::jsonb;
    path_nodes jsonb;
    path_edges jsonb;
    source_state text;
    relation_kind "char";
    rls_enabled boolean;
    candidate_value bigint;
    priority_value bigint;
    effective_result_key bigint;
    state text := 'complete';
BEGIN
    SELECT version.* INTO version_row
    FROM pgreact_internal.decision_programs program
    JOIN pgreact_internal.decision_program_versions version USING (program_id)
    WHERE program.program_name = target_name AND program.state <> 'REMOVED'
      AND version.state = 'DEPLOYED'
    ORDER BY version.valid_from DESC, version.version_no DESC LIMIT 1;
    IF NOT FOUND THEN
        boundary_id := 'boundary:missing:decision';
        edge := pgreact_internal.m41_edge('decision_predecessor', parent_id, boundary_id);
        RETURN jsonb_build_object('state', 'unavailable', 'nodes', nodes,
            'edges', jsonb_build_array(edge), 'paths', jsonb_build_array(
                pgreact_internal.m41_path(jsonb_build_array(parent_id, boundary_id),
                                           jsonb_build_array(edge ->> 'identity'), 'unavailable')),
            'boundaries', jsonb_build_array(jsonb_build_object('kind', 'missing', 'identity', boundary_id)),
            'findings', jsonb_build_array(pgreact_internal.m41_finding(
                'M41_EVIDENCE_MISSING', 'WARNING', target_name, 'decision',
                'the deployed decision version is unavailable',
                'Deploy or restore the decision evidence before retrying.')));
    END IF;
    SELECT state.* INTO winner_row
    FROM pgreact_internal.decision_subject_state state
    WHERE state.program_id = version_row.program_id
      AND state.subject_key = m41_decision_fragment.subject_key;
    IF NOT FOUND THEN
        boundary_id := 'boundary:missing:decision-result';
        edge := pgreact_internal.m41_edge('decision_predecessor', parent_id, boundary_id);
        RETURN jsonb_build_object('state', 'unavailable', 'nodes', nodes,
            'edges', jsonb_build_array(edge), 'paths', jsonb_build_array(
                pgreact_internal.m41_path(jsonb_build_array(parent_id, boundary_id),
                                           jsonb_build_array(edge ->> 'identity'), 'unavailable')),
            'boundaries', jsonb_build_array(jsonb_build_object('kind', 'missing', 'identity', boundary_id)),
            'findings', jsonb_build_array(pgreact_internal.m41_finding(
                'M41_ROOT_NOT_FOUND', 'WARNING', target_name, 'decision_result',
                'the requested decision result is not retained',
                'Use a current decision result identity.')));
    END IF;
    effective_result_key := COALESCE(result_key, winner_row.winner_candidate);
    result_id := format('decision_result:%s@%s:subject=%s:candidate=%s:revision=%s',
                        target_name, version_row.version_no, subject_key,
                        COALESCE(effective_result_key::text, '<none>'), winner_row.revision);
    nodes := jsonb_build_array(jsonb_build_object(
        'kind', 'decision_result', 'identity', result_id,
        'evidence', jsonb_build_object(
            'target', target_name, 'version', version_row.version_no,
            'subject_key', subject_key, 'state', winner_row.state,
            'candidate_key', winner_row.winner_candidate,
            'priority', winner_row.winner_priority, 'result', winner_row.winner_result,
            'generation', winner_row.generation, 'revision', winner_row.revision)));
    IF parent_id IS NOT NULL THEN
        edge := pgreact_internal.m41_edge('decision_work', parent_id, result_id);
        edges := edges || jsonb_build_array(edge);
        path_nodes := jsonb_build_array(parent_id, result_id);
        path_edges := jsonb_build_array(edge ->> 'identity');
    ELSE
        path_nodes := jsonb_build_array(result_id);
        path_edges := '[]'::jsonb;
    END IF;
    IF winner_row.state <> 'WINNER' OR winner_row.winner_candidate IS NULL
       OR effective_result_key <> winner_row.winner_candidate THEN
        state := 'unavailable';
        boundary_id := 'boundary:missing:decision-selection:' ||
            pgreact_internal.m41_digest(jsonb_build_object('target', target_name, 'subject_key', subject_key));
        boundaries := jsonb_build_array(jsonb_build_object('kind', 'missing', 'identity', boundary_id));
        edge := pgreact_internal.m41_edge('decision_selection', result_id, boundary_id);
        edges := edges || jsonb_build_array(edge);
        paths := jsonb_build_array(pgreact_internal.m41_path(
            path_nodes || jsonb_build_array(boundary_id),
            path_edges || jsonb_build_array(edge ->> 'identity'), state));
        findings := jsonb_build_array(pgreact_internal.m41_finding(
            'M41_ROOT_NOT_FOUND', 'WARNING', target_name, 'decision_result',
            'the requested candidate is not the retained decision winner',
            'Use the current winner candidate and revision.'));
        RETURN jsonb_build_object('state', state, 'nodes', nodes, 'edges', edges,
            'paths', paths, 'boundaries', boundaries, 'findings', findings);
    END IF;
    selection_id := format('decision_selection:%s@%s:subject=%s:revision=%s',
                           target_name, version_row.version_no, subject_key, winner_row.revision);
    candidate_id := format('decision_candidate:%s@%s:subject=%s:candidate=%s',
                           target_name, version_row.version_no, subject_key, effective_result_key);
    nodes := nodes || jsonb_build_array(
        jsonb_build_object('kind', 'decision_selection', 'identity', selection_id,
            'evidence', jsonb_build_object(
                'state', winner_row.state, 'winner_candidate', winner_row.winner_candidate,
                'winner_priority', winner_row.winner_priority, 'revision', winner_row.revision)),
        jsonb_build_object('kind', 'decision_candidate', 'identity', candidate_id,
            'evidence', jsonb_build_object('candidate_key', effective_result_key,
                'priority', winner_row.winner_priority, 'result', winner_row.winner_result)));
    edge := pgreact_internal.m41_edge('decision_selection', result_id, selection_id);
    edges := edges || jsonb_build_array(edge);
    edge := pgreact_internal.m41_edge('decision_candidate', selection_id, candidate_id);
    edges := edges || jsonb_build_array(edge);
    path_nodes := path_nodes || jsonb_build_array(selection_id, candidate_id);
    path_edges := path_edges || jsonb_build_array(
        edges -> (jsonb_array_length(edges) - 2) ->> 'identity',
        edges -> (jsonb_array_length(edges) - 1) ->> 'identity');

    SELECT c.relkind, c.relrowsecurity INTO relation_kind, rls_enabled
    FROM pg_class c WHERE c.oid = version_row.candidate_relation_oid;
    IF relation_kind IS NULL THEN source_state := 'schema_drift';
    ELSIF rls_enabled THEN source_state := 'rls';
    ELSIF NOT has_table_privilege(session_user, version_row.candidate_relation_oid, 'SELECT') THEN source_state := 'unauthorized';
    ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = version_row.candidate_relation_oid
                      AND attname = version_row.subject_key_column AND attnum > 0 AND NOT attisdropped)
       OR NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = version_row.candidate_relation_oid
                      AND attname = version_row.candidate_key_column AND attnum > 0 AND NOT attisdropped)
       OR NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = version_row.candidate_relation_oid
                      AND attname = version_row.priority_column AND attnum > 0 AND NOT attisdropped)
    THEN source_state := 'schema_drift';
    ELSE
        EXECUTE format('SELECT to_jsonb(s) FROM %s s WHERE s.%I = $1 AND s.%I = $2 LIMIT 1',
                       version_row.candidate_relation_oid::regclass,
                       version_row.subject_key_column, version_row.candidate_key_column)
        INTO candidate_row USING subject_key, effective_result_key;
        source_state := CASE WHEN candidate_row IS NULL THEN 'missing' ELSE 'ok' END;
    END IF;
    IF source_state = 'ok' THEN
        source_id := format('authoritative:%s:subject=%s:candidate=%s',
                            version_row.candidate_relation_name, subject_key, effective_result_key);
        nodes := nodes || jsonb_build_array(jsonb_build_object(
            'kind', 'authoritative_fact', 'identity', source_id,
            'evidence', jsonb_build_object('source', version_row.candidate_relation_name,
                                            'subject_key', subject_key,
                                            'candidate_key', effective_result_key,
                                            'row', candidate_row)));
        edge := pgreact_internal.m41_edge('candidate_source', candidate_id, source_id);
        edges := edges || jsonb_build_array(edge);
        path_nodes := path_nodes || jsonb_build_array(source_id);
        path_edges := path_edges || jsonb_build_array(edge ->> 'identity');
    ELSE
        state := CASE WHEN source_state = 'missing' THEN 'partial' ELSE 'unavailable' END;
        boundary_id := 'boundary:' || CASE source_state
            WHEN 'unauthorized' THEN 'inaccessible'
            WHEN 'rls' THEN 'inaccessible'
            WHEN 'schema_drift' THEN 'schema_drift'
            WHEN 'missing' THEN 'missing'
            ELSE 'unsupported' END || ':' || pgreact_internal.m41_digest(
                jsonb_build_object('parent', candidate_id));
        boundaries := boundaries || jsonb_build_array(jsonb_build_object(
            'kind', split_part(boundary_id, ':', 2), 'identity', boundary_id));
        edge := pgreact_internal.m41_edge('candidate_source', candidate_id, boundary_id);
        edges := edges || jsonb_build_array(edge);
        path_nodes := path_nodes || jsonb_build_array(boundary_id);
        path_edges := path_edges || jsonb_build_array(edge ->> 'identity');
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            CASE source_state
                WHEN 'unauthorized' THEN 'M41_UNAUTHORIZED'
                WHEN 'rls' THEN 'M41_RLS_REJECTED'
                WHEN 'schema_drift' THEN 'M41_SCHEMA_DRIFT'
                WHEN 'missing' THEN 'M41_EVIDENCE_MISSING'
                ELSE 'M41_UNSUPPORTED_NODE' END,
            'WARNING', target_name, 'candidate_source',
            'the decision candidate ends at an explicit evidence boundary',
            'Restore the candidate source and retry the request.'));
    END IF;
    paths := jsonb_build_array(pgreact_internal.m41_path(path_nodes, path_edges, state));

    FOR policy_row IN
        SELECT version.policy_set_version_id
        FROM pgreact_internal.policy_set_members member
        JOIN pgreact_internal.policy_set_versions version
          USING (policy_set_version_id)
        WHERE member.member_kind = 'decision_program'
          AND member.member_name = target_name
          AND version.state = 'DEPLOYED'
          AND version.valid_from <= sampled_time
          AND (version.valid_to IS NULL OR sampled_time < version.valid_to)
        ORDER BY version.valid_from, version.version
    LOOP
        child := pgreact_internal.m41_policy_fragment(
            policy_row.policy_set_version_id, subject_key, result_id, sampled_time,
            depth_limit, fanout_limit, path_limit);
        nodes := pgreact_internal.m41_array_union(nodes, child -> 'nodes');
        edges := pgreact_internal.m41_array_union(edges, child -> 'edges');
        paths := pgreact_internal.m41_array_union(paths, child -> 'paths');
        boundaries := pgreact_internal.m41_array_union(boundaries, child -> 'boundaries');
        findings := pgreact_internal.m41_array_union(findings, child -> 'findings');
        IF child ->> 'state' = 'unavailable' THEN state := 'unavailable';
        ELSIF child ->> 'state' = 'partial' AND state = 'complete' THEN state := 'partial';
        ELSIF child ->> 'state' = 'unsupported' AND state = 'complete' THEN state := 'unsupported'; END IF;
    END LOOP;
    RETURN jsonb_build_object('state', state, 'nodes', nodes, 'edges', edges,
                              'paths', paths, 'boundaries', boundaries, 'findings', findings);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m41_derived_fragment(relation_version_id uuid, subject_key bigint, parent_id text DEFAULT NULL::text, depth integer DEFAULT 0, depth_limit integer DEFAULT 16, fanout_limit integer DEFAULT 64, path_limit integer DEFAULT 64, visited text[] DEFAULT ARRAY[]::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
<<m41_derived_block>>
DECLARE
    relation_row record;
    fact_row record;
    support_row record;
    input_row record;
    child jsonb;
    child_path jsonb;
    source_fragment jsonb;
    relation_identity text;
    fact_identity text;
    support_identity text;
    boundary_id text;
    path_nodes jsonb;
    path_edges jsonb;
    combined_nodes jsonb;
    combined_edges jsonb;
    support_edge jsonb;
    child_edge jsonb;
    nodes jsonb := '[]'::jsonb;
    edges jsonb := '[]'::jsonb;
    paths jsonb := '[]'::jsonb;
    boundaries jsonb := '[]'::jsonb;
    findings jsonb := '[]'::jsonb;
    state text := 'complete';
    support_number integer := 0;
    input_count bigint;
    support_count bigint;
BEGIN
    SELECT relation.relation_name, version.version, version.public_view_name
    INTO relation_row
    FROM pgreact_internal.derived_relation_versions version
    JOIN pgreact_internal.derived_relations relation USING (relation_id)
    WHERE version.relation_version_id = m41_derived_fragment.relation_version_id;
    IF NOT FOUND THEN
        boundary_id := 'boundary:missing:derived-relation';
        boundaries := jsonb_build_array(jsonb_build_object(
            'kind', 'missing', 'identity', boundary_id));
        IF parent_id IS NULL THEN
            path_nodes := jsonb_build_array(boundary_id);
        ELSE
            path_nodes := jsonb_build_array(parent_id, boundary_id);
            child_edge := pgreact_internal.m41_edge('derived_predecessor', parent_id, boundary_id);
            edges := jsonb_build_array(child_edge);
            path_edges := jsonb_build_array(child_edge ->> 'identity');
        END IF;
        RETURN jsonb_build_object('state', 'unavailable', 'nodes', nodes, 'edges', edges,
            'paths', jsonb_build_array(pgreact_internal.m41_path(
                path_nodes, COALESCE(path_edges, '[]'::jsonb), 'unavailable')),
            'boundaries', boundaries,
            'findings', jsonb_build_array(pgreact_internal.m41_finding(
                'M41_EVIDENCE_MISSING', 'WARNING', '<unknown>', 'derived_relation',
                'the modeled derived relation version is unavailable',
                'Restore the derived relation evidence before retrying.')));
    END IF;
    relation_identity := relation_row.relation_name || '@' || relation_row.version;
    IF relation_identity = ANY (visited) THEN
        boundary_id := 'boundary:cyclic:' || pgreact_internal.m41_digest(
            jsonb_build_object('relation', relation_identity, 'subject_key', subject_key));
        boundaries := jsonb_build_array(jsonb_build_object('kind', 'cyclic', 'identity', boundary_id));
        IF parent_id IS NULL THEN
            path_nodes := jsonb_build_array(boundary_id);
        ELSE
            path_nodes := jsonb_build_array(parent_id, boundary_id);
            child_edge := pgreact_internal.m41_edge('cycle', parent_id, boundary_id);
            edges := jsonb_build_array(child_edge);
            path_edges := jsonb_build_array(child_edge ->> 'identity');
        END IF;
        RETURN jsonb_build_object('state', 'partial', 'nodes', nodes, 'edges', edges,
            'paths', jsonb_build_array(pgreact_internal.m41_path(
                path_nodes, COALESCE(path_edges, '[]'::jsonb), 'partial')),
            'boundaries', boundaries,
            'findings', jsonb_build_array(pgreact_internal.m41_finding(
                'M41_CYCLE', 'WARNING', relation_row.relation_name, 'support',
                'derived support contains a cycle',
                'Inspect the recursive support definition.')));
    END IF;
    IF depth >= depth_limit THEN
        boundary_id := 'boundary:over_limit:' || pgreact_internal.m41_digest(
            jsonb_build_object('relation', relation_identity, 'subject_key', subject_key));
        boundaries := jsonb_build_array(jsonb_build_object('kind', 'over_limit', 'identity', boundary_id));
        IF parent_id IS NULL THEN
            path_nodes := jsonb_build_array(boundary_id);
        ELSE
            path_nodes := jsonb_build_array(parent_id, boundary_id);
            child_edge := pgreact_internal.m41_edge('depth_limit', parent_id, boundary_id);
            edges := jsonb_build_array(child_edge);
            path_edges := jsonb_build_array(child_edge ->> 'identity');
        END IF;
        RETURN jsonb_build_object('state', 'partial', 'nodes', nodes, 'edges', edges,
            'paths', jsonb_build_array(pgreact_internal.m41_path(
                path_nodes, COALESCE(path_edges, '[]'::jsonb), 'partial')),
            'boundaries', boundaries,
            'findings', jsonb_build_array(pgreact_internal.m41_finding(
                'M41_RESOURCE_LIMIT', 'WARNING', relation_row.relation_name, 'depth',
                'the causal path reached the depth limit',
                'Increase depth_limit only when the workload needs it.')));
    END IF;

    SELECT f.fact, f.support_count, f.first_frontier, f.last_frontier
    INTO fact_row
    FROM pgreact_internal.derived_facts f
    WHERE f.relation_version_id = m41_derived_fragment.relation_version_id
      AND f.semantic_key = m41_derived_fragment.subject_key;
    fact_identity := 'derived_fact:' || relation_identity || ':subject=' || subject_key;
    IF NOT FOUND THEN
        boundary_id := 'boundary:missing:' || pgreact_internal.m41_digest(
            jsonb_build_object('parent', COALESCE(parent_id, relation_identity), 'subject_key', subject_key));
        boundaries := jsonb_build_array(jsonb_build_object('kind', 'missing', 'identity', boundary_id));
        IF parent_id IS NULL THEN
            path_nodes := jsonb_build_array(boundary_id);
        ELSE
            path_nodes := jsonb_build_array(parent_id, boundary_id);
            child_edge := pgreact_internal.m41_edge('derived_fact', parent_id, boundary_id);
            edges := jsonb_build_array(child_edge);
            path_edges := jsonb_build_array(child_edge ->> 'identity');
        END IF;
        RETURN jsonb_build_object('state', 'partial', 'nodes', nodes, 'edges', edges,
            'paths', jsonb_build_array(pgreact_internal.m41_path(
                path_nodes, COALESCE(path_edges, '[]'::jsonb), 'partial')),
            'boundaries', boundaries,
            'findings', jsonb_build_array(pgreact_internal.m41_finding(
                'M41_EVIDENCE_MISSING', 'WARNING', relation_row.relation_name, 'fact',
                'the derived fact is not retained at the sampled frontier',
                'Reconcile or restore the derived evidence before retrying.')));
    END IF;
    nodes := jsonb_build_array(jsonb_build_object(
        'kind', 'derived_fact', 'identity', fact_identity,
        'evidence', jsonb_build_object(
            'relation', relation_row.relation_name, 'version', relation_row.version,
            'subject_key', subject_key, 'fact', fact_row.fact,
            'support_count', fact_row.support_count,
            'first_frontier', fact_row.first_frontier, 'last_frontier', fact_row.last_frontier)));
    IF parent_id IS NULL THEN
        path_nodes := jsonb_build_array(fact_identity);
        path_edges := '[]'::jsonb;
    ELSE
        child_edge := pgreact_internal.m41_edge('derived_predecessor', parent_id, fact_identity);
        edges := edges || jsonb_build_array(child_edge);
        path_nodes := jsonb_build_array(parent_id, fact_identity);
        path_edges := jsonb_build_array(child_edge ->> 'identity');
    END IF;

    SELECT count(*) INTO support_count
    FROM pgreact_internal.derived_supports support
    WHERE support.relation_version_id = m41_derived_fragment.relation_version_id
      AND support.semantic_key = m41_derived_fragment.subject_key AND support.active;
    IF support_count = 0 THEN
        boundary_id := 'boundary:missing:support:' || pgreact_internal.m41_digest(
            jsonb_build_object('relation', relation_identity, 'subject_key', subject_key));
        boundaries := boundaries || jsonb_build_array(jsonb_build_object(
            'kind', 'missing', 'identity', boundary_id));
        child_edge := pgreact_internal.m41_edge('derived_support', fact_identity, boundary_id);
        edges := edges || jsonb_build_array(child_edge);
        paths := paths || jsonb_build_array(pgreact_internal.m41_path(
            path_nodes || jsonb_build_array(boundary_id),
            path_edges || jsonb_build_array(child_edge ->> 'identity'), 'partial'));
        RETURN jsonb_build_object('state', 'partial', 'nodes', nodes, 'edges', edges,
            'paths', paths, 'boundaries', boundaries,
            'findings', jsonb_build_array(pgreact_internal.m41_finding(
                'M41_EVIDENCE_MISSING', 'WARNING', relation_row.relation_name, 'support',
                'the derived fact has no active modeled support',
                'Reconcile the derived relation before retrying.')));
    END IF;
    IF support_count > fanout_limit THEN
        state := 'partial';
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            'M41_RESOURCE_LIMIT', 'WARNING', relation_row.relation_name, 'fanout',
            'the causal path reached the support fan-out limit',
            'Increase fanout_limit only for a bounded workload.'));
    END IF;
    FOR support_row IN
        SELECT support.rule_version_id, support.activation_id, support.semantic_key AS source_key,
               support.activation_generation, support.activation_revision,
               support.source_binding, rule.rule_name, derivation.version AS rule_version
        FROM pgreact_internal.derived_supports support
        JOIN pgreact_internal.derivation_rule_versions derivation
          ON derivation.rule_version_id = support.rule_version_id
        JOIN pgreact_internal.rules rule ON rule.rule_id = derivation.rule_id
        WHERE support.relation_version_id = m41_derived_fragment.relation_version_id
          AND support.semantic_key = m41_derived_fragment.subject_key AND support.active
        ORDER BY rule.rule_name, derivation.version,
                 support.activation_generation, support.activation_revision
        LIMIT fanout_limit
    LOOP
        support_number := support_number + 1;
        support_identity := format('derived_support:%s:subject=%s:rule=%s@%s:generation=%s:revision=%s:ordinal=%s',
            relation_identity, subject_key, support_row.rule_name, support_row.rule_version,
            support_row.activation_generation, support_row.activation_revision, support_number);
        nodes := nodes || jsonb_build_array(jsonb_build_object(
            'kind', 'derived_support', 'identity', support_identity,
            'evidence', jsonb_build_object(
                'relation', relation_row.relation_name, 'version', relation_row.version,
                'subject_key', subject_key, 'rule', support_row.rule_name,
                'rule_version', support_row.rule_version,
                'generation', support_row.activation_generation,
                'revision', support_row.activation_revision,
                'source_binding', support_row.source_binding)));
        support_edge := pgreact_internal.m41_edge('derived_support', fact_identity, support_identity);
        edges := edges || jsonb_build_array(support_edge);
        SELECT count(*) INTO input_count
        FROM pgreact_internal.derived_support_inputs input
        WHERE input.support_id = (
            SELECT support_id FROM pgreact_internal.derived_supports candidate
            WHERE candidate.relation_version_id = m41_derived_fragment.relation_version_id
              AND candidate.semantic_key = m41_derived_fragment.subject_key
              AND candidate.rule_version_id = support_row.rule_version_id
              AND candidate.activation_id = support_row.activation_id
              AND candidate.activation_generation = support_row.activation_generation
              AND candidate.activation_revision = support_row.activation_revision
            LIMIT 1);
        IF input_count = 0 THEN
            source_fragment := pgreact_internal.m41_rule_source_fragment(
                support_row.rule_version_id, support_row.source_key,
                NULL, support_row.activation_id, support_row.activation_generation,
                support_row.activation_revision);
            nodes := pgreact_internal.m41_array_union(nodes, source_fragment -> 'nodes');
            edges := pgreact_internal.m41_array_union(edges, source_fragment -> 'edges');
            boundaries := pgreact_internal.m41_array_union(boundaries, source_fragment -> 'boundaries');
            findings := pgreact_internal.m41_array_union(findings, source_fragment -> 'findings');
            IF source_fragment -> 'paths' IS NOT NULL
               AND jsonb_array_length(source_fragment -> 'paths') > 0 THEN
                FOR child_path IN SELECT value FROM jsonb_array_elements(source_fragment -> 'paths') item(value) LOOP
                    child_edge := pgreact_internal.m41_edge(
                        'support_rule', support_identity,
                        child_path -> 'nodes' ->> 0);
                    edges := edges || jsonb_build_array(child_edge);
                    combined_nodes := path_nodes || jsonb_build_array(support_identity) || child_path -> 'nodes';
                    combined_edges := path_edges || jsonb_build_array(support_edge ->> 'identity')
                        || jsonb_build_array(child_edge ->> 'identity') || child_path -> 'edges';
                    paths := paths || jsonb_build_array(pgreact_internal.m41_path(
                        combined_nodes, combined_edges,
                        CASE WHEN source_fragment ->> 'state' = 'complete' THEN state ELSE source_fragment ->> 'state' END));
                END LOOP;
            END IF;
        ELSE
            FOR input_row IN
                SELECT input.relation_version_id, input.semantic_key,
                       relation.relation_name, version.version
                FROM pgreact_internal.derived_support_inputs input
                JOIN pgreact_internal.derived_relation_versions version
                  ON version.relation_version_id = input.relation_version_id
                JOIN pgreact_internal.derived_relations relation USING (relation_id)
                WHERE input.support_id = (
                    SELECT support_id FROM pgreact_internal.derived_supports candidate
                    WHERE candidate.relation_version_id = m41_derived_fragment.relation_version_id
                      AND candidate.semantic_key = m41_derived_fragment.subject_key
                      AND candidate.rule_version_id = support_row.rule_version_id
                      AND candidate.activation_id = support_row.activation_id
                      AND candidate.activation_generation = support_row.activation_generation
                      AND candidate.activation_revision = support_row.activation_revision
                    LIMIT 1)
                ORDER BY input.input_order
            LOOP
                child := pgreact_internal.m41_derived_fragment(
                    input_row.relation_version_id, input_row.semantic_key, NULL,
                    depth + 1, depth_limit, fanout_limit, path_limit,
                    visited || relation_identity);
                nodes := pgreact_internal.m41_array_union(nodes, child -> 'nodes');
                edges := pgreact_internal.m41_array_union(edges, child -> 'edges');
                boundaries := pgreact_internal.m41_array_union(boundaries, child -> 'boundaries');
                findings := pgreact_internal.m41_array_union(findings, child -> 'findings');
                IF child ->> 'state' = 'unavailable' THEN state := 'unavailable';
                ELSIF child ->> 'state' = 'partial' AND state = 'complete' THEN state := 'partial'; END IF;
                FOR child_path IN SELECT value FROM jsonb_array_elements(child -> 'paths') item(value) LOOP
                    child_edge := pgreact_internal.m41_edge(
                        'support_input', support_identity, child_path -> 'nodes' ->> 0,
                        jsonb_build_object('input_relation', input_row.relation_name,
                                           'input_version', input_row.version));
                    edges := edges || jsonb_build_array(child_edge);
                    combined_nodes := path_nodes || jsonb_build_array(support_identity) || child_path -> 'nodes';
                    combined_edges := path_edges || jsonb_build_array(support_edge ->> 'identity')
                        || jsonb_build_array(child_edge ->> 'identity') || child_path -> 'edges';
                    paths := paths || jsonb_build_array(pgreact_internal.m41_path(
                        combined_nodes, combined_edges,
                        CASE WHEN child ->> 'state' = 'complete' THEN state ELSE child ->> 'state' END));
                END LOOP;
            END LOOP;
        END IF;
    END LOOP;
    paths := pgreact_internal.m41_array_union(paths, '[]'::jsonb);
    IF jsonb_array_length(paths) > path_limit THEN
        SELECT COALESCE(jsonb_agg(value ORDER BY ordinal) FILTER (WHERE ordinal <= path_limit), '[]'::jsonb)
        INTO paths FROM jsonb_array_elements(paths) WITH ORDINALITY item(value, ordinal);
        state := 'partial';
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            'M41_RESOURCE_LIMIT', 'WARNING', relation_row.relation_name, 'paths',
            'the causal path reached the returned-path limit',
            'Increase path_limit only for a bounded workload.'));
    END IF;
    RETURN jsonb_build_object('state', state, 'nodes', nodes, 'edges', edges,
                              'paths', paths, 'boundaries', boundaries,
                              'findings', findings);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m41_explain(target_name text, subject jsonb, options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
<<m41_explain_block>>
DECLARE
    started_at timestamptz := clock_timestamp();
    sampled_time timestamptz := statement_timestamp();
    authoritative_frontier timestamptz;
    cp jsonb;
    root_kind text;
    result_key text;
    work_id text;
    event_kind text;
    consequence_identity text;
    target_kind text;
    target_version text;
    target_count bigint;
    explain_subject_key bigint;
    result_key_numeric bigint;
    generation bigint;
    explain_revision bigint;
    limit_text text;
    option_name text;
    unknown_option text;
    node_limit integer := 256;
    edge_limit integer := 512;
    path_limit integer := 64;
    depth_limit integer := 16;
    fanout_limit integer := 64;
    payload_limit integer := 65536;
    root jsonb;
    root_id text;
    fragment jsonb;
    edge jsonb;
    nodes jsonb := '[]'::jsonb;
    edges jsonb := '[]'::jsonb;
    paths jsonb := '[]'::jsonb;
    boundaries jsonb := '[]'::jsonb;
    findings jsonb := '[]'::jsonb;
    state text := 'complete';
    limits jsonb;
    declaration_digest text;
    semantic_digest text;
    source_digest text;
    decision_row record;
    work_row record;
    event_row record;
    activation_row record;
    root_request jsonb;
    policy_limit integer;
BEGIN
    SELECT frontier INTO authoritative_frontier
    FROM pgreact_internal.clock_frontier WHERE singleton;
    cp := options -> 'causal_path';
    limits := jsonb_build_object(
        'node_limit', node_limit, 'edge_limit', edge_limit, 'path_limit', path_limit,
        'depth_limit', depth_limit, 'fanout_limit', fanout_limit,
        'payload_limit', payload_limit);
    IF jsonb_typeof(options) IS DISTINCT FROM 'object'
       OR jsonb_typeof(cp) IS DISTINCT FROM 'object' THEN
        RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
            cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
            jsonb_build_array(pgreact_internal.m41_finding(
                'M41_OPTIONS_INVALID', 'ERROR', COALESCE(target_name, '<unknown>'),
                'options.causal_path', 'causal_path must be an object',
                'Pass a root_kind and its public identity fields.')),
            limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
    END IF;
    SELECT key INTO unknown_option
    FROM jsonb_object_keys(cp) key
    WHERE key <> ALL (ARRAY[
        'root_kind', 'result_key', 'work_id', 'generation', 'revision',
        'consequence_identity', 'event_kind', 'node_limit', 'edge_limit',
        'path_limit', 'depth_limit', 'fanout_limit', 'payload_limit'])
    ORDER BY key LIMIT 1;
    IF unknown_option IS NOT NULL THEN
        RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
            cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
            jsonb_build_array(pgreact_internal.m41_finding(
                'M41_OPTIONS_INVALID', 'ERROR', COALESCE(target_name, '<unknown>'),
                'options.causal_path.' || unknown_option, 'causal_path contains an unknown field',
                'Use only fields listed in the M41 causal-path contract.')),
            limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
    END IF;
    FOREACH option_name IN ARRAY ARRAY['node_limit', 'edge_limit', 'path_limit',
                                      'depth_limit', 'fanout_limit', 'payload_limit'] LOOP
        IF cp ? option_name THEN
            limit_text := cp ->> option_name;
            IF jsonb_typeof(cp -> option_name) <> 'number'
               OR limit_text !~ '^[1-9][0-9]*$'
               OR length(limit_text) > 6 THEN
                RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
                    cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
                    jsonb_build_array(pgreact_internal.m41_finding(
                        'M41_OPTIONS_INVALID', 'ERROR', COALESCE(target_name, '<unknown>'),
                        'options.causal_path.' || option_name,
                        'causal-path limits must be positive bounded integers',
                        'Use positive values within the published M41 limits.')),
                    limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
            END IF;
            IF option_name = 'node_limit' THEN node_limit := limit_text::integer;
            ELSIF option_name = 'edge_limit' THEN edge_limit := limit_text::integer;
            ELSIF option_name = 'path_limit' THEN path_limit := limit_text::integer;
            ELSIF option_name = 'depth_limit' THEN depth_limit := limit_text::integer;
            ELSIF option_name = 'fanout_limit' THEN fanout_limit := limit_text::integer;
            ELSE payload_limit := limit_text::integer; END IF;
        END IF;
    END LOOP;
    limits := jsonb_build_object(
        'node_limit', node_limit, 'edge_limit', edge_limit, 'path_limit', path_limit,
        'depth_limit', depth_limit, 'fanout_limit', fanout_limit,
        'payload_limit', payload_limit);
    root_kind := cp ->> 'root_kind';
    IF root_kind NOT IN ('decision_result', 'rule_work', 'decision_work') THEN
        RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
            cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
            jsonb_build_array(pgreact_internal.m41_finding(
                'M41_UNSUPPORTED_ROOT', 'WARNING', COALESCE(target_name, '<unknown>'),
                'options.causal_path.root_kind', 'this root kind is outside the bounded adapter',
                'Use decision_result, rule_work, or decision_work.')),
            limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
    END IF;
    IF root_kind = 'decision_result' THEN
        result_key := cp ->> 'result_key';
        IF result_key IS NULL OR result_key = '' THEN
            RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
                cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
                jsonb_build_array(pgreact_internal.m41_finding(
                    'M41_ROOT_INVALID', 'ERROR', target_name, 'options.causal_path.result_key',
                    'a decision-result root requires one result key',
                    'Pass the public candidate key as result_key.')),
                limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
        END IF;
        result_key_numeric := pgreact_internal.m40_subject_key(to_jsonb(result_key));
        IF result_key_numeric IS NULL THEN
            RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
                cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
                jsonb_build_array(pgreact_internal.m41_finding(
                    'M41_ROOT_INVALID', 'ERROR', target_name, 'options.causal_path.result_key',
                    'result_key must be a bigint public candidate key',
                    'Pass a decimal candidate key.')),
                limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
        END IF;
    ELSE
        work_id := cp ->> 'work_id';
        IF work_id IS NULL OR work_id = '' OR cp ->> 'generation' IS NULL THEN
            RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
                cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
                jsonb_build_array(pgreact_internal.m41_finding(
                    'M41_ROOT_INVALID', 'ERROR', target_name, 'options.causal_path',
                    'work roots require work_id and generation',
                    'Use the public work identity and retained generation.')),
                limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
        END IF;
        IF work_id !~ '^-?[0-9]+$' THEN
            RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
                cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
                jsonb_build_array(pgreact_internal.m41_finding(
                    'M41_ROOT_INVALID', 'ERROR', target_name, 'options.causal_path.work_id',
                    'work_id must be the public decimal work identity',
                    'Pass the work_id returned by pgreact.work.')),
                limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
        END IF;
        IF cp ->> 'generation' !~ '^[0-9]+$'
           OR (root_kind = 'decision_work' AND (cp ->> 'revision') !~ '^[0-9]+$')
           OR (root_kind = 'rule_work' AND (cp ? 'revision')
               AND (cp ->> 'revision') !~ '^[0-9]+$') THEN
            RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
                cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
                jsonb_build_array(pgreact_internal.m41_finding(
                    'M41_ROOT_INVALID', 'ERROR', target_name, 'options.causal_path.generation',
                    'generation and revision must be non-negative integers',
                    'Use the generation and revision from public evidence.')),
                limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
        END IF;
        generation := (cp ->> 'generation')::bigint;
        IF cp ? 'revision' THEN explain_revision := (cp ->> 'revision')::bigint; END IF;
        event_kind := cp ->> 'event_kind';
        IF root_kind = 'rule_work' AND event_kind NOT IN ('ACTIVATE', 'DEACTIVATE') THEN
            RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
                cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
                jsonb_build_array(pgreact_internal.m41_finding(
                    'M41_ROOT_INVALID', 'ERROR', target_name, 'options.causal_path.event_kind',
                    'rule work requires ACTIVATE or DEACTIVATE event_kind',
                    'Use the lifecycle event kind attached to the work item.')),
                limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
        END IF;
    END IF;
    explain_subject_key := pgreact_internal.m40_subject_key(subject);
    IF explain_subject_key IS NULL THEN
        RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
            cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
            jsonb_build_array(pgreact_internal.m41_finding(
                'M41_SUBJECT_INVALID', 'ERROR', COALESCE(target_name, '<unknown>'), 'subject',
                'causal-path adapters require one bigint business subject key',
                'Pass a JSON number or {"key": number}.')),
            limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
    END IF;

    SELECT count(*) INTO target_count
    FROM (
        SELECT declaration.kind, declaration.object_name
        FROM pgreact_internal.api_declarations declaration
        WHERE declaration.state = 'DEPLOYED'
        UNION
        SELECT 'policy_set', set.set_name
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE version.state = 'DEPLOYED'
        UNION
        SELECT 'derived_relation', relation.relation_name
        FROM pgreact_internal.derived_relations relation
        JOIN pgreact_internal.derived_relation_versions version USING (relation_id)
        WHERE version.state = 'ACTIVE'
    ) targets WHERE object_name = target_name;
    IF target_count = 0 THEN
        RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
            cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
            jsonb_build_array(pgreact_internal.m41_finding(
                'M41_TARGET_NOT_FOUND', 'ERROR', COALESCE(target_name, '<unknown>'), 'target',
                'no deployed target with this public name exists',
                'Use the stable name of a deployed decision or rule.')),
            limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
    ELSIF target_count > 1 THEN
        RETURN pgreact_internal.m41_result(NULL, target_name, NULL, 'unsupported', subject,
            cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
            jsonb_build_array(pgreact_internal.m41_finding(
                'M41_TARGET_AMBIGUOUS', 'ERROR', target_name, 'target',
                'more than one deployed target has this public name',
                'Use a unique public target name.')),
            limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
    END IF;
    SELECT kind INTO target_kind
    FROM (
        SELECT declaration.kind, declaration.object_name
        FROM pgreact_internal.api_declarations declaration
        WHERE declaration.state = 'DEPLOYED'
        UNION
        SELECT 'policy_set', set.set_name
        FROM pgreact_internal.policy_set_versions version
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE version.state = 'DEPLOYED'
        UNION
        SELECT 'derived_relation', relation.relation_name
        FROM pgreact_internal.derived_relations relation
        JOIN pgreact_internal.derived_relation_versions version USING (relation_id)
        WHERE version.state = 'ACTIVE'
    ) targets WHERE object_name = target_name LIMIT 1;
    IF (root_kind = 'decision_result' AND target_kind <> 'decision_program')
       OR (root_kind = 'decision_work' AND target_kind <> 'decision_program')
       OR (root_kind = 'rule_work' AND target_kind <> 'rule') THEN
        RETURN pgreact_internal.m41_result(target_kind, target_name, NULL, 'unsupported', subject,
            cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
            jsonb_build_array(pgreact_internal.m41_finding(
                'M41_UNSUPPORTED_ROOT', 'WARNING', target_name, 'root_kind',
                'the requested root kind does not match the deployed target kind',
                'Use decision roots for decisions and rule work roots for rules.')),
            limits, pgreact_internal.m41_cost(started_at, 0, 0, 0, 0, 0, 0, 0, 0), '{}');
    END IF;

    IF root_kind = 'decision_result' AND NOT EXISTS (
        SELECT 1
        FROM pgreact_internal.decision_programs program
        JOIN pgreact_internal.decision_program_versions version USING (program_id)
        JOIN pgreact_internal.decision_subject_state decision USING (program_id)
        WHERE program.program_name = target_name
          AND version.state = 'DEPLOYED'
          AND decision.subject_key = explain_subject_key
          AND decision.state = 'WINNER'
          AND decision.winner_candidate = result_key_numeric
    ) THEN
        RETURN pgreact_internal.m41_result(target_kind, target_name, NULL, 'unavailable', subject,
            cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
            jsonb_build_array(pgreact_internal.m41_finding(
                'M41_ROOT_NOT_FOUND', 'WARNING', target_name, 'result_key',
                'the requested decision result is absent or no longer authoritative',
                'Use a current public decision result identity.')),
            limits, pgreact_internal.m41_cost(started_at, 1, 0, 0, 0, 0, 0, 0, 1), '{}');
    END IF;

    IF root_kind = 'decision_result' THEN
        fragment := pgreact_internal.m41_decision_fragment(
            target_name, explain_subject_key, result_key_numeric, NULL, sampled_time,
            depth_limit, fanout_limit, path_limit);
        SELECT version_no::text, encode(source_definition_digest, 'hex')
        INTO target_version, source_digest
        FROM pgreact_internal.decision_programs program
        JOIN pgreact_internal.decision_program_versions version USING (program_id)
        WHERE program.program_name = target_name AND version.state = 'DEPLOYED'
        ORDER BY version.valid_from DESC, version.version_no DESC LIMIT 1;
        root_id := format('decision_result:%s@%s:subject=%s:candidate=%s',
                          target_name, target_version, explain_subject_key, result_key_numeric);
        root := jsonb_build_object('kind', root_kind, 'identity', root_id,
            'target', target_name, 'version', target_version,
            'subject_key', explain_subject_key, 'result_key', result_key_numeric);
    ELSIF root_kind = 'decision_work' THEN
        SELECT work.*, state.version_id, state.generation, state.revision, state.winner_candidate,
               state.winner_result, state.state AS decision_state, version.version_no
        INTO work_row
        FROM pgreact_internal.decision_work work
        JOIN pgreact_internal.decision_programs program USING (program_id)
        JOIN pgreact_internal.decision_subject_state state
          USING (program_id, subject_key)
        JOIN pgreact_internal.decision_program_versions version
          ON version.version_id = state.version_id
        WHERE program.program_name = target_name
          AND work.subject_key = work_id::bigint;
        IF NOT FOUND OR work_row.generation <> generation
           OR work_row.revision <> explain_revision THEN
            RETURN pgreact_internal.m41_result(target_kind, target_name, NULL, 'unavailable', subject,
                cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
                jsonb_build_array(pgreact_internal.m41_finding(
                    'M41_ROOT_NOT_FOUND', 'WARNING', target_name, 'work_id',
                    'the requested decision work identity is not retained',
                    'Use work_id, generation, and revision from pgreact.work evidence.')),
                limits, pgreact_internal.m41_cost(started_at, 1, 0, 0, 0, 0, 0, 0, 1), '{}');
        END IF;
        target_version := work_row.version_no::text;
        root_id := format('decision_work:%s@%s:subject=%s:generation=%s:revision=%s',
                          target_name, target_version, work_row.subject_key,
                          generation, explain_revision);
        root := jsonb_build_object('kind', root_kind, 'identity', root_id,
            'target', target_name, 'version', target_version,
            'subject_key', work_row.subject_key, 'work_id', work_id,
            'generation', generation, 'revision', explain_revision);
        nodes := jsonb_build_array(jsonb_build_object(
            'kind', 'decision_work', 'identity', root_id,
            'evidence', jsonb_build_object('state', work_row.state,
                'claimable', work_row.claimable, 'updated_at', work_row.updated_at,
                'subject_key', work_row.subject_key, 'generation', generation,
                'revision', explain_revision)));
        IF work_row.decision_state = 'WINNER' THEN
            fragment := pgreact_internal.m41_decision_fragment(
                target_name, work_row.subject_key, work_row.winner_candidate,
                root_id, sampled_time, depth_limit, fanout_limit, path_limit);
        ELSE
            fragment := jsonb_build_object('state', 'complete', 'nodes', '[]'::jsonb,
                'edges', '[]'::jsonb,
                'paths', jsonb_build_array(pgreact_internal.m41_path(
                    jsonb_build_array(root_id), '[]'::jsonb, 'complete')),
                'boundaries', '[]'::jsonb,
                'findings', '[]'::jsonb);
        END IF;
        SELECT version_no::text, encode(source_definition_digest, 'hex')
        INTO target_version, source_digest
        FROM pgreact_internal.decision_program_versions
        WHERE version_id = work_row.version_id;
    ELSE
        SELECT episode.episode_id, episode.rule_id, episode.rule_version_id,
               episode.activation_id, episode.activation_generation, episode.activation_revision,
               episode.state, event.event_kind, event.generation,
               event.transitioned_at, event.old_bindings, event.new_bindings,
               version.consequence_identity, version.source_definition_digest,
               rule.rule_name, version.source_view_name
        INTO work_row
        FROM pgreact_internal.agenda episode
        JOIN pgreact_internal.lifecycle_events event ON event.event_id = episode.event_id
        JOIN pgreact_internal.rule_versions version
          ON version.rule_version_id = episode.rule_version_id
        JOIN pgreact_internal.rules rule ON rule.rule_id = episode.rule_id
        WHERE rule.rule_name = target_name AND episode.episode_id::text = work_id;
        IF NOT FOUND OR work_row.generation <> generation OR work_row.event_kind <> event_kind
           OR (explain_revision IS NOT NULL AND NOT EXISTS (
               SELECT 1 FROM pgreact_internal.activation_state activation
               WHERE activation.rule_version_id = work_row.rule_version_id
                 AND activation.activation_id = work_row.activation_id
                 AND activation.revision = explain_revision)) THEN
            RETURN pgreact_internal.m41_result(target_kind, target_name, NULL, 'unavailable', subject,
                cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
                jsonb_build_array(pgreact_internal.m41_finding(
                    'M41_ROOT_NOT_FOUND', 'WARNING', target_name, 'work_id',
                    'the requested rule work identity is not retained',
                    'Use work_id, generation, event_kind, and revision from public evidence.')),
                limits, pgreact_internal.m41_cost(started_at, 1, 0, 0, 0, 0, 0, 0, 1), '{}');
        END IF;
        target_version := '1';
        IF cp ? 'consequence_identity'
           AND cp ->> 'consequence_identity' IS DISTINCT FROM work_row.consequence_identity THEN
            RETURN pgreact_internal.m41_result(target_kind, target_name, target_version, 'unavailable', subject,
                cp, sampled_time, authoritative_frontier, NULL, nodes, edges, paths, boundaries,
                jsonb_build_array(pgreact_internal.m41_finding(
                    'M41_CHANGED_STATE', 'WARNING', target_name, 'consequence_identity',
                    'the requested consequence does not match the retained work',
                    'Retry with the public consequence identity.')),
                limits, pgreact_internal.m41_cost(started_at, 1, 0, 0, 0, 0, 0, 0, 1), '{}');
        END IF;
        SELECT a.revision INTO explain_revision
        FROM pgreact_internal.activation_state a
        WHERE a.rule_version_id = work_row.rule_version_id
          AND a.activation_id = work_row.activation_id
        ORDER BY a.revision DESC LIMIT 1;
        root_id := format('rule_work:%s@1:subject=%s:work_id=%s:generation=%s:revision=%s:event=%s',
                          target_name, explain_subject_key, work_id, generation, explain_revision, event_kind);
        root := jsonb_build_object('kind', root_kind, 'identity', root_id,
            'target', target_name, 'version', target_version,
            'subject_key', explain_subject_key, 'work_id', work_id,
            'generation', generation, 'revision', explain_revision,
            'consequence_identity', work_row.consequence_identity,
            'event_kind', event_kind);
        nodes := jsonb_build_array(
            jsonb_build_object('kind', 'rule_work', 'identity', root_id,
                'evidence', jsonb_build_object('work_id', work_id, 'state', work_row.state,
                    'generation', generation, 'revision', explain_revision)),
            jsonb_build_object('kind', 'lifecycle_event',
                'identity', format('lifecycle:%s@1:subject=%s:generation=%s:event=%s',
                    target_name, explain_subject_key, generation, event_kind),
                'evidence', jsonb_build_object('event_kind', event_kind,
                    'transitioned_at', work_row.transitioned_at,
                    'old_bindings', work_row.old_bindings, 'new_bindings', work_row.new_bindings)));
        root_id := root ->> 'identity';
        edge := pgreact_internal.m41_edge('work_lifecycle', root_id,
            nodes -> 1 ->> 'identity');
        edges := jsonb_build_array(edge);
        fragment := pgreact_internal.m41_rule_source_fragment(
            work_row.rule_version_id, explain_subject_key, nodes -> 1 ->> 'identity',
            work_row.activation_id, generation, explain_revision);
    END IF;
    nodes := pgreact_internal.m41_array_union(nodes, fragment -> 'nodes');
    edges := pgreact_internal.m41_array_union(edges, fragment -> 'edges');
    paths := pgreact_internal.m41_array_union(paths, fragment -> 'paths');
    boundaries := pgreact_internal.m41_array_union(boundaries, fragment -> 'boundaries');
    findings := pgreact_internal.m41_array_union(findings, fragment -> 'findings');
    state := fragment ->> 'state';
    IF jsonb_array_length(nodes) > node_limit THEN
        SELECT COALESCE(jsonb_agg(value ORDER BY ordinal) FILTER (WHERE ordinal <= node_limit), '[]'::jsonb)
        INTO nodes FROM jsonb_array_elements(nodes) WITH ORDINALITY item(value, ordinal);
        state := 'partial';
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            'M41_RESOURCE_LIMIT', 'WARNING', target_name, 'nodes',
            'the causal path reached the node limit', 'Increase node_limit only for a bounded workload.'));
    END IF;
    IF jsonb_array_length(edges) > edge_limit THEN
        SELECT COALESCE(jsonb_agg(value ORDER BY ordinal) FILTER (WHERE ordinal <= edge_limit), '[]'::jsonb)
        INTO edges FROM jsonb_array_elements(edges) WITH ORDINALITY item(value, ordinal);
        state := 'partial';
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            'M41_RESOURCE_LIMIT', 'WARNING', target_name, 'edges',
            'the causal path reached the edge limit', 'Increase edge_limit only for a bounded workload.'));
    END IF;
    IF jsonb_array_length(paths) > path_limit THEN
        SELECT COALESCE(jsonb_agg(value ORDER BY ordinal) FILTER (WHERE ordinal <= path_limit), '[]'::jsonb)
        INTO paths FROM jsonb_array_elements(paths) WITH ORDINALITY item(value, ordinal);
        state := 'partial';
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            'M41_RESOURCE_LIMIT', 'WARNING', target_name, 'paths',
            'the causal path reached the returned-path limit', 'Increase path_limit only for a bounded workload.'));
    END IF;
    nodes := pgreact_internal.m41_array_union(nodes, '[]'::jsonb);
    edges := pgreact_internal.m41_array_union(edges, '[]'::jsonb);
    paths := pgreact_internal.m41_array_union(paths, '[]'::jsonb);
    boundaries := pgreact_internal.m41_array_union(boundaries, '[]'::jsonb);
    findings := pgreact_internal.m41_array_union(findings, '[]'::jsonb);
    SELECT encode(declaration.declaration_digest, 'hex')
    INTO declaration_digest
    FROM pgreact_internal.api_declarations declaration
    WHERE declaration.object_name = target_name AND declaration.state = 'DEPLOYED'
    ORDER BY declaration.created_at DESC LIMIT 1;
    semantic_digest := pgreact_internal.m41_digest(jsonb_build_object(
        'root', root, 'nodes', nodes, 'edges', edges, 'paths', paths,
        'boundaries', boundaries, 'findings', findings, 'limits', limits));
    RETURN pgreact_internal.m41_result(
        target_kind, target_name, target_version, state, subject, cp, sampled_time,
        authoritative_frontier, root, nodes, edges, paths, boundaries, findings, limits,
        pgreact_internal.m41_cost(started_at, 1, jsonb_array_length(nodes),
            jsonb_array_length(edges), jsonb_array_length(paths),
            (SELECT count(*) FROM jsonb_array_elements(nodes) item WHERE item.value ->> 'kind' = 'derived_support'),
            depth_limit, fanout_limit, jsonb_array_length(boundaries)),
        jsonb_build_object('semantic', semantic_digest,
            'declaration', COALESCE(declaration_digest, source_digest),
            'source_definition', source_digest,
            'authoritative_frontier', authoritative_frontier));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m41_policy_fragment(policy_set_version_id uuid, subject_key bigint, parent_id text, sampled_time timestamp with time zone, depth_limit integer, fanout_limit integer, path_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    policy_row record;
    member_row record;
    source jsonb;
    child jsonb;
    policy_id text;
    applicability_id text;
    source_id text;
    boundary_id text;
    edge jsonb;
    path_nodes jsonb;
    path_edges jsonb := '[]'::jsonb;
    nodes jsonb := '[]'::jsonb;
    edges jsonb := '[]'::jsonb;
    paths jsonb := '[]'::jsonb;
    boundaries jsonb := '[]'::jsonb;
    findings jsonb := '[]'::jsonb;
    state text := 'complete';
    policy_target pgreact_api.target;
BEGIN
    SELECT set.set_name, version.version, version.applicability_kind,
           version.applicability_source, version.applicability_source_oid,
           version.subject_key, version.subject_type, version.valid_from, version.valid_to,
           version.complete_frontier, version.policy_set_id
    INTO policy_row
    FROM pgreact_internal.policy_set_versions version
    JOIN pgreact_internal.policy_sets set USING (policy_set_id)
    WHERE version.policy_set_version_id = m41_policy_fragment.policy_set_version_id;
    IF NOT FOUND THEN
        boundary_id := 'boundary:missing:policy-set';
        edge := pgreact_internal.m41_edge('policy_predecessor', parent_id, boundary_id);
        RETURN jsonb_build_object('state', 'unavailable', 'nodes', '[]'::jsonb,
            'edges', jsonb_build_array(edge), 'paths', jsonb_build_array(
                pgreact_internal.m41_path(jsonb_build_array(parent_id, boundary_id),
                                           jsonb_build_array(edge ->> 'identity'), 'unavailable')),
            'boundaries', jsonb_build_array(jsonb_build_object('kind', 'missing', 'identity', boundary_id)),
            'findings', jsonb_build_array(pgreact_internal.m41_finding(
                'M41_EVIDENCE_MISSING', 'WARNING', '<unknown>', 'policy_set',
                'the policy-set version is no longer available',
                'Restore the policy-set evidence before retrying.')));
    END IF;
    policy_id := format('policy_set:%s@%s:subject=%s', policy_row.set_name,
                        policy_row.version, subject_key);
    applicability_id := policy_id || ':applicability';
    nodes := jsonb_build_array(
        jsonb_build_object('kind', 'policy_set', 'identity', policy_id,
            'evidence', jsonb_build_object(
                'name', policy_row.set_name, 'version', policy_row.version,
                'valid_from', policy_row.valid_from, 'valid_to', policy_row.valid_to)),
        jsonb_build_object('kind', 'policy_applicability', 'identity', applicability_id,
            'evidence', jsonb_build_object(
                'source', policy_row.applicability_source,
                'subject_key', subject_key, 'sampled_time', sampled_time)));
    edge := pgreact_internal.m41_edge('policy_applicability', parent_id, policy_id);
    edges := edges || jsonb_build_array(edge);
    edge := pgreact_internal.m41_edge('policy_evaluation', policy_id, applicability_id);
    edges := edges || jsonb_build_array(edge);
    path_nodes := jsonb_build_array(parent_id, policy_id, applicability_id);
    path_edges := jsonb_build_array(edges -> 0 ->> 'identity', edges -> 1 ->> 'identity');

    policy_target := pgreact_api.target('policy_set', policy_row.set_name, policy_row.version);
    IF sampled_time < policy_row.valid_from
       OR (policy_row.valid_to IS NOT NULL AND sampled_time >= policy_row.valid_to) THEN
        state := 'partial';
        boundary_id := 'boundary:inactive_time:' || pgreact_internal.m41_digest(
            jsonb_build_object('policy', policy_id));
        boundaries := boundaries || jsonb_build_array(jsonb_build_object(
            'kind', 'inactive_time', 'identity', boundary_id));
        edge := pgreact_internal.m41_edge('policy_time', applicability_id, boundary_id);
        edges := edges || jsonb_build_array(edge);
        paths := paths || jsonb_build_array(pgreact_internal.m41_path(
            path_nodes || jsonb_build_array(boundary_id),
            path_edges || jsonb_build_array(edge ->> 'identity'), 'partial'));
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            'M41_STALE_FRONTIER', 'WARNING', policy_row.set_name, 'validity',
            'the policy applicability interval is inactive at the sampled time',
            'Use the policy version active at the requested evaluation point.'));
    ELSIF policy_row.applicability_kind <> 'relation'
          OR policy_row.subject_type::text NOT IN ('bigint', 'integer', 'smallint') THEN
        state := 'unsupported';
        boundary_id := 'boundary:unsupported:policy-applicability:' ||
            pgreact_internal.m41_digest(jsonb_build_object('policy', policy_id));
        boundaries := boundaries || jsonb_build_array(jsonb_build_object(
            'kind', 'unsupported', 'identity', boundary_id));
        edge := pgreact_internal.m41_edge('policy_evaluation', applicability_id, boundary_id);
        edges := edges || jsonb_build_array(edge);
        paths := paths || jsonb_build_array(pgreact_internal.m41_path(
            path_nodes || jsonb_build_array(boundary_id),
            path_edges || jsonb_build_array(edge ->> 'identity'), 'unsupported'));
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            'M41_UNSUPPORTED_NODE', 'WARNING', policy_row.set_name, 'applicability',
            'only relational bigint policy applicability is in the qualified adapter',
            'Use a supported relation-backed policy set.'));
    ELSE
        source := pgreact_internal.m41_source_evidence(
            policy_row.applicability_source_oid, policy_row.applicability_source,
            policy_row.subject_key, subject_key);
        IF source ->> 'state' = 'ok'
           AND pgreact_internal.m30_subject_eligible(policy_target, to_jsonb(subject_key)) THEN
            source_id := 'authoritative:' || policy_row.applicability_source || ':' ||
                policy_row.subject_key || '=' || subject_key;
            nodes := nodes || jsonb_build_array(jsonb_build_object(
                'kind', 'authoritative_fact', 'identity', source_id,
                'evidence', source - 'state'));
            edge := pgreact_internal.m41_edge('policy_source', applicability_id, source_id);
            edges := edges || jsonb_build_array(edge);
            path_nodes := path_nodes || jsonb_build_array(source_id);
            path_edges := path_edges || jsonb_build_array(edge ->> 'identity');
        ELSE
            state := CASE source ->> 'state'
                WHEN 'unauthorized' THEN 'unavailable'
                WHEN 'rls' THEN 'unavailable'
                WHEN 'schema_drift' THEN 'unavailable'
                ELSE 'partial' END;
            boundary_id := 'boundary:' || CASE source ->> 'state'
                WHEN 'unauthorized' THEN 'inaccessible'
                WHEN 'rls' THEN 'inaccessible'
                WHEN 'schema_drift' THEN 'schema_drift'
                WHEN 'missing' THEN 'missing'
                ELSE 'ineligible' END || ':' ||
                pgreact_internal.m41_digest(jsonb_build_object('parent', applicability_id));
            boundaries := boundaries || jsonb_build_array(jsonb_build_object(
                'kind', split_part(boundary_id, ':', 2), 'identity', boundary_id));
            edge := pgreact_internal.m41_edge('policy_source', applicability_id, boundary_id);
            edges := edges || jsonb_build_array(edge);
            path_nodes := path_nodes || jsonb_build_array(boundary_id);
            path_edges := path_edges || jsonb_build_array(edge ->> 'identity');
            findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
                CASE source ->> 'state'
                    WHEN 'unauthorized' THEN 'M41_UNAUTHORIZED'
                    WHEN 'rls' THEN 'M41_RLS_REJECTED'
                    WHEN 'schema_drift' THEN 'M41_SCHEMA_DRIFT'
                    WHEN 'missing' THEN 'M41_EVIDENCE_MISSING'
                    ELSE 'M41_EVIDENCE_MISSING' END,
                'WARNING', policy_row.set_name, 'applicability',
                'policy applicability ends at an explicit evidence boundary',
                'Restore the source and retry the causal path.'));
        END IF;
        IF policy_row.complete_frontier < sampled_time AND state = 'complete' THEN
            state := 'partial';
            findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
                'M41_STALE_FRONTIER', 'WARNING', policy_row.set_name, 'complete_frontier',
                'policy applicability evidence is older than the sampled time',
                'Refresh the policy set and retry the request.'));
        END IF;
        paths := paths || jsonb_build_array(pgreact_internal.m41_path(path_nodes, path_edges, state));
    END IF;

    FOR member_row IN
        SELECT member.member_kind, member.member_name, member.member_version
        FROM pgreact_internal.policy_set_members member
        WHERE member.policy_set_version_id = m41_policy_fragment.policy_set_version_id
          AND member.member_kind <> 'decision_program'
        ORDER BY member.ordinal
    LOOP
        child := pgreact_internal.m41_member_fragment(
            member_row.member_kind, member_row.member_name, member_row.member_version,
            subject_key, policy_id, sampled_time, depth_limit, fanout_limit, path_limit);
        nodes := pgreact_internal.m41_array_union(nodes, child -> 'nodes');
        edges := pgreact_internal.m41_array_union(edges, child -> 'edges');
        paths := pgreact_internal.m41_array_union(paths, child -> 'paths');
        boundaries := pgreact_internal.m41_array_union(boundaries, child -> 'boundaries');
        findings := pgreact_internal.m41_array_union(findings, child -> 'findings');
        IF child ->> 'state' = 'unavailable' THEN state := 'unavailable';
        ELSIF child ->> 'state' = 'partial' AND state = 'complete' THEN state := 'partial';
        ELSIF child ->> 'state' = 'unsupported' AND state = 'complete' THEN state := 'unsupported'; END IF;
    END LOOP;
    RETURN jsonb_build_object('state', state, 'nodes', nodes, 'edges', edges,
                              'paths', paths, 'boundaries', boundaries,
                              'findings', findings);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m41_rule_source_fragment(rule_version_id uuid, subject_key bigint, parent_id text DEFAULT NULL::text, requested_activation_id uuid DEFAULT NULL::uuid, requested_generation bigint DEFAULT NULL::bigint, requested_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    rule_row record;
    activation_row record;
    source jsonb;
    match_id text;
    source_id text;
    boundary_id text;
    nodes jsonb := '[]'::jsonb;
    edges jsonb := '[]'::jsonb;
    paths jsonb := '[]'::jsonb;
    boundaries jsonb := '[]'::jsonb;
    findings jsonb := '[]'::jsonb;
    path_nodes jsonb;
    path_edges jsonb := '[]'::jsonb;
    state text := 'complete';
    actual_generation bigint;
    actual_revision bigint;
    boundary_kind text;
    boundary_code text;
BEGIN
    SELECT r.rule_name, v.source_view_oid, v.source_view_name, v.key_column, v.state
    INTO rule_row
    FROM pgreact_internal.rule_versions v
    JOIN pgreact_internal.rules r USING (rule_id)
    WHERE v.rule_version_id = m41_rule_source_fragment.rule_version_id;
    IF NOT FOUND THEN
        boundary_id := 'boundary:missing:rule';
        boundaries := jsonb_build_array(jsonb_build_object(
            'kind', 'missing', 'identity', boundary_id));
        IF parent_id IS NULL THEN
            path_nodes := jsonb_build_array(boundary_id);
        ELSE
            path_nodes := jsonb_build_array(parent_id, boundary_id);
            edges := jsonb_build_array(pgreact_internal.m41_edge(
                'lifecycle_predecessor', parent_id, boundary_id));
            path_edges := jsonb_build_array(edges -> 0 ->> 'identity');
        END IF;
        findings := jsonb_build_array(pgreact_internal.m41_finding(
            'M41_EVIDENCE_MISSING', 'WARNING', '<unknown>', 'rule',
            'the modeled rule version is no longer available',
            'Restore the deployed rule evidence before retrying.'));
        RETURN jsonb_build_object('state', 'unavailable', 'nodes', nodes,
            'edges', edges, 'paths', jsonb_build_array(
                pgreact_internal.m41_path(path_nodes, path_edges, 'unavailable')),
            'boundaries', boundaries, 'findings', findings);
    END IF;

    SELECT a.activation_id, a.active, a.generation, a.revision,
           a.current_bindings, a.last_active_bindings
    INTO activation_row
    FROM pgreact_internal.activation_state a
    WHERE a.rule_version_id = m41_rule_source_fragment.rule_version_id
      AND a.semantic_key = subject_key
      AND (requested_activation_id IS NULL OR a.activation_id = requested_activation_id)
    ORDER BY a.revision DESC, a.generation DESC
    LIMIT 1;
    IF NOT FOUND THEN
        boundary_id := 'boundary:missing:rule-match';
        boundaries := jsonb_build_array(jsonb_build_object(
            'kind', 'missing', 'identity', boundary_id));
        IF parent_id IS NULL THEN
            path_nodes := jsonb_build_array(boundary_id);
        ELSE
            path_nodes := jsonb_build_array(parent_id, boundary_id);
            edges := jsonb_build_array(pgreact_internal.m41_edge(
                'lifecycle_predecessor', parent_id, boundary_id));
            path_edges := jsonb_build_array(edges -> 0 ->> 'identity');
        END IF;
        findings := jsonb_build_array(pgreact_internal.m41_finding(
            'M41_ROOT_NOT_FOUND', 'WARNING', rule_row.rule_name, 'rule_match',
            'the requested lifecycle event has no retained rule match state',
            'Use a retained generation and revision.'));
        RETURN jsonb_build_object('state', 'unavailable', 'nodes', nodes,
            'edges', edges, 'paths', jsonb_build_array(
                pgreact_internal.m41_path(path_nodes, path_edges, 'unavailable')),
            'boundaries', boundaries, 'findings', findings);
    END IF;
    actual_generation := activation_row.generation;
    actual_revision := activation_row.revision;
    match_id := format('rule_match:%s@1:subject=%s:generation=%s:revision=%s',
                       rule_row.rule_name, subject_key, actual_generation, actual_revision);
    nodes := jsonb_build_array(jsonb_build_object(
        'kind', 'rule_match', 'identity', match_id,
        'evidence', jsonb_build_object(
            'target', rule_row.rule_name, 'version', '1', 'subject_key', subject_key,
            'generation', actual_generation, 'revision', actual_revision,
            'active', activation_row.active,
            'bindings', COALESCE(activation_row.current_bindings,
                                 activation_row.last_active_bindings, '{}'::jsonb))));
    IF parent_id IS NOT NULL THEN
        edges := edges || jsonb_build_array(pgreact_internal.m41_edge(
            'lifecycle_match', parent_id, match_id,
            jsonb_build_object('generation', actual_generation,
                               'revision', actual_revision)));
        path_nodes := jsonb_build_array(parent_id, match_id);
        path_edges := jsonb_build_array(edges -> 0 ->> 'identity');
    ELSE
        path_nodes := jsonb_build_array(match_id);
    END IF;
    IF requested_generation IS NOT NULL AND requested_generation <> actual_generation THEN
        state := 'unavailable';
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            'M41_CHANGED_STATE', 'WARNING', rule_row.rule_name, 'root.generation',
            'the retained rule generation does not match the requested root',
            'Retry with the generation returned by the public work evidence.'));
    END IF;
    IF requested_revision IS NOT NULL AND requested_revision <> actual_revision THEN
        state := 'unavailable';
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            'M41_CHANGED_STATE', 'WARNING', rule_row.rule_name, 'root.revision',
            'the retained rule revision does not match the requested root',
            'Retry with the revision returned by the public match evidence.'));
    END IF;

    source := pgreact_internal.m41_source_evidence(
        rule_row.source_view_oid, rule_row.source_view_name, rule_row.key_column, subject_key);
    IF source ->> 'state' = 'ok' THEN
        source_id := format('authoritative:%s:%s=%s', rule_row.source_view_name,
                            rule_row.key_column, subject_key);
        nodes := nodes || jsonb_build_array(jsonb_build_object(
            'kind', 'authoritative_fact', 'identity', source_id,
            'evidence', source - 'state'));
        edges := edges || jsonb_build_array(pgreact_internal.m41_edge(
            'rule_source', match_id, source_id,
            jsonb_build_object('source_definition', rule_row.source_view_name)));
        path_nodes := path_nodes || jsonb_build_array(source_id);
        path_edges := path_edges || jsonb_build_array(
            edges -> (jsonb_array_length(edges) - 1) ->> 'identity');
    ELSE
        boundary_kind := CASE source ->> 'state'
            WHEN 'unauthorized' THEN 'inaccessible'
            WHEN 'rls' THEN 'inaccessible'
            WHEN 'schema_drift' THEN 'schema_drift'
            WHEN 'missing' THEN 'missing'
            ELSE 'unsupported' END;
        boundary_id := 'boundary:' || boundary_kind || ':' ||
            pgreact_internal.m41_digest(jsonb_build_object('parent', match_id));
        boundaries := boundaries || jsonb_build_array(jsonb_build_object(
            'kind', boundary_kind, 'identity', boundary_id));
        edges := edges || jsonb_build_array(pgreact_internal.m41_edge(
            'rule_source', match_id, boundary_id));
        path_nodes := path_nodes || jsonb_build_array(boundary_id);
        path_edges := path_edges || jsonb_build_array(
            edges -> (jsonb_array_length(edges) - 1) ->> 'identity');
        state := CASE WHEN source ->> 'state' IN ('missing') THEN 'partial' ELSE 'unavailable' END;
        boundary_code := CASE source ->> 'state'
            WHEN 'unauthorized' THEN 'M41_UNAUTHORIZED'
            WHEN 'rls' THEN 'M41_RLS_REJECTED'
            WHEN 'schema_drift' THEN 'M41_SCHEMA_DRIFT'
            WHEN 'missing' THEN 'M41_EVIDENCE_MISSING'
            ELSE 'M41_UNSUPPORTED_NODE' END;
        findings := findings || jsonb_build_array(pgreact_internal.m41_finding(
            boundary_code, 'WARNING', rule_row.rule_name, 'source',
            'the rule predecessor ends at an explicit evidence boundary',
            'Restore access and retained source evidence before retrying.'));
    END IF;
    paths := jsonb_build_array(pgreact_internal.m41_path(path_nodes, path_edges, state));
    RETURN jsonb_build_object('state', state, 'nodes', nodes, 'edges', edges,
                              'paths', paths, 'boundaries', boundaries,
                              'findings', findings);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m41_source_evidence(source_oid oid, source_name text, key_column name, subject_key bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
<<m41_rule_source_block>>
DECLARE
    relation_kind "char";
    rls_enabled boolean;
    row_data jsonb;
BEGIN
    IF source_oid IS NULL THEN
        RETURN jsonb_build_object('state', 'schema_drift', 'source', source_name);
    END IF;
    SELECT c.relkind, c.relrowsecurity
    INTO relation_kind, rls_enabled
    FROM pg_class c WHERE c.oid = source_oid;
    IF relation_kind IS NULL THEN
        RETURN jsonb_build_object('state', 'schema_drift', 'source', source_name);
    ELSIF rls_enabled THEN
        RETURN jsonb_build_object('state', 'rls', 'source', source_name);
    ELSIF NOT has_table_privilege(session_user, source_oid, 'SELECT') THEN
        RETURN jsonb_build_object('state', 'unauthorized', 'source', source_name);
    ELSIF NOT EXISTS (
        SELECT 1 FROM pg_attribute
        WHERE attrelid = source_oid AND attname = key_column
          AND attnum > 0 AND NOT attisdropped) THEN
        RETURN jsonb_build_object('state', 'schema_drift', 'source', source_name);
    END IF;
    EXECUTE format('SELECT to_jsonb(s) FROM %s s WHERE s.%I = $1 LIMIT 1',
                   source_oid::regclass, key_column)
    INTO row_data USING subject_key;
    IF row_data IS NULL THEN
        RETURN jsonb_build_object('state', 'missing', 'source', source_name,
                                  'key', subject_key);
    END IF;
    RETURN jsonb_build_object('state', 'ok', 'source', source_name,
                              'key', subject_key, 'row', row_data);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m42_policy_findings(policy jsonb, target_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE findings jsonb := '[]'::jsonb;
    unknown_field text;
    enabled boolean := true;
    retention_text text;
BEGIN
    IF jsonb_typeof(policy) IS DISTINCT FROM 'object' THEN
        RETURN jsonb_build_array(pgreact_internal.m42_finding(
            'M42_POLICY_INVALID', 'ERROR', 'spec.evidence_snapshot',
            'evidence_snapshot must be an object',
            'Use {"retention_seconds": number} with an optional enabled boolean.'));
    END IF;
    SELECT key INTO unknown_field
    FROM jsonb_object_keys(policy) key
    WHERE key NOT IN ('enabled', 'retention_seconds')
    ORDER BY key LIMIT 1;
    IF unknown_field IS NOT NULL THEN
        findings := findings || jsonb_build_array(pgreact_internal.m42_finding(
            'M42_POLICY_INVALID', 'ERROR', 'spec.evidence_snapshot.' || unknown_field,
            'evidence_snapshot contains an unknown field',
            'Use only enabled and retention_seconds.', jsonb_build_object('field', unknown_field)));
    END IF;
    IF policy ? 'enabled' AND jsonb_typeof(policy -> 'enabled') IS DISTINCT FROM 'boolean' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m42_finding(
            'M42_POLICY_INVALID', 'ERROR', 'spec.evidence_snapshot.enabled',
            'enabled must be boolean', 'Use true to enable capture or false to disable it.'));
    ELSE
        enabled := COALESCE((policy ->> 'enabled')::boolean, true);
    END IF;
    retention_text := policy ->> 'retention_seconds';
    IF enabled AND (NOT policy ? 'retention_seconds'
                    OR jsonb_typeof(policy -> 'retention_seconds') IS DISTINCT FROM 'number'
                    OR retention_text !~ '^[1-9][0-9]*$'
                    OR length(retention_text) > 10
                    OR retention_text::bigint > 3153600000) THEN
        findings := findings || jsonb_build_array(pgreact_internal.m42_finding(
            'M42_POLICY_INVALID', 'ERROR', 'spec.evidence_snapshot.retention_seconds',
            'retention_seconds must be a positive integer no greater than one hundred years',
            'Choose a finite retention period in seconds.',
            jsonb_build_object('target', target_name)));
    END IF;
    RETURN findings;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m43_object_access(object_kind text, object_identity text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE object_oid oid;
    owner_oid oid;
    has_rls boolean;
BEGIN
    IF object_identity IS NULL THEN RETURN true; END IF;
    IF object_kind = 'relation_identity' THEN
        object_oid := to_regclass(object_identity);
        IF object_oid IS NULL THEN
            SELECT condition.owner_oid INTO owner_oid
            FROM pgreact_internal.shared_conditions condition
            WHERE condition.condition_name = object_identity;
            RETURN FOUND AND (pg_has_role(session_user, owner_oid, 'USAGE')
                              OR pgreact_internal.is_operator_admin());
        END IF;
        SELECT c.relowner, c.relrowsecurity INTO owner_oid, has_rls
        FROM pg_class c WHERE c.oid = object_oid;
        RETURN NOT COALESCE(has_rls, false)
            AND (pg_has_role(session_user, owner_oid, 'USAGE')
                 OR has_table_privilege(session_user, object_oid, 'SELECT')
                 OR pgreact_internal.is_operator_admin());
    ELSIF object_kind = 'function_identity' THEN
        object_oid := to_regprocedure(object_identity);
        IF object_oid IS NULL THEN RETURN false; END IF;
        SELECT p.proowner INTO owner_oid FROM pg_proc p WHERE p.oid = object_oid;
        RETURN pg_has_role(session_user, owner_oid, 'USAGE')
            OR has_function_privilege(session_user, object_oid, 'EXECUTE')
            OR pgreact_internal.is_operator_admin();
    END IF;
    RETURN true;
EXCEPTION WHEN OTHERS THEN
    RETURN false;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m43_opaque_record(target_kind text, field_path text, public_identity text, stored_digest text, delegated_id uuid, subject_keys name[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE object_oid oid;
    live_digest text;
    action_row record;
    event_kind text;
BEGIN
    IF public_identity IS NULL THEN RETURN NULL; END IF;
    IF field_path LIKE 'spec.applicability.%' OR field_path IN ('spec.condition', 'spec.candidate_relation') THEN
        IF stored_digest IS NULL THEN RETURN NULL; END IF;
        object_oid := to_regclass(public_identity);
        IF object_oid IS NULL THEN RETURN NULL; END IF;
        IF target_kind = 'policy_set' AND field_path = 'spec.applicability.relation' THEN
            live_digest := pgreact_internal.m31_source_definition_digest(
                object_oid, COALESCE(subject_keys, ARRAY[]::name[]));
        ELSIF target_kind = 'decision_program' THEN
            live_digest := encode(pgreact_internal.decision_source_digest(object_oid), 'hex');
        ELSE
            live_digest := encode(sha256(convert_to(
                COALESCE(pg_get_viewdef(object_oid, true), object_oid::regclass::text), 'UTF8')), 'hex');
        END IF;
    ELSIF field_path IN ('spec.on_activate', 'spec.on_deactivate', 'spec.on_change') THEN
        event_kind := upper(replace(split_part(field_path, '.', 2), 'on_', ''));
        SELECT binding.function_digest INTO action_row
        FROM pgreact_internal.consequence_bindings binding
        WHERE binding.rule_version_id = delegated_id
          AND binding.event_kind = event_kind;
        object_oid := to_regprocedure(public_identity);
        IF object_oid IS NULL OR action_row.function_digest IS NULL THEN RETURN NULL; END IF;
        live_digest := encode(sha256(convert_to(pg_get_functiondef(object_oid), 'UTF8')), 'hex');
        stored_digest := encode(action_row.function_digest, 'hex');
    ELSE
        RETURN NULL;
    END IF;
    IF live_digest IS NOT DISTINCT FROM stored_digest THEN RETURN NULL; END IF;
    RETURN jsonb_build_object(
        'field_path', field_path,
        'field_kind', CASE WHEN field_path LIKE 'spec.on_%' THEN 'function_identity'
                           ELSE 'relation_identity' END,
        'change_kind', 'opaque',
        'identity', public_identity,
        'before_digest', stored_digest,
        'after_digest', live_digest,
        'meaning', 'the stored public object evidence changed; SQL meaning is opaque');
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m43_prepare_declaration(declaration pgreact_api.declaration)
 RETURNS pgreact_api.declaration
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE spec jsonb;
    field text;
    relation_name text;
    relation_oid oid;
    function_oid oid;
BEGIN
    IF declaration IS NULL THEN RETURN NULL; END IF;
    spec := COALESCE((declaration).spec, '{}'::jsonb);
    FOREACH field IN ARRAY ARRAY['condition', 'candidate_relation'] LOOP
        IF spec ? field THEN
            relation_name := spec ->> field;
            relation_oid := to_regclass(relation_name);
            IF relation_oid IS NOT NULL THEN
                spec := jsonb_set(spec, ARRAY[field], to_jsonb(relation_oid::regclass::text), true);
            END IF;
        END IF;
    END LOOP;
    IF (declaration).kind = 'policy_set'
       AND jsonb_typeof(spec -> 'applicability') = 'object' THEN
        relation_name := spec -> 'applicability' ->> 'relation';
        relation_oid := to_regclass(relation_name);
        IF relation_oid IS NOT NULL THEN
            spec := jsonb_set(spec, '{applicability,relation}',
                              to_jsonb(relation_oid::regclass::text), true);
        END IF;
        relation_name := spec -> 'applicability' ->> 'condition';
        relation_oid := to_regclass(relation_name);
        IF relation_oid IS NOT NULL THEN
            spec := jsonb_set(spec, '{applicability,condition}',
                              to_jsonb(relation_oid::regclass::text), true);
        END IF;
    END IF;
    FOREACH field IN ARRAY ARRAY['on_activate', 'on_deactivate', 'on_change'] LOOP
        IF spec ? field THEN
            BEGIN
                function_oid := to_regprocedure(spec ->> field);
                IF function_oid IS NOT NULL THEN
                    spec := jsonb_set(spec, ARRAY[field],
                                      to_jsonb(function_oid::regprocedure::text), true);
                END IF;
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
    END LOOP;
    RETURN ROW((declaration).api_version, (declaration).kind, (declaration).name, spec)
        ::pgreact_api.declaration;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m53_explain_question(options jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    causal boolean := pgreact_internal.m41_requested(options);
    why_not boolean := pgreact_internal.m40_requested(options);
BEGIN
    IF causal AND why_not THEN RETURN 'conflict';
    ELSIF causal THEN RETURN 'causal_path';
    ELSIF why_not THEN RETURN 'why_not';
    END IF;
    RETURN 'ordinary';
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m53_next_actions(findings jsonb, origin_state text, origin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    finding jsonb;
    action jsonb;
    actions jsonb := '[]'::jsonb;
    code text;
    field_name text;
    action_name text;
    retryable boolean;
BEGIN
    FOR finding IN
        SELECT value FROM jsonb_array_elements(
            CASE WHEN jsonb_typeof(findings) = 'array' THEN findings ELSE '[]'::jsonb END)
    LOOP
        code := COALESCE(finding ->> 'code', 'M53_STATE_INCOMPLETE');
        field_name := COALESCE(finding ->> 'field', finding ->> 'field_path');
        IF code LIKE '%UNAUTHORIZED%' OR code LIKE '%RLS%' THEN
            action_name := 'grant_access'; retryable := false;
        ELSIF code LIKE '%LIMIT%' OR code LIKE '%PARTIAL%' THEN
            action_name := 'increase_limit'; retryable := true;
            field_name := COALESCE(field_name, 'limit');
        ELSIF code LIKE '%POLICY_MISSING%' OR code LIKE '%UNSUPPORTED%'
              OR code LIKE '%INVALID%' OR code LIKE '%AMBIGUOUS%' THEN
            action_name := 'stop'; retryable := false;
        ELSIF code LIKE '%DELETED%' THEN
            action_name := 'recapture'; retryable := false;
        ELSIF code LIKE '%DRIFT%' OR code LIKE '%SCHEMA%' THEN
            action_name := 'repair_schema'; retryable := false;
        ELSIF code LIKE '%NOT_FOUND%' OR code LIKE '%STALE%' THEN
            action_name := 'refresh_target'; retryable := true;
        ELSE
            action_name := 'retry'; retryable := true;
        END IF;
        action := jsonb_build_object(
            'action', action_name, 'reason_code', code,
            'safe_to_retry', retryable,
            'parameters', CASE WHEN field_name IS NULL THEN '{}'::jsonb
                               ELSE jsonb_build_object('field', field_name) END);
        IF NOT actions @> jsonb_build_array(action) THEN
            actions := actions || jsonb_build_array(action);
        END IF;
        IF jsonb_array_length(actions) >= 16 THEN EXIT; END IF;
    END LOOP;
    IF jsonb_array_length(actions) = 0 AND
       pgreact_internal.m53_state(origin_state) <> 'complete' THEN
        actions := jsonb_build_array(jsonb_build_object(
            'action', CASE WHEN pgreact_internal.m53_state(origin_state) = 'unsupported'
                           THEN 'stop' ELSE 'retry' END,
            'reason_code', 'M53_STATE_INCOMPLETE',
            'safe_to_retry', pgreact_internal.m53_state(origin_state) <> 'unsupported',
            'parameters', '{}'::jsonb));
    END IF;
    RETURN actions;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m53_package_deploy(declaration pgreact_api.declaration, preconditions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    checked jsonb := pgreact_internal.m53_package_validate(declaration);
    package_normalized jsonb := checked -> 'normalized';
    findings jsonb := checked -> 'findings';
    runtime_declaration pgreact_api.declaration;
    result jsonb;
    preview jsonb;
    version_id uuid;
    package_definition_digest text;
    package_plan_digest text;
    node jsonb;
    child pgreact_api.declaration;
    existing_child pgreact_internal.api_declarations%ROWTYPE;
    child_exists boolean;
    support jsonb;
    dependency jsonb;
    ordinal integer := 0;
BEGIN
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(findings) value
               WHERE value ->> 'severity' = 'ERROR') THEN
        RETURN pgreact_internal.m53_package_preview(declaration, preconditions);
    END IF;
    preview := pgreact_internal.m53_package_preview(declaration, preconditions);
    package_plan_digest := preview -> 'summary' ->> 'plan_digest';
    IF preconditions ? 'plan_digest'
       AND preconditions ->> 'plan_digest' IS DISTINCT FROM package_plan_digest THEN
        RAISE EXCEPTION 'M53_STALE_PREVIEW: package preview is stale';
    END IF;
    FOR node IN SELECT value FROM jsonb_array_elements(package_normalized -> 'spec' -> 'members') value LOOP
        IF jsonb_typeof(node -> 'declaration') = 'object' THEN
            child := pgreact_api.declaration(
                node -> 'declaration' ->> 'kind', node -> 'declaration' ->> 'name',
                node -> 'declaration' -> 'spec');
            SELECT * INTO existing_child
            FROM pgreact_internal.api_declarations row_data
            WHERE row_data.kind = node ->> 'kind'
              AND row_data.object_name = node ->> 'name'
              AND row_data.state = 'DEPLOYED';
            child_exists := FOUND;
            IF EXISTS (SELECT 1 FROM pgreact_internal.policy_set_members member
                       JOIN pgreact_internal.policy_set_versions version
                         USING (policy_set_version_id)
                       JOIN pgreact_internal.policy_sets set USING (policy_set_id)
                       WHERE set.set_name <> (declaration).name
                         AND version.state = 'DEPLOYED' AND member.package_owned
                         AND member.member_kind = node ->> 'kind'
                         AND member.member_name = node ->> 'name'
                         AND member.member_version = COALESCE(node ->> 'version', '1')) THEN
                RAISE EXCEPTION 'M53_POLICY_CROSS_PACKAGE: child is owned by another package';
            END IF;
            IF child_exists
               AND NOT EXISTS (SELECT 1 FROM pgreact_internal.policy_set_members member
                               JOIN pgreact_internal.policy_set_versions version
                                 USING (policy_set_version_id)
                               JOIN pgreact_internal.policy_sets set USING (policy_set_id)
                               WHERE set.set_name = (declaration).name
                                 AND version.version = package_normalized -> 'spec' ->> 'version'
                                 AND version.state = 'DEPLOYED'
                                 AND member.member_kind = node ->> 'kind'
                                 AND member.member_name = node ->> 'name'
                                 AND member.member_version = COALESCE(node ->> 'version', '1'))
               AND NOT COALESCE(preconditions -> 'adopt', '[]'::jsonb) @>
                   jsonb_build_array(jsonb_build_object(
                       'kind', node ->> 'kind', 'name', node ->> 'name',
                       'version', COALESCE(node ->> 'version', '1'))) THEN
                RAISE EXCEPTION 'M53_POLICY_ADOPTION_REQUIRED: declare the existing child in preconditions.adopt';
            END IF;
            IF (child).kind IN ('rule', 'decision_program') THEN
                IF child_exists THEN
                    IF existing_child.declaration_digest IS DISTINCT FROM sha256(convert_to(
                        pgreact_internal.m28_normalize(child)::text, 'UTF8')) THEN
                        RAISE EXCEPTION 'M53_POLICY_ADOPTION_DIGEST: existing child digest does not match';
                    END IF;
                ELSE
                    PERFORM pgreact_api.deploy_m31(child, '{}'::jsonb);
                END IF;
            END IF;
        END IF;
    END LOOP;
    runtime_declaration := pgreact_internal.m53_package_runtime_declaration(package_normalized);
    result := pgreact_api.deploy_m31(runtime_declaration, COALESCE(preconditions, '{}'::jsonb) - 'plan_digest');
    SELECT version.policy_set_version_id INTO version_id
    FROM pgreact_internal.policy_set_versions version
    JOIN pgreact_internal.policy_sets set USING (policy_set_id)
    WHERE set.set_name = (declaration).name
      AND version.version = package_normalized -> 'spec' ->> 'version'
    ORDER BY version.created_at DESC LIMIT 1;
    IF version_id IS NULL THEN
        RAISE EXCEPTION 'M53_DEPLOYMENT_MISSING: installed policy planner did not create a version';
    END IF;
    package_definition_digest := pgreact_internal.m53_package_digest(package_normalized);
    UPDATE pgreact_internal.policy_set_versions
    SET package_format_version = 1, package_complete = COALESCE((checked ->> 'complete')::boolean, false),
        definition_digest = package_definition_digest, plan_digest = package_plan_digest,
        dependency_graph = package_normalized -> 'spec' -> 'dependencies',
        support_declarations = package_normalized -> 'spec' -> 'support',
        normalized = package_normalized,
        declaration_digest = decode(package_definition_digest, 'hex')
    WHERE policy_set_version_id = version_id;
    DELETE FROM pgreact_internal.policy_set_supports WHERE policy_set_version_id = version_id;
    UPDATE pgreact_internal.policy_set_members member
    SET package_owned = true
    WHERE member.policy_set_version_id = version_id;
    FOR support IN SELECT value FROM jsonb_array_elements(package_normalized -> 'spec' -> 'support') value LOOP
        ordinal := ordinal + 1;
        INSERT INTO pgreact_internal.policy_set_supports(
            policy_set_version_id, ordinal, support_kind, support_name, support_version,
            support_declaration, definition_digest)
        VALUES (version_id, ordinal, support ->> 'kind', support ->> 'name',
                COALESCE(support ->> 'version', '1'), support -> 'declaration',
                pgreact_internal.m53_package_digest(support -> 'declaration'));
    END LOOP;
    DELETE FROM pgreact_internal.policy_set_dependencies WHERE policy_set_version_id = version_id;
    ordinal := 0;
    FOR dependency IN SELECT value FROM jsonb_array_elements(package_normalized -> 'spec' -> 'dependencies') value LOOP
        ordinal := ordinal + 1;
        INSERT INTO pgreact_internal.policy_set_dependencies(
            policy_set_version_id, ordinal, from_kind, from_name, from_version,
            on_kind, on_name, on_version)
        VALUES (version_id, ordinal, dependency -> 'from' ->> 'kind',
                dependency -> 'from' ->> 'name', COALESCE(dependency -> 'from' ->> 'version', '1'),
                dependency -> 'on' ->> 'kind', dependency -> 'on' ->> 'name',
                COALESCE(dependency -> 'on' ->> 'version', '1'));
    END LOOP;
    RETURN result || jsonb_build_object(
        'contract_version', 53, 'operation', 'deploy',
        'package', jsonb_build_object(
            'complete', checked -> 'complete', 'definition_digest', package_definition_digest,
            'plan_digest', package_plan_digest, 'member_count', checked -> 'member_count',
            'support_count', checked -> 'support_count',
            'dependency_count', checked -> 'dependency_count'),
        'findings', findings);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m53_package_validate(declaration pgreact_api.declaration)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    normalized jsonb := pgreact_internal.m53_package_normalize(declaration);
    spec jsonb := COALESCE(normalized -> 'spec', '{}'::jsonb);
    findings jsonb := '[]'::jsonb;
    member jsonb;
    support jsonb;
    dependency jsonb;
    node_id text;
    endpoint text;
    field text;
    member_count integer := 0;
    support_count integer := 0;
    dependency_count integer := 0;
    complete boolean := true;
    valid_from timestamptz;
    valid_to timestamptz;
BEGIN
    IF declaration IS NULL OR (declaration).kind IS DISTINCT FROM 'policy_set' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_KIND', 'ERROR', 'kind',
            'M53 packaging accepts one policy_set declaration',
            'Build the declaration with pgreact.policy_set().'));
        RETURN jsonb_build_object('normalized', normalized, 'findings', findings,
                                  'complete', false);
    END IF;
    IF (declaration).api_version IS DISTINCT FROM '1' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_API_VERSION', 'ERROR', 'api_version',
            'only declaration API version 1 is supported', 'Use API version 1.'));
    END IF;
    IF (declaration).name IS NULL OR (declaration).name !~ '^[A-Za-z_][A-Za-z0-9_.-]*$' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_NAME', 'ERROR', 'name',
            'policy-set name must be a stable public name', 'Use a qualified name.'));
    END IF;
    IF NULLIF(btrim(spec ->> 'version'), '') IS NULL
       OR length(spec ->> 'version') > 64
       OR spec ->> 'version' !~ '^[A-Za-z0-9][A-Za-z0-9._-]*$' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_VERSION', 'ERROR', 'spec.version',
            'policy-set version must be a stable immutable identifier',
            'Use a value such as 1 or 2026-09.'));
    END IF;
    FOR field IN SELECT key FROM jsonb_object_keys(spec) key LOOP
        IF field NOT IN ('version', 'members', 'support', 'dependencies', 'applicability',
                         'valid_from', 'valid_to', 'evidence_limit') THEN
            findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                'M53_POLICY_FIELD_UNKNOWN', 'ERROR', 'spec.' || field,
                'policy-set declaration contains an unknown field',
                'Remove the field or use the M53 policy-set contract.'));
        END IF;
    END LOOP;
    IF jsonb_typeof(spec -> 'members') IS DISTINCT FROM 'array'
       OR jsonb_array_length(COALESCE(spec -> 'members', '[]'::jsonb)) = 0 THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_MEMBERS', 'ERROR', 'spec.members',
            'a complete policy set needs at least one member',
            'Add a rule or decision declaration.'));
    ELSE
        member_count := jsonb_array_length(spec -> 'members');
        IF member_count > 64 THEN
            findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                'M53_POLICY_MEMBER_LIMIT', 'ERROR', 'spec.members',
                'a policy set may contain at most 64 members',
                'Split the policy into smaller sets.'));
        END IF;
        FOR member IN SELECT value FROM jsonb_array_elements(spec -> 'members') value LOOP
            node_id := pgreact_internal.m53_package_id(member);
            IF member ->> 'kind' NOT IN ('rule', 'decision_program')
               OR NULLIF(member ->> 'name', '') IS NULL THEN
                findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                    'M53_POLICY_MEMBER_KIND', 'ERROR', 'spec.members',
                    'members must be named rule or decision_program declarations',
                    'Use a complete typed child declaration.'));
            END IF;
            IF jsonb_typeof(member -> 'declaration') IS DISTINCT FROM 'object'
               OR (member -> 'declaration' ->> 'kind') IS DISTINCT FROM member ->> 'kind'
               OR (member -> 'declaration' ->> 'name') IS DISTINCT FROM member ->> 'name'
               OR jsonb_typeof(member -> 'declaration' -> 'spec') IS DISTINCT FROM 'object' THEN
                findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                    'M53_POLICY_MEMBER_DECLARATION', 'ERROR', 'spec.members',
                    'each member needs its complete child declaration',
                    'Use a rule or decision declaration in the member field.'));
            END IF;
            IF (SELECT count(*) FROM jsonb_array_elements(spec -> 'members') value
                WHERE pgreact_internal.m53_package_id(value) = node_id) > 1 THEN
                findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                    'M53_POLICY_MEMBER_DUPLICATE', 'ERROR', 'spec.members',
                    'a member identity appears more than once',
                    'Keep each immutable child identity once.'));
            END IF;
        END LOOP;
    END IF;
    IF jsonb_typeof(spec -> 'support') IS DISTINCT FROM 'array' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_SUPPORT_SHAPE', 'ERROR', 'spec.support',
            'support must be an array', 'Use shared-condition or parameter-family declarations.'));
    ELSE
        support_count := jsonb_array_length(spec -> 'support');
        IF support_count > 64 THEN
            findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                'M53_POLICY_SUPPORT_LIMIT', 'ERROR', 'spec.support',
                'a policy set may contain at most 64 support declarations',
                'Split the support declarations between policy sets.'));
        END IF;
        FOR support IN SELECT value FROM jsonb_array_elements(spec -> 'support') value LOOP
            IF support ->> 'kind' NOT IN ('shared_condition', 'parameter_family')
               OR NULLIF(support ->> 'name', '') IS NULL THEN
                findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                    'M53_POLICY_SUPPORT_KIND', 'ERROR', 'spec.support',
                    'support must be a shared_condition or parameter_family declaration',
                    'Use the typed support constructors.'));
            END IF;
            IF jsonb_typeof(support -> 'declaration') IS DISTINCT FROM 'object'
               OR (support -> 'declaration' ->> 'kind') IS DISTINCT FROM support ->> 'kind'
               OR (support -> 'declaration' ->> 'name') IS DISTINCT FROM support ->> 'name'
               OR jsonb_typeof(support -> 'declaration' -> 'spec') IS DISTINCT FROM 'object' THEN
                findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                    'M53_POLICY_SUPPORT_DECLARATION', 'ERROR', 'spec.support',
                    'each support item needs its complete typed declaration',
                    'Use a shared-condition or parameter-family constructor.'));
            END IF;
        END LOOP;
    END IF;
    IF jsonb_typeof(spec -> 'dependencies') IS DISTINCT FROM 'array' THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_DEPENDENCY_SHAPE', 'ERROR', 'spec.dependencies',
            'dependencies must be an array', 'Use objects with from and on identities.'));
    ELSE
        dependency_count := jsonb_array_length(spec -> 'dependencies');
        IF dependency_count > 256 THEN
            findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                'M53_POLICY_DEPENDENCY_LIMIT', 'ERROR', 'spec.dependencies',
                'a policy set may contain at most 256 dependency edges',
                'Remove unused edges or split the policy.'));
        END IF;
        FOR dependency IN SELECT value FROM jsonb_array_elements(spec -> 'dependencies') value LOOP
            IF jsonb_typeof(dependency -> 'from') IS DISTINCT FROM 'object'
               OR jsonb_typeof(dependency -> 'on') IS DISTINCT FROM 'object' THEN
                findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                    'M53_POLICY_DEPENDENCY_IDENTITY', 'ERROR', 'spec.dependencies',
                    'each dependency needs typed from and on identities',
                    'Use kind, name, and version at both endpoints.'));
                CONTINUE;
            END IF;
            node_id := pgreact_internal.m53_package_id(dependency -> 'from');
            endpoint := pgreact_internal.m53_package_id(dependency -> 'on');
            IF node_id = endpoint THEN
                findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                    'M53_POLICY_DEPENDENCY_SELF', 'ERROR', 'spec.dependencies',
                    'a dependency cannot point to itself', 'Remove the self-edge.'));
            END IF;
            IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(
                               CASE WHEN jsonb_typeof(spec -> 'members') = 'array'
                               THEN spec -> 'members' ELSE '[]'::jsonb END) value
                           WHERE pgreact_internal.m53_package_id(value) = node_id)
               AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(
                                   CASE WHEN jsonb_typeof(spec -> 'support') = 'array'
                                   THEN spec -> 'support' ELSE '[]'::jsonb END) value
                               WHERE pgreact_internal.m53_package_id(value) = node_id) THEN
                findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                    'M53_POLICY_DEPENDENCY_ENDPOINT', 'ERROR', 'spec.dependencies',
                    'dependency endpoints must be declared in this policy set',
                    'Add both endpoint declarations or remove the edge.'));
            END IF;
            IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(
                               CASE WHEN jsonb_typeof(spec -> 'members') = 'array'
                               THEN spec -> 'members' ELSE '[]'::jsonb END) value
                           WHERE pgreact_internal.m53_package_id(value) = endpoint)
               AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(
                                   CASE WHEN jsonb_typeof(spec -> 'support') = 'array'
                                   THEN spec -> 'support' ELSE '[]'::jsonb END) value
                               WHERE pgreact_internal.m53_package_id(value) = endpoint) THEN
                findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                    'M53_POLICY_DEPENDENCY_ENDPOINT', 'ERROR', 'spec.dependencies',
                    'dependency endpoints must be declared in this policy set',
                    'Add both endpoint declarations or remove the edge.'));
            END IF;
            IF (SELECT count(*) FROM jsonb_array_elements(spec -> 'dependencies') value
                WHERE value -> 'from' = dependency -> 'from'
                  AND value -> 'on' = dependency -> 'on') > 1 THEN
                findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                    'M53_POLICY_DEPENDENCY_DUPLICATE', 'ERROR', 'spec.dependencies',
                    'a dependency edge appears more than once', 'Keep each edge once.'));
            END IF;
        END LOOP;
    END IF;
    IF jsonb_typeof(spec -> 'applicability') IS DISTINCT FROM 'object'
       OR NULLIF(spec -> 'applicability' ->> 'relation', '') IS NULL
       OR to_regclass(spec -> 'applicability' ->> 'relation') IS NULL THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_APPLICABILITY', 'ERROR', 'spec.applicability',
            'applicability must name an existing relation',
            'Create the relation before previewing the policy set.'));
    END IF;
    BEGIN
        valid_from := (spec ->> 'valid_from')::timestamptz;
        valid_to := NULLIF(spec ->> 'valid_to', '')::timestamptz;
        IF valid_to IS NOT NULL AND valid_to <= valid_from THEN
            findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
                'M53_POLICY_EFFECTIVE_PERIOD', 'ERROR', 'spec.valid_to',
                'valid_to must be after valid_from', 'Use a non-overlapping effective period.'));
        END IF;
    EXCEPTION WHEN OTHERS THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_EFFECTIVE_PERIOD', 'ERROR', 'spec.valid_from',
            'effective timestamps must be valid timestamptz values',
            'Use RFC3339 timestamps.'));
    END;
    IF octet_length(normalized::text) > 1048576 THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_PAYLOAD_LIMIT', 'ERROR', 'spec',
            'the canonical policy declaration may not exceed 1 MiB',
            'Remove unused declarations or split the policy set.'));
    END IF;

    IF pgreact_internal.m54_package_has_cycle(spec) THEN
        findings := findings || jsonb_build_array(pgreact_internal.m53_finding(
            'M53_POLICY_DEPENDENCY_CYCLE', 'ERROR', 'spec.dependencies',
            'dependency edges must form an acyclic graph',
            'Remove one edge from the cycle.'));
    END IF;
    complete := complete AND NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(findings) value
        WHERE value ->> 'severity' = 'ERROR');
    RETURN jsonb_build_object('normalized', normalized, 'findings', findings,
        'complete', complete, 'member_count', member_count,
        'support_count', support_count, 'dependency_count', dependency_count);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_canonicalize_declaration(declaration pgreact_api.declaration)
 RETURNS pgreact_api.declaration
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    result_spec jsonb := COALESCE((declaration).spec, '{}'::jsonb);
    field text;
    relation_oid oid;
    function_oid oid;
    item jsonb;
    child pgreact_api.declaration;
    canonical_items jsonb := '[]'::jsonb;
BEGIN
    IF declaration IS NULL THEN
        RETURN NULL;
    END IF;
    FOREACH field IN ARRAY ARRAY[
        'condition', 'candidate_relation', 'parameter_relation',
        'population_relation', 'candidate_catalog'
    ] LOOP
        IF result_spec ? field THEN
            BEGIN
                relation_oid := to_regclass(result_spec ->> field);
                IF relation_oid IS NOT NULL THEN
                    result_spec := jsonb_set(result_spec, ARRAY[field],
                        to_jsonb(pgreact_internal.m54_relation_identity(relation_oid)), true);
                END IF;
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
    END LOOP;
    IF jsonb_typeof(result_spec -> 'applicability') = 'object'
       AND result_spec -> 'applicability' ? 'relation' THEN
        BEGIN
            relation_oid := to_regclass(result_spec -> 'applicability' ->> 'relation');
            IF relation_oid IS NOT NULL THEN
                result_spec := jsonb_set(result_spec, '{applicability,relation}',
                    to_jsonb(pgreact_internal.m54_relation_identity(relation_oid)), true);
            END IF;
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;
    FOREACH field IN ARRAY ARRAY['on_activate', 'on_deactivate', 'on_change'] LOOP
        IF result_spec ? field THEN
            BEGIN
                function_oid := to_regprocedure(result_spec ->> field);
                IF function_oid IS NOT NULL THEN
                    result_spec := jsonb_set(result_spec, ARRAY[field],
                        to_jsonb(pgreact_internal.m54_function_identity(function_oid)), true);
                END IF;
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
    END LOOP;
    IF (declaration).kind = 'policy_set' THEN
        IF jsonb_typeof(result_spec -> 'members') = 'array' THEN
            FOR item IN SELECT value FROM jsonb_array_elements(result_spec -> 'members') value LOOP
                IF jsonb_typeof(item -> 'declaration') = 'object' THEN
                    child := pgreact_api.declaration(
                        item -> 'declaration' ->> 'kind',
                        item -> 'declaration' ->> 'name',
                        item -> 'declaration' -> 'spec');
                    child := pgreact_internal.m54_canonicalize_declaration(child);
                    item := jsonb_set(item, '{declaration}', jsonb_build_object(
                        'api_version', (child).api_version,
                        'kind', (child).kind, 'name', (child).name,
                        'spec', (child).spec), true);
                END IF;
                canonical_items := canonical_items || jsonb_build_array(item);
            END LOOP;
            result_spec := jsonb_set(result_spec, '{members}', canonical_items, true);
        END IF;
        canonical_items := '[]'::jsonb;
        IF jsonb_typeof(result_spec -> 'support') = 'array' THEN
            FOR item IN SELECT value FROM jsonb_array_elements(result_spec -> 'support') value LOOP
                IF jsonb_typeof(item -> 'declaration') = 'object' THEN
                    child := pgreact_api.declaration(
                        item -> 'declaration' ->> 'kind',
                        item -> 'declaration' ->> 'name',
                        item -> 'declaration' -> 'spec');
                    child := pgreact_internal.m54_canonicalize_declaration(child);
                    item := jsonb_set(item, '{declaration}', jsonb_build_object(
                        'api_version', (child).api_version,
                        'kind', (child).kind, 'name', (child).name,
                        'spec', (child).spec), true);
                END IF;
                canonical_items := canonical_items || jsonb_build_array(item);
            END LOOP;
            result_spec := jsonb_set(result_spec, '{support}', canonical_items, true);
        END IF;
    END IF;
    RETURN ROW((declaration).api_version, (declaration).kind, (declaration).name,
               result_spec)::pgreact_api.declaration;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_check_preconditions(preconditions jsonb, current_found boolean, current_state text, current_digest text, preview jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    field text;
    expected text;
    allow_create boolean;
BEGIN
    IF preconditions IS NULL OR jsonb_typeof(preconditions) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'M54_PRECONDITIONS: preconditions must be a JSON object';
    END IF;
    FOR field IN SELECT key FROM jsonb_object_keys(preconditions) key LOOP
        IF field NOT IN ('allow_create', 'expected_current_digest', 'preview_digest',
                         'plan_digest', 'old_work', 'old_work_policy', 'adopt') THEN
            RAISE EXCEPTION 'M54_PRECONDITION_FIELD: unsupported precondition %', field;
        END IF;
    END LOOP;
    IF preconditions ? 'allow_create' THEN
        IF jsonb_typeof(preconditions -> 'allow_create') IS DISTINCT FROM 'boolean' THEN
            RAISE EXCEPTION 'M54_PRECONDITION_FIELD: allow_create must be boolean';
        END IF;
        allow_create := (preconditions ->> 'allow_create')::boolean;
        IF allow_create AND current_found AND upper(current_state) = 'DEPLOYED' THEN
            RAISE EXCEPTION 'M28_EXISTS: target already exists';
        END IF;
    END IF;
    IF preconditions ? 'expected_current_digest' THEN
        IF jsonb_typeof(preconditions -> 'expected_current_digest') IS DISTINCT FROM 'string'
           OR preconditions ->> 'expected_current_digest' !~ '^[0-9a-f]{64}$' THEN
            RAISE EXCEPTION 'M54_PRECONDITION_FIELD: expected_current_digest must be a 64-character lowercase hex digest';
        END IF;
        expected := preconditions ->> 'expected_current_digest';
        IF current_found AND upper(current_state) = 'DEPLOYED'
           AND expected IS DISTINCT FROM current_digest THEN
            RAISE EXCEPTION 'M28_REPLACE_STALE'
                USING HINT = 'Preview the current target and use its exact digest as expected_current_digest.';
        ELSIF NOT current_found OR upper(current_state) <> 'DEPLOYED' THEN
            RAISE EXCEPTION 'M28_REPLACE_STALE'
                USING HINT = 'The expected target is not currently deployed.';
        END IF;
    ELSIF preconditions ? 'allow_create'
          AND (preconditions ->> 'allow_create')::boolean = false
          AND current_found AND upper(current_state) = 'DEPLOYED' THEN
        RAISE EXCEPTION 'M28_REPLACE_STALE'
            USING HINT = 'Preview the current target and use its exact digest as expected_current_digest.';
    END IF;
    FOREACH field IN ARRAY ARRAY['preview_digest', 'plan_digest'] LOOP
        IF preconditions ? field THEN
            IF jsonb_typeof(preconditions -> field) IS DISTINCT FROM 'string'
               OR preconditions ->> field !~ '^[0-9a-f]{64}$' THEN
                RAISE EXCEPTION 'M54_PRECONDITION_FIELD: % must be a 64-character lowercase hex digest', field;
            END IF;
            expected := preconditions ->> field;
            IF expected IS DISTINCT FROM preview -> 'summary' ->> field
               AND NOT (field = 'preview_digest'
                        AND expected = preview -> 'summary' ->> 'legacy_preview_digest') THEN
                RAISE EXCEPTION 'M54_REVIEW_TOKEN_STALE: reviewed preview is stale';
            END IF;
        END IF;
    END LOOP;
    IF preconditions ? 'old_work' AND preconditions ? 'old_work_policy'
       AND preconditions ->> 'old_work' IS DISTINCT FROM preconditions ->> 'old_work_policy' THEN
        RAISE EXCEPTION 'M54_PRECONDITION_FIELD: old_work and old_work_policy disagree';
    END IF;
    IF preconditions ? 'old_work'
       AND jsonb_typeof(preconditions -> 'old_work') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'M54_PRECONDITION_FIELD: old_work must be a string';
    END IF;
    IF preconditions ? 'old_work_policy'
       AND jsonb_typeof(preconditions -> 'old_work_policy') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'M54_PRECONDITION_FIELD: old_work_policy must be a string';
    END IF;
    IF preconditions ? 'adopt'
       AND jsonb_typeof(preconditions -> 'adopt') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'M54_PRECONDITION_FIELD: adopt must be an array';
    END IF;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_decode_review_token(token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE decoded bytea;
    payload jsonb;
BEGIN
    IF token IS NULL OR octet_length(token) > 4096 OR token NOT LIKE 'm54.v1.%'
       OR substring(token from 8) !~ '^[0-9a-f]+$'
       OR length(substring(token from 8)) % 2 <> 0 THEN
        RETURN NULL;
    END IF;
    decoded := decode(substring(token from 8), 'hex');
    payload := convert_from(decoded, 'UTF8')::jsonb;
    IF jsonb_typeof(payload) IS DISTINCT FROM 'object'
       OR payload ->> 'token_version' IS DISTINCT FROM '1' THEN
        RETURN NULL;
    END IF;
    RETURN payload;
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_deploy(declaration pgreact_api.declaration, preconditions jsonb DEFAULT '{}'::jsonb, token_payload jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    canonical pgreact_api.declaration := pgreact_internal.m54_canonicalize_declaration(declaration);
    preview jsonb;
    validation jsonb;
    normalized_decl jsonb;
    current_row pgreact_internal.api_declarations%ROWTYPE;
    current_found boolean;
    owner_id oid := (SELECT oid FROM pg_roles WHERE rolname = session_user);
    action text;
    old_work text;
    old_work_required boolean;
    condition_oid regclass;
    candidate_oid regclass;
    result_columns name[];
    live_source text;
    new_delegated_id uuid;
    effective_preconditions jsonb := COALESCE(preconditions, '{}'::jsonb);
BEGIN
    validation := pgreact_internal.m54_validate(canonical);
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(validation -> 'findings', '[]'::jsonb)) item
               WHERE item ->> 'severity' = 'ERROR') THEN
        RAISE EXCEPTION 'M54_VALIDATION: %', validation -> 'findings';
    END IF;
    IF token_payload IS NOT NULL THEN
        IF token_payload ->> 'operation' IS DISTINCT FROM 'preview'
           OR token_payload ->> 'digest_kind' IS NULL
           OR jsonb_typeof(token_payload -> 'target') IS DISTINCT FROM 'object' THEN
            RAISE EXCEPTION 'M54_REVIEW_TOKEN_UNSUPPORTED: review token shape is not supported';
        END IF;
        IF token_payload -> 'target' ->> 'kind' IS DISTINCT FROM (canonical).kind
           OR token_payload -> 'target' ->> 'name' IS DISTINCT FROM (canonical).name THEN
            RAISE EXCEPTION 'M54_REVIEW_TOKEN_MISMATCH: token target does not match declaration';
        END IF;
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(
        (canonical).kind || ':' || (canonical).name, 5788046901200000));
    SELECT * INTO current_row
    FROM pgreact_internal.api_declarations row_data
    WHERE row_data.kind = (canonical).kind
      AND row_data.object_name = (canonical).name
    FOR UPDATE;
    current_found := FOUND;
    preview := pgreact_internal.m54_preview(canonical, effective_preconditions);
    IF token_payload IS NOT NULL THEN
        IF token_payload ->> 'contract_version' IS DISTINCT FROM preview ->> 'contract_version' THEN
            RAISE EXCEPTION 'M54_REVIEW_TOKEN_MISMATCH: token contract does not match';
        END IF;
        IF token_payload ->> 'proposed_declaration_digest' IS DISTINCT FROM
           preview -> 'summary' ->> 'proposed_declaration_digest' THEN
            RAISE EXCEPTION 'M54_REVIEW_TOKEN_MISMATCH: token declaration digest does not match';
        END IF;
        IF token_payload ->> 'digest_kind' NOT IN ('plan_digest', 'preview_digest')
           OR token_payload ->> 'digest' IS DISTINCT FROM
              preview -> 'summary' ->> (token_payload ->> 'digest_kind') THEN
            RAISE EXCEPTION 'M54_REVIEW_TOKEN_STALE: reviewed preview is stale';
        END IF;
        effective_preconditions := effective_preconditions || jsonb_build_object(
            token_payload ->> 'digest_kind', token_payload ->> 'digest');
    END IF;
    PERFORM pgreact_internal.m54_check_preconditions(
        effective_preconditions, current_found, current_row.state,
        CASE WHEN current_found THEN encode(current_row.declaration_digest, 'hex') ELSE NULL END,
        preview);
    IF preview ->> 'state' <> 'ready' THEN
        RAISE EXCEPTION 'M54_VALIDATION: preview contains blocking findings';
    END IF;
    normalized_decl := preview -> 'evidence' -> 'normalized_declaration';
    action := preview -> 'summary' ->> 'action';
    old_work_required := COALESCE((preview -> 'summary' ->> 'old_work_policy_required')::boolean, false);
    old_work := COALESCE(effective_preconditions ->> 'old_work',
                         effective_preconditions ->> 'old_work_policy');
    IF current_found AND current_row.owner_oid <> owner_id
       AND NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M54_OWNER: only the declaration owner or operator may deploy this target';
    END IF;
    IF pgreact_internal.m54_is_package(canonical) THEN
        RETURN pgreact_internal.m54_package_deploy(canonical, effective_preconditions);
    END IF;
    IF normalized_decl IS NOT NULL THEN
        live_source := pgreact_internal.m54_source_fingerprint(normalized_decl);
        IF live_source IS DISTINCT FROM preview -> 'summary' ->> 'source_fingerprint' THEN
            RAISE EXCEPTION 'M54_REVIEW_TOKEN_STALE: source or executable dependency changed during deployment';
        END IF;
    END IF;
    IF current_found AND current_row.state = 'DEPLOYED' AND EXISTS (
        SELECT 1 FROM pgreact_internal.policy_set_members member
        JOIN pgreact_internal.policy_set_versions version USING (policy_set_version_id)
        JOIN pgreact_internal.policy_sets set USING (policy_set_id)
        WHERE version.state = 'DEPLOYED' AND member.package_owned
          AND member.member_kind = current_row.kind
          AND member.member_name = current_row.object_name) THEN
        RAISE EXCEPTION 'M54_PACKAGE_OWNED: replace the complete policy set';
    END IF;
    IF old_work_required AND old_work IS NULL THEN
        RAISE EXCEPTION 'M54_OLD_WORK_REQUIRED: choose DRAIN_OLD or CANCEL_OLD explicitly';
    END IF;
    IF old_work IS NOT NULL AND old_work NOT IN ('DRAIN_OLD', 'CANCEL_OLD') THEN
        RAISE EXCEPTION 'M54_OLD_WORK_POLICY: choose DRAIN_OLD or CANCEL_OLD';
    END IF;
    IF action = 'KEEP' THEN
        RETURN preview || jsonb_build_object('operation', 'deploy', 'state', 'deployed',
            'summary', preview -> 'summary' || jsonb_build_object(
                'read_only', false, 'reviewed', token_payload IS NOT NULL,
                'old_work_policy', old_work));
    END IF;
    IF action = 'REPLACE' AND current_found AND current_row.state = 'DEPLOYED' THEN
        IF (canonical).kind = 'rule' THEN
            condition_oid := to_regclass(normalized_decl -> 'spec' ->> 'condition');
            SELECT pgreact_internal.replace_pack_rule(
                current_row.delegated_id, (canonical).name, condition_oid,
                ARRAY[(normalized_decl -> 'spec' ->> 'semantic_key')::name],
                normalized_decl -> 'spec' ->> 'kind',
                (normalized_decl -> 'spec' ->> 'on_activate')::regprocedure,
                (normalized_decl -> 'spec' ->> 'on_deactivate')::regprocedure,
                (normalized_decl -> 'spec' ->> 'on_change')::regprocedure,
                normalized_decl -> 'spec' ->> 'bootstrap_policy',
                pgreact_internal.m54_name_array(normalized_decl -> 'spec', 'change_columns'),
                COALESCE((normalized_decl -> 'spec' ->> 'salience')::integer, 0),
                COALESCE(normalized_decl -> 'spec' ->> 'agenda_group', 'default'),
                pgreact_internal.m54_name_array(normalized_decl -> 'spec', 'conflict_key_columns'),
                COALESCE((normalized_decl -> 'spec' ->> 'max_attempts')::integer, 1),
                COALESCE((normalized_decl -> 'spec' ->> 'initial_backoff_seconds')::integer, 1),
                COALESCE((normalized_decl -> 'spec' ->> 'backoff_multiplier')::numeric, 2),
                COALESCE((normalized_decl -> 'spec' ->> 'max_backoff_seconds')::integer, 60),
                COALESCE(old_work, 'DRAIN_OLD')) INTO new_delegated_id;
            current_row.delegated_id := new_delegated_id;
        ELSIF (canonical).kind = 'decision_program' THEN
            candidate_oid := to_regclass(normalized_decl -> 'spec' ->> 'candidate_relation');
            result_columns := ARRAY(SELECT value::name FROM jsonb_array_elements_text(
                normalized_decl -> 'spec' -> 'results') value);
            SELECT pgreact_internal.m54_replace_decision(
                current_row.delegated_id, (canonical).name, candidate_oid,
                (normalized_decl -> 'spec' ->> 'subject_key')::name,
                (normalized_decl -> 'spec' ->> 'candidate_key')::name,
                (normalized_decl -> 'spec' ->> 'priority')::name, result_columns,
                COALESCE((normalized_decl -> 'spec' ->> 'valid_from')::timestamptz, clock_timestamp()),
                NULLIF(normalized_decl -> 'spec' ->> 'valid_to', '')::timestamptz,
                COALESCE((normalized_decl -> 'spec' ->> 'max_candidates')::integer, 1000))
            INTO new_delegated_id;
            current_row.delegated_id := new_delegated_id;
        ELSE
            RAISE EXCEPTION 'M54_KIND: ordinary replacement supports rule and decision_program';
        END IF;
    ELSE
        IF (canonical).kind = 'rule' THEN
            condition_oid := to_regclass(normalized_decl -> 'spec' ->> 'condition');
            new_delegated_id := pgreact_api.author_rule(
                (canonical).name, condition_oid,
                (normalized_decl -> 'spec' ->> 'semantic_key')::name,
                normalized_decl -> 'spec' ->> 'kind', normalized_decl -> 'spec' ->> 'on_activate',
                normalized_decl -> 'spec' ->> 'on_deactivate', normalized_decl -> 'spec' ->> 'on_change',
                normalized_decl -> 'spec' ->> 'bootstrap_policy',
                pgreact_internal.m54_name_array(normalized_decl -> 'spec', 'change_columns'),
                COALESCE((normalized_decl -> 'spec' ->> 'salience')::integer, 0),
                COALESCE(normalized_decl -> 'spec' ->> 'agenda_group', 'default'),
                pgreact_internal.m54_name_array(normalized_decl -> 'spec', 'conflict_key_columns'),
                COALESCE((normalized_decl -> 'spec' ->> 'max_attempts')::integer, 1),
                COALESCE((normalized_decl -> 'spec' ->> 'initial_backoff_seconds')::integer, 1),
                COALESCE((normalized_decl -> 'spec' ->> 'backoff_multiplier')::numeric, 2),
                COALESCE((normalized_decl -> 'spec' ->> 'max_backoff_seconds')::integer, 60));
            current_row.delegated_id := new_delegated_id;
        ELSIF (canonical).kind = 'decision_program' THEN
            candidate_oid := to_regclass(normalized_decl -> 'spec' ->> 'candidate_relation');
            result_columns := ARRAY(SELECT value::name FROM jsonb_array_elements_text(
                normalized_decl -> 'spec' -> 'results') value);
            new_delegated_id := pgreact_api.author_decision_program(
                (canonical).name, candidate_oid,
                (normalized_decl -> 'spec' ->> 'subject_key')::name,
                (normalized_decl -> 'spec' ->> 'candidate_key')::name,
                (normalized_decl -> 'spec' ->> 'priority')::name, result_columns,
                COALESCE((normalized_decl -> 'spec' ->> 'valid_from')::timestamptz, clock_timestamp()),
                NULLIF(normalized_decl -> 'spec' ->> 'valid_to', '')::timestamptz,
                COALESCE((normalized_decl -> 'spec' ->> 'max_candidates')::integer, 1000));
            current_row.delegated_id := new_delegated_id;
        ELSE
            RETURN pgreact.deploy_m53(canonical, effective_preconditions);
        END IF;
    END IF;
    IF current_found THEN
        UPDATE pgreact_internal.api_declarations
        SET api_version = (canonical).api_version, spec = (canonical).spec,
            normalized = normalized_decl,
            declaration_digest = decode(preview -> 'summary' ->> 'proposed_declaration_digest', 'hex'),
            delegated_id = current_row.delegated_id, owner_oid = owner_id, state = 'DEPLOYED',
            last_preview_digest = decode(preview -> 'summary' ->> 'source_fingerprint', 'hex'),
            deployed_at = clock_timestamp(), removed_at = NULL
        WHERE declaration_id = current_row.declaration_id;
    ELSE
        INSERT INTO pgreact_internal.api_declarations(
            api_version, kind, object_name, spec, normalized, declaration_digest,
            delegated_id, owner_oid, state, last_preview_digest, deployed_at)
        VALUES ((canonical).api_version, (canonical).kind, (canonical).name,
            (canonical).spec, normalized_decl,
            decode(preview -> 'summary' ->> 'proposed_declaration_digest', 'hex'),
            current_row.delegated_id, owner_id, 'DEPLOYED',
            decode(preview -> 'summary' ->> 'source_fingerprint', 'hex'), clock_timestamp());
    END IF;
    RETURN preview || jsonb_build_object('operation', 'deploy', 'state', 'deployed',
        'summary', preview -> 'summary' || jsonb_build_object(
            'read_only', false, 'delegated_id', current_row.delegated_id,
            'reviewed', token_payload IS NOT NULL, 'old_work_policy', old_work));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_package_preview(declaration pgreact_api.declaration, options jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    result jsonb := pgreact_internal.m53_package_preview(declaration, options);
    normalized jsonb := result -> 'evidence' -> 'normalized_declaration';
    actions jsonb := COALESCE(result -> 'summary' -> 'action_plan', '[]'::jsonb);
    findings jsonb := COALESCE(result -> 'findings', '[]'::jsonb);
    blockers jsonb := '[]'::jsonb;
    action_row jsonb;
    member jsonb;
    child pgreact_api.declaration;
    current_digest text;
    proposed_digest text;
BEGIN
    result := result || jsonb_build_object(
        'summary', result -> 'summary' || jsonb_build_object(
            'proposed_declaration_digest', result -> 'summary' ->> 'definition_digest'));
    FOR action_row IN SELECT value FROM jsonb_array_elements(actions) value LOOP
        CONTINUE WHEN action_row ->> 'kind' NOT IN ('rule', 'decision_program');
        CONTINUE WHEN action_row ->> 'action' NOT IN ('KEEP', 'ADOPT');
        SELECT value INTO member
        FROM jsonb_array_elements(COALESCE(normalized -> 'spec' -> 'members', '[]'::jsonb)) value
        WHERE value ->> 'kind' = action_row ->> 'kind'
          AND value ->> 'name' = action_row ->> 'name'
          AND COALESCE(value ->> 'version', '1') = COALESCE(action_row ->> 'version', '1')
        LIMIT 1;
        CONTINUE WHEN member IS NULL OR jsonb_typeof(member -> 'declaration') <> 'object';
        child := pgreact_internal.m54_canonicalize_declaration(pgreact_api.declaration(
            member -> 'declaration' ->> 'kind', member -> 'declaration' ->> 'name',
            member -> 'declaration' -> 'spec'));
        proposed_digest := encode(sha256(convert_to(
            pgreact_internal.m28_normalize(child)::text, 'UTF8')), 'hex');
        SELECT encode(row_data.declaration_digest, 'hex') INTO current_digest
        FROM pgreact_internal.api_declarations row_data
        WHERE row_data.kind = action_row ->> 'kind'
          AND row_data.object_name = action_row ->> 'name'
          AND row_data.state = 'DEPLOYED';
        IF current_digest IS NOT NULL AND current_digest IS DISTINCT FROM proposed_digest THEN
            blockers := blockers || jsonb_build_array(pgreact_internal.m54_finding(
                'M54_PACKAGE_CHILD_CHANGE', 'ERROR', 'spec.members',
                'package preview cannot KEEP or ADOPT a changed child declaration',
                'Publish a new child version or replace the complete package.',
                jsonb_build_object('kind', action_row ->> 'kind', 'name', action_row ->> 'name',
                    'version', COALESCE(action_row ->> 'version', '1'),
                    'before_digest', current_digest, 'after_digest', proposed_digest)));
        END IF;
    END LOOP;
    IF jsonb_array_length(blockers) = 0 THEN
        RETURN result;
    END IF;
    actions := COALESCE((SELECT jsonb_agg(
        CASE WHEN item.value ->> 'kind' IN ('rule', 'decision_program')
                  AND item.value ->> 'action' IN ('KEEP', 'ADOPT')
             THEN item.value || jsonb_build_object('action', 'BLOCKED')
             ELSE item.value END ORDER BY item.ordinality)
        FROM jsonb_array_elements(actions) WITH ORDINALITY item(value, ordinality)), '[]'::jsonb);
    RETURN result || jsonb_build_object(
        'state', 'attention',
        'summary', result -> 'summary' || jsonb_build_object(
            'action_plan', actions,
            'blockers', COALESCE(result -> 'summary' -> 'blockers', '[]'::jsonb) || blockers),
        'findings', findings || blockers);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_preview(declaration pgreact_api.declaration, options jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    canonical pgreact_api.declaration := pgreact_internal.m54_canonicalize_declaration(declaration);
    base jsonb;
    normalized_decl jsonb;
    current_row pgreact_internal.api_declarations%ROWTYPE;
    current_found boolean;
    current_state text := 'absent';
    current_digest text;
    current_source text;
    source_fingerprint text;
    proposed_digest text;
    action text;
    work_state text := 'NOT_APPLICABLE';
    old_work_required boolean := false;
    old_kind text;
    plan_digest text;
    extra jsonb := '[]'::jsonb;
    filtered jsonb := '[]'::jsonb;
    item jsonb;
    source_name text;
    source_oid oid;
BEGIN
    IF pgreact_internal.m54_is_package(canonical) THEN
        RETURN pgreact_internal.m54_package_preview(canonical, options);
    END IF;
    base := pgreact.preview_m53(canonical, options);
    source_name := (canonical).spec ->> CASE WHEN (canonical).kind = 'rule'
                                             THEN 'condition' ELSE 'candidate_relation' END;
    BEGIN
        source_oid := to_regclass(source_name);
    EXCEPTION WHEN OTHERS THEN
        source_oid := NULL;
    END;
    FOR item IN SELECT value FROM jsonb_array_elements(COALESCE(base -> 'findings', '[]'::jsonb)) value LOOP
        IF (COALESCE(item ->> 'code', '') = 'M28_RELATION_NAME'
            OR item -> 'details' ->> 'source_code' = 'M28_RELATION_NAME')
           AND item ->> 'field' IN ('spec.condition', 'spec.candidate_relation')
           AND source_oid IS NOT NULL THEN
            CONTINUE;
        END IF;
        filtered := filtered || jsonb_build_array(item);
    END LOOP;
    base := base || jsonb_build_object(
        'state', CASE WHEN EXISTS (
            SELECT 1 FROM jsonb_array_elements(filtered) value
            WHERE value ->> 'severity' = 'ERROR') THEN 'attention' ELSE 'ready' END,
        'findings', filtered);
    normalized_decl := base -> 'evidence' -> 'normalized_declaration';
    BEGIN
        extra := pgreact_internal.m54_rule_findings(canonical);
    EXCEPTION WHEN OTHERS THEN
        extra := '[]'::jsonb;
    END;
    IF base ->> 'state' = 'attention' THEN
        RETURN base || jsonb_build_object('findings',
            COALESCE(base -> 'findings', '[]'::jsonb) || extra);
    END IF;
    SELECT * INTO current_row
    FROM pgreact_internal.api_declarations row_data
    WHERE row_data.kind = (canonical).kind
      AND row_data.object_name = (canonical).name;
    current_found := FOUND;
    IF current_found THEN
        current_state := lower(current_row.state);
        current_digest := encode(current_row.declaration_digest, 'hex');
        current_source := pgreact_internal.m54_source_fingerprint(current_row.normalized);
        work_state := pgreact_internal.m54_current_work(canonical, current_row);
        old_kind := CASE WHEN current_row.kind = 'rule'
                         THEN COALESCE(current_row.normalized -> 'spec' ->> 'kind', 'CONSTRAINT')
                         ELSE current_row.kind END;
    END IF;
    source_fingerprint := pgreact_internal.m54_source_fingerprint(normalized_decl);
    proposed_digest := encode(sha256(convert_to(normalized_decl::text, 'UTF8')), 'hex');
    action := CASE WHEN NOT current_found OR current_state <> 'deployed' THEN 'ADD'
                   WHEN current_digest = proposed_digest AND current_source = source_fingerprint
                   THEN 'KEEP' ELSE 'REPLACE' END;
    old_work_required := action = 'REPLACE'
        AND old_kind = 'COMMAND'
        AND work_state IN ('PENDING', 'LEASED', 'RETRY_WAIT');
    plan_digest := encode(sha256(convert_to(jsonb_build_object(
        'kind', (canonical).kind, 'name', (canonical).name,
        'normalized', normalized_decl, 'action', action,
        'current_state', current_state, 'current_digest', current_digest,
        'source_fingerprint', source_fingerprint, 'current_source_fingerprint', current_source,
        'work_state', work_state, 'old_work_required', old_work_required)::text, 'UTF8')), 'hex');
    RETURN base || jsonb_build_object(
        'state', CASE WHEN jsonb_array_length(extra) > 0 OR base ->> 'state' = 'attention'
                      THEN 'attention' ELSE 'ready' END,
        'summary', COALESCE(base -> 'summary', '{}'::jsonb) || jsonb_build_object(
            'action', action,
            'deployment', CASE action WHEN 'ADD' THEN 'create' WHEN 'KEEP' THEN 'keep'
                                      ELSE 'replacement' END,
            'current_state', current_state, 'current_declaration_digest', current_digest,
            'proposed_declaration_digest', proposed_digest,
            'source_fingerprint', source_fingerprint,
            'current_source_fingerprint', current_source,
            'work_state', work_state, 'current_effect_kind', old_kind,
            'old_work_policy_required', old_work_required, 'old_work_policy', NULL,
            'plan_digest', plan_digest,
            'legacy_preview_digest', base -> 'summary' ->> 'preview_digest',
            'blockers', CASE WHEN jsonb_array_length(extra) > 0 THEN extra
                             ELSE COALESCE(base -> 'summary' -> 'blockers', '[]'::jsonb) END),
        'findings', COALESCE(base -> 'findings', '[]'::jsonb) || extra);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_read_rule_model(source_schema name, source_relation name, key_column name, source_label text, work_enabled boolean, evidence_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    total_count bigint;
    null_count bigint;
    duplicate_count bigint;
    rows jsonb;
BEGIN
    EXECUTE format('SELECT count(*) FROM %I.%I', source_schema, source_relation)
        INTO total_count;
    EXECUTE format('SELECT count(*) FROM %I.%I WHERE %I IS NULL',
                   source_schema, source_relation, key_column) INTO null_count;
    IF null_count > 0 THEN
        RAISE EXCEPTION 'M34_SOURCE_DRIFT: rule source % contains null keys', source_label;
    END IF;
    EXECUTE format('SELECT count(*) FROM (SELECT %I FROM %I.%I GROUP BY %I HAVING count(*) > 1) duplicates',
                   key_column, source_schema, source_relation, key_column)
        INTO duplicate_count;
    IF duplicate_count > 0 THEN
        RAISE EXCEPTION 'M34_PROPOSAL_DUPLICATE: rule source % contains duplicate keys', source_label;
    END IF;
    EXECUTE format($query$
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'subject_key', s.%1$I::text, 'result_key', s.%1$I::text,
            'state', 'MATCH', 'value', to_jsonb(s),
            'work', jsonb_build_object('would_be_work', $2),
            'evidence', jsonb_build_object('source', $3, 'complete', true))
            ORDER BY s.%1$I), '[]'::jsonb)
        FROM (SELECT * FROM %2$I.%3$I ORDER BY %1$I LIMIT ($1 + 1)) s
    $query$, key_column, source_schema, source_relation)
    INTO rows USING evidence_limit, work_enabled, source_label;
    RETURN jsonb_build_object('rows', rows, 'rows_considered', total_count,
                              'truncated', total_count > evidence_limit);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_replace_decision(current_version_id uuid, program_name text, candidate_relation regclass, subject_key_column name, candidate_key_column name, priority_column name, result_columns name[], valid_from timestamp with time zone, valid_to timestamp with time zone, max_candidates integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    old_program pgreact_internal.decision_programs%ROWTYPE;
    old_version pgreact_internal.decision_program_versions%ROWTYPE;
    new_program_id uuid;
    next_version integer;
    next_version_id uuid;
    temporary_name text := program_name || '#m54-' || replace(gen_random_uuid()::text, '-', '');
    frontier timestamptz;
BEGIN
    SELECT program.* INTO STRICT old_program
    FROM pgreact_internal.decision_programs program
    JOIN pgreact_internal.decision_program_versions version USING (program_id)
    WHERE version.version_id = current_version_id
    FOR UPDATE;
    SELECT * INTO STRICT old_version
    FROM pgreact_internal.decision_program_versions
    WHERE version_id = current_version_id
    FOR UPDATE;
    IF NOT pg_has_role(session_user, old_program.owner_oid, 'USAGE')
       AND NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M54_OWNER: only the decision owner or operator may replace this target';
    END IF;
    UPDATE pgreact_internal.decision_programs
    SET program_name = temporary_name WHERE program_id = old_program.program_id;
    next_version_id := pgreact_api.author_decision_program(
        program_name, candidate_relation, subject_key_column, candidate_key_column,
        priority_column, result_columns, valid_from, valid_to, max_candidates);
    SELECT version.program_id INTO new_program_id
    FROM pgreact_internal.decision_program_versions version
    WHERE version.version_id = next_version_id;
    SELECT COALESCE(max(version_no), 0) + 1 INTO next_version
    FROM pgreact_internal.decision_program_versions version
    WHERE version.program_id = old_program.program_id;
    UPDATE pgreact_internal.decision_program_versions
    SET program_id = old_program.program_id, version_no = next_version
    WHERE version_id = next_version_id;
    UPDATE pgreact_internal.decision_program_versions
    SET state = 'RETIRED'
    WHERE program_id = old_program.program_id AND version_id <> next_version_id;
    DELETE FROM pgreact_internal.decision_programs
    WHERE program_id = new_program_id;
    UPDATE pgreact_internal.decision_programs
    SET program_name = old_program.program_name, state = old_program.state
    WHERE program_id = old_program.program_id;
    SELECT clock.frontier INTO frontier
    FROM pgreact_internal.clock_frontier clock;
    PERFORM pgreact_internal.refresh_decision_program(old_program.program_id, frontier);
    PERFORM pgreact_internal.maybe_fail_pack('programs');
    RETURN next_version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_rule_findings(declaration pgreact_api.declaration)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    spec jsonb := (declaration).spec;
    source_oid oid := to_regclass(spec ->> 'condition');
    field text;
    column_name name;
    columns jsonb;
    findings jsonb := '[]'::jsonb;
    field_count integer;
BEGIN
    IF (declaration).kind IS DISTINCT FROM 'rule' THEN
        RETURN findings;
    END IF;
    FOREACH field IN ARRAY ARRAY['change_columns', 'conflict_key_columns'] LOOP
        IF spec ? field THEN
            columns := spec -> field;
            IF jsonb_typeof(columns) IS DISTINCT FROM 'array' THEN
                findings := findings || jsonb_build_array(pgreact_internal.m54_finding(
                    'M54_COLUMNS_SHAPE', 'ERROR', 'spec.' || field,
                    field || ' must be an array of column names',
                    'Use ARRAY[...]::name[] or omit the field.'));
                CONTINUE;
            END IF;
            field_count := jsonb_array_length(columns);
            IF field_count > 32 THEN
                findings := findings || jsonb_build_array(pgreact_internal.m54_finding(
                    'M54_COLUMNS_LIMIT', 'ERROR', 'spec.' || field,
                    field || ' may contain at most 32 columns',
                    'Split the rule or choose a smaller projected set.'));
            END IF;
            IF EXISTS (
                SELECT 1 FROM jsonb_array_elements(columns) item
                WHERE jsonb_typeof(item) IS DISTINCT FROM 'string') THEN
                findings := findings || jsonb_build_array(pgreact_internal.m54_finding(
                    'M54_COLUMNS_NAME', 'ERROR', 'spec.' || field,
                    field || ' entries must be strings',
                    'Use PostgreSQL column names.'));
                CONTINUE;
            END IF;
            IF EXISTS (
                SELECT 1 FROM jsonb_array_elements_text(columns) item
                GROUP BY item HAVING count(*) > 1) THEN
                findings := findings || jsonb_build_array(pgreact_internal.m54_finding(
                    'M54_COLUMNS_DUPLICATE', 'ERROR', 'spec.' || field,
                    field || ' must not contain duplicate columns',
                    'Keep each projected column once.'));
            END IF;
            IF source_oid IS NOT NULL AND EXISTS (
                SELECT 1 FROM jsonb_array_elements_text(columns) item
                WHERE NOT EXISTS (
                    SELECT 1 FROM pg_catalog.pg_attribute attribute
                    WHERE attribute.attrelid = source_oid
                      AND attribute.attname = item::name
                      AND attribute.attnum > 0
                      AND NOT attribute.attisdropped)) THEN
                findings := findings || jsonb_build_array(pgreact_internal.m54_finding(
                    'M54_COLUMNS_NOT_PROJECTED', 'ERROR', 'spec.' || field,
                    field || ' must contain only columns projected by the condition',
                    'Add the column to the condition view or remove it.'));
            END IF;
        END IF;
    END LOOP;
    IF spec ? 'change_columns' AND jsonb_typeof(spec -> 'change_columns') = 'array'
       AND jsonb_array_length(spec -> 'change_columns') > 0
       AND source_oid IS NOT NULL
       AND EXISTS (
           SELECT 1 FROM jsonb_array_elements_text(spec -> 'change_columns') item
           WHERE item::name = (spec ->> 'semantic_key')::name) THEN
        findings := findings || jsonb_build_array(pgreact_internal.m54_finding(
            'M54_SEMANTIC_KEY_WATCHED', 'ERROR', 'spec.change_columns',
            'semantic_key cannot also be a watched change column',
            'Watch a non-key projected value instead.'));
    END IF;
    RETURN findings;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_source_fingerprint(normalized jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    field text;
    identity text;
    object_oid oid;
    function_oid oid;
    parts text := 'm54-source-fingerprint-v2';
BEGIN
    IF normalized IS NULL THEN
        RETURN NULL;
    END IF;
    FOREACH field IN ARRAY ARRAY[
        'condition', 'candidate_relation', 'population_relation',
        'candidate_catalog', 'parameter_relation'
    ] LOOP
        identity := normalized -> 'spec' ->> field;
        IF identity IS NULL THEN
            CONTINUE;
        END IF;
        object_oid := to_regclass(identity);
        IF object_oid IS NULL THEN
            parts := parts || '|' || field || '=missing:' || identity;
        ELSE
            PERFORM pgreact_internal.m54_require_source(object_oid, identity);
            parts := parts || '|' || field || '=' ||
                pgreact_internal.m54_relation_identity(object_oid) || ':' ||
                pgreact_internal.m54_dependency_signature(object_oid);
        END IF;
    END LOOP;
    FOREACH field IN ARRAY ARRAY['on_activate', 'on_deactivate', 'on_change'] LOOP
        identity := normalized -> 'spec' ->> field;
        IF identity IS NULL THEN
            CONTINUE;
        END IF;
        function_oid := to_regprocedure(identity);
        IF function_oid IS NULL THEN
            parts := parts || '|' || field || '=missing:' || identity;
        ELSE
            parts := parts || '|' || field || '=' ||
                pgreact_internal.m54_function_identity(function_oid) || ':' ||
                pg_get_functiondef(function_oid) || ':' ||
                COALESCE((SELECT proowner::text || ':' || prosecdef::text || ':' || provolatile::text
                          FROM pg_proc WHERE oid = function_oid), '');
        END IF;
    END LOOP;
    RETURN encode(sha256(convert_to(parts, 'UTF8')), 'hex');
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_sync_grants(old_roles oid[] DEFAULT ARRAY[]::oid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    author_oid oid;
    operator_oid oid;
    reader_oid oid;
    role_oid oid;
BEGIN
    SELECT application_role.role_oid INTO author_oid
    FROM pgreact_internal.application_roles AS application_role
    WHERE application_role.role_kind = 'author';
    SELECT application_role.role_oid INTO operator_oid
    FROM pgreact_internal.application_roles AS application_role
    WHERE application_role.role_kind = 'operator';
    SELECT application_role.role_oid INTO reader_oid
    FROM pgreact_internal.application_roles AS application_role
    WHERE application_role.role_kind = 'reader';
    FOREACH role_oid IN ARRAY COALESCE(old_roles, ARRAY[]::oid[]) LOOP
        CONTINUE WHEN role_oid IS NULL OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE oid = role_oid);
        EXECUTE format('REVOKE ALL ON FUNCTION pgreact.review_token(jsonb), pgreact.deploy(pgreact_api.declaration,text,jsonb), pgreact_api.deploy(pgreact_api.declaration,text,jsonb), pgreact.reconcile_rule(text,text), pgreact.sweep_expired_leases(text), pgreact.requeue_episode(text,text) FROM %I', role_oid::regrole::text);
    END LOOP;
    IF author_oid IS NOT NULL THEN
        EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact.review_token(jsonb), pgreact.deploy(pgreact_api.declaration,text,jsonb), pgreact_api.deploy(pgreact_api.declaration,text,jsonb), pgreact.validate(pgreact_api.declaration), pgreact.preview(pgreact_api.declaration,jsonb), pgreact.deploy(pgreact_api.declaration,jsonb), pgreact.export(text,text,text) TO %I', author_oid::regrole::text);
    END IF;
    IF reader_oid IS NOT NULL THEN
        EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact.review_token(jsonb), pgreact.validate(pgreact_api.declaration), pgreact.export(text,text,text) TO %I', reader_oid::regrole::text);
    END IF;
    IF operator_oid IS NOT NULL THEN
        EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact.reconcile_rule(text,text), pgreact.sweep_expired_leases(text), pgreact.requeue_episode(text,text) TO %I', operator_oid::regrole::text);
    END IF;
    FOREACH role_oid IN ARRAY ARRAY[author_oid, operator_oid, reader_oid] LOOP
        CONTINUE WHEN role_oid IS NULL;
        EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact.compare(pgreact_api.declaration,pgreact_api.target,jsonb), pgreact.compare_results(pgreact_api.declaration,pgreact_api.target,jsonb), pgreact_internal.m54_read_rule_model(name,name,name,text,boolean,integer), pgreact_internal.m54_read_decision_model(name,name,name,name,name,name[],integer,text,integer), pgreact_internal.m54_decision_result(jsonb,name[]) TO %I', role_oid::regrole::text);
        EXECUTE format('GRANT EXECUTE ON FUNCTION pgreact_internal.m34_authoritative_checksum(), pgreact_internal.m34_delta(jsonb,jsonb), pgreact_internal.m34_raw_rows(jsonb,bigint,integer), pgreact_internal.m34_finding(text,text,text,text,text,text,jsonb) TO %I', role_oid::regrole::text);
    END LOOP;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m54_validate(declaration pgreact_api.declaration)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    canonical pgreact_api.declaration := pgreact_internal.m54_canonicalize_declaration(declaration);
    result jsonb := pgreact.validate_m53(canonical);
    findings jsonb := COALESCE(result -> 'findings', '[]'::jsonb);
    extra jsonb := '[]'::jsonb;
    source_name text;
    source_oid oid;
    field text;
    item jsonb;
    filtered jsonb := '[]'::jsonb;
    source_error text;
BEGIN
    BEGIN
        extra := pgreact_internal.m54_rule_findings(canonical);
    EXCEPTION WHEN OTHERS THEN
        extra := '[]'::jsonb;
    END;
    FOR item IN SELECT value FROM jsonb_array_elements(findings) value LOOP
        IF (COALESCE(item ->> 'code', '') = 'M28_RELATION_NAME'
            OR item -> 'details' ->> 'source_code' = 'M28_RELATION_NAME')
           AND item ->> 'field' IN ('spec.condition', 'spec.candidate_relation') THEN
            field := split_part(item ->> 'field', '.', 2);
            source_name := (canonical).spec ->> field;
            BEGIN
                source_oid := to_regclass(source_name);
            EXCEPTION WHEN OTHERS THEN
                source_oid := NULL;
            END;
            CONTINUE WHEN source_oid IS NOT NULL;
        END IF;
        filtered := filtered || jsonb_build_array(item);
    END LOOP;
    findings := filtered || extra;
    IF (canonical).kind IN ('rule', 'decision_program') THEN
        field := CASE WHEN (canonical).kind = 'rule' THEN 'condition' ELSE 'candidate_relation' END;
        source_name := (canonical).spec ->> field;
        BEGIN
            source_oid := to_regclass(source_name);
        EXCEPTION WHEN OTHERS THEN
            source_oid := NULL;
        END;
        IF source_oid IS NOT NULL THEN
            BEGIN
                PERFORM pgreact_internal.m54_require_source(source_oid, source_name);
            EXCEPTION WHEN OTHERS THEN
                source_error := SQLERRM;
                findings := findings || jsonb_build_array(pgreact_internal.m54_finding(
                    split_part(source_error, ':', 1), 'ERROR', 'spec.' || field,
                    source_error, 'Use a caller-readable source without transitive RLS or SECURITY DEFINER dependencies.'));
            END;
        END IF;
    END IF;
    RETURN result
        || jsonb_build_object(
            'state', CASE WHEN EXISTS (
                SELECT 1 FROM jsonb_array_elements(findings) value
                WHERE value ->> 'severity' = 'ERROR')
                THEN 'attention' ELSE 'ready' END,
            'findings', findings,
            'evidence', COALESCE(result -> 'evidence', '{}'::jsonb)
                || jsonb_build_object('normalized_declaration', jsonb_build_object(
                    'api_version', (canonical).api_version,
                    'kind', (canonical).kind,
                    'name', (canonical).name,
                    'spec', (canonical).spec)));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.m55_source_checksum(normalized jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE source_name text;
    source_oid oid;
    key_column name;
BEGIN
    source_name := CASE normalized ->> 'kind'
        WHEN 'rule' THEN normalized -> 'spec' ->> 'condition'
        WHEN 'decision_program' THEN normalized -> 'spec' ->> 'candidate_relation'
        WHEN 'policy_set' THEN normalized -> 'spec' -> 'applicability' ->> 'relation'
    END;
    key_column := CASE normalized ->> 'kind'
        WHEN 'rule' THEN (normalized -> 'spec' ->> 'semantic_key')::name
        WHEN 'decision_program' THEN (normalized -> 'spec' ->> 'candidate_key')::name
        WHEN 'policy_set' THEN
            (normalized -> 'spec' -> 'applicability' -> 'subject_keys' ->> 0)::name
    END;
    source_oid := to_regclass(source_name);
    IF source_oid IS NULL OR key_column IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN pgreact_internal.m35_source_checksum(source_oid, key_column);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.maintain_derived_support_m7(target_rule_version uuid, target_activation uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    derivation pgreact_internal.derivation_rule_versions%ROWTYPE;
    activation pgreact_internal.activation_state%ROWTYPE;
    old_support record;
    projected jsonb;
    canonical bytea;
    target_fact_id uuid;
    target_support_id uuid;
    frontier_value bigint;
    clean_binding jsonb;
BEGIN
    SELECT d.* INTO derivation
    FROM pgreact_internal.derivation_rule_versions d
    JOIN pgreact_internal.rule_versions v USING (rule_version_id)
    WHERE d.rule_version_id = target_rule_version AND v.rule_kind = 'DERIVATION';
    IF NOT FOUND THEN RETURN; END IF;
    SELECT * INTO activation
    FROM pgreact_internal.activation_state
    WHERE rule_version_id = target_rule_version AND activation_id = target_activation;
    IF NOT FOUND THEN RETURN; END IF;
    IF activation.active THEN
        clean_binding := activation.current_bindings - '__pgt_row_id';
        projected := pgreact_internal.project_derived_fact(
            derivation.relation_version_id, clean_binding);
        canonical := pgreact_internal.canonical_bigint_v1(activation.semantic_key);
        target_fact_id := pgreact_internal.activation_uuid(
            pgreact_internal.activation_digest(derivation.relation_version_id, canonical));
        target_support_id := pgreact_internal.activation_uuid(sha256(convert_to(
            target_rule_version::text || ':' || target_activation::text || ':' ||
            activation.generation || ':' || activation.revision || ':' || target_fact_id::text,
            'UTF8')));
        IF EXISTS (
            SELECT 1 FROM pgreact_internal.derived_supports s
            WHERE s.relation_version_id = derivation.relation_version_id
              AND s.semantic_key = activation.semantic_key AND s.active
              AND s.support_id <> target_support_id AND s.fact IS DISTINCT FROM projected
        ) THEN
            RAISE EXCEPTION 'conflicting derived payloads for % key %',
                derivation.relation_version_id, activation.semantic_key;
        END IF;
    END IF;
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.derived_supports s
        WHERE s.rule_version_id = target_rule_version
          AND s.activation_id = target_activation AND s.active
          AND (NOT activation.active OR s.support_id <> target_support_id)
    ) OR (activation.active AND NOT EXISTS (
        SELECT 1 FROM pgreact_internal.derived_supports s
        WHERE s.support_id = target_support_id AND s.active
          AND s.source_binding = clean_binding AND s.fact = projected
    )) THEN
        frontier_value := pgreact_internal.advance_derived_frontier(derivation.relation_version_id);
    ELSE
        RETURN;
    END IF;
    FOR old_support IN
        UPDATE pgreact_internal.derived_supports
        SET active = false, last_frontier = frontier_value,
            invalidated_at = clock_timestamp()
        WHERE rule_version_id = target_rule_version
          AND activation_id = target_activation AND active
          AND (NOT activation.active OR support_id <> target_support_id)
        RETURNING relation_version_id, semantic_key
    LOOP
        PERFORM pgreact_internal.recompute_derived_fact(
            old_support.relation_version_id, old_support.semantic_key, frontier_value);
    END LOOP;
    IF activation.active THEN
        INSERT INTO pgreact_internal.derived_supports (
            support_id, relation_version_id, rule_version_id, activation_id,
            activation_generation, activation_revision, semantic_key, fact_id,
            fact, source_binding, active, first_frontier
        ) VALUES (
            target_support_id, derivation.relation_version_id, target_rule_version,
            target_activation, activation.generation, activation.revision,
            activation.semantic_key, target_fact_id, projected,
            clean_binding, true, frontier_value
        )
        ON CONFLICT (support_id) DO UPDATE SET
            fact = EXCLUDED.fact, source_binding = EXCLUDED.source_binding,
            active = true, last_frontier = NULL, invalidated_at = NULL;
        PERFORM pgreact_internal.recompute_derived_fact(
            derivation.relation_version_id, activation.semantic_key, frontier_value);
    END IF;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.maintain_derived_support_m8(target_rule_version uuid, target_activation uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    program_rule record;
    activation pgreact_internal.activation_state%ROWTYPE;
    old_support record;
    input_row record;
    input_fact_id uuid;
    input_ready boolean := true;
    projected jsonb;
    clean_binding jsonb;
    canonical bytea;
    target_fact_id uuid;
    target_logical_support_id uuid;
    target_support_id uuid;
    frontier_value bigint;
BEGIN
    SELECT pr.*, pv.frontier AS program_frontier
    INTO program_rule
    FROM pgreact_internal.derivation_program_rules pr
    JOIN pgreact_internal.derivation_program_versions pv USING (program_version_id)
    WHERE pr.rule_version_id = target_rule_version AND pv.state = 'ACTIVE'
    ORDER BY pv.created_at DESC LIMIT 1;
    IF NOT FOUND THEN
        PERFORM pgreact_internal.maintain_derived_support_m7(
            target_rule_version, target_activation);
        RETURN;
    END IF;
    SELECT * INTO activation
    FROM pgreact_internal.activation_state
    WHERE rule_version_id = target_rule_version
      AND activation_id = target_activation;
    IF NOT FOUND THEN RETURN; END IF;

    IF activation.active THEN
        clean_binding := activation.current_bindings - '__pgt_row_id';
        projected := pgreact_internal.project_derived_fact(
            program_rule.target_relation_version_id, clean_binding);
        canonical := pgreact_internal.canonical_bigint_v1(activation.semantic_key);
        target_fact_id := pgreact_internal.activation_uuid(
            pgreact_internal.activation_digest(
                program_rule.target_relation_version_id, canonical));
        target_logical_support_id := pgreact_internal.activation_uuid(sha256(convert_to(
            target_rule_version::text || ':' || target_activation::text || ':' ||
            target_fact_id::text, 'UTF8')));
        target_support_id := pgreact_internal.activation_uuid(sha256(convert_to(
            target_rule_version::text || ':' || target_activation::text || ':' ||
            activation.generation || ':' || activation.revision || ':' ||
            target_fact_id::text, 'UTF8')));
        FOR input_row IN
            SELECT * FROM pgreact_internal.derivation_program_inputs
            WHERE program_version_id = program_rule.program_version_id
              AND rule_version_id = target_rule_version
            ORDER BY input_order
        LOOP
            IF clean_binding ->> input_row.key_column IS NULL
               OR (clean_binding ->> input_row.key_column)::bigint
                    IS DISTINCT FROM activation.semantic_key THEN
                RAISE EXCEPTION 'program rule % input key % must equal output key %',
                    program_rule.rule_name, input_row.key_column,
                    activation.semantic_key;
            END IF;
            SELECT f.fact_id INTO input_fact_id
            FROM pgreact_internal.derived_facts f
            WHERE f.relation_version_id = input_row.relation_version_id
              AND f.semantic_key = activation.semantic_key;
            input_ready := input_ready AND FOUND;
        END LOOP;
    END IF;

    SELECT * INTO old_support
    FROM pgreact_internal.derived_supports s
    WHERE s.rule_version_id = target_rule_version
      AND s.activation_id = target_activation AND s.active;
    IF activation.active AND input_ready AND FOUND
       AND old_support.logical_support_id = target_logical_support_id
       AND old_support.support_id = target_support_id
       AND old_support.fact = projected
       AND old_support.source_binding = clean_binding
       AND old_support.activation_generation = activation.generation
       AND old_support.activation_revision = activation.revision
       AND NOT EXISTS (
            SELECT 1
            FROM pgreact_internal.derivation_program_inputs i
            LEFT JOIN pgreact_internal.derived_support_inputs si
              ON si.support_id = target_support_id
             AND si.input_order = i.input_order
             AND si.relation_version_id = i.relation_version_id
             AND si.semantic_key = activation.semantic_key
             AND si.fact_id = pgreact_internal.activation_uuid(
                 pgreact_internal.activation_digest(
                     i.relation_version_id,
                     pgreact_internal.canonical_bigint_v1(activation.semantic_key)))
            WHERE i.program_version_id = program_rule.program_version_id
              AND i.rule_version_id = target_rule_version
              AND si.support_id IS NULL
       ) THEN
        RETURN;
    END IF;
    IF old_support.support_id IS NULL AND (NOT activation.active OR NOT input_ready) THEN
        RETURN;
    END IF;

    frontier_value := pgreact_internal.advance_derived_frontier(
        program_rule.target_relation_version_id);
    IF old_support.support_id IS NOT NULL THEN
        UPDATE pgreact_internal.derived_supports
        SET active = false, grounded = false,
            last_frontier = frontier_value,
            invalidated_at = clock_timestamp()
        WHERE support_id = old_support.support_id;
        PERFORM pgreact_internal.recompute_derived_fact(
            old_support.relation_version_id,
            old_support.semantic_key, frontier_value);
    END IF;
    IF NOT activation.active OR NOT input_ready THEN RETURN; END IF;
    IF EXISTS (
        SELECT 1 FROM pgreact_internal.derived_supports s
        WHERE s.relation_version_id = program_rule.target_relation_version_id
          AND s.semantic_key = activation.semantic_key AND s.active
          AND s.support_id <> target_support_id
          AND s.fact IS DISTINCT FROM projected
    ) THEN
        RAISE EXCEPTION 'conflicting derived payloads for % key %',
            program_rule.target_relation_version_id, activation.semantic_key;
    END IF;
    INSERT INTO pgreact_internal.derived_supports (
        support_id, logical_support_id, relation_version_id, rule_version_id, activation_id,
        activation_generation, activation_revision, semantic_key, fact_id,
        fact, source_binding, active, first_frontier, program_version_id,
        grounded, support_frontier
    ) VALUES (
        target_support_id, target_logical_support_id,
        program_rule.target_relation_version_id,
        target_rule_version, target_activation, activation.generation,
        activation.revision, activation.semantic_key, target_fact_id,
        projected, clean_binding, true, frontier_value,
        program_rule.program_version_id, true,
        COALESCE(NULLIF(pg_catalog.current_setting(
            'pgreact.program_support_frontier', true), '')::bigint,
            program_rule.program_frontier + 1)
    )
    ON CONFLICT (support_id) DO UPDATE SET
        fact = EXCLUDED.fact,
        source_binding = EXCLUDED.source_binding,
        active = true,
        last_frontier = NULL,
        invalidated_at = NULL,
        program_version_id = EXCLUDED.program_version_id,
        grounded = true,
        support_frontier = EXCLUDED.support_frontier;
    DELETE FROM pgreact_internal.derived_support_inputs
    WHERE support_id = target_support_id;
    FOR input_row IN
        SELECT * FROM pgreact_internal.derivation_program_inputs
        WHERE program_version_id = program_rule.program_version_id
          AND rule_version_id = target_rule_version
        ORDER BY input_order
    LOOP
        input_fact_id := pgreact_internal.activation_uuid(
            pgreact_internal.activation_digest(
                input_row.relation_version_id,
                pgreact_internal.canonical_bigint_v1(activation.semantic_key)));
        INSERT INTO pgreact_internal.derived_support_inputs (
            support_id, input_order, relation_version_id,
            semantic_key, fact_id
        ) VALUES (
            target_support_id, input_row.input_order,
            input_row.relation_version_id, activation.semantic_key,
            input_fact_id
        );
    END LOOP;
    PERFORM pgreact_internal.recompute_derived_fact(
        program_rule.target_relation_version_id,
        activation.semantic_key, frontier_value);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.managed_cycle_m44(process_pid integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    worker text := format('pg-react-managed/%s/%s', current_database(), process_pid);
    batch_limit integer := current_setting('pg_react.batch_size')::integer;
    claim_limit integer := least(batch_limit, 100);
    pending_limit integer := current_setting('pg_react.max_pending_jobs')::integer;
    pending bigint;
    processed bigint := 0;
    claimed record;
    runtime_state text := 'ready';
    process_detail text;
    run_result jsonb;
    blocked boolean := false;
BEGIN
    SELECT count(*) INTO pending
    FROM pgreact_internal.agenda job
    WHERE job.state IN ('PENDING', 'LEASED', 'RETRY_WAIT');
    INSERT INTO pgreact_internal.managed_processes (
        database_oid, database_name, backend_pid, state, protocol, pending_jobs)
    VALUES (
        (SELECT oid FROM pg_database WHERE datname = current_database()),
        current_database(), process_pid, 'ready', 2, pending)
    ON CONFLICT (database_oid) DO UPDATE
    SET database_name = EXCLUDED.database_name,
        backend_pid = EXCLUDED.backend_pid,
        state = EXCLUDED.state,
        protocol = EXCLUDED.protocol,
        pending_jobs = EXCLUDED.pending_jobs,
        started_at = CASE
            WHEN pgreact_internal.managed_processes.backend_pid = EXCLUDED.backend_pid
            THEN pgreact_internal.managed_processes.started_at
            ELSE clock_timestamp() END,
        heartbeat_at = clock_timestamp(), detail = NULL;

    IF pg_is_in_recovery() THEN
        runtime_state := 'standby';
    ELSIF NOT pgreact.worker_protocol_compatible(2) THEN
        runtime_state := 'error';
        process_detail := 'worker protocol 2 is incompatible';
    ELSE
        IF pending >= pending_limit THEN
            runtime_state := 'backpressure';
        ELSE
            BEGIN
                run_result := pgreact_api.run();
            EXCEPTION WHEN OTHERS THEN
                run_result := jsonb_build_object(
                    'runtime_state', 'BLOCKED',
                    'error', SQLSTATE || ': ' || SQLERRM);
            END;
            blocked := COALESCE(run_result ->> 'runtime_state', '') = 'BLOCKED'
                OR COALESCE(run_result #>> '{target_status,summary,runtime_state}', '') = 'BLOCKED'
                OR EXISTS (
                    SELECT 1
                    FROM jsonb_array_elements(
                        CASE WHEN jsonb_typeof(run_result -> 'policy_sets') = 'array'
                             THEN run_result -> 'policy_sets'
                             ELSE '[]'::jsonb END) item
                    WHERE item -> 'runtime' ->> 'runtime_state' = 'BLOCKED');
            IF blocked THEN
                runtime_state := 'error';
                process_detail := COALESCE(run_result ->> 'error', run_result::text);
            END IF;
        END IF;
        FOR claimed IN
            SELECT * FROM pgreact_api.claim(worker, claim_limit, interval '60 seconds')
        LOOP
            PERFORM pgreact_api.execute(
                claimed.episode_id, worker, claimed.lease_token);
            processed := processed + 1;
        END LOOP;
    END IF;
    SELECT count(*) INTO pending
    FROM pgreact_internal.agenda job
    WHERE job.state IN ('PENDING', 'LEASED', 'RETRY_WAIT');
    UPDATE pgreact_internal.managed_processes
    SET state = runtime_state,
        pending_jobs = pending,
        processed_jobs = processed_jobs + processed,
        heartbeat_at = clock_timestamp(),
        detail = process_detail
    WHERE database_oid = (
        SELECT oid FROM pg_database WHERE datname = current_database());
    RETURN jsonb_build_object(
        'state', runtime_state, 'pending_jobs', pending,
        'processed_jobs', processed, 'run', run_result,
        'runtime_state', CASE WHEN blocked THEN 'BLOCKED' END);
EXCEPTION WHEN OTHERS THEN
    INSERT INTO pgreact_internal.managed_processes (
        database_oid, database_name, backend_pid, state, protocol, detail)
    VALUES (
        (SELECT oid FROM pg_database WHERE datname = current_database()),
        current_database(), process_pid, 'error', 2, SQLSTATE || ': ' || SQLERRM)
    ON CONFLICT (database_oid) DO UPDATE
    SET backend_pid = EXCLUDED.backend_pid,
        state = 'error', heartbeat_at = clock_timestamp(), detail = EXCLUDED.detail;
    RETURN jsonb_build_object(
        'state', 'error', 'sqlstate', SQLSTATE, 'message', SQLERRM);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.mark_deadline_rule(target_version_id uuid, deadline_column name, bootstrap_policy text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    version_row pgreact_internal.rule_versions%ROWTYPE;
    frontier timestamptz;
    due_count bigint;
    index_name text := 'deadline_' || substring(replace(target_version_id::text, '-', ''), 1, 24);
BEGIN
    IF bootstrap_policy NOT IN ('SEED_CURRENT', 'REQUIRE_EMPTY') THEN
        RAISE EXCEPTION 'bootstrap policy must be SEED_CURRENT or REQUIRE_EMPTY';
    END IF;
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_version_id;
    SELECT clock.frontier INTO STRICT frontier
    FROM pgreact_internal.clock_frontier clock;

    INSERT INTO pgreact_internal.deadline_rules (rule_version_id, deadline_column)
    VALUES (target_version_id, deadline_column);
    EXECUTE format('CREATE INDEX %I ON %s (%I, %I)',
        index_name, version_row.match_relid::regclass,
        deadline_column, version_row.key_column);
    EXECUTE format('DROP TRIGGER pgreact_finalize ON %s',
        version_row.match_relid::regclass);
    EXECUTE format(
        'CREATE CONSTRAINT TRIGGER pgreact_finalize '
        'AFTER INSERT OR UPDATE OR DELETE ON %s '
        'DEFERRABLE INITIALLY DEFERRED FOR EACH ROW '
        'EXECUTE FUNCTION pgreact_internal.finalize_deadline_match_delta(%L)',
        version_row.match_relid::regclass, target_version_id::text);
    EXECUTE format('SELECT count(*) FROM %s WHERE %I <= $1',
        version_row.match_relid::regclass, deadline_column)
        INTO due_count USING frontier;
    IF bootstrap_policy = 'REQUIRE_EMPTY' AND due_count > 0 THEN
        RAISE EXCEPTION 'REQUIRE_EMPTY deadline source % currently has % due matches',
            version_row.source_view_name, due_count;
    END IF;
    EXECUTE format(
        'DELETE FROM pgreact_internal.activation_state activation '
        'WHERE activation.rule_version_id = $1 AND NOT EXISTS ('
        'SELECT 1 FROM %s candidate '
        'WHERE (to_jsonb(candidate) ->> %L)::bigint = activation.semantic_key '
        'AND (to_jsonb(candidate) ->> %L)::timestamptz <= $2)',
        version_row.match_relid::regclass,
        version_row.key_column::text,
        deadline_column::text
    ) USING target_version_id, frontier;
    UPDATE pgreact_internal.rule_versions
    SET bootstrap_policy = mark_deadline_rule.bootstrap_policy
    WHERE rule_version_id = target_version_id;
    RETURN target_version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.normalize_program(definition jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    normalized jsonb := pgreact_api.infer_program(definition);
    rule_item record;
    dependency record;
    derived pgreact_internal.keyed_derived_relations%ROWTYPE;
    dependency_derived pgreact_internal.keyed_derived_relations%ROWTYPE;
    wrapper regclass;
    source regclass;
BEGIN
    FOR rule_item IN
        SELECT value, ordinal
        FROM jsonb_array_elements(definition -> 'rules')
             WITH ORDINALITY rules(value, ordinal)
        ORDER BY ordinal
    LOOP
        SELECT * INTO derived
        FROM pgreact_internal.keyed_derived_relations
        WHERE public_name = rule_item.value ->> 'target';
        IF NOT FOUND THEN CONTINUE; END IF;
        source := to_regclass(rule_item.value ->> 'definition');
        IF source IS NULL THEN
            RAISE EXCEPTION 'M15_DERIVATION_SOURCE: definition view % does not exist',
                rule_item.value ->> 'definition';
        END IF;
        SELECT * INTO dependency_derived
        FROM pgreact_internal.keyed_derived_relations
        WHERE public_name = rule_item.value ->> 'definition';
        IF FOUND THEN
            wrapper := dependency_derived.internal_name::regclass;
        ELSE
            wrapper := pgreact_internal.create_key_wrapper(source, derived.key_columns);
        END IF;
        normalized := jsonb_set(normalized,
            ARRAY['rules', (rule_item.ordinal - 1)::text, 'definition'],
            to_jsonb(wrapper::text));
        normalized := jsonb_set(normalized,
            ARRAY['rules', (rule_item.ordinal - 1)::text, 'key'],
            to_jsonb('__pgreact_key'::text));
        normalized := jsonb_set(normalized,
            ARRAY['rules', (rule_item.ordinal - 1)::text, 'target'],
            to_jsonb(derived.internal_name));
        FOR dependency IN
            SELECT dependency_kind, dependency_value, dependency_ordinal
            FROM (
                SELECT 'inputs'::text, value, ordinal
                FROM jsonb_array_elements(COALESCE(normalized #> ARRAY[
                    'rules', (rule_item.ordinal - 1)::text, 'inputs'], '[]'::jsonb))
                     WITH ORDINALITY input(value, ordinal)
                UNION ALL
                SELECT 'negative_inputs'::text, value, ordinal
                FROM jsonb_array_elements(COALESCE(rule_item.value -> 'negative_inputs', '[]'::jsonb))
                     WITH ORDINALITY negative_input(value, ordinal)
            ) dependencies(dependency_kind, dependency_value, dependency_ordinal)
        LOOP
            source := to_regclass(dependency.dependency_value ->> 'relation');
            IF source IS NULL THEN
                RAISE EXCEPTION 'M15_DERIVATION_INPUT: relation % does not exist',
                    dependency.dependency_value ->> 'relation';
            END IF;
            SELECT * INTO dependency_derived
            FROM pgreact_internal.keyed_derived_relations
            WHERE public_name = dependency.dependency_value ->> 'relation';
            IF FOUND THEN
                wrapper := dependency_derived.internal_name::regclass;
            ELSE
                wrapper := pgreact_internal.create_key_wrapper(source, derived.key_columns);
            END IF;
            normalized := jsonb_set(normalized, ARRAY[
                'rules', (rule_item.ordinal - 1)::text, dependency.dependency_kind,
                (dependency.dependency_ordinal - 1)::text, 'relation'], to_jsonb(wrapper::text));
            normalized := jsonb_set(normalized, ARRAY[
                'rules', (rule_item.ordinal - 1)::text, dependency.dependency_kind,
                (dependency.dependency_ordinal - 1)::text, 'key'], to_jsonb('__pgreact_key'::text));
        END LOOP;
        IF rule_item.value -> 'aggregate_input' IS NOT NULL THEN
            source := to_regclass(rule_item.value #>> '{aggregate_input,relation}');
            IF source IS NULL THEN
                RAISE EXCEPTION 'M15_DERIVATION_INPUT: relation % does not exist',
                    rule_item.value #>> '{aggregate_input,relation}';
            END IF;
            SELECT * INTO dependency_derived
            FROM pgreact_internal.keyed_derived_relations
            WHERE public_name = rule_item.value #>> '{aggregate_input,relation}';
            IF FOUND THEN
                wrapper := dependency_derived.internal_name::regclass;
            ELSE
                wrapper := pgreact_internal.create_key_wrapper(source, derived.key_columns);
            END IF;
            IF (rule_item.value -> 'aggregate_input') ? 'function' THEN
                normalized := jsonb_set(normalized,
                    ARRAY['rules', (rule_item.ordinal - 1)::text,
                          'aggregate_input', 'public_relation'],
                    to_jsonb(rule_item.value #>> '{aggregate_input,relation}'));
            END IF;
            normalized := jsonb_set(normalized,
                ARRAY['rules', (rule_item.ordinal - 1)::text, 'aggregate_input', 'relation'],
                to_jsonb(wrapper::text));
            normalized := jsonb_set(normalized,
                ARRAY['rules', (rule_item.ordinal - 1)::text, 'aggregate_input', 'key'],
                to_jsonb('__pgreact_key'::text));
        END IF;
    END LOOP;
    RETURN normalized;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.pack_plan_digest(definition jsonb, mappings jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    material text := definition::text || E'\n' || mappings::text || E'\nowner:' || session_user;
    rule_item record;
    rule_name text;
    logical_identity text;
    mapped_identity text;
    object_oid oid;
    object_owner oid;
    current_version uuid;
    current_state text;
    current_match text;
    work_state jsonb;
    consequence record;
    active_pack_version uuid;
BEGIN
    SELECT v.pack_version_id INTO active_pack_version
    FROM pgreact_internal.rule_packs p
    JOIN pgreact_internal.rule_pack_versions v USING (pack_id)
    WHERE p.pack_name = definition ->> 'pack'
      AND p.owner_oid = (SELECT oid FROM pg_catalog.pg_roles WHERE rolname = session_user)
      AND v.state = 'ACTIVE';
    material := material || E'\nactive_pack:' || COALESCE(active_pack_version::text, '<none>');
    FOR rule_item IN
        SELECT value, ordinal FROM pg_catalog.jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY AS r(value, ordinal)
    LOOP
        rule_name := rule_item.value ->> 'name';
        logical_identity := rule_item.value ->> 'definition';
        mapped_identity := pgreact_internal.pack_mapping(mappings, 'objects', logical_identity);
        object_oid := pg_catalog.to_regclass(mapped_identity);
        SELECT relowner INTO object_owner FROM pg_catalog.pg_class WHERE oid = object_oid;
        SELECT v.rule_version_id, v.state, v.match_name
          INTO current_version, current_state, current_match
        FROM pgreact_internal.rules r JOIN pgreact_internal.rule_versions v USING (rule_id)
        WHERE r.rule_name = rule_name AND v.state <> 'REMOVED'
        ORDER BY v.created_at DESC LIMIT 1;
        SELECT COALESCE(jsonb_object_agg(state, total ORDER BY state), '{}'::jsonb) INTO work_state
        FROM (SELECT state, count(*) AS total FROM pgreact_internal.agenda
              WHERE rule_version_id = current_version GROUP BY state) AS q;
        material := material || format(E'\nrule:%s:%s:%s:%s:%s:%s:%s:%s',
            rule_item.ordinal, rule_name, object_oid, object_owner,
            encode(sha256(convert_to(pg_get_viewdef(object_oid, true), 'UTF8')), 'hex'),
            encode(pgreact_internal.source_row_signature(object_oid), 'hex'),
            COALESCE(current_version::text || ':' || current_state || ':' || current_match, '<add>'),
            work_state::text);
        FOR consequence IN
            SELECT identity FROM (VALUES
                (rule_item.value ->> 'on_activate'),
                (rule_item.value ->> 'on_deactivate'),
                (rule_item.value ->> 'on_change')
            ) AS typed(identity) WHERE identity IS NOT NULL
            UNION ALL
            SELECT value #>> '{}' FROM pg_catalog.jsonb_each(COALESCE(rule_item.value -> 'outbox', '{}'::jsonb))
        LOOP
            mapped_identity := pgreact_internal.pack_mapping(mappings, 'objects', consequence.identity);
            object_oid := pg_catalog.to_regprocedure(mapped_identity);
            SELECT proowner INTO object_owner FROM pg_catalog.pg_proc WHERE oid = object_oid;
            material := material || format(E'\nfunction:%s:%s:%s:%s', consequence.identity,
                object_oid, object_owner,
                encode(sha256(convert_to(pg_get_functiondef(object_oid), 'UTF8')), 'hex'));
        END LOOP;
    END LOOP;
    FOR rule_item IN
        SELECT value, ordinal FROM pg_catalog.jsonb_array_elements(definition -> 'remove')
        WITH ORDINALITY AS r(value, ordinal)
    LOOP
        rule_name := rule_item.value ->> 'name';
        SELECT m.rule_version_id, v.state, v.match_name
          INTO current_version, current_state, current_match
        FROM pgreact_internal.rule_packs p
        JOIN pgreact_internal.rule_pack_versions pv USING (pack_id)
        JOIN pgreact_internal.rule_pack_members m USING (pack_version_id)
        JOIN pgreact_internal.rule_versions v USING (rule_version_id)
        WHERE p.pack_name = definition ->> 'pack' AND pv.state = 'ACTIVE' AND m.rule_name = rule_name;
        SELECT COALESCE(jsonb_object_agg(state, total ORDER BY state), '{}'::jsonb) INTO work_state
        FROM (SELECT state, count(*) AS total FROM pgreact_internal.agenda
              WHERE rule_version_id = current_version GROUP BY state) AS q;
        material := material || format(E'\nremove:%s:%s:%s:%s:%s:%s', rule_item.ordinal,
            rule_name, current_version, current_state, current_match, work_state::text);
    END LOOP;
    RETURN encode(sha256(convert_to(material, 'UTF8')), 'hex');
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.parameter_family_dml_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE target_family_id uuid := TG_ARGV[0]::uuid;
    parameter_key bigint;
    values jsonb;
BEGIN
    IF NOT pgreact_internal.parameter_family_editor_allowed(target_family_id) THEN
        RAISE EXCEPTION 'M25_PARAMETER_EDITOR_FORBIDDEN: % cannot change parameter family %',
            session_user, target_family_id USING ERRCODE = '42501';
    END IF;
    IF TG_OP <> 'DELETE' THEN
        values := to_jsonb(NEW);
        parameter_key := (values ->> (SELECT parameter_key_column::text
            FROM pgreact_internal.parameter_families WHERE parameter_families.family_id = target_family_id))::bigint;
    ELSE
        values := to_jsonb(OLD);
        parameter_key := (values ->> (SELECT parameter_key_column::text
            FROM pgreact_internal.parameter_families WHERE parameter_families.family_id = target_family_id))::bigint;
    END IF;
    INSERT INTO pgreact_internal.parameter_family_events(
        family_id, event_kind, parameter_key, details)
    VALUES (
        target_family_id, 'PARAMETER_CHANGED', parameter_key,
        jsonb_build_object('operation', TG_OP,
                           'old', CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE
                               pgreact_internal.parameter_family_project(target_family_id, to_jsonb(OLD)) END,
                           'new', CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE
                               pgreact_internal.parameter_family_project(target_family_id, to_jsonb(NEW)) END));
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.parameter_family_project(target_family_id uuid, row_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE family_row pgreact_internal.parameter_families%ROWTYPE;
    column_name name;
    projected jsonb := '{}'::jsonb;
BEGIN
    IF row_data IS NULL THEN RETURN NULL; END IF;
    SELECT * INTO STRICT family_row FROM pgreact_internal.parameter_families
    WHERE family_id = target_family_id AND state = 'ACTIVE';
    FOREACH column_name IN ARRAY ARRAY[family_row.parameter_key_column] || family_row.parameter_value_columns LOOP
        projected := projected || jsonb_build_object(column_name::text, row_data -> (column_name::text));
    END LOOP;
    RETURN projected;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.pgtrickle_capability_report(rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE row_data jsonb;
    capability_name text;
    major_text text;
    minor_text text;
    major_version integer;
    minor_version integer;
    enabled boolean;
    status text;
    seen text[] := ARRAY[]::text[];
    capabilities jsonb := '{}'::jsonb;
BEGIN
    IF jsonb_typeof(rows) <> 'array' THEN
        RAISE EXCEPTION 'pg-react pg_trickle capability contract must be an array';
    END IF;

    FOR row_data IN SELECT value FROM jsonb_array_elements(rows) LOOP
        IF jsonb_typeof(row_data) <> 'object' THEN
            RAISE EXCEPTION 'pg-react pg_trickle capability row must be an object: %', row_data;
        END IF;
        capability_name := NULLIF(COALESCE(row_data ->> 'capability', row_data ->> 'name'), '');
        major_text := COALESCE(row_data ->> 'major', row_data ->> 'major_version');
        minor_text := COALESCE(row_data ->> 'minor', row_data ->> 'minor_version');
        IF capability_name IS NULL OR major_text IS NULL OR minor_text IS NULL
           OR jsonb_typeof(row_data -> 'enabled') <> 'boolean'
           OR major_text !~ '^[0-9]+$' OR minor_text !~ '^[0-9]+$' THEN
            RAISE EXCEPTION 'pg-react pg_trickle capability row is malformed: %', row_data;
        END IF;
        BEGIN
            major_version := major_text::integer;
            minor_version := minor_text::integer;
        EXCEPTION WHEN numeric_value_out_of_range THEN
            RAISE EXCEPTION 'pg-react pg_trickle capability version is out of range: %', row_data;
        END;
        IF row_data ? 'status' AND jsonb_typeof(row_data -> 'status') <> 'string' THEN
            RAISE EXCEPTION 'pg-react pg_trickle capability status is malformed: %', row_data;
        END IF;
        IF capability_name = ANY(seen) THEN
            RAISE EXCEPTION 'pg-react pg_trickle capability is duplicated: %', capability_name;
        END IF;
        seen := array_append(seen, capability_name);
        enabled := (row_data ->> 'enabled')::boolean;
        status := COALESCE(row_data ->> 'status', row_data -> 'details' ->> 'status',
                           CASE WHEN enabled THEN 'enabled' ELSE 'disabled' END);
        capabilities := capabilities || jsonb_build_object(
            capability_name,
            jsonb_build_object(
                'major', major_version,
                'minor', minor_version,
                'enabled', enabled,
                'status', status,
                'raw', row_data));
    END LOOP;
    RETURN capabilities;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.preview_pack(definition jsonb, mappings jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(plan_digest text, action_order integer, action text, rule_name text, dependencies text[], generated_object_changes jsonb, lifecycle_risks jsonb, details jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    diagnostic record;
    item record;
    current_row record;
    preview_row record;
    digest text;
    ordinal integer := 0;
    mapped_name text;
    mapped_source text;
    dependency_names text[];
BEGIN
    IF NOT (definition ? 'derived_relations' OR definition ? 'derivations'
            OR definition ? 'remove_derivations' OR definition ? 'remove_derived_relations') THEN
        RETURN QUERY SELECT * FROM pgreact_internal.preview_pack_v1(definition, mappings);
        RETURN;
    END IF;
    SELECT * INTO diagnostic FROM pgreact.validate_pack(definition, mappings) d
    WHERE d.severity = 'ERROR' ORDER BY d.code, d.object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react pack validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    digest := pgreact_internal.m7_pack_plan_digest(definition, mappings);
    FOR item IN
        SELECT value, array_ordinal
        FROM jsonb_array_elements(definition -> 'derived_relations')
        WITH ORDINALITY r(value, array_ordinal)
    LOOP
        ordinal := ordinal + 1;
        mapped_name := pgreact_internal.pack_mapping(
            mappings, 'objects', item.value ->> 'name');
        SELECT v.relation_version_id, v.version, v.state INTO current_row
        FROM pgreact_internal.derived_relations r
        JOIN pgreact_internal.derived_relation_versions v USING (relation_id)
        WHERE r.relation_name = mapped_name AND v.state = 'ACTIVE';
        plan_digest := digest;
        action_order := ordinal;
        action := CASE WHEN current_row.relation_version_id IS NULL THEN 'ADD'
                       WHEN current_row.version = (item.value ->> 'version')::integer THEN 'KEEP'
                       ELSE 'REPLACE' END;
        rule_name := item.value ->> 'name';
        dependencies := ARRAY[]::text[];
        generated_object_changes := jsonb_build_object(
            'object_kind', 'DERIVED_RELATION',
            'public_view', mapped_name,
            'row_type', pgreact_internal.pack_mapping(
                mappings, 'objects', item.value ->> 'row_type'));
        lifecycle_risks := CASE WHEN action = 'REPLACE'
            THEN jsonb_build_array('all producers must move to the new immutable relation version atomically')
            ELSE '[]'::jsonb END;
        details := jsonb_build_object(
            'prior_relation_version_id', current_row.relation_version_id,
            'prior_version', current_row.version,
            'next_version', (item.value ->> 'version')::integer);
        RETURN NEXT;
    END LOOP;
    FOR item IN
        SELECT value, array_ordinal
        FROM jsonb_array_elements(definition -> 'derivations')
        WITH ORDINALITY r(value, array_ordinal)
    LOOP
        ordinal := ordinal + 1;
        SELECT v.rule_version_id, d.version, v.state, v.source_view_name
        INTO current_row
        FROM pgreact_internal.rules r
        JOIN pgreact_internal.rule_versions v USING (rule_id)
        JOIN pgreact_internal.derivation_rule_versions d USING (rule_version_id)
        WHERE r.rule_name = item.value ->> 'name' AND v.state <> 'REMOVED'
        ORDER BY v.created_at DESC LIMIT 1;
        SELECT array_agg(value #>> '{}' ORDER BY dependency_ordinal)::text[]
        INTO dependency_names
        FROM jsonb_array_elements(COALESCE(item.value -> 'depends_on', '[]'::jsonb))
        WITH ORDINALITY d(value, dependency_ordinal);
        mapped_source := pgreact_internal.pack_mapping(
            mappings, 'objects', item.value ->> 'definition');
        plan_digest := digest;
        action_order := ordinal;
        action := CASE WHEN current_row.rule_version_id IS NULL THEN 'ADD'
                       WHEN current_row.version = (item.value ->> 'version')::integer
                        AND current_row.source_view_name = mapped_source THEN 'KEEP'
                       ELSE 'REPLACE' END;
        rule_name := item.value ->> 'name';
        dependencies := COALESCE(dependency_names, ARRAY[]::text[]);
        generated_object_changes := jsonb_build_object(
            'object_kind', 'DERIVATION',
            'create', jsonb_build_array('match_relation', 'support_binding'),
            'agenda', false);
        lifecycle_risks := CASE WHEN action = 'REPLACE'
            THEN jsonb_build_array('old supports retract after replacement supports are seeded')
            ELSE jsonb_build_array(COALESCE(item.value ->> 'bootstrap_policy', 'SEED_CURRENT') ||
                                   ' may seed current supports') END;
        details := jsonb_build_object(
            'source', item.value ->> 'definition', 'mapped_source', mapped_source,
            'target', item.value ->> 'target',
            'prior_rule_version_id', current_row.rule_version_id,
            'prior_version', current_row.version,
            'next_version', (item.value ->> 'version')::integer);
        RETURN NEXT;
    END LOOP;
    FOR preview_row IN
        SELECT * FROM pgreact_internal.preview_pack_v1(
            pgreact_internal.m7_pack_definition(definition), mappings)
        ORDER BY action_order
    LOOP
        ordinal := ordinal + 1;
        plan_digest := digest;
        action_order := ordinal;
        action := preview_row.action;
        rule_name := preview_row.rule_name;
        dependencies := preview_row.dependencies;
        generated_object_changes := preview_row.generated_object_changes;
        lifecycle_risks := preview_row.lifecycle_risks;
        details := preview_row.details;
        RETURN NEXT;
    END LOOP;
    FOR item IN
        SELECT value FROM jsonb_array_elements(definition -> 'remove_derivations') value
    LOOP
        ordinal := ordinal + 1;
        plan_digest := digest; action_order := ordinal; action := 'REMOVE';
        rule_name := item.value ->> 'name'; dependencies := ARRAY[]::text[];
        generated_object_changes := jsonb_build_object('object_kind', 'DERIVATION');
        lifecycle_risks := jsonb_build_array('active supports retract before commit');
        details := '{}'::jsonb;
        RETURN NEXT;
    END LOOP;
    FOR item IN
        SELECT value FROM jsonb_array_elements(definition -> 'remove_derived_relations') value
    LOOP
        ordinal := ordinal + 1;
        plan_digest := digest; action_order := ordinal; action := 'REMOVE';
        rule_name := item.value ->> 'name'; dependencies := ARRAY[]::text[];
        generated_object_changes := jsonb_build_object('object_kind', 'DERIVED_RELATION');
        lifecycle_risks := jsonb_build_array('removal requires no active producer, consumer, or fact');
        details := '{}'::jsonb;
        RETURN NEXT;
    END LOOP;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.preview_pack_v1(definition jsonb, mappings jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(plan_digest text, action_order integer, action text, rule_name text, dependencies text[], generated_object_changes jsonb, lifecycle_risks jsonb, details jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    diagnostic record;
    rule_item record;
    current_row record;
    dependency_names text[];
    work_state jsonb;
    digest text;
    ordinal integer := 0;
BEGIN
    SELECT * INTO diagnostic FROM pgreact.validate_pack(definition, mappings)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react pack validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message USING HINT = diagnostic.hint;
    END IF;
    digest := pgreact_internal.pack_plan_digest(definition, mappings);
    FOR rule_item IN
        SELECT value, array_ordinal FROM pg_catalog.jsonb_array_elements(definition -> 'rules')
        WITH ORDINALITY AS r(value, array_ordinal)
    LOOP
        ordinal := ordinal + 1;
        SELECT v.rule_version_id, v.state, v.match_name INTO current_row
        FROM pgreact_internal.rules r JOIN pgreact_internal.rule_versions v USING (rule_id)
        WHERE r.rule_name = rule_item.value ->> 'name' AND v.state <> 'REMOVED'
        ORDER BY v.created_at DESC LIMIT 1;
        SELECT array_agg(value #>> '{}' ORDER BY dependency_ordinal)::text[] INTO dependency_names
        FROM pg_catalog.jsonb_array_elements(COALESCE(rule_item.value -> 'depends_on', '[]'::jsonb))
        WITH ORDINALITY AS d(value, dependency_ordinal);
        SELECT COALESCE(jsonb_object_agg(state, total ORDER BY state), '{}'::jsonb) INTO work_state
        FROM (SELECT state, count(*) AS total FROM pgreact_internal.agenda
              WHERE rule_version_id = current_row.rule_version_id GROUP BY state) AS q;
        plan_digest := digest;
        action_order := ordinal;
        action := CASE WHEN current_row.rule_version_id IS NULL THEN 'ADD' ELSE 'REPLACE' END;
        rule_name := rule_item.value ->> 'name';
        dependencies := COALESCE(dependency_names, ARRAY[]::text[]);
        generated_object_changes := jsonb_build_object(
            'create', jsonb_build_array('match_relation', 'lifecycle_triggers') ||
                CASE WHEN rule_item.value ->> 'on_activate' IS NOT NULL
                       OR rule_item.value ->> 'on_deactivate' IS NOT NULL
                       OR rule_item.value ->> 'on_change' IS NOT NULL
                     THEN jsonb_build_array('typed_dispatchers') ELSE '[]'::jsonb END,
            'retire', CASE WHEN current_row.rule_version_id IS NULL THEN '[]'::jsonb
                           ELSE jsonb_build_array(current_row.match_name) END
        );
        lifecycle_risks := CASE WHEN current_row.rule_version_id IS NULL
            THEN jsonb_build_array(COALESCE(rule_item.value ->> 'bootstrap_policy', 'SEED_CURRENT') || ' may seed current matches')
            ELSE jsonb_build_array(COALESCE(rule_item.value ->> 'old_work_policy', 'DRAIN_OLD') ||
                                   ' applies to prior pending, retrying, and leased work') END;
        details := jsonb_build_object(
            'source', rule_item.value ->> 'definition',
            'mapped_source', pgreact_internal.pack_mapping(mappings, 'objects', rule_item.value ->> 'definition'),
            'prior_rule_version_id', current_row.rule_version_id,
            'prior_state', current_row.state,
            'prior_work', work_state
        );
        RETURN NEXT;
    END LOOP;
    FOR rule_item IN
        SELECT value FROM pg_catalog.jsonb_array_elements(definition -> 'remove') AS r(value)
    LOOP
        ordinal := ordinal + 1;
        SELECT m.rule_version_id, v.state, v.match_name INTO current_row
        FROM pgreact_internal.rule_packs p
        JOIN pgreact_internal.rule_pack_versions pv USING (pack_id)
        JOIN pgreact_internal.rule_pack_members m USING (pack_version_id)
        JOIN pgreact_internal.rule_versions v USING (rule_version_id)
        WHERE p.pack_name = definition ->> 'pack' AND pv.state = 'ACTIVE'
          AND m.rule_name = rule_item.value ->> 'name';
        SELECT COALESCE(jsonb_object_agg(state, total ORDER BY state), '{}'::jsonb) INTO work_state
        FROM (SELECT state, count(*) AS total FROM pgreact_internal.agenda
              WHERE rule_version_id = current_row.rule_version_id GROUP BY state) AS q;
        plan_digest := digest;
        action_order := ordinal;
        action := 'REMOVE';
        rule_name := rule_item.value ->> 'name';
        dependencies := ARRAY[]::text[];
        generated_object_changes := jsonb_build_object('retire', jsonb_build_array(current_row.match_name));
        lifecycle_risks := jsonb_build_array(COALESCE(rule_item.value ->> 'old_work_policy', 'DRAIN_OLD') ||
                                             ' applies to pending, retrying, and leased work');
        details := jsonb_build_object('prior_rule_version_id', current_row.rule_version_id,
                                      'prior_state', current_row.state, 'prior_work', work_state);
        RETURN NEXT;
    END LOOP;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.preview_program_m14(definition jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    inferred jsonb := pgreact_api.infer_program(definition);
    diagnostic record;
    plan text;
BEGIN
    SELECT * INTO diagnostic FROM pgreact_api.validate_program(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M14_PROGRAM_INVALID: % for %', diagnostic.code, diagnostic.object_identity
            USING HINT = diagnostic.hint;
    END IF;
    plan := encode(sha256(convert_to(inferred::text || ':' || session_user, 'UTF8')), 'hex');
    RETURN jsonb_build_object(
        'contract_version', 4,
        'program', inferred,
        'plan_digest', plan);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.preview_program_m16(definition jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    normalized jsonb;
    inferred jsonb;
    diagnostic record;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(definition -> 'rules') rule
        JOIN pgreact_internal.keyed_derived_relations relation_spec
          ON relation_spec.public_name = rule ->> 'target') THEN
        RETURN pgreact_internal.preview_program_m14(definition);
    END IF;
    SELECT * INTO diagnostic FROM pgreact_api.validate_program(definition)
    WHERE severity = 'ERROR' ORDER BY code, object_identity LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'M16_PROGRAM_INVALID: % for %', diagnostic.code, diagnostic.object_identity
            USING HINT = diagnostic.hint;
    END IF;
    normalized := pgreact_internal.normalize_program(definition);
    inferred := pgreact_api.infer_program(definition);
    RETURN jsonb_build_object(
        'contract_version', 5, 'program', inferred,
        'plan_digest', pgreact_internal.program_plan_digest(normalized));
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.project_derived_fact(target_relation uuid, binding jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE relation_row pgreact_internal.derived_relation_versions%ROWTYPE; result jsonb;
BEGIN
    SELECT * INTO STRICT relation_row
    FROM pgreact_internal.derived_relation_versions
    WHERE relation_version_id = target_relation;
    IF pgreact_internal.composite_type_signature(relation_row.row_type_oid)
       IS DISTINCT FROM relation_row.row_signature THEN
        RAISE EXCEPTION 'derived row type drift for %', relation_row.public_view_name;
    END IF;
    EXECUTE format(
        'SELECT to_jsonb(pg_catalog.jsonb_populate_record(NULL::%s, $1))',
        relation_row.row_type_name
    ) INTO result USING binding;
    IF result ->> relation_row.key_column IS NULL THEN
        RAISE EXCEPTION 'derived fact key %.% must be non-null',
            relation_row.public_view_name, relation_row.key_column;
    END IF;
    RETURN result;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.public_json(input_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    result jsonb;
    member record;
    item jsonb;
    public_key jsonb;
    public_name text;
BEGIN
    CASE jsonb_typeof(input_value)
    WHEN 'object' THEN
        result := '{}'::jsonb;
        public_key := input_value -> '__pgreact_public_key';
        FOR member IN
            SELECT entry.key, entry.value
            FROM jsonb_each(input_value) entry ORDER BY entry.key
        LOOP
            IF left(member.key, 10) = '__pgreact_' THEN CONTINUE; END IF;
            item := member.value;
            IF member.key IN ('key', 'semantic_key', 'group_key')
               AND jsonb_typeof(item) = 'number' THEN
                IF public_key IS NULL THEN
                    SELECT identity.public_key INTO public_key
                    FROM pgreact_internal.semantic_key_identities identity
                    WHERE identity.semantic_key = (item #>> '{}')::bigint
                    ORDER BY identity.rule_version_id LIMIT 1;
                END IF;
                item := COALESCE(public_key, item);
            END IF;
            result := result || jsonb_build_object(
                member.key, pgreact_internal.public_json(item));
        END LOOP;
        RETURN result;
    WHEN 'array' THEN
        SELECT COALESCE(jsonb_agg(pgreact_internal.public_json(element) ORDER BY ordinal), '[]'::jsonb)
        INTO result
        FROM jsonb_array_elements(input_value) WITH ORDINALITY item(element, ordinal);
        RETURN result;
    WHEN 'string' THEN
        SELECT spec.public_name || substring(input_value #>> '{}'
            FROM length(spec.internal_name) + 1) INTO public_name
        FROM pgreact_internal.keyed_derived_relations spec
        WHERE input_value #>> '{}' = spec.internal_name
           OR input_value #>> '{}' LIKE spec.internal_name || '@%';
        IF public_name IS NULL THEN
            SELECT wrapper.public_condition::regclass::text INTO public_name
            FROM pgreact_internal.key_wrappers wrapper
            WHERE wrapper.wrapper_condition::regclass::text = input_value #>> '{}';
        END IF;
        RETURN COALESCE(to_jsonb(public_name), input_value);
    ELSE
        RETURN input_value;
    END CASE;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.reconcile_deadline_key(target_version_id uuid, target_key bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    version_row pgreact_internal.rule_versions%ROWTYPE;
    deadline_rule pgreact_internal.deadline_rules%ROWTYPE;
    candidate_count bigint;
    candidate_bindings jsonb;
    declared_deadline timestamptz;
    frontier timestamptz;
    present boolean;
    canonical bytea;
    digest bytea;
    activation uuid;
    prior pgreact_internal.activation_state%ROWTYPE;
    next_generation bigint;
    next_revision bigint;
    new_event_id bigint;
BEGIN
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_version_id;
    SELECT * INTO STRICT deadline_rule
    FROM pgreact_internal.deadline_rules
    WHERE rule_version_id = target_version_id;
    IF version_row.state <> 'ACTIVE' THEN
        RETURN 0;
    END IF;
    SELECT clock.frontier INTO STRICT frontier
    FROM pgreact_internal.clock_frontier clock;
    EXECUTE format(
        'SELECT count(*), min(to_jsonb(candidate)::text)::jsonb, '
        'min((to_jsonb(candidate) ->> %L)::timestamptz) '
        'FROM %s candidate WHERE (to_jsonb(candidate) ->> %L)::bigint = $1',
        deadline_rule.deadline_column::text,
        version_row.match_relid::regclass,
        version_row.key_column::text
    ) INTO candidate_count, candidate_bindings, declared_deadline
      USING target_key;
    IF candidate_count > 1 THEN
        RAISE EXCEPTION 'pg-react duplicate semantic key % in %',
            target_key, version_row.match_name;
    END IF;
    IF candidate_count = 1
       AND (declared_deadline IS NULL OR NOT isfinite(declared_deadline)) THEN
        RAISE EXCEPTION 'M12_DEADLINE_VALUE: %.% must be finite and non-null for key %',
            version_row.source_view_name, deadline_rule.deadline_column, target_key;
    END IF;
    present := candidate_count = 1 AND declared_deadline <= frontier;
    canonical := pgreact_internal.canonical_bigint_v1(target_key);
    digest := pgreact_internal.activation_digest(target_version_id, canonical);
    activation := pgreact_internal.activation_uuid(digest);
    SELECT * INTO prior
    FROM pgreact_internal.activation_state
    WHERE rule_version_id = target_version_id AND activation_id = activation
    FOR UPDATE;
    IF FOUND AND (prior.canonical_key <> canonical OR prior.canonical_key_digest <> digest) THEN
        RAISE EXCEPTION 'pg-react activation UUID collision for semantic key %', target_key;
    END IF;

    IF present AND (prior.activation_id IS NULL OR NOT prior.active) THEN
        next_generation := COALESCE(prior.generation, 0) + 1;
        INSERT INTO pgreact_internal.activation_state (
            rule_version_id, activation_id, semantic_key, canonical_key,
            canonical_key_digest, key_codec_version, active, generation,
            revision, current_bindings, last_active_bindings,
            first_seen_at, last_seen_at
        ) VALUES (
            target_version_id, activation, target_key, canonical, digest, 1,
            true, next_generation, 0, candidate_bindings, candidate_bindings,
            clock_timestamp(), clock_timestamp()
        )
        ON CONFLICT (rule_version_id, activation_id) DO UPDATE SET
            active = true,
            generation = EXCLUDED.generation,
            revision = 0,
            current_bindings = EXCLUDED.current_bindings,
            last_active_bindings = EXCLUDED.last_active_bindings,
            last_seen_at = EXCLUDED.last_seen_at,
            deactivated_at = NULL;
        new_event_id := pgreact_internal.emit_event(
            version_row, activation, next_generation, 0,
            'ACTIVATE', NULL, candidate_bindings);
    ELSIF present AND prior.active THEN
        IF pgreact_internal.watched_changed(
            version_row, prior.current_bindings, candidate_bindings) THEN
            next_revision := prior.revision + 1;
            new_event_id := pgreact_internal.emit_event(
                version_row, activation, prior.generation, next_revision,
                'CHANGE', prior.current_bindings, candidate_bindings);
            UPDATE pgreact_internal.activation_state
            SET revision = next_revision,
                current_bindings = candidate_bindings,
                last_active_bindings = candidate_bindings,
                last_seen_at = clock_timestamp()
            WHERE rule_version_id = target_version_id
              AND activation_id = activation;
        ELSE
            UPDATE pgreact_internal.activation_state
            SET current_bindings = candidate_bindings,
                last_active_bindings = candidate_bindings,
                last_seen_at = clock_timestamp()
            WHERE rule_version_id = target_version_id
              AND activation_id = activation;
        END IF;
    ELSIF NOT present AND prior.active THEN
        UPDATE pgreact_internal.activation_state
        SET active = false,
            current_bindings = NULL,
            deactivated_at = clock_timestamp(),
            last_seen_at = clock_timestamp()
        WHERE rule_version_id = target_version_id
          AND activation_id = activation;
        UPDATE pgreact_internal.agenda
        SET state = 'WITHDRAWN',
            completed_at = clock_timestamp(),
            lease_token = NULL,
            worker_id = NULL,
            lease_expires_at = NULL
        WHERE rule_version_id = target_version_id
          AND activation_id = activation
          AND activation_generation = prior.generation
          AND event_kind = 'ACTIVATE'
          AND state IN ('PENDING', 'RETRY_WAIT');
        new_event_id := pgreact_internal.emit_event(
            version_row, activation, prior.generation, 0,
            'DEACTIVATE', prior.last_active_bindings, NULL);
        declared_deadline := COALESCE(
            declared_deadline,
            (prior.last_active_bindings ->> deadline_rule.deadline_column::text)::timestamptz);
    END IF;

    IF new_event_id IS NOT NULL THEN
        INSERT INTO pgreact_internal.deadline_lifecycle (
            event_id, declared_deadline, observed_frontier
        ) VALUES (
            new_event_id, declared_deadline, frontier
        )
        ON CONFLICT (event_id) DO UPDATE SET
            declared_deadline = EXCLUDED.declared_deadline,
            observed_frontier = EXCLUDED.observed_frontier;
        RETURN 1;
    END IF;
    RETURN 0;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.reconcile_deadline_rule(target_version_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    version_row pgreact_internal.rule_versions%ROWTYPE;
    candidate record;
    repaired bigint := 0;
BEGIN
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_version_id;
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    PERFORM pgreact_internal.refresh_rule(target_version_id);
    SET CONSTRAINTS ALL IMMEDIATE;
    FOR candidate IN EXECUTE format(
        'SELECT (to_jsonb(candidate) ->> %L)::bigint AS semantic_key '
        'FROM %s candidate UNION SELECT semantic_key '
        'FROM pgreact_internal.activation_state WHERE rule_version_id = %L::uuid '
        'ORDER BY semantic_key',
        version_row.key_column::text,
        version_row.match_relid::regclass,
        target_version_id::text)
    LOOP
        repaired := repaired + pgreact_internal.reconcile_deadline_key(
            target_version_id, candidate.semantic_key);
    END LOOP;
    RETURN repaired;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.reconcile_deadline_state(target_version_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    version_row pgreact_internal.rule_versions%ROWTYPE;
    deadline_rule pgreact_internal.deadline_rules%ROWTYPE;
    frontier timestamptz;
    candidate record;
    candidate_count bigint;
    candidate_bindings jsonb;
    declared_deadline timestamptz;
    present boolean;
    canonical bytea;
    digest bytea;
    activation uuid;
    prior pgreact_internal.activation_state%ROWTYPE;
    repaired bigint := 0;
    audit_id bigint;
BEGIN
    SELECT * INTO STRICT version_row
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_version_id AND state = 'ACTIVE';
    SELECT * INTO STRICT deadline_rule
    FROM pgreact_internal.deadline_rules
    WHERE rule_version_id = target_version_id;
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    PERFORM pgreact_internal.refresh_rule(target_version_id);
    SET CONSTRAINTS ALL IMMEDIATE;
    SELECT clock.frontier INTO STRICT frontier
    FROM pgreact_internal.clock_frontier clock;
    INSERT INTO pgreact_internal.reconciliation_audit (
        rule_version_id, mode, started_at, status, requested_by, reason
    ) VALUES (
        target_version_id, 'STATE_ONLY', clock_timestamp(),
        'RUNNING', session_user, 'OPERATOR'
    ) RETURNING reconciliation_id INTO audit_id;

    FOR candidate IN EXECUTE format(
        'SELECT (to_jsonb(candidate) ->> %L)::bigint AS semantic_key '
        'FROM %s candidate UNION SELECT semantic_key '
        'FROM pgreact_internal.activation_state WHERE rule_version_id = %L::uuid '
        'ORDER BY semantic_key',
        version_row.key_column::text,
        version_row.match_relid::regclass,
        target_version_id::text)
    LOOP
        EXECUTE format(
            'SELECT count(*), min(to_jsonb(candidate)::text)::jsonb, '
            'min((to_jsonb(candidate) ->> %L)::timestamptz) '
            'FROM %s candidate WHERE (to_jsonb(candidate) ->> %L)::bigint = $1',
            deadline_rule.deadline_column::text,
            version_row.match_relid::regclass,
            version_row.key_column::text
        ) INTO candidate_count, candidate_bindings, declared_deadline
          USING candidate.semantic_key;
        IF candidate_count > 1 THEN
            RAISE EXCEPTION 'pg-react duplicate semantic key % in %',
                candidate.semantic_key, version_row.match_name;
        END IF;
        IF candidate_count = 1
           AND (declared_deadline IS NULL OR NOT isfinite(declared_deadline)) THEN
            RAISE EXCEPTION 'M12_DEADLINE_VALUE: %.% must be finite and non-null for key %',
                version_row.source_view_name,
                deadline_rule.deadline_column,
                candidate.semantic_key;
        END IF;
        present := candidate_count = 1 AND declared_deadline <= frontier;
        canonical := pgreact_internal.canonical_bigint_v1(candidate.semantic_key);
        digest := pgreact_internal.activation_digest(target_version_id, canonical);
        activation := pgreact_internal.activation_uuid(digest);
        SELECT * INTO prior
        FROM pgreact_internal.activation_state
        WHERE rule_version_id = target_version_id
          AND activation_id = activation
        FOR UPDATE;
        IF present AND (prior.activation_id IS NULL OR NOT prior.active) THEN
            INSERT INTO pgreact_internal.activation_state (
                rule_version_id, activation_id, semantic_key, canonical_key,
                canonical_key_digest, key_codec_version, active, generation,
                revision, current_bindings, last_active_bindings,
                first_seen_at, last_seen_at
            ) VALUES (
                target_version_id, activation, candidate.semantic_key,
                canonical, digest, 1, true,
                COALESCE(prior.generation, 0) + 1, 0,
                candidate_bindings, candidate_bindings,
                clock_timestamp(), clock_timestamp()
            )
            ON CONFLICT (rule_version_id, activation_id) DO UPDATE SET
                active = true,
                generation = EXCLUDED.generation,
                revision = 0,
                current_bindings = EXCLUDED.current_bindings,
                last_active_bindings = EXCLUDED.last_active_bindings,
                deactivated_at = NULL,
                last_seen_at = EXCLUDED.last_seen_at;
            repaired := repaired + 1;
        ELSIF present AND prior.active
              AND pgreact_internal.watched_changed(
                  version_row, prior.current_bindings, candidate_bindings) THEN
            UPDATE pgreact_internal.activation_state
            SET revision = revision + 1,
                current_bindings = candidate_bindings,
                last_active_bindings = candidate_bindings,
                last_seen_at = clock_timestamp()
            WHERE rule_version_id = target_version_id
              AND activation_id = activation;
            repaired := repaired + 1;
        ELSIF NOT present AND prior.active THEN
            UPDATE pgreact_internal.activation_state
            SET active = false,
                current_bindings = NULL,
                deactivated_at = clock_timestamp(),
                last_seen_at = clock_timestamp()
            WHERE rule_version_id = target_version_id
              AND activation_id = activation;
            repaired := repaired + 1;
        END IF;
    END LOOP;
    UPDATE pgreact_internal.reconciliation_audit
    SET completed_at = clock_timestamp(),
        rows_repaired = repaired,
        events_emitted = 0,
        status = 'COMPLETED'
    WHERE reconciliation_id = audit_id;
    RETURN repaired;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.reconcile_derived_relation_m7(target_relation uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    relation_row pgreact_internal.derived_relation_versions%ROWTYPE;
    run_id bigint;
    diagnostic_order integer := 0;
    expected record;
    actual record;
    projected jsonb;
    canonical bytea;
    expected_fact_id uuid;
    expected_support_id uuid;
    frontier_value bigint;
    support_total bigint;
    expected_fact jsonb;
BEGIN
    relation_row := pgreact_internal.assert_derived_owner(target_relation);
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    SELECT frontier INTO frontier_value
    FROM pgreact_internal.derived_frontiers
    WHERE relation_version_id = target_relation;
    frontier_value := COALESCE(frontier_value, 1);
    INSERT INTO pgreact_internal.derived_reconciliations (
        relation_version_id, started_at, status, requested_by
    ) VALUES (target_relation, clock_timestamp(), 'RUNNING', session_user)
    RETURNING reconciliation_id INTO run_id;

    FOR actual IN
        SELECT s.*
        FROM pgreact_internal.derived_supports s
        LEFT JOIN pgreact_internal.activation_state a
          ON a.rule_version_id = s.rule_version_id
         AND a.activation_id = s.activation_id
         AND a.active
         AND a.generation = s.activation_generation
         AND a.revision = s.activation_revision
         AND a.current_bindings - '__pgt_row_id' = s.source_binding
        LEFT JOIN pgreact_internal.rule_versions v
          ON v.rule_version_id = s.rule_version_id AND v.state = 'ACTIVE'
        WHERE s.relation_version_id = target_relation AND s.active
          AND (a.activation_id IS NULL OR v.rule_version_id IS NULL)
        ORDER BY s.support_id
    LOOP
        diagnostic_order := diagnostic_order + 1;
        INSERT INTO pgreact_internal.derived_repair_diagnostics VALUES (
            run_id, diagnostic_order,
            CASE WHEN EXISTS (
                SELECT 1 FROM pgreact_internal.activation_state a
                WHERE a.rule_version_id = actual.rule_version_id
                  AND a.activation_id = actual.activation_id
            ) THEN 'STALE_SUPPORT' ELSE 'EXTRA_SUPPORT' END,
            actual.support_id::text,
            jsonb_build_object('rule_version_id', actual.rule_version_id,
                               'activation_id', actual.activation_id)
        );
        UPDATE pgreact_internal.derived_supports
        SET active = false, last_frontier = COALESCE(last_frontier, frontier_value),
            invalidated_at = COALESCE(invalidated_at, clock_timestamp())
        WHERE support_id = actual.support_id;
    END LOOP;

    FOR expected IN
        SELECT d.rule_version_id, a.activation_id, a.generation, a.revision,
               a.semantic_key, a.current_bindings
        FROM pgreact_internal.derivation_rule_versions d
        JOIN pgreact_internal.rule_versions v USING (rule_version_id)
        JOIN pgreact_internal.activation_state a USING (rule_version_id)
        WHERE d.relation_version_id = target_relation
          AND v.state = 'ACTIVE' AND a.active
        ORDER BY d.rule_version_id, a.activation_id
    LOOP
        projected := pgreact_internal.project_derived_fact(
            target_relation, expected.current_bindings - '__pgt_row_id');
        canonical := pgreact_internal.canonical_bigint_v1(expected.semantic_key);
        expected_fact_id := pgreact_internal.activation_uuid(
            pgreact_internal.activation_digest(target_relation, canonical));
        expected_support_id := pgreact_internal.activation_uuid(sha256(convert_to(
            expected.rule_version_id::text || ':' || expected.activation_id::text || ':' ||
            expected.generation || ':' || expected.revision || ':' || expected_fact_id::text,
            'UTF8')));
        SELECT * INTO actual FROM pgreact_internal.derived_supports
        WHERE support_id = expected_support_id;
        IF NOT FOUND THEN
            diagnostic_order := diagnostic_order + 1;
            INSERT INTO pgreact_internal.derived_repair_diagnostics VALUES (
                run_id, diagnostic_order, 'MISSING_SUPPORT', expected_support_id::text,
                jsonb_build_object('rule_version_id', expected.rule_version_id,
                                   'activation_id', expected.activation_id)
            );
            INSERT INTO pgreact_internal.derived_supports (
                support_id, relation_version_id, rule_version_id, activation_id,
                activation_generation, activation_revision, semantic_key, fact_id,
                fact, source_binding, active, first_frontier
            ) VALUES (
                expected_support_id, target_relation, expected.rule_version_id,
                expected.activation_id, expected.generation, expected.revision,
                expected.semantic_key, expected_fact_id, projected,
                expected.current_bindings - '__pgt_row_id', true, frontier_value
            );
        ELSIF NOT actual.active OR actual.fact IS DISTINCT FROM projected
              OR actual.source_binding IS DISTINCT FROM expected.current_bindings - '__pgt_row_id'
              OR actual.semantic_key IS DISTINCT FROM expected.semantic_key THEN
            diagnostic_order := diagnostic_order + 1;
            INSERT INTO pgreact_internal.derived_repair_diagnostics VALUES (
                run_id, diagnostic_order, 'STALE_SUPPORT', expected_support_id::text,
                jsonb_build_object('rule_version_id', expected.rule_version_id,
                                   'activation_id', expected.activation_id)
            );
            UPDATE pgreact_internal.derived_supports SET
                semantic_key = expected.semantic_key, fact_id = expected_fact_id,
                fact = projected, source_binding = expected.current_bindings - '__pgt_row_id',
                active = true, last_frontier = NULL, invalidated_at = NULL
            WHERE support_id = expected_support_id;
        END IF;
    END LOOP;

    FOR actual IN
        SELECT f.* FROM pgreact_internal.derived_facts f
        WHERE f.relation_version_id = target_relation ORDER BY f.semantic_key
    LOOP
        SELECT count(*), min(s.fact::text)::jsonb
        INTO support_total, expected_fact
        FROM pgreact_internal.derived_supports s
        WHERE s.relation_version_id = target_relation
          AND s.semantic_key = actual.semantic_key AND s.active;
        IF support_total = 0 THEN
            diagnostic_order := diagnostic_order + 1;
            INSERT INTO pgreact_internal.derived_repair_diagnostics VALUES (
                run_id, diagnostic_order, 'EXTRA_FACT', actual.fact_id::text,
                jsonb_build_object('semantic_key', actual.semantic_key)
            );
            DELETE FROM pgreact_internal.derived_facts
            WHERE relation_version_id = target_relation AND fact_id = actual.fact_id;
        ELSIF actual.support_count IS DISTINCT FROM support_total
              OR actual.fact IS DISTINCT FROM expected_fact THEN
            diagnostic_order := diagnostic_order + 1;
            INSERT INTO pgreact_internal.derived_repair_diagnostics VALUES (
                run_id, diagnostic_order, 'STALE_FACT', actual.fact_id::text,
                jsonb_build_object('semantic_key', actual.semantic_key,
                                   'support_count', support_total)
            );
            UPDATE pgreact_internal.derived_facts SET
                fact = expected_fact, support_count = support_total,
                last_changed_at = clock_timestamp()
            WHERE relation_version_id = target_relation AND fact_id = actual.fact_id;
        END IF;
    END LOOP;

    FOR expected IN
        SELECT s.semantic_key, min(s.fact::text)::jsonb AS fact, count(*) AS support_count
        FROM pgreact_internal.derived_supports s
        WHERE s.relation_version_id = target_relation AND s.active
        GROUP BY s.semantic_key
        HAVING NOT EXISTS (
            SELECT 1 FROM pgreact_internal.derived_facts f
            WHERE f.relation_version_id = target_relation
              AND f.semantic_key = s.semantic_key
        )
        ORDER BY s.semantic_key
    LOOP
        canonical := pgreact_internal.canonical_bigint_v1(expected.semantic_key);
        expected_fact_id := pgreact_internal.activation_uuid(
            pgreact_internal.activation_digest(target_relation, canonical));
        diagnostic_order := diagnostic_order + 1;
        INSERT INTO pgreact_internal.derived_repair_diagnostics VALUES (
            run_id, diagnostic_order, 'MISSING_FACT', expected_fact_id::text,
            jsonb_build_object('semantic_key', expected.semantic_key,
                               'support_count', expected.support_count)
        );
        INSERT INTO pgreact_internal.derived_facts (
            relation_version_id, fact_id, semantic_key, fact, support_count,
            first_frontier, last_frontier
        ) VALUES (
            target_relation, expected_fact_id, expected.semantic_key, expected.fact,
            expected.support_count, frontier_value, frontier_value
        );
    END LOOP;

    UPDATE pgreact_internal.derived_reconciliations
    SET completed_at = clock_timestamp(), repairs = diagnostic_order,
        status = 'COMPLETED'
    WHERE reconciliation_id = run_id;
    RETURN diagnostic_order;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.reconcile_effective_policy(target_policy_name text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_id uuid;
    repaired bigint := 0;
BEGIN
    PERFORM pgreact_internal.m24_advance();
    SELECT policy.authoritative_version_id INTO version_id
    FROM pgreact_internal.effective_policies policy
    WHERE policy.policy_name = target_policy_name;
    IF version_id IS NOT NULL THEN
        SELECT repaired + pgreact_internal.m24_sync_rule(version.rule_version_id)
        INTO repaired
        FROM pgreact_internal.effective_policy_versions version
        WHERE version.policy_version_id = version_id;
    END IF;
    RETURN repaired;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.reconcile_rule_m7(target_version_id uuid, emission_mode text DEFAULT 'STATE_ONLY'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE; audit_id bigint; repaired bigint := 0;
    events bigint := 0; match_row record; state_row pgreact_internal.activation_state%ROWTYPE;
    canonical bytea; digest bytea; activation uuid; present boolean;
    null_count bigint; duplicate_count bigint;
BEGIN
    PERFORM pgreact_internal.assert_rule_owner(target_version_id);
    IF emission_mode NOT IN ('STATE_ONLY', 'EMIT_MISSING_EVENTS') THEN RAISE EXCEPTION 'emission_mode must be STATE_ONLY or EMIT_MISSING_EVENTS'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pgreact_internal.rule_barriers
                   WHERE rule_version_id = target_version_id AND reason = 'RECONCILING') THEN
        RAISE EXCEPTION 'reconciliation requires a committed claim barrier for rule version %', target_version_id
            USING HINT = 'Commit pgreact.begin_reconciliation(version), then retry reconciliation in a new transaction.';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions WHERE rule_version_id = target_version_id;
    INSERT INTO pgreact_internal.reconciliation_audit (rule_version_id, mode, started_at, status, requested_by, reason)
    VALUES (target_version_id, emission_mode, clock_timestamp(), 'RUNNING', current_user, 'OPERATOR') RETURNING reconciliation_id INTO audit_id;
    EXECUTE format('SELECT count(*) FROM %s WHERE %I IS NULL',
                   version_row.match_relid::regclass, version_row.key_column)
        INTO null_count;
    EXECUTE format(
        'SELECT count(*) FROM (SELECT %I FROM %s GROUP BY %I HAVING count(*) > 1) d',
        version_row.key_column, version_row.match_relid::regclass, version_row.key_column
    ) INTO duplicate_count;
    IF null_count > 0 OR duplicate_count > 0 THEN
        RAISE EXCEPTION 'cannot reconcile: % null and % duplicate semantic keys', null_count, duplicate_count
            USING HINT = 'Correct the match relation, then retry while the reconciliation barrier remains in place.';
    END IF;
    FOR state_row IN SELECT * FROM pgreact_internal.activation_state WHERE rule_version_id = target_version_id FOR UPDATE LOOP
        EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s WHERE %I = $1)', version_row.match_relid::regclass, version_row.key_column)
            INTO present USING state_row.semantic_key;
        IF state_row.active AND NOT present THEN
            UPDATE pgreact_internal.activation_state SET active = false, current_bindings = NULL,
                deactivated_at = clock_timestamp(), last_seen_at = clock_timestamp() WHERE rule_version_id = target_version_id AND activation_id = state_row.activation_id;
            IF emission_mode = 'EMIT_MISSING_EVENTS' THEN
                PERFORM pgreact_internal.emit_event(version_row, state_row.activation_id, state_row.generation, 0, 'DEACTIVATE', state_row.last_active_bindings, NULL);
                events := events + 1;
            END IF;
            repaired := repaired + 1;
        END IF;
    END LOOP;
    FOR match_row IN EXECUTE format('SELECT %I::bigint semantic_key, to_jsonb(m) bindings FROM %s m', version_row.key_column, version_row.match_relid::regclass) LOOP
        canonical := pgreact_internal.canonical_bigint_v1(match_row.semantic_key);
        digest := pgreact_internal.activation_digest(target_version_id, canonical);
        activation := pgreact_internal.activation_uuid(digest);
        SELECT * INTO state_row FROM pgreact_internal.activation_state WHERE rule_version_id = target_version_id AND activation_id = activation FOR UPDATE;
        IF NOT FOUND OR NOT state_row.active THEN
            INSERT INTO pgreact_internal.activation_state (rule_version_id, activation_id, semantic_key, canonical_key, canonical_key_digest,
                key_codec_version, active, generation, revision, current_bindings, last_active_bindings, first_seen_at, last_seen_at)
            VALUES (target_version_id, activation, match_row.semantic_key, canonical, digest, 1, true,
                COALESCE(state_row.generation, 0) + 1, 0, match_row.bindings, match_row.bindings, clock_timestamp(), clock_timestamp())
            ON CONFLICT (rule_version_id, activation_id) DO UPDATE SET active = true, generation = EXCLUDED.generation,
                revision = 0, current_bindings = EXCLUDED.current_bindings, last_active_bindings = EXCLUDED.last_active_bindings,
                deactivated_at = NULL, last_seen_at = EXCLUDED.last_seen_at;
            IF emission_mode = 'EMIT_MISSING_EVENTS' THEN
                PERFORM pgreact_internal.emit_event(version_row, activation, COALESCE(state_row.generation, 0) + 1, 0, 'ACTIVATE', NULL, match_row.bindings);
                events := events + 1;
            END IF;
            repaired := repaired + 1;
        ELSIF pgreact_internal.watched_changed(version_row, state_row.current_bindings, match_row.bindings) THEN
            UPDATE pgreact_internal.activation_state SET current_bindings = match_row.bindings, last_active_bindings = match_row.bindings,
                revision = revision + 1, last_seen_at = clock_timestamp() WHERE rule_version_id = target_version_id AND activation_id = activation;
            IF emission_mode = 'EMIT_MISSING_EVENTS' THEN
                PERFORM pgreact_internal.emit_event(version_row, activation, state_row.generation, state_row.revision + 1,
                    'CHANGE', state_row.current_bindings, match_row.bindings);
                events := events + 1;
            END IF;
            repaired := repaired + 1;
        END IF;
    END LOOP;
    DELETE FROM pgreact_internal.rule_barriers
    WHERE rule_version_id = target_version_id AND reason = 'RECONCILING';
    UPDATE pgreact_internal.reconciliation_audit SET completed_at = clock_timestamp(), rows_repaired = repaired,
        events_emitted = events, status = 'COMPLETED' WHERE reconciliation_id = audit_id;
    RETURN repaired;
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.reconcile_state_only(target_version_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    version_row pgreact_internal.rule_versions%ROWTYPE;
    audit_id bigint;
    repaired bigint := 0;
    null_count bigint;
    duplicate_count bigint;
    match_row record;
    state_row pgreact_internal.activation_state%ROWTYPE;
    current_count bigint;
    canonical bytea;
    digest bytea;
    activation uuid;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions v
    WHERE v.rule_version_id = target_version_id;
    INSERT INTO pgreact_internal.rule_barriers (rule_version_id, reason)
    VALUES (target_version_id, 'RECONCILING')
    ON CONFLICT ON CONSTRAINT rule_barriers_pkey DO UPDATE SET reason = 'RECONCILING';
    INSERT INTO pgreact_internal.reconciliation_audit (
        rule_version_id, mode, started_at, status
    ) VALUES (target_version_id, 'STATE_ONLY', clock_timestamp(), 'RUNNING')
    RETURNING reconciliation_id INTO audit_id;

    EXECUTE format('SELECT count(*) FROM %s WHERE %I IS NULL',
                   version_row.match_relid::regclass, version_row.key_column)
        INTO null_count;
    EXECUTE format(
        'SELECT count(*) FROM (SELECT %I FROM %s GROUP BY %I HAVING count(*) > 1) d',
        version_row.key_column, version_row.match_relid::regclass, version_row.key_column
    ) INTO duplicate_count;
    IF null_count > 0 OR duplicate_count > 0 THEN
        UPDATE pgreact_internal.rule_barriers SET reason = 'INVALID_KEY'
        WHERE rule_version_id = target_version_id;
        RAISE EXCEPTION 'cannot reconcile: % null and % duplicate semantic keys',
            null_count, duplicate_count;
    END IF;

    FOR state_row IN
        SELECT * FROM pgreact_internal.activation_state s
        WHERE s.rule_version_id = target_version_id
        FOR UPDATE
    LOOP
        EXECUTE format('SELECT count(*) FROM %s m WHERE %I = $1',
                       version_row.match_relid::regclass, version_row.key_column)
            INTO current_count USING state_row.semantic_key;
        IF current_count = 0 AND state_row.active THEN
            UPDATE pgreact_internal.activation_state SET active = false,
                current_bindings = NULL, deactivated_at = clock_timestamp(),
                last_seen_at = clock_timestamp()
            WHERE rule_version_id = target_version_id
              AND activation_id = state_row.activation_id;
            repaired := repaired + 1;
        END IF;
    END LOOP;

    FOR match_row IN EXECUTE format(
        'SELECT %I::bigint AS semantic_key, to_jsonb(m) AS bindings FROM %s m',
        version_row.key_column, version_row.match_relid::regclass
    ) LOOP
        canonical := pgreact_internal.canonical_bigint_v1(match_row.semantic_key);
        digest := pgreact_internal.activation_digest(target_version_id, canonical);
        activation := pgreact_internal.activation_uuid(digest);
        SELECT * INTO state_row FROM pgreact_internal.activation_state s
        WHERE s.rule_version_id = target_version_id
          AND s.activation_id = activation FOR UPDATE;
        IF NOT FOUND THEN
            INSERT INTO pgreact_internal.activation_state (
                rule_version_id, activation_id, semantic_key, canonical_key,
                canonical_key_digest, key_codec_version, active, generation,
                current_bindings, last_active_bindings, first_seen_at, last_seen_at
            ) VALUES (
                target_version_id, activation, match_row.semantic_key, canonical, digest,
                1, true, 1, match_row.bindings, match_row.bindings,
                clock_timestamp(), clock_timestamp()
            );
            repaired := repaired + 1;
        ELSIF NOT state_row.active OR state_row.current_bindings IS DISTINCT FROM match_row.bindings THEN
            UPDATE pgreact_internal.activation_state SET
                active = true,
                generation = CASE WHEN state_row.active THEN state_row.generation
                                  ELSE state_row.generation + 1 END,
                current_bindings = match_row.bindings,
                last_active_bindings = match_row.bindings,
                last_seen_at = clock_timestamp(), deactivated_at = NULL
            WHERE rule_version_id = target_version_id
              AND activation_id = activation;
            repaired := repaired + 1;
        END IF;
    END LOOP;

    DELETE FROM pgreact_internal.rule_barriers
    WHERE rule_version_id = target_version_id;
    UPDATE pgreact_internal.reconciliation_audit SET
        completed_at = clock_timestamp(), rows_repaired = repaired, status = 'COMPLETED'
    WHERE reconciliation_id = audit_id;
    RETURN repaired;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.reconcile_temporal_frontier()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE spec record; changed bigint := 0;
    max_keys integer;
    total_keys bigint;
BEGIN
    SELECT max_temporal_keys_per_pass INTO max_keys
    FROM pgreact_internal.operational_settings;
    SELECT count(*) INTO total_keys
    FROM pgreact_internal.temporal_state state
    JOIN pgreact_internal.temporal_rules temporal USING (rule_version_id)
    JOIN pgreact_internal.rule_versions version USING (rule_version_id)
    WHERE version.state = 'ACTIVE';
    IF total_keys > max_keys THEN
        RAISE EXCEPTION 'M23_TEMPORAL_LIMIT: % temporal keys exceed max_temporal_keys_per_pass %',
            total_keys, max_keys;
    END IF;
    FOR spec IN
        SELECT rule_version_id FROM pgreact_internal.temporal_rules spec
        JOIN pgreact_internal.rule_versions version USING (rule_version_id)
        WHERE version.state = 'ACTIVE' ORDER BY rule_version_id
    LOOP
        changed := changed + pgreact_internal.reconcile_temporal_rule(spec.rule_version_id);
    END LOOP;
    RETURN changed;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.reconcile_temporal_key(target_version_id uuid, target_key bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
<<temporal_key>>
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE;
    spec pgreact_internal.temporal_rules%ROWTYPE;
    prior_state pgreact_internal.temporal_state%ROWTYPE;
    prior_activation pgreact_internal.activation_state%ROWTYPE;
    frontier timestamptz; candidate_count bigint; candidate_bindings jsonb;
    declared_deadline timestamptz; recovery_count bigint; recovery_true boolean := false;
    input_true boolean; new_active boolean; new_state text; new_continuous timestamptz;
    new_pending timestamptz; new_cooldown timestamptz; new_bindings jsonb;
    activation uuid; canonical bytea; digest bytea; lifecycle_event bigint;
    event_kind text; next_generation bigint; event_bindings jsonb;
BEGIN
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions WHERE rule_version_id = target_version_id;
    SELECT * INTO STRICT spec FROM pgreact_internal.temporal_rules WHERE rule_version_id = target_version_id;
    SELECT clock.frontier INTO STRICT frontier
    FROM pgreact_internal.clock_frontier clock FOR UPDATE;
    EXECUTE format(
        'SELECT count(*)::bigint, min(to_jsonb(v)::text)::jsonb FROM %s v WHERE (%I)::bigint = $1',
        version_row.match_relid::regclass, version_row.key_column)
        INTO candidate_count, candidate_bindings USING target_key;
    IF candidate_count > 1 THEN
        RAISE EXCEPTION 'M23_DUPLICATE_KEY: % contains multiple rows for semantic key %',
            version_row.source_view_name, target_key;
    END IF;
    IF spec.deadline_column IS NOT NULL AND candidate_count = 1 THEN
        EXECUTE format(
            'SELECT (to_jsonb(v) ->> %L)::timestamptz FROM %s v WHERE (%I)::bigint = $1',
            spec.deadline_column::text, version_row.match_relid::regclass, version_row.key_column)
            INTO declared_deadline USING target_key;
        IF declared_deadline IS NULL OR NOT isfinite(declared_deadline) THEN
            RAISE EXCEPTION 'M23_DEADLINE_VALUE: deadline must be finite and non-null for key %', target_key;
        END IF;
    END IF;
    input_true := candidate_count = 1;
    IF spec.recovery_condition_oid IS NOT NULL THEN
        EXECUTE format(
            'SELECT count(*)::bigint FROM %s v WHERE (to_jsonb(v) ->> %L)::bigint = $1',
            spec.recovery_condition_oid::regclass, spec.recovery_key_column::text)
            INTO recovery_count USING target_key;
        IF recovery_count > 1 THEN
            RAISE EXCEPTION 'M23_DUPLICATE_RECOVERY_KEY: recovery condition has multiple rows for key %', target_key;
        END IF;
        recovery_true := recovery_count = 1;
    END IF;
    SELECT * INTO prior_state FROM pgreact_internal.temporal_state
    WHERE rule_version_id = target_version_id AND semantic_key = target_key FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO pgreact_internal.temporal_state (
            rule_version_id, semantic_key, state, last_frontier)
        VALUES (target_version_id, target_key, 'WAITING', frontier);
        SELECT * INTO prior_state FROM pgreact_internal.temporal_state
        WHERE rule_version_id = target_version_id AND semantic_key = target_key FOR UPDATE;
    END IF;
    new_active := prior_state.active;
    new_state := prior_state.state;
    new_continuous := prior_state.continuous_since;
    new_pending := prior_state.pending_deadline;
    new_cooldown := prior_state.cooldown_until;
    new_bindings := COALESCE(candidate_bindings, prior_state.last_bindings,
                             jsonb_build_object('semantic_key', target_key));

    IF spec.primitive = 'DURATION' THEN
        IF NOT input_true THEN
            new_active := false; new_state := 'WAITING';
            new_continuous := NULL; new_pending := NULL;
        ELSIF NOT isfinite(frontier) THEN
            new_active := false; new_state := 'WAITING';
        ELSIF new_continuous IS NULL THEN
            new_active := false; new_state := 'PENDING';
            new_continuous := frontier;
            new_pending := frontier + spec.duration_us * interval '1 microsecond';
        ELSIF prior_state.active THEN
            new_active := true; new_state := 'ACTIVE';
        ELSIF new_pending <= frontier THEN
            new_active := true; new_state := 'ACTIVE';
        ELSE
            new_active := false; new_state := 'PENDING';
        END IF;
    ELSIF spec.primitive = 'ABSENCE' THEN
        IF input_true THEN
            new_active := false; new_state := 'WAITING';
            new_pending := declared_deadline;
        ELSIF new_pending IS NULL THEN
            new_active := false; new_state := 'WAITING';
        ELSIF isfinite(frontier) AND frontier >= new_pending THEN
            new_active := true; new_state := 'ACTIVE';
        ELSE
            new_active := false; new_state := 'PENDING';
        END IF;
    ELSIF spec.primitive = 'COOLDOWN' THEN
        IF input_true THEN
            IF prior_state.active THEN
                new_active := true; new_state := 'ACTIVE';
            ELSIF new_cooldown IS NOT NULL AND (NOT isfinite(frontier) OR new_cooldown > frontier) THEN
                new_active := false; new_state := 'COOLDOWN';
            ELSIF isfinite(frontier) THEN
                new_active := true; new_state := 'ACTIVE'; new_cooldown := NULL;
            ELSE
                new_active := false; new_state := 'WAITING';
            END IF;
        ELSIF prior_state.active THEN
            new_active := false; new_state := 'COOLDOWN';
            new_cooldown := CASE WHEN isfinite(frontier)
                THEN frontier + spec.cooldown_us * interval '1 microsecond' ELSE NULL END;
        ELSIF new_cooldown IS NOT NULL AND (NOT isfinite(frontier) OR new_cooldown > frontier) THEN
            new_active := false; new_state := 'COOLDOWN';
        ELSE
            new_active := false; new_state := 'WAITING'; new_cooldown := NULL;
        END IF;
    ELSE
        IF prior_state.active AND recovery_true THEN
            new_active := false; new_state := 'RECOVERED';
        ELSIF prior_state.active THEN
            new_active := true; new_state := 'ACTIVE';
        ELSIF input_true AND isfinite(frontier) THEN
            new_active := true; new_state := 'ACTIVE';
        ELSIF recovery_true THEN
            new_active := false; new_state := 'RECOVERED';
        ELSE
            new_active := false; new_state := 'ARMED';
        END IF;
    END IF;

    IF new_active IS DISTINCT FROM prior_state.active AND isfinite(frontier) THEN
        canonical := pgreact_internal.canonical_bigint_v1(target_key);
        digest := pgreact_internal.activation_digest(target_version_id, canonical);
        activation := pgreact_internal.activation_uuid(digest);
        SELECT * INTO prior_activation FROM pgreact_internal.activation_state
        WHERE rule_version_id = target_version_id AND activation_id = activation FOR UPDATE;
        event_bindings := COALESCE(new_bindings, jsonb_build_object('semantic_key', target_key));
        IF new_active THEN
            next_generation := COALESCE(prior_activation.generation, 0) + 1;
            INSERT INTO pgreact_internal.activation_state (
                rule_version_id, activation_id, semantic_key, canonical_key,
                canonical_key_digest, key_codec_version, active, generation, revision,
                current_bindings, last_active_bindings, first_seen_at, last_seen_at)
            VALUES (target_version_id, activation, target_key, canonical, digest, 1, true,
                    next_generation, 0, event_bindings, event_bindings,
                    clock_timestamp(), clock_timestamp())
            ON CONFLICT (rule_version_id, activation_id) DO UPDATE SET
                active = true, generation = EXCLUDED.generation, revision = 0,
                current_bindings = EXCLUDED.current_bindings,
                last_active_bindings = EXCLUDED.last_active_bindings,
                last_seen_at = EXCLUDED.last_seen_at, deactivated_at = NULL;
            lifecycle_event := pgreact_internal.emit_event(
                version_row, activation, next_generation, 0, 'ACTIVATE', NULL, event_bindings);
            event_kind := 'ACTIVATE';
        ELSE
            next_generation := COALESCE(prior_activation.generation, 1);
            UPDATE pgreact_internal.activation_state
            SET active = false, current_bindings = NULL,
                deactivated_at = clock_timestamp(), last_seen_at = clock_timestamp()
            WHERE rule_version_id = target_version_id AND activation_id = activation;
            lifecycle_event := pgreact_internal.emit_event(
                version_row, activation, next_generation, 0, 'DEACTIVATE',
                COALESCE(prior_activation.last_active_bindings, event_bindings), NULL);
            event_kind := 'DEACTIVATE';
        END IF;
    ELSE
        next_generation := prior_state.generation;
    END IF;
    UPDATE pgreact_internal.temporal_state AS target
    SET state = temporal_key.new_state, active = temporal_key.new_active,
        input_true = temporal_key.input_true, recovery_true = temporal_key.recovery_true,
        continuous_since = temporal_key.new_continuous,
        pending_deadline = temporal_key.new_pending, cooldown_until = temporal_key.new_cooldown,
        generation = CASE WHEN temporal_key.lifecycle_event IS NULL
                          THEN target.generation ELSE temporal_key.next_generation END,
        last_frontier = temporal_key.frontier, last_bindings = temporal_key.new_bindings,
        updated_at = clock_timestamp()
    WHERE target.rule_version_id = target_version_id AND target.semantic_key = target_key;
    INSERT INTO pgreact_internal.temporal_history (
        rule_version_id, semantic_key, lifecycle_event_id, event_kind,
        primitive_state, input_true, recovery_true, continuous_since,
        pending_deadline, cooldown_until, clock_frontier, bindings)
    VALUES (target_version_id, target_key, lifecycle_event,
            COALESCE(event_kind, 'OBSERVE'), new_state, input_true, recovery_true,
            new_continuous, new_pending, new_cooldown, frontier, new_bindings);
    RETURN COALESCE(lifecycle_event, 0);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.reconcile_temporal_rule(target_version_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE;
    spec pgreact_internal.temporal_rules%ROWTYPE; item record; statement text; changed bigint := 0;
BEGIN
    SELECT * INTO STRICT version_row FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_version_id;
    SELECT * INTO STRICT spec FROM pgreact_internal.temporal_rules
    WHERE rule_version_id = target_version_id;
    statement := format(
        'SELECT (%1$I)::bigint AS semantic_key FROM %2$s WHERE %1$I IS NOT NULL '
        'UNION SELECT semantic_key FROM pgreact_internal.temporal_state WHERE rule_version_id = %3$L::uuid',
        version_row.key_column, version_row.match_relid::regclass, target_version_id::text);
    IF spec.recovery_condition_oid IS NOT NULL THEN
        statement := statement || format(
            ' UNION SELECT (to_jsonb(v) ->> %L)::bigint FROM %s v '
            'WHERE (to_jsonb(v) ->> %L) IS NOT NULL',
            spec.recovery_key_column::text, spec.recovery_condition_oid::regclass,
            spec.recovery_key_column::text);
    END IF;
    FOR item IN EXECUTE statement || ' ORDER BY 1' LOOP
        changed := changed + pgreact_internal.reconcile_temporal_key(
            target_version_id, item.semantic_key);
    END LOOP;
    RETURN changed;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.refresh_decision_program(target_program_id uuid, sampled_time timestamp with time zone)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.decision_program_versions%ROWTYPE;
    program_row pgreact_internal.decision_programs%ROWTYPE;
    old_state pgreact_internal.decision_subject_state%ROWTYPE;
    subject_row record;
    candidate_row record;
    winner_row record;
    desired_state text;
    desired_candidate bigint;
    desired_priority bigint;
    desired_result jsonb;
    competitors jsonb;
    candidate_result jsonb;
    activation uuid;
    generation bigint;
    revision bigint;
    top_count bigint;
    competitor_count bigint;
    competitors_truncated boolean;
    changed bigint := 0;
    had_old boolean;
BEGIN
    -- ponytail: one per-program lock; shard by subject only if throughput requires it.
    PERFORM pg_advisory_xact_lock(hashtextextended(target_program_id::text, 26));
    SELECT * INTO STRICT program_row FROM pgreact_internal.decision_programs
    WHERE program_id = target_program_id AND state <> 'REMOVED';
    SELECT * INTO version_row
    FROM pgreact_internal.decision_program_versions
    WHERE program_id = target_program_id AND state = 'DEPLOYED'
      AND valid_from <= sampled_time
      AND (valid_to IS NULL OR sampled_time < valid_to)
    ORDER BY valid_from DESC, version_no DESC LIMIT 1;
    IF NOT FOUND THEN
        FOR old_state IN SELECT * FROM pgreact_internal.decision_subject_state
                         WHERE program_id = target_program_id FOR UPDATE LOOP
            IF old_state.state = 'WINNER' THEN
                PERFORM pgreact_internal.record_decision_event(
                    target_program_id, old_state.version_id, old_state.subject_key,
                    old_state.winner_candidate, old_state.activation_id, 'WINNER_OUT',
                    old_state.generation, old_state.revision,
                    jsonb_build_object('reason', 'no authoritative decision version'));
            END IF;
            UPDATE pgreact_internal.decision_subject_state
            SET version_id = NULL, state = 'NO_CANDIDATE', winner_candidate = NULL,
                winner_priority = NULL, winner_result = NULL, activation_id = NULL,
                competitors = '[]'::jsonb, last_seen_at = clock_timestamp()
            WHERE program_id = target_program_id AND subject_key = old_state.subject_key;
            UPDATE pgreact_internal.decision_work
            SET activation_id = NULL, claimable = false, state = 'NO_CANDIDATE',
                updated_at = clock_timestamp()
            WHERE program_id = target_program_id AND subject_key = old_state.subject_key;
        END LOOP;
        RETURN 0;
    END IF;
    PERFORM pgreact_internal.load_decision_candidates(version_row.version_id);
    FOR subject_row IN
        SELECT subject_key FROM pg_temp.m26_decision_candidates
        UNION
        SELECT subject_key FROM pgreact_internal.decision_subject_state
        WHERE program_id = target_program_id
        ORDER BY subject_key
    LOOP
        desired_candidate := NULL;
        desired_priority := NULL;
        desired_result := NULL;
        SELECT min(priority), count(*) FILTER (WHERE priority = (SELECT min(c.priority)
               FROM pg_temp.m26_decision_candidates c
               WHERE c.subject_key = subject_row.subject_key))
        INTO desired_priority, top_count
        FROM pg_temp.m26_decision_candidates c
        WHERE c.subject_key = subject_row.subject_key;
        IF desired_priority IS NULL THEN
            desired_state := 'NO_CANDIDATE';
            competitors := '[]'::jsonb;
            competitors_truncated := false;
        ELSE
            competitors := '[]'::jsonb;
            SELECT count(*) INTO competitor_count
            FROM pg_temp.m26_decision_candidates
            WHERE subject_key = subject_row.subject_key;
            competitors_truncated := competitor_count > 25;
            FOR candidate_row IN
                SELECT candidate_key, priority, row_data
                FROM pg_temp.m26_decision_candidates
                WHERE subject_key = subject_row.subject_key
                ORDER BY priority, candidate_key
                LIMIT 25
            LOOP
                candidate_result := pgreact_internal.decision_result(
                    candidate_row.row_data, version_row.result_columns);
                competitors := competitors || jsonb_build_array(jsonb_build_object(
                    'candidate', candidate_row.candidate_key,
                    'priority', candidate_row.priority,
                    'result', candidate_result));
            END LOOP;
            IF top_count > 1 THEN
                desired_state := 'AMBIGUOUS';
            ELSE
                desired_state := 'WINNER';
                SELECT candidate_key, priority, row_data INTO winner_row
                FROM pg_temp.m26_decision_candidates
                WHERE subject_key = subject_row.subject_key
                  AND priority = desired_priority
                ORDER BY candidate_key LIMIT 1;
                desired_candidate := winner_row.candidate_key;
                desired_result := pgreact_internal.decision_result(
                    winner_row.row_data, version_row.result_columns);
            END IF;
        END IF;
        SELECT * INTO old_state FROM pgreact_internal.decision_subject_state
        WHERE program_id = target_program_id AND subject_key = subject_row.subject_key
        FOR UPDATE;
        had_old := FOUND;
        IF NOT had_old AND desired_state = 'NO_CANDIDATE' THEN CONTINUE; END IF;
        activation := CASE WHEN desired_state = 'WINNER' THEN
            pgreact_internal.decision_activation_id(version_row.version_id,
                                                    subject_row.subject_key, desired_candidate)
            ELSE NULL END;
        generation := COALESCE(old_state.generation, 0);
        revision := COALESCE(old_state.revision, 0);
        IF had_old AND old_state.state = 'WINNER'
           AND (desired_state <> 'WINNER' OR old_state.activation_id IS DISTINCT FROM activation) THEN
            PERFORM pgreact_internal.record_decision_event(
                target_program_id, old_state.version_id, old_state.subject_key,
                old_state.winner_candidate, old_state.activation_id, 'WINNER_OUT',
                old_state.generation, old_state.revision,
                jsonb_build_object('reason', CASE WHEN desired_state = 'WINNER'
                    THEN 'winner_replaced' ELSE lower(desired_state) END));
        END IF;
        IF had_old AND old_state.state = 'AMBIGUOUS' AND desired_state <> 'AMBIGUOUS' THEN
            PERFORM pgreact_internal.record_decision_event(
                target_program_id, version_row.version_id, subject_row.subject_key,
                NULL, NULL, 'AMBIGUITY_EXIT', old_state.generation, old_state.revision,
                jsonb_build_object('state', desired_state));
        END IF;
        IF desired_state = 'AMBIGUOUS' AND (NOT had_old OR old_state.state <> 'AMBIGUOUS') THEN
            PERFORM pgreact_internal.record_decision_event(
                target_program_id, version_row.version_id, subject_row.subject_key,
                NULL, NULL, 'AMBIGUITY_ENTER', generation, revision,
                jsonb_build_object('competitors', competitors));
        ELSIF desired_state = 'WINNER' AND (NOT had_old OR old_state.activation_id IS DISTINCT FROM activation) THEN
            generation := generation + 1;
            revision := 0;
            PERFORM pgreact_internal.record_decision_event(
                target_program_id, version_row.version_id, subject_row.subject_key,
                desired_candidate, activation, 'WINNER_IN', generation, revision,
                jsonb_build_object('priority', desired_priority, 'result', desired_result));
        ELSIF desired_state = 'WINNER' AND old_state.winner_result IS DISTINCT FROM desired_result THEN
            revision := revision + 1;
            PERFORM pgreact_internal.record_decision_event(
                target_program_id, version_row.version_id, subject_row.subject_key,
                desired_candidate, activation, 'WINNER_REVISION', generation, revision,
                jsonb_build_object('priority', desired_priority, 'result', desired_result));
        END IF;
        IF desired_state = 'NO_CANDIDATE' AND (NOT had_old OR old_state.state <> 'NO_CANDIDATE') THEN
            PERFORM pgreact_internal.record_decision_event(
                target_program_id, version_row.version_id, subject_row.subject_key,
                NULL, NULL, 'NO_CANDIDATE', generation, revision, '{}'::jsonb);
        END IF;
        INSERT INTO pgreact_internal.decision_subject_state(
            program_id, subject_key, version_id, state, winner_candidate,
            winner_priority, winner_result, activation_id, generation, revision,
            competitors, competitors_truncated, first_seen_at, last_seen_at)
        VALUES (target_program_id, subject_row.subject_key, version_row.version_id,
                desired_state, desired_candidate, desired_priority, desired_result,
                activation, generation, revision, competitors, competitors_truncated,
                COALESCE(old_state.first_seen_at, clock_timestamp()), clock_timestamp())
        ON CONFLICT (program_id, subject_key) DO UPDATE SET
            version_id = EXCLUDED.version_id, state = EXCLUDED.state,
            winner_candidate = EXCLUDED.winner_candidate,
            winner_priority = EXCLUDED.winner_priority,
            winner_result = EXCLUDED.winner_result,
            activation_id = EXCLUDED.activation_id, generation = EXCLUDED.generation,
            revision = EXCLUDED.revision, competitors = EXCLUDED.competitors,
            competitors_truncated = EXCLUDED.competitors_truncated,
            last_seen_at = EXCLUDED.last_seen_at;
        INSERT INTO pgreact_internal.decision_work(
            program_id, subject_key, activation_id, claimable, state)
        VALUES (target_program_id, subject_row.subject_key, activation,
                desired_state = 'WINNER', desired_state)
        ON CONFLICT (program_id, subject_key) DO UPDATE SET
            activation_id = EXCLUDED.activation_id, claimable = EXCLUDED.claimable,
            state = EXCLUDED.state, updated_at = clock_timestamp();
        changed := changed + 1;
    END LOOP;
    RETURN changed;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.register_effective_policy(target_policy_name text, target_rule_version_id uuid, target_valid_from timestamp with time zone, target_valid_to timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE diagnostic record;
    policy_id uuid;
    policy_version_id uuid := gen_random_uuid();
    owner_id oid;
    next_version integer;
    frontier timestamptz;
    rule_state text;
BEGIN
    SELECT result.* INTO diagnostic
    FROM pgreact_internal.validate_effective_policy(
        target_policy_name, target_rule_version_id, target_valid_from, target_valid_to) result
    WHERE result.severity = 'ERROR'
    ORDER BY result.code
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react effective-policy validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    SELECT owner_oid INTO STRICT owner_id
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_rule_version_id;
    SELECT clock.frontier INTO STRICT frontier
    FROM pgreact_internal.clock_frontier clock;

    SELECT policy.policy_id INTO policy_id
    FROM pgreact_internal.effective_policies policy
    WHERE policy.policy_name = target_policy_name
    FOR UPDATE;
    IF policy_id IS NULL THEN
        policy_id := gen_random_uuid();
        INSERT INTO pgreact_internal.effective_policies (
            policy_id, policy_name, owner_oid
        ) VALUES (policy_id, target_policy_name, owner_id);
    END IF;
    SELECT COALESCE(max(version), 0) + 1 INTO next_version
    FROM pgreact_internal.effective_policy_versions
    WHERE effective_policy_versions.policy_id = policy_id;
    INSERT INTO pgreact_internal.effective_policy_versions (
        policy_version_id, policy_id, rule_version_id, version,
        valid_from, valid_to, deployment_state, effective_state
    ) VALUES (
        policy_version_id, policy_id, target_rule_version_id, next_version,
        target_valid_from, target_valid_to, 'DEPLOYED',
        pgreact_internal.m24_policy_version_state(
            target_valid_from, target_valid_to, 'DEPLOYED', frontier));
    PERFORM pgreact_internal.m24_record(
        policy_id, policy_version_id, 'DEPLOYED', frontier,
        jsonb_build_object('deployment_frontier', frontier,
                           'valid_from', target_valid_from,
                           'valid_to', target_valid_to));
    SELECT state INTO STRICT rule_state
    FROM pgreact_internal.rule_versions
    WHERE rule_version_id = target_rule_version_id;
    IF target_valid_from > frontier THEN
        IF rule_state = 'ACTIVE' AND EXISTS (
            SELECT 1 FROM pgreact_internal.activation_state
            WHERE rule_version_id = target_rule_version_id AND active
        ) THEN
            RAISE EXCEPTION 'M24_FUTURE_RULE_ACTIVE: future policy version % already has active matches',
                target_rule_version_id
                USING HINT = 'Pause and reconcile the rule before scheduling it.';
        END IF;
        UPDATE pgreact_internal.rule_versions SET state = 'PAUSED'
        WHERE rule_version_id = target_rule_version_id AND state = 'ACTIVE';
    END IF;
    PERFORM pgreact_internal.m24_advance();
    RETURN policy_version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.register_effective_program(target_policy_name text, target_definition jsonb, target_valid_from timestamp with time zone, target_valid_to timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE diagnostic record;
    policy_id uuid;
    policy_version_id uuid := gen_random_uuid();
    owner_id oid;
    next_version integer;
    frontier timestamptz;
BEGIN
    SELECT result.* INTO diagnostic
    FROM pgreact_internal.validate_effective_program(
        target_policy_name, target_definition, target_valid_from, target_valid_to) result
    WHERE result.severity = 'ERROR'
    ORDER BY result.code
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react effective-program validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    SELECT oid INTO STRICT owner_id
    FROM pg_roles WHERE rolname = session_user;
    SELECT clock.frontier INTO STRICT frontier
    FROM pgreact_internal.clock_frontier clock;
    SELECT policy.policy_id INTO policy_id
    FROM pgreact_internal.effective_policies policy
    WHERE policy.policy_name = target_policy_name
    FOR UPDATE;
    IF policy_id IS NULL THEN
        policy_id := gen_random_uuid();
        INSERT INTO pgreact_internal.effective_policies (
            policy_id, policy_name, owner_oid
        ) VALUES (policy_id, target_policy_name, owner_id);
    END IF;
    SELECT COALESCE(max(version), 0) + 1 INTO next_version
    FROM pgreact_internal.effective_policy_versions
    WHERE effective_policy_versions.policy_id = policy_id;
    INSERT INTO pgreact_internal.effective_policy_versions (
        policy_version_id, policy_id, target_kind, program_definition, version,
        valid_from, valid_to, deployment_state, effective_state
    ) VALUES (
        policy_version_id, policy_id, 'PROGRAM', target_definition, next_version,
        target_valid_from, target_valid_to, 'DEPLOYED',
        pgreact_internal.m24_policy_version_state(
            target_valid_from, target_valid_to, 'DEPLOYED', frontier));
    PERFORM pgreact_internal.m24_record(
        policy_id, policy_version_id, 'DEPLOYED', frontier,
        jsonb_build_object('deployment_frontier', frontier,
                           'target_kind', 'PROGRAM',
                           'program', target_definition ->> 'name',
                           'version', target_definition ->> 'version',
                           'valid_from', target_valid_from,
                           'valid_to', target_valid_to));
    PERFORM pgreact_internal.m24_advance();
    RETURN policy_version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.register_parameter_family(target_family_name text, target_relation regclass, target_key_column name, target_value_columns name[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE diagnostic record;
    family_id uuid := gen_random_uuid();
    owner_id oid := (SELECT oid FROM pg_roles WHERE rolname = session_user);
    value_types jsonb;
    signature bytea;
    row_count bigint;
BEGIN
    SELECT result.* INTO diagnostic
    FROM pgreact_internal.validate_parameter_family(
        target_family_name, target_relation, target_key_column, target_value_columns) result
    WHERE result.severity = 'ERROR'
    ORDER BY result.code LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'pg-react parameter-family validation % for %: %',
            diagnostic.code, diagnostic.object_identity, diagnostic.message
            USING HINT = diagnostic.hint;
    END IF;
    IF EXISTS (SELECT 1 FROM pgreact_internal.parameter_families
               WHERE family_name = target_family_name AND state = 'ACTIVE') THEN
        RAISE EXCEPTION 'an active parameter family named % already exists', target_family_name;
    END IF;
    SELECT details -> 'value_types' INTO value_types
    FROM pgreact_internal.validate_parameter_family(
        target_family_name, target_relation, target_key_column, target_value_columns)
    WHERE code = 'OK';
    signature := pgreact_internal.source_row_signature(target_relation);
    EXECUTE format('SELECT count(*) FROM %s', target_relation::regclass) INTO row_count;
    IF row_count > 100000 THEN
        RAISE EXCEPTION 'M25_PARAMETER_LIMIT: parameter relation % has % rows; maximum is 100000',
            target_relation, row_count USING HINT = 'Partition or archive parameter data before declaring the family.';
    END IF;
    INSERT INTO pgreact_internal.parameter_families(
        family_id, family_name, owner_oid, parameter_relation_oid,
        parameter_relation_name, parameter_key_column, parameter_value_columns,
        parameter_value_types, source_signature)
    VALUES (
        family_id, target_family_name, owner_id, target_relation,
        target_relation::text, target_key_column, target_value_columns,
        value_types, signature);
    EXECUTE format(
        'CREATE CONSTRAINT TRIGGER pgreact_parameter_family_guard '
        'AFTER INSERT OR UPDATE OR DELETE ON %s DEFERRABLE INITIALLY DEFERRED '
        'FOR EACH ROW EXECUTE FUNCTION pgreact_internal.parameter_family_dml_guard(%L)',
        target_relation::regclass, family_id::text);
    INSERT INTO pgreact_internal.parameter_family_events(family_id, event_kind, details)
    VALUES (family_id, 'FAMILY_CREATED', jsonb_build_object(
        'relation', target_relation::text, 'key_column', target_key_column,
        'value_columns', target_value_columns, 'row_count', row_count));
    RETURN family_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.register_reference_rule(rule_name text, source_view regclass, key_column name, consequence regprocedure, bootstrap_policy text DEFAULT 'SEED_CURRENT'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    installer_oid oid := (SELECT oid FROM pg_catalog.pg_roles WHERE rolname = session_user);
    source_row record;
    function_row record;
    rule_id uuid := gen_random_uuid();
    version_id uuid := gen_random_uuid();
    match_table text := 'm0_' || substring(replace(version_id::text, '-', ''), 1, 20);
    match_qualified text;
    source_qualified text;
    function_qualified text;
    function_identity text;
    function_digest bytea;
    source_signature bytea;
    dispatcher_name text := 'dispatch_' || replace(version_id::text, '-', '');
    dispatcher_qualified text;
    dispatcher_proc_oid oid;
    null_count bigint;
    duplicate_count bigint;
    current_count bigint;
    seeded record;
    canonical bytea;
    digest bytea;
BEGIN
    PERFORM pgreact_internal.assert_m0_compatibility();
    IF bootstrap_policy NOT IN ('SEED_CURRENT', 'REQUIRE_EMPTY') THEN
        RAISE EXCEPTION 'bootstrap policy must be SEED_CURRENT or REQUIRE_EMPTY';
    END IF;

    SELECT c.relkind, c.relowner, c.reltype,
           format('%I.%I', n.nspname, c.relname) AS qualified,
           pg_catalog.pg_get_viewdef(c.oid, true) AS definition
    INTO STRICT source_row
    FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
    WHERE c.oid = source_view;
    IF source_row.relkind <> 'v' THEN
        RAISE EXCEPTION 'pg-react M0 source % must be a normal view', source_view;
    END IF;
    IF source_row.relowner <> installer_oid THEN
        RAISE EXCEPTION 'rule owner must own source view %', source_view;
    END IF;
    source_qualified := source_row.qualified;
    source_signature := pgreact_internal.source_row_signature(source_view);
    IF NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_attribute
        WHERE attrelid = source_view AND attname = key_column
          AND atttypid = 'bigint'::regtype AND attnum > 0 AND NOT attisdropped
    ) THEN
        RAISE EXCEPTION 'key %.% must be bigint', source_view, key_column;
    END IF;

    IF consequence IS NOT NULL THEN
        SELECT p.proowner, p.prorettype, p.pronargs, p.proargtypes,
               format('%I.%I', n.nspname, p.proname) AS qualified,
               p.oid::regprocedure::text AS identity
        INTO STRICT function_row
        FROM pg_catalog.pg_proc p
        JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
        WHERE p.oid = consequence;
        IF function_row.proowner <> installer_oid OR function_row.prorettype <> 'void'::regtype
           OR function_row.pronargs <> 2
           OR function_row.proargtypes[0] <> 'pgreact.activation_context'::regtype
           OR function_row.proargtypes[1] <> source_row.reltype THEN
            RAISE EXCEPTION 'consequence % must be owned by the rule owner and have signature (pgreact.activation_context, %) RETURNS void',
                consequence, source_qualified;
        END IF;
        function_qualified := function_row.qualified;
        function_identity := function_row.identity;
        function_digest := sha256(convert_to(pg_catalog.pg_get_functiondef(consequence), 'UTF8'));
    END IF;

    match_qualified := format('%I.%I', 'pgreact_runtime', match_table);
    dispatcher_qualified := format('%I.%I', 'pgreact_runtime', dispatcher_name);

    INSERT INTO pgreact_internal.rules VALUES (rule_id, rule_name, installer_oid, clock_timestamp());
    INSERT INTO pgreact_internal.rule_versions (
        rule_version_id, rule_id, owner_oid, source_view_oid, source_view_name,
        source_definition, source_definition_digest, source_row_signature, key_column, match_name,
        consequence_oid, consequence_identity, consequence_digest,
        bootstrap_policy, refresh_mode, isolation_level, state
    ) VALUES (
        version_id, rule_id, installer_oid, source_view, source_qualified,
        source_row.definition, sha256(convert_to(source_row.definition, 'UTF8')), source_signature,
        key_column, match_qualified, consequence, function_identity, function_digest,
        bootstrap_policy, 'DIFFERENTIAL', 'read committed', 'INITIALIZING'
    );

    PERFORM pgreact_internal.create_m0_stream(
        match_qualified,
        format('SELECT * FROM %s', source_qualified)
    );

    UPDATE pgreact_internal.rule_versions
    SET match_relid = match_qualified::regclass
    WHERE rule_version_id = version_id;

    IF consequence IS NOT NULL THEN
        EXECUTE format(
            'CREATE FUNCTION %s(context pgreact.activation_context, bindings jsonb) '
            'RETURNS void LANGUAGE SQL SECURITY DEFINER '
            'SET search_path = pg_catalog, pg_temp '
            'AS $dispatcher$ SELECT %s($1, pg_catalog.jsonb_populate_record(NULL::%s, $2)) $dispatcher$',
            dispatcher_qualified, function_qualified, source_qualified
        );
        EXECUTE format('ALTER FUNCTION %s(pgreact.activation_context,jsonb) OWNER TO %I',
                       dispatcher_qualified, session_user);
        EXECUTE format('REVOKE ALL ON FUNCTION %s(pgreact.activation_context,jsonb) FROM PUBLIC',
                       dispatcher_qualified);
        dispatcher_proc_oid := to_regprocedure(dispatcher_qualified || '(pgreact.activation_context,jsonb)');

        UPDATE pgreact_internal.rule_versions SET
            dispatcher_oid = dispatcher_proc_oid,
            dispatcher_identity = dispatcher_proc_oid::regprocedure::text,
            dispatcher_digest = sha256(convert_to(pg_catalog.pg_get_functiondef(dispatcher_proc_oid), 'UTF8'))
        WHERE rule_version_id = version_id;
    END IF;

    EXECUTE format(
        'CREATE TRIGGER pgreact_capture AFTER INSERT OR UPDATE OR DELETE ON %s '
        'FOR EACH ROW EXECUTE FUNCTION pgreact_internal.capture_match_delta(%L, %L)',
        match_qualified, version_id::text, key_column::text
    );
    EXECUTE format(
        'CREATE CONSTRAINT TRIGGER pgreact_finalize AFTER INSERT OR UPDATE OR DELETE ON %s '
        'DEFERRABLE INITIALLY DEFERRED FOR EACH ROW '
        'EXECUTE FUNCTION pgreact_internal.finalize_match_delta(%L)',
        match_qualified, version_id::text
    );

    EXECUTE format('SELECT count(*) FROM %s WHERE %I IS NULL', match_qualified, key_column)
        INTO null_count;
    EXECUTE format(
        'SELECT count(*) FROM (SELECT %I FROM %s GROUP BY %I HAVING count(*) > 1) d',
        key_column, match_qualified, key_column
    ) INTO duplicate_count;
    EXECUTE format('SELECT count(*) FROM %s', match_qualified) INTO current_count;
    IF null_count > 0 OR duplicate_count > 0 THEN
        RAISE EXCEPTION 'source % has % null and % duplicate bigint keys',
            source_qualified, null_count, duplicate_count;
    END IF;
    IF bootstrap_policy = 'REQUIRE_EMPTY' AND current_count > 0 THEN
        RAISE EXCEPTION 'REQUIRE_EMPTY source % currently has % matches', source_qualified, current_count;
    END IF;

    IF bootstrap_policy = 'SEED_CURRENT' THEN
        FOR seeded IN EXECUTE format(
            'SELECT %I::bigint AS semantic_key, to_jsonb(m) AS bindings FROM %s m',
            key_column, match_qualified
        ) LOOP
            canonical := pgreact_internal.canonical_bigint_v1(seeded.semantic_key);
            digest := pgreact_internal.activation_digest(version_id, canonical);
            INSERT INTO pgreact_internal.activation_state (
                rule_version_id, activation_id, semantic_key, canonical_key,
                canonical_key_digest, key_codec_version, active, generation,
                current_bindings, last_active_bindings, first_seen_at, last_seen_at
            ) VALUES (
                version_id, pgreact_internal.activation_uuid(digest), seeded.semantic_key,
                canonical, digest, 1, true, 1, seeded.bindings, seeded.bindings,
                clock_timestamp(), clock_timestamp()
            );
        END LOOP;
    END IF;

    UPDATE pgreact_internal.rule_versions SET state = 'ACTIVE'
    WHERE rule_version_id = version_id;
    RETURN version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.remove_derivation_rule_m7(target_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE derivation pgreact_internal.derivation_rule_versions%ROWTYPE;
BEGIN
    PERFORM pgreact_internal.assert_rule_owner(target_version_id);
    SELECT * INTO STRICT derivation
    FROM pgreact_internal.derivation_rule_versions
    WHERE rule_version_id = target_version_id;
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    PERFORM pgreact_internal.retire_derivation_rule(target_version_id);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.remove_rule_m7(target_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE version_row pgreact_internal.rule_versions%ROWTYPE; dispatcher_name text;
BEGIN
    version_row := pgreact_internal.assert_rule_owner(target_version_id);
    IF version_row.state <> 'PAUSED' OR EXISTS (
        SELECT 1 FROM pgreact_internal.agenda WHERE rule_version_id = target_version_id AND state IN ('PENDING', 'LEASED')
    ) THEN
        RAISE EXCEPTION 'removal requires a paused rule with no pending or leased episodes';
    END IF;
    PERFORM pgtrickle.drop_stream_table(version_row.match_name, true);
    IF version_row.dispatcher_oid IS NOT NULL THEN
        SELECT format('%I.%I', n.nspname, p.proname) INTO dispatcher_name
        FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
        WHERE p.oid = version_row.dispatcher_oid;
        IF dispatcher_name IS NOT NULL THEN
            EXECUTE format('DROP FUNCTION IF EXISTS %s(pgreact.activation_context, jsonb)', dispatcher_name);
        END IF;
    END IF;
    UPDATE pgreact_internal.rule_versions SET state = 'REMOVED', match_relid = NULL WHERE rule_version_id = target_version_id;
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.replace_derivation_rule_m7(target_version_id uuid, definition regclass, key_columns name[], rule_version integer, bootstrap_policy text DEFAULT 'SEED_CURRENT'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    prior pgreact_internal.rule_versions%ROWTYPE;
    derivation pgreact_internal.derivation_rule_versions%ROWTYPE;
    next_version uuid;
    orphan_rule uuid;
    rule_name text;
BEGIN
    prior := pgreact_internal.assert_rule_owner(target_version_id);
    SELECT * INTO STRICT derivation
    FROM pgreact_internal.derivation_rule_versions
    WHERE rule_version_id = target_version_id;
    IF prior.state NOT IN ('ACTIVE', 'PAUSED') THEN
        RAISE EXCEPTION 'only active or paused derivations can be replaced';
    END IF;
    SELECT r.rule_name INTO STRICT rule_name
    FROM pgreact_internal.rules r WHERE r.rule_id = prior.rule_id;
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    UPDATE pgreact_internal.rule_versions SET state = 'REMOVED'
    WHERE rule_version_id = target_version_id;
    next_version := pgreact.create_derivation_rule(
        rule_name, definition, key_columns, derivation.relation_version_id,
        rule_version, bootstrap_policy);
    SELECT rule_id INTO STRICT orphan_rule
    FROM pgreact_internal.rule_versions WHERE rule_version_id = next_version;
    UPDATE pgreact_internal.rule_versions SET rule_id = prior.rule_id
    WHERE rule_version_id = next_version;
    UPDATE pgreact_internal.derivation_rule_versions SET rule_id = prior.rule_id
    WHERE rule_version_id = next_version;
    DELETE FROM pgreact_internal.rules WHERE rule_id = orphan_rule;
    PERFORM pgreact_internal.retire_derivation_rule(target_version_id);
    RETURN next_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.replace_derived_relation(target_relation uuid, row_type regtype, key_columns name[], relation_version integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    prior pgreact_internal.derived_relation_versions%ROWTYPE;
    next_version uuid := gen_random_uuid();
    type_row record;
BEGIN
    prior := pgreact_internal.assert_derived_owner(target_relation);
    IF prior.state <> 'ACTIVE' THEN
        RAISE EXCEPTION 'only an active derived relation can be replaced';
    END IF;
    SELECT t.typowner, format('%I.%I', n.nspname, t.typname) AS identity
    INTO STRICT type_row
    FROM pg_catalog.pg_type t
    JOIN pg_catalog.pg_namespace n ON n.oid = t.typnamespace
    WHERE t.oid = row_type AND t.typtype = 'c';
    IF type_row.typowner <> prior.owner_oid
       OR cardinality(key_columns) IS DISTINCT FROM 1
       OR key_columns[1] IS DISTINCT FROM prior.key_column
       OR pgreact_internal.composite_type_signature(row_type) IS DISTINCT FROM prior.row_signature THEN
        RAISE EXCEPTION 'M7 derived relation replacement must preserve the exact row type and key';
    END IF;
    IF relation_version <= prior.version THEN
        RAISE EXCEPTION 'derived relation replacement version must increase beyond %', prior.version;
    END IF;
    UPDATE pgreact_internal.derived_relation_versions SET state = 'REMOVED'
    WHERE relation_version_id = target_relation;
    INSERT INTO pgreact_internal.derived_relation_versions (
        relation_version_id, relation_id, version, owner_oid, row_type_oid,
        row_type_name, row_signature, key_column, public_view_oid,
        public_view_name, state
    ) VALUES (
        next_version, prior.relation_id, relation_version, prior.owner_oid,
        row_type, type_row.identity, prior.row_signature, prior.key_column,
        prior.public_view_oid, prior.public_view_name, 'ACTIVE'
    );
    EXECUTE format(
        'CREATE OR REPLACE VIEW %s WITH (security_barrier=true) AS '
        'SELECT (pg_catalog.jsonb_populate_record(NULL::%s, f.fact)).* '
        'FROM pgreact_internal.derived_facts f WHERE f.relation_version_id = %L::uuid',
        prior.public_view_name, type_row.identity, next_version
    );
    RETURN next_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.replace_keyed_rule(rule_name text, condition regclass, key_columns name[], action_schema name, on_activate name, on_deactivate name DEFAULT NULL::name, on_change name DEFAULT NULL::name, deadline_column name DEFAULT NULL::name)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    prior_version uuid;
    wrapper regclass;
    next_version uuid;
    event_kind text;
    selected_action name;
    action regprocedure;
    activate_proxy regprocedure;
    deactivate_proxy regprocedure;
    change_proxy regprocedure;
    key_types regtype[];
    key_collations regcollation[];
BEGIN
    PERFORM pgreact_internal.assert_key_columns(condition, key_columns);
    SELECT version.rule_version_id INTO prior_version
    FROM pgreact_internal.rules rule
    JOIN pgreact_internal.rule_versions version USING (rule_id)
    WHERE rule.rule_name = replace_keyed_rule.rule_name
      AND version.state IN ('ACTIVE', 'PAUSED')
    ORDER BY version.created_at DESC LIMIT 1;
    IF prior_version IS NULL THEN
        RAISE EXCEPTION 'M15_RULE_NOT_FOUND: %', rule_name;
    END IF;
    wrapper := pgreact_internal.create_key_wrapper(condition, key_columns);
    FOR event_kind, selected_action IN
        SELECT * FROM (VALUES
            ('ACTIVATE'::text, on_activate),
            ('DEACTIVATE'::text, on_deactivate),
            ('CHANGE'::text, on_change)) actions(selected_event, selected_name)
        WHERE selected_name IS NOT NULL
    LOOP
        action := pgreact_internal.resolve_action(
            action_schema, selected_action, condition, event_kind);
        action := pgreact_internal.create_action_proxy(
            prior_version, event_kind, action, condition, wrapper);
        CASE event_kind
            WHEN 'ACTIVATE' THEN activate_proxy := action;
            WHEN 'DEACTIVATE' THEN deactivate_proxy := action;
            WHEN 'CHANGE' THEN change_proxy := action;
        END CASE;
    END LOOP;
    next_version := pgreact.replace_rule(
        prior_version, wrapper, ARRAY['__pgreact_key'::name], NULL,
        'SEED_CURRENT', NULL, NULL, 'DRAIN_OLD');
    IF activate_proxy IS NOT NULL THEN
        PERFORM pgreact_internal.add_resolved_binding(
            next_version, 'ACTIVATE', activate_proxy);
    END IF;
    IF deactivate_proxy IS NOT NULL THEN
        PERFORM pgreact_internal.add_resolved_binding(
            next_version, 'DEACTIVATE', deactivate_proxy);
    END IF;
    IF change_proxy IS NOT NULL THEN
        PERFORM pgreact_internal.add_resolved_binding(
            next_version, 'CHANGE', change_proxy);
    END IF;
    IF deadline_column IS NOT NULL THEN
        next_version := pgreact_internal.mark_deadline_rule(
            next_version, deadline_column, 'SEED_CURRENT');
    END IF;
    UPDATE pgreact_internal.consequence_bindings
    SET max_attempts = 3
    WHERE rule_version_id = next_version;
    SELECT array_agg(attribute.atttypid::regtype ORDER BY key.ordinality),
           array_agg(attribute.attcollation::regcollation ORDER BY key.ordinality)
    INTO key_types, key_collations
    FROM unnest(key_columns) WITH ORDINALITY key(key_column, ordinality)
    JOIN pg_attribute attribute
      ON attribute.attrelid = condition AND attribute.attname = key.key_column
     AND attribute.attnum > 0 AND NOT attribute.attisdropped;
    INSERT INTO pgreact_internal.keyed_rule_versions VALUES (
        next_version, condition, wrapper, key_columns, key_types, key_collations);
    RETURN next_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.replace_pack_rule(target_version_id uuid, rule_name text, definition regclass, key_columns name[], kind text, on_activate regprocedure, on_deactivate regprocedure, on_change regprocedure, bootstrap_policy text, change_columns name[], salience integer, agenda_group text, conflict_key_columns name[], max_attempts integer, initial_backoff_seconds integer, backoff_multiplier numeric, max_backoff_seconds integer, old_work_policy text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE
    prior pgreact_internal.rule_versions%ROWTYPE;
    next_version uuid;
    orphan_rule uuid;
    temporary_name text := rule_name || '#m54-' || replace(gen_random_uuid()::text, '-', '');
BEGIN
    prior := pgreact_internal.assert_rule_owner(target_version_id);
    IF prior.state NOT IN ('ACTIVE', 'PAUSED') THEN
        RAISE EXCEPTION 'only active or paused versions can be replaced';
    END IF;
    IF old_work_policy = 'CANCEL_OLD' THEN
        UPDATE pgreact_internal.agenda SET state = 'CANCELLED', completed_at = clock_timestamp()
        WHERE rule_version_id = target_version_id AND state IN ('PENDING', 'RETRY_WAIT');
    END IF;
    PERFORM pgreact_internal.maybe_fail_pack('catalog');
    UPDATE pgreact_internal.rules SET rule_name = temporary_name WHERE rule_id = prior.rule_id;
    UPDATE pgreact_internal.rule_versions SET state = 'REMOVED' WHERE rule_version_id = target_version_id;
    PERFORM pgreact_internal.maybe_fail_pack('rules');
    next_version := pgreact.create_rule(rule_name, definition, key_columns, kind,
        on_activate, on_deactivate, on_change, bootstrap_policy, change_columns,
        salience, agenda_group, conflict_key_columns, max_attempts,
        initial_backoff_seconds, backoff_multiplier, max_backoff_seconds);
    PERFORM pgreact_internal.maybe_fail_pack('generated');
    SELECT rule_id INTO orphan_rule FROM pgreact_internal.rule_versions WHERE rule_version_id = next_version;
    UPDATE pgreact_internal.rule_versions SET rule_id = prior.rule_id WHERE rule_version_id = next_version;
    DELETE FROM pgreact_internal.rules WHERE rule_id = orphan_rule;
    PERFORM pgreact_internal.maybe_fail_pack('removals');
    UPDATE pgreact_internal.rules SET rule_name = replace_pack_rule.rule_name WHERE rule_id = prior.rule_id;
    IF prior.match_relid IS NOT NULL THEN
        PERFORM pgtrickle.drop_stream_table(prior.match_name, true);
    END IF;
    PERFORM pgreact_internal.maybe_fail_pack('activation');
    UPDATE pgreact_internal.rule_versions
    SET match_relid = NULL,
        state = CASE WHEN EXISTS (
            SELECT 1 FROM pgreact_internal.agenda
            WHERE rule_version_id = target_version_id AND state IN ('PENDING', 'LEASED', 'RETRY_WAIT')
        ) THEN 'DRAINING' ELSE 'REMOVED' END
    WHERE rule_version_id = target_version_id;
    RETURN next_version;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.replace_rule_m7(target_version_id uuid, definition regclass, key_columns name[], on_activate regprocedure DEFAULT NULL::regprocedure, bootstrap_policy text DEFAULT 'SEED_CURRENT'::text, on_deactivate regprocedure DEFAULT NULL::regprocedure, on_change regprocedure DEFAULT NULL::regprocedure, old_work_policy text DEFAULT 'DRAIN_OLD'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE prior pgreact_internal.rule_versions%ROWTYPE; next_version uuid; orphan_rule uuid;
BEGIN
    prior := pgreact_internal.assert_rule_owner(target_version_id);
    IF prior.state NOT IN ('ACTIVE', 'PAUSED') THEN RAISE EXCEPTION 'only active or paused versions can be replaced'; END IF;
    IF old_work_policy NOT IN ('DRAIN_OLD', 'CANCEL_OLD') THEN RAISE EXCEPTION 'old_work_policy must be DRAIN_OLD or CANCEL_OLD'; END IF;
    -- Temporarily retire the old name only while the immutable green version is compiled.
    -- It is restored to DRAINING before this transaction commits.
    UPDATE pgreact_internal.rule_versions SET state = 'REMOVED' WHERE rule_version_id = target_version_id;
    IF old_work_policy = 'CANCEL_OLD' THEN
        UPDATE pgreact_internal.agenda SET state = 'CANCELLED', completed_at = clock_timestamp()
        WHERE rule_version_id = target_version_id AND state IN ('PENDING', 'RETRY_WAIT');
    END IF;
    next_version := pgreact.create_rule((SELECT rule_name FROM pgreact_internal.rules WHERE rule_id = prior.rule_id),
        definition, key_columns, NULL, on_activate, on_deactivate, on_change, bootstrap_policy);
    SELECT rule_id INTO orphan_rule FROM pgreact_internal.rule_versions WHERE rule_version_id = next_version;
    UPDATE pgreact_internal.rule_versions SET rule_id = prior.rule_id WHERE rule_version_id = next_version;
    DELETE FROM pgreact_internal.rules WHERE rule_id = orphan_rule;
    UPDATE pgreact_internal.rule_versions SET state = CASE WHEN EXISTS (
        SELECT 1 FROM pgreact_internal.agenda
        WHERE rule_version_id = target_version_id AND state IN ('PENDING', 'LEASED', 'RETRY_WAIT')
    ) THEN 'DRAINING' ELSE 'REMOVED' END
    WHERE rule_version_id = target_version_id;
    RETURN next_version;
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.requeue_episode_m7(target_episode_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE episode pgreact_internal.agenda%ROWTYPE;
BEGIN
    SELECT * INTO STRICT episode FROM pgreact_internal.agenda WHERE episode_id = target_episode_id FOR UPDATE;
    PERFORM pgreact_internal.assert_rule_owner(episode.rule_version_id);
    IF episode.state NOT IN ('FAILED', 'CANCELLED', 'WITHDRAWN') THEN RAISE EXCEPTION 'only terminal episodes can be manually requeued'; END IF;
    UPDATE pgreact_internal.agenda SET state = 'PENDING', lease_token = NULL, worker_id = NULL,
        claimed_at = NULL, lease_expires_at = NULL, available_at = clock_timestamp(), last_error = NULL
    WHERE episode_id = target_episode_id;
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.resume_rule_m7(target_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
    PERFORM pgreact_internal.assert_rule_owner(target_version_id);
    IF EXISTS (SELECT 1 FROM pgreact_internal.rule_barriers WHERE rule_version_id = target_version_id) THEN
        RAISE EXCEPTION 'cannot resume rule version % while its claim barrier is present', target_version_id;
    END IF;
    UPDATE pgreact_internal.rule_versions SET state = 'ACTIVE' WHERE rule_version_id = target_version_id AND state = 'PAUSED';
    IF NOT FOUND THEN RAISE EXCEPTION 'rule version % is not paused', target_version_id; END IF;
END $function$

CREATE OR REPLACE FUNCTION pgreact_internal.retention_apply_family_m21(target_family text, target_cutoff timestamp with time zone, target_batch_size integer, target_policy_version bigint, target_batch_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE item record; removed bigint := 0;
BEGIN
    IF target_family = 'runtime_events' THEN
        FOR item IN SELECT r.runtime_event_id, r.event_type, r.occurred_at FROM pgreact_internal.runtime_events r
                    WHERE r.occurred_at < target_cutoff ORDER BY r.runtime_event_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.runtime_event_id::text, item.event_type,
                to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.runtime_events WHERE runtime_event_id=item.runtime_event_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'executions' THEN
        FOR item IN SELECT e.execution_id, e.episode_id, e.status, e.finished_at FROM pgreact_internal.executions e
                    WHERE e.finished_at < target_cutoff ORDER BY e.execution_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.execution_id::text, item.status,
                to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.executions WHERE execution_id=item.execution_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derived_support_inputs' THEN
        FOR item IN SELECT i.support_id, i.input_order FROM pgreact_internal.derived_support_inputs i
                    JOIN pgreact_internal.derived_supports s USING (support_id)
                    WHERE NOT s.active AND s.invalidated_at < target_cutoff
                    ORDER BY i.support_id, i.input_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.support_id::text || ':' || item.input_order,
                'support_input', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derived_support_inputs WHERE support_id=item.support_id AND input_order=item.input_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'negative_dependency_evidence' THEN
        FOR item IN SELECT e.evidence_id, e.active, e.invalidated_at FROM pgreact_internal.negative_dependency_evidence e
                    WHERE NOT e.active AND e.invalidated_at < target_cutoff ORDER BY e.evidence_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.evidence_id::text, 'negative_evidence', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.negative_dependency_evidence WHERE evidence_id=item.evidence_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'aggregate_dependency_evidence' THEN
        FOR item IN SELECT e.evidence_id, e.active, e.invalidated_at FROM pgreact_internal.aggregate_dependency_evidence e
                    WHERE NOT e.active AND e.invalidated_at < target_cutoff ORDER BY e.evidence_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.evidence_id::text, 'aggregate_evidence', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.aggregate_dependency_evidence WHERE evidence_id=item.evidence_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derived_supports' THEN
        FOR item IN SELECT s.support_id, s.active, s.invalidated_at FROM pgreact_internal.derived_supports s
                    WHERE NOT s.active AND s.invalidated_at < target_cutoff
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derived_support_inputs i WHERE i.support_id=s.support_id)
                    ORDER BY s.support_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.support_id::text, 'inactive_support', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derived_supports WHERE support_id=item.support_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derived_repair_diagnostics' THEN
        FOR item IN SELECT d.reconciliation_id, d.diagnostic_order, d.code FROM pgreact_internal.derived_repair_diagnostics d
                    JOIN pgreact_internal.derived_reconciliations r USING (reconciliation_id)
                    WHERE r.completed_at < target_cutoff AND r.status='COMPLETED'
                    ORDER BY d.reconciliation_id, d.diagnostic_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.reconciliation_id::text || ':' || item.diagnostic_order, item.code, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derived_repair_diagnostics WHERE reconciliation_id=item.reconciliation_id AND diagnostic_order=item.diagnostic_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derived_reconciliations' THEN
        FOR item IN SELECT r.reconciliation_id, r.status, r.completed_at FROM pgreact_internal.derived_reconciliations r
                    WHERE r.completed_at < target_cutoff AND r.status='COMPLETED'
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derived_repair_diagnostics d WHERE d.reconciliation_id=r.reconciliation_id)
                    ORDER BY r.reconciliation_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.reconciliation_id::text, item.status, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derived_reconciliations WHERE reconciliation_id=item.reconciliation_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derivation_program_repair_diagnostics' THEN
        FOR item IN SELECT d.reconciliation_id, d.diagnostic_order, d.code FROM pgreact_internal.derivation_program_repair_diagnostics d
                    JOIN pgreact_internal.derivation_program_reconciliations r USING (reconciliation_id)
                    WHERE r.completed_at < target_cutoff AND r.status='COMPLETED'
                    ORDER BY d.reconciliation_id, d.diagnostic_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.reconciliation_id::text || ':' || item.diagnostic_order, item.code, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derivation_program_repair_diagnostics WHERE reconciliation_id=item.reconciliation_id AND diagnostic_order=item.diagnostic_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derivation_program_iterations' THEN
        FOR item IN SELECT i.run_id, i.component_id, i.iteration, i.completed_at FROM pgreact_internal.derivation_program_iterations i
                    WHERE i.completed_at < target_cutoff ORDER BY i.run_id, i.component_id, i.iteration LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.run_id::text || ':' || item.component_id::text || ':' || item.iteration, 'iteration', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derivation_program_iterations WHERE run_id=item.run_id AND component_id=item.component_id AND iteration=item.iteration; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'derivation_program_runs' THEN
        FOR item IN SELECT r.run_id, r.status, r.completed_at FROM pgreact_internal.derivation_program_runs r
                    WHERE r.completed_at < target_cutoff AND r.status IN ('COMPLETED','NOOP','FAILED')
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derivation_program_iterations i WHERE i.run_id=r.run_id)
                    ORDER BY r.run_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.run_id::text, item.status, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.derivation_program_runs WHERE run_id=item.run_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'window_corrections' THEN
        FOR item IN SELECT c.correction_order, c.correction_identity, c.created_at FROM pgreact_internal.window_corrections c
                    JOIN pgreact_internal.window_programs p USING (program_version_id)
                    WHERE c.created_at < target_cutoff AND NOT p.active ORDER BY c.correction_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.correction_identity, 'window_correction', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.window_corrections WHERE correction_order=item.correction_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'window_diagnostics' THEN
        FOR item IN SELECT d.diagnostic_order, d.code, d.created_at FROM pgreact_internal.window_diagnostics d
                    JOIN pgreact_internal.window_programs p USING (program_version_id)
                    WHERE d.created_at < target_cutoff AND NOT p.active ORDER BY d.diagnostic_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.diagnostic_order::text, item.code, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.window_diagnostics WHERE diagnostic_order=item.diagnostic_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'window_audits' THEN
        FOR item IN SELECT a.audit_order, a.operation, a.created_at FROM pgreact_internal.window_audits a
                    LEFT JOIN pgreact_internal.window_programs p USING (program_version_id)
                    WHERE a.created_at < target_cutoff AND (p.program_version_id IS NULL OR NOT p.active)
                    ORDER BY a.audit_order LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.audit_order::text, item.operation, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.window_audits WHERE audit_order=item.audit_order; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'clock_history' THEN
        FOR item IN SELECT h.clock_event_id, h.frontier, h.advanced_at FROM pgreact_internal.clock_history h
                    WHERE h.advanced_at < target_cutoff ORDER BY h.clock_event_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.clock_event_id::text, 'clock_frontier', to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.clock_history WHERE clock_event_id=item.clock_event_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'reconciliation_audit' THEN
        FOR item IN SELECT r.reconciliation_id, r.status, r.completed_at FROM pgreact_internal.reconciliation_audit r
                    WHERE r.completed_at < target_cutoff AND r.status='COMPLETED' ORDER BY r.reconciliation_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.reconciliation_id::text, rtrim(item.status), to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.reconciliation_audit WHERE reconciliation_id=item.reconciliation_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'metadata_rebuild_audits' THEN
        FOR item IN SELECT r.metadata_rebuild_id, r.status, r.completed_at FROM pgreact_internal.metadata_rebuild_audits r
                    WHERE r.completed_at < target_cutoff AND r.status='COMPLETED' ORDER BY r.metadata_rebuild_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.metadata_rebuild_id::text, item.status, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.metadata_rebuild_audits WHERE metadata_rebuild_id=item.metadata_rebuild_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'agenda' THEN
        FOR item IN SELECT a.episode_id, a.state, a.completed_at FROM pgreact_internal.agenda a
                    WHERE a.completed_at < target_cutoff AND a.state IN ('COMPLETED','FAILED','SKIPPED','WITHDRAWN','CANCELLED','SUPERSEDED')
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.executions e WHERE e.episode_id=a.episode_id)
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.execution_batch_items i WHERE i.episode_id=a.episode_id)
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.conflict_leases l WHERE l.episode_id=a.episode_id)
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.runtime_events r WHERE r.episode_id=a.episode_id)
                    ORDER BY a.episode_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.episode_id::text, item.state, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.agenda WHERE episode_id=item.episode_id; removed := removed+1;
        END LOOP;
    ELSIF target_family = 'lifecycle_events' THEN
        FOR item IN SELECT e.event_id, e.event_kind, e.transitioned_at FROM pgreact_internal.lifecycle_events e
                    WHERE e.transitioned_at < target_cutoff
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.activation_state s WHERE s.rule_version_id=e.rule_version_id AND s.activation_id=e.activation_id AND s.active)
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.agenda a WHERE a.event_id=e.event_id)
                      AND NOT EXISTS (SELECT 1 FROM pgreact_internal.deadline_lifecycle d WHERE d.event_id=e.event_id)
                    ORDER BY e.event_id LIMIT target_batch_size LOOP
            PERFORM pgreact_internal.retention_record_tombstone(target_family, item.event_id::text, item.event_kind, to_jsonb(item), target_policy_version, target_batch_id);
            DELETE FROM pgreact_internal.lifecycle_events WHERE event_id=item.event_id; removed := removed+1;
        END LOOP;
    END IF;
    RETURN removed;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.retention_apply_family(target_family text, target_cutoff timestamp with time zone, target_batch_size integer, target_policy_version bigint, target_batch_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE item record; removed bigint := 0;
BEGIN
    IF target_family <> 'evidence_snapshots' THEN
        RETURN pgreact_internal.retention_apply_family_m21(
            target_family, target_cutoff, target_batch_size,
            target_policy_version, target_batch_id);
    END IF;
    FOR item IN SELECT * FROM pgreact_internal.evidence_snapshots s
        WHERE s.captured_at < target_cutoff AND s.deletion_eligible_at <= clock_timestamp()
        ORDER BY s.captured_at, s.snapshot_identity LIMIT target_batch_size LOOP
        PERFORM pgreact_internal.retention_record_tombstone(
            target_family, item.snapshot_identity, 'evidence_snapshot',
            to_jsonb(item), target_policy_version, target_batch_id);
        DELETE FROM pgreact_internal.evidence_snapshots
        WHERE snapshot_identity = item.snapshot_identity;
        removed := removed + 1;
    END LOOP;
    RETURN removed;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.retention_preview_data_m21(target_cutoff timestamp with time zone, target_batch_size integer)
 RETURNS TABLE(family text, relation_name text, eligible_rows bigint, eligible_bytes bigint, protected_rows bigint, protected_bytes bigint, blocking_reasons jsonb, lost_capabilities text[], remediation text, has_more boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE item record; candidate_rows bigint; candidate_bytes bigint;
    rows_ok bigint; bytes_ok bigint;
BEGIN
    IF target_batch_size < 1 THEN RAISE EXCEPTION 'M21_RETENTION_BATCH_SIZE: must be positive'; END IF;
    FOR item IN SELECT * FROM pgreact_internal.retention_families WHERE enabled ORDER BY family LOOP
        candidate_rows := 0; candidate_bytes := 0; rows_ok := 0; bytes_ok := 0;
        IF item.family = 'lifecycle_events' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(e)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.lifecycle_events e WHERE e.transitioned_at < target_cutoff;
            SELECT count(*), COALESCE(sum(pg_column_size(e)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.lifecycle_events e
            WHERE e.transitioned_at < target_cutoff
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.activation_state s
                              WHERE s.rule_version_id = e.rule_version_id
                                AND s.activation_id = e.activation_id AND s.active)
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.agenda a WHERE a.event_id = e.event_id)
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.deadline_lifecycle d WHERE d.event_id = e.event_id);
            blocking_reasons := jsonb_build_object(
                'active_state', (SELECT count(*) FROM pgreact_internal.lifecycle_events e
                    WHERE e.transitioned_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.activation_state s
                        WHERE s.rule_version_id=e.rule_version_id AND s.activation_id=e.activation_id AND s.active)),
                'work_reference', (SELECT count(*) FROM pgreact_internal.lifecycle_events e
                    WHERE e.transitioned_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.agenda a WHERE a.event_id=e.event_id)),
                'deadline_reference', (SELECT count(*) FROM pgreact_internal.lifecycle_events e
                    WHERE e.transitioned_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.deadline_lifecycle d WHERE d.event_id=e.event_id)));
        ELSIF item.family = 'executions' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(e)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.executions e WHERE e.finished_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes;
            blocking_reasons := '{}'::jsonb;
        ELSIF item.family = 'agenda' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(a)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.agenda a
            WHERE a.completed_at < target_cutoff
              AND a.state IN ('COMPLETED','FAILED','SKIPPED','WITHDRAWN','CANCELLED','SUPERSEDED');
            SELECT count(*), COALESCE(sum(pg_column_size(a)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.agenda a
            WHERE a.completed_at < target_cutoff
              AND a.state IN ('COMPLETED','FAILED','SKIPPED','WITHDRAWN','CANCELLED','SUPERSEDED')
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.executions e WHERE e.episode_id=a.episode_id)
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.execution_batch_items i WHERE i.episode_id=a.episode_id)
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.conflict_leases l WHERE l.episode_id=a.episode_id)
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.runtime_events r WHERE r.episode_id=a.episode_id);
            blocking_reasons := jsonb_build_object(
                'active_work', (SELECT count(*) FROM pgreact_internal.agenda a
                    WHERE a.completed_at < target_cutoff AND a.state NOT IN ('COMPLETED','FAILED','SKIPPED','WITHDRAWN','CANCELLED','SUPERSEDED')),
                'execution_reference', (SELECT count(*) FROM pgreact_internal.agenda a
                    WHERE a.completed_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.executions e WHERE e.episode_id=a.episode_id)),
                'batch_reference', (SELECT count(*) FROM pgreact_internal.agenda a
                    WHERE a.completed_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.execution_batch_items i WHERE i.episode_id=a.episode_id)),
                'runtime_reference', (SELECT count(*) FROM pgreact_internal.agenda a
                    WHERE a.completed_at < target_cutoff AND EXISTS (SELECT 1 FROM pgreact_internal.runtime_events r WHERE r.episode_id=a.episode_id)));
        ELSIF item.family = 'runtime_events' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.runtime_events r WHERE r.occurred_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := '{}'::jsonb;
        ELSIF item.family = 'reconciliation_audit' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.reconciliation_audit r
            WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED';
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := jsonb_build_object('running', 0);
        ELSIF item.family = 'metadata_rebuild_audits' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.metadata_rebuild_audits r
            WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED';
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := jsonb_build_object('running', 0);
        ELSIF item.family = 'derived_support_inputs' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(i)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derived_support_inputs i JOIN pgreact_internal.derived_supports s USING (support_id)
            WHERE NOT s.active AND s.invalidated_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := jsonb_build_object('active_support', 0);
        ELSIF item.family = 'derived_supports' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(s)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derived_supports s WHERE NOT s.active AND s.invalidated_at < target_cutoff;
            SELECT count(*), COALESCE(sum(pg_column_size(s)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.derived_supports s
            WHERE NOT s.active AND s.invalidated_at < target_cutoff
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derived_support_inputs i WHERE i.support_id=s.support_id);
            blocking_reasons := jsonb_build_object('support_inputs', (SELECT count(*) FROM pgreact_internal.derived_supports s
                WHERE NOT s.active AND s.invalidated_at < target_cutoff
                  AND EXISTS (SELECT 1 FROM pgreact_internal.derived_support_inputs i WHERE i.support_id=s.support_id)));
        ELSIF item.family = 'derived_repair_diagnostics' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(d)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derived_repair_diagnostics d JOIN pgreact_internal.derived_reconciliations r USING (reconciliation_id)
            WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED';
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := '{}'::jsonb;
        ELSIF item.family = 'derived_reconciliations' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derived_reconciliations r WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED';
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.derived_reconciliations r
            WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED'
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derived_repair_diagnostics d WHERE d.reconciliation_id=r.reconciliation_id);
            blocking_reasons := jsonb_build_object('diagnostics', (SELECT count(*) FROM pgreact_internal.derived_reconciliations r
                WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED'
                  AND EXISTS (SELECT 1 FROM pgreact_internal.derived_repair_diagnostics d WHERE d.reconciliation_id=r.reconciliation_id)));
        ELSIF item.family = 'derivation_program_repair_diagnostics' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(d)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derivation_program_repair_diagnostics d
            JOIN pgreact_internal.derivation_program_reconciliations r USING (reconciliation_id)
            WHERE r.completed_at < target_cutoff AND r.status = 'COMPLETED';
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := '{}'::jsonb;
        ELSIF item.family = 'derivation_program_iterations' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(i)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derivation_program_iterations i WHERE i.completed_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := '{}'::jsonb;
        ELSIF item.family = 'derivation_program_runs' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.derivation_program_runs r
            WHERE r.completed_at < target_cutoff AND r.status IN ('COMPLETED','NOOP','FAILED');
            SELECT count(*), COALESCE(sum(pg_column_size(r)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.derivation_program_runs r
            WHERE r.completed_at < target_cutoff AND r.status IN ('COMPLETED','NOOP','FAILED')
              AND NOT EXISTS (SELECT 1 FROM pgreact_internal.derivation_program_iterations i WHERE i.run_id=r.run_id);
            blocking_reasons := jsonb_build_object('iterations', (SELECT count(*) FROM pgreact_internal.derivation_program_runs r
                WHERE r.completed_at < target_cutoff AND r.status IN ('COMPLETED','NOOP','FAILED')
                  AND EXISTS (SELECT 1 FROM pgreact_internal.derivation_program_iterations i WHERE i.run_id=r.run_id)));
        ELSIF item.family = 'negative_dependency_evidence' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(e)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.negative_dependency_evidence e WHERE NOT e.active AND e.invalidated_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := jsonb_build_object('active', 0);
        ELSIF item.family = 'aggregate_dependency_evidence' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(e)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.aggregate_dependency_evidence e WHERE NOT e.active AND e.invalidated_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := jsonb_build_object('active', 0);
        ELSIF item.family = 'window_corrections' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(c)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.window_corrections c WHERE c.created_at < target_cutoff;
            SELECT count(*), COALESCE(sum(pg_column_size(c)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.window_corrections c JOIN pgreact_internal.window_programs p USING (program_version_id)
            WHERE c.created_at < target_cutoff AND NOT p.active;
            blocking_reasons := jsonb_build_object('active_program', (SELECT count(*) FROM pgreact_internal.window_corrections c
                JOIN pgreact_internal.window_programs p USING (program_version_id) WHERE c.created_at < target_cutoff AND p.active));
        ELSIF item.family = 'window_diagnostics' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(d)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.window_diagnostics d WHERE d.created_at < target_cutoff;
            SELECT count(*), COALESCE(sum(pg_column_size(d)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.window_diagnostics d JOIN pgreact_internal.window_programs p USING (program_version_id)
            WHERE d.created_at < target_cutoff AND NOT p.active;
            blocking_reasons := jsonb_build_object('active_program', (SELECT count(*) FROM pgreact_internal.window_diagnostics d
                JOIN pgreact_internal.window_programs p USING (program_version_id) WHERE d.created_at < target_cutoff AND p.active));
        ELSIF item.family = 'window_audits' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(a)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.window_audits a WHERE a.created_at < target_cutoff;
            SELECT count(*), COALESCE(sum(pg_column_size(a)), 0) INTO rows_ok, bytes_ok
            FROM pgreact_internal.window_audits a LEFT JOIN pgreact_internal.window_programs p USING (program_version_id)
            WHERE a.created_at < target_cutoff AND (p.program_version_id IS NULL OR NOT p.active);
            blocking_reasons := jsonb_build_object('active_program', (SELECT count(*) FROM pgreact_internal.window_audits a
                JOIN pgreact_internal.window_programs p USING (program_version_id) WHERE a.created_at < target_cutoff AND p.active));
        ELSIF item.family = 'clock_history' THEN
            SELECT count(*), COALESCE(sum(pg_column_size(h)), 0) INTO candidate_rows, candidate_bytes
            FROM pgreact_internal.clock_history h WHERE h.advanced_at < target_cutoff;
            rows_ok := candidate_rows; bytes_ok := candidate_bytes; blocking_reasons := '{}'::jsonb;
        END IF;
        family := item.family; relation_name := item.relation_name;
        eligible_rows := rows_ok; eligible_bytes := bytes_ok;
        protected_rows := candidate_rows - rows_ok; protected_bytes := candidate_bytes - bytes_ok;
        lost_capabilities := item.lost_capabilities; remediation := item.remediation;
        has_more := rows_ok > target_batch_size;
        RETURN NEXT;
    END LOOP;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.retire_pack_rule(target_version_id uuid, old_work_policy text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE prior pgreact_internal.rule_versions%ROWTYPE;
BEGIN
    prior := pgreact_internal.assert_rule_owner(target_version_id);
    IF old_work_policy = 'CANCEL_OLD' THEN
        UPDATE pgreact_internal.agenda SET state = 'CANCELLED', completed_at = clock_timestamp()
        WHERE rule_version_id = target_version_id AND state IN ('PENDING', 'RETRY_WAIT');
    END IF;
    IF prior.match_relid IS NOT NULL THEN
        PERFORM pgtrickle.drop_stream_table(prior.match_name, true);
    END IF;
    UPDATE pgreact_internal.rule_versions
    SET match_relid = NULL,
        state = CASE WHEN EXISTS (
            SELECT 1 FROM pgreact_internal.agenda
            WHERE rule_version_id = target_version_id AND state IN ('PENDING', 'LEASED', 'RETRY_WAIT')
        ) THEN 'DRAINING' ELSE 'REMOVED' END
    WHERE rule_version_id = target_version_id;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.run_m14(sampled_time timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    run_refresh_id bigint := pg_catalog.pg_current_xact_id()::text::bigint;
    rule_row record;
    relation_row record;
    program_row record;
    program_frontier bigint;
    clock_result jsonb;
    rules jsonb := '[]'::jsonb;
    relations jsonb := '[]'::jsonb;
    programs jsonb := '[]'::jsonb;
    jobs_before bigint;
    jobs_after bigint;
    session_locks integer := 0;
BEGIN
    IF NOT pgreact_internal.is_operator_admin() THEN
        RAISE EXCEPTION 'M13_RUN_UNAUTHORIZED: only the configured operator may run coordination';
    END IF;
    IF sampled_time IS NULL OR NOT isfinite(sampled_time) THEN
        RAISE EXCEPTION 'M13_RUN_SAMPLE: sampled database time must be finite and non-null';
    END IF;
    IF pg_catalog.pg_is_in_recovery() THEN
        RAISE EXCEPTION 'M13_RUN_STANDBY: coordination cannot run on a physical standby';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(5788046901200000);
    SELECT count(*) INTO jobs_before FROM pgreact_internal.agenda;
    BEGIN
        PERFORM pgreact.begin_deadline_refresh(run_refresh_id);
        session_locks := 1;
        IF EXISTS (
            SELECT 1 FROM pgreact_internal.rule_barriers barrier
             WHERE barrier.refresh_id IS DISTINCT FROM run_refresh_id
        ) THEN
            RAISE EXCEPTION 'M13_RUN_BARRIER: a rule already has a recovery or maintenance barrier';
        END IF;

        FOR rule_row IN
            SELECT rule.rule_name, version.rule_version_id,
                   deadline.rule_version_id IS NOT NULL AS deadline
              FROM pgreact_internal.rule_versions version
              JOIN pgreact_internal.rules rule USING (rule_id)
              LEFT JOIN pgreact_internal.deadline_rules deadline
                USING (rule_version_id)
             WHERE version.state = 'ACTIVE'
               AND NOT EXISTS (
                    SELECT 1
                      FROM pgreact_internal.derivation_rule_versions derivation
                     WHERE derivation.rule_version_id = version.rule_version_id)
               AND NOT EXISTS (
                    SELECT 1
                      FROM pgreact_internal.source_derived_dependencies(
                            version.source_view_oid))
             ORDER BY rule.rule_name, version.created_at
        LOOP
            PERFORM pgreact.refresh_rule(rule_row.rule_version_id);
            SET CONSTRAINTS ALL IMMEDIATE;
            SET CONSTRAINTS ALL DEFERRED;
            rules := rules || jsonb_build_array(jsonb_build_object(
                'rule', rule_row.rule_name,
                'kind', CASE WHEN rule_row.deadline
                    THEN 'deadline' ELSE 'ordinary' END,
                'result', 'refreshed'));
        END LOOP;
        IF pg_catalog.current_setting('pgreact.test_fail_run_phase', true) = 'rules' THEN
            RAISE EXCEPTION 'injected M13 run failure after rules';
        END IF;

        FOR relation_row IN
            SELECT relation.relation_name, version.relation_version_id
              FROM pgreact_internal.derived_relation_versions version
              JOIN pgreact_internal.derived_relations relation USING (relation_id)
             WHERE version.state = 'ACTIVE'
               AND NOT EXISTS (
                    SELECT 1
                      FROM pgreact_internal.derivation_program_components component
                      JOIN pgreact_internal.derivation_program_versions program
                        USING (program_version_id)
                     WHERE program.state = 'ACTIVE'
                       AND version.relation_version_id = ANY (component.target_relations))
             ORDER BY relation.relation_name, version.version
        LOOP
            program_frontier := pgreact.refresh_derived_relation(
                relation_row.relation_version_id);
            relations := relations || jsonb_build_array(jsonb_build_object(
                'relation', relation_row.relation_name,
                'frontier', program_frontier));
        END LOOP;

        IF EXISTS (
            WITH RECURSIVE active AS (
                SELECT program_version_id
                  FROM pgreact_internal.derivation_program_versions
                 WHERE state = 'ACTIVE'
            ), edges AS (
                SELECT DISTINCT producer.program_version_id AS source_program,
                                consumer.program_version_id AS target_program
                  FROM pgreact_internal.derivation_program_inputs input
                  JOIN active consumer
                    ON consumer.program_version_id = input.program_version_id
                  JOIN pgreact_internal.derivation_program_components component
                    ON input.relation_version_id = ANY (component.target_relations)
                  JOIN active producer
                    ON producer.program_version_id = component.program_version_id
                 WHERE producer.program_version_id <> consumer.program_version_id
            ), reach(source_program, target_program) AS (
                SELECT source_program, target_program FROM edges
                UNION
                SELECT reach.source_program, edges.target_program
                  FROM reach JOIN edges
                    ON edges.source_program = reach.target_program
            )
            SELECT 1 FROM reach WHERE source_program = target_program
        ) THEN
            RAISE EXCEPTION 'M13_RUN_PROGRAM_CYCLE: active programs have a cross-program dependency cycle';
        END IF;
        FOR program_row IN
            SELECT * FROM pgreact_internal.active_program_order()
        LOOP
            program_frontier := pgreact.refresh_derivation_program(
                program_row.program_version_id);
            IF program_frontier IS NULL THEN
                RAISE EXCEPTION 'M13_RUN_PROGRAM_FAILED: program % failed',
                    program_row.program_name;
            END IF;
            programs := programs || jsonb_build_array(jsonb_build_object(
                'program', program_row.program_name,
                'frontier', program_frontier));
        END LOOP;

        FOR rule_row IN
            SELECT rule.rule_name, version.rule_version_id,
                   deadline.rule_version_id IS NOT NULL AS deadline
              FROM pgreact_internal.rule_versions version
              JOIN pgreact_internal.rules rule USING (rule_id)
              LEFT JOIN pgreact_internal.deadline_rules deadline
                USING (rule_version_id)
             WHERE version.state = 'ACTIVE'
               AND NOT EXISTS (
                    SELECT 1
                      FROM pgreact_internal.derivation_rule_versions derivation
                     WHERE derivation.rule_version_id = version.rule_version_id)
               AND EXISTS (
                    SELECT 1
                      FROM pgreact_internal.source_derived_dependencies(
                            version.source_view_oid))
             ORDER BY rule.rule_name, version.created_at
        LOOP
            PERFORM pgreact.refresh_rule(rule_row.rule_version_id);
            SET CONSTRAINTS ALL IMMEDIATE;
            SET CONSTRAINTS ALL DEFERRED;
            rules := rules || jsonb_build_array(jsonb_build_object(
                'rule', rule_row.rule_name,
                'kind', CASE WHEN rule_row.deadline
                    THEN 'deadline' ELSE 'ordinary' END,
                'result', 'refreshed'));
        END LOOP;
        IF pg_catalog.current_setting('pgreact.test_fail_run_phase', true) = 'programs' THEN
            RAISE EXCEPTION 'injected M13 run failure after programs';
        END IF;

        clock_result := pgreact.advance_deadline_clock(sampled_time);
        IF pg_catalog.current_setting('pgreact.test_fail_run_phase', true) = 'clock' THEN
            RAISE EXCEPTION 'injected M13 run failure after clock';
        END IF;
        PERFORM pgreact.finish_deadline_refresh();
        session_locks := 0;
        SELECT count(*) INTO jobs_after FROM pgreact_internal.agenda;
        RETURN jsonb_build_object(
            'contract_version', 3,
            'sampled_time', sampled_time,
            'rules', rules,
            'relations', relations,
            'programs', programs,
            'clock', clock_result,
            'jobs_created', jobs_after - jobs_before);
    EXCEPTION WHEN OTHERS THEN
        WHILE session_locks > 0 LOOP
            PERFORM pg_catalog.pg_advisory_unlock(5788046901200000);
            session_locks := session_locks - 1;
        END LOOP;
        RAISE;
    END;
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.run_m16(sampled_time timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE result jsonb;
BEGIN
    PERFORM pgreact_internal.sync_semantic_keys();
    result := pgreact_internal.run_m14(sampled_time);
    RETURN jsonb_set(result, '{contract_version}', '5'::jsonb);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.run_m22(sampled_time timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    result jsonb;
    program record;
    prepare_status text;
    summaries jsonb := '[]'::jsonb;
    advance_result jsonb;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pgreact_internal.window_programs WHERE active) THEN
        RETURN pgreact_internal.run_m16(sampled_time);
    END IF;
    PERFORM pg_advisory_xact_lock(5788046901200000);
    PERFORM pgreact_internal.begin_window_stage();
    FOR program IN SELECT program_version_id,program_name
        FROM pgreact_internal.window_programs WHERE active ORDER BY program_name
    LOOP
        prepare_status := pgreact_internal.prepare_window_program(program.program_version_id);
        summaries := summaries || jsonb_build_array(jsonb_build_object(
            'program',program.program_name,'maintenance',prepare_status));
    END LOOP;
    result := pgreact_internal.run_m16(sampled_time);
    FOR program IN SELECT program_version_id,program_name
        FROM pgreact_internal.window_programs WHERE active AND barrier IS NULL ORDER BY program_name
    LOOP
        PERFORM pgreact_internal.finish_window_program(program.program_version_id);
        advance_result := pgreact_internal.advance_window_watermark(program.program_version_id);
        summaries := summaries || jsonb_build_array(
            jsonb_build_object('program',program.program_name,'watermark',advance_result));
    END LOOP;
    RETURN jsonb_set(result, '{contract_version}', '6'::jsonb)
        || jsonb_build_object('windows',summaries);
END
$function$

CREATE OR REPLACE FUNCTION pgreact_internal.run_m24(sampled_time timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
